static int asfrtp_parse_packet(AVFormatContext *s, PayloadContext *asf,

                               AVStream *st, AVPacket *pkt,

                               uint32_t *timestamp,

                               const uint8_t *buf, int len, int flags)

{

    AVIOContext *pb = &asf->pb;

    int res, mflags, len_off;

    RTSPState *rt = s->priv_data;



    if (!rt->asf_ctx)




    if (len > 0) {

        int off, out_len = 0;



        if (len < 4)




        av_freep(&asf->buf);



        ffio_init_context(pb, buf, len, 0, NULL, NULL, NULL, NULL);



        while (avio_tell(pb) + 4 < len) {

            int start_off = avio_tell(pb);



            mflags = avio_r8(pb);

            if (mflags & 0x80)

                flags |= RTP_FLAG_KEY;

            len_off = avio_rb24(pb);

            if (mflags & 0x20)   /**< relative timestamp */

                avio_skip(pb, 4);

            if (mflags & 0x10)   /**< has duration */

                avio_skip(pb, 4);

            if (mflags & 0x8)    /**< has location ID */

                avio_skip(pb, 4);

            off = avio_tell(pb);



            if (!(mflags & 0x40)) {

                /**

                 * If 0x40 is not set, the len_off field specifies an offset

                 * of this packet's payload data in the complete (reassembled)

                 * ASF packet. This is used to spread one ASF packet over

                 * multiple RTP packets.

                 */

                if (asf->pktbuf && len_off != avio_tell(asf->pktbuf)) {

                    uint8_t *p;

                    avio_close_dyn_buf(asf->pktbuf, &p);

                    asf->pktbuf = NULL;

                    av_free(p);

                }

                if (!len_off && !asf->pktbuf &&

                    (res = avio_open_dyn_buf(&asf->pktbuf)) < 0)

                    return res;

                if (!asf->pktbuf)

                    return AVERROR(EIO);



                avio_write(asf->pktbuf, buf + off, len - off);

                avio_skip(pb, len - off);

                if (!(flags & RTP_FLAG_MARKER))


                out_len     = avio_close_dyn_buf(asf->pktbuf, &asf->buf);

                asf->pktbuf = NULL;

            } else {

                /**

                 * If 0x40 is set, the len_off field specifies the length of

                 * the next ASF packet that can be read from this payload

                 * data alone. This is commonly the same as the payload size,

                 * but could be less in case of packet splitting (i.e.

                 * multiple ASF packets in one RTP packet).

                 */



                int cur_len = start_off + len_off - off;

                int prev_len = out_len;

                out_len += cur_len;

                asf->buf = av_realloc(asf->buf, out_len);



                memcpy(asf->buf + prev_len, buf + off,

                       FFMIN(cur_len, len - off));

                avio_skip(pb, cur_len);

            }

        }



        init_packetizer(pb, asf->buf, out_len);

        pb->pos += rt->asf_pb_pos;

        pb->eof_reached = 0;

        rt->asf_ctx->pb = pb;

    }



    for (;;) {

        int i;



        res = av_read_packet(rt->asf_ctx, pkt);

        rt->asf_pb_pos = avio_tell(pb);

        if (res != 0)

            break;

        for (i = 0; i < s->nb_streams; i++) {

            if (s->streams[i]->id == rt->asf_ctx->streams[pkt->stream_index]->id) {

                pkt->stream_index = i;

                return 1; // FIXME: return 0 if last packet

            }

        }

        av_free_packet(pkt);

    }



    return res == 1 ? -1 : res;

}

static void gen_mulo(DisasContext *ctx)

{

    int l1 = gen_new_label();

    TCGv_i64 t0 = tcg_temp_new_i64();

    TCGv_i64 t1 = tcg_temp_new_i64();

    TCGv t2 = tcg_temp_new();

    /* Start with XER OV disabled, the most likely case */

    tcg_gen_movi_tl(cpu_ov, 0);

    tcg_gen_extu_tl_i64(t0, cpu_gpr[rA(ctx->opcode)]);

    tcg_gen_extu_tl_i64(t1, cpu_gpr[rB(ctx->opcode)]);

    tcg_gen_mul_i64(t0, t0, t1);

    tcg_gen_trunc_i64_tl(t2, t0);

    gen_store_spr(SPR_MQ, t2);

    tcg_gen_shri_i64(t1, t0, 32);

    tcg_gen_trunc_i64_tl(cpu_gpr[rD(ctx->opcode)], t1);

    tcg_gen_ext32s_i64(t1, t0);

    tcg_gen_brcond_i64(TCG_COND_EQ, t0, t1, l1);

    tcg_gen_movi_tl(cpu_ov, 1);

    tcg_gen_movi_tl(cpu_so, 1);

    gen_set_label(l1);

    tcg_temp_free_i64(t0);

    tcg_temp_free_i64(t1);

    tcg_temp_free(t2);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rD(ctx->opcode)]);

}

static void taihu_405ep_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *kernel_filename = machine->kernel_filename;

    const char *initrd_filename = machine->initrd_filename;

    char *filename;

    qemu_irq *pic;

    MemoryRegion *sysmem = get_system_memory();

    MemoryRegion *bios;

    MemoryRegion *ram_memories = g_malloc(2 * sizeof(*ram_memories));

    hwaddr ram_bases[2], ram_sizes[2];

    long bios_size;

    target_ulong kernel_base, initrd_base;

    long kernel_size, initrd_size;

    int linux_boot;

    int fl_idx, fl_sectors;

    DriveInfo *dinfo;



    /* RAM is soldered to the board so the size cannot be changed */

    memory_region_allocate_system_memory(&ram_memories[0], NULL,

                           "taihu_405ep.ram-0", 0x04000000);

    ram_bases[0] = 0;

    ram_sizes[0] = 0x04000000;

    memory_region_allocate_system_memory(&ram_memories[1], NULL,

                           "taihu_405ep.ram-1", 0x04000000);

    ram_bases[1] = 0x04000000;

    ram_sizes[1] = 0x04000000;

    ram_size = 0x08000000;

#ifdef DEBUG_BOARD_INIT

    printf("%s: register cpu\n", __func__);

#endif

    ppc405ep_init(sysmem, ram_memories, ram_bases, ram_sizes,

                  33333333, &pic, kernel_filename == NULL ? 0 : 1);

    /* allocate and load BIOS */

#ifdef DEBUG_BOARD_INIT

    printf("%s: register BIOS\n", __func__);

#endif

    fl_idx = 0;

#if defined(USE_FLASH_BIOS)

    dinfo = drive_get(IF_PFLASH, 0, fl_idx);

    if (dinfo) {

        bios_size = bdrv_getlength(dinfo->bdrv);

        /* XXX: should check that size is 2MB */

        //        bios_size = 2 * 1024 * 1024;

        fl_sectors = (bios_size + 65535) >> 16;

#ifdef DEBUG_BOARD_INIT

        printf("Register parallel flash %d size %lx"

               " at addr %lx '%s' %d\n",

               fl_idx, bios_size, -bios_size,

               bdrv_get_device_name(dinfo->bdrv), fl_sectors);

#endif

        pflash_cfi02_register((uint32_t)(-bios_size),

                              NULL, "taihu_405ep.bios", bios_size,

                              dinfo->bdrv, 65536, fl_sectors, 1,

                              4, 0x0001, 0x22DA, 0x0000, 0x0000, 0x555, 0x2AA,

                              1);

        fl_idx++;

    } else

#endif

    {

#ifdef DEBUG_BOARD_INIT

        printf("Load BIOS from file\n");

#endif

        if (bios_name == NULL)

            bios_name = BIOS_FILENAME;

        bios = g_new(MemoryRegion, 1);

        memory_region_allocate_system_memory(bios, NULL, "taihu_405ep.bios",

                                             BIOS_SIZE);

        filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

        if (filename) {

            bios_size = load_image(filename, memory_region_get_ram_ptr(bios));

            g_free(filename);

            if (bios_size < 0 || bios_size > BIOS_SIZE) {

                error_report("Could not load PowerPC BIOS '%s'", bios_name);

                exit(1);

            }

            bios_size = (bios_size + 0xfff) & ~0xfff;

            memory_region_add_subregion(sysmem, (uint32_t)(-bios_size), bios);

        } else if (!qtest_enabled()) {

            error_report("Could not load PowerPC BIOS '%s'", bios_name);

            exit(1);

        }

        memory_region_set_readonly(bios, true);

    }

    /* Register Linux flash */

    dinfo = drive_get(IF_PFLASH, 0, fl_idx);

    if (dinfo) {

        bios_size = bdrv_getlength(dinfo->bdrv);

        /* XXX: should check that size is 32MB */

        bios_size = 32 * 1024 * 1024;

        fl_sectors = (bios_size + 65535) >> 16;

#ifdef DEBUG_BOARD_INIT

        printf("Register parallel flash %d size %lx"

               " at addr " TARGET_FMT_lx " '%s'\n",

               fl_idx, bios_size, (target_ulong)0xfc000000,

               bdrv_get_device_name(dinfo->bdrv));

#endif

        pflash_cfi02_register(0xfc000000, NULL, "taihu_405ep.flash", bios_size,

                              dinfo->bdrv, 65536, fl_sectors, 1,

                              4, 0x0001, 0x22DA, 0x0000, 0x0000, 0x555, 0x2AA,

                              1);

        fl_idx++;

    }

    /* Register CLPD & LCD display */

#ifdef DEBUG_BOARD_INIT

    printf("%s: register CPLD\n", __func__);

#endif

    taihu_cpld_init(sysmem, 0x50100000);

    /* Load kernel */

    linux_boot = (kernel_filename != NULL);

    if (linux_boot) {

#ifdef DEBUG_BOARD_INIT

        printf("%s: load kernel\n", __func__);

#endif

        kernel_base = KERNEL_LOAD_ADDR;

        /* now we can load the kernel */

        kernel_size = load_image_targphys(kernel_filename, kernel_base,

                                          ram_size - kernel_base);

        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    kernel_filename);

            exit(1);

        }

        /* load initrd */

        if (initrd_filename) {

            initrd_base = INITRD_LOAD_ADDR;

            initrd_size = load_image_targphys(initrd_filename, initrd_base,

                                              ram_size - initrd_base);

            if (initrd_size < 0) {

                fprintf(stderr,

                        "qemu: could not load initial ram disk '%s'\n",

                        initrd_filename);

                exit(1);

            }

        } else {

            initrd_base = 0;

            initrd_size = 0;

        }

    } else {

        kernel_base = 0;

        kernel_size = 0;

        initrd_base = 0;

        initrd_size = 0;

    }

#ifdef DEBUG_BOARD_INIT

    printf("%s: Done\n", __func__);

#endif

}

static void vmxnet3_deactivate_device(VMXNET3State *s)

{

    VMW_CBPRN("Deactivating vmxnet3...");

    s->device_active = false;

}

void ff_eac3_apply_spectral_extension(AC3DecodeContext *s)

{

    int bin, bnd, ch, i;

    uint8_t wrapflag[SPX_MAX_BANDS]={1,0,}, num_copy_sections, copy_sizes[SPX_MAX_BANDS];

    float rms_energy[SPX_MAX_BANDS];



    /* Set copy index mapping table. Set wrap flags to apply a notch filter at

       wrap points later on. */

    bin = s->spx_dst_start_freq;

    num_copy_sections = 0;

    for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

        int copysize;

        int bandsize = s->spx_band_sizes[bnd];

        if (bin + bandsize > s->spx_src_start_freq) {

            copy_sizes[num_copy_sections++] = bin - s->spx_dst_start_freq;

            bin = s->spx_dst_start_freq;

            wrapflag[bnd] = 1;

        }

        for (i = 0; i < bandsize; i += copysize) {

            if (bin == s->spx_src_start_freq) {

                copy_sizes[num_copy_sections++] = bin - s->spx_dst_start_freq;

                bin = s->spx_dst_start_freq;

            }

            copysize = FFMIN(bandsize - i, s->spx_src_start_freq - bin);

            bin += copysize;

        }

    }

    copy_sizes[num_copy_sections++] = bin - s->spx_dst_start_freq;



    for (ch = 1; ch <= s->fbw_channels; ch++) {

        if (!s->channel_uses_spx[ch])

            continue;



        /* Copy coeffs from normal bands to extension bands */

        bin = s->spx_src_start_freq;

        for (i = 0; i < num_copy_sections; i++) {

            memcpy(&s->transform_coeffs[ch][bin],

                   &s->transform_coeffs[ch][s->spx_dst_start_freq],

                   copy_sizes[i]*sizeof(float));

            bin += copy_sizes[i];

        }



        /* Calculate RMS energy for each SPX band. */

        bin = s->spx_src_start_freq;

        for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

            int bandsize = s->spx_band_sizes[bnd];

            float accum = 0.0f;

            for (i = 0; i < bandsize; i++) {

                float coeff = s->transform_coeffs[ch][bin++];

                accum += coeff * coeff;

            }

            rms_energy[bnd] = sqrtf(accum / bandsize);

        }



        /* Apply a notch filter at transitions between normal and extension

           bands and at all wrap points. */

        if (s->spx_atten_code[ch] >= 0) {

            const float *atten_tab = ff_eac3_spx_atten_tab[s->spx_atten_code[ch]];

            bin = s->spx_src_start_freq - 2;

            for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

                if (wrapflag[bnd]) {

                    float *coeffs = &s->transform_coeffs[ch][bin];

                    coeffs[0] *= atten_tab[0];

                    coeffs[1] *= atten_tab[1];

                    coeffs[2] *= atten_tab[2];

                    coeffs[3] *= atten_tab[1];

                    coeffs[4] *= atten_tab[0];

                }

                bin += s->spx_band_sizes[bnd];

            }

        }



        /* Apply noise-blended coefficient scaling based on previously

           calculated RMS energy, blending factors, and SPX coordinates for

           each band. */

        bin = s->spx_src_start_freq;

        for (bnd = 0; bnd < s->num_spx_bands; bnd++) {

            float nscale = s->spx_noise_blend[ch][bnd] * rms_energy[bnd] * (1.0f / INT32_MIN);

            float sscale = s->spx_signal_blend[ch][bnd];

            for (i = 0; i < s->spx_band_sizes[bnd]; i++) {

                float noise  = nscale * (int32_t)av_lfg_get(&s->dith_state);

                s->transform_coeffs[ch][bin]   *= sscale;

                s->transform_coeffs[ch][bin++] += noise;

            }

        }

    }

}

static uint64_t qemu_opt_get_number_helper(QemuOpts *opts, const char *name,

                                           uint64_t defval, bool del)

{

    QemuOpt *opt = qemu_opt_find(opts, name);

    uint64_t ret = defval;



    if (opt == NULL) {

        const QemuOptDesc *desc = find_desc_by_name(opts->list->desc, name);

        if (desc && desc->def_value_str) {

            parse_option_number(name, desc->def_value_str, &ret, &error_abort);

        }

        return ret;

    }

    assert(opt->desc && opt->desc->type == QEMU_OPT_NUMBER);

    ret = opt->value.uint;

    if (del) {

        qemu_opt_del_all(opts, name);

    }

    return ret;

}

static int send_sub_rect_nojpeg(VncState *vs, int x, int y, int w, int h,

                                int bg, int fg, int colors, VncPalette *palette)

{

    int ret;



    if (colors == 0) {

        if (tight_detect_smooth_image(vs, w, h)) {

            ret = send_gradient_rect(vs, x, y, w, h);


            ret = send_full_color_rect(vs, x, y, w, h);

        }

    } else if (colors == 1) {

        ret = send_solid_rect(vs);

    } else if (colors == 2) {

        ret = send_mono_rect(vs, x, y, w, h, bg, fg);

    } else if (colors <= 256) {

        ret = send_palette_rect(vs, x, y, w, h, palette);



    }

    return ret;

}

static uint32_t nvic_readl(nvic_state *s, uint32_t offset)

{

    ARMCPU *cpu;

    uint32_t val;

    int irq;



    switch (offset) {

    case 4: /* Interrupt Control Type.  */

        return (s->num_irq / 32) - 1;

    case 0x10: /* SysTick Control and Status.  */

        val = s->systick.control;

        s->systick.control &= ~SYSTICK_COUNTFLAG;

        return val;

    case 0x14: /* SysTick Reload Value.  */

        return s->systick.reload;

    case 0x18: /* SysTick Current Value.  */

        {

            int64_t t;

            if ((s->systick.control & SYSTICK_ENABLE) == 0)

                return 0;

            t = qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL);

            if (t >= s->systick.tick)

                return 0;

            val = ((s->systick.tick - (t + 1)) / systick_scale(s)) + 1;

            /* The interrupt in triggered when the timer reaches zero.

               However the counter is not reloaded until the next clock

               tick.  This is a hack to return zero during the first tick.  */

            if (val > s->systick.reload)

                val = 0;

            return val;

        }

    case 0x1c: /* SysTick Calibration Value.  */

        return 10000;

    case 0xd00: /* CPUID Base.  */

        cpu = ARM_CPU(current_cpu);

        return cpu->env.cp15.c0_cpuid;

    case 0xd04: /* Interrupt Control State.  */

        /* VECTACTIVE */

        val = s->gic.running_irq[0];

        if (val == 1023) {

            val = 0;

        } else if (val >= 32) {

            val -= 16;

        }

        /* RETTOBASE */

        if (s->gic.running_irq[0] == 1023

                || s->gic.last_active[s->gic.running_irq[0]][0] == 1023) {

            val |= (1 << 11);

        }

        /* VECTPENDING */

        if (s->gic.current_pending[0] != 1023)

            val |= (s->gic.current_pending[0] << 12);

        /* ISRPENDING */

        for (irq = 32; irq < s->num_irq; irq++) {

            if (s->gic.irq_state[irq].pending) {

                val |= (1 << 22);

                break;

            }

        }

        /* PENDSTSET */

        if (s->gic.irq_state[ARMV7M_EXCP_SYSTICK].pending)

            val |= (1 << 26);

        /* PENDSVSET */

        if (s->gic.irq_state[ARMV7M_EXCP_PENDSV].pending)

            val |= (1 << 28);

        /* NMIPENDSET */

        if (s->gic.irq_state[ARMV7M_EXCP_NMI].pending)

            val |= (1 << 31);

        return val;

    case 0xd08: /* Vector Table Offset.  */

        cpu = ARM_CPU(current_cpu);

        return cpu->env.v7m.vecbase;

    case 0xd0c: /* Application Interrupt/Reset Control.  */

        return 0xfa05000;

    case 0xd10: /* System Control.  */

        /* TODO: Implement SLEEPONEXIT.  */

        return 0;

    case 0xd14: /* Configuration Control.  */

        /* TODO: Implement Configuration Control bits.  */

        return 0;

    case 0xd24: /* System Handler Status.  */

        val = 0;

        if (s->gic.irq_state[ARMV7M_EXCP_MEM].active) val |= (1 << 0);

        if (s->gic.irq_state[ARMV7M_EXCP_BUS].active) val |= (1 << 1);

        if (s->gic.irq_state[ARMV7M_EXCP_USAGE].active) val |= (1 << 3);

        if (s->gic.irq_state[ARMV7M_EXCP_SVC].active) val |= (1 << 7);

        if (s->gic.irq_state[ARMV7M_EXCP_DEBUG].active) val |= (1 << 8);

        if (s->gic.irq_state[ARMV7M_EXCP_PENDSV].active) val |= (1 << 10);

        if (s->gic.irq_state[ARMV7M_EXCP_SYSTICK].active) val |= (1 << 11);

        if (s->gic.irq_state[ARMV7M_EXCP_USAGE].pending) val |= (1 << 12);

        if (s->gic.irq_state[ARMV7M_EXCP_MEM].pending) val |= (1 << 13);

        if (s->gic.irq_state[ARMV7M_EXCP_BUS].pending) val |= (1 << 14);

        if (s->gic.irq_state[ARMV7M_EXCP_SVC].pending) val |= (1 << 15);

        if (s->gic.irq_state[ARMV7M_EXCP_MEM].enabled) val |= (1 << 16);

        if (s->gic.irq_state[ARMV7M_EXCP_BUS].enabled) val |= (1 << 17);

        if (s->gic.irq_state[ARMV7M_EXCP_USAGE].enabled) val |= (1 << 18);

        return val;

    case 0xd28: /* Configurable Fault Status.  */

        /* TODO: Implement Fault Status.  */

        qemu_log_mask(LOG_UNIMP, "Configurable Fault Status unimplemented\n");

        return 0;

    case 0xd2c: /* Hard Fault Status.  */

    case 0xd30: /* Debug Fault Status.  */

    case 0xd34: /* Mem Manage Address.  */

    case 0xd38: /* Bus Fault Address.  */

    case 0xd3c: /* Aux Fault Status.  */

        /* TODO: Implement fault status registers.  */

        qemu_log_mask(LOG_UNIMP, "Fault status registers unimplemented\n");

        return 0;

    case 0xd40: /* PFR0.  */

        return 0x00000030;

    case 0xd44: /* PRF1.  */

        return 0x00000200;

    case 0xd48: /* DFR0.  */

        return 0x00100000;

    case 0xd4c: /* AFR0.  */

        return 0x00000000;

    case 0xd50: /* MMFR0.  */

        return 0x00000030;

    case 0xd54: /* MMFR1.  */

        return 0x00000000;

    case 0xd58: /* MMFR2.  */

        return 0x00000000;

    case 0xd5c: /* MMFR3.  */

        return 0x00000000;

    case 0xd60: /* ISAR0.  */

        return 0x01141110;

    case 0xd64: /* ISAR1.  */

        return 0x02111000;

    case 0xd68: /* ISAR2.  */

        return 0x21112231;

    case 0xd6c: /* ISAR3.  */

        return 0x01111110;

    case 0xd70: /* ISAR4.  */

        return 0x01310102;

    /* TODO: Implement debug registers.  */

    default:

        qemu_log_mask(LOG_GUEST_ERROR, "NVIC: Bad read offset 0x%x\n", offset);

        return 0;

    }

}

static void monitor_handle_command(Monitor *mon, const char *cmdline)

{

    const char *p, *pstart, *typestr;

    char *q;

    int c, nb_args, len, i, has_arg;

    const mon_cmd_t *cmd;

    char cmdname[256];

    char buf[1024];

    void *str_allocated[MAX_ARGS];

    void *args[MAX_ARGS];

    void (*handler_0)(Monitor *mon);

    void (*handler_1)(Monitor *mon, void *arg0);

    void (*handler_2)(Monitor *mon, void *arg0, void *arg1);

    void (*handler_3)(Monitor *mon, void *arg0, void *arg1, void *arg2);

    void (*handler_4)(Monitor *mon, void *arg0, void *arg1, void *arg2,

                      void *arg3);

    void (*handler_5)(Monitor *mon, void *arg0, void *arg1, void *arg2,

                      void *arg3, void *arg4);

    void (*handler_6)(Monitor *mon, void *arg0, void *arg1, void *arg2,

                      void *arg3, void *arg4, void *arg5);

    void (*handler_7)(Monitor *mon, void *arg0, void *arg1, void *arg2,

                      void *arg3, void *arg4, void *arg5, void *arg6);



#ifdef DEBUG

    monitor_printf(mon, "command='%s'\n", cmdline);

#endif



    /* extract the command name */

    p = cmdline;

    q = cmdname;

    while (qemu_isspace(*p))

        p++;

    if (*p == '\0')

        return;

    pstart = p;

    while (*p != '\0' && *p != '/' && !qemu_isspace(*p))

        p++;

    len = p - pstart;

    if (len > sizeof(cmdname) - 1)

        len = sizeof(cmdname) - 1;

    memcpy(cmdname, pstart, len);

    cmdname[len] = '\0';



    /* find the command */

    for(cmd = mon_cmds; cmd->name != NULL; cmd++) {

        if (compare_cmd(cmdname, cmd->name))

            goto found;

    }

    monitor_printf(mon, "unknown command: '%s'\n", cmdname);

    return;

 found:



    for(i = 0; i < MAX_ARGS; i++)

        str_allocated[i] = NULL;



    /* parse the parameters */

    typestr = cmd->args_type;

    nb_args = 0;

    for(;;) {

        c = *typestr;

        if (c == '\0')

            break;

        typestr++;

        switch(c) {

        case 'F':

        case 'B':

        case 's':

            {

                int ret;

                char *str;



                while (qemu_isspace(*p))

                    p++;

                if (*typestr == '?') {

                    typestr++;

                    if (*p == '\0') {

                        /* no optional string: NULL argument */

                        str = NULL;

                        goto add_str;

                    }

                }

                ret = get_str(buf, sizeof(buf), &p);

                if (ret < 0) {

                    switch(c) {

                    case 'F':

                        monitor_printf(mon, "%s: filename expected\n",

                                       cmdname);

                        break;

                    case 'B':

                        monitor_printf(mon, "%s: block device name expected\n",

                                       cmdname);

                        break;

                    default:

                        monitor_printf(mon, "%s: string expected\n", cmdname);

                        break;

                    }

                    goto fail;

                }

                str = qemu_malloc(strlen(buf) + 1);

                pstrcpy(str, sizeof(buf), buf);

                str_allocated[nb_args] = str;

            add_str:

                if (nb_args >= MAX_ARGS) {

                error_args:

                    monitor_printf(mon, "%s: too many arguments\n", cmdname);

                    goto fail;

                }

                args[nb_args++] = str;

            }

            break;

        case '/':

            {

                int count, format, size;



                while (qemu_isspace(*p))

                    p++;

                if (*p == '/') {

                    /* format found */

                    p++;

                    count = 1;

                    if (qemu_isdigit(*p)) {

                        count = 0;

                        while (qemu_isdigit(*p)) {

                            count = count * 10 + (*p - '0');

                            p++;

                        }

                    }

                    size = -1;

                    format = -1;

                    for(;;) {

                        switch(*p) {

                        case 'o':

                        case 'd':

                        case 'u':

                        case 'x':

                        case 'i':

                        case 'c':

                            format = *p++;

                            break;

                        case 'b':

                            size = 1;

                            p++;

                            break;

                        case 'h':

                            size = 2;

                            p++;

                            break;

                        case 'w':

                            size = 4;

                            p++;

                            break;

                        case 'g':

                        case 'L':

                            size = 8;

                            p++;

                            break;

                        default:

                            goto next;

                        }

                    }

                next:

                    if (*p != '\0' && !qemu_isspace(*p)) {

                        monitor_printf(mon, "invalid char in format: '%c'\n",

                                       *p);

                        goto fail;

                    }

                    if (format < 0)

                        format = default_fmt_format;

                    if (format != 'i') {

                        /* for 'i', not specifying a size gives -1 as size */

                        if (size < 0)

                            size = default_fmt_size;

                        default_fmt_size = size;

                    }

                    default_fmt_format = format;

                } else {

                    count = 1;

                    format = default_fmt_format;

                    if (format != 'i') {

                        size = default_fmt_size;

                    } else {

                        size = -1;

                    }

                }

                if (nb_args + 3 > MAX_ARGS)

                    goto error_args;

                args[nb_args++] = (void*)(long)count;

                args[nb_args++] = (void*)(long)format;

                args[nb_args++] = (void*)(long)size;

            }

            break;

        case 'i':

        case 'l':

            {

                int64_t val;



                while (qemu_isspace(*p))

                    p++;

                if (*typestr == '?' || *typestr == '.') {

                    if (*typestr == '?') {

                        if (*p == '\0')

                            has_arg = 0;

                        else

                            has_arg = 1;

                    } else {

                        if (*p == '.') {

                            p++;

                            while (qemu_isspace(*p))

                                p++;

                            has_arg = 1;

                        } else {

                            has_arg = 0;

                        }

                    }

                    typestr++;

                    if (nb_args >= MAX_ARGS)

                        goto error_args;

                    args[nb_args++] = (void *)(long)has_arg;

                    if (!has_arg) {

                        if (nb_args >= MAX_ARGS)

                            goto error_args;

                        val = -1;

                        goto add_num;

                    }

                }

                if (get_expr(mon, &val, &p))

                    goto fail;

            add_num:

                if (c == 'i') {

                    if (nb_args >= MAX_ARGS)

                        goto error_args;

                    args[nb_args++] = (void *)(long)val;

                } else {

                    if ((nb_args + 1) >= MAX_ARGS)

                        goto error_args;

#if TARGET_PHYS_ADDR_BITS > 32

                    args[nb_args++] = (void *)(long)((val >> 32) & 0xffffffff);

#else

                    args[nb_args++] = (void *)0;

#endif

                    args[nb_args++] = (void *)(long)(val & 0xffffffff);

                }

            }

            break;

        case '-':

            {

                int has_option;

                /* option */



                c = *typestr++;

                if (c == '\0')

                    goto bad_type;

                while (qemu_isspace(*p))

                    p++;

                has_option = 0;

                if (*p == '-') {

                    p++;

                    if (*p != c) {

                        monitor_printf(mon, "%s: unsupported option -%c\n",

                                       cmdname, *p);

                        goto fail;

                    }

                    p++;

                    has_option = 1;

                }

                if (nb_args >= MAX_ARGS)

                    goto error_args;

                args[nb_args++] = (void *)(long)has_option;

            }

            break;

        default:

        bad_type:

            monitor_printf(mon, "%s: unknown type '%c'\n", cmdname, c);

            goto fail;

        }

    }

    /* check that all arguments were parsed */

    while (qemu_isspace(*p))

        p++;

    if (*p != '\0') {

        monitor_printf(mon, "%s: extraneous characters at the end of line\n",

                       cmdname);

        goto fail;

    }



    switch(nb_args) {

    case 0:

        handler_0 = cmd->handler;

        handler_0(mon);

        break;

    case 1:

        handler_1 = cmd->handler;

        handler_1(mon, args[0]);

        break;

    case 2:

        handler_2 = cmd->handler;

        handler_2(mon, args[0], args[1]);

        break;

    case 3:

        handler_3 = cmd->handler;

        handler_3(mon, args[0], args[1], args[2]);

        break;

    case 4:

        handler_4 = cmd->handler;

        handler_4(mon, args[0], args[1], args[2], args[3]);

        break;

    case 5:

        handler_5 = cmd->handler;

        handler_5(mon, args[0], args[1], args[2], args[3], args[4]);

        break;

    case 6:

        handler_6 = cmd->handler;

        handler_6(mon, args[0], args[1], args[2], args[3], args[4], args[5]);

        break;

    case 7:

        handler_7 = cmd->handler;

        handler_7(mon, args[0], args[1], args[2], args[3], args[4], args[5],

                  args[6]);

        break;

    default:

        monitor_printf(mon, "unsupported number of arguments: %d\n", nb_args);

        goto fail;

    }

 fail:

    for(i = 0; i < MAX_ARGS; i++)

        qemu_free(str_allocated[i]);

    return;

}

static inline int round_sample(int64_t *sum)

{

    int sum1;

    sum1 = (int)((*sum) >> OUT_SHIFT);

    *sum &= (1<<OUT_SHIFT)-1;

    return av_clip(sum1, OUT_MIN, OUT_MAX);

}

static inline void gen_neon_mull(TCGv_i64 dest, TCGv a, TCGv b, int size, int u)

{

    TCGv_i64 tmp;



    switch ((size << 1) | u) {

    case 0: gen_helper_neon_mull_s8(dest, a, b); break;

    case 1: gen_helper_neon_mull_u8(dest, a, b); break;

    case 2: gen_helper_neon_mull_s16(dest, a, b); break;

    case 3: gen_helper_neon_mull_u16(dest, a, b); break;

    case 4:

        tmp = gen_muls_i64_i32(a, b);

        tcg_gen_mov_i64(dest, tmp);


        break;

    case 5:

        tmp = gen_mulu_i64_i32(a, b);

        tcg_gen_mov_i64(dest, tmp);


        break;

    default: abort();

    }



    /* gen_helper_neon_mull_[su]{8|16} do not free their parameters.

       Don't forget to clean them now.  */

    if (size < 2) {

        tcg_temp_free_i32(a);

        tcg_temp_free_i32(b);

    }

}

static void test_visitor_out_null(TestOutputVisitorData *data,

                                  const void *unused)

{

    QObject *arg;

    QDict *qdict;

    QObject *nil;



    visit_start_struct(data->ov, NULL, NULL, 0, &error_abort);

    visit_type_null(data->ov, "a", &error_abort);

    visit_end_struct(data->ov, &error_abort);

    arg = qmp_output_get_qobject(data->qov);

    g_assert(qobject_type(arg) == QTYPE_QDICT);

    qdict = qobject_to_qdict(arg);

    g_assert_cmpint(qdict_size(qdict), ==, 1);

    nil = qdict_get(qdict, "a");

    g_assert(nil);

    g_assert(qobject_type(nil) == QTYPE_QNULL);

    qobject_decref(arg);

}

static int cirrus_bitblt_common_patterncopy(CirrusVGAState * s,

					    const uint8_t * src)

{

    uint8_t *dst;



    dst = s->vga.vram_ptr + (s->cirrus_blt_dstaddr & s->cirrus_addr_mask);



    if (BLTUNSAFE(s))

        return 0;



    (*s->cirrus_rop) (s, dst, src,

                      s->cirrus_blt_dstpitch, 0,

                      s->cirrus_blt_width, s->cirrus_blt_height);

    cirrus_invalidate_region(s, s->cirrus_blt_dstaddr,

                             s->cirrus_blt_dstpitch, s->cirrus_blt_width,

                             s->cirrus_blt_height);

    return 1;

}

static TranslationBlock *tb_find_physical(CPUState *cpu,

                                          target_ulong pc,

                                          target_ulong cs_base,

                                          uint32_t flags)

{

    CPUArchState *env = (CPUArchState *)cpu->env_ptr;

    TranslationBlock *tb, **tb_hash_head, **ptb1;

    unsigned int h;

    tb_page_addr_t phys_pc, phys_page1;



    tcg_ctx.tb_ctx.tb_invalidated_flag = 0;



    /* find translated block using physical mappings */

    phys_pc = get_page_addr_code(env, pc);

    phys_page1 = phys_pc & TARGET_PAGE_MASK;

    h = tb_phys_hash_func(phys_pc);



    /* Start at head of the hash entry */

    ptb1 = tb_hash_head = &tcg_ctx.tb_ctx.tb_phys_hash[h];

    tb = *ptb1;



    while (tb) {

        if (tb->pc == pc &&

            tb->page_addr[0] == phys_page1 &&

            tb->cs_base == cs_base &&

            tb->flags == flags) {



            if (tb->page_addr[1] == -1) {

                /* done, we have a match */

                break;

            } else {

                /* check next page if needed */

                target_ulong virt_page2 = (pc & TARGET_PAGE_MASK) +

                                          TARGET_PAGE_SIZE;

                tb_page_addr_t phys_page2 = get_page_addr_code(env, virt_page2);



                if (tb->page_addr[1] == phys_page2) {

                    break;

                }

            }

        }



        ptb1 = &tb->phys_hash_next;

        tb = *ptb1;

    }



    if (tb) {

        /* Move the TB to the head of the list */

        *ptb1 = tb->phys_hash_next;

        tb->phys_hash_next = *tb_hash_head;

        *tb_hash_head = tb;

    }

    return tb;

}

static int qcow2_co_flush(BlockDriverState *bs)

{

    BDRVQcowState *s = bs->opaque;

    int ret;



    qemu_co_mutex_lock(&s->lock);

    ret = qcow2_cache_flush(bs, s->l2_table_cache);

    if (ret < 0) {


        return ret;

    }



    ret = qcow2_cache_flush(bs, s->refcount_block_cache);

    if (ret < 0) {


        return ret;

    }




    return bdrv_co_flush(bs->file);

}

static int ram_load_dead(QEMUFile *f, void *opaque)

{

    RamDecompressState s1, *s = &s1;

    uint8_t buf[10];

    ram_addr_t i;



    if (ram_decompress_open(s, f) < 0)

        return -EINVAL;

    for(i = 0; i < last_ram_offset; i+= BDRV_HASH_BLOCK_SIZE) {

        if (ram_decompress_buf(s, buf, 1) < 0) {

            fprintf(stderr, "Error while reading ram block header\n");

            goto error;

        }

        if (buf[0] == 0) {

            if (ram_decompress_buf(s, qemu_get_ram_ptr(i),

                                   BDRV_HASH_BLOCK_SIZE) < 0) {

                fprintf(stderr, "Error while reading ram block address=0x%08" PRIx64, (uint64_t)i);

                goto error;

            }

        } else {

        error:

            printf("Error block header\n");

            return -EINVAL;

        }

    }

    ram_decompress_close(s);



    return 0;

}

int rom_load_all(void)

{

    target_phys_addr_t addr = 0;

    int memtype;

    Rom *rom;



    QTAILQ_FOREACH(rom, &roms, next) {

        if (addr < rom->min)

            addr = rom->min;

        if (rom->max) {

            /* load address range */

            if (rom->align) {

                addr += (rom->align-1);

                addr &= ~(rom->align-1);

            }

            if (addr + rom->romsize > rom->max) {

                fprintf(stderr, "rom: out of memory (rom %s, "

                        "addr 0x" TARGET_FMT_plx

                        ", size 0x%zx, max 0x" TARGET_FMT_plx ")\n",

                        rom->name, addr, rom->romsize, rom->max);

                return -1;

            }

        } else {

            /* fixed address requested */

            if (addr != rom->min) {

                fprintf(stderr, "rom: requested regions overlap "

                        "(rom %s. free=0x" TARGET_FMT_plx

                        ", addr=0x" TARGET_FMT_plx ")\n",

                        rom->name, addr, rom->min);

                return -1;

            }

        }

        rom->addr = addr;

        addr += rom->romsize;

        memtype = cpu_get_physical_page_desc(rom->addr) & (3 << IO_MEM_SHIFT);

        if (memtype == IO_MEM_ROM)

            rom->isrom = 1;

    }

    qemu_register_reset(rom_reset, NULL);

    roms_loaded = 1;

    return 0;

}

static int local_chown(FsContext *ctx, const char *path, uid_t uid, gid_t gid)

{

    return chown(rpath(ctx, path), uid, gid);

}

START_TEST(keyword_literal)

{

    QObject *obj;

    QBool *qbool;

    QString *str;



    obj = qobject_from_json("true");

    fail_unless(obj != NULL);

    fail_unless(qobject_type(obj) == QTYPE_QBOOL);



    qbool = qobject_to_qbool(obj);

    fail_unless(qbool_get_int(qbool) != 0);



    str = qobject_to_json(obj);

    fail_unless(strcmp(qstring_get_str(str), "true") == 0);

    QDECREF(str);



    QDECREF(qbool);



    obj = qobject_from_json("false");

    fail_unless(obj != NULL);

    fail_unless(qobject_type(obj) == QTYPE_QBOOL);



    qbool = qobject_to_qbool(obj);

    fail_unless(qbool_get_int(qbool) == 0);



    str = qobject_to_json(obj);

    fail_unless(strcmp(qstring_get_str(str), "false") == 0);

    QDECREF(str);



    QDECREF(qbool);



    obj = qobject_from_jsonf("%i", false);

    fail_unless(obj != NULL);

    fail_unless(qobject_type(obj) == QTYPE_QBOOL);



    qbool = qobject_to_qbool(obj);

    fail_unless(qbool_get_int(qbool) == 0);



    QDECREF(qbool);



    obj = qobject_from_jsonf("%i", true);

    fail_unless(obj != NULL);

    fail_unless(qobject_type(obj) == QTYPE_QBOOL);



    qbool = qobject_to_qbool(obj);

    fail_unless(qbool_get_int(qbool) != 0);



    QDECREF(qbool);

}

static inline void sync_jmpstate(DisasContext *dc)

{

    if (dc->jmp == JMP_DIRECT) {

            dc->jmp = JMP_INDIRECT;

            tcg_gen_movi_tl(env_btaken, 1);

            tcg_gen_movi_tl(env_btarget, dc->jmp_pc);

    }

}

target_ulong helper_lwr(CPUMIPSState *env, target_ulong arg1,

                        target_ulong arg2, int mem_idx)

{

    target_ulong tmp;



    tmp = do_lbu(env, arg2, mem_idx);

    arg1 = (arg1 & 0xFFFFFF00) | tmp;



    if (GET_LMASK(arg2) >= 1) {

        tmp = do_lbu(env, GET_OFFSET(arg2, -1), mem_idx);

        arg1 = (arg1 & 0xFFFF00FF) | (tmp << 8);

    }



    if (GET_LMASK(arg2) >= 2) {

        tmp = do_lbu(env, GET_OFFSET(arg2, -2), mem_idx);

        arg1 = (arg1 & 0xFF00FFFF) | (tmp << 16);

    }



    if (GET_LMASK(arg2) == 3) {

        tmp = do_lbu(env, GET_OFFSET(arg2, -3), mem_idx);

        arg1 = (arg1 & 0x00FFFFFF) | (tmp << 24);

    }

    return (int32_t)arg1;

}

static int unpack_dct_coeffs(Vp3DecodeContext *s, GetBitContext *gb)

{

    int i;

    int dc_y_table;

    int dc_c_table;

    int ac_y_table;

    int ac_c_table;

    int residual_eob_run = 0;



    /* fetch the DC table indexes */

    dc_y_table = get_bits(gb, 4);

    dc_c_table = get_bits(gb, 4);



    /* unpack the Y plane DC coefficients */

    residual_eob_run = unpack_vlcs(s, gb, &s->dc_vlc[dc_y_table], 0,

        1, residual_eob_run);



    /* reverse prediction of the Y-plane DC coefficients */

    reverse_dc_prediction(s, 0, s->fragment_width, s->fragment_height);



    /* unpack the C plane DC coefficients */

    residual_eob_run = unpack_vlcs(s, gb, &s->dc_vlc[dc_c_table], 0,

        0, residual_eob_run);



    /* reverse prediction of the C-plane DC coefficients */

    if (!(s->avctx->flags & CODEC_FLAG_GRAY))

    {

        reverse_dc_prediction(s, s->fragment_start[1],

            s->fragment_width / 2, s->fragment_height / 2);

        reverse_dc_prediction(s, s->fragment_start[2],

            s->fragment_width / 2, s->fragment_height / 2);

    }



    /* fetch the AC table indexes */

    ac_y_table = get_bits(gb, 4);

    ac_c_table = get_bits(gb, 4);



    /* unpack the group 1 AC coefficients (coeffs 1-5) */

    for (i = 1; i <= 5; i++) {

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_1[ac_y_table], i,

            1, residual_eob_run);



        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_1[ac_c_table], i,

            0, residual_eob_run);

    }



    /* unpack the group 2 AC coefficients (coeffs 6-14) */

    for (i = 6; i <= 14; i++) {

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_2[ac_y_table], i,

            1, residual_eob_run);



        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_2[ac_c_table], i,

            0, residual_eob_run);

    }



    /* unpack the group 3 AC coefficients (coeffs 15-27) */

    for (i = 15; i <= 27; i++) {

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_3[ac_y_table], i,

            1, residual_eob_run);



        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_3[ac_c_table], i,

            0, residual_eob_run);

    }



    /* unpack the group 4 AC coefficients (coeffs 28-63) */

    for (i = 28; i <= 63; i++) {

        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_4[ac_y_table], i,

            1, residual_eob_run);



        residual_eob_run = unpack_vlcs(s, gb, &s->ac_vlc_4[ac_c_table], i,

            0, residual_eob_run);

    }



    return 0;

}

static int raw_decode(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    int linesize_align = 4;

    RawVideoContext *context = avctx->priv_data;



    AVFrame   *frame   = data;

    AVPicture *picture = data;



    frame->pict_type        = avctx->coded_frame->pict_type;

    frame->interlaced_frame = avctx->coded_frame->interlaced_frame;

    frame->top_field_first = avctx->coded_frame->top_field_first;

    frame->reordered_opaque = avctx->reordered_opaque;

    frame->pkt_pts          = avctx->pkt->pts;

    frame->pkt_pos          = avctx->pkt->pos;



    if(context->tff>=0){

        frame->interlaced_frame = 1;

        frame->top_field_first  = context->tff;

    }



    if(buf_size < context->length - (avctx->pix_fmt==PIX_FMT_PAL8 ? 256*4 : 0))

        return -1;



    if (avctx->width <= 0 || avctx->height <= 0) {

        av_log(avctx, AV_LOG_ERROR, "w/h is invalid\n");

        return AVERROR(EINVAL);

    }



    //2bpp and 4bpp raw in avi and mov (yes this is ugly ...)

    if (context->buffer) {

        int i;

        uint8_t *dst = context->buffer;

        buf_size = context->length - 256*4;

        if (avctx->bits_per_coded_sample == 4){

            for(i=0; 2*i+1 < buf_size && i<avpkt->size; i++){

                dst[2*i+0]= buf[i]>>4;

                dst[2*i+1]= buf[i]&15;

            }

            linesize_align = 8;

        } else {

            for(i=0; 4*i+3 < buf_size && i<avpkt->size; i++){

                dst[4*i+0]= buf[i]>>6;

                dst[4*i+1]= buf[i]>>4&3;

                dst[4*i+2]= buf[i]>>2&3;

                dst[4*i+3]= buf[i]   &3;

            }

            linesize_align = 16;

        }

        buf= dst;

    }



    if(avctx->codec_tag == MKTAG('A', 'V', '1', 'x') ||

       avctx->codec_tag == MKTAG('A', 'V', 'u', 'p'))

        buf += buf_size - context->length;



    avpicture_fill(picture, buf, avctx->pix_fmt, avctx->width, avctx->height);

    if((avctx->pix_fmt==PIX_FMT_PAL8 && buf_size < context->length) ||

       (av_pix_fmt_descriptors[avctx->pix_fmt].flags & PIX_FMT_PSEUDOPAL)) {

        frame->data[1]= context->palette;

    }

    if (avctx->pix_fmt == PIX_FMT_PAL8) {

        const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



        if (pal) {

            memcpy(frame->data[1], pal, AVPALETTE_SIZE);

            frame->palette_has_changed = 1;

        }

    }

    if((avctx->pix_fmt==PIX_FMT_BGR24    ||

        avctx->pix_fmt==PIX_FMT_GRAY8    ||

        avctx->pix_fmt==PIX_FMT_RGB555LE ||

        avctx->pix_fmt==PIX_FMT_RGB555BE ||

        avctx->pix_fmt==PIX_FMT_RGB565LE ||

        avctx->pix_fmt==PIX_FMT_MONOWHITE ||

        avctx->pix_fmt==PIX_FMT_PAL8) &&

        FFALIGN(frame->linesize[0], linesize_align)*avctx->height <= buf_size)

        frame->linesize[0] = FFALIGN(frame->linesize[0], linesize_align);



    if(context->flip)

        flip(avctx, picture);



    if (   avctx->codec_tag == MKTAG('Y', 'V', '1', '2')

        || avctx->codec_tag == MKTAG('Y', 'V', '1', '6')

        || avctx->codec_tag == MKTAG('Y', 'V', '2', '4')

        || avctx->codec_tag == MKTAG('Y', 'V', 'U', '9'))

        FFSWAP(uint8_t *, picture->data[1], picture->data[2]);



    if(avctx->codec_tag == AV_RL32("yuv2") &&

       avctx->pix_fmt   == PIX_FMT_YUYV422) {

        int x, y;

        uint8_t *line = picture->data[0];

        for(y = 0; y < avctx->height; y++) {

            for(x = 0; x < avctx->width; x++)

                line[2*x + 1] ^= 0x80;

            line += picture->linesize[0];

        }

    }



    *data_size = sizeof(AVPicture);

    return buf_size;

}

static int ipvideo_decode_block_opcode_0x8(IpvideoContext *s)

{

    int x, y;

    unsigned char P[2];

    unsigned int flags = 0;



    /* 2-color encoding for each 4x4 quadrant, or 2-color encoding on

     * either top and bottom or left and right halves */

    CHECK_STREAM_PTR(2);



    P[0] = *s->stream_ptr++;

    P[1] = *s->stream_ptr++;



    if (P[0] <= P[1]) {



        CHECK_STREAM_PTR(14);

        s->stream_ptr -= 2;



        for (y = 0; y < 16; y++) {

            // new values for each 4x4 block

            if (!(y & 3)) {

                P[0] = *s->stream_ptr++; P[1] = *s->stream_ptr++;

                flags = bytestream_get_le16(&s->stream_ptr);

            }



            for (x = 0; x < 4; x++, flags >>= 1)

                *s->pixel_ptr++ = P[flags & 1];

            s->pixel_ptr += s->stride - 4;

            // switch to right half

            if (y == 7) s->pixel_ptr -= 8 * s->stride - 4;

        }



    } else {



        /* need 10 more bytes */

        CHECK_STREAM_PTR(10);



        if (s->stream_ptr[4] <= s->stream_ptr[5]) {



            flags = bytestream_get_le32(&s->stream_ptr);



            /* vertical split; left & right halves are 2-color encoded */



            for (y = 0; y < 16; y++) {

                for (x = 0; x < 4; x++, flags >>= 1)

                    *s->pixel_ptr++ = P[flags & 1];

                s->pixel_ptr += s->stride - 4;

                // switch to right half

                if (y == 7) {

                    s->pixel_ptr -= 8 * s->stride - 4;

                    P[0] = *s->stream_ptr++; P[1] = *s->stream_ptr++;

                    flags = bytestream_get_le32(&s->stream_ptr);

                }

            }



        } else {



            /* horizontal split; top & bottom halves are 2-color encoded */



            for (y = 0; y < 8; y++) {

                if (y == 4) {

                    P[0] = *s->stream_ptr++;

                    P[1] = *s->stream_ptr++;

                }

                flags = *s->stream_ptr++ | 0x100;



                for (; flags != 1; flags >>= 1)

                    *s->pixel_ptr++ = P[flags & 1];

                s->pixel_ptr += s->line_inc;

            }

        }

    }



    /* report success */

    return 0;

}

static void scsi_destroy(SCSIDevice *dev)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, dev);



    scsi_disk_purge_requests(s);

    blockdev_mark_auto_del(s->qdev.conf.dinfo->bdrv);

}

int MPV_encode_init(AVCodecContext *avctx)

{

    MpegEncContext *s = avctx->priv_data;

    int i, dummy;

    int chroma_h_shift, chroma_v_shift;



    avctx->pix_fmt = PIX_FMT_YUV420P; // FIXME



    s->bit_rate = avctx->bit_rate;

    s->width = avctx->width;

    s->height = avctx->height;

    if(avctx->gop_size > 600){

	av_log(avctx, AV_LOG_ERROR, "Warning keyframe interval too large! reducing it ...\n");

        avctx->gop_size=600;

    }

    s->gop_size = avctx->gop_size;

    s->avctx = avctx;

    s->flags= avctx->flags;

    s->flags2= avctx->flags2;

    s->max_b_frames= avctx->max_b_frames;

    s->codec_id= avctx->codec->id;

    s->luma_elim_threshold  = avctx->luma_elim_threshold;

    s->chroma_elim_threshold= avctx->chroma_elim_threshold;

    s->strict_std_compliance= avctx->strict_std_compliance;

    s->data_partitioning= avctx->flags & CODEC_FLAG_PART;

    s->quarter_sample= (avctx->flags & CODEC_FLAG_QPEL)!=0;

    s->mpeg_quant= avctx->mpeg_quant;

    s->rtp_mode= !!avctx->rtp_payload_size;



    if (s->gop_size <= 1) {

        s->intra_only = 1;

        s->gop_size = 12;

    } else {

        s->intra_only = 0;

    }



    s->me_method = avctx->me_method;



    /* Fixed QSCALE */

    s->fixed_qscale = !!(avctx->flags & CODEC_FLAG_QSCALE);



    s->adaptive_quant= (   s->avctx->lumi_masking

                        || s->avctx->dark_masking

                        || s->avctx->temporal_cplx_masking 

                        || s->avctx->spatial_cplx_masking

                        || s->avctx->p_masking

                        || (s->flags&CODEC_FLAG_QP_RD))

                       && !s->fixed_qscale;



    s->obmc= !!(s->flags & CODEC_FLAG_OBMC);

    s->loop_filter= !!(s->flags & CODEC_FLAG_LOOP_FILTER);

    s->alternate_scan= !!(s->flags & CODEC_FLAG_ALT_SCAN);



    if(avctx->rc_max_rate && !avctx->rc_buffer_size){

        av_log(avctx, AV_LOG_ERROR, "a vbv buffer size is needed, for encoding with a maximum bitrate\n");

        return -1;

    }    



    if(avctx->rc_min_rate && avctx->rc_max_rate != avctx->rc_min_rate){

        av_log(avctx, AV_LOG_INFO, "Warning min_rate > 0 but min_rate != max_rate isnt recommanded!\n");

    }    



    if((s->flags & CODEC_FLAG_4MV) && s->codec_id != CODEC_ID_MPEG4 

       && s->codec_id != CODEC_ID_H263 && s->codec_id != CODEC_ID_H263P){

        av_log(avctx, AV_LOG_ERROR, "4MV not supported by codec\n");

        return -1;

    }



    if(s->obmc && s->avctx->mb_decision != FF_MB_DECISION_SIMPLE){

        av_log(avctx, AV_LOG_ERROR, "OBMC is only supported with simple mb decission\n");

        return -1;

    }



    if(s->obmc && s->codec_id != CODEC_ID_H263 && s->codec_id != CODEC_ID_H263P){

        av_log(avctx, AV_LOG_ERROR, "OBMC is only supported with H263(+)\n");

        return -1;

    }



    if(s->quarter_sample && s->codec_id != CODEC_ID_MPEG4){

        av_log(avctx, AV_LOG_ERROR, "qpel not supported by codec\n");

        return -1;

    }



    if(s->data_partitioning && s->codec_id != CODEC_ID_MPEG4){

        av_log(avctx, AV_LOG_ERROR, "data partitioning not supported by codec\n");

        return -1;

    }



    if(s->max_b_frames && s->codec_id != CODEC_ID_MPEG4 && s->codec_id != CODEC_ID_MPEG1VIDEO && s->codec_id != CODEC_ID_MPEG2VIDEO){

        av_log(avctx, AV_LOG_ERROR, "b frames not supported by codec\n");

        return -1;

    }



    if(s->mpeg_quant && s->codec_id != CODEC_ID_MPEG4){ //FIXME mpeg2 uses that too

        av_log(avctx, AV_LOG_ERROR, "mpeg2 style quantization not supporetd by codec\n");

        return -1;

    }



    if((s->flags & CODEC_FLAG_CBP_RD) && !(s->flags & CODEC_FLAG_TRELLIS_QUANT)){

        av_log(avctx, AV_LOG_ERROR, "CBP RD needs trellis quant\n");

        return -1;

    }



    if((s->flags & CODEC_FLAG_QP_RD) && s->avctx->mb_decision != FF_MB_DECISION_RD){

        av_log(avctx, AV_LOG_ERROR, "QP RD needs mbd=2\n");

        return -1;

    }



    if(s->avctx->scenechange_threshold < 1000000000 && (s->flags & CODEC_FLAG_CLOSED_GOP)){

        av_log(avctx, AV_LOG_ERROR, "closed gop with scene change detection arent supported yet\n");

        return -1;

    }



    i= ff_gcd(avctx->frame_rate, avctx->frame_rate_base);

    if(i > 1){

        av_log(avctx, AV_LOG_INFO, "removing common factors from framerate\n");

        avctx->frame_rate /= i;

        avctx->frame_rate_base /= i;

//        return -1;

    }



    if(s->codec_id==CODEC_ID_MJPEG){

        s->intra_quant_bias= 1<<(QUANT_BIAS_SHIFT-1); //(a + x/2)/x

        s->inter_quant_bias= 0;

    }else if(s->mpeg_quant || s->codec_id==CODEC_ID_MPEG1VIDEO || s->codec_id==CODEC_ID_MPEG2VIDEO){

        s->intra_quant_bias= 3<<(QUANT_BIAS_SHIFT-3); //(a + x*3/8)/x

        s->inter_quant_bias= 0;

    }else{

        s->intra_quant_bias=0;

        s->inter_quant_bias=-(1<<(QUANT_BIAS_SHIFT-2)); //(a - x/4)/x

    }



    if(avctx->intra_quant_bias != FF_DEFAULT_QUANT_BIAS)

        s->intra_quant_bias= avctx->intra_quant_bias;

    if(avctx->inter_quant_bias != FF_DEFAULT_QUANT_BIAS)

        s->inter_quant_bias= avctx->inter_quant_bias;



    avcodec_get_chroma_sub_sample(avctx->pix_fmt, &chroma_h_shift, &chroma_v_shift);



    av_reduce(&s->time_increment_resolution, &dummy, s->avctx->frame_rate, s->avctx->frame_rate_base, (1<<16)-1);

    s->time_increment_bits = av_log2(s->time_increment_resolution - 1) + 1;



    switch(avctx->codec->id) {

    case CODEC_ID_MPEG1VIDEO:

        s->out_format = FMT_MPEG1;

        s->low_delay= 0; //s->max_b_frames ? 0 : 1;

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1);

        break;

    case CODEC_ID_MPEG2VIDEO:

        s->out_format = FMT_MPEG1;

        s->low_delay= 0; //s->max_b_frames ? 0 : 1;

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1);

        s->rtp_mode= 1;

        break;

    case CODEC_ID_LJPEG:

    case CODEC_ID_MJPEG:

        s->out_format = FMT_MJPEG;

        s->intra_only = 1; /* force intra only for jpeg */

        s->mjpeg_write_tables = 1; /* write all tables */

	s->mjpeg_data_only_frames = 0; /* write all the needed headers */

        s->mjpeg_vsample[0] = 1<<chroma_v_shift;

        s->mjpeg_vsample[1] = 1;

        s->mjpeg_vsample[2] = 1; 

        s->mjpeg_hsample[0] = 1<<chroma_h_shift;

        s->mjpeg_hsample[1] = 1; 

        s->mjpeg_hsample[2] = 1; 

        if (mjpeg_init(s) < 0)

            return -1;

        avctx->delay=0;

        s->low_delay=1;

        break;

#ifdef CONFIG_RISKY

    case CODEC_ID_H263:

        if (h263_get_picture_format(s->width, s->height) == 7) {

            av_log(avctx, AV_LOG_INFO, "Input picture size isn't suitable for h263 codec! try h263+\n");

            return -1;

        }

        s->out_format = FMT_H263;

	s->obmc= (avctx->flags & CODEC_FLAG_OBMC) ? 1:0;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_H263P:

        s->out_format = FMT_H263;

        s->h263_plus = 1;

	/* Fx */

        s->umvplus = (avctx->flags & CODEC_FLAG_H263P_UMV) ? 1:0;

	s->h263_aic= (avctx->flags & CODEC_FLAG_H263P_AIC) ? 1:0;

	s->modified_quant= s->h263_aic;

	s->alt_inter_vlc= (avctx->flags & CODEC_FLAG_H263P_AIV) ? 1:0;

	s->obmc= (avctx->flags & CODEC_FLAG_OBMC) ? 1:0;

	s->loop_filter= (avctx->flags & CODEC_FLAG_LOOP_FILTER) ? 1:0;

	s->unrestricted_mv= s->obmc || s->loop_filter || s->umvplus;

        s->h263_slice_structured= (s->flags & CODEC_FLAG_H263P_SLICE_STRUCT) ? 1:0;



	/* /Fx */

        /* These are just to be sure */

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_FLV1:

        s->out_format = FMT_H263;

        s->h263_flv = 2; /* format = 1; 11-bit codes */

        s->unrestricted_mv = 1;

        s->rtp_mode=0; /* don't allow GOB */

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_RV10:

        s->out_format = FMT_H263;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_MPEG4:

        s->out_format = FMT_H263;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->low_delay= s->max_b_frames ? 0 : 1;

        avctx->delay= s->low_delay ? 0 : (s->max_b_frames + 1);

        break;

    case CODEC_ID_MSMPEG4V1:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_MSMPEG4V2:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 2;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_MSMPEG4V3:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 3;

        s->flipflop_rounding=1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_WMV1:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 4;

        s->flipflop_rounding=1;

        avctx->delay=0;

        s->low_delay=1;

        break;

    case CODEC_ID_WMV2:

        s->out_format = FMT_H263;

        s->h263_msmpeg4 = 1;

        s->h263_pred = 1;

        s->unrestricted_mv = 1;

        s->msmpeg4_version= 5;

        s->flipflop_rounding=1;

        avctx->delay=0;

        s->low_delay=1;

        break;

#endif

    default:

        return -1;

    }



    { /* set up some save defaults, some codecs might override them later */

        static int done=0;

        if(!done){

            int i;

            done=1;



            default_mv_penalty= av_mallocz( sizeof(uint8_t)*(MAX_FCODE+1)*(2*MAX_MV+1) );

            memset(default_mv_penalty, 0, sizeof(uint8_t)*(MAX_FCODE+1)*(2*MAX_MV+1));

            memset(default_fcode_tab , 0, sizeof(uint8_t)*(2*MAX_MV+1));



            for(i=-16; i<16; i++){

                default_fcode_tab[i + MAX_MV]= 1;

            }

        }

    }

    s->me.mv_penalty= default_mv_penalty;

    s->fcode_tab= default_fcode_tab;



    /* dont use mv_penalty table for crap MV as it would be confused */

    //FIXME remove after fixing / removing old ME

    if (s->me_method < ME_EPZS) s->me.mv_penalty = default_mv_penalty;



    s->encoding = 1;



    /* init */

    if (MPV_common_init(s) < 0)

        return -1;



    if(s->modified_quant)

        s->chroma_qscale_table= ff_h263_chroma_qscale_table;

    s->progressive_frame= 

    s->progressive_sequence= !(avctx->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME));



    ff_set_cmp(&s->dsp, s->dsp.ildct_cmp, s->avctx->ildct_cmp);



    ff_init_me(s);



#ifdef CONFIG_ENCODERS

#ifdef CONFIG_RISKY

    if (s->out_format == FMT_H263)

        h263_encode_init(s);

    if(s->msmpeg4_version)

        ff_msmpeg4_encode_init(s);

#endif

    if (s->out_format == FMT_MPEG1)

        ff_mpeg1_encode_init(s);

#endif



    /* init default q matrix */

    for(i=0;i<64;i++) {

        int j= s->dsp.idct_permutation[i];

#ifdef CONFIG_RISKY

        if(s->codec_id==CODEC_ID_MPEG4 && s->mpeg_quant){

            s->intra_matrix[j] = ff_mpeg4_default_intra_matrix[i];

            s->inter_matrix[j] = ff_mpeg4_default_non_intra_matrix[i];

        }else if(s->out_format == FMT_H263){

            s->intra_matrix[j] =

            s->inter_matrix[j] = ff_mpeg1_default_non_intra_matrix[i];

        }else

#endif

        { /* mpeg1/2 */

            s->intra_matrix[j] = ff_mpeg1_default_intra_matrix[i];

            s->inter_matrix[j] = ff_mpeg1_default_non_intra_matrix[i];

        }

        if(s->avctx->intra_matrix)

            s->intra_matrix[j] = s->avctx->intra_matrix[i];

        if(s->avctx->inter_matrix)

            s->inter_matrix[j] = s->avctx->inter_matrix[i];

    }



    /* precompute matrix */

    /* for mjpeg, we do include qscale in the matrix */

    if (s->out_format != FMT_MJPEG) {

        convert_matrix(&s->dsp, s->q_intra_matrix, s->q_intra_matrix16, 

                       s->intra_matrix, s->intra_quant_bias, 1, 31);

        convert_matrix(&s->dsp, s->q_inter_matrix, s->q_inter_matrix16, 

                       s->inter_matrix, s->inter_quant_bias, 1, 31);

    }



    if(ff_rate_control_init(s) < 0)

        return -1;



    s->picture_number = 0;

    s->input_picture_number = 0;

    s->picture_in_gop_number = 0;

    /* motion detector init */

    s->f_code = 1;

    s->b_code = 1;



    return 0;

}

static int msmpeg4v12_decode_mb(MpegEncContext *s, int16_t block[6][64])

{

    int cbp, code, i;

    uint32_t * const mb_type_ptr = &s->current_picture.mb_type[s->mb_x + s->mb_y*s->mb_stride];



    if (s->pict_type == AV_PICTURE_TYPE_P) {

        if (s->use_skip_mb_code) {

            if (get_bits1(&s->gb)) {

                /* skip mb */

                s->mb_intra = 0;

                for(i=0;i<6;i++)

                    s->block_last_index[i] = -1;

                s->mv_dir = MV_DIR_FORWARD;

                s->mv_type = MV_TYPE_16X16;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->mb_skipped = 1;

                *mb_type_ptr = MB_TYPE_SKIP | MB_TYPE_L0 | MB_TYPE_16x16;

                return 0;

            }

        }



        if(s->msmpeg4_version==2)

            code = get_vlc2(&s->gb, v2_mb_type_vlc.table, V2_MB_TYPE_VLC_BITS, 1);

        else

            code = get_vlc2(&s->gb, ff_h263_inter_MCBPC_vlc.table, INTER_MCBPC_VLC_BITS, 2);

        if(code<0 || code>7){

            av_log(s->avctx, AV_LOG_ERROR, "cbpc %d invalid at %d %d\n", code, s->mb_x, s->mb_y);

            return -1;

        }



        s->mb_intra = code >>2;



        cbp = code & 0x3;

    } else {

        s->mb_intra = 1;

        if(s->msmpeg4_version==2)

            cbp= get_vlc2(&s->gb, v2_intra_cbpc_vlc.table, V2_INTRA_CBPC_VLC_BITS, 1);

        else

            cbp= get_vlc2(&s->gb, ff_h263_intra_MCBPC_vlc.table, INTRA_MCBPC_VLC_BITS, 1);

        if(cbp<0 || cbp>3){

            av_log(s->avctx, AV_LOG_ERROR, "cbpc %d invalid at %d %d\n", cbp, s->mb_x, s->mb_y);

            return -1;

        }

    }



    if (!s->mb_intra) {

        int mx, my, cbpy;



        cbpy= get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1);

        if(cbpy<0){

            av_log(s->avctx, AV_LOG_ERROR, "cbpy %d invalid at %d %d\n", cbp, s->mb_x, s->mb_y);

            return -1;

        }



        cbp|= cbpy<<2;

        if(s->msmpeg4_version==1 || (cbp&3) != 3) cbp^= 0x3C;



        ff_h263_pred_motion(s, 0, 0, &mx, &my);

        mx= msmpeg4v2_decode_motion(s, mx, 1);

        my= msmpeg4v2_decode_motion(s, my, 1);



        s->mv_dir = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16;

        s->mv[0][0][0] = mx;

        s->mv[0][0][1] = my;

        *mb_type_ptr = MB_TYPE_L0 | MB_TYPE_16x16;

    } else {

        if(s->msmpeg4_version==2){

            s->ac_pred = get_bits1(&s->gb);

            cbp|= get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1)<<2; //FIXME check errors

        } else{

            s->ac_pred = 0;

            cbp|= get_vlc2(&s->gb, ff_h263_cbpy_vlc.table, CBPY_VLC_BITS, 1)<<2; //FIXME check errors

            if(s->pict_type==AV_PICTURE_TYPE_P) cbp^=0x3C;

        }

        *mb_type_ptr = MB_TYPE_INTRA;

    }



    s->bdsp.clear_blocks(s->block[0]);

    for (i = 0; i < 6; i++) {

        if (ff_msmpeg4_decode_block(s, block[i], i, (cbp >> (5 - i)) & 1, NULL) < 0)

        {

             av_log(s->avctx, AV_LOG_ERROR, "\nerror while decoding block: %d x %d (%d)\n", s->mb_x, s->mb_y, i);

             return -1;

        }

    }

    return 0;

}

static CPAccessResult ats_access(CPUARMState *env, const ARMCPRegInfo *ri)

{

    if (ri->opc2 & 4) {

        /* Other states are only available with TrustZone; in

         * a non-TZ implementation these registers don't exist

         * at all, which is an Uncategorized trap. This underdecoding

         * is safe because the reginfo is NO_MIGRATE.

         */

        return CP_ACCESS_TRAP_UNCATEGORIZED;

    }

    return CP_ACCESS_OK;

}

static void alac_linear_predictor(AlacEncodeContext *s, int ch)

{

    int i;

    LPCContext lpc = s->lpc[ch];



    if(lpc.lpc_order == 31) {

        s->predictor_buf[0] = s->sample_buf[ch][0];



        for(i=1; i<s->avctx->frame_size; i++)

            s->predictor_buf[i] = s->sample_buf[ch][i] - s->sample_buf[ch][i-1];



        return;

    }



    // generalised linear predictor



    if(lpc.lpc_order > 0) {

        int32_t *samples  = s->sample_buf[ch];

        int32_t *residual = s->predictor_buf;



        // generate warm-up samples

        residual[0] = samples[0];

        for(i=1;i<=lpc.lpc_order;i++)

            residual[i] = samples[i] - samples[i-1];



        // perform lpc on remaining samples

        for(i = lpc.lpc_order + 1; i < s->avctx->frame_size; i++) {

            int sum = 1 << (lpc.lpc_quant - 1), res_val, j;



            for (j = 0; j < lpc.lpc_order; j++) {

                sum += (samples[lpc.lpc_order-j] - samples[0]) *

                        lpc.lpc_coeff[j];

            }



            sum >>= lpc.lpc_quant;

            sum += samples[0];

            residual[i] = samples[lpc.lpc_order+1] - sum;

            res_val = residual[i];



            if(res_val) {

                int index = lpc.lpc_order - 1;

                int neg = (res_val < 0);



                while(index >= 0 && (neg ? (res_val < 0):(res_val > 0))) {

                    int val = samples[0] - samples[lpc.lpc_order - index];

                    int sign = (val ? FFSIGN(val) : 0);



                    if(neg)

                        sign*=-1;



                    lpc.lpc_coeff[index] -= sign;

                    val *= sign;

                    res_val -= ((val >> lpc.lpc_quant) *

                            (lpc.lpc_order - index));

                    index--;

                }

            }

            samples++;

        }

    }

}

static void avc_h_loop_filter_luma_mbaff_intra_msa(uint8_t *src,

                                                   int32_t stride,

                                                   int32_t alpha_in,

                                                   int32_t beta_in)

{

    uint64_t load0, load1;

    uint32_t out0, out2;

    uint16_t out1, out3;

    v8u16 src0_r, src1_r, src2_r, src3_r, src4_r, src5_r, src6_r, src7_r;

    v8u16 dst0_r, dst1_r, dst4_r, dst5_r;

    v8u16 dst2_x_r, dst2_y_r, dst3_x_r, dst3_y_r;

    v16u8 dst0, dst1, dst4, dst5, dst2_x, dst2_y, dst3_x, dst3_y;

    v8i16 tmp0, tmp1, tmp2, tmp3;

    v16u8 alpha, beta;

    v16u8 p0_asub_q0, p1_asub_p0, q1_asub_q0, p2_asub_p0, q2_asub_q0;

    v16u8 is_less_than, is_less_than_alpha, is_less_than_beta;

    v16u8 is_less_than_beta1, is_less_than_beta2;

    v16i8 src0 = { 0 };

    v16i8 src1 = { 0 };

    v16i8 src2 = { 0 };

    v16i8 src3 = { 0 };

    v16i8 src4 = { 0 };

    v16i8 src5 = { 0 };

    v16i8 src6 = { 0 };

    v16i8 src7 = { 0 };

    v16i8 zeros = { 0 };



    load0 = LOAD_DWORD(src - 4);

    load1 = LOAD_DWORD(src + stride - 4);

    src0 = (v16i8) __msa_insert_d((v2i64) src0, 0, load0);

    src1 = (v16i8) __msa_insert_d((v2i64) src1, 0, load1);



    load0 = LOAD_DWORD(src + (2 * stride) - 4);

    load1 = LOAD_DWORD(src + (3 * stride) - 4);

    src2 = (v16i8) __msa_insert_d((v2i64) src2, 0, load0);

    src3 = (v16i8) __msa_insert_d((v2i64) src3, 0, load1);



    load0 = LOAD_DWORD(src + (4 * stride) - 4);

    load1 = LOAD_DWORD(src + (5 * stride) - 4);

    src4 = (v16i8) __msa_insert_d((v2i64) src4, 0, load0);

    src5 = (v16i8) __msa_insert_d((v2i64) src5, 0, load1);



    load0 = LOAD_DWORD(src + (6 * stride) - 4);

    load1 = LOAD_DWORD(src + (7 * stride) - 4);

    src6 = (v16i8) __msa_insert_d((v2i64) src6, 0, load0);

    src7 = (v16i8) __msa_insert_d((v2i64) src7, 0, load1);



    src0 = __msa_ilvr_b(src1, src0);

    src1 = __msa_ilvr_b(src3, src2);

    src2 = __msa_ilvr_b(src5, src4);

    src3 = __msa_ilvr_b(src7, src6);

    tmp0 = __msa_ilvr_h((v8i16) src1, (v8i16) src0);

    tmp1 = __msa_ilvl_h((v8i16) src1, (v8i16) src0);

    tmp2 = __msa_ilvr_h((v8i16) src3, (v8i16) src2);

    tmp3 = __msa_ilvl_h((v8i16) src3, (v8i16) src2);

    src6 = (v16i8) __msa_ilvr_w((v4i32) tmp2, (v4i32) tmp0);

    src0 = __msa_sldi_b(zeros, src6, 8);

    src1 = (v16i8) __msa_ilvl_w((v4i32) tmp2, (v4i32) tmp0);

    src2 = __msa_sldi_b(zeros, src1, 8);

    src3 = (v16i8) __msa_ilvr_w((v4i32) tmp3, (v4i32) tmp1);

    src4 = __msa_sldi_b(zeros, src3, 8);

    src5 = (v16i8) __msa_ilvl_w((v4i32) tmp3, (v4i32) tmp1);

    src7 = __msa_sldi_b(zeros, src5, 8);



    p0_asub_q0 = __msa_asub_u_b((v16u8) src2, (v16u8) src3);

    p1_asub_p0 = __msa_asub_u_b((v16u8) src1, (v16u8) src2);

    q1_asub_q0 = __msa_asub_u_b((v16u8) src4, (v16u8) src3);



    alpha = (v16u8) __msa_fill_b(alpha_in);

    beta = (v16u8) __msa_fill_b(beta_in);



    is_less_than_alpha = (p0_asub_q0 < alpha);

    is_less_than_beta = (p1_asub_p0 < beta);

    is_less_than = is_less_than_alpha & is_less_than_beta;

    is_less_than_beta = (q1_asub_q0 < beta);

    is_less_than = is_less_than & is_less_than_beta;



    alpha >>= 2;

    alpha += 2;



    is_less_than_alpha = (p0_asub_q0 < alpha);



    p2_asub_p0 = __msa_asub_u_b((v16u8) src0, (v16u8) src2);

    is_less_than_beta1 = (p2_asub_p0 < beta);

    q2_asub_q0 = __msa_asub_u_b((v16u8) src5, (v16u8) src3);

    is_less_than_beta2 = (q2_asub_q0 < beta);



    src0_r = (v8u16) __msa_ilvr_b(zeros, src0);

    src1_r = (v8u16) __msa_ilvr_b(zeros, src1);

    src2_r = (v8u16) __msa_ilvr_b(zeros, src2);

    src3_r = (v8u16) __msa_ilvr_b(zeros, src3);

    src4_r = (v8u16) __msa_ilvr_b(zeros, src4);

    src5_r = (v8u16) __msa_ilvr_b(zeros, src5);

    src6_r = (v8u16) __msa_ilvr_b(zeros, src6);

    src7_r = (v8u16) __msa_ilvr_b(zeros, src7);



    dst2_x_r = src1_r + src2_r + src3_r;

    dst2_x_r = src0_r + (2 * (dst2_x_r)) + src4_r;

    dst2_x_r = (v8u16) __msa_srari_h((v8i16) dst2_x_r, 3);



    dst1_r = src0_r + src1_r + src2_r + src3_r;

    dst1_r = (v8u16) __msa_srari_h((v8i16) dst1_r, 2);



    dst0_r = (2 * src6_r) + (3 * src0_r);

    dst0_r += src1_r + src2_r + src3_r;

    dst0_r = (v8u16) __msa_srari_h((v8i16) dst0_r, 3);



    dst2_y_r = (2 * src1_r) + src2_r + src4_r;

    dst2_y_r = (v8u16) __msa_srari_h((v8i16) dst2_y_r, 2);



    dst2_x = (v16u8) __msa_pckev_b((v16i8) dst2_x_r, (v16i8) dst2_x_r);

    dst2_y = (v16u8) __msa_pckev_b((v16i8) dst2_y_r, (v16i8) dst2_y_r);

    dst2_x = __msa_bmnz_v(dst2_y, dst2_x, is_less_than_beta1);



    dst3_x_r = src2_r + src3_r + src4_r;

    dst3_x_r = src1_r + (2 * dst3_x_r) + src5_r;

    dst3_x_r = (v8u16) __msa_srari_h((v8i16) dst3_x_r, 3);



    dst4_r = src2_r + src3_r + src4_r + src5_r;

    dst4_r = (v8u16) __msa_srari_h((v8i16) dst4_r, 2);



    dst5_r = (2 * src7_r) + (3 * src5_r);

    dst5_r += src4_r + src3_r + src2_r;

    dst5_r = (v8u16) __msa_srari_h((v8i16) dst5_r, 3);



    dst3_y_r = (2 * src4_r) + src3_r + src1_r;

    dst3_y_r = (v8u16) __msa_srari_h((v8i16) dst3_y_r, 2);

    dst3_x = (v16u8) __msa_pckev_b((v16i8) dst3_x_r, (v16i8) dst3_x_r);

    dst3_y = (v16u8) __msa_pckev_b((v16i8) dst3_y_r, (v16i8) dst3_y_r);

    dst3_x = __msa_bmnz_v(dst3_y, dst3_x, is_less_than_beta2);



    dst2_y_r = (2 * src1_r) + src2_r + src4_r;

    dst2_y_r = (v8u16) __msa_srari_h((v8i16) dst2_y_r, 2);



    dst3_y_r = (2 * src4_r) + src3_r + src1_r;

    dst3_y_r = (v8u16) __msa_srari_h((v8i16) dst3_y_r, 2);



    dst2_y = (v16u8) __msa_pckev_b((v16i8) dst2_y_r, (v16i8) dst2_y_r);

    dst3_y = (v16u8) __msa_pckev_b((v16i8) dst3_y_r, (v16i8) dst3_y_r);

    dst2_x = __msa_bmnz_v(dst2_y, dst2_x, is_less_than_alpha);

    dst3_x = __msa_bmnz_v(dst3_y, dst3_x, is_less_than_alpha);

    dst2_x = __msa_bmnz_v((v16u8) src2, dst2_x, is_less_than);

    dst3_x = __msa_bmnz_v((v16u8) src3, dst3_x, is_less_than);



    is_less_than = is_less_than_alpha & is_less_than;

    dst1 = (v16u8) __msa_pckev_b((v16i8) dst1_r, (v16i8) dst1_r);

    is_less_than_beta1 = is_less_than_beta1 & is_less_than;

    dst1 = __msa_bmnz_v((v16u8) src1, dst1, is_less_than_beta1);



    dst0 = (v16u8) __msa_pckev_b((v16i8) dst0_r, (v16i8) dst0_r);

    dst0 = __msa_bmnz_v((v16u8) src0, dst0, is_less_than_beta1);



    dst4 = (v16u8) __msa_pckev_b((v16i8) dst4_r, (v16i8) dst4_r);

    is_less_than_beta2 = is_less_than_beta2 & is_less_than;

    dst4 = __msa_bmnz_v((v16u8) src4, dst4, is_less_than_beta2);



    dst5 = (v16u8) __msa_pckev_b((v16i8) dst5_r, (v16i8) dst5_r);

    dst5 = __msa_bmnz_v((v16u8) src5, dst5, is_less_than_beta2);



    dst0 = (v16u8) __msa_ilvr_b((v16i8) dst1, (v16i8) dst0);

    dst1 = (v16u8) __msa_ilvr_b((v16i8) dst3_x, (v16i8) dst2_x);

    dst2_x = (v16u8) __msa_ilvr_b((v16i8) dst5, (v16i8) dst4);

    tmp0 = __msa_ilvr_h((v8i16) dst1, (v8i16) dst0);

    tmp1 = __msa_ilvl_h((v8i16) dst1, (v8i16) dst0);

    tmp2 = __msa_ilvr_h((v8i16) zeros, (v8i16) dst2_x);

    tmp3 = __msa_ilvl_h((v8i16) zeros, (v8i16) dst2_x);

    dst0 = (v16u8) __msa_ilvr_w((v4i32) tmp2, (v4i32) tmp0);

    dst1 = (v16u8) __msa_sldi_b(zeros, (v16i8) dst0, 8);

    dst2_x = (v16u8) __msa_ilvl_w((v4i32) tmp2, (v4i32) tmp0);

    dst3_x = (v16u8) __msa_sldi_b(zeros, (v16i8) dst2_x, 8);

    dst4 = (v16u8) __msa_ilvr_w((v4i32) tmp3, (v4i32) tmp1);

    dst5 = (v16u8) __msa_sldi_b(zeros, (v16i8) dst4, 8);

    dst2_y = (v16u8) __msa_ilvl_w((v4i32) tmp3, (v4i32) tmp1);

    dst3_y = (v16u8) __msa_sldi_b(zeros, (v16i8) dst2_y, 8);



    out0 = __msa_copy_u_w((v4i32) dst0, 0);

    out1 = __msa_copy_u_h((v8i16) dst0, 2);

    out2 = __msa_copy_u_w((v4i32) dst1, 0);

    out3 = __msa_copy_u_h((v8i16) dst1, 2);



    STORE_WORD((src - 3), out0);

    STORE_HWORD((src + 1), out1);

    src += stride;

    STORE_WORD((src - 3), out2);

    STORE_HWORD((src + 1), out3);

    src += stride;



    out0 = __msa_copy_u_w((v4i32) dst2_x, 0);

    out1 = __msa_copy_u_h((v8i16) dst2_x, 2);

    out2 = __msa_copy_u_w((v4i32) dst3_x, 0);

    out3 = __msa_copy_u_h((v8i16) dst3_x, 2);



    STORE_WORD((src - 3), out0);

    STORE_HWORD((src + 1), out1);

    src += stride;

    STORE_WORD((src - 3), out2);

    STORE_HWORD((src + 1), out3);

    src += stride;



    out0 = __msa_copy_u_w((v4i32) dst4, 0);

    out1 = __msa_copy_u_h((v8i16) dst4, 2);

    out2 = __msa_copy_u_w((v4i32) dst5, 0);

    out3 = __msa_copy_u_h((v8i16) dst5, 2);



    STORE_WORD((src - 3), out0);

    STORE_HWORD((src + 1), out1);

    src += stride;

    STORE_WORD((src - 3), out2);

    STORE_HWORD((src + 1), out3);

    src += stride;



    out0 = __msa_copy_u_w((v4i32) dst2_y, 0);

    out1 = __msa_copy_u_h((v8i16) dst2_y, 2);

    out2 = __msa_copy_u_w((v4i32) dst3_y, 0);

    out3 = __msa_copy_u_h((v8i16) dst3_y, 2);



    STORE_WORD((src - 3), out0);

    STORE_HWORD((src + 1), out1);

    src += stride;

    STORE_WORD((src - 3), out2);

    STORE_HWORD((src + 1), out3);

}

static int ac3_decode_frame(AVCodecContext * avctx, void *data, int *data_size, uint8_t * buf, int buf_size)

{

    AC3DecodeContext *ctx = avctx->priv_data;

    int frame_start;

    int i, j, k, l;

    float tmp0[128], tmp1[128], tmp[512];

    short *out_samples = (short *)data;

    float *samples = ctx->samples;



    //Synchronize the frame.

    frame_start = ac3_synchronize(buf, buf_size);

    if (frame_start == -1) {

        av_log(avctx, AV_LOG_ERROR, "frame is not synchronized\n");

        *data_size = 0;

        return -1;

    }



    //Initialize the GetBitContext with the start of valid AC3 Frame.

    init_get_bits(&(ctx->gb), buf + frame_start, (buf_size - frame_start) * 8);

    //Parse the syncinfo.

    ////If 'fscod' is not valid the decoder shall mute as per the standard.

    if (ac3_parse_sync_info(ctx)) {

        av_log(avctx, AV_LOG_ERROR, "fscod is not valid\n");

        *data_size = 0;

        return -1;

    }



    //Check for the errors.

    /* if (ac3_error_check(ctx)) {

        *data_size = 0;

        return -1;

    } */



    //Parse the BSI.

    //If 'bsid' is not valid decoder shall not decode the audio as per the standard.

    if (ac3_parse_bsi(ctx)) {

        av_log(avctx, AV_LOG_ERROR, "bsid is not valid\n");

        *data_size = 0;

        return -1;

    }



    avctx->sample_rate = ctx->sync_info.sampling_rate;

    if (avctx->channels == 0) {

        avctx->channels = ctx->bsi.nfchans + ((ctx->bsi.flags & AC3_BSI_LFEON) ? 1 : 0);

        ctx->output = AC3_OUTPUT_UNMODIFIED;

    }

    else if ((ctx->bsi.nfchans + ((ctx->bsi.flags & AC3_BSI_LFEON) ? 1 : 0)) < avctx->channels) {

        av_log(avctx, AV_LOG_INFO, "ac3_decoder: AC3 Source Channels Are Less Then Specified %d: Output to %d Channels\n",

                avctx->channels, (ctx->bsi.nfchans + ((ctx->bsi.flags & AC3_BSI_LFEON) ? 1 : 0)));

        avctx->channels = ctx->bsi.nfchans + ((ctx->bsi.flags & AC3_BSI_LFEON) ? 1 : 0);

        ctx->output = AC3_OUTPUT_UNMODIFIED;

    }

    else if (avctx->channels == 1) {

        ctx->output = AC3_OUTPUT_MONO;

    } else if (avctx->channels == 2) {

        if (ctx->bsi.dsurmod == 0x02)

            ctx->output = AC3_OUTPUT_DOLBY;

        else

            ctx->output = AC3_OUTPUT_STEREO;

    }





    avctx->bit_rate = ctx->sync_info.bit_rate;

    av_log(avctx, AV_LOG_INFO, "channels = %d \t bit rate = %d \t sampling rate = %d \n", avctx->channels, avctx->sample_rate, avctx->bit_rate);



    //Parse the Audio Blocks.

    for (i = 0; i < 6; i++) {

        if (ac3_parse_audio_block(ctx, i)) {

            av_log(avctx, AV_LOG_ERROR, "error parsing the audio block\n");

            *data_size = 0;

            return -1;

        }

        samples = ctx->samples;

        if (ctx->bsi.flags & AC3_BSI_LFEON) {

            ff_imdct_calc(&ctx->imdct_ctx_512, ctx->samples + 1536, samples, tmp);

            for (l = 0; l < 256; l++)

                samples[l] = (ctx->samples + 1536)[l];

            float_to_int(samples, out_samples, 256);

            samples += 256;

            out_samples += 256;

        }

        for (j = 0; j < ctx->bsi.nfchans; j++) {

            if (ctx->audio_block.blksw & (1 << j)) {

                for (k = 0; k < 128; k++) {

                    tmp0[k] = samples[2 * k];

                    tmp1[k] = samples[2 * k + 1];

                }

                ff_imdct_calc(&ctx->imdct_ctx_256, ctx->samples + 1536, tmp0, tmp);

                for (l = 0; l < 256; l++)

                    samples[l] = (ctx->samples + 1536)[l] * window[l] + (ctx->samples + 2048)[l] * window[255 - l];

                ff_imdct_calc(&ctx->imdct_ctx_256, ctx->samples + 2048, tmp1, tmp);

                float_to_int(samples, out_samples, 256);

                samples += 256;

                out_samples += 256;

            }

            else {

                ff_imdct_calc(&ctx->imdct_ctx_512, ctx->samples + 1536, samples, tmp);

                for (l = 0; l < 256; l++)

                    samples[l] = (ctx->samples + 1536)[l] * window[l] + (ctx->samples + 2048)[l] * window[255 - l];

                float_to_int(samples, out_samples, 256);

                memcpy(ctx->samples + 2048, ctx->samples + 1792, 256 * sizeof (float));

                samples += 256;

                out_samples += 256;

            }

        }

    }

    *data_size = 6 * ctx->bsi.nfchans * 256 * sizeof (int16_t);



    return (buf_size - frame_start);

}

static int mkv_check_tag(AVDictionary *m)

{

    AVDictionaryEntry *t = NULL;



    while ((t = av_dict_get(m, "", t, AV_DICT_IGNORE_SUFFIX)))

        if (av_strcasecmp(t->key, "title") && av_strcasecmp(t->key, "stereo_mode"))

            return 1;



    return 0;

}

static char *sysbus_get_fw_dev_path(DeviceState *dev)

{

    SysBusDevice *s = SYS_BUS_DEVICE(dev);

    char path[40];

    int off;



    off = snprintf(path, sizeof(path), "%s", qdev_fw_name(dev));



    if (s->num_mmio) {

        snprintf(path + off, sizeof(path) - off, "@"TARGET_FMT_plx,

                 s->mmio[0].addr);

    } else if (s->num_pio) {

        snprintf(path + off, sizeof(path) - off, "@i%04x", s->pio[0]);

    }



    return g_strdup(path);

}

static int mov_read_cmov(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

#if CONFIG_ZLIB

    AVIOContext ctx;

    uint8_t *cmov_data;

    uint8_t *moov_data; /* uncompressed data */

    long cmov_len, moov_len;

    int ret = -1;



    avio_rb32(pb); /* dcom atom */

    if (avio_rl32(pb) != MKTAG('d','c','o','m'))

        return AVERROR_INVALIDDATA;

    if (avio_rl32(pb) != MKTAG('z','l','i','b')) {

        av_log(c->fc, AV_LOG_ERROR, "unknown compression for cmov atom !");

        return AVERROR_INVALIDDATA;

    }

    avio_rb32(pb); /* cmvd atom */

    if (avio_rl32(pb) != MKTAG('c','m','v','d'))

        return AVERROR_INVALIDDATA;

    moov_len = avio_rb32(pb); /* uncompressed size */

    cmov_len = atom.size - 6 * 4;



    cmov_data = av_malloc(cmov_len);

    if (!cmov_data)

        return AVERROR(ENOMEM);

    moov_data = av_malloc(moov_len);

    if (!moov_data) {

        av_free(cmov_data);

        return AVERROR(ENOMEM);

    }

    avio_read(pb, cmov_data, cmov_len);

    if (uncompress (moov_data, (uLongf *) &moov_len, (const Bytef *)cmov_data, cmov_len) != Z_OK)

        goto free_and_return;

    if (ffio_init_context(&ctx, moov_data, moov_len, 0, NULL, NULL, NULL, NULL) != 0)

        goto free_and_return;

    atom.type = MKTAG('m','o','o','v');

    atom.size = moov_len;

    ret = mov_read_default(c, &ctx, atom);

free_and_return:

    av_free(moov_data);

    av_free(cmov_data);

    return ret;

#else

    av_log(c->fc, AV_LOG_ERROR, "this file requires zlib support compiled in\n");

    return AVERROR(ENOSYS);

#endif

}

writev_f(int argc, char **argv)

{

	struct timeval t1, t2;

	int Cflag = 0, qflag = 0;

	int c, cnt;

	char *buf;

	int64_t offset;

	int total;

	int nr_iov;

	int pattern = 0xcd;

	QEMUIOVector qiov;



	while ((c = getopt(argc, argv, "CqP:")) != EOF) {

		switch (c) {

		case 'C':

			Cflag = 1;

			break;

		case 'q':

			qflag = 1;

			break;

		case 'P':

			pattern = atoi(optarg);

			break;

		default:

			return command_usage(&writev_cmd);

		}

	}



	if (optind > argc - 2)

		return command_usage(&writev_cmd);



	offset = cvtnum(argv[optind]);

	if (offset < 0) {

		printf("non-numeric length argument -- %s\n", argv[optind]);

		return 0;

	}

	optind++;



	if (offset & 0x1ff) {

		printf("offset %lld is not sector aligned\n",

			(long long)offset);

		return 0;

	}



	nr_iov = argc - optind;

	buf = create_iovec(&qiov, &argv[optind], nr_iov, pattern);



	gettimeofday(&t1, NULL);

	cnt = do_aio_writev(&qiov, offset, &total);

	gettimeofday(&t2, NULL);



	if (cnt < 0) {

		printf("writev failed: %s\n", strerror(-cnt));

		goto out;

	}



	if (qflag)

		goto out;



	/* Finally, report back -- -C gives a parsable format */

	t2 = tsub(t2, t1);

	print_report("wrote", &t2, offset, qiov.size, total, cnt, Cflag);

out:

	qemu_io_free(buf);

	return 0;

}

long do_rt_sigreturn(CPUS390XState *env)

{

    rt_sigframe *frame;

    abi_ulong frame_addr = env->regs[15];

    qemu_log("%s: frame_addr 0x%llx\n", __FUNCTION__,

             (unsigned long long)frame_addr);

    sigset_t set;



    if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1)) {

        goto badframe;

    }

    target_to_host_sigset(&set, &frame->uc.tuc_sigmask);



    sigprocmask(SIG_SETMASK, &set, NULL); /* ~_BLOCKABLE? */



    if (restore_sigregs(env, &frame->uc.tuc_mcontext)) {

        goto badframe;

    }



    if (do_sigaltstack(frame_addr + offsetof(rt_sigframe, uc.tuc_stack), 0,

                       get_sp_from_cpustate(env)) == -EFAULT) {

        goto badframe;

    }

    unlock_user_struct(frame, frame_addr, 0);

    return env->regs[2];



badframe:

    unlock_user_struct(frame, frame_addr, 0);

    force_sig(TARGET_SIGSEGV);

    return 0;

}

static DeviceState *qbus_find_dev(BusState *bus, char *elem)

{

    DeviceState *dev;



    /*

     * try to match in order:

     *   (1) instance id, if present

     *   (2) driver name

     *   (3) driver alias, if present

     */

    LIST_FOREACH(dev, &bus->children, sibling) {

        if (dev->id  &&  strcmp(dev->id, elem) == 0) {

            return dev;

        }

    }

    LIST_FOREACH(dev, &bus->children, sibling) {

        if (strcmp(dev->info->name, elem) == 0) {

            return dev;

        }

    }

    LIST_FOREACH(dev, &bus->children, sibling) {

        if (dev->info->alias && strcmp(dev->info->alias, elem) == 0) {

            return dev;

        }

    }

    return NULL;

}

int av_lockmgr_register(int (*cb)(void **mutex, enum AVLockOp op))

{

    if (lockmgr_cb) {

        // There is no good way to rollback a failure to destroy the

        // mutex, so we ignore failures.

        lockmgr_cb(&codec_mutex,    AV_LOCK_DESTROY);

        lockmgr_cb(&avformat_mutex, AV_LOCK_DESTROY);

        lockmgr_cb     = NULL;

        codec_mutex    = NULL;

        avformat_mutex = NULL;

    }



    if (cb) {

        void *new_codec_mutex    = NULL;

        void *new_avformat_mutex = NULL;

        int err;

        if (err = cb(&new_codec_mutex, AV_LOCK_CREATE)) {

            return err > 0 ? AVERROR_UNKNOWN : err;

        }

        if (err = cb(&new_avformat_mutex, AV_LOCK_CREATE)) {

            // Ignore failures to destroy the newly created mutex.

            cb(&new_codec_mutex, AV_LOCK_DESTROY);

            return err > 0 ? AVERROR_UNKNOWN : err;

        }

        lockmgr_cb     = cb;

        codec_mutex    = new_codec_mutex;

        avformat_mutex = new_avformat_mutex;

    }



    return 0;

}

