}

MKSCALE16(scale16be, AV_RB16, AV_WB16)

MKSCALE16(scale16le, AV_RL16, AV_WL16)



static int raw_decode(AVCodecContext *avctx, void *data, int *got_frame,

                      AVPacket *avpkt)

{

    const AVPixFmtDescriptor *desc;

    RawVideoContext *context       = avctx->priv_data;

    const uint8_t *buf             = avpkt->data;

    int buf_size                   = avpkt->size;

    int linesize_align             = 4;

    int stride;

    int res, len;

    int need_copy;



    AVFrame   *frame   = data;



    if (avctx->width <= 0) {

        av_log(avctx, AV_LOG_ERROR, "width is not set\n");

        return AVERROR_INVALIDDATA;

    }

    if (avctx->height <= 0) {

        av_log(avctx, AV_LOG_ERROR, "height is not set\n");

        return AVERROR_INVALIDDATA;

    }



    if (context->is_nut_mono)

        stride = avctx->width / 8 + (avctx->width & 7 ? 1 : 0);

    else if (context->is_nut_pal8)

        stride = avctx->width;

    else

        stride = avpkt->size / avctx->height;



    av_log(avctx, AV_LOG_DEBUG, "PACKET SIZE: %d, STRIDE: %d\n", avpkt->size, stride);



    if (stride == 0 || avpkt->size < stride * avctx->height) {

        av_log(avctx, AV_LOG_ERROR, "Packet too small (%d)\n", avpkt->size);

        return AVERROR_INVALIDDATA;

    }



    desc = av_pix_fmt_desc_get(avctx->pix_fmt);



    if ((avctx->bits_per_coded_sample == 8 || avctx->bits_per_coded_sample == 4 ||

         avctx->bits_per_coded_sample == 2 || avctx->bits_per_coded_sample == 1 ||

         (avctx->bits_per_coded_sample == 0 && (context->is_nut_pal8 || context->is_mono)) ) &&

        (context->is_mono || context->is_pal8) &&

        (!avctx->codec_tag || avctx->codec_tag == MKTAG('r','a','w',' ') ||

                context->is_nut_mono || context->is_nut_pal8)) {

        context->is_1_2_4_8_bpp = 1;

        if (context->is_mono) {

            int row_bytes = avctx->width / 8 + (avctx->width & 7 ? 1 : 0);

            context->frame_size = av_image_get_buffer_size(avctx->pix_fmt,

                                                           FFALIGN(row_bytes, 16) * 8,

                                                           avctx->height, 1);

        } else

            context->frame_size = av_image_get_buffer_size(avctx->pix_fmt,

                                                           FFALIGN(avctx->width, 16),

                                                           avctx->height, 1);

    } else {

        context->is_lt_16bpp = av_get_bits_per_pixel(desc) == 16 && avctx->bits_per_coded_sample && avctx->bits_per_coded_sample < 16;

        context->frame_size = av_image_get_buffer_size(avctx->pix_fmt, avctx->width,

                                                       avctx->height, 1);

    }

    if (context->frame_size < 0)

        return context->frame_size;



    need_copy = !avpkt->buf || context->is_1_2_4_8_bpp || context->is_yuv2 || context->is_lt_16bpp;



    frame->pict_type        = AV_PICTURE_TYPE_I;

    frame->key_frame        = 1;



    res = ff_decode_frame_props(avctx, frame);

    if (res < 0)

        return res;



    av_frame_set_pkt_pos     (frame, avctx->internal->pkt->pos);

    av_frame_set_pkt_duration(frame, avctx->internal->pkt->duration);



    if (context->tff >= 0) {

        frame->interlaced_frame = 1;

        frame->top_field_first  = context->tff;

    }



    if ((res = av_image_check_size(avctx->width, avctx->height, 0, avctx)) < 0)

        return res;



    if (need_copy)

        frame->buf[0] = av_buffer_alloc(FFMAX(context->frame_size, buf_size));

    else

        frame->buf[0] = av_buffer_ref(avpkt->buf);

    if (!frame->buf[0])

        return AVERROR(ENOMEM);



    // 1, 2, 4 and 8 bpp in avi/mov, 1 and 8 bpp in nut

    if (context->is_1_2_4_8_bpp) {

        int i, j, row_pix = 0;

        uint8_t *dst = frame->buf[0]->data;

        buf_size = context->frame_size - (context->is_pal8 ? AVPALETTE_SIZE : 0);

        if (avctx->bits_per_coded_sample == 8 || context->is_nut_pal8 || context->is_mono) {

            int pix_per_byte = context->is_mono ? 8 : 1;

            for (i = 0, j = 0; j < buf_size && i<avpkt->size; i++, j++) {

                dst[j] = buf[i];

                row_pix += pix_per_byte;

                if (row_pix >= avctx->width) {

                    i += stride - (i % stride) - 1;

                    j += 16 - (j % 16) - 1;

                    row_pix = 0;

                }

            }

        } else if (avctx->bits_per_coded_sample == 4) {

            for (i = 0, j = 0; 2 * j + 1 < buf_size && i<avpkt->size; i++, j++) {

                dst[2 * j + 0] = buf[i] >> 4;

                dst[2 * j + 1] = buf[i] & 15;

                row_pix += 2;

                if (row_pix >= avctx->width) {

                    i += stride - (i % stride) - 1;

                    j += 8 - (j % 8) - 1;

                    row_pix = 0;

                }

            }

        } else if (avctx->bits_per_coded_sample == 2) {

            for (i = 0, j = 0; 4 * j + 3 < buf_size && i<avpkt->size; i++, j++) {

                dst[4 * j + 0] = buf[i] >> 6;

                dst[4 * j + 1] = buf[i] >> 4 & 3;

                dst[4 * j + 2] = buf[i] >> 2 & 3;

                dst[4 * j + 3] = buf[i]      & 3;

                row_pix += 4;

                if (row_pix >= avctx->width) {

                    i += stride - (i % stride) - 1;

                    j += 4 - (j % 4) - 1;

                    row_pix = 0;

                }

            }

        } else {

            av_assert0(avctx->bits_per_coded_sample == 1);

            for (i = 0, j = 0; 8 * j + 7 < buf_size && i<avpkt->size; i++, j++) {

                dst[8 * j + 0] = buf[i] >> 7;

                dst[8 * j + 1] = buf[i] >> 6 & 1;

                dst[8 * j + 2] = buf[i] >> 5 & 1;

                dst[8 * j + 3] = buf[i] >> 4 & 1;

                dst[8 * j + 4] = buf[i] >> 3 & 1;

                dst[8 * j + 5] = buf[i] >> 2 & 1;

                dst[8 * j + 6] = buf[i] >> 1 & 1;

                dst[8 * j + 7] = buf[i]      & 1;

                row_pix += 8;

                if (row_pix >= avctx->width) {

                    i += stride - (i % stride) - 1;

                    j += 2 - (j % 2) - 1;

                    row_pix = 0;

                }

            }

        }

        linesize_align = 16;

        buf = dst;

    } else if (context->is_lt_16bpp) {

        uint8_t *dst = frame->buf[0]->data;

        int packed = (avctx->codec_tag & 0xFFFFFF) == MKTAG('B','I','T', 0);

        int swap   =  avctx->codec_tag >> 24;



        if (packed && swap) {

            av_fast_padded_malloc(&context->bitstream_buf, &context->bitstream_buf_size, buf_size);

            if (!context->bitstream_buf)

                return AVERROR(ENOMEM);

            if (swap == 16)

                context->bbdsp.bswap16_buf(context->bitstream_buf, (const uint16_t*)buf, buf_size / 2);

            else if (swap == 32)

                context->bbdsp.bswap_buf(context->bitstream_buf, (const uint32_t*)buf, buf_size / 4);

            else

                return AVERROR_INVALIDDATA;

            buf = context->bitstream_buf;

        }



        if (desc->flags & AV_PIX_FMT_FLAG_BE)

            scale16be(avctx, dst, buf, buf_size, packed);

        else

            scale16le(avctx, dst, buf, buf_size, packed);



        buf = dst;

    } else if (need_copy) {

        memcpy(frame->buf[0]->data, buf, buf_size);

        buf = frame->buf[0]->data;

    }



    if (avctx->codec_tag == MKTAG('A', 'V', '1', 'x') ||

        avctx->codec_tag == MKTAG('A', 'V', 'u', 'p'))

        buf += buf_size - context->frame_size;



    len = context->frame_size - (avctx->pix_fmt==AV_PIX_FMT_PAL8 ? AVPALETTE_SIZE : 0);

    if (buf_size < len && ((avctx->codec_tag & 0xFFFFFF) != MKTAG('B','I','T', 0) || !need_copy)) {

        av_log(avctx, AV_LOG_ERROR, "Invalid buffer size, packet size %d < expected frame_size %d\n", buf_size, len);

        av_buffer_unref(&frame->buf[0]);

        return AVERROR(EINVAL);

    }



    if ((res = av_image_fill_arrays(frame->data, frame->linesize,

                                    buf, avctx->pix_fmt,

                                    avctx->width, avctx->height, 1)) < 0) {

        av_buffer_unref(&frame->buf[0]);

        return res;

    }



    if (avctx->pix_fmt == AV_PIX_FMT_PAL8) {

        const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE,

                                                     NULL);

        int ret;

        if (!context->palette)

            context->palette = av_buffer_alloc(AVPALETTE_SIZE);

        if (!context->palette) {

            av_buffer_unref(&frame->buf[0]);

            return AVERROR(ENOMEM);

        }

        ret = av_buffer_make_writable(&context->palette);

        if (ret < 0) {

            av_buffer_unref(&frame->buf[0]);

            return ret;

        }



        if (pal) {

            memcpy(context->palette->data, pal, AVPALETTE_SIZE);

            frame->palette_has_changed = 1;

        } else if (context->is_nut_pal8) {

            int vid_size = avctx->width * avctx->height;

            int pal_size = avpkt->size - vid_size;



            if (avpkt->size > vid_size && pal_size <= AVPALETTE_SIZE) {

                pal = avpkt->data + vid_size;

                memcpy(context->palette->data, pal, pal_size);

                frame->palette_has_changed = 1;

            }

        }

    }



    if ((avctx->pix_fmt==AV_PIX_FMT_RGB24    ||

        avctx->pix_fmt==AV_PIX_FMT_BGR24     ||

        avctx->pix_fmt==AV_PIX_FMT_GRAY8     ||

        avctx->pix_fmt==AV_PIX_FMT_RGB555LE  ||

        avctx->pix_fmt==AV_PIX_FMT_RGB555BE  ||

        avctx->pix_fmt==AV_PIX_FMT_RGB565LE  ||

        avctx->pix_fmt==AV_PIX_FMT_MONOWHITE ||

        avctx->pix_fmt==AV_PIX_FMT_MONOBLACK ||

        avctx->pix_fmt==AV_PIX_FMT_PAL8) &&

        FFALIGN(frame->linesize[0], linesize_align) * avctx->height <= buf_size)

        frame->linesize[0] = FFALIGN(frame->linesize[0], linesize_align);



    if (avctx->pix_fmt == AV_PIX_FMT_NV12 && avctx->codec_tag == MKTAG('N', 'V', '1', '2') &&

        FFALIGN(frame->linesize[0], linesize_align) * avctx->height +

        FFALIGN(frame->linesize[1], linesize_align) * ((avctx->height + 1) / 2) <= buf_size) {

        int la0 = FFALIGN(frame->linesize[0], linesize_align);

        frame->data[1] += (la0 - frame->linesize[0]) * avctx->height;

        frame->linesize[0] = la0;

        frame->linesize[1] = FFALIGN(frame->linesize[1], linesize_align);

    }



    if ((avctx->pix_fmt == AV_PIX_FMT_PAL8 && buf_size < context->frame_size) ||

        (desc->flags & AV_PIX_FMT_FLAG_PSEUDOPAL)) {

        frame->buf[1]  = av_buffer_ref(context->palette);

        if (!frame->buf[1]) {

            av_buffer_unref(&frame->buf[0]);

            return AVERROR(ENOMEM);

        }

        frame->data[1] = frame->buf[1]->data;

    }



    if (avctx->pix_fmt == AV_PIX_FMT_BGR24 &&

        ((frame->linesize[0] + 3) & ~3) * avctx->height <= buf_size)

        frame->linesize[0] = (frame->linesize[0] + 3) & ~3;



    if (context->flip)

        flip(avctx, frame);



    if (avctx->codec_tag == MKTAG('Y', 'V', '1', '2') ||

        avctx->codec_tag == MKTAG('Y', 'V', '1', '6') ||

        avctx->codec_tag == MKTAG('Y', 'V', '2', '4') ||

        avctx->codec_tag == MKTAG('Y', 'V', 'U', '9'))

        FFSWAP(uint8_t *, frame->data[1], frame->data[2]);



    if (avctx->codec_tag == AV_RL32("I420") && (avctx->width+1)*(avctx->height+1) * 3/2 == buf_size) {

        frame->data[1] = frame->data[1] +  (avctx->width+1)*(avctx->height+1) -avctx->width*avctx->height;

        frame->data[2] = frame->data[2] + ((avctx->width+1)*(avctx->height+1) -avctx->width*avctx->height)*5/4;

    }



    if (avctx->codec_tag == AV_RL32("yuv2") &&

        avctx->pix_fmt   == AV_PIX_FMT_YUYV422) {

        int x, y;

        uint8_t *line = frame->data[0];

        for (y = 0; y < avctx->height; y++) {

            for (x = 0; x < avctx->width; x++)

                line[2 * x + 1] ^= 0x80;

            line += frame->linesize[0];

        }

    }



    if (avctx->codec_tag == AV_RL32("b64a") &&

        avctx->pix_fmt   == AV_PIX_FMT_RGBA64BE) {

        uint8_t *dst = frame->data[0];

        uint64_t v;

        int x;

        for (x = 0; x >> 3 < avctx->width * avctx->height; x += 8) {

            v = AV_RB64(&dst[x]);

            AV_WB64(&dst[x], v << 16 | v >> 48);

        }

    }



    if (avctx->field_order > AV_FIELD_PROGRESSIVE) { /* we have interlaced material flagged in container */

        frame->interlaced_frame = 1;

        if (avctx->field_order == AV_FIELD_TT || avctx->field_order == AV_FIELD_TB)

            frame->top_field_first = 1;

    }



    *got_frame = 1;

    return buf_size;

}

static void test_qemu_strtosz_simple(void)

{

    const char *str;

    char *endptr = NULL;

    int64_t res;



    str = "0";

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 0);

    g_assert(endptr == str + 1);



    str = "12345";

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 12345);

    g_assert(endptr == str + 5);



    res = qemu_strtosz(str, NULL);

    g_assert_cmpint(res, ==, 12345);



    /* Note: precision is 53 bits since we're parsing with strtod() */



    str = "9007199254740991"; /* 2^53-1 */

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 0x1fffffffffffff);

    g_assert(endptr == str + 16);



    str = "9007199254740992"; /* 2^53 */

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 0x20000000000000);

    g_assert(endptr == str + 16);



    str = "9007199254740993"; /* 2^53+1 */

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 0x20000000000000); /* rounded to 53 bits */

    g_assert(endptr == str + 16);



    str = "9223372036854774784"; /* 0x7ffffffffffffc00 (53 msbs set) */

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 0x7ffffffffffffc00);

    g_assert(endptr == str + 19);



    str = "9223372036854775295"; /* 0x7ffffffffffffdff */

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 0x7ffffffffffffc00); /* rounded to 53 bits */

    g_assert(endptr == str + 19);



    /* 0x7ffffffffffffe00..0x7fffffffffffffff get rounded to

     * 0x8000000000000000, thus -ERANGE; see test_qemu_strtosz_erange() */

}

static int dpcm_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    const uint8_t *buf_end = buf + buf_size;

    DPCMContext *s = avctx->priv_data;

    int out = 0, ret;

    int predictor[2];

    int ch = 0;

    int stereo = s->channels - 1;

    int16_t *output_samples;



    /* calculate output size */

    switch(avctx->codec->id) {

    case CODEC_ID_ROQ_DPCM:

        out = buf_size - 8;

        break;

    case CODEC_ID_INTERPLAY_DPCM:

        out = buf_size - 6 - s->channels;

        break;

    case CODEC_ID_XAN_DPCM:

        out = buf_size - 2 * s->channels;

        break;

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3)

            out = buf_size * 2;

        else

            out = buf_size;

        break;

    }

    if (out <= 0) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    s->frame.nb_samples = out / s->channels;

    if ((ret = avctx->get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    output_samples = (int16_t *)s->frame.data[0];



    switch(avctx->codec->id) {



    case CODEC_ID_ROQ_DPCM:

        buf += 6;



        if (stereo) {

            predictor[1] = (int16_t)(bytestream_get_byte(&buf) << 8);

            predictor[0] = (int16_t)(bytestream_get_byte(&buf) << 8);

        } else {

            predictor[0] = (int16_t)bytestream_get_le16(&buf);

        }



        /* decode the samples */

        while (buf < buf_end) {

            predictor[ch] += s->roq_square_array[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_INTERPLAY_DPCM:

        buf += 6;  /* skip over the stream mask and stream length */



        for (ch = 0; ch < s->channels; ch++) {

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);

            *output_samples++ = predictor[ch];

        }



        ch = 0;

        while (buf < buf_end) {

            predictor[ch] += interplay_delta_table[*buf++];

            predictor[ch]  = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;



    case CODEC_ID_XAN_DPCM:

    {

        int shift[2] = { 4, 4 };



        for (ch = 0; ch < s->channels; ch++)

            predictor[ch] = (int16_t)bytestream_get_le16(&buf);



        ch = 0;

        while (buf < buf_end) {

            uint8_t n = *buf++;

            int16_t diff = (n & 0xFC) << 8;

            if ((n & 0x03) == 3)

                shift[ch]++;

            else

                shift[ch] -= (2 * (n & 3));

            /* saturate the shifter to a lower limit of 0 */

            if (shift[ch] < 0)

                shift[ch] = 0;



            diff >>= shift[ch];

            predictor[ch] += diff;



            predictor[ch] = av_clip_int16(predictor[ch]);

            *output_samples++ = predictor[ch];



            /* toggle channel */

            ch ^= stereo;

        }

        break;

    }

    case CODEC_ID_SOL_DPCM:

        if (avctx->codec_tag != 3) {

            uint8_t *output_samples_u8 = data;

            while (buf < buf_end) {

                uint8_t n = *buf++;



                s->sample[0] += s->sol_table[n >> 4];

                s->sample[0]  = av_clip_uint8(s->sample[0]);

                *output_samples_u8++ = s->sample[0];



                s->sample[stereo] += s->sol_table[n & 0x0F];

                s->sample[stereo]  = av_clip_uint8(s->sample[stereo]);

                *output_samples_u8++ = s->sample[stereo];

            }

        } else {

            while (buf < buf_end) {

                uint8_t n = *buf++;

                if (n & 0x80) s->sample[ch] -= sol_table_16[n & 0x7F];

                else          s->sample[ch] += sol_table_16[n & 0x7F];

                s->sample[ch] = av_clip_int16(s->sample[ch]);

                *output_samples++ = s->sample[ch];

                /* toggle channel */

                ch ^= stereo;

            }

        }

        break;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return buf_size;

}

void hmp_change(Monitor *mon, const QDict *qdict)

{

    const char *device = qdict_get_str(qdict, "device");

    const char *target = qdict_get_str(qdict, "target");

    const char *arg = qdict_get_try_str(qdict, "arg");

    Error *err = NULL;



    if (strcmp(device, "vnc") == 0 &&

            (strcmp(target, "passwd") == 0 ||

             strcmp(target, "password") == 0)) {

        if (!arg) {

            monitor_read_password(mon, hmp_change_read_arg, NULL);

            return;

        }

    }



    qmp_change(device, target, !!arg, arg, &err);

    if (error_is_type(err, QERR_DEVICE_ENCRYPTED)) {

        monitor_printf(mon, "%s (%s) is encrypted.\n",

                       error_get_field(err, "device"),

                       error_get_field(err, "filename"));

        if (!monitor_get_rs(mon)) {

            monitor_printf(mon,

                    "terminal does not support password prompting\n");

            error_free(err);

            return;

        }

        readline_start(monitor_get_rs(mon), "Password: ", 1,

                       cb_hmp_change_bdrv_pwd, err);

        return;

    }

    hmp_handle_error(mon, &err);

}

static int pci_bridge_initfn(PCIDevice *dev)

{

    PCIBridge *s = DO_UPCAST(PCIBridge, dev, dev);



    pci_config_set_vendor_id(s->dev.config, s->vid);

    pci_config_set_device_id(s->dev.config, s->did);



    s->dev.config[0x04] = 0x06; // command = bus master, pci mem

    s->dev.config[0x05] = 0x00;

    s->dev.config[0x06] = 0xa0; // status = fast back-to-back, 66MHz, no error

    s->dev.config[0x07] = 0x00; // status = fast devsel

    s->dev.config[0x08] = 0x00; // revision

    s->dev.config[0x09] = 0x00; // programming i/f

    pci_config_set_class(s->dev.config, PCI_CLASS_BRIDGE_PCI);

    s->dev.config[0x0D] = 0x10; // latency_timer

    s->dev.config[PCI_HEADER_TYPE] =

        PCI_HEADER_TYPE_MULTI_FUNCTION | PCI_HEADER_TYPE_BRIDGE; // header_type

    s->dev.config[0x1E] = 0xa0; // secondary status

    return 0;

}

static void convert_matrix(DSPContext *dsp, int (*qmat)[64], uint16_t (*qmat16)[2][64],

                           const uint16_t *quant_matrix, int bias, int qmin, int qmax, int intra)

{

    int qscale;

    int shift=0;



    for(qscale=qmin; qscale<=qmax; qscale++){

        int i;

        if (dsp->fdct == ff_jpeg_fdct_islow 

#ifdef FAAN_POSTSCALE

            || dsp->fdct == ff_faandct

#endif

            ) {

            for(i=0;i<64;i++) {

                const int j= dsp->idct_permutation[i];

                /* 16 <= qscale * quant_matrix[i] <= 7905 */

                /* 19952         <= aanscales[i] * qscale * quant_matrix[i]           <= 249205026 */

                /* (1<<36)/19952 >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= (1<<36)/249205026 */

                /* 3444240       >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= 275 */



                qmat[qscale][i] = (int)((uint64_t_C(1) << QMAT_SHIFT) / 

                                (qscale * quant_matrix[j]));

            }

        } else if (dsp->fdct == fdct_ifast

#ifndef FAAN_POSTSCALE

                   || dsp->fdct == ff_faandct

#endif

                   ) {

            for(i=0;i<64;i++) {

                const int j= dsp->idct_permutation[i];

                /* 16 <= qscale * quant_matrix[i] <= 7905 */

                /* 19952         <= aanscales[i] * qscale * quant_matrix[i]           <= 249205026 */

                /* (1<<36)/19952 >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= (1<<36)/249205026 */

                /* 3444240       >= (1<<36)/(aanscales[i] * qscale * quant_matrix[i]) >= 275 */



                qmat[qscale][i] = (int)((uint64_t_C(1) << (QMAT_SHIFT + 14)) / 

                                (aanscales[i] * qscale * quant_matrix[j]));

            }

        } else {

            for(i=0;i<64;i++) {

                const int j= dsp->idct_permutation[i];

                /* We can safely suppose that 16 <= quant_matrix[i] <= 255

                   So 16           <= qscale * quant_matrix[i]             <= 7905

                   so (1<<19) / 16 >= (1<<19) / (qscale * quant_matrix[i]) >= (1<<19) / 7905

                   so 32768        >= (1<<19) / (qscale * quant_matrix[i]) >= 67

                */

                qmat[qscale][i] = (int)((uint64_t_C(1) << QMAT_SHIFT) / (qscale * quant_matrix[j]));

//                qmat  [qscale][i] = (1 << QMAT_SHIFT_MMX) / (qscale * quant_matrix[i]);

                qmat16[qscale][0][i] = (1 << QMAT_SHIFT_MMX) / (qscale * quant_matrix[j]);



                if(qmat16[qscale][0][i]==0 || qmat16[qscale][0][i]==128*256) qmat16[qscale][0][i]=128*256-1;

                qmat16[qscale][1][i]= ROUNDED_DIV(bias<<(16-QUANT_BIAS_SHIFT), qmat16[qscale][0][i]);

            }

        }



        for(i=intra; i<64; i++){

            while(((8191LL * qmat[qscale][i]) >> shift) > INT_MAX){ 

                shift++;

            }

        }

    }

    if(shift){

        av_log(NULL, AV_LOG_INFO, "Warning, QMAT_SHIFT is larger then %d, overflows possible\n", QMAT_SHIFT - shift);

    }

}

static int monitor_fdset_dup_fd_find_remove(int dup_fd, bool remove)

{

    MonFdset *mon_fdset;

    MonFdsetFd *mon_fdset_fd_dup;



    QLIST_FOREACH(mon_fdset, &mon_fdsets, next) {

        QLIST_FOREACH(mon_fdset_fd_dup, &mon_fdset->dup_fds, next) {

            if (mon_fdset_fd_dup->fd == dup_fd) {

                if (remove) {

                    QLIST_REMOVE(mon_fdset_fd_dup, next);

                    if (QLIST_EMPTY(&mon_fdset->dup_fds)) {

                        monitor_fdset_cleanup(mon_fdset);

                    }

                }

                return mon_fdset->id;

            }

        }

    }

    return -1;

}

static int hevc_decode_nal_units(const uint8_t *buf, int buf_size, HEVCParamSets *ps,

                                 int is_nalff, int nal_length_size, void *logctx)

{

    int i;

    int ret = 0;

    H2645Packet pkt = { 0 };



    ret = ff_h2645_packet_split(&pkt, buf, buf_size, logctx, is_nalff, nal_length_size, AV_CODEC_ID_HEVC, 1);

    if (ret < 0) {

        goto done;

    }



    for (i = 0; i < pkt.nb_nals; i++) {

        H2645NAL *nal = &pkt.nals[i];



        /* ignore everything except parameter sets and VCL NALUs */

        switch (nal->type) {

        case HEVC_NAL_VPS: ff_hevc_decode_nal_vps(&nal->gb, logctx, ps);    break;

        case HEVC_NAL_SPS: ff_hevc_decode_nal_sps(&nal->gb, logctx, ps, 1); break;

        case HEVC_NAL_PPS: ff_hevc_decode_nal_pps(&nal->gb, logctx, ps);    break;

        default:

            av_log(logctx, AV_LOG_VERBOSE, "Ignoring NAL type %d in extradata\n", nal->type);

            break;

        }

    }



done:

    ff_h2645_packet_uninit(&pkt);

    return ret;

}

static void virtio_pci_vector_mask(PCIDevice *dev, unsigned vector)

{

    VirtIOPCIProxy *proxy = container_of(dev, VirtIOPCIProxy, pci_dev);

    VirtIODevice *vdev = virtio_bus_get_device(&proxy->bus);

    VirtQueue *vq = virtio_vector_first_queue(vdev, vector);

    int index;



    while (vq) {

        index = virtio_get_queue_index(vq);

        if (!virtio_queue_get_num(vdev, index)) {

            break;

        }

        virtio_pci_vq_vector_mask(proxy, index, vector);

        vq = virtio_vector_next_queue(vq);

    }

}

int ppc_hash64_handle_mmu_fault(CPUPPCState *env, target_ulong address, int rw,

                                int mmu_idx)

{

    struct mmu_ctx_hash64 ctx;

    int access_type;

    int ret = 0;



    if (rw == 2) {

        /* code access */

        rw = 0;

        access_type = ACCESS_CODE;

    } else {

        /* data access */

        access_type = env->access_type;

    }

    ret = ppc_hash64_get_physical_address(env, &ctx, address, rw, access_type);

    if (ret == 0) {

        tlb_set_page(env, address & TARGET_PAGE_MASK,

                     ctx.raddr & TARGET_PAGE_MASK, ctx.prot,

                     mmu_idx, TARGET_PAGE_SIZE);

        ret = 0;

    } else if (ret < 0) {

        LOG_MMU_STATE(env);

        if (access_type == ACCESS_CODE) {

            switch (ret) {

            case -1:

                env->exception_index = POWERPC_EXCP_ISI;

                env->error_code = 0x40000000;

                break;

            case -2:

                /* Access rights violation */

                env->exception_index = POWERPC_EXCP_ISI;

                env->error_code = 0x08000000;

                break;

            case -3:

                /* No execute protection violation */

                env->exception_index = POWERPC_EXCP_ISI;

                env->error_code = 0x10000000;

                break;

            case -5:

                /* No match in segment table */

                env->exception_index = POWERPC_EXCP_ISEG;

                env->error_code = 0;

                break;

            }

        } else {

            switch (ret) {

            case -1:

                /* No matches in page tables or TLB */

                env->exception_index = POWERPC_EXCP_DSI;

                env->error_code = 0;

                env->spr[SPR_DAR] = address;

                if (rw == 1) {

                    env->spr[SPR_DSISR] = 0x42000000;

                } else {

                    env->spr[SPR_DSISR] = 0x40000000;

                }

                break;

            case -2:

                /* Access rights violation */

                env->exception_index = POWERPC_EXCP_DSI;

                env->error_code = 0;

                env->spr[SPR_DAR] = address;

                if (rw == 1) {

                    env->spr[SPR_DSISR] = 0x0A000000;

                } else {

                    env->spr[SPR_DSISR] = 0x08000000;

                }

                break;

            case -5:

                /* No match in segment table */

                env->exception_index = POWERPC_EXCP_DSEG;

                env->error_code = 0;

                env->spr[SPR_DAR] = address;

                break;

            }

        }

#if 0

        printf("%s: set exception to %d %02x\n", __func__,

               env->exception, env->error_code);

#endif

        ret = 1;

    }



    return ret;

}

void memory_region_init(MemoryRegion *mr,

                        const char *name,

                        uint64_t size)

{

    mr->ops = NULL;

    mr->parent = NULL;

    mr->size = int128_make64(size);

    if (size == UINT64_MAX) {

        mr->size = int128_2_64();

    }

    mr->addr = 0;

    mr->subpage = false;

    mr->enabled = true;

    mr->terminates = false;

    mr->ram = false;

    mr->romd_mode = true;

    mr->readonly = false;

    mr->rom_device = false;

    mr->destructor = memory_region_destructor_none;

    mr->priority = 0;

    mr->may_overlap = false;

    mr->alias = NULL;

    QTAILQ_INIT(&mr->subregions);

    memset(&mr->subregions_link, 0, sizeof mr->subregions_link);

    QTAILQ_INIT(&mr->coalesced);

    mr->name = g_strdup(name);

    mr->dirty_log_mask = 0;

    mr->ioeventfd_nb = 0;

    mr->ioeventfds = NULL;

    mr->flush_coalesced_mmio = false;

}

static void raw_aio_flush_io_queue(BlockDriverState *bs)

{

