static int iscsi_open(BlockDriverState *bs, const char *filename, int flags)

{

    IscsiLun *iscsilun = bs->opaque;

    struct iscsi_context *iscsi = NULL;

    struct iscsi_url *iscsi_url = NULL;

    struct IscsiTask task;

    char *initiator_name = NULL;

    int ret;



    if ((BDRV_SECTOR_SIZE % 512) != 0) {

        error_report("iSCSI: Invalid BDRV_SECTOR_SIZE. "

                     "BDRV_SECTOR_SIZE(%lld) is not a multiple "

                     "of 512", BDRV_SECTOR_SIZE);

        return -EINVAL;

    }



    iscsi_url = iscsi_parse_full_url(iscsi, filename);

    if (iscsi_url == NULL) {

        error_report("Failed to parse URL : %s %s", filename,

                     iscsi_get_error(iscsi));

        ret = -EINVAL;

        goto out;

    }



    memset(iscsilun, 0, sizeof(IscsiLun));



    initiator_name = parse_initiator_name(iscsi_url->target);



    iscsi = iscsi_create_context(initiator_name);

    if (iscsi == NULL) {

        error_report("iSCSI: Failed to create iSCSI context.");

        ret = -ENOMEM;

        goto out;

    }



    if (iscsi_set_targetname(iscsi, iscsi_url->target)) {

        error_report("iSCSI: Failed to set target name.");

        ret = -EINVAL;

        goto out;

    }



    if (iscsi_url->user != NULL) {

        ret = iscsi_set_initiator_username_pwd(iscsi, iscsi_url->user,

                                              iscsi_url->passwd);

        if (ret != 0) {

            error_report("Failed to set initiator username and password");

            ret = -EINVAL;

            goto out;

        }

    }



    /* check if we got CHAP username/password via the options */

    if (parse_chap(iscsi, iscsi_url->target) != 0) {

        error_report("iSCSI: Failed to set CHAP user/password");

        ret = -EINVAL;

        goto out;

    }



    if (iscsi_set_session_type(iscsi, ISCSI_SESSION_NORMAL) != 0) {

        error_report("iSCSI: Failed to set session type to normal.");

        ret = -EINVAL;

        goto out;

    }



    iscsi_set_header_digest(iscsi, ISCSI_HEADER_DIGEST_NONE_CRC32C);



    /* check if we got HEADER_DIGEST via the options */

    parse_header_digest(iscsi, iscsi_url->target);



    task.iscsilun = iscsilun;

    task.status = 0;

    task.complete = 0;

    task.bs = bs;



    iscsilun->iscsi = iscsi;

    iscsilun->lun   = iscsi_url->lun;



    if (iscsi_full_connect_async(iscsi, iscsi_url->portal, iscsi_url->lun,

                                 iscsi_connect_cb, &task)

        != 0) {

        error_report("iSCSI: Failed to start async connect.");

        ret = -EINVAL;

        goto out;

    }



    while (!task.complete) {

        iscsi_set_events(iscsilun);

        qemu_aio_wait();

    }

    if (task.status != 0) {

        error_report("iSCSI: Failed to connect to LUN : %s",

                     iscsi_get_error(iscsi));

        ret = -EINVAL;

        goto out;

    }



    /* Medium changer or tape. We dont have any emulation for this so this must

     * be sg ioctl compatible. We force it to be sg, otherwise qemu will try

     * to read from the device to guess the image format.

     */

    if (iscsilun->type == TYPE_MEDIUM_CHANGER ||

        iscsilun->type == TYPE_TAPE) {

        bs->sg = 1;

    }



    ret = 0;



out:

    if (initiator_name != NULL) {

        g_free(initiator_name);

    }

    if (iscsi_url != NULL) {

        iscsi_destroy_url(iscsi_url);

    }



    if (ret) {

        if (iscsi != NULL) {

            iscsi_destroy_context(iscsi);

        }

        memset(iscsilun, 0, sizeof(IscsiLun));

    }

    return ret;

}

static void tcg_reg_alloc_bb_end(TCGContext *s, TCGRegSet allocated_regs)

{

    int i;



    for (i = s->nb_globals; i < s->nb_temps; i++) {

        TCGTemp *ts = &s->temps[i];

        if (ts->temp_local) {

            temp_save(s, ts, allocated_regs);

        } else {

#ifdef USE_LIVENESS_ANALYSIS

            /* ??? Liveness does not yet incorporate indirect bases.  */

            if (!ts->indirect_base) {

                /* The liveness analysis already ensures that temps are dead.

                   Keep an assert for safety. */

                assert(ts->val_type == TEMP_VAL_DEAD);

                continue;

            }

#endif

            temp_dead(s, ts);

        }

    }



    save_globals(s, allocated_regs);

}

av_cold int ff_vaapi_encode_close(AVCodecContext *avctx)

{

    VAAPIEncodeContext *ctx = avctx->priv_data;

    VAAPIEncodePicture *pic, *next;



    for (pic = ctx->pic_start; pic; pic = next) {

        next = pic->next;

        vaapi_encode_free(avctx, pic);

    }



    if (ctx->va_context != VA_INVALID_ID) {

        vaDestroyContext(ctx->hwctx->display, ctx->va_context);

        ctx->va_context = VA_INVALID_ID;

    }



    if (ctx->va_config != VA_INVALID_ID) {

        vaDestroyConfig(ctx->hwctx->display, ctx->va_config);

        ctx->va_config = VA_INVALID_ID;

    }



    if (ctx->codec->close)

        ctx->codec->close(avctx);



    av_buffer_pool_uninit(&ctx->output_buffer_pool);



    av_freep(&ctx->codec_sequence_params);

    av_freep(&ctx->codec_picture_params);



    av_buffer_unref(&ctx->recon_frames_ref);

    av_buffer_unref(&ctx->input_frames_ref);

    av_buffer_unref(&ctx->device_ref);



    av_freep(&ctx->priv_data);



    return 0;

}

void os_set_proc_name(const char *s)

{

#if defined(PR_SET_NAME)

    char name[16];

    if (!s)

        return;

    name[sizeof(name) - 1] = 0;

    strncpy(name, s, sizeof(name));

    /* Could rewrite argv[0] too, but that's a bit more complicated.

       This simple way is enough for `top'. */

    if (prctl(PR_SET_NAME, name)) {

        perror("unable to change process name");

        exit(1);

    }

#else

    fprintf(stderr, "Change of process name not supported by your OS\n");

    exit(1);

#endif

}

static void vga_ioport_write(void *opaque, uint32_t addr, uint32_t val)

{

    CirrusVGAState *s = opaque;

    int index;



    /* check port range access depending on color/monochrome mode */

    if ((addr >= 0x3b0 && addr <= 0x3bf && (s->msr & MSR_COLOR_EMULATION))

	|| (addr >= 0x3d0 && addr <= 0x3df

	    && !(s->msr & MSR_COLOR_EMULATION)))

	return;



#ifdef DEBUG_VGA

    printf("VGA: write addr=0x%04x data=0x%02x\n", addr, val);

#endif



    switch (addr) {

    case 0x3c0:

	if (s->ar_flip_flop == 0) {

	    val &= 0x3f;

	    s->ar_index = val;

	} else {

	    index = s->ar_index & 0x1f;

	    switch (index) {

	    case 0x00 ... 0x0f:

		s->ar[index] = val & 0x3f;

		break;

	    case 0x10:

		s->ar[index] = val & ~0x10;

		break;

	    case 0x11:

		s->ar[index] = val;

		break;

	    case 0x12:

		s->ar[index] = val & ~0xc0;

		break;

	    case 0x13:

		s->ar[index] = val & ~0xf0;

		break;

	    case 0x14:

		s->ar[index] = val & ~0xf0;

		break;

	    default:

		break;

	    }

	}

	s->ar_flip_flop ^= 1;

	break;

    case 0x3c2:

	s->msr = val & ~0x10;

	break;

    case 0x3c4:

	s->sr_index = val;

	break;

    case 0x3c5:

	if (cirrus_hook_write_sr(s, s->sr_index, val))

	    break;

#ifdef DEBUG_VGA_REG

	printf("vga: write SR%x = 0x%02x\n", s->sr_index, val);

#endif

	s->sr[s->sr_index] = val & sr_mask[s->sr_index];

	break;

    case 0x3c6:

	cirrus_write_hidden_dac(s, val);

	break;

    case 0x3c7:

	s->dac_read_index = val;

	s->dac_sub_index = 0;

	s->dac_state = 3;

	break;

    case 0x3c8:

	s->dac_write_index = val;

	s->dac_sub_index = 0;

	s->dac_state = 0;

	break;

    case 0x3c9:

	if (cirrus_hook_write_palette(s, val))

	    break;

	s->dac_cache[s->dac_sub_index] = val;

	if (++s->dac_sub_index == 3) {

	    memcpy(&s->palette[s->dac_write_index * 3], s->dac_cache, 3);

	    s->dac_sub_index = 0;

	    s->dac_write_index++;

	}

	break;

    case 0x3ce:

	s->gr_index = val;

	break;

    case 0x3cf:

	if (cirrus_hook_write_gr(s, s->gr_index, val))

	    break;

#ifdef DEBUG_VGA_REG

	printf("vga: write GR%x = 0x%02x\n", s->gr_index, val);

#endif

	s->gr[s->gr_index] = val & gr_mask[s->gr_index];

	break;

    case 0x3b4:

    case 0x3d4:

	s->cr_index = val;

	break;

    case 0x3b5:

    case 0x3d5:

	if (cirrus_hook_write_cr(s, s->cr_index, val))

	    break;

#ifdef DEBUG_VGA_REG

	printf("vga: write CR%x = 0x%02x\n", s->cr_index, val);

#endif

	/* handle CR0-7 protection */

	if ((s->cr[11] & 0x80) && s->cr_index <= 7) {

	    /* can always write bit 4 of CR7 */

	    if (s->cr_index == 7)

		s->cr[7] = (s->cr[7] & ~0x10) | (val & 0x10);

	    return;

	}

	switch (s->cr_index) {

	case 0x01:		/* horizontal display end */

	case 0x07:

	case 0x09:

	case 0x0c:

	case 0x0d:

	case 0x12:		/* veritcal display end */

	    s->cr[s->cr_index] = val;

	    break;



	default:

	    s->cr[s->cr_index] = val;

	    break;

	}

	break;

    case 0x3ba:

    case 0x3da:

	s->fcr = val & 0x10;

	break;

    }

}

int kvm_arch_handle_exit(CPUPPCState *env, struct kvm_run *run)

{

    int ret;



    switch (run->exit_reason) {

    case KVM_EXIT_DCR:

        if (run->dcr.is_write) {

            dprintf("handle dcr write\n");

            ret = kvmppc_handle_dcr_write(env, run->dcr.dcrn, run->dcr.data);

        } else {

            dprintf("handle dcr read\n");

            ret = kvmppc_handle_dcr_read(env, run->dcr.dcrn, &run->dcr.data);

        }

        break;

    case KVM_EXIT_HLT:

        dprintf("handle halt\n");

        ret = kvmppc_handle_halt(env);

        break;

#ifdef CONFIG_PSERIES

    case KVM_EXIT_PAPR_HCALL:

        dprintf("handle PAPR hypercall\n");

        run->papr_hcall.ret = spapr_hypercall(env, run->papr_hcall.nr,

                                              run->papr_hcall.args);

        ret = 1;

        break;

#endif

    default:

        fprintf(stderr, "KVM: unknown exit reason %d\n", run->exit_reason);

        ret = -1;

        break;

    }



    return ret;

}

Object *user_creatable_add(const QDict *qdict,

                           Visitor *v, Error **errp)

{

    char *type = NULL;

    char *id = NULL;

    Object *obj = NULL;

    Error *local_err = NULL, *end_err = NULL;

    QDict *pdict;



    pdict = qdict_clone_shallow(qdict);



    visit_start_struct(v, NULL, NULL, 0, &local_err);

    if (local_err) {

        goto out;

    }



    qdict_del(pdict, "qom-type");

    visit_type_str(v, "qom-type", &type, &local_err);

    if (local_err) {

        goto out_visit;

    }



    qdict_del(pdict, "id");

    visit_type_str(v, "id", &id, &local_err);

    if (local_err) {

        goto out_visit;

    }



    obj = user_creatable_add_type(type, id, pdict, v, &local_err);

    if (local_err) {

        goto out_visit;

    }



 out_visit:

    visit_end_struct(v, &end_err);

    if (end_err) {

        error_propagate(&local_err, end_err);

        if (obj) {

            user_creatable_del(id, NULL);

        }

        goto out;

    }



out:

    QDECREF(pdict);

    g_free(id);

    g_free(type);

    if (local_err) {

        error_propagate(errp, local_err);

        object_unref(obj);

        return NULL;

    }

    return obj;

}

gdb_handlesig (CPUState *env, int sig)

{

  GDBState *s;

  char buf[256];

  int n;



  s = gdbserver_state;

  if (gdbserver_fd < 0 || s->fd < 0)

    return sig;



  /* disable single step if it was enabled */

  cpu_single_step(env, 0);

  tb_flush(env);



  if (sig != 0)

    {

      snprintf(buf, sizeof(buf), "S%02x", target_signal_to_gdb (sig));

      put_packet(s, buf);

    }

  /* put_packet() might have detected that the peer terminated the 

     connection.  */

  if (s->fd < 0)

      return sig;



  sig = 0;

  s->state = RS_IDLE;

  s->running_state = 0;

  while (s->running_state == 0) {

      n = read (s->fd, buf, 256);

      if (n > 0)

        {

          int i;



          for (i = 0; i < n; i++)

            gdb_read_byte (s, buf[i]);

        }

      else if (n == 0 || errno != EAGAIN)

        {

          /* XXX: Connection closed.  Should probably wait for annother

             connection before continuing.  */

          return sig;

        }

  }

  sig = s->signal;

  s->signal = 0;

  return sig;

}

static gboolean io_watch_poll_prepare(GSource *source, gint *timeout_)

{

    IOWatchPoll *iwp = io_watch_poll_from_source(source);

    bool now_active = iwp->fd_can_read(iwp->opaque) > 0;

    bool was_active = g_source_get_context(iwp->src) != NULL;

    if (was_active == now_active) {

        return FALSE;

    }



    if (now_active) {

        g_source_attach(iwp->src, NULL);

    } else {

        g_source_remove(g_source_get_id(iwp->src));

    }

    return FALSE;

}

