static int ivi_decode_coded_blocks(GetBitContext *gb, IVIBandDesc *band,

                                   ivi_mc_func mc, int mv_x, int mv_y,

                                   int *prev_dc, int is_intra, int mc_type,

                                   uint32_t quant, int offs,

                                   AVCodecContext *avctx)

{

    const uint16_t *base_tab  = is_intra ? band->intra_base : band->inter_base;

    RVMapDesc *rvmap = band->rv_map;

    uint8_t col_flags[8];

    int32_t trvec[64];

    uint32_t sym = 0, lo, hi, q;

    int pos, run, val;

    int blk_size   = band->blk_size;

    int num_coeffs = blk_size * blk_size;

    int col_mask   = blk_size - 1;

    int scan_pos   = -1;

    int min_size   = band->pitch * (band->transform_size - 1) +

                     band->transform_size;

    int buf_size   = band->pitch * band->aheight - offs;



    if (min_size > buf_size)

        return AVERROR_INVALIDDATA;



    if (!band->scan) {

        av_log(avctx, AV_LOG_ERROR, "Scan pattern is not set.\n");

        return AVERROR_INVALIDDATA;

    }



    /* zero transform vector */

    memset(trvec, 0, num_coeffs * sizeof(trvec[0]));

    /* zero column flags */

    memset(col_flags, 0, sizeof(col_flags));

    while (scan_pos <= num_coeffs) {

        sym = get_vlc2(gb, band->blk_vlc.tab->table,

                       IVI_VLC_BITS, 1);

        if (sym == rvmap->eob_sym)

            break; /* End of block */



        /* Escape - run/val explicitly coded using 3 vlc codes */

        if (sym == rvmap->esc_sym) {

            run = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1) + 1;

            lo  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);

            hi  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);

            /* merge them and convert into signed val */

            val = IVI_TOSIGNED((hi << 6) | lo);

        } else {

            if (sym >= 256U) {

                av_log(avctx, AV_LOG_ERROR, "Invalid sym encountered: %d.\n", sym);

                return AVERROR_INVALIDDATA;

            }

            run = rvmap->runtab[sym];

            val = rvmap->valtab[sym];

        }



        /* de-zigzag and dequantize */

        scan_pos += run;

        if (scan_pos >= num_coeffs || scan_pos < 0)

            break;

        pos = band->scan[scan_pos];



        if (!val)

            av_dlog(avctx, "Val = 0 encountered!\n");



        q = (base_tab[pos] * quant) >> 9;

        if (q > 1)

            val = val * q + FFSIGN(val) * (((q ^ 1) - 1) >> 1);

        trvec[pos] = val;

        /* track columns containing non-zero coeffs */

        col_flags[pos & col_mask] |= !!val;

    }



    if (scan_pos < 0 || scan_pos >= num_coeffs && sym != rvmap->eob_sym)

        return AVERROR_INVALIDDATA; /* corrupt block data */



    /* undoing DC coeff prediction for intra-blocks */

    if (is_intra && band->is_2d_trans) {

        *prev_dc     += trvec[0];

        trvec[0]      = *prev_dc;

        col_flags[0] |= !!*prev_dc;

    }



    /* apply inverse transform */

    band->inv_transform(trvec, band->buf + offs,

                        band->pitch, col_flags);



    /* apply motion compensation */

    if (!is_intra)

        return ivi_mc(mc, band->buf, band->ref_buf, offs, mv_x, mv_y,

                      band->pitch, mc_type);



    return 0;

}

static int qemu_rbd_create(const char *filename, QemuOpts *opts, Error **errp)

{

    Error *local_err = NULL;

    int64_t bytes = 0;

    int64_t objsize;

    int obj_order = 0;

    const char *pool, *name, *conf, *clientname, *keypairs;

    const char *secretid;

    rados_t cluster;

    rados_ioctx_t io_ctx;

    QDict *options = NULL;

    int ret = 0;



    secretid = qemu_opt_get(opts, "password-secret");



    /* Read out options */

    bytes = ROUND_UP(qemu_opt_get_size_del(opts, BLOCK_OPT_SIZE, 0),

                     BDRV_SECTOR_SIZE);

    objsize = qemu_opt_get_size_del(opts, BLOCK_OPT_CLUSTER_SIZE, 0);

    if (objsize) {

        if ((objsize - 1) & objsize) {    /* not a power of 2? */

            error_setg(errp, "obj size needs to be power of 2");

            ret = -EINVAL;

            goto exit;

        }

        if (objsize < 4096) {

            error_setg(errp, "obj size too small");

            ret = -EINVAL;

            goto exit;

        }

        obj_order = ctz32(objsize);

    }



    options = qdict_new();

    qemu_rbd_parse_filename(filename, options, &local_err);

    if (local_err) {

        ret = -EINVAL;

        error_propagate(errp, local_err);

        goto exit;

    }









    pool       = qdict_get_try_str(options, "pool");

    conf       = qdict_get_try_str(options, "conf");

    clientname = qdict_get_try_str(options, "user");

    name       = qdict_get_try_str(options, "image");

    keypairs   = qdict_get_try_str(options, "=keyvalue-pairs");



    ret = rados_create(&cluster, clientname);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "error initializing");

        goto exit;

    }



    /* try default location when conf=NULL, but ignore failure */

    ret = rados_conf_read_file(cluster, conf);

    if (conf && ret < 0) {

        error_setg_errno(errp, -ret, "error reading conf file %s", conf);

        ret = -EIO;

        goto shutdown;

    }



    ret = qemu_rbd_set_keypairs(cluster, keypairs, errp);

    if (ret < 0) {

        ret = -EIO;

        goto shutdown;

    }



    if (qemu_rbd_set_auth(cluster, secretid, errp) < 0) {

        ret = -EIO;

        goto shutdown;

    }



    ret = rados_connect(cluster);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "error connecting");

        goto shutdown;

    }



    ret = rados_ioctx_create(cluster, pool, &io_ctx);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "error opening pool %s", pool);

        goto shutdown;

    }



    ret = rbd_create(io_ctx, name, bytes, &obj_order);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "error rbd create");

    }



    rados_ioctx_destroy(io_ctx);



shutdown:

    rados_shutdown(cluster);



exit:

    QDECREF(options);

    return ret;

}

void bdrv_set_dirty_tracking(BlockDriverState *bs, int enable)

{

    int64_t bitmap_size;



    if (enable) {

        if (bs->dirty_tracking == 0) {

            int64_t i;

            uint8_t test;



            bitmap_size = (bdrv_getlength(bs) >> BDRV_SECTOR_BITS);

            bitmap_size /= BDRV_SECTORS_PER_DIRTY_CHUNK;

            bitmap_size++;



            bs->dirty_bitmap = qemu_mallocz(bitmap_size);



            bs->dirty_tracking = enable;

            for(i = 0; i < bitmap_size; i++) test = bs->dirty_bitmap[i]; 

        }

    } else {

        if (bs->dirty_tracking != 0) {

            qemu_free(bs->dirty_bitmap);

            bs->dirty_tracking = enable;

        }

    }

}

static int read_cpuinfo(const char *field, char *value, int len)

{

    FILE *f;

    int ret = -1;

    int field_len = strlen(field);

    char line[512];



    f = fopen("/proc/cpuinfo", "r");

    if (!f) {

        return -1;

    }



    do {

        if(!fgets(line, sizeof(line), f)) {

            break;

        }

        if (!strncmp(line, field, field_len)) {

            strncpy(value, line, len);

            ret = 0;

            break;

        }

    } while(*line);



    fclose(f);



    return ret;

}

static int vhost_user_start(VhostUserState *s)

{

