static void virtio_device_realize(DeviceState *dev, Error **errp)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(dev);

    VirtioDeviceClass *vdc = VIRTIO_DEVICE_GET_CLASS(dev);

    Error *err = NULL;



    /* Devices should either use vmsd or the load/save methods */

    assert(!vdc->vmsd || !vdc->load);



    if (vdc->realize != NULL) {

        vdc->realize(dev, &err);

        if (err != NULL) {

            error_propagate(errp, err);

            return;

        }

    }



    virtio_bus_device_plugged(vdev, &err);

    if (err != NULL) {

        error_propagate(errp, err);


        return;

    }



    vdev->listener.commit = virtio_memory_listener_commit;

    memory_listener_register(&vdev->listener, vdev->dma_as);

}

static int flv_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    AVIOContext *pb = s->pb;

    AVCodecContext *enc = s->streams[pkt->stream_index]->codec;

    FLVContext *flv = s->priv_data;

    unsigned ts;

    int size= pkt->size;

    uint8_t *data= NULL;

    int flags, flags_size;



//    av_log(s, AV_LOG_DEBUG, "type:%d pts: %"PRId64" size:%d\n", enc->codec_type, timestamp, size);



    if(enc->codec_id == CODEC_ID_VP6 || enc->codec_id == CODEC_ID_VP6F ||

       enc->codec_id == CODEC_ID_AAC)

        flags_size= 2;

    else if(enc->codec_id == CODEC_ID_H264)

        flags_size= 5;

    else

        flags_size= 1;



    if (enc->codec_type == AVMEDIA_TYPE_VIDEO) {

        avio_w8(pb, FLV_TAG_TYPE_VIDEO);



        flags = enc->codec_tag;

        if(flags == 0) {

            av_log(enc, AV_LOG_ERROR, "video codec %X not compatible with flv\n",enc->codec_id);

            return -1;

        }



        flags |= pkt->flags & AV_PKT_FLAG_KEY ? FLV_FRAME_KEY : FLV_FRAME_INTER;

    } else {

        assert(enc->codec_type == AVMEDIA_TYPE_AUDIO);

        flags = get_audio_flags(enc);



        assert(size);



        avio_w8(pb, FLV_TAG_TYPE_AUDIO);

    }



    if (enc->codec_id == CODEC_ID_H264) {

        /* check if extradata looks like mp4 formated */

        if (enc->extradata_size > 0 && *(uint8_t*)enc->extradata != 1) {

            if (ff_avc_parse_nal_units_buf(pkt->data, &data, &size) < 0)

                return -1;

        }

    }

    if (!flv->delay && pkt->dts < 0)

        flv->delay = -pkt->dts;



    ts = pkt->dts + flv->delay; // add delay to force positive dts

    if (enc->codec_type == AVMEDIA_TYPE_VIDEO) {

        if (flv->last_video_ts < ts)

            flv->last_video_ts = ts;

    }

    avio_wb24(pb,size + flags_size);

    avio_wb24(pb,ts);

    avio_w8(pb,(ts >> 24) & 0x7F); // timestamps are 32bits _signed_

    avio_wb24(pb,flv->reserved);

    avio_w8(pb,flags);

    if (enc->codec_id == CODEC_ID_VP6)

        avio_w8(pb,0);

    if (enc->codec_id == CODEC_ID_VP6F)

        avio_w8(pb, enc->extradata_size ? enc->extradata[0] : 0);

    else if (enc->codec_id == CODEC_ID_AAC)

        avio_w8(pb,1); // AAC raw

    else if (enc->codec_id == CODEC_ID_H264) {

        avio_w8(pb,1); // AVC NALU

        avio_wb24(pb,pkt->pts - pkt->dts);

    }



    avio_write(pb, data ? data : pkt->data, size);



    avio_wb32(pb,size+flags_size+11); // previous tag size

    flv->duration = FFMAX(flv->duration, pkt->pts + flv->delay + pkt->duration);



    avio_flush(pb);



    av_free(data);



    return pb->error;

}

static void write_fp_dreg(DisasContext *s, int reg, TCGv_i64 v)

{

    TCGv_i64 tcg_zero = tcg_const_i64(0);



    tcg_gen_st_i64(v, cpu_env, fp_reg_offset(reg, MO_64));

    tcg_gen_st_i64(tcg_zero, cpu_env, fp_reg_hi_offset(reg));

    tcg_temp_free_i64(tcg_zero);

}

static int sd_parse_uri(BDRVSheepdogState *s, const char *filename,

                        char *vdi, uint32_t *snapid, char *tag)

{

    URI *uri;

    QueryParams *qp = NULL;

    int ret = 0;



    uri = uri_parse(filename);

    if (!uri) {

        return -EINVAL;

    }



    /* transport */

    if (!strcmp(uri->scheme, "sheepdog")) {

        s->is_unix = false;

    } else if (!strcmp(uri->scheme, "sheepdog+tcp")) {

        s->is_unix = false;

    } else if (!strcmp(uri->scheme, "sheepdog+unix")) {

        s->is_unix = true;

    } else {

        ret = -EINVAL;

        goto out;

    }



    if (uri->path == NULL || !strcmp(uri->path, "/")) {

        ret = -EINVAL;

        goto out;

    }

    pstrcpy(vdi, SD_MAX_VDI_LEN, uri->path + 1);



    qp = query_params_parse(uri->query);

    if (qp->n > 1 || (s->is_unix && !qp->n) || (!s->is_unix && qp->n)) {

        ret = -EINVAL;

        goto out;

    }



    if (s->is_unix) {

        /* sheepdog+unix:///vdiname?socket=path */

        if (uri->server || uri->port || strcmp(qp->p[0].name, "socket")) {

            ret = -EINVAL;

            goto out;

        }

        s->host_spec = g_strdup(qp->p[0].value);

    } else {

        /* sheepdog[+tcp]://[host:port]/vdiname */

        s->host_spec = g_strdup_printf("%s:%d", uri->server ?: SD_DEFAULT_ADDR,

                                       uri->port ?: SD_DEFAULT_PORT);

    }



    /* snapshot tag */

    if (uri->fragment) {

        *snapid = strtoul(uri->fragment, NULL, 10);

        if (*snapid == 0) {

            pstrcpy(tag, SD_MAX_VDI_TAG_LEN, uri->fragment);

        }

    } else {

        *snapid = CURRENT_VDI_ID; /* search current vdi */

    }



out:

    if (qp) {

        query_params_free(qp);

    }

    uri_free(uri);

    return ret;

}

void qed_release(BDRVQEDState *s)

{

    aio_context_release(bdrv_get_aio_context(s->bs));

}

void cpu_loop (CPUState *env)

{

    int trapnr;

    target_siginfo_t info;



    while (1) {

        trapnr = cpu_alpha_exec (env);



        switch (trapnr) {

        case EXCP_RESET:

            fprintf(stderr, "Reset requested. Exit\n");

            exit(1);

            break;

        case EXCP_MCHK:

            fprintf(stderr, "Machine check exception. Exit\n");

            exit(1);

            break;

        case EXCP_ARITH:

            fprintf(stderr, "Arithmetic trap.\n");

            exit(1);

            break;

        case EXCP_HW_INTERRUPT:

            fprintf(stderr, "External interrupt. Exit\n");

            exit(1);

            break;

        case EXCP_DFAULT:

            fprintf(stderr, "MMU data fault\n");

            exit(1);

            break;

        case EXCP_DTB_MISS_PAL:

            fprintf(stderr, "MMU data TLB miss in PALcode\n");

            exit(1);

            break;

        case EXCP_ITB_MISS:

            fprintf(stderr, "MMU instruction TLB miss\n");

            exit(1);

            break;

        case EXCP_ITB_ACV:

            fprintf(stderr, "MMU instruction access violation\n");

            exit(1);

            break;

        case EXCP_DTB_MISS_NATIVE:

            fprintf(stderr, "MMU data TLB miss\n");

            exit(1);

            break;

        case EXCP_UNALIGN:

            fprintf(stderr, "Unaligned access\n");

            exit(1);

            break;

        case EXCP_OPCDEC:

            fprintf(stderr, "Invalid instruction\n");

            exit(1);

            break;

        case EXCP_FEN:

            fprintf(stderr, "Floating-point not allowed\n");

            exit(1);

            break;

        case EXCP_CALL_PAL ... (EXCP_CALL_PALP - 1):

            call_pal(env, (trapnr >> 6) | 0x80);

            break;

        case EXCP_CALL_PALP ... (EXCP_CALL_PALE - 1):

            fprintf(stderr, "Privileged call to PALcode\n");

            exit(1);

            break;

        case EXCP_DEBUG:

            {

                int sig;



                sig = gdb_handlesig (env, TARGET_SIGTRAP);

                if (sig)

                  {

                    info.si_signo = sig;

                    info.si_errno = 0;

                    info.si_code = TARGET_TRAP_BRKPT;

                    queue_signal(env, info.si_signo, &info);

                  }

            }

            break;

        default:

            printf ("Unhandled trap: 0x%x\n", trapnr);

            cpu_dump_state(env, stderr, fprintf, 0);

            exit (1);

        }

        process_pending_signals (env);

    }

}

static int decode_motion_vector (bit_buffer_t *bitbuf, svq1_pmv_t *mv, svq1_pmv_t **pmv) {

  uint32_t    bit_cache;

  vlc_code_t *vlc;

  int	      diff, sign;

  int	      i;



  for (i=0; i < 2; i++) {



    /* get motion code */

    bit_cache = get_bit_cache (bitbuf);



    if (!(bit_cache & 0xFFE00000))

      return -1;	/* invalid vlc code */



    if (bit_cache & 0x80000000) {

      diff = 0;



      /* flush bit */

      skip_bits(bitbuf,1);



    } else {

      if (bit_cache >= 0x06000000) {

        vlc = &motion_table_0[(bit_cache >> (32 - 7)) - 3];

      } else {

        vlc = &motion_table_1[(bit_cache >> (32 - 12)) - 2];

      }



      /* decode motion vector differential */

      sign = (int) (bit_cache << (vlc->length - 1)) >> 31;

      diff = (vlc->value ^ sign) - sign;



      /* flush bits */

      skip_bits(bitbuf,vlc->length);

    }



    /* add median of motion vector predictors and clip result */

    if (i == 1)

      mv->y = ((diff + MEDIAN(pmv[0]->y, pmv[1]->y, pmv[2]->y)) << 26) >> 26;

    else

      mv->x = ((diff + MEDIAN(pmv[0]->x, pmv[1]->x, pmv[2]->x)) << 26) >> 26;

  }



  return 0;

}

static int aio_read_f(int argc, char **argv)

{

    int nr_iov, c;

    struct aio_ctx *ctx = calloc(1, sizeof(struct aio_ctx));



    while ((c = getopt(argc, argv, "CP:qv")) != EOF) {

        switch (c) {

        case 'C':

            ctx->Cflag = 1;

            break;

        case 'P':

            ctx->Pflag = 1;

            ctx->pattern = parse_pattern(optarg);

            if (ctx->pattern < 0) {

                free(ctx);

                return 0;

            }

            break;

        case 'q':

            ctx->qflag = 1;

            break;

        case 'v':

            ctx->vflag = 1;

            break;

        default:

            free(ctx);

            return command_usage(&aio_read_cmd);

        }

    }



    if (optind > argc - 2) {

        free(ctx);

        return command_usage(&aio_read_cmd);

    }



    ctx->offset = cvtnum(argv[optind]);

    if (ctx->offset < 0) {

        printf("non-numeric length argument -- %s\n", argv[optind]);

        free(ctx);

        return 0;

    }

    optind++;



    if (ctx->offset & 0x1ff) {

        printf("offset %" PRId64 " is not sector aligned\n",

               ctx->offset);

        free(ctx);

        return 0;

    }



    nr_iov = argc - optind;

    ctx->buf = create_iovec(&ctx->qiov, &argv[optind], nr_iov, 0xab);

    if (ctx->buf == NULL) {

        free(ctx);

        return 0;

    }



    gettimeofday(&ctx->t1, NULL);

    bdrv_aio_readv(bs, ctx->offset >> 9, &ctx->qiov,

                   ctx->qiov.size >> 9, aio_read_done, ctx);

    return 0;

}

int kvm_arch_remove_hw_breakpoint(target_ulong addr,

                                  target_ulong len, int type)

{

    int n;



    n = find_hw_breakpoint(addr, (type == GDB_BREAKPOINT_HW) ? 1 : len, type);

    if (n < 0)

        return -ENOENT;



    nb_hw_breakpoint--;

    hw_breakpoint[n] = hw_breakpoint[nb_hw_breakpoint];



    return 0;

}

int h263_decode_picture_header(MpegEncContext *s)

{

    int format, width, height, i;

    uint32_t startcode;



    align_get_bits(&s->gb);



    startcode= get_bits(&s->gb, 22-8);



    for(i= s->gb.size_in_bits - get_bits_count(&s->gb); i>24; i-=8) {

        startcode = ((startcode << 8) | get_bits(&s->gb, 8)) & 0x003FFFFF;



        if(startcode == 0x20)

            break;

    }



    if (startcode != 0x20) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");

        return -1;

    }

    /* temporal reference */

    s->picture_number = get_bits(&s->gb, 8); /* picture timestamp */



    /* PTYPE starts here */    

    if (get_bits1(&s->gb) != 1) {

        /* marker */

        av_log(s->avctx, AV_LOG_ERROR, "Bad marker\n");

        return -1;

    }

    if (get_bits1(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad H263 id\n");

        return -1;	/* h263 id */

    }

    skip_bits1(&s->gb);	/* split screen off */

    skip_bits1(&s->gb);	/* camera  off */

    skip_bits1(&s->gb);	/* freeze picture release off */



    /* Reset GOB number */

    s->gob_number = 0;



    format = get_bits(&s->gb, 3);

    /*

        0    forbidden

        1    sub-QCIF

        10   QCIF

        7	extended PTYPE (PLUSPTYPE)

    */



    if (format != 7 && format != 6) {

        s->h263_plus = 0;

        /* H.263v1 */

        width = h263_format[format][0];

        height = h263_format[format][1];

        if (!width)

            return -1;



        s->pict_type = I_TYPE + get_bits1(&s->gb);



        s->h263_long_vectors = get_bits1(&s->gb); 



        if (get_bits1(&s->gb) != 0) {

            av_log(s->avctx, AV_LOG_ERROR, "H263 SAC not supported\n");

            return -1;	/* SAC: off */

        }

        s->obmc= get_bits1(&s->gb); /* Advanced prediction mode */

        s->unrestricted_mv = s->h263_long_vectors || s->obmc;



        if (get_bits1(&s->gb) != 0) {

            av_log(s->avctx, AV_LOG_ERROR, "H263 PB frame not supported\n");

            return -1;	/* not PB frame */

        }

        s->qscale = get_bits(&s->gb, 5);

        skip_bits1(&s->gb);	/* Continuous Presence Multipoint mode: off */



        s->width = width;

        s->height = height;

    } else {

        int ufep;



        /* H.263v2 */

        s->h263_plus = 1;

        ufep = get_bits(&s->gb, 3); /* Update Full Extended PTYPE */



        /* ufep other than 0 and 1 are reserved */        

        if (ufep == 1) {

            /* OPPTYPE */       

            format = get_bits(&s->gb, 3);

            dprintf("ufep=1, format: %d\n", format);

            skip_bits(&s->gb,1); /* Custom PCF */

            s->umvplus = get_bits(&s->gb, 1); /* Unrestricted Motion Vector */

            skip_bits1(&s->gb); /* Syntax-based Arithmetic Coding (SAC) */

            s->obmc= get_bits1(&s->gb); /* Advanced prediction mode */

            s->unrestricted_mv = s->umvplus || s->obmc;

            s->h263_aic = get_bits1(&s->gb); /* Advanced Intra Coding (AIC) */



            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Deblocking Filter not supported\n");

            }

            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Slice Structured not supported\n");

            }

            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Reference Picture Selection not supported\n");

            }

            if (get_bits1(&s->gb) != 0) {

                av_log(s->avctx, AV_LOG_ERROR, "Independent Segment Decoding not supported\n");

            }

            s->alt_inter_vlc= get_bits1(&s->gb);

            s->modified_quant= get_bits1(&s->gb);



            skip_bits(&s->gb, 1); /* Prevent start code emulation */



            skip_bits(&s->gb, 3); /* Reserved */

        } else if (ufep != 0) {

            av_log(s->avctx, AV_LOG_ERROR, "Bad UFEP type (%d)\n", ufep);

            return -1;

        }



        /* MPPTYPE */

        s->pict_type = get_bits(&s->gb, 3) + I_TYPE;

	if (s->pict_type == 8 && s->avctx->codec_tag == ff_get_fourcc("ZYGO"))

	    s->pict_type = I_TYPE;

        if (s->pict_type != I_TYPE &&

            s->pict_type != P_TYPE)

            return -1;

        skip_bits(&s->gb, 2);

        s->no_rounding = get_bits1(&s->gb);

        skip_bits(&s->gb, 4);



        /* Get the picture dimensions */

        if (ufep) {

            if (format == 6) {

                /* Custom Picture Format (CPFMT) */

                s->aspect_ratio_info = get_bits(&s->gb, 4);

                dprintf("aspect: %d\n", s->aspect_ratio_info);

                /* aspect ratios:

                0 - forbidden

                1 - 1:1

                2 - 12:11 (CIF 4:3)

                3 - 10:11 (525-type 4:3)

                4 - 16:11 (CIF 16:9)

                5 - 40:33 (525-type 16:9)

                6-14 - reserved

                */

                width = (get_bits(&s->gb, 9) + 1) * 4;

                skip_bits1(&s->gb);

                height = get_bits(&s->gb, 9) * 4;

                dprintf("\nH.263+ Custom picture: %dx%d\n",width,height);

                if (s->aspect_ratio_info == FF_ASPECT_EXTENDED) {

                    /* aspected dimensions */

                    s->avctx->sample_aspect_ratio.num= get_bits(&s->gb, 8);

                    s->avctx->sample_aspect_ratio.den= get_bits(&s->gb, 8);

                }else{

                    s->avctx->sample_aspect_ratio= pixel_aspect[s->aspect_ratio_info];

                }

            } else {

                width = h263_format[format][0];

                height = h263_format[format][1];

            }

            if ((width == 0) || (height == 0))

                return -1;

            s->width = width;

            s->height = height;

            if (s->umvplus) {

                if(get_bits1(&s->gb)==0) /* Unlimited Unrestricted Motion Vectors Indicator (UUI) */

                    skip_bits1(&s->gb); 

            }

        }



        s->qscale = get_bits(&s->gb, 5);

    }

    /* PEI */

    while (get_bits1(&s->gb) != 0) {

        skip_bits(&s->gb, 8);

    }

    s->f_code = 1;



    if(s->h263_aic){

         s->y_dc_scale_table= 

         s->c_dc_scale_table= ff_aic_dc_scale_table;

    }else{

        s->y_dc_scale_table=

        s->c_dc_scale_table= ff_mpeg1_dc_scale_table;

    }



     if(s->avctx->debug&FF_DEBUG_PICT_INFO){

         av_log(s->avctx, AV_LOG_DEBUG, "qp:%d %c size:%d rnd:%d%s%s%s%s%s%s%s\n", 

         s->qscale, av_get_pict_type_char(s->pict_type),

         s->gb.size_in_bits, 1-s->no_rounding,

         s->obmc ? " AP" : "",

         s->umvplus ? " UMV" : "",

         s->h263_long_vectors ? " LONG" : "",

         s->h263_plus ? " +" : "",

         s->h263_aic ? " AIC" : "",

         s->alt_inter_vlc ? " AIV" : "",

         s->modified_quant ? " MQ" : ""

         ); 

     }

#if 1

    if (s->pict_type == I_TYPE && s->avctx->codec_tag == ff_get_fourcc("ZYGO")){

        int i,j;

        for(i=0; i<85; i++) av_log(s->avctx, AV_LOG_DEBUG, "%d", get_bits1(&s->gb));

        av_log(s->avctx, AV_LOG_DEBUG, "\n");

        for(i=0; i<13; i++){

            for(j=0; j<3; j++){

                int v= get_bits(&s->gb, 8);

                v |= get_sbits(&s->gb, 8)<<8;

                av_log(s->avctx, AV_LOG_DEBUG, " %5d", v);

            }

            av_log(s->avctx, AV_LOG_DEBUG, "\n");

        }

        for(i=0; i<50; i++) av_log(s->avctx, AV_LOG_DEBUG, "%d", get_bits1(&s->gb));

    }

#endif



    return 0;

}

void unregister_savevm(DeviceState *dev, const char *idstr, void *opaque)

{

    SaveStateEntry *se, *new_se;

    char id[256] = "";



    if (dev) {

        char *path = qdev_get_dev_path(dev);

        if (path) {

            pstrcpy(id, sizeof(id), path);

            pstrcat(id, sizeof(id), "/");

            g_free(path);

        }

    }

    pstrcat(id, sizeof(id), idstr);



    QTAILQ_FOREACH_SAFE(se, &savevm_state.handlers, entry, new_se) {

        if (strcmp(se->idstr, id) == 0 && se->opaque == opaque) {

            QTAILQ_REMOVE(&savevm_state.handlers, se, entry);

            if (se->compat) {

                g_free(se->compat);

            }

            g_free(se->ops);

            g_free(se);

        }

    }

}

static int plot_cqt(AVFilterContext *ctx)

{

    AVFilterLink *outlink = ctx->outputs[0];

    ShowCQTContext *s = ctx->priv;

    int ret;



    memcpy(s->fft_result, s->fft_data, s->fft_len * sizeof(*s->fft_data));

    av_fft_permute(s->fft_ctx, s->fft_result);

    av_fft_calc(s->fft_ctx, s->fft_result);

    s->fft_result[s->fft_len] = s->fft_result[0];

    s->cqt_calc(s->cqt_result, s->fft_result, s->coeffs, s->cqt_len, s->fft_len);

    process_cqt(s);

    if (s->sono_h)

        s->update_sono(s->sono_frame, s->c_buf, s->sono_idx);

    if (!s->sono_count) {

        AVFrame *out = ff_get_video_buffer(outlink, outlink->w, outlink->h);

        if (!out)

            return AVERROR(ENOMEM);

        if (s->bar_h)

            s->draw_bar(out, s->h_buf, s->rcp_h_buf, s->c_buf, s->bar_h);

        if (s->axis_h)

            s->draw_axis(out, s->axis_frame, s->c_buf, s->bar_h);

        if (s->sono_h)

            s->draw_sono(out, s->sono_frame, s->bar_h + s->axis_h, s->sono_idx);

        out->pts = s->frame_count;

        ret = ff_filter_frame(outlink, out);

        s->frame_count++;

    }

    s->sono_count = (s->sono_count + 1) % s->count;

    if (s->sono_h)

        s->sono_idx = (s->sono_idx + s->sono_h - 1) % s->sono_h;

    return ret;

}

void avcodec_set_dimensions(AVCodecContext *s, int width, int height){

    s->coded_width = width;

    s->coded_height= height;

    s->width  = width;

    s->height = height;

}

static int cfhd_decode(AVCodecContext *avctx, void *data, int *got_frame,

                       AVPacket *avpkt)

{

    CFHDContext *s = avctx->priv_data;

    GetByteContext gb;

    ThreadFrame frame = { .f = data };

    AVFrame *pic = data;

    int ret = 0, i, j, planes, plane, got_buffer = 0;

    int16_t *coeff_data;



    s->coded_format = AV_PIX_FMT_YUV422P10;

    init_frame_defaults(s);

    planes = av_pix_fmt_count_planes(s->coded_format);



    bytestream2_init(&gb, avpkt->data, avpkt->size);



    while (bytestream2_get_bytes_left(&gb) > 4) {

        /* Bit weird but implement the tag parsing as the spec says */

        uint16_t tagu   = bytestream2_get_be16(&gb);

        int16_t tag     = (int16_t)tagu;

        int8_t tag8     = (int8_t)(tagu >> 8);

        uint16_t abstag = abs(tag);

        int8_t abs_tag8 = abs(tag8);

        uint16_t data   = bytestream2_get_be16(&gb);

        if (abs_tag8 >= 0x60 && abs_tag8 <= 0x6f) {

            av_log(avctx, AV_LOG_DEBUG, "large len %x\n", ((tagu & 0xff) << 16) | data);

        } else if (tag == 20) {

            av_log(avctx, AV_LOG_DEBUG, "Width %"PRIu16"\n", data);

            s->coded_width = data;

        } else if (tag == 21) {

            av_log(avctx, AV_LOG_DEBUG, "Height %"PRIu16"\n", data);

            s->coded_height = data;

        } else if (tag == 101) {

            av_log(avctx, AV_LOG_DEBUG, "Bits per component: %"PRIu16"\n", data);

            s->bpc = data;

        } else if (tag == 12) {

            av_log(avctx, AV_LOG_DEBUG, "Channel Count: %"PRIu16"\n", data);

            s->channel_cnt = data;

            if (data > 4) {

                av_log(avctx, AV_LOG_ERROR, "Channel Count of %"PRIu16" is unsupported\n", data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

        } else if (tag == 14) {

            av_log(avctx, AV_LOG_DEBUG, "Subband Count: %"PRIu16"\n", data);

            if (data != SUBBAND_COUNT) {

                av_log(avctx, AV_LOG_ERROR, "Subband Count of %"PRIu16" is unsupported\n", data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

        } else if (tag == 62) {

            s->channel_num = data;

            av_log(avctx, AV_LOG_DEBUG, "Channel number %"PRIu16"\n", data);

            if (s->channel_num >= planes) {

                av_log(avctx, AV_LOG_ERROR, "Invalid channel number\n");

                ret = AVERROR(EINVAL);

                break;

            }

            init_plane_defaults(s);

        } else if (tag == 48) {

            if (s->subband_num != 0 && data == 1)  // hack

                s->level++;

            av_log(avctx, AV_LOG_DEBUG, "Subband number %"PRIu16"\n", data);

            s->subband_num = data;

            if (s->level >= DWT_LEVELS) {

                av_log(avctx, AV_LOG_ERROR, "Invalid level\n");

                ret = AVERROR(EINVAL);

                break;

            }

            if (s->subband_num > 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid subband number\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 51) {

            av_log(avctx, AV_LOG_DEBUG, "Subband number actual %"PRIu16"\n", data);

            s->subband_num_actual = data;

            if (s->subband_num_actual >= 10) {

                av_log(avctx, AV_LOG_ERROR, "Invalid subband number actual\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 35)

            av_log(avctx, AV_LOG_DEBUG, "Lowpass precision bits: %"PRIu16"\n", data);

        else if (tag == 53) {

            s->quantisation = data;

            av_log(avctx, AV_LOG_DEBUG, "Quantisation: %"PRIu16"\n", data);

        } else if (tag == 109) {

            s->prescale_shift[0] = (data >> 0) & 0x7;

            s->prescale_shift[1] = (data >> 3) & 0x7;

            s->prescale_shift[2] = (data >> 6) & 0x7;

            av_log(avctx, AV_LOG_DEBUG, "Prescale shift (VC-5): %x\n", data);

        } else if (tag == 27) {

            s->plane[s->channel_num].band[0][0].width  = data;

            s->plane[s->channel_num].band[0][0].stride = data;

            av_log(avctx, AV_LOG_DEBUG, "Lowpass width %"PRIu16"\n", data);

            if (data < 3 || data > s->plane[s->channel_num].band[0][0].a_width) {

                av_log(avctx, AV_LOG_ERROR, "Invalid lowpass width\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 28) {

            s->plane[s->channel_num].band[0][0].height = data;

            av_log(avctx, AV_LOG_DEBUG, "Lowpass height %"PRIu16"\n", data);

            if (data < 3 || data > s->plane[s->channel_num].band[0][0].height) {

                av_log(avctx, AV_LOG_ERROR, "Invalid lowpass height\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 1)

            av_log(avctx, AV_LOG_DEBUG, "Sample type? %"PRIu16"\n", data);

        else if (tag == 10) {

            if (data != 0) {

                avpriv_report_missing_feature(avctx, "Transform type of %"PRIu16, data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

            av_log(avctx, AV_LOG_DEBUG, "Transform-type? %"PRIu16"\n", data);

        } else if (abstag >= 0x4000 && abstag <= 0x40ff) {

            av_log(avctx, AV_LOG_DEBUG, "Small chunk length %d %s\n", data * 4, tag < 0 ? "optional" : "required");

            bytestream2_skipu(&gb, data * 4);

        } else if (tag == 23) {

            av_log(avctx, AV_LOG_DEBUG, "Skip frame\n");

            avpriv_report_missing_feature(avctx, "Skip frame");

            ret = AVERROR_PATCHWELCOME;

            break;

        } else if (tag == 2) {

            av_log(avctx, AV_LOG_DEBUG, "tag=2 header - skipping %i tag/value pairs\n", data);

            if (data > bytestream2_get_bytes_left(&gb) / 4) {

                av_log(avctx, AV_LOG_ERROR, "too many tag/value pairs (%d)\n", data);

                ret = AVERROR_INVALIDDATA;

                break;

            }

            for (i = 0; i < data; i++) {

                uint16_t tag2 = bytestream2_get_be16(&gb);

                uint16_t val2 = bytestream2_get_be16(&gb);

                av_log(avctx, AV_LOG_DEBUG, "Tag/Value = %x %x\n", tag2, val2);

            }

        } else if (tag == 41) {

            s->plane[s->channel_num].band[s->level][s->subband_num].width  = data;

            s->plane[s->channel_num].band[s->level][s->subband_num].stride = FFALIGN(data, 8);

            av_log(avctx, AV_LOG_DEBUG, "Highpass width %i channel %i level %i subband %i\n", data, s->channel_num, s->level, s->subband_num);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass width\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 42) {

            s->plane[s->channel_num].band[s->level][s->subband_num].height = data;

            av_log(avctx, AV_LOG_DEBUG, "Highpass height %i\n", data);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass height\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 49) {

            s->plane[s->channel_num].band[s->level][s->subband_num].width  = data;

            s->plane[s->channel_num].band[s->level][s->subband_num].stride = FFALIGN(data, 8);

            av_log(avctx, AV_LOG_DEBUG, "Highpass width2 %i\n", data);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass width2\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 50) {

            s->plane[s->channel_num].band[s->level][s->subband_num].height = data;

            av_log(avctx, AV_LOG_DEBUG, "Highpass height2 %i\n", data);

            if (data < 3) {

                av_log(avctx, AV_LOG_ERROR, "Invalid highpass height2\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 71) {

            s->codebook = data;

            av_log(avctx, AV_LOG_DEBUG, "Codebook %i\n", s->codebook);

        } else if (tag == 72) {

            s->codebook = data;

            av_log(avctx, AV_LOG_DEBUG, "Other codebook? %i\n", s->codebook);

        } else if (tag == 70) {

            av_log(avctx, AV_LOG_DEBUG, "Subsampling or bit-depth flag? %i\n", data);

            s->bpc = data;

            if (!(s->bpc == 10 || s->bpc == 12)) {

                av_log(avctx, AV_LOG_ERROR, "Invalid bits per channel\n");

                ret = AVERROR(EINVAL);

                break;

            }

        } else if (tag == 84) {

            av_log(avctx, AV_LOG_DEBUG, "Sample format? %i\n", data);

            if (data == 1)

                s->coded_format = AV_PIX_FMT_YUV422P10;

            else if (data == 3)

                s->coded_format = AV_PIX_FMT_GBRP12;

            else if (data == 4)

                s->coded_format = AV_PIX_FMT_GBRAP12;

            else {

                avpriv_report_missing_feature(avctx, "Sample format of %"PRIu16, data);

                ret = AVERROR_PATCHWELCOME;

                break;

            }

            planes = av_pix_fmt_count_planes(s->coded_format);

        } else

            av_log(avctx, AV_LOG_DEBUG,  "Unknown tag %i data %x\n", tag, data);



        /* Some kind of end of header tag */

        if (tag == 4 && data == 0x1a4a && s->coded_width && s->coded_height &&

            s->coded_format != AV_PIX_FMT_NONE) {

            if (s->a_width != s->coded_width || s->a_height != s->coded_height ||

                s->a_format != s->coded_format) {

                free_buffers(avctx);

                if ((ret = alloc_buffers(avctx)) < 0) {

                    free_buffers(avctx);

                    return ret;

                }

            }

            ret = ff_set_dimensions(avctx, s->coded_width, s->coded_height);

            if (ret < 0)

                return ret;

            frame.f->width =

            frame.f->height = 0;



            if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0)

                return ret;



            s->coded_width = 0;

            s->coded_height = 0;

            s->coded_format = AV_PIX_FMT_NONE;

            got_buffer = 1;

        }

        coeff_data = s->plane[s->channel_num].subband[s->subband_num_actual];



        /* Lowpass coefficients */

        if (tag == 4 && data == 0xf0f && s->a_width && s->a_height) {

            int lowpass_height = s->plane[s->channel_num].band[0][0].height;

            int lowpass_width  = s->plane[s->channel_num].band[0][0].width;

            int lowpass_a_height = s->plane[s->channel_num].band[0][0].a_height;

            int lowpass_a_width  = s->plane[s->channel_num].band[0][0].a_width;



            if (!got_buffer) {

                av_log(avctx, AV_LOG_ERROR, "No end of header tag found\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            if (lowpass_height > lowpass_a_height || lowpass_width > lowpass_a_width ||

                lowpass_a_width * lowpass_a_height * sizeof(int16_t) > bytestream2_get_bytes_left(&gb)) {

                av_log(avctx, AV_LOG_ERROR, "Too many lowpass coefficients\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            av_log(avctx, AV_LOG_DEBUG, "Start of lowpass coeffs component %d height:%d, width:%d\n", s->channel_num, lowpass_height, lowpass_width);

            for (i = 0; i < lowpass_height; i++) {

                for (j = 0; j < lowpass_width; j++)

                    coeff_data[j] = bytestream2_get_be16u(&gb);



                coeff_data += lowpass_width;

            }



            /* Align to mod-4 position to continue reading tags */

            bytestream2_seek(&gb, bytestream2_tell(&gb) & 3, SEEK_CUR);



            /* Copy last line of coefficients if odd height */

            if (lowpass_height & 1) {

                memcpy(&coeff_data[lowpass_height * lowpass_width],

                       &coeff_data[(lowpass_height - 1) * lowpass_width],

                       lowpass_width * sizeof(*coeff_data));

            }



            av_log(avctx, AV_LOG_DEBUG, "Lowpass coefficients %d\n", lowpass_width * lowpass_height);

        }



        if (tag == 55 && s->subband_num_actual != 255 && s->a_width && s->a_height) {

            int highpass_height = s->plane[s->channel_num].band[s->level][s->subband_num].height;

            int highpass_width  = s->plane[s->channel_num].band[s->level][s->subband_num].width;

            int highpass_a_width = s->plane[s->channel_num].band[s->level][s->subband_num].a_width;

            int highpass_a_height = s->plane[s->channel_num].band[s->level][s->subband_num].a_height;

            int highpass_stride = s->plane[s->channel_num].band[s->level][s->subband_num].stride;

            int expected = highpass_height * highpass_stride;

            int a_expected = highpass_a_height * highpass_a_width;

            int level, run, coeff;

            int count = 0, bytes;



            if (!got_buffer) {

                av_log(avctx, AV_LOG_ERROR, "No end of header tag found\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            if (highpass_height > highpass_a_height || highpass_width > highpass_a_width || a_expected < expected) {

                av_log(avctx, AV_LOG_ERROR, "Too many highpass coefficients\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            av_log(avctx, AV_LOG_DEBUG, "Start subband coeffs plane %i level %i codebook %i expected %i\n", s->channel_num, s->level, s->codebook, expected);



            init_get_bits(&s->gb, gb.buffer, bytestream2_get_bytes_left(&gb) * 8);

            {

                OPEN_READER(re, &s->gb);

                if (!s->codebook) {

                    while (1) {

                        UPDATE_CACHE(re, &s->gb);

                        GET_RL_VLC(level, run, re, &s->gb, s->table_9_rl_vlc,

                                   VLC_BITS, 3, 1);



                        /* escape */

                        if (level == 64)

                            break;



                        count += run;



                        if (count > expected)

                            break;



                        coeff = dequant_and_decompand(level, s->quantisation);

                        for (i = 0; i < run; i++)

                            *coeff_data++ = coeff;

                    }

                } else {

                    while (1) {

                        UPDATE_CACHE(re, &s->gb);

                        GET_RL_VLC(level, run, re, &s->gb, s->table_18_rl_vlc,

                                   VLC_BITS, 3, 1);



                        /* escape */

                        if (level == 255 && run == 2)

                            break;



                        count += run;



                        if (count > expected)

                            break;



                        coeff = dequant_and_decompand(level, s->quantisation);

                        for (i = 0; i < run; i++)

                            *coeff_data++ = coeff;

                    }

                }

                CLOSE_READER(re, &s->gb);

            }



            if (count > expected) {

                av_log(avctx, AV_LOG_ERROR, "Escape codeword not found, probably corrupt data\n");

                ret = AVERROR(EINVAL);

                goto end;

            }



            bytes = FFALIGN(FF_CEIL_RSHIFT(get_bits_count(&s->gb), 3), 4);

            if (bytes > bytestream2_get_bytes_left(&gb)) {

                av_log(avctx, AV_LOG_ERROR, "Bitstream overread error\n");

                ret = AVERROR(EINVAL);

                goto end;

            } else

                bytestream2_seek(&gb, bytes, SEEK_CUR);



            av_log(avctx, AV_LOG_DEBUG, "End subband coeffs %i extra %i\n", count, count - expected);

            s->codebook = 0;



            /* Copy last line of coefficients if odd height */

            if (highpass_height & 1) {

                memcpy(&coeff_data[highpass_height * highpass_stride],

                       &coeff_data[(highpass_height - 1) * highpass_stride],

                       highpass_stride * sizeof(*coeff_data));

            }

        }

    }



    if (!s->a_width || !s->a_height || s->a_format == AV_PIX_FMT_NONE ||

        s->coded_width || s->coded_height || s->coded_format != AV_PIX_FMT_NONE) {

        av_log(avctx, AV_LOG_ERROR, "Invalid dimensions\n");

        ret = AVERROR(EINVAL);

        goto end;

    }



    if (!got_buffer) {

        av_log(avctx, AV_LOG_ERROR, "No end of header tag found\n");

        ret = AVERROR(EINVAL);

        goto end;

    }



    planes = av_pix_fmt_count_planes(avctx->pix_fmt);

    for (plane = 0; plane < planes && !ret; plane++) {

        /* level 1 */

        int lowpass_height  = s->plane[plane].band[0][0].height;

        int lowpass_width   = s->plane[plane].band[0][0].width;

        int highpass_stride = s->plane[plane].band[0][1].stride;

        int act_plane = plane == 1 ? 2 : plane == 2 ? 1 : plane;

        int16_t *low, *high, *output, *dst;



        if (lowpass_height > s->plane[plane].band[0][0].a_height || lowpass_width > s->plane[plane].band[0][0].a_width ||

            !highpass_stride || s->plane[plane].band[0][1].width > s->plane[plane].band[0][1].a_width) {

            av_log(avctx, AV_LOG_ERROR, "Invalid plane dimensions\n");

            ret = AVERROR(EINVAL);

            goto end;

        }



        av_log(avctx, AV_LOG_DEBUG, "Decoding level 1 plane %i %i %i %i\n", plane, lowpass_height, lowpass_width, highpass_stride);



        low    = s->plane[plane].subband[0];

        high   = s->plane[plane].subband[2];

        output = s->plane[plane].l_h[0];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, lowpass_width, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].subband[1];

        high   = s->plane[plane].subband[3];

        output = s->plane[plane].l_h[1];



        for (i = 0; i < lowpass_width; i++) {

            // note the stride of "low" is highpass_stride

            vert_filter(output, lowpass_width, low, highpass_stride, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].l_h[0];

        high   = s->plane[plane].l_h[1];

        output = s->plane[plane].subband[0];

        for (i = 0; i < lowpass_height * 2; i++) {

            horiz_filter(output, low, high, lowpass_width);

            low    += lowpass_width;

            high   += lowpass_width;

            output += lowpass_width * 2;

        }

        if (s->bpc == 12) {

            output = s->plane[plane].subband[0];

            for (i = 0; i < lowpass_height * 2; i++) {

                for (j = 0; j < lowpass_width * 2; j++)

                    output[j] <<= 2;



                output += lowpass_width * 2;

            }

        }



        /* level 2 */

        lowpass_height  = s->plane[plane].band[1][1].height;

        lowpass_width   = s->plane[plane].band[1][1].width;

        highpass_stride = s->plane[plane].band[1][1].stride;



        if (lowpass_height > s->plane[plane].band[1][1].a_height || lowpass_width > s->plane[plane].band[1][1].a_width ||

            !highpass_stride || s->plane[plane].band[1][1].width > s->plane[plane].band[1][1].a_width) {

            av_log(avctx, AV_LOG_ERROR, "Invalid plane dimensions\n");

            ret = AVERROR(EINVAL);

            goto end;

        }



        av_log(avctx, AV_LOG_DEBUG, "Level 2 plane %i %i %i %i\n", plane, lowpass_height, lowpass_width, highpass_stride);



        low    = s->plane[plane].subband[0];

        high   = s->plane[plane].subband[5];

        output = s->plane[plane].l_h[3];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, lowpass_width, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].subband[4];

        high   = s->plane[plane].subband[6];

        output = s->plane[plane].l_h[4];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, highpass_stride, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].l_h[3];

        high   = s->plane[plane].l_h[4];

        output = s->plane[plane].subband[0];

        for (i = 0; i < lowpass_height * 2; i++) {

            horiz_filter(output, low, high, lowpass_width);

            low    += lowpass_width;

            high   += lowpass_width;

            output += lowpass_width * 2;

        }



        output = s->plane[plane].subband[0];

        for (i = 0; i < lowpass_height * 2; i++) {

            for (j = 0; j < lowpass_width * 2; j++)

                output[j] <<= 2;



            output += lowpass_width * 2;

        }



        /* level 3 */

        lowpass_height  = s->plane[plane].band[2][1].height;

        lowpass_width   = s->plane[plane].band[2][1].width;

        highpass_stride = s->plane[plane].band[2][1].stride;



        if (lowpass_height > s->plane[plane].band[2][1].a_height || lowpass_width > s->plane[plane].band[2][1].a_width ||

            !highpass_stride || s->plane[plane].band[2][1].width > s->plane[plane].band[2][1].a_width) {

            av_log(avctx, AV_LOG_ERROR, "Invalid plane dimensions\n");

            ret = AVERROR(EINVAL);

            goto end;

        }



        av_log(avctx, AV_LOG_DEBUG, "Level 3 plane %i %i %i %i\n", plane, lowpass_height, lowpass_width, highpass_stride);



        low    = s->plane[plane].subband[0];

        high   = s->plane[plane].subband[8];

        output = s->plane[plane].l_h[6];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, lowpass_width, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        low    = s->plane[plane].subband[7];

        high   = s->plane[plane].subband[9];

        output = s->plane[plane].l_h[7];

        for (i = 0; i < lowpass_width; i++) {

            vert_filter(output, lowpass_width, low, highpass_stride, high, highpass_stride, lowpass_height);

            low++;

            high++;

            output++;

        }



        dst = (int16_t *)pic->data[act_plane];

        low  = s->plane[plane].l_h[6];

        high = s->plane[plane].l_h[7];

        for (i = 0; i < lowpass_height * 2; i++) {

            horiz_filter_clip(dst, low, high, lowpass_width, s->bpc);

            low  += lowpass_width;

            high += lowpass_width;

            dst  += pic->linesize[act_plane] / 2;

        }

    }





end:

    if (ret < 0)

        return ret;



    *got_frame = 1;

    return avpkt->size;

}

