int ff_pnm_decode_header(AVCodecContext *avctx, PNMContext * const s)

{

    char buf1[32], tuple_type[32];

    int h, w, depth, maxval;



    pnm_get(s, buf1, sizeof(buf1));

    s->type= buf1[1]-'0';

    if(buf1[0] != 'P')

        return -1;



    if (s->type==1 || s->type==4) {

        avctx->pix_fmt = PIX_FMT_MONOWHITE;

    } else if (s->type==2 || s->type==5) {

        if (avctx->codec_id == CODEC_ID_PGMYUV)

            avctx->pix_fmt = PIX_FMT_YUV420P;

        else

            avctx->pix_fmt = PIX_FMT_GRAY8;

    } else if (s->type==3 || s->type==6) {

        avctx->pix_fmt = PIX_FMT_RGB24;

    } else if (s->type==7) {

        w      = -1;

        h      = -1;

        maxval = -1;

        depth  = -1;

        tuple_type[0] = '\0';

        for (;;) {

            pnm_get(s, buf1, sizeof(buf1));

            if (!strcmp(buf1, "WIDTH")) {

                pnm_get(s, buf1, sizeof(buf1));

                w = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "HEIGHT")) {

                pnm_get(s, buf1, sizeof(buf1));

                h = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "DEPTH")) {

                pnm_get(s, buf1, sizeof(buf1));

                depth = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "MAXVAL")) {

                pnm_get(s, buf1, sizeof(buf1));

                maxval = strtol(buf1, NULL, 10);

            } else if (!strcmp(buf1, "TUPLTYPE") ||

            // FFmpeg used to write invalid files

                       !strcmp(buf1, "TUPLETYPE")) {

                pnm_get(s, tuple_type, sizeof(tuple_type));

            } else if (!strcmp(buf1, "ENDHDR")) {

                break;

            } else {

                return -1;

            }

        }

        /* check that all tags are present */

        if (w <= 0 || h <= 0 || maxval <= 0 || depth <= 0 || tuple_type[0] == '\0' || av_image_check_size(w, h, 0, avctx))

            return -1;



        avctx->width  = w;

        avctx->height = h;


        if (depth == 1) {

            if (maxval == 1)

                avctx->pix_fmt = PIX_FMT_MONOWHITE;

            else

                avctx->pix_fmt = PIX_FMT_GRAY8;

        } else if (depth == 3) {

            if (maxval < 256) {

            avctx->pix_fmt = PIX_FMT_RGB24;

            } else {

                av_log(avctx, AV_LOG_ERROR, "16-bit components are only supported for grayscale\n");

                avctx->pix_fmt = PIX_FMT_NONE;

                return -1;

            }

        } else if (depth == 4) {

            avctx->pix_fmt = PIX_FMT_RGB32;

        } else {

            return -1;

        }

        return 0;

    } else {

        return -1;

    }

    pnm_get(s, buf1, sizeof(buf1));

    avctx->width = atoi(buf1);

    if (avctx->width <= 0)

        return -1;

    pnm_get(s, buf1, sizeof(buf1));

    avctx->height = atoi(buf1);

    if(avctx->height <= 0 || av_image_check_size(avctx->width, avctx->height, 0, avctx))

        return -1;

    if (avctx->pix_fmt != PIX_FMT_MONOWHITE) {

        pnm_get(s, buf1, sizeof(buf1));

        s->maxval = atoi(buf1);

        if (s->maxval <= 0) {

            av_log(avctx, AV_LOG_ERROR, "Invalid maxval: %d\n", s->maxval);

            s->maxval = 255;

        }

        if (s->maxval >= 256) {

            if (avctx->pix_fmt == PIX_FMT_GRAY8) {

                avctx->pix_fmt = PIX_FMT_GRAY16BE;

                if (s->maxval != 65535)

                    avctx->pix_fmt = PIX_FMT_GRAY16;

            } else if (avctx->pix_fmt == PIX_FMT_RGB24) {

                if (s->maxval > 255)

                    avctx->pix_fmt = PIX_FMT_RGB48BE;

            } else {

                av_log(avctx, AV_LOG_ERROR, "Unsupported pixel format\n");

                avctx->pix_fmt = PIX_FMT_NONE;

                return -1;

            }

        }

    }else

        s->maxval=1;

    /* more check if YUV420 */

    if (avctx->pix_fmt == PIX_FMT_YUV420P) {

        if ((avctx->width & 1) != 0)

            return -1;

        h = (avctx->height * 2);

        if ((h % 3) != 0)

            return -1;

        h /= 3;

        avctx->height = h;

    }

    return 0;

}

void *fw_cfg_modify_file(FWCfgState *s, const char *filename,

                        void *data, size_t len)

{

    int i, index;

    void *ptr = NULL;



    assert(s->files);



    index = be32_to_cpu(s->files->count);

    assert(index < fw_cfg_file_slots(s));



    for (i = 0; i < index; i++) {

        if (strcmp(filename, s->files->f[i].name) == 0) {

            ptr = fw_cfg_modify_bytes_read(s, FW_CFG_FILE_FIRST + i,

                                           data, len);

            s->files->f[i].size   = cpu_to_be32(len);

            return ptr;

        }

    }

    /* add new one */

    fw_cfg_add_file_callback(s, filename, NULL, NULL, NULL, data, len, true);

    return NULL;

}

