void ff_free_parser_state(AVFormatContext *s, AVParserState *state)

{

    int i;

    AVParserStreamState *ss;



    if (!state)

        return;



    for (i = 0; i < state->nb_streams; i++) {

        ss = &state->stream_states[i];

        if (ss->parser)

            av_parser_close(ss->parser);

        av_free_packet(&ss->cur_pkt);

    }



    free_packet_list(state->packet_buffer);

    free_packet_list(state->raw_packet_buffer);



    av_free(state->stream_states);

    av_free(state);

}

static void intra_predict_vert_dc_8x8_msa(uint8_t *src, int32_t stride)

{

    uint8_t lp_cnt;

    uint32_t out0 = 0, out1 = 0;

    v16u8 src_top;

    v8u16 add;

    v4u32 sum;

    v4i32 res0, res1;



    src_top = LD_UB(src - stride);

    add = __msa_hadd_u_h(src_top, src_top);

    sum = __msa_hadd_u_w(add, add);

    sum = (v4u32) __msa_srari_w((v4i32) sum, 2);

    res0 = (v4i32) __msa_splati_b((v16i8) sum, 0);

    res1 = (v4i32) __msa_splati_b((v16i8) sum, 4);

    out0 = __msa_copy_u_w(res0, 0);

    out1 = __msa_copy_u_w(res1, 0);



    for (lp_cnt = 8; lp_cnt--;) {

        SW(out0, src);

        SW(out1, src + 4);

        src += stride;

    }

}

static void pcie_pci_bridge_realize(PCIDevice *d, Error **errp)

{

    PCIBridge *br = PCI_BRIDGE(d);

    PCIEPCIBridge *pcie_br = PCIE_PCI_BRIDGE_DEV(d);

    int rc, pos;



    pci_bridge_initfn(d, TYPE_PCI_BUS);



    d->config[PCI_INTERRUPT_PIN] = 0x1;

    memory_region_init(&pcie_br->shpc_bar, OBJECT(d), "shpc-bar",

                       shpc_bar_size(d));

    rc = shpc_init(d, &br->sec_bus, &pcie_br->shpc_bar, 0, errp);

    if (rc) {

        goto error;

    }



    rc = pcie_cap_init(d, 0, PCI_EXP_TYPE_PCI_BRIDGE, 0, errp);

    if (rc < 0) {

        goto cap_error;

    }



    pos = pci_add_capability(d, PCI_CAP_ID_PM, 0, PCI_PM_SIZEOF, errp);

    if (pos < 0) {

        goto pm_error;

    }

    d->exp.pm_cap = pos;

    pci_set_word(d->config + pos + PCI_PM_PMC, 0x3);



    pcie_cap_arifwd_init(d);

    pcie_cap_deverr_init(d);



    rc = pcie_aer_init(d, PCI_ERR_VER, 0x100, PCI_ERR_SIZEOF, errp);

    if (rc < 0) {

        goto aer_error;

    }



    if (pcie_br->msi != ON_OFF_AUTO_OFF) {

        rc = msi_init(d, 0, 1, true, true, errp);

        if (rc < 0) {

            goto msi_error;

        }

    }

    pci_register_bar(d, 0, PCI_BASE_ADDRESS_SPACE_MEMORY |

                     PCI_BASE_ADDRESS_MEM_TYPE_64, &pcie_br->shpc_bar);

    return;



msi_error:

    pcie_aer_exit(d);

aer_error:

pm_error:

    pcie_cap_exit(d);

cap_error:

    shpc_free(d);

error:

    pci_bridge_exitfn(d);

}

