static void test_primitives(gconstpointer opaque)

{

    TestArgs *args = (TestArgs *) opaque;

    const SerializeOps *ops = args->ops;

    PrimitiveType *pt = args->test_data;

    PrimitiveType *pt_copy = g_malloc0(sizeof(*pt_copy));

    Error *err = NULL;

    void *serialize_data;



    pt_copy->type = pt->type;

    ops->serialize(pt, &serialize_data, visit_primitive_type, &err);

    ops->deserialize((void **)&pt_copy, serialize_data, visit_primitive_type, &err);



    g_assert(err == NULL);

    g_assert(pt_copy != NULL);

    if (pt->type == PTYPE_STRING) {

        g_assert_cmpstr(pt->value.string, ==, pt_copy->value.string);

        g_free((char *)pt_copy->value.string);

    } else if (pt->type == PTYPE_NUMBER) {

        GString *double_expected = g_string_new("");

        GString *double_actual = g_string_new("");

        /* we serialize with %f for our reference visitors, so rather than fuzzy

         * floating math to test "equality", just compare the formatted values

         */

        g_string_printf(double_expected, "%.6f", pt->value.number);

        g_string_printf(double_actual, "%.6f", pt_copy->value.number);

        g_assert_cmpstr(double_actual->str, ==, double_expected->str);



        g_string_free(double_expected, true);

        g_string_free(double_actual, true);

    } else if (pt->type == PTYPE_BOOLEAN) {

        g_assert_cmpint(!!pt->value.max, ==, !!pt->value.max);

    } else {

        g_assert_cmpint(pt->value.max, ==, pt_copy->value.max);

    }



    ops->cleanup(serialize_data);

    g_free(args);

    g_free(pt_copy);

}

static int sort_stt(FFV1Context *s, uint8_t stt[256])

{

    int i, i2, changed, print = 0;



    do {

        changed = 0;

        for (i = 12; i < 244; i++) {

            for (i2 = i + 1; i2 < 245 && i2 < i + 4; i2++) {



#define COST(old, new)                                      \

    s->rc_stat[old][0] * -log2((256 - (new)) / 256.0) +     \

    s->rc_stat[old][1] * -log2((new)         / 256.0)



#define COST2(old, new)                         \

    COST(old, new) + COST(256 - (old), 256 - (new))



                double size0 = COST2(i,  i) + COST2(i2, i2);

                double sizeX = COST2(i, i2) + COST2(i2, i);

                if (sizeX < size0 && i != 128 && i2 != 128) {

                    int j;

                    FFSWAP(int, stt[i], stt[i2]);

                    FFSWAP(int, s->rc_stat[i][0], s->rc_stat[i2][0]);

                    FFSWAP(int, s->rc_stat[i][1], s->rc_stat[i2][1]);

                    if (i != 256 - i2) {

                        FFSWAP(int, stt[256 - i], stt[256 - i2]);

                        FFSWAP(int, s->rc_stat[256 - i][0], s->rc_stat[256 - i2][0]);

                        FFSWAP(int, s->rc_stat[256 - i][1], s->rc_stat[256 - i2][1]);

                    }

                    for (j = 1; j < 256; j++) {

                        if (stt[j] == i)

                            stt[j] = i2;

                        else if (stt[j] == i2)

                            stt[j] = i;

                        if (i != 256 - i2) {

                            if (stt[256 - j] == 256 - i)

                                stt[256 - j] = 256 - i2;

                            else if (stt[256 - j] == 256 - i2)

                                stt[256 - j] = 256 - i;

                        }

                    }

                    print = changed = 1;

                }

            }

        }

    } while (changed);

    return print;

}

static inline void gen_cmps(DisasContext *s, int ot)

{

