        gen_op_addw_EDI_T0();

    }

}

static void qht_bucket_reset__locked(struct qht_bucket *head)

{

    struct qht_bucket *b = head;

    int i;



    seqlock_write_begin(&head->sequence);

    do {

        for (i = 0; i < QHT_BUCKET_ENTRIES; i++) {

            if (b->pointers[i] == NULL) {

                goto done;

            }

            b->hashes[i] = 0;

            atomic_set(&b->pointers[i], NULL);

        }

        b = b->next;

    } while (b);

 done:

    seqlock_write_end(&head->sequence);

}

static void check_threshold_8(void){

    LOCAL_ALIGNED_32(uint8_t, in       , [WIDTH_PADDED]);

    LOCAL_ALIGNED_32(uint8_t, threshold, [WIDTH_PADDED]);

    LOCAL_ALIGNED_32(uint8_t, min      , [WIDTH_PADDED]);

    LOCAL_ALIGNED_32(uint8_t, max      , [WIDTH_PADDED]);

    LOCAL_ALIGNED_32(uint8_t, out_ref  , [WIDTH_PADDED]);

    LOCAL_ALIGNED_32(uint8_t, out_new  , [WIDTH_PADDED]);

    ptrdiff_t line_size = WIDTH_PADDED;

    int w = WIDTH;



    ThresholdContext s;

    s.depth = 8;

    ff_threshold_init(&s);



    declare_func(void, const uint8_t *in, const uint8_t *threshold,

                 const uint8_t *min, const uint8_t *max, uint8_t *out,

                 ptrdiff_t ilinesize, ptrdiff_t tlinesize,

                 ptrdiff_t flinesize, ptrdiff_t slinesize,

                 ptrdiff_t olinesize, int w, int h);



    memset(in,     0, WIDTH_PADDED);

    memset(threshold, 0, WIDTH_PADDED);

    memset(min, 0, WIDTH_PADDED);

    memset(max, 0, WIDTH_PADDED);

    memset(out_ref, 0, WIDTH_PADDED);

    memset(out_new, 0, WIDTH_PADDED);

    randomize_buffers(in, WIDTH);

    randomize_buffers(threshold, WIDTH);

    randomize_buffers(min, WIDTH);

    randomize_buffers(max, WIDTH);



    if (check_func(s.threshold, "threshold8")) {

        call_ref(in, threshold, min, max, out_ref, line_size, line_size, line_size, line_size, line_size, w, 1);

        call_new(in, threshold, min, max, out_new, line_size, line_size, line_size, line_size, line_size, w, 1);

        if (memcmp(out_ref, out_new, w))

            fail();

        bench_new(in, threshold, min, max, out_new, line_size, line_size, line_size, line_size, line_size, w, 1);

    }

}

static int parse_read_interval(const char *interval_spec,

                               ReadInterval *interval)

{

    int ret = 0;

    char *next, *p, *spec = av_strdup(interval_spec);

    if (!spec)

        return AVERROR(ENOMEM);



    if (!*spec) {

        av_log(NULL, AV_LOG_ERROR, "Invalid empty interval specification\n");

        ret = AVERROR(EINVAL);

        goto end;

    }



    p = spec;

    next = strchr(spec, '%');

    if (next)

        *next++ = 0;



    /* parse first part */

    if (*p) {

        interval->has_start = 1;



        if (*p == '+') {

            interval->start_is_offset = 1;

            p++;

        } else {

            interval->start_is_offset = 0;

        }



        ret = av_parse_time(&interval->start, p, 1);

        if (ret < 0) {

            av_log(NULL, AV_LOG_ERROR, "Invalid interval start specification '%s'\n", p);

            goto end;

        }

    } else {

        interval->has_start = 0;

    }



    /* parse second part */

    p = next;

    if (p && *p) {

        int64_t us;

        interval->has_end = 1;



        if (*p == '+') {

            interval->end_is_offset = 1;

            p++;

        } else {

            interval->end_is_offset = 0;

        }



        if (interval->end_is_offset && *p == '#') {

            long long int lli;

            char *tail;

            interval->duration_frames = 1;

            p++;

            lli = strtoll(p, &tail, 10);

            if (*tail || lli < 0) {

                av_log(NULL, AV_LOG_ERROR,

                       "Invalid or negative value '%s' for duration number of frames\n", p);

                goto end;

            }

            interval->end = lli;

        } else {


            ret = av_parse_time(&us, p, 1);

            if (ret < 0) {

                av_log(NULL, AV_LOG_ERROR, "Invalid interval end/duration specification '%s'\n", p);

                goto end;

            }

            interval->end = us;

        }

    } else {

        interval->has_end = 0;

    }



end:

    av_free(spec);

    return ret;

}

static void m5206_mbar_writeb(void *opaque, target_phys_addr_t offset,

                              uint32_t value)

{

    m5206_mbar_state *s = (m5206_mbar_state *)opaque;

    int width;

    offset &= 0x3ff;

    if (offset >= 0x200) {

        hw_error("Bad MBAR write offset 0x%x", (int)offset);

    }

    width = m5206_mbar_width[offset >> 2];

    if (width > 1) {

        uint32_t tmp;

        tmp = m5206_mbar_readw(opaque, offset & ~1);

        if (offset & 1) {

            tmp = (tmp & 0xff00) | value;

        } else {

            tmp = (tmp & 0x00ff) | (value << 8);

        }

        m5206_mbar_writew(opaque, offset & ~1, tmp);

        return;

    }

    m5206_mbar_write(s, offset, value, 1);

}

static int stdio_pclose(void *opaque)

{

    QEMUFileStdio *s = opaque;

    int ret;

    ret = pclose(s->stdio_file);

    if (ret == -1) {

        ret = -errno;

    } else if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {

        /* close succeeded, but non-zero exit code: */

        ret = -EIO; /* fake errno value */

    }

    g_free(s);

    return ret;

}

static int h264_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    H264Context *h     = avctx->priv_data;

    AVFrame *pict      = data;

    int buf_index      = 0;

    int ret;

    const uint8_t *new_extradata;

    int new_extradata_size;



    h->flags = avctx->flags;

    h->setup_finished = 0;



    /* end of stream, output what is still in the buffers */

out:

    if (buf_size == 0) {

        H264Picture *out;

        int i, out_idx;



        h->cur_pic_ptr = NULL;



        // FIXME factorize this with the output code below

        out     = h->delayed_pic[0];

        out_idx = 0;

        for (i = 1;

             h->delayed_pic[i] &&

             !h->delayed_pic[i]->f->key_frame &&

             !h->delayed_pic[i]->mmco_reset;

             i++)

            if (h->delayed_pic[i]->poc < out->poc) {

                out     = h->delayed_pic[i];

                out_idx = i;

            }



        for (i = out_idx; h->delayed_pic[i]; i++)

            h->delayed_pic[i] = h->delayed_pic[i + 1];



        if (out) {

            ret = output_frame(h, pict, out->f);

            if (ret < 0)

                return ret;

            *got_frame = 1;

        }



        return buf_index;

    }



    new_extradata_size = 0;

    new_extradata = av_packet_get_side_data(avpkt, AV_PKT_DATA_NEW_EXTRADATA,

                                            &new_extradata_size);

    if (new_extradata_size > 0 && new_extradata) {

        ret = ff_h264_decode_extradata(new_extradata, new_extradata_size,

                                       &h->ps, &h->is_avc, &h->nal_length_size,

                                       avctx->err_recognition, avctx);

        if (ret < 0)

            return ret;

    }



    buf_index = decode_nal_units(h, buf, buf_size);

    if (buf_index < 0)

        return AVERROR_INVALIDDATA;



    if (!h->cur_pic_ptr && h->nal_unit_type == NAL_END_SEQUENCE) {

        buf_size = 0;

        goto out;

    }



    if (!(avctx->flags2 & AV_CODEC_FLAG2_CHUNKS) && !h->cur_pic_ptr) {

        if (avctx->skip_frame >= AVDISCARD_NONREF)

            return 0;

        av_log(avctx, AV_LOG_ERROR, "no frame!\n");

        return AVERROR_INVALIDDATA;

    }



    if (!(avctx->flags2 & AV_CODEC_FLAG2_CHUNKS) ||

        (h->mb_y >= h->mb_height && h->mb_height)) {

        if (avctx->flags2 & AV_CODEC_FLAG2_CHUNKS)

            decode_postinit(h, 1);



        ff_h264_field_end(h, &h->slice_ctx[0], 0);



        *got_frame = 0;

        if (h->next_output_pic && ((avctx->flags & AV_CODEC_FLAG_OUTPUT_CORRUPT) ||

                                   h->next_output_pic->recovered)) {

            if (!h->next_output_pic->recovered)

                h->next_output_pic->f->flags |= AV_FRAME_FLAG_CORRUPT;



            ret = output_frame(h, pict, h->next_output_pic->f);

            if (ret < 0)

                return ret;

            *got_frame = 1;

        }

    }



    assert(pict->buf[0] || !*got_frame);



    return get_consumed_bytes(buf_index, buf_size);

}

static void xics_reset(DeviceState *d)

{

    XICSState *icp = XICS(d);

    int i;



    for (i = 0; i < icp->nr_servers; i++) {

        device_reset(DEVICE(&icp->ss[i]));

    }



    device_reset(DEVICE(icp->ics));

}

static int opus_packet(AVFormatContext *avf, int idx)

{

    struct ogg *ogg              = avf->priv_data;

    struct ogg_stream *os        = &ogg->streams[idx];

    AVStream *st                 = avf->streams[idx];

    struct oggopus_private *priv = os->private;

    uint8_t *packet              = os->buf + os->pstart;

    int ret;



    if (!os->psize)

        return AVERROR_INVALIDDATA;

    if (os->granule > INT64_MAX - UINT32_MAX) {

        av_log(avf, AV_LOG_ERROR, "Unsupported huge granule pos %"PRId64 "\n", os->granule);

        return AVERROR_INVALIDDATA;

    }



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) && !(os->flags & OGG_FLAG_EOS)) {

        int seg, d;

        int duration;

        uint8_t *last_pkt  = os->buf + os->pstart;

        uint8_t *next_pkt  = last_pkt;



        duration = 0;

        seg = os->segp;

        d = opus_duration(last_pkt, os->psize);

        if (d < 0) {

            os->pflags |= AV_PKT_FLAG_CORRUPT;

            return 0;

        }

        duration += d;

        last_pkt = next_pkt =  next_pkt + os->psize;

        for (; seg < os->nsegs; seg++) {

            next_pkt += os->segments[seg];

            if (os->segments[seg] < 255 && next_pkt != last_pkt) {

                int d = opus_duration(last_pkt, next_pkt - last_pkt);

                if (d > 0)

                    duration += d;

                last_pkt = next_pkt;

            }

        }

        os->lastpts                 =

        os->lastdts                 = os->granule - duration;

    }



    if ((ret = opus_duration(packet, os->psize)) < 0)

        return ret;



    os->pduration = ret;

    if (os->lastpts != AV_NOPTS_VALUE) {

        if (st->start_time == AV_NOPTS_VALUE)

            st->start_time = os->lastpts;

        priv->cur_dts = os->lastdts = os->lastpts -= priv->pre_skip;

    }



    priv->cur_dts += os->pduration;

    if ((os->flags & OGG_FLAG_EOS)) {

        int64_t skip = priv->cur_dts - os->granule + priv->pre_skip;

        skip = FFMIN(skip, os->pduration);

        if (skip > 0) {

            os->pduration = skip < os->pduration ? os->pduration - skip : 1;

            os->end_trimming = skip;

            av_log(avf, AV_LOG_DEBUG,

                   "Last packet was truncated to %d due to end trimming.\n",

                   os->pduration);

        }

    }



    return 0;

}

static int mkv_field_order(MatroskaDemuxContext *matroska, int64_t field_order)

{

    int major, minor, micro, bttb = 0;



    /* workaround a bug in our Matroska muxer, introduced in version 57.36 alongside

     * this function, and fixed in 57.52 */

    if (sscanf(matroska->muxingapp, "Lavf%d.%d.%d", &major, &minor, &micro) == 3)

        bttb = (major == 57 && minor >= 36 && minor <= 51 && micro >= 100);



    switch (field_order) {

    case MATROSKA_VIDEO_FIELDORDER_PROGRESSIVE:

        return AV_FIELD_PROGRESSIVE;

    case MATROSKA_VIDEO_FIELDORDER_UNDETERMINED:

        return AV_FIELD_UNKNOWN;

    case MATROSKA_VIDEO_FIELDORDER_TT:

        return AV_FIELD_TT;

    case MATROSKA_VIDEO_FIELDORDER_BB:

        return AV_FIELD_BB;

    case MATROSKA_VIDEO_FIELDORDER_BT:

        return bttb ? AV_FIELD_TB : AV_FIELD_BT;

    case MATROSKA_VIDEO_FIELDORDER_TB:

        return bttb ? AV_FIELD_BT : AV_FIELD_TB;

    default:

        return AV_FIELD_UNKNOWN;

    }

}

static void float_number(void)

{

    int i;

    struct {

        const char *encoded;

        double decoded;

        int skip;

    } test_cases[] = {

        { "32.43", 32.43 },

        { "0.222", 0.222 },

        { "-32.12313", -32.12313 },

        { "-32.20e-10", -32.20e-10, .skip = 1 },

        { },

    };



    for (i = 0; test_cases[i].encoded; i++) {

        QObject *obj;

        QFloat *qfloat;



        obj = qobject_from_json(test_cases[i].encoded);

        g_assert(obj != NULL);

        g_assert(qobject_type(obj) == QTYPE_QFLOAT);



        qfloat = qobject_to_qfloat(obj);

        g_assert(qfloat_get_double(qfloat) == test_cases[i].decoded);



        if (test_cases[i].skip == 0) {

            QString *str;



            str = qobject_to_json(obj);

            g_assert(strcmp(qstring_get_str(str), test_cases[i].encoded) == 0);

            QDECREF(str);

        }



        QDECREF(qfloat);

    }

}

static void chr_read(void *opaque, const void *buf, size_t size)

{

    VirtIORNG *vrng = opaque;

    size_t len;

    int offset;



    if (!is_guest_ready(vrng)) {

        return;

    }



    offset = 0;

    while (offset < size) {

        if (!pop_an_elem(vrng)) {

            break;

        }

        len = iov_from_buf(vrng->elem.in_sg, vrng->elem.in_num,

                           0, buf + offset, size - offset);

        offset += len;



        virtqueue_push(vrng->vq, &vrng->elem, len);

        vrng->popped = false;

    }

    virtio_notify(&vrng->vdev, vrng->vq);



    /*

     * Lastly, if we had multiple elems queued by the guest, and we

     * didn't have enough data to fill them all, indicate we want more

     * data.

     */

    len = pop_an_elem(vrng);

    if (len) {

        rng_backend_request_entropy(vrng->rng, size, chr_read, vrng);

    }

}

