static int dirac_decode_data_unit(AVCodecContext *avctx, const uint8_t *buf, int size)

{

    DiracContext *s   = avctx->priv_data;

    DiracFrame *pic   = NULL;

    int ret, i, parse_code = buf[4];

    unsigned tmp;



    if (size < DATA_UNIT_HEADER_SIZE)

        return -1;



    init_get_bits(&s->gb, &buf[13], 8*(size - DATA_UNIT_HEADER_SIZE));



    if (parse_code == pc_seq_header) {

        if (s->seen_sequence_header)

            return 0;



        /* [DIRAC_STD] 10. Sequence header */

        if (avpriv_dirac_parse_sequence_header(avctx, &s->gb, &s->source))

            return -1;



        avcodec_get_chroma_sub_sample(avctx->pix_fmt, &s->chroma_x_shift, &s->chroma_y_shift);



        if (alloc_sequence_buffers(s))

            return -1;



        s->seen_sequence_header = 1;

    } else if (parse_code == pc_eos) { /* [DIRAC_STD] End of Sequence */

        free_sequence_buffers(s);

        s->seen_sequence_header = 0;

    } else if (parse_code == pc_aux_data) {

        if (buf[13] == 1) {     /* encoder implementation/version */

            int ver[3];

            /* versions older than 1.0.8 don't store quant delta for

               subbands with only one codeblock */

            if (sscanf(buf+14, "Schroedinger %d.%d.%d", ver, ver+1, ver+2) == 3)

                if (ver[0] == 1 && ver[1] == 0 && ver[2] <= 7)

                    s->old_delta_quant = 1;

        }

    } else if (parse_code & 0x8) {  /* picture data unit */

        if (!s->seen_sequence_header) {

            av_log(avctx, AV_LOG_DEBUG, "Dropping frame without sequence header\n");

            return -1;

        }



        /* find an unused frame */

        for (i = 0; i < MAX_FRAMES; i++)

            if (s->all_frames[i].avframe->data[0] == NULL)

                pic = &s->all_frames[i];

        if (!pic) {

            av_log(avctx, AV_LOG_ERROR, "framelist full\n");

            return -1;

        }



        av_frame_unref(pic->avframe);



        /* [DIRAC_STD] Defined in 9.6.1 ... */

        tmp            =  parse_code & 0x03;                   /* [DIRAC_STD] num_refs()      */

        if (tmp > 2) {

            av_log(avctx, AV_LOG_ERROR, "num_refs of 3\n");

            return -1;

        }

        s->num_refs    = tmp;

        s->is_arith    = (parse_code & 0x48) == 0x08;          /* [DIRAC_STD] using_ac()      */

        s->low_delay   = (parse_code & 0x88) == 0x88;          /* [DIRAC_STD] is_low_delay()  */

        pic->avframe->reference = (parse_code & 0x0C) == 0x0C;  /* [DIRAC_STD]  is_reference() */

        pic->avframe->key_frame = s->num_refs == 0;             /* [DIRAC_STD] is_intra()      */

        pic->avframe->pict_type = s->num_refs + 1;              /* Definition of AVPictureType in avutil.h */



        if ((ret = get_buffer_with_edge(avctx, pic->avframe, (parse_code & 0x0C) == 0x0C ? AV_GET_BUFFER_FLAG_REF : 0)) < 0)

            return ret;

        s->current_picture = pic;

        s->plane[0].stride = pic->avframe->linesize[0];

        s->plane[1].stride = pic->avframe->linesize[1];

        s->plane[2].stride = pic->avframe->linesize[2];



        if (alloc_buffers(s, FFMAX3(FFABS(s->plane[0].stride), FFABS(s->plane[1].stride), FFABS(s->plane[2].stride))) < 0)

            return AVERROR(ENOMEM);



        /* [DIRAC_STD] 11.1 Picture parse. picture_parse() */

        if (dirac_decode_picture_header(s))

            return -1;



        /* [DIRAC_STD] 13.0 Transform data syntax. transform_data() */

        if (dirac_decode_frame_internal(s))

            return -1;

    }

    return 0;

}

static int h264_parse(AVCodecParserContext *s,

                      AVCodecContext *avctx,

                      uint8_t **poutbuf, int *poutbuf_size,

                      const uint8_t *buf, int buf_size)

{

    H264Context *h = s->priv_data;

    ParseContext *pc = &h->s.parse_context;

    int next;



    if(s->flags & PARSER_FLAG_COMPLETE_FRAMES){

        next= buf_size;

    }else{

        next= find_frame_end(h, buf, buf_size);



        if (ff_combine_frame(pc, next, (uint8_t **)&buf, &buf_size) < 0) {

            *poutbuf = NULL;

            *poutbuf_size = 0;

            return buf_size;

        }



        if(next<0){

            find_frame_end(h, &pc->buffer[pc->last_index + next], -next); //update state

        }

    }



    *poutbuf = (uint8_t *)buf;

    *poutbuf_size = buf_size;

    return next;

}

void kqemu_flush_page(CPUState *env, target_ulong addr)

{

    LOG_INT("kqemu_flush_page: addr=" TARGET_FMT_lx "\n", addr);

    if (nb_pages_to_flush >= KQEMU_MAX_PAGES_TO_FLUSH)

        nb_pages_to_flush = KQEMU_FLUSH_ALL;

    else

        pages_to_flush[nb_pages_to_flush++] = addr;

}

static void icp_set_cppr(struct icp_state *icp, int server, uint8_t cppr)

{

    struct icp_server_state *ss = icp->ss + server;

    uint8_t old_cppr;

    uint32_t old_xisr;



    old_cppr = CPPR(ss);

    ss->xirr = (ss->xirr & ~CPPR_MASK) | (cppr << 24);



    if (cppr < old_cppr) {

        if (XISR(ss) && (cppr <= ss->pending_priority)) {

            old_xisr = XISR(ss);

            ss->xirr &= ~XISR_MASK; /* Clear XISR */


            qemu_irq_lower(ss->output);

            ics_reject(icp->ics, old_xisr);

        }

    } else {

        if (!XISR(ss)) {

            icp_resend(icp, server);

        }

    }

}

int av_set_string3(void *obj, const char *name, const char *val, int alloc, const AVOption **o_out)

{

    int ret;

    const AVOption *o = av_opt_find(obj, name, NULL, 0, 0);

    if (o_out)

        *o_out = o;

    if (!o)

        return AVERROR_OPTION_NOT_FOUND;

    if (!val || o->offset<=0)

        return AVERROR(EINVAL);



    if (o->type == FF_OPT_TYPE_BINARY) {

        uint8_t **dst = (uint8_t **)(((uint8_t*)obj) + o->offset);

        int *lendst = (int *)(dst + 1);

        uint8_t *bin, *ptr;

        int len = strlen(val);

        av_freep(dst);

        *lendst = 0;

        if (len & 1) return AVERROR(EINVAL);

        len /= 2;

        ptr = bin = av_malloc(len);

        while (*val) {

            int a = hexchar2int(*val++);

            int b = hexchar2int(*val++);

            if (a < 0 || b < 0) {

                av_free(bin);

                return AVERROR(EINVAL);

            }

            *ptr++ = (a << 4) | b;

        }

        *dst = bin;

        *lendst = len;

        return 0;

    }

    if (o->type != FF_OPT_TYPE_STRING) {

        int notfirst=0;

        for (;;) {

            int i;

            char buf[256];

            int cmd=0;

            double d;



            if (*val == '+' || *val == '-')

                cmd= *(val++);



            for (i=0; i<sizeof(buf)-1 && val[i] && val[i]!='+' && val[i]!='-'; i++)

                buf[i]= val[i];

            buf[i]=0;



            {

                const AVOption *o_named = av_opt_find(obj, buf, o->unit, 0, 0);

                if (o_named && o_named->type == FF_OPT_TYPE_CONST)

                    d= o_named->default_val.dbl;

                else if (!strcmp(buf, "default")) d= o->default_val.dbl;

                else if (!strcmp(buf, "max"    )) d= o->max;

                else if (!strcmp(buf, "min"    )) d= o->min;

                else if (!strcmp(buf, "none"   )) d= 0;

                else if (!strcmp(buf, "all"    )) d= ~0;

                else {

                    int res = av_expr_parse_and_eval(&d, buf, const_names, const_values, NULL, NULL, NULL, NULL, NULL, 0, obj);

                    if (res < 0) {

                        av_log(obj, AV_LOG_ERROR, "Unable to parse option value \"%s\"\n", val);

                        return res;

                    }

                }

            }

            if (o->type == FF_OPT_TYPE_FLAGS) {

                if      (cmd=='+') d= av_get_int(obj, name, NULL) | (int64_t)d;

                else if (cmd=='-') d= av_get_int(obj, name, NULL) &~(int64_t)d;

            } else {

                if      (cmd=='+') d= notfirst*av_get_double(obj, name, NULL) + d;

                else if (cmd=='-') d= notfirst*av_get_double(obj, name, NULL) - d;

            }



            if ((ret = av_set_number2(obj, name, d, 1, 1, o_out)) < 0)

                return ret;

            val+= i;

            if (!*val)

                return 0;

            notfirst=1;

        }

        return AVERROR(EINVAL);

    }



    if (alloc) {

        av_free(*(void**)(((uint8_t*)obj) + o->offset));

        val= av_strdup(val);

    }



    memcpy(((uint8_t*)obj) + o->offset, &val, sizeof(val));

    return 0;

}

static int vnc_auth_sasl_check_ssf(VncState *vs)

{

    const void *val;

    int err, ssf;



    if (!vs->sasl.wantSSF)

        return 1;



    err = sasl_getprop(vs->sasl.conn, SASL_SSF, &val);

    if (err != SASL_OK)

        return 0;



    ssf = *(const int *)val;

    VNC_DEBUG("negotiated an SSF of %d\n", ssf);

    if (ssf < 56)

        return 0; /* 56 is good for Kerberos */



    /* Only setup for read initially, because we're about to send an RPC

     * reply which must be in plain text. When the next incoming RPC

     * arrives, we'll switch on writes too

     *

     * cf qemudClientReadSASL  in qemud.c

     */

    vs->sasl.runSSF = 1;



    /* We have a SSF that's good enough */

    return 1;

}

static int smacker_read_header(AVFormatContext *s)
{
    AVIOContext *pb = s->pb;
    SmackerContext *smk = s->priv_data;
    AVStream *st, *ast[7];
    int i, ret;
    int tbase;
    /* read and check header */
    smk->magic = avio_rl32(pb);
    if (smk->magic != MKTAG('S', 'M', 'K', '2') && smk->magic != MKTAG('S', 'M', 'K', '4'))
    smk->width = avio_rl32(pb);
    smk->height = avio_rl32(pb);
    smk->frames = avio_rl32(pb);
    smk->pts_inc = (int32_t)avio_rl32(pb);
    smk->flags = avio_rl32(pb);
    if(smk->flags & SMACKER_FLAG_RING_FRAME)
        smk->frames++;
    for(i = 0; i < 7; i++)
        smk->audio[i] = avio_rl32(pb);
    smk->treesize = avio_rl32(pb);
    if(smk->treesize >= UINT_MAX/4){ // smk->treesize + 16 must not overflow (this check is probably redundant)
        av_log(s, AV_LOG_ERROR, "treesize too large\n");
//FIXME remove extradata "rebuilding"
    smk->mmap_size = avio_rl32(pb);
    smk->mclr_size = avio_rl32(pb);
    smk->full_size = avio_rl32(pb);
    smk->type_size = avio_rl32(pb);
    for(i = 0; i < 7; i++) {
        smk->rates[i]  = avio_rl24(pb);
        smk->aflags[i] = avio_r8(pb);
    smk->pad = avio_rl32(pb);
    /* setup data */
    if(smk->frames > 0xFFFFFF) {
        av_log(s, AV_LOG_ERROR, "Too many frames: %"PRIu32"\n", smk->frames);
    smk->frm_size = av_malloc_array(smk->frames, sizeof(*smk->frm_size));
    smk->frm_flags = av_malloc(smk->frames);
    if (!smk->frm_size || !smk->frm_flags) {
        av_freep(&smk->frm_size);
        av_freep(&smk->frm_flags);
        return AVERROR(ENOMEM);
    smk->is_ver4 = (smk->magic != MKTAG('S', 'M', 'K', '2'));
    /* read frame info */
    for(i = 0; i < smk->frames; i++) {
        smk->frm_size[i] = avio_rl32(pb);
    for(i = 0; i < smk->frames; i++) {
        smk->frm_flags[i] = avio_r8(pb);
    /* init video codec */
    st = avformat_new_stream(s, NULL);
    if (!st)
        return AVERROR(ENOMEM);
    smk->videoindex = st->index;
    st->codec->width = smk->width;
    st->codec->height = smk->height;
    st->codec->pix_fmt = AV_PIX_FMT_PAL8;
    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;
    st->codec->codec_id = AV_CODEC_ID_SMACKVIDEO;
    st->codec->codec_tag = smk->magic;
    /* Smacker uses 100000 as internal timebase */
    if(smk->pts_inc < 0)
        smk->pts_inc = -smk->pts_inc;
    else
        smk->pts_inc *= 100;
    tbase = 100000;
    av_reduce(&tbase, &smk->pts_inc, tbase, smk->pts_inc, (1UL<<31)-1);
    avpriv_set_pts_info(st, 33, smk->pts_inc, tbase);
    st->duration = smk->frames;
    /* handle possible audio streams */
    for(i = 0; i < 7; i++) {
        smk->indexes[i] = -1;
        if (smk->rates[i]) {
            ast[i] = avformat_new_stream(s, NULL);
            if (!ast[i])
                return AVERROR(ENOMEM);
            smk->indexes[i] = ast[i]->index;
            ast[i]->codec->codec_type = AVMEDIA_TYPE_AUDIO;
            if (smk->aflags[i] & SMK_AUD_BINKAUD) {
                ast[i]->codec->codec_id = AV_CODEC_ID_BINKAUDIO_RDFT;
            } else if (smk->aflags[i] & SMK_AUD_USEDCT) {
                ast[i]->codec->codec_id = AV_CODEC_ID_BINKAUDIO_DCT;
            } else if (smk->aflags[i] & SMK_AUD_PACKED){
                ast[i]->codec->codec_id = AV_CODEC_ID_SMACKAUDIO;
                ast[i]->codec->codec_tag = MKTAG('S', 'M', 'K', 'A');
            } else {
                ast[i]->codec->codec_id = AV_CODEC_ID_PCM_U8;
            if (smk->aflags[i] & SMK_AUD_STEREO) {
                ast[i]->codec->channels       = 2;
                ast[i]->codec->channel_layout = AV_CH_LAYOUT_STEREO;
            } else {
                ast[i]->codec->channels       = 1;
                ast[i]->codec->channel_layout = AV_CH_LAYOUT_MONO;
            ast[i]->codec->sample_rate = smk->rates[i];
            ast[i]->codec->bits_per_coded_sample = (smk->aflags[i] & SMK_AUD_16BITS) ? 16 : 8;
            if(ast[i]->codec->bits_per_coded_sample == 16 && ast[i]->codec->codec_id == AV_CODEC_ID_PCM_U8)
                ast[i]->codec->codec_id = AV_CODEC_ID_PCM_S16LE;
            avpriv_set_pts_info(ast[i], 64, 1, ast[i]->codec->sample_rate
                    * ast[i]->codec->channels * ast[i]->codec->bits_per_coded_sample / 8);
    /* load trees to extradata, they will be unpacked by decoder */
    if(ff_alloc_extradata(st->codec, smk->treesize + 16)){
        av_log(s, AV_LOG_ERROR,
               "Cannot allocate %"PRIu32" bytes of extradata\n",
               smk->treesize + 16);
        av_freep(&smk->frm_size);
        av_freep(&smk->frm_flags);
        return AVERROR(ENOMEM);
    ret = avio_read(pb, st->codec->extradata + 16, st->codec->extradata_size - 16);
    if(ret != st->codec->extradata_size - 16){
        av_freep(&smk->frm_size);
        av_freep(&smk->frm_flags);
        return AVERROR(EIO);
    ((int32_t*)st->codec->extradata)[0] = av_le2ne32(smk->mmap_size);
    ((int32_t*)st->codec->extradata)[1] = av_le2ne32(smk->mclr_size);
    ((int32_t*)st->codec->extradata)[2] = av_le2ne32(smk->full_size);
    ((int32_t*)st->codec->extradata)[3] = av_le2ne32(smk->type_size);
    smk->curstream = -1;
    smk->nextpos = avio_tell(pb);
    return 0;

static void do_info_history (void)

{

    int i;



    for (i = 0; i < TERM_MAX_CMDS; i++) {

	if (term_history[i] == NULL)

	    break;

	term_printf("%d: '%s'\n", i, term_history[i]);

    }

}

static int transcode(void)

{

    int ret, i;

    AVFormatContext *is, *os;

    OutputStream *ost;

    InputStream *ist;

    uint8_t *no_packet;

    int no_packet_count = 0;

    int64_t timer_start;

    int key;



    if (!(no_packet = av_mallocz(nb_input_files)))

        exit_program(1);



    ret = transcode_init();

    if (ret < 0)

        goto fail;



    if (!using_stdin) {

        av_log(NULL, AV_LOG_INFO, "Press [q] to stop, [?] for help\n");

    }



    timer_start = av_gettime();



    for (; received_sigterm == 0;) {

        int file_index, ist_index;

        AVPacket pkt;

        int64_t cur_time= av_gettime();



        /* if 'q' pressed, exits */

        if (!using_stdin) {

            static int64_t last_time;

            if (received_nb_signals)

                break;

            /* read_key() returns 0 on EOF */

            if(cur_time - last_time >= 100000 && !run_as_daemon){

                key =  read_key();

                last_time = cur_time;

            }else

                key = -1;

            if (key == 'q')

                break;

            if (key == '+') av_log_set_level(av_log_get_level()+10);

            if (key == '-') av_log_set_level(av_log_get_level()-10);

            if (key == 's') qp_hist     ^= 1;

            if (key == 'h'){

                if (do_hex_dump){

                    do_hex_dump = do_pkt_dump = 0;

                } else if(do_pkt_dump){

                    do_hex_dump = 1;

                } else

                    do_pkt_dump = 1;

                av_log_set_level(AV_LOG_DEBUG);

            }

            if (key == 'c' || key == 'C'){

                char buf[4096], target[64], command[256], arg[256] = {0};

                double time;

                int k, n = 0;

                fprintf(stderr, "\nEnter command: <target> <time> <command>[ <argument>]\n");

                i = 0;

                while ((k = read_key()) != '\n' && k != '\r' && i < sizeof(buf)-1)

                    if (k > 0)

                        buf[i++] = k;

                buf[i] = 0;

                if (k > 0 &&

                    (n = sscanf(buf, "%63[^ ] %lf %255[^ ] %255[^\n]", target, &time, command, arg)) >= 3) {

                    av_log(NULL, AV_LOG_DEBUG, "Processing command target:%s time:%f command:%s arg:%s",

                           target, time, command, arg);

                    for (i = 0; i < nb_filtergraphs; i++) {

                        FilterGraph *fg = filtergraphs[i];

                        if (fg->graph) {

                            if (time < 0) {

                                ret = avfilter_graph_send_command(fg->graph, target, command, arg, buf, sizeof(buf),

                                                                  key == 'c' ? AVFILTER_CMD_FLAG_ONE : 0);

                                fprintf(stderr, "Command reply for stream %d: ret:%d res:%s\n", i, ret, buf);

                            } else {

                                ret = avfilter_graph_queue_command(fg->graph, target, command, arg, 0, time);

                            }

                        }

                    }

                } else {

                    av_log(NULL, AV_LOG_ERROR,

                           "Parse error, at least 3 arguments were expected, "

                           "only %d given in string '%s'\n", n, buf);

                }

            }

            if (key == 'd' || key == 'D'){

                int debug=0;

                if(key == 'D') {

                    debug = input_streams[0]->st->codec->debug<<1;

                    if(!debug) debug = 1;

                    while(debug & (FF_DEBUG_DCT_COEFF|FF_DEBUG_VIS_QP|FF_DEBUG_VIS_MB_TYPE)) //unsupported, would just crash

                        debug += debug;

                }else

                    if(scanf("%d", &debug)!=1)

                        fprintf(stderr,"error parsing debug value\n");

                for(i=0;i<nb_input_streams;i++) {

                    input_streams[i]->st->codec->debug = debug;

                }

                for(i=0;i<nb_output_streams;i++) {

                    ost = output_streams[i];

                    ost->st->codec->debug = debug;

                }

                if(debug) av_log_set_level(AV_LOG_DEBUG);

                fprintf(stderr,"debug=%d\n", debug);

            }

            if (key == '?'){

                fprintf(stderr, "key    function\n"

                                "?      show this help\n"

                                "+      increase verbosity\n"

                                "-      decrease verbosity\n"

                                "c      Send command to filtergraph\n"

                                "D      cycle through available debug modes\n"

                                "h      dump packets/hex press to cycle through the 3 states\n"

                                "q      quit\n"

                                "s      Show QP histogram\n"

                );

            }

        }



        /* check if there's any stream where output is still needed */

        if (!need_output()) {

            av_log(NULL, AV_LOG_VERBOSE, "No more output streams to write to, finishing.\n");

            break;

        }



        /* select the stream that we must read now */

        file_index = select_input_file(no_packet);

        /* if none, if is finished */

        if (file_index < 0) {

            if (no_packet_count) {

                no_packet_count = 0;

                memset(no_packet, 0, nb_input_files);

                usleep(10000);

                continue;

            }

            break;

        }



        /* read a frame from it and output it in the fifo */

        is  = input_files[file_index]->ctx;

        ret = av_read_frame(is, &pkt);

        if (ret == AVERROR(EAGAIN)) {

            no_packet[file_index] = 1;

            no_packet_count++;

            continue;

        }

        if (ret < 0) {

            input_files[file_index]->eof_reached = 1;



            for (i = 0; i < input_files[file_index]->nb_streams; i++) {

                ist = input_streams[input_files[file_index]->ist_index + i];

                if (ist->decoding_needed)

                    output_packet(ist, NULL);

            }



            if (opt_shortest)

                break;

            else

                continue;

        }



        no_packet_count = 0;

        memset(no_packet, 0, nb_input_files);



        if (do_pkt_dump) {

            av_pkt_dump_log2(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump,

                             is->streams[pkt.stream_index]);

        }

        /* the following test is needed in case new streams appear

           dynamically in stream : we ignore them */

        if (pkt.stream_index >= input_files[file_index]->nb_streams)

            goto discard_packet;

        ist_index = input_files[file_index]->ist_index + pkt.stream_index;

        ist = input_streams[ist_index];

        if (ist->discard)

            goto discard_packet;



        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);

        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts += av_rescale_q(input_files[ist->file_index]->ts_offset, AV_TIME_BASE_Q, ist->st->time_base);



        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts *= ist->ts_scale;

        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts *= ist->ts_scale;



        if (debug_ts) {

            av_log(NULL, AV_LOG_INFO, "demuxer -> ist_index:%d type:%s "

                    "next_dts:%s next_dts_time:%s next_pts:%s next_pts_time:%s  pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s off:%"PRId64"\n",

                    ist_index, av_get_media_type_string(ist->st->codec->codec_type),

                    av_ts2str(ist->next_dts), av_ts2timestr(ist->next_dts, &ist->st->time_base),

                    av_ts2str(ist->next_pts), av_ts2timestr(ist->next_pts, &ist->st->time_base),

                    av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &ist->st->time_base),

                    av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &ist->st->time_base),

                    input_files[ist->file_index]->ts_offset);

        }



        if (pkt.dts != AV_NOPTS_VALUE && ist->next_dts != AV_NOPTS_VALUE && !copy_ts) {

            int64_t pkt_dts = av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

            int64_t delta   = pkt_dts - ist->next_dts;

            if (is->iformat->flags & AVFMT_TS_DISCONT) {

            if(delta < -1LL*dts_delta_threshold*AV_TIME_BASE ||

                (delta > 1LL*dts_delta_threshold*AV_TIME_BASE &&

                 ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                pkt_dts+1<ist->pts){

                input_files[ist->file_index]->ts_offset -= delta;

                av_log(NULL, AV_LOG_DEBUG,

                       "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n",

                       delta, input_files[ist->file_index]->ts_offset);

                pkt.dts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

                if (pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            }

            } else {

                if ( delta < -1LL*dts_error_threshold*AV_TIME_BASE ||

                    (delta > 1LL*dts_error_threshold*AV_TIME_BASE && ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                     pkt_dts+1<ist->pts){

                    av_log(NULL, AV_LOG_WARNING, "DTS %"PRId64", next:%"PRId64" st:%d invalid dropping\n", pkt.dts, ist->next_dts, pkt.stream_index);

                    pkt.dts = AV_NOPTS_VALUE;

                }

                if (pkt.pts != AV_NOPTS_VALUE){

                    int64_t pkt_pts = av_rescale_q(pkt.pts, ist->st->time_base, AV_TIME_BASE_Q);

                    delta   = pkt_pts - ist->next_dts;

                    if ( delta < -1LL*dts_error_threshold*AV_TIME_BASE ||

                        (delta > 1LL*dts_error_threshold*AV_TIME_BASE && ist->st->codec->codec_type != AVMEDIA_TYPE_SUBTITLE) ||

                        pkt_pts+1<ist->pts) {

                        av_log(NULL, AV_LOG_WARNING, "PTS %"PRId64", next:%"PRId64" invalid dropping st:%d\n", pkt.pts, ist->next_dts, pkt.stream_index);

                        pkt.pts = AV_NOPTS_VALUE;

                    }

                }

            }

        }



        // fprintf(stderr,"read #%d.%d size=%d\n", ist->file_index, ist->st->index, pkt.size);

        if ((ret = output_packet(ist, &pkt)) < 0 ||

            ((ret = poll_filters()) < 0 && ret != AVERROR_EOF)) {

            char buf[128];

            av_strerror(ret, buf, sizeof(buf));

            av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d: %s\n",

                   ist->file_index, ist->st->index, buf);

            if (exit_on_error)

                exit_program(1);

            av_free_packet(&pkt);

            continue;

        }



    discard_packet:

        av_free_packet(&pkt);



        /* dump report by using the output first video and audio streams */

        print_report(0, timer_start, cur_time);

    }



    /* at the end of stream, we must flush the decoder buffers */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (!input_files[ist->file_index]->eof_reached && ist->decoding_needed) {

            output_packet(ist, NULL);

        }

    }

    poll_filters();

    flush_encoders();



    term_exit();



    /* write the trailer if needed and close file */

    for (i = 0; i < nb_output_files; i++) {

        os = output_files[i]->ctx;

        av_write_trailer(os);

    }



    /* dump report by using the first video and audio streams */

    print_report(1, timer_start, av_gettime());



    /* close each encoder */

    for (i = 0; i < nb_output_streams; i++) {

        ost = output_streams[i];

        if (ost->encoding_needed) {

            av_freep(&ost->st->codec->stats_in);

            avcodec_close(ost->st->codec);

        }

    }



    /* close each decoder */

    for (i = 0; i < nb_input_streams; i++) {

        ist = input_streams[i];

        if (ist->decoding_needed) {

            avcodec_close(ist->st->codec);

        }

    }



    /* finished ! */

    ret = 0;



 fail:

    av_freep(&no_packet);



    if (output_streams) {

        for (i = 0; i < nb_output_streams; i++) {

            ost = output_streams[i];

            if (ost) {

                if (ost->stream_copy)

                    av_freep(&ost->st->codec->extradata);

                if (ost->logfile) {

                    fclose(ost->logfile);

                    ost->logfile = NULL;

                }

                av_freep(&ost->st->codec->subtitle_header);

                av_free(ost->forced_kf_pts);

                av_dict_free(&ost->opts);

            }

        }

    }

    return ret;

}

static void imx_eth_enable_rx(IMXFECState *s)

{

    IMXFECBufDesc bd;

    bool rx_ring_full;



    imx_fec_read_bd(&bd, s->rx_descriptor);



    rx_ring_full = !(bd.flags & ENET_BD_E);



    if (rx_ring_full) {

        FEC_PRINTF("RX buffer full\n");

    } else if (!s->regs[ENET_RDAR]) {

        qemu_flush_queued_packets(qemu_get_queue(s->nic));

    }



    s->regs[ENET_RDAR] = rx_ring_full ? 0 : ENET_RDAR_RDAR;

}

int ff_wmv2_decode_secondary_picture_header(MpegEncContext *s)

{

    Wmv2Context *const w = (Wmv2Context *) s;



    if (s->pict_type == AV_PICTURE_TYPE_I) {

        if (w->j_type_bit)

            w->j_type = get_bits1(&s->gb);

        else

            w->j_type = 0; // FIXME check



        if (!w->j_type) {

            if (w->per_mb_rl_bit)

                s->per_mb_rl_table = get_bits1(&s->gb);

            else

                s->per_mb_rl_table = 0;



            if (!s->per_mb_rl_table) {

                s->rl_chroma_table_index = decode012(&s->gb);

                s->rl_table_index        = decode012(&s->gb);

            }



            s->dc_table_index = get_bits1(&s->gb);

        }

        s->inter_intra_pred = 0;

        s->no_rounding      = 1;

        if (s->avctx->debug & FF_DEBUG_PICT_INFO) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "qscale:%d rlc:%d rl:%d dc:%d mbrl:%d j_type:%d \n",

                   s->qscale, s->rl_chroma_table_index, s->rl_table_index,

                   s->dc_table_index, s->per_mb_rl_table, w->j_type);

        }

    } else {

        int cbp_index;

        w->j_type = 0;



        parse_mb_skip(w);

        cbp_index = decode012(&s->gb);

        w->cbp_table_index = wmv2_get_cbp_table_index(s, cbp_index);



        if (w->mspel_bit)

            s->mspel = get_bits1(&s->gb);

        else

            s->mspel = 0; // FIXME check



        if (w->abt_flag) {

            w->per_mb_abt = get_bits1(&s->gb) ^ 1;

            if (!w->per_mb_abt)

                w->abt_type = decode012(&s->gb);

        }



        if (w->per_mb_rl_bit)

            s->per_mb_rl_table = get_bits1(&s->gb);

        else

            s->per_mb_rl_table = 0;



        if (!s->per_mb_rl_table) {

            s->rl_table_index        = decode012(&s->gb);

            s->rl_chroma_table_index = s->rl_table_index;

        }



        s->dc_table_index   = get_bits1(&s->gb);

        s->mv_table_index   = get_bits1(&s->gb);



        s->inter_intra_pred = 0; // (s->width * s->height < 320 * 240 && s->bit_rate <= II_BITRATE);

        s->no_rounding     ^= 1;



        if (s->avctx->debug & FF_DEBUG_PICT_INFO) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "rl:%d rlc:%d dc:%d mv:%d mbrl:%d qp:%d mspel:%d "

                   "per_mb_abt:%d abt_type:%d cbp:%d ii:%d\n",

                   s->rl_table_index, s->rl_chroma_table_index,

                   s->dc_table_index, s->mv_table_index,

                   s->per_mb_rl_table, s->qscale, s->mspel,

                   w->per_mb_abt, w->abt_type, w->cbp_table_index,

                   s->inter_intra_pred);

        }

    }

    s->esc3_level_length = 0;

    s->esc3_run_length   = 0;

    s->picture_number++; // FIXME ?



    if (w->j_type) {

        ff_intrax8_decode_picture(&w->x8, &s->current_picture,

                                  &s->gb, &s->mb_x, &s->mb_y,

                                  2 * s->qscale, (s->qscale - 1) | 1,

                                  s->loop_filter, s->low_delay);



        ff_er_add_slice(&w->s.er, 0, 0,

                        (w->s.mb_x >> 1) - 1, (w->s.mb_y >> 1) - 1,

                        ER_MB_END);

        return 1;

    }



    return 0;

}

void qemu_system_debug_request(void)

{

    debug_requested = 1;

    vm_stop(VMSTOP_DEBUG);

}

static int asf_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    ASFContext *asf = s->priv_data;

    GUID g;

    ByteIOContext *pb = &s->pb;

    AVStream *st;

    ASFStream *asf_st;

    int size, i, bps;

    INT64 gsize;



    get_guid(pb, &g);

    if (memcmp(&g, &asf_header, sizeof(GUID)))

        goto fail;

    get_le64(pb);

    get_le32(pb);

    get_byte(pb);

    get_byte(pb);

    memset(&asf->asfid2avid, -1, sizeof(asf->asfid2avid));

    for(;;) {

        get_guid(pb, &g);

        gsize = get_le64(pb);

#ifdef DEBUG

        printf("%08Lx: ", url_ftell(pb) - 24);

        print_guid(&g);

        printf("  size=0x%Lx\n", gsize);

#endif

        if (gsize < 24)

            goto fail;

        if (!memcmp(&g, &file_header, sizeof(GUID))) {

            get_guid(pb, &asf->hdr.guid);

	    asf->hdr.file_size		= get_le64(pb);

	    asf->hdr.create_time	= get_le64(pb);

	    asf->hdr.packets_count	= get_le64(pb);

	    asf->hdr.play_time		= get_le64(pb);

	    asf->hdr.send_time		= get_le64(pb);

	    asf->hdr.preroll		= get_le32(pb);

	    asf->hdr.ignore		= get_le32(pb);

	    asf->hdr.flags		= get_le32(pb);

	    asf->hdr.min_pktsize	= get_le32(pb);

	    asf->hdr.max_pktsize	= get_le32(pb);

	    asf->hdr.max_bitrate	= get_le32(pb);

	    asf->packet_size = asf->hdr.max_pktsize;

            asf->nb_packets = asf->hdr.packets_count;

        } else if (!memcmp(&g, &stream_header, sizeof(GUID))) {

            int type, id, total_size;

            unsigned int tag1;

            INT64 pos1, pos2;



            pos1 = url_ftell(pb);



            st = av_mallocz(sizeof(AVStream));

            if (!st)

                goto fail;

            s->streams[s->nb_streams] = st;

            asf_st = av_mallocz(sizeof(ASFStream));

            if (!asf_st)

                goto fail;

            st->priv_data = asf_st;

	    st->time_length = (asf->hdr.send_time - asf->hdr.preroll) / 10000;

            get_guid(pb, &g);

            if (!memcmp(&g, &audio_stream, sizeof(GUID))) {

                type = CODEC_TYPE_AUDIO;

            } else if (!memcmp(&g, &video_stream, sizeof(GUID))) {

                type = CODEC_TYPE_VIDEO;

            } else {

                goto fail;

            }

            get_guid(pb, &g);

            total_size = get_le64(pb);

            get_le32(pb);

            get_le32(pb);

	    st->id = get_le16(pb) & 0x7f; /* stream id */

            // mapping of asf ID to AV stream ID;

            asf->asfid2avid[st->id] = s->nb_streams++;



            get_le32(pb);

	    st->codec.codec_type = type;

            st->codec.frame_rate = 1000; // in packet ticks

            if (type == CODEC_TYPE_AUDIO) {

                id = get_le16(pb);

                st->codec.codec_tag = id;

                st->codec.channels = get_le16(pb);

		st->codec.sample_rate = get_le32(pb);

                st->codec.bit_rate = get_le32(pb) * 8;

		st->codec.block_align = get_le16(pb); /* block align */

                bps = get_le16(pb); /* bits per sample */

                st->codec.codec_id = wav_codec_get_id(id, bps);

		size = get_le16(pb);

		if (size > 0) {

		    st->extra_data = av_mallocz(size);

		    get_buffer(pb, st->extra_data, size);

		    st->extra_data_size = size;

		}

		/* We have to init the frame size at some point .... */

		pos2 = url_ftell(pb);

		if (gsize > (pos2 + 8 - pos1 + 24)) {

		    asf_st->ds_span = get_byte(pb);

		    asf_st->ds_packet_size = get_le16(pb);

		    asf_st->ds_chunk_size = get_le16(pb);

		    asf_st->ds_data_size = get_le16(pb);

		    asf_st->ds_silence_data = get_byte(pb);

		}

		//printf("Descrambling: ps:%d cs:%d ds:%d s:%d  sd:%d\n",

		//       asf_st->ds_packet_size, asf_st->ds_chunk_size,

		//       asf_st->ds_data_size, asf_st->ds_span, asf_st->ds_silence_data);

		if (asf_st->ds_span > 1) {

		    if (!asf_st->ds_chunk_size

			|| (asf_st->ds_packet_size/asf_st->ds_chunk_size <= 1))

			asf_st->ds_span = 0; // disable descrambling

		}

                switch (st->codec.codec_id) {

                case CODEC_ID_MP3LAME:

                    st->codec.frame_size = MPA_FRAME_SIZE;

                    break;

                case CODEC_ID_PCM_S16LE:

                case CODEC_ID_PCM_S16BE:

                case CODEC_ID_PCM_U16LE:

                case CODEC_ID_PCM_U16BE:

                case CODEC_ID_PCM_S8:

                case CODEC_ID_PCM_U8:

                case CODEC_ID_PCM_ALAW:

                case CODEC_ID_PCM_MULAW:

                    st->codec.frame_size = 1;

                    break;

                default:

                    /* This is probably wrong, but it prevents a crash later */

                    st->codec.frame_size = 1;

                    break;

                }

            } else {

		get_le32(pb);

                get_le32(pb);

                get_byte(pb);

                size = get_le16(pb); /* size */

                get_le32(pb); /* size */

                st->codec.width = get_le32(pb);

		st->codec.height = get_le32(pb);

                /* not available for asf */

                get_le16(pb); /* panes */

                get_le16(pb); /* depth */

                tag1 = get_le32(pb);

		url_fskip(pb, 20);

		if (size > 40) {

		    st->extra_data_size = size - 40;

		    st->extra_data = av_mallocz(st->extra_data_size);

		    get_buffer(pb, st->extra_data, st->extra_data_size);

		}

                st->codec.codec_tag = tag1;

		st->codec.codec_id = codec_get_id(codec_asf_bmp_tags, tag1);

            }

            pos2 = url_ftell(pb);

            url_fskip(pb, gsize - (pos2 - pos1 + 24));

        } else if (!memcmp(&g, &data_header, sizeof(GUID))) {

            break;

        } else if (!memcmp(&g, &comment_header, sizeof(GUID))) {

            int len1, len2, len3, len4, len5;



            len1 = get_le16(pb);

            len2 = get_le16(pb);

            len3 = get_le16(pb);

            len4 = get_le16(pb);

            len5 = get_le16(pb);

            get_str16_nolen(pb, len1, s->title, sizeof(s->title));

            get_str16_nolen(pb, len2, s->author, sizeof(s->author));

            get_str16_nolen(pb, len3, s->copyright, sizeof(s->copyright));

            get_str16_nolen(pb, len4, s->comment, sizeof(s->comment));

	    url_fskip(pb, len5);

#if 0

        } else if (!memcmp(&g, &head1_guid, sizeof(GUID))) {

            int v1, v2;

            get_guid(pb, &g);

            v1 = get_le32(pb);

            v2 = get_le16(pb);

        } else if (!memcmp(&g, &codec_comment_header, sizeof(GUID))) {

            int len, v1, n, num;

            char str[256], *q;

            char tag[16];



            get_guid(pb, &g);

            print_guid(&g);



            n = get_le32(pb);

            for(i=0;i<n;i++) {

                num = get_le16(pb); /* stream number */

                get_str16(pb, str, sizeof(str));

                get_str16(pb, str, sizeof(str));

                len = get_le16(pb);

                q = tag;

                while (len > 0) {

                    v1 = get_byte(pb);

                    if ((q - tag) < sizeof(tag) - 1)

                        *q++ = v1;

                    len--;

                }

                *q = '\0';

            }

#endif

        } else if (url_feof(pb)) {

            goto fail;

        } else {

            url_fseek(pb, gsize - 24, SEEK_CUR);

        }

    }

    get_guid(pb, &g);

    get_le64(pb);

    get_byte(pb);

    get_byte(pb);

    if (url_feof(pb))

        goto fail;

    asf->data_offset = url_ftell(pb);

    asf->packet_size_left = 0;



    return 0;



 fail:

    for(i=0;i<s->nb_streams;i++) {

        AVStream *st = s->streams[i];

	if (st) {

	    av_free(st->priv_data);

	    av_free(st->extra_data);

	}

        av_free(st);

    }

    //av_free(asf);

    return -1;

}

static void virtio_net_tx_bh(void *opaque)

{

    VirtIONetQueue *q = opaque;

    VirtIONet *n = q->n;

    VirtIODevice *vdev = VIRTIO_DEVICE(n);

    int32_t ret;



    assert(vdev->vm_running);



    q->tx_waiting = 0;



    /* Just in case the driver is not ready on more */

    if (unlikely(!(vdev->status & VIRTIO_CONFIG_S_DRIVER_OK))) {

        return;

    }



    ret = virtio_net_flush_tx(q);

    if (ret == -EBUSY) {

        return; /* Notification re-enable handled by tx_complete */

    }



    /* If we flush a full burst of packets, assume there are

     * more coming and immediately reschedule */

    if (ret >= n->tx_burst) {

        qemu_bh_schedule(q->tx_bh);

        q->tx_waiting = 1;

        return;

    }



    /* If less than a full burst, re-enable notification and flush

     * anything that may have come in while we weren't looking.  If

     * we find something, assume the guest is still active and reschedule */

    virtio_queue_set_notification(q->tx_vq, 1);

    if (virtio_net_flush_tx(q) > 0) {

        virtio_queue_set_notification(q->tx_vq, 0);

        qemu_bh_schedule(q->tx_bh);

        q->tx_waiting = 1;

    }

}

char *ff_AMediaCodecList_getCodecNameByType(const char *mime, int width, int height, void *log_ctx)

{

    int ret;

    char *name = NULL;

    char *supported_type = NULL;



    int attached = 0;

    JNIEnv *env = NULL;

    struct JNIAMediaCodecListFields jfields = { 0 };



    jobject format = NULL;

    jobject codec = NULL;

    jstring tmp = NULL;



    jobject info = NULL;

    jobject type = NULL;

    jobjectArray types = NULL;



    JNI_ATTACH_ENV_OR_RETURN(env, &attached, log_ctx, NULL);



    if ((ret = ff_jni_init_jfields(env, &jfields, jni_amediacodeclist_mapping, 0, log_ctx)) < 0) {

        goto done;

    }



    if (jfields.init_id && jfields.find_decoder_for_format_id) {

        tmp = ff_jni_utf_chars_to_jstring(env, mime, log_ctx);

        if (!tmp) {

            goto done;

        }



        format = (*env)->CallStaticObjectMethod(env, jfields.mediaformat_class, jfields.create_video_format_id, tmp, width, height);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }

        (*env)->DeleteLocalRef(env, tmp);

        tmp = NULL;



        codec = (*env)->NewObject(env, jfields.mediacodec_list_class, jfields.init_id, 0);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }



        tmp = (*env)->CallObjectMethod(env, codec, jfields.find_decoder_for_format_id, format);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }

        if (!tmp) {

            av_log(NULL, AV_LOG_ERROR, "Could not find decoder in media codec list "

                                       "for format { mime=%s width=%d height=%d }\n", mime, width, height);

            goto done;

        }



        name = ff_jni_jstring_to_utf_chars(env, tmp, log_ctx);

        if (!name) {

            goto done;

        }



    } else {

        int i;

        int codec_count;



        codec_count = (*env)->CallStaticIntMethod(env, jfields.mediacodec_list_class, jfields.get_codec_count_id);

        if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

            goto done;

        }



        for(i = 0; i < codec_count; i++) {

            int j;

            int type_count;

            int is_encoder;



            info = (*env)->CallStaticObjectMethod(env, jfields.mediacodec_list_class, jfields.get_codec_info_at_id, i);

            if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                goto done;

            }



            types = (*env)->CallObjectMethod(env, info, jfields.get_supported_types_id);

            if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                goto done;

            }



            is_encoder = (*env)->CallBooleanMethod(env, info, jfields.is_encoder_id);

            if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                goto done;

            }



            if (is_encoder) {

                continue;

            }



            type_count = (*env)->GetArrayLength(env, types);

            for (j = 0; j < type_count; j++) {



                type = (*env)->GetObjectArrayElement(env, types, j);

                if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                    goto done;

                }



                supported_type = ff_jni_jstring_to_utf_chars(env, type, log_ctx);

                if (!supported_type) {

                    goto done;

                }



                if (!av_strcasecmp(supported_type, mime)) {

                    jobject codec_name;



                    codec_name = (*env)->CallObjectMethod(env, info, jfields.get_name_id);

                    if (ff_jni_exception_check(env, 1, log_ctx) < 0) {

                        goto done;

                    }



                    name = ff_jni_jstring_to_utf_chars(env, codec_name, log_ctx);

                    if (!name) {

                        goto done;

                    }



                    if (strstr(name, "OMX.google")) {

                        av_freep(&name);

                        continue;

                    }

                }



                av_freep(&supported_type);

            }



            (*env)->DeleteLocalRef(env, info);

            info = NULL;



            (*env)->DeleteLocalRef(env, types);

            types = NULL;



            if (name)

                break;

        }

    }



done:

    if (format) {

        (*env)->DeleteLocalRef(env, format);

    }



    if (codec) {

        (*env)->DeleteLocalRef(env, codec);

    }



    if (tmp) {

        (*env)->DeleteLocalRef(env, tmp);

    }



    if (info) {

        (*env)->DeleteLocalRef(env, info);

    }



    if (type) {

        (*env)->DeleteLocalRef(env, type);

    }



    if (types) {

        (*env)->DeleteLocalRef(env, types);

    }



    av_freep(&supported_type);



    ff_jni_reset_jfields(env, &jfields, jni_amediacodeclist_mapping, 0, log_ctx);



    JNI_DETACH_ENV(attached, log_ctx);



    return name;

}

