static void hpdmc_write(void *opaque, target_phys_addr_t addr, uint64_t value,

                        unsigned size)

{

    MilkymistHpdmcState *s = opaque;



    trace_milkymist_hpdmc_memory_write(addr, value);



    addr >>= 2;

    switch (addr) {

    case R_SYSTEM:

    case R_BYPASS:

    case R_TIMING:

        s->regs[addr] = value;

        break;

    case R_IODELAY:

        /* ignore writes */

        break;



    default:

        error_report("milkymist_hpdmc: write access to unknown register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    }

}

static void test_visitor_in_fail_list_nested(TestInputVisitorData *data,

                                             const void *unused)

{

    int64_t i64 = -1;

    Visitor *v;



    /* Unvisited nested list tail */



    v = visitor_input_test_init(data, "[ 0, [ 1, 2, 3 ] ]");



    visit_start_list(v, NULL, NULL, 0, &error_abort);

    visit_type_int(v, NULL, &i64, &error_abort);

    g_assert_cmpint(i64, ==, 0);

    visit_start_list(v, NULL, NULL, 0, &error_abort);

    visit_type_int(v, NULL, &i64, &error_abort);

    g_assert_cmpint(i64, ==, 1);

    visit_end_list(v, NULL);

    /* BUG: unvisited tail not reported; actually not reportable by design */

    visit_end_list(v, NULL);

}

static int handle_update_file_cred(int dirfd, const char *name, FsCred *credp)

{

    int fd, ret;

    fd = openat(dirfd, name, O_NONBLOCK | O_NOFOLLOW);

    if (fd < 0) {

        return fd;

    }

    ret = fchmod(fd, credp->fc_mode & 07777);

    if (ret < 0) {

        goto err_out;

    }

    ret = fchownat(fd, "", credp->fc_uid, credp->fc_gid, AT_EMPTY_PATH);

err_out:

    close(fd);

    return ret;

}

static int bands_dist(OpusPsyContext *s, CeltFrame *f, float *total_dist)

{

    int i, tdist = 0.0f;

    OpusRangeCoder dump;



    ff_opus_rc_enc_init(&dump);

    ff_celt_enc_bitalloc(f, &dump);



    for (i = 0; i < CELT_MAX_BANDS; i++) {

        float bits = 0.0f;

        float dist = f->pvq->band_cost(f->pvq, f, &dump, i, &bits, s->lambda);

        tdist += dist;

    }



    *total_dist = tdist;



    return 0;

}

int split_commandline(OptionParseContext *octx, int argc, char *argv[],

                      const OptionDef *options,

                      const OptionGroupDef *groups)

{

    int optindex = 1;



    /* perform system-dependent conversions for arguments list */

    prepare_app_arguments(&argc, &argv);



    init_parse_context(octx, groups);

    av_log(NULL, AV_LOG_DEBUG, "Splitting the commandline.\n");



    while (optindex < argc) {

        const char *opt = argv[optindex++], *arg;

        const OptionDef *po;

        int ret;



        av_log(NULL, AV_LOG_DEBUG, "Reading option '%s' ...", opt);



        /* unnamed group separators, e.g. output filename */

        if (opt[0] != '-' || !opt[1]) {

            finish_group(octx, 0, opt);

            av_log(NULL, AV_LOG_DEBUG, " matched as %s.\n", groups[0].name);

            continue;

        }

        opt++;



#define GET_ARG(arg)                                                           \

do {                                                                           \

    arg = argv[optindex++];                                                    \

    if (!arg) {                                                                \

        av_log(NULL, AV_LOG_ERROR, "Missing argument for option '%s'.\n", opt);\

        return AVERROR(EINVAL);                                                \

    }                                                                          \

} while (0)



        /* named group separators, e.g. -i */

        if ((ret = match_group_separator(groups, opt)) >= 0) {

            GET_ARG(arg);

            finish_group(octx, ret, arg);

            av_log(NULL, AV_LOG_DEBUG, " matched as %s with argument '%s'.\n",

                   groups[ret].name, arg);

            continue;

        }



        /* normal options */

        po = find_option(options, opt);

        if (po->name) {

            if (po->flags & OPT_EXIT) {

                /* optional argument, e.g. -h */

                arg = argv[optindex++];

            } else if (po->flags & HAS_ARG) {

                GET_ARG(arg);

            } else {

                arg = "1";

            }



            add_opt(octx, po, opt, arg);

            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "

                   "argument '%s'.\n", po->name, po->help, arg);

            continue;

        }



        /* AVOptions */

        if (argv[optindex]) {

            ret = opt_default(NULL, opt, argv[optindex]);

            if (ret >= 0) {

                av_log(NULL, AV_LOG_DEBUG, " matched as AVOption '%s' with "

                       "argument '%s'.\n", opt, argv[optindex]);

                optindex++;

                continue;

            } else if (ret != AVERROR_OPTION_NOT_FOUND) {

                av_log(NULL, AV_LOG_ERROR, "Error parsing option '%s' "

                       "with argument '%s'.\n", opt, argv[optindex]);

                return ret;

            }

        }



        /* boolean -nofoo options */

        if (opt[0] == 'n' && opt[1] == 'o' &&

            (po = find_option(options, opt + 2)) &&

            po->name && po->flags & OPT_BOOL) {

            add_opt(octx, po, opt, "0");

            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "

                   "argument 0.\n", po->name, po->help);

            continue;

        }



        av_log(NULL, AV_LOG_ERROR, "Unrecognized option '%s'.\n", opt);

        return AVERROR_OPTION_NOT_FOUND;

    }



    if (octx->cur_group.nb_opts || codec_opts || format_opts)

        av_log(NULL, AV_LOG_WARNING, "Trailing options were found on the "

               "commandline.\n");



    av_log(NULL, AV_LOG_DEBUG, "Finished splitting the commandline.\n");



    return 0;

}

static int configure_accelerator(MachineClass *mc)

{

    const char *p;

    char buf[10];

    int i, ret;

    bool accel_initialised = false;

    bool init_failed = false;



    p = qemu_opt_get(qemu_get_machine_opts(), "accel");

    if (p == NULL) {

        /* Use the default "accelerator", tcg */

        p = "tcg";

    }



    while (!accel_initialised && *p != '\0') {

        if (*p == ':') {

            p++;

        }

        p = get_opt_name(buf, sizeof (buf), p, ':');

        for (i = 0; i < ARRAY_SIZE(accel_list); i++) {

            if (strcmp(accel_list[i].opt_name, buf) == 0) {

                if (!accel_list[i].available()) {

                    printf("%s not supported for this target\n",

                           accel_list[i].name);

                    break;

                }

                *(accel_list[i].allowed) = true;

                ret = accel_list[i].init(mc);

                if (ret < 0) {

                    init_failed = true;

                    fprintf(stderr, "failed to initialize %s: %s\n",

                            accel_list[i].name,

                            strerror(-ret));

                    *(accel_list[i].allowed) = false;

                } else {

                    accel_initialised = true;

                }

                break;

            }

        }

        if (i == ARRAY_SIZE(accel_list)) {

            fprintf(stderr, "\"%s\" accelerator does not exist.\n", buf);

        }

    }



    if (!accel_initialised) {

        if (!init_failed) {

            fprintf(stderr, "No accelerator found!\n");

        }

        exit(1);

    }



    if (init_failed) {

        fprintf(stderr, "Back to %s accelerator.\n", accel_list[i].name);

    }



    return !accel_initialised;

}

