int ff_intel_h263_decode_picture_header(MpegEncContext *s)

{

    int format;



    /* picture header */

    if (get_bits_long(&s->gb, 22) != 0x20) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");

        return -1;

    }

    s->picture_number = get_bits(&s->gb, 8); /* picture timestamp */



    if (get_bits1(&s->gb) != 1) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad marker\n");

        return -1;      /* marker */

    }

    if (get_bits1(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad H263 id\n");

        return -1;      /* h263 id */

    }

    skip_bits1(&s->gb);         /* split screen off */

    skip_bits1(&s->gb);         /* camera  off */

    skip_bits1(&s->gb);         /* freeze picture release off */



    format = get_bits(&s->gb, 3);

    if (format == 0 || format == 6) {

        av_log(s->avctx, AV_LOG_ERROR, "Intel H263 free format not supported\n");

        return -1;

    }

    s->h263_plus = 0;



    s->pict_type = AV_PICTURE_TYPE_I + get_bits1(&s->gb);



    s->unrestricted_mv = get_bits1(&s->gb);

    s->h263_long_vectors = s->unrestricted_mv;



    if (get_bits1(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "SAC not supported\n");

        return -1;      /* SAC: off */

    }

    s->obmc= get_bits1(&s->gb);

    s->pb_frame = get_bits1(&s->gb);



    if (format < 6) {

        s->width = ff_h263_format[format][0];

        s->height = ff_h263_format[format][1];

        s->avctx->sample_aspect_ratio.num = 12;

        s->avctx->sample_aspect_ratio.den = 11;

    } else {

        format = get_bits(&s->gb, 3);

        if(format == 0 || format == 7){

            av_log(s->avctx, AV_LOG_ERROR, "Wrong Intel H263 format\n");

            return -1;

        }

        if(get_bits(&s->gb, 2))

            av_log(s->avctx, AV_LOG_ERROR, "Bad value for reserved field\n");

        s->loop_filter = get_bits1(&s->gb);

        if(get_bits1(&s->gb))

            av_log(s->avctx, AV_LOG_ERROR, "Bad value for reserved field\n");

        if(get_bits1(&s->gb))

            s->pb_frame = 2;

        if(get_bits(&s->gb, 5))

            av_log(s->avctx, AV_LOG_ERROR, "Bad value for reserved field\n");

        if(get_bits(&s->gb, 5) != 1)

            av_log(s->avctx, AV_LOG_ERROR, "Invalid marker\n");

    }

    if(format == 6){

        int ar = get_bits(&s->gb, 4);

        skip_bits(&s->gb, 9); // display width

        skip_bits1(&s->gb);

        skip_bits(&s->gb, 9); // display height

        if(ar == 15){

            s->avctx->sample_aspect_ratio.num = get_bits(&s->gb, 8); // aspect ratio - width

            s->avctx->sample_aspect_ratio.den = get_bits(&s->gb, 8); // aspect ratio - height

        } else {

            s->avctx->sample_aspect_ratio = ff_h263_pixel_aspect[ar];

        }

        if (s->avctx->sample_aspect_ratio.num == 0)

            av_log(s->avctx, AV_LOG_ERROR, "Invalid aspect ratio.\n");

    }



    s->chroma_qscale= s->qscale = get_bits(&s->gb, 5);

    skip_bits1(&s->gb); /* Continuous Presence Multipoint mode: off */



    if(s->pb_frame){

        skip_bits(&s->gb, 3); //temporal reference for B-frame

        skip_bits(&s->gb, 2); //dbquant

    }



    /* PEI */

    while (get_bits1(&s->gb) != 0) {

        skip_bits(&s->gb, 8);

    }

    s->f_code = 1;



    s->y_dc_scale_table=

    s->c_dc_scale_table= ff_mpeg1_dc_scale_table;



    ff_h263_show_pict_info(s);



    return 0;

}

static int xenstore_scan(const char *type, int dom, struct XenDevOps *ops)

{

    struct XenDevice *xendev;

    char path[XEN_BUFSIZE], token[XEN_BUFSIZE];

    char **dev = NULL, *dom0;

    unsigned int cdev, j;



    /* setup watch */

    dom0 = xs_get_domain_path(xenstore, 0);

    snprintf(token, sizeof(token), "be:%p:%d:%p", type, dom, ops);

    snprintf(path, sizeof(path), "%s/backend/%s/%d", dom0, type, dom);

    free(dom0);

    if (!xs_watch(xenstore, path, token)) {

        xen_be_printf(NULL, 0, "xen be: watching backend path (%s) failed\n", path);

        return -1;

    }



    /* look for backends */

    dev = xs_directory(xenstore, 0, path, &cdev);

    if (!dev) {

        return 0;

    }

    for (j = 0; j < cdev; j++) {

        xendev = xen_be_get_xendev(type, dom, atoi(dev[j]), ops);

        if (xendev == NULL) {

            continue;

        }

        xen_be_check_state(xendev);

    }

    free(dev);

    return 0;

}

static int vfio_initfn(PCIDevice *pdev)

{

    VFIODevice *pvdev, *vdev = DO_UPCAST(VFIODevice, pdev, pdev);

    VFIOGroup *group;

    char path[PATH_MAX], iommu_group_path[PATH_MAX], *group_name;

    ssize_t len;

    struct stat st;

    int groupid;

    int ret;



    /* Check that the host device exists */

    snprintf(path, sizeof(path),

             "/sys/bus/pci/devices/%04x:%02x:%02x.%01x/",

             vdev->host.domain, vdev->host.bus, vdev->host.slot,

             vdev->host.function);

    if (stat(path, &st) < 0) {

        error_report("vfio: error: no such host device: %s", path);

        return -errno;

    }



    strncat(path, "iommu_group", sizeof(path) - strlen(path) - 1);



    len = readlink(path, iommu_group_path, PATH_MAX);

    if (len <= 0) {

        error_report("vfio: error no iommu_group for device");

        return -errno;

    }



    iommu_group_path[len] = 0;

    group_name = basename(iommu_group_path);



    if (sscanf(group_name, "%d", &groupid) != 1) {

        error_report("vfio: error reading %s: %m", path);

        return -errno;

    }



    DPRINTF("%s(%04x:%02x:%02x.%x) group %d\n", __func__, vdev->host.domain,

            vdev->host.bus, vdev->host.slot, vdev->host.function, groupid);



    group = vfio_get_group(groupid);

    if (!group) {

        error_report("vfio: failed to get group %d", groupid);

        return -ENOENT;

    }



    snprintf(path, sizeof(path), "%04x:%02x:%02x.%01x",

            vdev->host.domain, vdev->host.bus, vdev->host.slot,

            vdev->host.function);



    QLIST_FOREACH(pvdev, &group->device_list, next) {

        if (pvdev->host.domain == vdev->host.domain &&

            pvdev->host.bus == vdev->host.bus &&

            pvdev->host.slot == vdev->host.slot &&

            pvdev->host.function == vdev->host.function) {



            error_report("vfio: error: device %s is already attached", path);

            vfio_put_group(group);

            return -EBUSY;

        }

    }



    ret = vfio_get_device(group, path, vdev);

    if (ret) {

        error_report("vfio: failed to get device %s", path);

        vfio_put_group(group);

        return ret;

    }



    /* Get a copy of config space */

    ret = pread(vdev->fd, vdev->pdev.config,

                MIN(pci_config_size(&vdev->pdev), vdev->config_size),

                vdev->config_offset);

    if (ret < (int)MIN(pci_config_size(&vdev->pdev), vdev->config_size)) {

        ret = ret < 0 ? -errno : -EFAULT;

        error_report("vfio: Failed to read device config space");

        goto out_put;

    }



    /* vfio emulates a lot for us, but some bits need extra love */

    vdev->emulated_config_bits = g_malloc0(vdev->config_size);



    /* QEMU can choose to expose the ROM or not */

    memset(vdev->emulated_config_bits + PCI_ROM_ADDRESS, 0xff, 4);



    /* QEMU can change multi-function devices to single function, or reverse */

    vdev->emulated_config_bits[PCI_HEADER_TYPE] =

                                              PCI_HEADER_TYPE_MULTI_FUNCTION;



    /* Restore or clear multifunction, this is always controlled by QEMU */

    if (vdev->pdev.cap_present & QEMU_PCI_CAP_MULTIFUNCTION) {

        vdev->pdev.config[PCI_HEADER_TYPE] |= PCI_HEADER_TYPE_MULTI_FUNCTION;

    } else {

        vdev->pdev.config[PCI_HEADER_TYPE] &= ~PCI_HEADER_TYPE_MULTI_FUNCTION;

    }



    /*

     * Clear host resource mapping info.  If we choose not to register a

     * BAR, such as might be the case with the option ROM, we can get

     * confusing, unwritable, residual addresses from the host here.

     */

    memset(&vdev->pdev.config[PCI_BASE_ADDRESS_0], 0, 24);

    memset(&vdev->pdev.config[PCI_ROM_ADDRESS], 0, 4);



    vfio_pci_size_rom(vdev);



    ret = vfio_early_setup_msix(vdev);

    if (ret) {

        goto out_put;

    }



    vfio_map_bars(vdev);



    ret = vfio_add_capabilities(vdev);

    if (ret) {

        goto out_teardown;

    }



    /* QEMU emulates all of MSI & MSIX */

    if (pdev->cap_present & QEMU_PCI_CAP_MSIX) {

        memset(vdev->emulated_config_bits + pdev->msix_cap, 0xff,

               MSIX_CAP_LENGTH);

    }



    if (pdev->cap_present & QEMU_PCI_CAP_MSI) {

        memset(vdev->emulated_config_bits + pdev->msi_cap, 0xff,

               vdev->msi_cap_size);

    }



    if (vfio_pci_read_config(&vdev->pdev, PCI_INTERRUPT_PIN, 1)) {

        vdev->intx.mmap_timer = timer_new_ms(QEMU_CLOCK_VIRTUAL,

                                                  vfio_intx_mmap_enable, vdev);

        pci_device_set_intx_routing_notifier(&vdev->pdev, vfio_update_irq);

        ret = vfio_enable_intx(vdev);

        if (ret) {

            goto out_teardown;

        }

    }



    add_boot_device_path(vdev->bootindex, &pdev->qdev, NULL);

    vfio_register_err_notifier(vdev);



    return 0;



out_teardown:

    pci_device_set_intx_routing_notifier(&vdev->pdev, NULL);

    vfio_teardown_msi(vdev);

    vfio_unmap_bars(vdev);

out_put:

    g_free(vdev->emulated_config_bits);

    vfio_put_device(vdev);

    vfio_put_group(group);

    return ret;

}

build_fadt(GArray *table_data, BIOSLinker *linker, unsigned dsdt)

{

    AcpiFadtDescriptorRev5_1 *fadt = acpi_data_push(table_data, sizeof(*fadt));



    /* Hardware Reduced = 1 and use PSCI 0.2+ and with HVC */

    fadt->flags = cpu_to_le32(1 << ACPI_FADT_F_HW_REDUCED_ACPI);

    fadt->arm_boot_flags = cpu_to_le16((1 << ACPI_FADT_ARM_USE_PSCI_G_0_2) |

                                       (1 << ACPI_FADT_ARM_PSCI_USE_HVC));



    /* ACPI v5.1 (fadt->revision.fadt->minor_revision) */

    fadt->minor_revision = 0x1;



    fadt->dsdt = cpu_to_le32(dsdt);

    /* DSDT address to be filled by Guest linker */

    bios_linker_loader_add_pointer(linker, ACPI_BUILD_TABLE_FILE,

                                   ACPI_BUILD_TABLE_FILE,

                                   &fadt->dsdt,

                                   sizeof fadt->dsdt);



    build_header(linker, table_data,

                 (void *)fadt, "FACP", sizeof(*fadt), 5, NULL, NULL);

}

