{

    int ret = blk_check_request(blk, sector_num, nb_sectors);

    if (ret < 0) {

        return ret;

    }



    return bdrv_co_discard(blk_bs(blk), sector_num, nb_sectors);

}

static void mmubooke_create_initial_mapping(CPUPPCState *env,

                                     target_ulong va,

                                     hwaddr pa)

{

    ppcemb_tlb_t *tlb = &env->tlb.tlbe[0];



    tlb->attr = 0;

    tlb->prot = PAGE_VALID | ((PAGE_READ | PAGE_WRITE | PAGE_EXEC) << 4);

    tlb->size = 1 << 31; /* up to 0x80000000  */

    tlb->EPN = va & TARGET_PAGE_MASK;

    tlb->RPN = pa & TARGET_PAGE_MASK;

    tlb->PID = 0;



    tlb = &env->tlb.tlbe[1];

    tlb->attr = 0;

    tlb->prot = PAGE_VALID | ((PAGE_READ | PAGE_WRITE | PAGE_EXEC) << 4);

    tlb->size = 1 << 31; /* up to 0xffffffff  */

    tlb->EPN = 0x80000000 & TARGET_PAGE_MASK;

    tlb->RPN = 0x80000000 & TARGET_PAGE_MASK;

    tlb->PID = 0;

}

void qemu_ram_foreach_block(RAMBlockIterFunc func, void *opaque)

{

    RAMBlock *block;



    rcu_read_lock();

    QLIST_FOREACH_RCU(block, &ram_list.blocks, next) {

        func(block->host, block->offset, block->used_length, opaque);

    }

    rcu_read_unlock();

}

int avformat_queue_attached_pictures(AVFormatContext *s)

{

    int i;

    for (i = 0; i < s->nb_streams; i++)

        if (s->streams[i]->disposition & AV_DISPOSITION_ATTACHED_PIC &&

            s->streams[i]->discard < AVDISCARD_ALL) {

            AVPacket copy = s->streams[i]->attached_pic;

            if (copy.size <= 0)

                return AVERROR(EINVAL);

            copy.buf = av_buffer_ref(copy.buf);

            if (!copy.buf)

                return AVERROR(ENOMEM);



            add_to_pktbuf(&s->raw_packet_buffer, &copy,

                          &s->raw_packet_buffer_end);

        }

    return 0;

}

static int g2m_init_buffers(G2MContext *c)

{

    int aligned_height;



    if (!c->framebuf || c->old_width < c->width || c->old_height < c->height) {

        c->framebuf_stride = FFALIGN(c->width * 3, 16);

        aligned_height     = FFALIGN(c->height,    16);

        av_free(c->framebuf);

        c->framebuf = av_mallocz(c->framebuf_stride * aligned_height);

        if (!c->framebuf)

            return AVERROR(ENOMEM);

    }

    if (!c->synth_tile || !c->jpeg_tile ||

        c->old_tile_w < c->tile_width ||

        c->old_tile_h < c->tile_height) {

        c->tile_stride = FFALIGN(c->tile_width * 3, 16);

        aligned_height = FFALIGN(c->tile_height,    16);

        av_free(c->synth_tile);

        av_free(c->jpeg_tile);

        av_free(c->kempf_buf);

        av_free(c->kempf_flags);

        c->synth_tile  = av_mallocz(c->tile_stride      * aligned_height);

        c->jpeg_tile   = av_mallocz(c->tile_stride      * aligned_height);

        c->kempf_buf   = av_mallocz((c->tile_width + 1) * aligned_height

                                    + FF_INPUT_BUFFER_PADDING_SIZE);

        c->kempf_flags = av_mallocz( c->tile_width      * aligned_height);

        if (!c->synth_tile || !c->jpeg_tile ||

            !c->kempf_buf || !c->kempf_flags)

            return AVERROR(ENOMEM);

    }



    return 0;

}

void blk_remove_bs(BlockBackend *blk)

{

    BlockDriverState *bs;

    ThrottleTimers *tt;



    notifier_list_notify(&blk->remove_bs_notifiers, blk);

    if (blk->public.throttle_group_member.throttle_state) {

        tt = &blk->public.throttle_group_member.throttle_timers;

        bs = blk_bs(blk);

        bdrv_drained_begin(bs);

        throttle_timers_detach_aio_context(tt);

        bdrv_drained_end(bs);

    }



    blk_update_root_state(blk);



    bdrv_root_unref_child(blk->root);

    blk->root = NULL;

}

static inline void asv2_encode_block(ASV1Context *a, int16_t block[64])

{

    int i;

    int count = 0;



    for (count = 63; count > 3; count--) {

        const int index = ff_asv_scantab[count];

        if ((block[index] * a->q_intra_matrix[index] + (1 << 15)) >> 16)

            break;

    }



    count >>= 2;



    asv2_put_bits(&a->pb, 4, count);

    asv2_put_bits(&a->pb, 8, (block[0] + 32) >> 6);

    block[0] = 0;



    for (i = 0; i <= count; i++) {

        const int index = ff_asv_scantab[4 * i];

        int ccp         = 0;



        if ((block[index + 0] = (block[index + 0] *

                                 a->q_intra_matrix[index + 0] + (1 << 15)) >> 16))

            ccp |= 8;

        if ((block[index + 8] = (block[index + 8] *

                                 a->q_intra_matrix[index + 8] + (1 << 15)) >> 16))

            ccp |= 4;

        if ((block[index + 1] = (block[index + 1] *

                                 a->q_intra_matrix[index + 1] + (1 << 15)) >> 16))

            ccp |= 2;

        if ((block[index + 9] = (block[index + 9] *

                                 a->q_intra_matrix[index + 9] + (1 << 15)) >> 16))

            ccp |= 1;



        av_assert2(i || ccp < 8);

        if (i)

            put_bits(&a->pb, ff_asv_ac_ccp_tab[ccp][1], ff_asv_ac_ccp_tab[ccp][0]);

        else

            put_bits(&a->pb, ff_asv_dc_ccp_tab[ccp][1], ff_asv_dc_ccp_tab[ccp][0]);



        if (ccp) {

            if (ccp & 8)

                asv2_put_level(&a->pb, block[index + 0]);

            if (ccp & 4)

                asv2_put_level(&a->pb, block[index + 8]);

            if (ccp & 2)

                asv2_put_level(&a->pb, block[index + 1]);

            if (ccp & 1)

                asv2_put_level(&a->pb, block[index + 9]);

        }

    }

}

static hwaddr ppc_hash64_htab_lookup(PowerPCCPU *cpu,

                                     ppc_slb_t *slb, target_ulong eaddr,

                                     ppc_hash_pte64_t *pte)

{

    CPUPPCState *env = &cpu->env;

    hwaddr pte_offset;

    hwaddr hash;

    uint64_t vsid, epnmask, epn, ptem;



    /* The SLB store path should prevent any bad page size encodings

     * getting in there, so: */

    assert(slb->sps);



    epnmask = ~((1ULL << slb->sps->page_shift) - 1);



    if (slb->vsid & SLB_VSID_B) {

        /* 1TB segment */

        vsid = (slb->vsid & SLB_VSID_VSID) >> SLB_VSID_SHIFT_1T;

        epn = (eaddr & ~SEGMENT_MASK_1T) & epnmask;

        hash = vsid ^ (vsid << 25) ^ (epn >> slb->sps->page_shift);

    } else {

        /* 256M segment */

        vsid = (slb->vsid & SLB_VSID_VSID) >> SLB_VSID_SHIFT;

        epn = (eaddr & ~SEGMENT_MASK_256M) & epnmask;

        hash = vsid ^ (epn >> slb->sps->page_shift);

    }

    ptem = (slb->vsid & SLB_VSID_PTEM) | ((epn >> 16) & HPTE64_V_AVPN);



    /* Page address translation */

    qemu_log_mask(CPU_LOG_MMU,

            "htab_base " TARGET_FMT_plx " htab_mask " TARGET_FMT_plx

            " hash " TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, hash);



    /* Primary PTEG lookup */

    qemu_log_mask(CPU_LOG_MMU,

            "0 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

            " vsid=" TARGET_FMT_lx " ptem=" TARGET_FMT_lx

            " hash=" TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, vsid, ptem,  hash);

    pte_offset = ppc_hash64_pteg_search(cpu, hash, slb, 0, ptem, pte);



    if (pte_offset == -1) {

        /* Secondary PTEG lookup */

        qemu_log_mask(CPU_LOG_MMU,

                "1 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

                " vsid=" TARGET_FMT_lx " api=" TARGET_FMT_lx

                " hash=" TARGET_FMT_plx "\n", env->htab_base,

                env->htab_mask, vsid, ptem, ~hash);



        pte_offset = ppc_hash64_pteg_search(cpu, ~hash, slb, 1, ptem, pte);

    }



    return pte_offset;

}

void memory_region_init_alias(MemoryRegion *mr,

                              Object *owner,

                              const char *name,

                              MemoryRegion *orig,

                              hwaddr offset,

                              uint64_t size)

{

    memory_region_init(mr, owner, name, size);

    memory_region_ref(orig);

    mr->destructor = memory_region_destructor_alias;

    mr->alias = orig;

    mr->alias_offset = offset;

}

static void omap_rtc_write(void *opaque, hwaddr addr,

                           uint64_t value, unsigned size)

{

    struct omap_rtc_s *s = (struct omap_rtc_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;

    struct tm new_tm;

    time_t ti[2];



    if (size != 1) {

        return omap_badwidth_write8(opaque, addr, value);

    }



    switch (offset) {

    case 0x00:	/* SECONDS_REG */

#ifdef ALMDEBUG

        printf("RTC SEC_REG <-- %02x\n", value);

#endif

        s->ti -= s->current_tm.tm_sec;

        s->ti += from_bcd(value);

        return;



    case 0x04:	/* MINUTES_REG */

#ifdef ALMDEBUG

        printf("RTC MIN_REG <-- %02x\n", value);

#endif

        s->ti -= s->current_tm.tm_min * 60;

        s->ti += from_bcd(value) * 60;

        return;



    case 0x08:	/* HOURS_REG */

#ifdef ALMDEBUG

        printf("RTC HRS_REG <-- %02x\n", value);

#endif

        s->ti -= s->current_tm.tm_hour * 3600;

        if (s->pm_am) {

            s->ti += (from_bcd(value & 0x3f) & 12) * 3600;

            s->ti += ((value >> 7) & 1) * 43200;

        } else

            s->ti += from_bcd(value & 0x3f) * 3600;

        return;



    case 0x0c:	/* DAYS_REG */

#ifdef ALMDEBUG

        printf("RTC DAY_REG <-- %02x\n", value);

#endif

        s->ti -= s->current_tm.tm_mday * 86400;

        s->ti += from_bcd(value) * 86400;

        return;



    case 0x10:	/* MONTHS_REG */

#ifdef ALMDEBUG

        printf("RTC MTH_REG <-- %02x\n", value);

#endif

        memcpy(&new_tm, &s->current_tm, sizeof(new_tm));

        new_tm.tm_mon = from_bcd(value);

        ti[0] = mktimegm(&s->current_tm);

        ti[1] = mktimegm(&new_tm);



        if (ti[0] != -1 && ti[1] != -1) {

            s->ti -= ti[0];

            s->ti += ti[1];

        } else {

            /* A less accurate version */

            s->ti -= s->current_tm.tm_mon * 2592000;

            s->ti += from_bcd(value) * 2592000;

        }

        return;



    case 0x14:	/* YEARS_REG */

#ifdef ALMDEBUG

        printf("RTC YRS_REG <-- %02x\n", value);

#endif

        memcpy(&new_tm, &s->current_tm, sizeof(new_tm));

        new_tm.tm_year += from_bcd(value) - (new_tm.tm_year % 100);

        ti[0] = mktimegm(&s->current_tm);

        ti[1] = mktimegm(&new_tm);



        if (ti[0] != -1 && ti[1] != -1) {

            s->ti -= ti[0];

            s->ti += ti[1];

        } else {

            /* A less accurate version */

            s->ti -= (s->current_tm.tm_year % 100) * 31536000;

            s->ti += from_bcd(value) * 31536000;

        }

        return;



    case 0x18:	/* WEEK_REG */

        return;	/* Ignored */



    case 0x20:	/* ALARM_SECONDS_REG */

#ifdef ALMDEBUG

        printf("ALM SEC_REG <-- %02x\n", value);

#endif

        s->alarm_tm.tm_sec = from_bcd(value);

        omap_rtc_alarm_update(s);

        return;



    case 0x24:	/* ALARM_MINUTES_REG */

#ifdef ALMDEBUG

        printf("ALM MIN_REG <-- %02x\n", value);

#endif

        s->alarm_tm.tm_min = from_bcd(value);

        omap_rtc_alarm_update(s);

        return;



    case 0x28:	/* ALARM_HOURS_REG */

#ifdef ALMDEBUG

        printf("ALM HRS_REG <-- %02x\n", value);

#endif

        if (s->pm_am)

            s->alarm_tm.tm_hour =

                    ((from_bcd(value & 0x3f)) % 12) +

                    ((value >> 7) & 1) * 12;

        else

            s->alarm_tm.tm_hour = from_bcd(value);

        omap_rtc_alarm_update(s);

        return;



    case 0x2c:	/* ALARM_DAYS_REG */

#ifdef ALMDEBUG

        printf("ALM DAY_REG <-- %02x\n", value);

#endif

        s->alarm_tm.tm_mday = from_bcd(value);

        omap_rtc_alarm_update(s);

        return;



    case 0x30:	/* ALARM_MONTHS_REG */

#ifdef ALMDEBUG

        printf("ALM MON_REG <-- %02x\n", value);

#endif

        s->alarm_tm.tm_mon = from_bcd(value);

        omap_rtc_alarm_update(s);

        return;



    case 0x34:	/* ALARM_YEARS_REG */

#ifdef ALMDEBUG

        printf("ALM YRS_REG <-- %02x\n", value);

#endif

        s->alarm_tm.tm_year = from_bcd(value);

        omap_rtc_alarm_update(s);

        return;



    case 0x40:	/* RTC_CTRL_REG */

#ifdef ALMDEBUG

        printf("RTC CONTROL <-- %02x\n", value);

#endif

        s->pm_am = (value >> 3) & 1;

        s->auto_comp = (value >> 2) & 1;

        s->round = (value >> 1) & 1;

        s->running = value & 1;

        s->status &= 0xfd;

        s->status |= s->running << 1;

        return;



    case 0x44:	/* RTC_STATUS_REG */

#ifdef ALMDEBUG

        printf("RTC STATUSL <-- %02x\n", value);

#endif

        s->status &= ~((value & 0xc0) ^ 0x80);

        omap_rtc_interrupts_update(s);

        return;



    case 0x48:	/* RTC_INTERRUPTS_REG */

#ifdef ALMDEBUG

        printf("RTC INTRS <-- %02x\n", value);

#endif

        s->interrupts = value;

        return;



    case 0x4c:	/* RTC_COMP_LSB_REG */

#ifdef ALMDEBUG

        printf("RTC COMPLSB <-- %02x\n", value);

#endif

        s->comp_reg &= 0xff00;

        s->comp_reg |= 0x00ff & value;

        return;



    case 0x50:	/* RTC_COMP_MSB_REG */

#ifdef ALMDEBUG

        printf("RTC COMPMSB <-- %02x\n", value);

#endif

        s->comp_reg &= 0x00ff;

        s->comp_reg |= 0xff00 & (value << 8);

        return;



    default:

        OMAP_BAD_REG(addr);

        return;

    }

}

static int opt_preset(const char *opt, const char *arg)

{

    FILE *f=NULL;

    char filename[1000], tmp[1000], tmp2[1000], line[1000];

    int i;

    const char *base[3]= { getenv("HOME"),

                           "/usr/local/share",

                           "/usr/share",

                         };



    for(i=!base[0]; i<3 && !f; i++){

        snprintf(filename, sizeof(filename), "%s/%sffmpeg/%s.ffpreset", base[i], i ? "" : ".", arg);

        f= fopen(filename, "r");

        if(!f){

            char *codec_name= *opt == 'v' ? video_codec_name :

                              *opt == 'a' ? audio_codec_name :

                                            subtitle_codec_name;

            snprintf(filename, sizeof(filename), "%s/%sffmpeg/%s-%s.ffpreset", base[i],  i ? "" : ".", codec_name, arg);

            f= fopen(filename, "r");

        }

    }

    if(!f && ((arg[0]=='.' && arg[1]=='/') || arg[0]=='/' ||

              is_dos_path(arg))){

        snprintf(filename, sizeof(filename), arg);

        f= fopen(filename, "r");

    }



    if(!f){

        fprintf(stderr, "File for preset '%s' not found\n", arg);

        av_exit(1);

    }



    while(!feof(f)){

        int e= fscanf(f, "%999[^\n]\n", line) - 1;

        if(line[0] == '#' && !e)

            continue;

        e|= sscanf(line, "%999[^=]=%999[^\n]\n", tmp, tmp2) - 2;

        if(e){

            fprintf(stderr, "%s: Preset file invalid\n", filename);

            av_exit(1);

        }

        if(!strcmp(tmp, "acodec")){

            opt_audio_codec(tmp2);

        }else if(!strcmp(tmp, "vcodec")){

            opt_video_codec(tmp2);

        }else if(!strcmp(tmp, "scodec")){

            opt_subtitle_codec(tmp2);

        }else if(opt_default(tmp, tmp2) < 0){

            fprintf(stderr, "%s: Invalid option or argument: %s=%s\n", filename, tmp, tmp2);

            av_exit(1);

        }

    }



    fclose(f);



    return 0;

}

static void qmp_input_type_str(Visitor *v, char **obj, const char *name,

                               Error **errp)

{

    QmpInputVisitor *qiv = to_qiv(v);

    QObject *qobj = qmp_input_get_object(qiv, name, true);



    if (!qobj || qobject_type(qobj) != QTYPE_QSTRING) {

        error_setg(errp, QERR_INVALID_PARAMETER_TYPE, name ? name : "null",

                   "string");

        return;

    }



    *obj = g_strdup(qstring_get_str(qobject_to_qstring(qobj)));

}

static int blend_frames(AVFilterContext *ctx, int interpolate)

{

    FrameRateContext *s = ctx->priv;

    AVFilterLink *outlink = ctx->outputs[0];

    double interpolate_scene_score = 0;



    if ((s->flags & FRAMERATE_FLAG_SCD)) {

        if (s->score >= 0.0)

            interpolate_scene_score = s->score;

        else

            interpolate_scene_score = s->score = get_scene_score(ctx, s->f0, s->f1);

        ff_dlog(ctx, "blend_frames() interpolate scene score:%f\n", interpolate_scene_score);

    }

    // decide if the shot-change detection allows us to blend two frames

    if (interpolate_scene_score < s->scene_score) {

        ThreadData td;

        td.copy_src1 = s->f0;

        td.copy_src2 = s->f1;

        td.src2_factor = interpolate;

        td.src1_factor = s->max - td.src2_factor;



        // get work-space for output frame

        s->work = ff_get_video_buffer(outlink, outlink->w, outlink->h);

        if (!s->work)

            return AVERROR(ENOMEM);



        av_frame_copy_props(s->work, s->f0);



        ff_dlog(ctx, "blend_frames() INTERPOLATE to create work frame\n");

        ctx->internal->execute(ctx, filter_slice, &td, NULL, FFMIN(outlink->h, ff_filter_get_nb_threads(ctx)));

        return 1;

    }

    return 0;

}

static int mpc7_decode_frame(AVCodecContext * avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MPCContext *c = avctx->priv_data;

    GetBitContext gb;

    uint8_t *bits;

    int i, ch;

    int mb = -1;

    Band *bands = c->bands;

    int off, ret;

    int bits_used, bits_avail;



    memset(bands, 0, sizeof(*bands) * (c->maxbands + 1));

    if(buf_size <= 4){

        av_log(avctx, AV_LOG_ERROR, "Too small buffer passed (%i bytes)\n", buf_size);

        return AVERROR(EINVAL);

    }



    /* get output buffer */

    c->frame.nb_samples = buf[1] ? c->lastframelen : MPC_FRAME_SIZE;

    if ((ret = avctx->get_buffer(avctx, &c->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    bits = av_malloc(((buf_size - 1) & ~3) + FF_INPUT_BUFFER_PADDING_SIZE);



    c->dsp.bswap_buf((uint32_t*)bits, (const uint32_t*)(buf + 4), (buf_size - 4) >> 2);

    init_get_bits(&gb, bits, (buf_size - 4)* 8);

    skip_bits_long(&gb, buf[0]);



    /* read subband indexes */

    for(i = 0; i <= c->maxbands; i++){

        for(ch = 0; ch < 2; ch++){

            int t = 4;

            if(i) t = get_vlc2(&gb, hdr_vlc.table, MPC7_HDR_BITS, 1) - 5;

            if(t == 4) bands[i].res[ch] = get_bits(&gb, 4);

            else bands[i].res[ch] = bands[i-1].res[ch] + t;

        }



        if(bands[i].res[0] || bands[i].res[1]){

            mb = i;

            if(c->MSS) bands[i].msf = get_bits1(&gb);

        }

    }

    /* get scale indexes coding method */

    for(i = 0; i <= mb; i++)

        for(ch = 0; ch < 2; ch++)

            if(bands[i].res[ch]) bands[i].scfi[ch] = get_vlc2(&gb, scfi_vlc.table, MPC7_SCFI_BITS, 1);

    /* get scale indexes */

    for(i = 0; i <= mb; i++){

        for(ch = 0; ch < 2; ch++){

            if(bands[i].res[ch]){

                bands[i].scf_idx[ch][2] = c->oldDSCF[ch][i];

                bands[i].scf_idx[ch][0] = get_scale_idx(&gb, bands[i].scf_idx[ch][2]);

                switch(bands[i].scfi[ch]){

                case 0:

                    bands[i].scf_idx[ch][1] = get_scale_idx(&gb, bands[i].scf_idx[ch][0]);

                    bands[i].scf_idx[ch][2] = get_scale_idx(&gb, bands[i].scf_idx[ch][1]);

                    break;

                case 1:

                    bands[i].scf_idx[ch][1] = get_scale_idx(&gb, bands[i].scf_idx[ch][0]);

                    bands[i].scf_idx[ch][2] = bands[i].scf_idx[ch][1];

                    break;

                case 2:

                    bands[i].scf_idx[ch][1] = bands[i].scf_idx[ch][0];

                    bands[i].scf_idx[ch][2] = get_scale_idx(&gb, bands[i].scf_idx[ch][1]);

                    break;

                case 3:

                    bands[i].scf_idx[ch][2] = bands[i].scf_idx[ch][1] = bands[i].scf_idx[ch][0];

                    break;

                }

                c->oldDSCF[ch][i] = bands[i].scf_idx[ch][2];

            }

        }

    }

    /* get quantizers */

    memset(c->Q, 0, sizeof(c->Q));

    off = 0;

    for(i = 0; i < BANDS; i++, off += SAMPLES_PER_BAND)

        for(ch = 0; ch < 2; ch++)

            idx_to_quant(c, &gb, bands[i].res[ch], c->Q[ch] + off);



    ff_mpc_dequantize_and_synth(c, mb, c->frame.data[0], 2);



    av_free(bits);



    bits_used = get_bits_count(&gb);

    bits_avail = (buf_size - 4) * 8;

    if(!buf[1] && ((bits_avail < bits_used) || (bits_used + 32 <= bits_avail))){

        av_log(NULL,0, "Error decoding frame: used %i of %i bits\n", bits_used, bits_avail);

        return -1;

    }

    if(c->frames_to_skip){

        c->frames_to_skip--;

        *got_frame_ptr = 0;

        return buf_size;

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = c->frame;



    return buf_size;

}

static int get_str(char *buf, int buf_size, const char **pp)

{

    const char *p;

    char *q;

    int c;



    q = buf;

    p = *pp;

    while (qemu_isspace(*p))

        p++;

    if (*p == '\0') {

    fail:

        *q = '\0';

        *pp = p;

        return -1;

    }

    if (*p == '\"') {

        p++;

        while (*p != '\0' && *p != '\"') {

            if (*p == '\\') {

                p++;

                c = *p++;

                switch(c) {

                case 'n':

                    c = '\n';

                    break;

                case 'r':

                    c = '\r';

                    break;

                case '\\':

                case '\'':

                case '\"':

                    break;

                default:

                    qemu_printf("unsupported escape code: '\\%c'\n", c);

                    goto fail;

                }

                if ((q - buf) < buf_size - 1) {

                    *q++ = c;

                }

            } else {

                if ((q - buf) < buf_size - 1) {

                    *q++ = *p;

                }

                p++;

            }

        }

        if (*p != '\"') {

            qemu_printf("unterminated string\n");

            goto fail;

        }

        p++;

    } else {

        while (*p != '\0' && !qemu_isspace(*p)) {

            if ((q - buf) < buf_size - 1) {

                *q++ = *p;

            }

            p++;

        }

    }

    *q = '\0';

    *pp = p;

    return 0;

}

