static void add_query_tests(QmpSchema *schema)

{

    SchemaInfoList *tail;

    SchemaInfo *si, *arg_type, *ret_type;

    const char *test_name;



    /* Test the query-like commands */

    for (tail = schema->list; tail; tail = tail->next) {

        si = tail->value;

        if (si->meta_type != SCHEMA_META_TYPE_COMMAND) {

            continue;

        }



        if (query_is_blacklisted(si->name)) {

            continue;

        }



        arg_type = qmp_schema_lookup(schema, si->u.command.arg_type);

        if (object_type_has_mandatory_members(arg_type)) {

            continue;

        }



        ret_type = qmp_schema_lookup(schema, si->u.command.ret_type);

        if (ret_type->meta_type == SCHEMA_META_TYPE_OBJECT

            && !ret_type->u.object.members) {

            continue;

        }



        test_name = g_strdup_printf("qmp/%s", si->name);

        qtest_add_data_func(test_name, si->name, test_query);

    }

}

static void tcg_out_ri(TCGContext *s, int const_arg, TCGArg arg)

{

    if (const_arg) {

        assert(const_arg == 1);

        tcg_out8(s, TCG_CONST);

        tcg_out_i(s, arg);

    } else {

        tcg_out_r(s, arg);

    }

}

static always_inline target_ulong MASK (uint32_t start, uint32_t end)

{

    target_ulong ret;



#if defined(TARGET_PPC64)

    if (likely(start == 0)) {

        ret = (uint64_t)(-1ULL) << (63 - end);

    } else if (likely(end == 63)) {

        ret = (uint64_t)(-1ULL) >> start;

    }

#else

    if (likely(start == 0)) {

        ret = (uint32_t)(-1ULL) << (31  - end);

    } else if (likely(end == 31)) {

        ret = (uint32_t)(-1ULL) >> start;

    }

#endif

    else {

        ret = (((target_ulong)(-1ULL)) >> (start)) ^

            (((target_ulong)(-1ULL) >> (end)) >> 1);

        if (unlikely(start > end))

            return ~ret;

    }



    return ret;

}

void kvm_arch_update_guest_debug(CPUState *env, struct kvm_guest_debug *dbg)

{

    const uint8_t type_code[] = {

        [GDB_BREAKPOINT_HW] = 0x0,

        [GDB_WATCHPOINT_WRITE] = 0x1,

        [GDB_WATCHPOINT_ACCESS] = 0x3

    };

    const uint8_t len_code[] = {

        [1] = 0x0, [2] = 0x1, [4] = 0x3, [8] = 0x2

    };

    int n;



    if (kvm_sw_breakpoints_active(env))

        dbg->control |= KVM_GUESTDBG_ENABLE | KVM_GUESTDBG_USE_SW_BP;



    if (nb_hw_breakpoint > 0) {

        dbg->control |= KVM_GUESTDBG_ENABLE | KVM_GUESTDBG_USE_HW_BP;

        dbg->arch.debugreg[7] = 0x0600;

        for (n = 0; n < nb_hw_breakpoint; n++) {

            dbg->arch.debugreg[n] = hw_breakpoint[n].addr;

            dbg->arch.debugreg[7] |= (2 << (n * 2)) |

                (type_code[hw_breakpoint[n].type] << (16 + n*4)) |

                ((uint32_t)len_code[hw_breakpoint[n].len] << (18 + n*4));

        }

    }

    /* Legal xcr0 for loading */

    env->xcr0 = 1;

}

void ff_hpeldsp_init_x86(HpelDSPContext *c, int flags)

{

    int cpu_flags = av_get_cpu_flags();



    if (INLINE_MMX(cpu_flags))

        hpeldsp_init_mmx(c, flags, cpu_flags);



    if (EXTERNAL_MMXEXT(cpu_flags))

        hpeldsp_init_mmxext(c, flags, cpu_flags);



    if (EXTERNAL_AMD3DNOW(cpu_flags))

        hpeldsp_init_3dnow(c, flags, cpu_flags);



    if (EXTERNAL_SSE2(cpu_flags))

        hpeldsp_init_sse2(c, flags, cpu_flags);

}

static inline void gen_405_mulladd_insn(DisasContext *ctx, int opc2, int opc3,

                                        int ra, int rb, int rt, int Rc)

{

    TCGv t0, t1;



    t0 = tcg_temp_local_new();

    t1 = tcg_temp_local_new();



    switch (opc3 & 0x0D) {

    case 0x05:

        /* macchw    - macchw.    - macchwo   - macchwo.   */

        /* macchws   - macchws.   - macchwso  - macchwso.  */

        /* nmacchw   - nmacchw.   - nmacchwo  - nmacchwo.  */

        /* nmacchws  - nmacchws.  - nmacchwso - nmacchwso. */

        /* mulchw - mulchw. */

        tcg_gen_ext16s_tl(t0, cpu_gpr[ra]);

        tcg_gen_sari_tl(t1, cpu_gpr[rb], 16);

        tcg_gen_ext16s_tl(t1, t1);

        break;

    case 0x04:

        /* macchwu   - macchwu.   - macchwuo  - macchwuo.  */

        /* macchwsu  - macchwsu.  - macchwsuo - macchwsuo. */

        /* mulchwu - mulchwu. */

        tcg_gen_ext16u_tl(t0, cpu_gpr[ra]);

        tcg_gen_shri_tl(t1, cpu_gpr[rb], 16);

        tcg_gen_ext16u_tl(t1, t1);

        break;

    case 0x01:

        /* machhw    - machhw.    - machhwo   - machhwo.   */

        /* machhws   - machhws.   - machhwso  - machhwso.  */

        /* nmachhw   - nmachhw.   - nmachhwo  - nmachhwo.  */

        /* nmachhws  - nmachhws.  - nmachhwso - nmachhwso. */

        /* mulhhw - mulhhw. */

        tcg_gen_sari_tl(t0, cpu_gpr[ra], 16);

        tcg_gen_ext16s_tl(t0, t0);

        tcg_gen_sari_tl(t1, cpu_gpr[rb], 16);

        tcg_gen_ext16s_tl(t1, t1);

        break;

    case 0x00:

        /* machhwu   - machhwu.   - machhwuo  - machhwuo.  */

        /* machhwsu  - machhwsu.  - machhwsuo - machhwsuo. */

        /* mulhhwu - mulhhwu. */

        tcg_gen_shri_tl(t0, cpu_gpr[ra], 16);

        tcg_gen_ext16u_tl(t0, t0);

        tcg_gen_shri_tl(t1, cpu_gpr[rb], 16);

        tcg_gen_ext16u_tl(t1, t1);

        break;

    case 0x0D:

        /* maclhw    - maclhw.    - maclhwo   - maclhwo.   */

        /* maclhws   - maclhws.   - maclhwso  - maclhwso.  */

        /* nmaclhw   - nmaclhw.   - nmaclhwo  - nmaclhwo.  */

        /* nmaclhws  - nmaclhws.  - nmaclhwso - nmaclhwso. */

        /* mullhw - mullhw. */

        tcg_gen_ext16s_tl(t0, cpu_gpr[ra]);

        tcg_gen_ext16s_tl(t1, cpu_gpr[rb]);

        break;

    case 0x0C:

        /* maclhwu   - maclhwu.   - maclhwuo  - maclhwuo.  */

        /* maclhwsu  - maclhwsu.  - maclhwsuo - maclhwsuo. */

        /* mullhwu - mullhwu. */

        tcg_gen_ext16u_tl(t0, cpu_gpr[ra]);

        tcg_gen_ext16u_tl(t1, cpu_gpr[rb]);

        break;

    }

    if (opc2 & 0x04) {

        /* (n)multiply-and-accumulate (0x0C / 0x0E) */

        tcg_gen_mul_tl(t1, t0, t1);

        if (opc2 & 0x02) {

            /* nmultiply-and-accumulate (0x0E) */

            tcg_gen_sub_tl(t0, cpu_gpr[rt], t1);

        } else {

            /* multiply-and-accumulate (0x0C) */

            tcg_gen_add_tl(t0, cpu_gpr[rt], t1);

        }



        if (opc3 & 0x12) {

            /* Check overflow and/or saturate */

            int l1 = gen_new_label();



            if (opc3 & 0x10) {

                /* Start with XER OV disabled, the most likely case */

                tcg_gen_movi_tl(cpu_ov, 0);

            }

            if (opc3 & 0x01) {

                /* Signed */

                tcg_gen_xor_tl(t1, cpu_gpr[rt], t1);

                tcg_gen_brcondi_tl(TCG_COND_GE, t1, 0, l1);

                tcg_gen_xor_tl(t1, cpu_gpr[rt], t0);

                tcg_gen_brcondi_tl(TCG_COND_LT, t1, 0, l1);

                if (opc3 & 0x02) {

                    /* Saturate */

                    tcg_gen_sari_tl(t0, cpu_gpr[rt], 31);

                    tcg_gen_xori_tl(t0, t0, 0x7fffffff);

                }

            } else {

                /* Unsigned */

                tcg_gen_brcond_tl(TCG_COND_GEU, t0, t1, l1);

                if (opc3 & 0x02) {

                    /* Saturate */

                    tcg_gen_movi_tl(t0, UINT32_MAX);

                }

            }

            if (opc3 & 0x10) {

                /* Check overflow */

                tcg_gen_movi_tl(cpu_ov, 1);

                tcg_gen_movi_tl(cpu_so, 1);

            }

            gen_set_label(l1);

            tcg_gen_mov_tl(cpu_gpr[rt], t0);

        }

    } else {

        tcg_gen_mul_tl(cpu_gpr[rt], t0, t1);

    }

    tcg_temp_free(t0);

    tcg_temp_free(t1);

    if (unlikely(Rc) != 0) {

        /* Update Rc0 */

        gen_set_Rc0(ctx, cpu_gpr[rt]);

    }

}

void bdrv_drained_begin(BlockDriverState *bs)

{

    if (!bs->quiesce_counter++) {

        aio_disable_external(bdrv_get_aio_context(bs));

        bdrv_parent_drained_begin(bs);

    }



    bdrv_io_unplugged_begin(bs);

    bdrv_drain_recurse(bs);

    if (qemu_in_coroutine()) {

        bdrv_co_yield_to_drain(bs);

    } else {

        bdrv_drain_poll(bs);

    }

    bdrv_io_unplugged_end(bs);

}

static av_cold int imc_decode_init(AVCodecContext * avctx)

{

    int i, j;

    IMCContext *q = avctx->priv_data;

    double r1, r2;



    q->decoder_reset = 1;



    for(i = 0; i < BANDS; i++)

        q->old_floor[i] = 1.0;



    /* Build mdct window, a simple sine window normalized with sqrt(2) */

    ff_sine_window_init(q->mdct_sine_window, COEFFS);

    for(i = 0; i < COEFFS; i++)

        q->mdct_sine_window[i] *= sqrt(2.0);

    for(i = 0; i < COEFFS/2; i++){

        q->post_cos[i] = (1.0f / 32768) * cos(i / 256.0 * M_PI);

        q->post_sin[i] = (1.0f / 32768) * sin(i / 256.0 * M_PI);



        r1 = sin((i * 4.0 + 1.0) / 1024.0 * M_PI);

        r2 = cos((i * 4.0 + 1.0) / 1024.0 * M_PI);



        if (i & 0x1)

        {

            q->pre_coef1[i] =  (r1 + r2) * sqrt(2.0);

            q->pre_coef2[i] = -(r1 - r2) * sqrt(2.0);

        }

        else

        {

            q->pre_coef1[i] = -(r1 + r2) * sqrt(2.0);

            q->pre_coef2[i] =  (r1 - r2) * sqrt(2.0);

        }



        q->last_fft_im[i] = 0;

    }



    /* Generate a square root table */



    for(i = 0; i < 30; i++) {

        q->sqrt_tab[i] = sqrt(i);

    }



    /* initialize the VLC tables */

    for(i = 0; i < 4 ; i++) {

        for(j = 0; j < 4; j++) {

            huffman_vlc[i][j].table = &vlc_tables[vlc_offsets[i * 4 + j]];

            huffman_vlc[i][j].table_allocated = vlc_offsets[i * 4 + j + 1] - vlc_offsets[i * 4 + j];

            init_vlc(&huffman_vlc[i][j], 9, imc_huffman_sizes[i],

                     imc_huffman_lens[i][j], 1, 1,

                     imc_huffman_bits[i][j], 2, 2, INIT_VLC_USE_NEW_STATIC);

        }

    }

    q->one_div_log2 = 1/log(2);



    ff_fft_init(&q->fft, 7, 1);

    dsputil_init(&q->dsp, avctx);

    avctx->sample_fmt = AV_SAMPLE_FMT_FLT;

    avctx->channel_layout = (avctx->channels==2) ? AV_CH_LAYOUT_STEREO : AV_CH_LAYOUT_MONO;

    return 0;

}

static inline int blah (int32_t i)

{

    if (i > 0x43c07fff)

        return 32767;

    else if (i < 0x43bf8000)

        return -32768;

    else

        return i - 0x43c00000;

}

static void fft_ref_init(int nbits, int inverse)

{

    int i, n = 1 << nbits;



    exptab = av_malloc((n / 2) * sizeof(*exptab));



    for (i = 0; i < (n/2); i++) {

        double alpha = 2 * M_PI * (float)i / (float)n;

        double c1 = cos(alpha), s1 = sin(alpha);

        if (!inverse)

            s1 = -s1;

        exptab[i].re = c1;

        exptab[i].im = s1;

    }

}

void qpci_io_writeb(QPCIDevice *dev, void *data, uint8_t value)

{

    uintptr_t addr = (uintptr_t)data;



    if (addr < QPCI_PIO_LIMIT) {

        dev->bus->pio_writeb(dev->bus, addr, value);

    } else {

        dev->bus->memwrite(dev->bus, addr, &value, sizeof(value));

    }

}

static void deblocking_filter_CTB(HEVCContext *s, int x0, int y0)

{

    uint8_t *src;

    int x, y, x_end, y_end, chroma;

    int c_tc[2], beta[2], tc[2];

    uint8_t no_p[2] = { 0 };

    uint8_t no_q[2] = { 0 };



    int log2_ctb_size = s->sps->log2_ctb_size;

    int ctb_size        = 1 << log2_ctb_size;

    int ctb             = (x0 >> log2_ctb_size) +

                          (y0 >> log2_ctb_size) * s->sps->ctb_width;

    int cur_tc_offset   = s->deblock[ctb].tc_offset;

    int cur_beta_offset = s->deblock[ctb].beta_offset;

    int tc_offset, left_tc_offset, beta_offset, left_beta_offset;

    int pcmf = (s->sps->pcm_enabled_flag &&

                s->sps->pcm.loop_filter_disable_flag) ||

               s->pps->transquant_bypass_enable_flag;



    if (x0) {

        left_tc_offset   = s->deblock[ctb - 1].tc_offset;

        left_beta_offset = s->deblock[ctb - 1].beta_offset;

    }



    x_end = x0 + ctb_size;

    if (x_end > s->sps->width)

        x_end = s->sps->width;

    y_end = y0 + ctb_size;

    if (y_end > s->sps->height)

        y_end = s->sps->height;



    tc_offset   = cur_tc_offset;

    beta_offset = cur_beta_offset;



    // vertical filtering luma

    for (y = y0; y < y_end; y += 8) {

        for (x = x0 ? x0 : 8; x < x_end; x += 8) {

            const int bs0 = s->vertical_bs[(x >> 3) + (y       >> 2) * s->bs_width];

            const int bs1 = s->vertical_bs[(x >> 3) + ((y + 4) >> 2) * s->bs_width];

            if (bs0 || bs1) {

                const int qp0 = (get_qPy(s, x - 1, y)     + get_qPy(s, x, y)     + 1) >> 1;

                const int qp1 = (get_qPy(s, x - 1, y + 4) + get_qPy(s, x, y + 4) + 1) >> 1;



                beta[0] = betatable[av_clip(qp0 + beta_offset, 0, MAX_QP)];

                beta[1] = betatable[av_clip(qp1 + beta_offset, 0, MAX_QP)];

                tc[0]   = bs0 ? TC_CALC(qp0, bs0) : 0;

                tc[1]   = bs1 ? TC_CALC(qp1, bs1) : 0;

                src     = &s->frame->data[LUMA][y * s->frame->linesize[LUMA] + (x << s->sps->pixel_shift)];

                if (pcmf) {

                    no_p[0] = get_pcm(s, x - 1, y);

                    no_p[1] = get_pcm(s, x - 1, y + 4);

                    no_q[0] = get_pcm(s, x, y);

                    no_q[1] = get_pcm(s, x, y + 4);

                    s->hevcdsp.hevc_v_loop_filter_luma_c(src,

                                                         s->frame->linesize[LUMA],

                                                         beta, tc, no_p, no_q);

                } else

                    s->hevcdsp.hevc_v_loop_filter_luma(src,

                                                       s->frame->linesize[LUMA],

                                                       beta, tc, no_p, no_q);

            }

        }

    }



    // vertical filtering chroma

    for (chroma = 1; chroma <= 2; chroma++) {

        for (y = y0; y < y_end; y += 16) {

            for (x = x0 ? x0 : 16; x < x_end; x += 16) {

                const int bs0 = s->vertical_bs[(x >> 3) + (y       >> 2) * s->bs_width];

                const int bs1 = s->vertical_bs[(x >> 3) + ((y + 8) >> 2) * s->bs_width];

                if ((bs0 == 2) || (bs1 == 2)) {

                    const int qp0 = (get_qPy(s, x - 1, y)     + get_qPy(s, x, y)     + 1) >> 1;

                    const int qp1 = (get_qPy(s, x - 1, y + 8) + get_qPy(s, x, y + 8) + 1) >> 1;



                    c_tc[0] = (bs0 == 2) ? chroma_tc(s, qp0, chroma, tc_offset) : 0;

                    c_tc[1] = (bs1 == 2) ? chroma_tc(s, qp1, chroma, tc_offset) : 0;

                    src     = &s->frame->data[chroma][y / 2 * s->frame->linesize[chroma] + ((x / 2) << s->sps->pixel_shift)];

                    if (pcmf) {

                        no_p[0] = get_pcm(s, x - 1, y);

                        no_p[1] = get_pcm(s, x - 1, y + 8);

                        no_q[0] = get_pcm(s, x, y);

                        no_q[1] = get_pcm(s, x, y + 8);

                        s->hevcdsp.hevc_v_loop_filter_chroma_c(src,

                                                               s->frame->linesize[chroma],

                                                               c_tc, no_p, no_q);

                    } else

                        s->hevcdsp.hevc_v_loop_filter_chroma(src,

                                                             s->frame->linesize[chroma],

                                                             c_tc, no_p, no_q);

                }

            }

        }

    }



    // horizontal filtering luma

    if (x_end != s->sps->width)

        x_end -= 8;

    for (y = y0 ? y0 : 8; y < y_end; y += 8) {

        for (x = x0 ? x0 - 8 : 0; x < x_end; x += 8) {

            const int bs0 = s->horizontal_bs[(x +     y * s->bs_width) >> 2];

            const int bs1 = s->horizontal_bs[(x + 4 + y * s->bs_width) >> 2];

            if (bs0 || bs1) {

                const int qp0 = (get_qPy(s, x, y - 1)     + get_qPy(s, x, y)     + 1) >> 1;

                const int qp1 = (get_qPy(s, x + 4, y - 1) + get_qPy(s, x + 4, y) + 1) >> 1;



                tc_offset   = x >= x0 ? cur_tc_offset : left_tc_offset;

                beta_offset = x >= x0 ? cur_beta_offset : left_beta_offset;



                beta[0] = betatable[av_clip(qp0 + beta_offset, 0, MAX_QP)];

                beta[1] = betatable[av_clip(qp1 + beta_offset, 0, MAX_QP)];

                tc[0]   = bs0 ? TC_CALC(qp0, bs0) : 0;

                tc[1]   = bs1 ? TC_CALC(qp1, bs1) : 0;

                src     = &s->frame->data[LUMA][y * s->frame->linesize[LUMA] + (x << s->sps->pixel_shift)];

                if (pcmf) {

                    no_p[0] = get_pcm(s, x, y - 1);

                    no_p[1] = get_pcm(s, x + 4, y - 1);

                    no_q[0] = get_pcm(s, x, y);

                    no_q[1] = get_pcm(s, x + 4, y);

                    s->hevcdsp.hevc_h_loop_filter_luma_c(src,

                                                         s->frame->linesize[LUMA],

                                                         beta, tc, no_p, no_q);

                } else

                    s->hevcdsp.hevc_h_loop_filter_luma(src,

                                                       s->frame->linesize[LUMA],

                                                       beta, tc, no_p, no_q);

            }

        }

    }



    // horizontal filtering chroma

    for (chroma = 1; chroma <= 2; chroma++) {

        for (y = y0 ? y0 : 16; y < y_end; y += 16) {

            for (x = x0 - 8; x < x_end; x += 16) {

                int bs0, bs1;

                // to make sure no memory access over boundary when x = -8

                // TODO: simplify with row based deblocking

                if (x < 0) {

                    bs0 = 0;

                    bs1 = s->horizontal_bs[(x + 8 + y * s->bs_width) >> 2];

                } else if (x >= x_end - 8) {

                    bs0 = s->horizontal_bs[(x +     y * s->bs_width) >> 2];

                    bs1 = 0;

                } else {

                    bs0 = s->horizontal_bs[(x + y     * s->bs_width) >> 2];

                    bs1 = s->horizontal_bs[(x + 8 + y * s->bs_width) >> 2];

                }



                if ((bs0 == 2) || (bs1 == 2)) {

                    const int qp0 = bs0 == 2 ? (get_qPy(s, x,     y - 1) + get_qPy(s, x,     y) + 1) >> 1 : 0;

                    const int qp1 = bs1 == 2 ? (get_qPy(s, x + 8, y - 1) + get_qPy(s, x + 8, y) + 1) >> 1 : 0;



                    tc_offset = x >= x0 ? cur_tc_offset : left_tc_offset;

                    c_tc[0]   = bs0 == 2 ? chroma_tc(s, qp0, chroma, tc_offset)     : 0;

                    c_tc[1]   = bs1 == 2 ? chroma_tc(s, qp1, chroma, cur_tc_offset) : 0;

                    src       = &s->frame->data[chroma][y / 2 * s->frame->linesize[chroma] + ((x / 2) << s->sps->pixel_shift)];

                    if (pcmf) {

                        no_p[0] = get_pcm(s, x, y - 1);

                        no_p[1] = get_pcm(s, x + 8, y - 1);

                        no_q[0] = get_pcm(s, x, y);

                        no_q[1] = get_pcm(s, x + 8, y);

                        s->hevcdsp.hevc_h_loop_filter_chroma_c(src,

                                                               s->frame->linesize[chroma],

                                                               c_tc, no_p, no_q);

                    } else

                        s->hevcdsp.hevc_h_loop_filter_chroma(src,

                                                             s->frame->linesize[chroma],

                                                             c_tc, no_p, no_q);

                }

            }

        }

    }

}

int64 float64_to_int64_round_to_zero( float64 a STATUS_PARAM )

{

    flag aSign;

    int16 aExp, shiftCount;

    bits64 aSig;

    int64 z;



    aSig = extractFloat64Frac( a );

    aExp = extractFloat64Exp( a );

    aSign = extractFloat64Sign( a );

    if ( aExp ) aSig |= LIT64( 0x0010000000000000 );

    shiftCount = aExp - 0x433;

    if ( 0 <= shiftCount ) {

        if ( 0x43E <= aExp ) {

            if ( a != LIT64( 0xC3E0000000000000 ) ) {

                float_raise( float_flag_invalid STATUS_VAR);

                if (    ! aSign

                     || (    ( aExp == 0x7FF )

                          && ( aSig != LIT64( 0x0010000000000000 ) ) )

                   ) {

                    return LIT64( 0x7FFFFFFFFFFFFFFF );

                }

            }

            return (sbits64) LIT64( 0x8000000000000000 );

        }

        z = aSig<<shiftCount;

    }

    else {

        if ( aExp < 0x3FE ) {

            if ( aExp | aSig ) STATUS(float_exception_flags) |= float_flag_inexact;

            return 0;

        }

        z = aSig>>( - shiftCount );

        if ( (bits64) ( aSig<<( shiftCount & 63 ) ) ) {

            STATUS(float_exception_flags) |= float_flag_inexact;

        }

    }

    if ( aSign ) z = - z;

    return z;



}

static void dec_sru(DisasContext *dc)

{

    if (dc->format == OP_FMT_RI) {

        LOG_DIS("srui r%d, r%d, %d\n", dc->r1, dc->r0, dc->imm5);

    } else {

        LOG_DIS("sru r%d, r%d, r%d\n", dc->r2, dc->r0, dc->r1);

    }



    if (!(dc->env->features & LM32_FEATURE_SHIFT)) {

        if (dc->format == OP_FMT_RI) {

            /* TODO: check r1 == 1 during runtime */

        } else {

            if (dc->imm5 != 1) {

                cpu_abort(dc->env, "hardware shifter is not available\n");

            }

        }

    }



    if (dc->format == OP_FMT_RI) {

        tcg_gen_shri_tl(cpu_R[dc->r1], cpu_R[dc->r0], dc->imm5);

    } else {

        TCGv t0 = tcg_temp_new();

        tcg_gen_andi_tl(t0, cpu_R[dc->r1], 0x1f);

        tcg_gen_shr_tl(cpu_R[dc->r2], cpu_R[dc->r0], t0);

        tcg_temp_free(t0);

    }

}

static void vnc_display_close(VncDisplay *vs)

{

    if (!vs)

        return;

    g_free(vs->display);

    vs->display = NULL;

    if (vs->lsock != -1) {

        qemu_set_fd_handler2(vs->lsock, NULL, NULL, NULL, NULL);

        close(vs->lsock);

        vs->lsock = -1;

    }

#ifdef CONFIG_VNC_WS

    g_free(vs->ws_display);

    vs->ws_display = NULL;

    if (vs->lwebsock != -1) {

        qemu_set_fd_handler2(vs->lwebsock, NULL, NULL, NULL, NULL);

        close(vs->lwebsock);

        vs->lwebsock = -1;

    }

#endif /* CONFIG_VNC_WS */

    vs->auth = VNC_AUTH_INVALID;

#ifdef CONFIG_VNC_TLS

    vs->subauth = VNC_AUTH_INVALID;

    vs->tls.x509verify = 0;

#endif

}

static void sysbus_device_class_init(ObjectClass *klass, void *data)

{

    DeviceClass *k = DEVICE_CLASS(klass);

    k->init = sysbus_device_init;

    k->bus_type = TYPE_SYSTEM_BUS;












}

static int fourxm_read_packet(AVFormatContext *s,

                              AVPacket *pkt)

{

    FourxmDemuxContext *fourxm = s->priv_data;

    ByteIOContext *pb = s->pb;

    unsigned int fourcc_tag;

    unsigned int size, out_size;

    int ret = 0;

    unsigned int track_number;

    int packet_read = 0;

    unsigned char header[8];

    int audio_frame_count;



    while (!packet_read) {



        if ((ret = get_buffer(s->pb, header, 8)) < 0)

            return ret;

        fourcc_tag = AV_RL32(&header[0]);

        size = AV_RL32(&header[4]);

        if (url_feof(pb))

            return AVERROR(EIO);

        switch (fourcc_tag) {



        case LIST_TAG:

            /* this is a good time to bump the video pts */

            fourxm->video_pts ++;



            /* skip the LIST-* tag and move on to the next fourcc */

            get_le32(pb);

            break;



        case ifrm_TAG:

        case pfrm_TAG:

        case cfrm_TAG:

        case ifr2_TAG:

        case pfr2_TAG:

        case cfr2_TAG:

            /* allocate 8 more bytes than 'size' to account for fourcc

             * and size */

            if (size + 8 < size || av_new_packet(pkt, size + 8))

                return AVERROR(EIO);

            pkt->stream_index = fourxm->video_stream_index;

            pkt->pts = fourxm->video_pts;

            pkt->pos = url_ftell(s->pb);

            memcpy(pkt->data, header, 8);

            ret = get_buffer(s->pb, &pkt->data[8], size);



            if (ret < 0){

                av_free_packet(pkt);

            }else

                packet_read = 1;

            break;



        case snd__TAG:

            track_number = get_le32(pb);

            out_size= get_le32(pb);

            size-=8;



            if (track_number < fourxm->track_count) {

                ret= av_get_packet(s->pb, pkt, size);

                if(ret<0)

                    return AVERROR(EIO);

                pkt->stream_index =

                    fourxm->tracks[track_number].stream_index;

                pkt->pts = fourxm->tracks[track_number].audio_pts;

                packet_read = 1;



                /* pts accounting */

                audio_frame_count = size;

                if (fourxm->tracks[track_number].adpcm)

                    audio_frame_count -=

                        2 * (fourxm->tracks[track_number].channels);

                audio_frame_count /=

                      fourxm->tracks[track_number].channels;

                if (fourxm->tracks[track_number].adpcm){

                    audio_frame_count *= 2;

                }else

                    audio_frame_count /=

                    (fourxm->tracks[track_number].bits / 8);

                fourxm->tracks[track_number].audio_pts += audio_frame_count;



            } else {

                url_fseek(pb, size, SEEK_CUR);

            }

            break;



        default:

            url_fseek(pb, size, SEEK_CUR);

            break;

        }

    }

    return ret;

}

