sPAPRTCETable *spapr_tce_new_table(DeviceState *owner, uint32_t liobn,

                                   uint64_t bus_offset,

                                   uint32_t page_shift,

                                   uint32_t nb_table,

                                   bool vfio_accel)

{

    sPAPRTCETable *tcet;

    char tmp[64];



    if (spapr_tce_find_by_liobn(liobn)) {

        fprintf(stderr, "Attempted to create TCE table with duplicate"

                " LIOBN 0x%x\n", liobn);

        return NULL;

    }



    if (!nb_table) {

        return NULL;

    }



    tcet = SPAPR_TCE_TABLE(object_new(TYPE_SPAPR_TCE_TABLE));

    tcet->liobn = liobn;

    tcet->bus_offset = bus_offset;

    tcet->page_shift = page_shift;

    tcet->nb_table = nb_table;

    tcet->vfio_accel = vfio_accel;



    snprintf(tmp, sizeof(tmp), "tce-table-%x", liobn);

    object_property_add_child(OBJECT(owner), tmp, OBJECT(tcet), NULL);



    object_property_set_bool(OBJECT(tcet), true, "realized", NULL);



    return tcet;

}

static int virtio_blk_init_pci(PCIDevice *pci_dev)

{

    VirtIOPCIProxy *proxy = DO_UPCAST(VirtIOPCIProxy, pci_dev, pci_dev);

    VirtIODevice *vdev;



    if (proxy->class_code != PCI_CLASS_STORAGE_SCSI &&

        proxy->class_code != PCI_CLASS_STORAGE_OTHER)

        proxy->class_code = PCI_CLASS_STORAGE_SCSI;



    if (!proxy->block.bs) {

        error_report("virtio-blk-pci: drive property not set");



    vdev = virtio_blk_init(&pci_dev->qdev, &proxy->block);




    vdev->nvectors = proxy->nvectors;

    virtio_init_pci(proxy, vdev,

                    PCI_VENDOR_ID_REDHAT_QUMRANET,

                    PCI_DEVICE_ID_VIRTIO_BLOCK,

                    proxy->class_code, 0x00);

    /* make the actual value visible */

    proxy->nvectors = vdev->nvectors;

    return 0;

static void test_native_list(TestOutputVisitorData *data,

                             const void *unused,

                             UserDefNativeListUnionKind kind)

{

    UserDefNativeListUnion *cvalue = g_new0(UserDefNativeListUnion, 1);

    QObject *obj;



    cvalue->type = kind;

    init_native_list(cvalue);



    visit_type_UserDefNativeListUnion(data->ov, NULL, &cvalue, &error_abort);



    obj = visitor_get(data);

    check_native_list(obj, cvalue->type);

    qapi_free_UserDefNativeListUnion(cvalue);

}

static int mov_write_stbl_tag(AVFormatContext *s, AVIOContext *pb, MOVMuxContext *mov, MOVTrack *track)

{

    int64_t pos = avio_tell(pb);

    int ret;



    avio_wb32(pb, 0); /* size */

    ffio_wfourcc(pb, "stbl");

    mov_write_stsd_tag(s, pb, mov, track);

    mov_write_stts_tag(pb, track);

    if ((track->par->codec_type == AVMEDIA_TYPE_VIDEO ||

         track->par->codec_tag == MKTAG('r','t','p',' ')) &&

        track->has_keyframes && track->has_keyframes < track->entry)

        mov_write_stss_tag(pb, track, MOV_SYNC_SAMPLE);

    if (track->mode == MODE_MOV && track->flags & MOV_TRACK_STPS)

        mov_write_stss_tag(pb, track, MOV_PARTIAL_SYNC_SAMPLE);

    if (track->par->codec_type == AVMEDIA_TYPE_VIDEO &&

        track->flags & MOV_TRACK_CTTS && track->entry) {



        if ((ret = mov_write_ctts_tag(pb, track)) < 0)

            return ret;

    }

    mov_write_stsc_tag(pb, track);

    mov_write_stsz_tag(pb, track);

    mov_write_stco_tag(pb, track);

    if (mov->encryption_scheme == MOV_ENC_CENC_AES_CTR) {

        ff_mov_cenc_write_stbl_atoms(&track->cenc, pb);

    }

    if (track->par->codec_id == AV_CODEC_ID_OPUS) {

        mov_preroll_write_stbl_atoms(pb, track);

    }

    return update_size(pb, pos);

}

static int aac_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                            const AVFrame *frame, int *got_packet_ptr)

{

    AACEncContext *s = avctx->priv_data;

    float **samples = s->planar_samples, *samples2, *la, *overlap;

    ChannelElement *cpe;

    SingleChannelElement *sce;

    IndividualChannelStream *ics;

    int i, its, ch, w, chans, tag, start_ch, ret, frame_bits;

    int target_bits, rate_bits, too_many_bits, too_few_bits;

    int ms_mode = 0, is_mode = 0, tns_mode = 0, pred_mode = 0;

    int chan_el_counter[4];

    FFPsyWindowInfo windows[AAC_MAX_CHANNELS];



    if (s->last_frame == 2)

        return 0;



    /* add current frame to queue */

    if (frame) {

        if ((ret = ff_af_queue_add(&s->afq, frame)) < 0)

            return ret;

    }



    copy_input_samples(s, frame);

    if (s->psypp)

        ff_psy_preprocess(s->psypp, s->planar_samples, s->channels);



    if (!avctx->frame_number)

        return 0;



    start_ch = 0;

    for (i = 0; i < s->chan_map[0]; i++) {

        FFPsyWindowInfo* wi = windows + start_ch;

        tag      = s->chan_map[i+1];

        chans    = tag == TYPE_CPE ? 2 : 1;

        cpe      = &s->cpe[i];

        for (ch = 0; ch < chans; ch++) {

            float clip_avoidance_factor;

            sce = &cpe->ch[ch];

            ics = &sce->ics;

            s->cur_channel = start_ch + ch;

            overlap  = &samples[s->cur_channel][0];

            samples2 = overlap + 1024;

            la       = samples2 + (448+64);

            if (!frame)

                la = NULL;

            if (tag == TYPE_LFE) {

                wi[ch].window_type[0] = ONLY_LONG_SEQUENCE;

                wi[ch].window_shape   = 0;

                wi[ch].num_windows    = 1;

                wi[ch].grouping[0]    = 1;



                /* Only the lowest 12 coefficients are used in a LFE channel.

                 * The expression below results in only the bottom 8 coefficients

                 * being used for 11.025kHz to 16kHz sample rates.

                 */

                ics->num_swb = s->samplerate_index >= 8 ? 1 : 3;

            } else {

                wi[ch] = s->psy.model->window(&s->psy, samples2, la, s->cur_channel,

                                              ics->window_sequence[0]);

            }

            ics->window_sequence[1] = ics->window_sequence[0];

            ics->window_sequence[0] = wi[ch].window_type[0];

            ics->use_kb_window[1]   = ics->use_kb_window[0];

            ics->use_kb_window[0]   = wi[ch].window_shape;

            ics->num_windows        = wi[ch].num_windows;

            ics->swb_sizes          = s->psy.bands    [ics->num_windows == 8];

            ics->num_swb            = tag == TYPE_LFE ? ics->num_swb : s->psy.num_bands[ics->num_windows == 8];

            ics->max_sfb            = FFMIN(ics->max_sfb, ics->num_swb);

            ics->swb_offset         = wi[ch].window_type[0] == EIGHT_SHORT_SEQUENCE ?

                                        ff_swb_offset_128 [s->samplerate_index]:

                                        ff_swb_offset_1024[s->samplerate_index];

            ics->tns_max_bands      = wi[ch].window_type[0] == EIGHT_SHORT_SEQUENCE ?

                                        ff_tns_max_bands_128 [s->samplerate_index]:

                                        ff_tns_max_bands_1024[s->samplerate_index];

            clip_avoidance_factor = 0.0f;

            for (w = 0; w < ics->num_windows; w++)

                ics->group_len[w] = wi[ch].grouping[w];

            for (w = 0; w < ics->num_windows; w++) {

                if (wi[ch].clipping[w] > CLIP_AVOIDANCE_FACTOR) {

                    ics->window_clipping[w] = 1;

                    clip_avoidance_factor = FFMAX(clip_avoidance_factor, wi[ch].clipping[w]);

                } else {

                    ics->window_clipping[w] = 0;

                }

            }

            if (clip_avoidance_factor > CLIP_AVOIDANCE_FACTOR) {

                ics->clip_avoidance_factor = CLIP_AVOIDANCE_FACTOR / clip_avoidance_factor;

            } else {

                ics->clip_avoidance_factor = 1.0f;

            }



            apply_window_and_mdct(s, sce, overlap);



            if (s->options.ltp && s->coder->update_ltp) {

                s->coder->update_ltp(s, sce);

                apply_window[sce->ics.window_sequence[0]](s->fdsp, sce, &sce->ltp_state[0]);

                s->mdct1024.mdct_calc(&s->mdct1024, sce->lcoeffs, sce->ret_buf);

            }



            if (isnan(cpe->ch->coeffs[0])) {

                av_log(avctx, AV_LOG_ERROR, "Input contains NaN\n");

                return AVERROR(EINVAL);

            }

            avoid_clipping(s, sce);

        }

        start_ch += chans;

    }

    if ((ret = ff_alloc_packet2(avctx, avpkt, 8192 * s->channels, 0)) < 0)

        return ret;

    frame_bits = its = 0;

    do {

        init_put_bits(&s->pb, avpkt->data, avpkt->size);



        if ((avctx->frame_number & 0xFF)==1 && !(avctx->flags & AV_CODEC_FLAG_BITEXACT))

            put_bitstream_info(s, LIBAVCODEC_IDENT);

        start_ch = 0;

        target_bits = 0;

        memset(chan_el_counter, 0, sizeof(chan_el_counter));

        for (i = 0; i < s->chan_map[0]; i++) {

            FFPsyWindowInfo* wi = windows + start_ch;

            const float *coeffs[2];

            tag      = s->chan_map[i+1];

            chans    = tag == TYPE_CPE ? 2 : 1;

            cpe      = &s->cpe[i];

            cpe->common_window = 0;

            memset(cpe->is_mask, 0, sizeof(cpe->is_mask));

            memset(cpe->ms_mask, 0, sizeof(cpe->ms_mask));

            put_bits(&s->pb, 3, tag);

            put_bits(&s->pb, 4, chan_el_counter[tag]++);

            for (ch = 0; ch < chans; ch++) {

                sce = &cpe->ch[ch];

                coeffs[ch] = sce->coeffs;

                sce->ics.predictor_present = 0;

                sce->ics.ltp.present = 0;

                memset(sce->ics.ltp.used, 0, sizeof(sce->ics.ltp.used));

                memset(sce->ics.prediction_used, 0, sizeof(sce->ics.prediction_used));

                memset(&sce->tns, 0, sizeof(TemporalNoiseShaping));

                for (w = 0; w < 128; w++)

                    if (sce->band_type[w] > RESERVED_BT)

                        sce->band_type[w] = 0;

            }

            s->psy.bitres.alloc = -1;

            s->psy.bitres.bits = s->last_frame_pb_count / s->channels;

            s->psy.model->analyze(&s->psy, start_ch, coeffs, wi);

            if (s->psy.bitres.alloc > 0) {

                /* Lambda unused here on purpose, we need to take psy's unscaled allocation */

                target_bits += s->psy.bitres.alloc

                    * (s->lambda / (avctx->global_quality ? avctx->global_quality : 120));

                s->psy.bitres.alloc /= chans;

            }

            s->cur_type = tag;

            for (ch = 0; ch < chans; ch++) {

                s->cur_channel = start_ch + ch;

                if (s->options.pns && s->coder->mark_pns)

                    s->coder->mark_pns(s, avctx, &cpe->ch[ch]);

                s->coder->search_for_quantizers(avctx, s, &cpe->ch[ch], s->lambda);

            }

            if (chans > 1

                && wi[0].window_type[0] == wi[1].window_type[0]

                && wi[0].window_shape   == wi[1].window_shape) {



                cpe->common_window = 1;

                for (w = 0; w < wi[0].num_windows; w++) {

                    if (wi[0].grouping[w] != wi[1].grouping[w]) {

                        cpe->common_window = 0;

                        break;

                    }

                }

            }

            for (ch = 0; ch < chans; ch++) { /* TNS and PNS */

                sce = &cpe->ch[ch];

                s->cur_channel = start_ch + ch;

                if (s->options.tns && s->coder->search_for_tns)

                    s->coder->search_for_tns(s, sce);

                if (s->options.tns && s->coder->apply_tns_filt)

                    s->coder->apply_tns_filt(s, sce);

                if (sce->tns.present)

                    tns_mode = 1;

                if (s->options.pns && s->coder->search_for_pns)

                    s->coder->search_for_pns(s, avctx, sce);

            }

            s->cur_channel = start_ch;

            if (s->options.intensity_stereo) { /* Intensity Stereo */

                if (s->coder->search_for_is)

                    s->coder->search_for_is(s, avctx, cpe);

                if (cpe->is_mode) is_mode = 1;

                apply_intensity_stereo(cpe);

            }

            if (s->options.pred) { /* Prediction */

                for (ch = 0; ch < chans; ch++) {

                    sce = &cpe->ch[ch];

                    s->cur_channel = start_ch + ch;

                    if (s->options.pred && s->coder->search_for_pred)

                        s->coder->search_for_pred(s, sce);

                    if (cpe->ch[ch].ics.predictor_present) pred_mode = 1;

                }

                if (s->coder->adjust_common_pred)

                    s->coder->adjust_common_pred(s, cpe);

                for (ch = 0; ch < chans; ch++) {

                    sce = &cpe->ch[ch];

                    s->cur_channel = start_ch + ch;

                    if (s->options.pred && s->coder->apply_main_pred)

                        s->coder->apply_main_pred(s, sce);

                }

                s->cur_channel = start_ch;

            }

            if (s->options.mid_side) { /* Mid/Side stereo */

                if (s->options.mid_side == -1 && s->coder->search_for_ms)

                    s->coder->search_for_ms(s, cpe);

                else if (cpe->common_window)

                    memset(cpe->ms_mask, 1, sizeof(cpe->ms_mask));

                apply_mid_side_stereo(cpe);

            }

            adjust_frame_information(cpe, chans);

            if (s->options.ltp) { /* LTP */

                for (ch = 0; ch < chans; ch++) {

                    sce = &cpe->ch[ch];

                    s->cur_channel = start_ch + ch;

                    if (s->coder->search_for_ltp)

                        s->coder->search_for_ltp(s, sce, cpe->common_window);

                    if (sce->ics.ltp.present) pred_mode = 1;

                }

                s->cur_channel = start_ch;

                if (s->coder->adjust_common_ltp)

                    s->coder->adjust_common_ltp(s, cpe);

            }

            if (chans == 2) {

                put_bits(&s->pb, 1, cpe->common_window);

                if (cpe->common_window) {

                    put_ics_info(s, &cpe->ch[0].ics);

                    if (s->coder->encode_main_pred)

                        s->coder->encode_main_pred(s, &cpe->ch[0]);

                    if (s->coder->encode_ltp_info)

                        s->coder->encode_ltp_info(s, &cpe->ch[0], 1);

                    encode_ms_info(&s->pb, cpe);

                    if (cpe->ms_mode) ms_mode = 1;

                }

            }

            for (ch = 0; ch < chans; ch++) {

                s->cur_channel = start_ch + ch;

                encode_individual_channel(avctx, s, &cpe->ch[ch], cpe->common_window);

            }

            start_ch += chans;

        }



        if (avctx->flags & CODEC_FLAG_QSCALE) {

            /* When using a constant Q-scale, don't mess with lambda */

            break;

        }



        /* rate control stuff

         * allow between the nominal bitrate, and what psy's bit reservoir says to target

         * but drift towards the nominal bitrate always

         */

        frame_bits = put_bits_count(&s->pb);

        rate_bits = avctx->bit_rate * 1024 / avctx->sample_rate;

        rate_bits = FFMIN(rate_bits, 6144 * s->channels - 3);

        too_many_bits = FFMAX(target_bits, rate_bits);

        too_many_bits = FFMIN(too_many_bits, 6144 * s->channels - 3);

        too_few_bits = FFMIN(FFMAX(rate_bits - rate_bits/4, target_bits), too_many_bits);



        /* When using ABR, be strict (but only for increasing) */

        too_few_bits = too_few_bits - too_few_bits/8;

        too_many_bits = too_many_bits + too_many_bits/2;



        if (   its == 0 /* for steady-state Q-scale tracking */

            || (its < 5 && (frame_bits < too_few_bits || frame_bits > too_many_bits))

            || frame_bits >= 6144 * s->channels - 3  )

        {

            float ratio = ((float)rate_bits) / frame_bits;



            if (frame_bits >= too_few_bits && frame_bits <= too_many_bits) {

                /*

                 * This path is for steady-state Q-scale tracking

                 * When frame bits fall within the stable range, we still need to adjust

                 * lambda to maintain it like so in a stable fashion (large jumps in lambda

                 * create artifacts and should be avoided), but slowly

                 */

                ratio = sqrtf(sqrtf(ratio));

                ratio = av_clipf(ratio, 0.9f, 1.1f);

            } else {

                /* Not so fast though */

                ratio = sqrtf(ratio);

            }

            s->lambda = FFMIN(s->lambda * ratio, 65536.f);



            /* Keep iterating if we must reduce and lambda is in the sky */

            if (ratio > 0.9f && ratio < 1.1f) {

                break;

            } else {

                if (is_mode || ms_mode || tns_mode || pred_mode) {

                    for (i = 0; i < s->chan_map[0]; i++) {

                        // Must restore coeffs

                        chans = tag == TYPE_CPE ? 2 : 1;

                        cpe = &s->cpe[i];

                        for (ch = 0; ch < chans; ch++)

                            memcpy(cpe->ch[ch].coeffs, cpe->ch[ch].pcoeffs, sizeof(cpe->ch[ch].coeffs));

                    }

                }

                its++;

            }

        } else {

            break;

        }

    } while (1);



    if (s->options.ltp && s->coder->ltp_insert_new_frame)

        s->coder->ltp_insert_new_frame(s);



    put_bits(&s->pb, 3, TYPE_END);

    flush_put_bits(&s->pb);



    s->last_frame_pb_count = put_bits_count(&s->pb);



    s->lambda_sum += s->lambda;

    s->lambda_count++;



    if (!frame)

        s->last_frame++;



    ff_af_queue_remove(&s->afq, avctx->frame_size, &avpkt->pts,

                       &avpkt->duration);



    avpkt->size = put_bits_count(&s->pb) >> 3;

    *got_packet_ptr = 1;

    return 0;

}

static int read_rle_sgi(uint8_t *out_buf, SgiState *s)

{

    uint8_t *dest_row;

    unsigned int len = s->height * s->depth * 4;

    GetByteContext g_table = s->g;

    unsigned int y, z;

    unsigned int start_offset;

    int linesize, ret;



    /* size of  RLE offset and length tables */

    if (len * 2 > bytestream2_get_bytes_left(&s->g)) {

        return AVERROR_INVALIDDATA;

    }



    for (z = 0; z < s->depth; z++) {

        dest_row = out_buf;

        for (y = 0; y < s->height; y++) {

            linesize = s->width * s->depth * s->bytes_per_channel;

            dest_row -= s->linesize;

            start_offset = bytestream2_get_be32(&g_table);

            bytestream2_seek(&s->g, start_offset, SEEK_SET);

            if (s->bytes_per_channel == 1)

                ret = expand_rle_row8(s, dest_row + z, linesize, s->depth);

            else

                ret = expand_rle_row16(s, (uint16_t *)dest_row + z, linesize, s->depth);

            if (ret != s->width)

                return AVERROR_INVALIDDATA;

        }

    }

    return 0;

}

static void rtas_ibm_configure_connector(PowerPCCPU *cpu,

                                         sPAPRMachineState *spapr,

                                         uint32_t token, uint32_t nargs,

                                         target_ulong args, uint32_t nret,

                                         target_ulong rets)

{

    uint64_t wa_addr;

    uint64_t wa_offset;

    uint32_t drc_index;

    sPAPRDRConnector *drc;

    sPAPRDRConnectorClass *drck;

    sPAPRConfigureConnectorState *ccs;

    sPAPRDRCCResponse resp = SPAPR_DR_CC_RESPONSE_CONTINUE;

    int rc;

    const void *fdt;



    if (nargs != 2 || nret != 1) {

        rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

        return;




    wa_addr = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 0);



    drc_index = rtas_ld(wa_addr, 0);

    drc = spapr_dr_connector_by_index(drc_index);

    if (!drc) {

        DPRINTF("rtas_ibm_configure_connector: invalid DRC index: %xh\n",


        rc = RTAS_OUT_PARAM_ERROR;





    drck = SPAPR_DR_CONNECTOR_GET_CLASS(drc);

    fdt = drck->get_fdt(drc, NULL);









    ccs = spapr_ccs_find(spapr, drc_index);

    if (!ccs) {

        ccs = g_new0(sPAPRConfigureConnectorState, 1);

        (void)drck->get_fdt(drc, &ccs->fdt_offset);

        ccs->drc_index = drc_index;

        spapr_ccs_add(spapr, ccs);




    do {

        uint32_t tag;

        const char *name;

        const struct fdt_property *prop;

        int fdt_offset_next, prop_len;



        tag = fdt_next_tag(fdt, ccs->fdt_offset, &fdt_offset_next);



        switch (tag) {

        case FDT_BEGIN_NODE:

            ccs->fdt_depth++;

            name = fdt_get_name(fdt, ccs->fdt_offset, NULL);



            /* provide the name of the next OF node */

            wa_offset = CC_VAL_DATA_OFFSET;

            rtas_st(wa_addr, CC_IDX_NODE_NAME_OFFSET, wa_offset);

            rtas_st_buffer_direct(wa_addr + wa_offset, CC_WA_LEN - wa_offset,

                                  (uint8_t *)name, strlen(name) + 1);

            resp = SPAPR_DR_CC_RESPONSE_NEXT_CHILD;

            break;

        case FDT_END_NODE:

            ccs->fdt_depth--;

            if (ccs->fdt_depth == 0) {

                /* done sending the device tree, don't need to track

                 * the state anymore

                 */

                drck->set_configured(drc);

                spapr_ccs_remove(spapr, ccs);

                ccs = NULL;

                resp = SPAPR_DR_CC_RESPONSE_SUCCESS;

            } else {

                resp = SPAPR_DR_CC_RESPONSE_PREV_PARENT;


            break;

        case FDT_PROP:

            prop = fdt_get_property_by_offset(fdt, ccs->fdt_offset,

                                              &prop_len);

            name = fdt_string(fdt, fdt32_to_cpu(prop->nameoff));



            /* provide the name of the next OF property */

            wa_offset = CC_VAL_DATA_OFFSET;

            rtas_st(wa_addr, CC_IDX_PROP_NAME_OFFSET, wa_offset);

            rtas_st_buffer_direct(wa_addr + wa_offset, CC_WA_LEN - wa_offset,

                                  (uint8_t *)name, strlen(name) + 1);



            /* provide the length and value of the OF property. data gets

             * placed immediately after NULL terminator of the OF property's

             * name string

             */

            wa_offset += strlen(name) + 1,

            rtas_st(wa_addr, CC_IDX_PROP_LEN, prop_len);

            rtas_st(wa_addr, CC_IDX_PROP_DATA_OFFSET, wa_offset);

            rtas_st_buffer_direct(wa_addr + wa_offset, CC_WA_LEN - wa_offset,

                                  (uint8_t *)((struct fdt_property *)prop)->data,

                                  prop_len);

            resp = SPAPR_DR_CC_RESPONSE_NEXT_PROPERTY;

            break;

        case FDT_END:

            resp = SPAPR_DR_CC_RESPONSE_ERROR;

        default:

            /* keep seeking for an actionable tag */

            break;


        if (ccs) {

            ccs->fdt_offset = fdt_offset_next;


    } while (resp == SPAPR_DR_CC_RESPONSE_CONTINUE);



    rc = resp;

out:

    rtas_st(rets, 0, rc);

static inline void ls_decode_line(JLSState *state, MJpegDecodeContext *s,

                                  void *last, void *dst, int last2, int w,

                                  int stride, int comp, int bits)

{

    int i, x = 0;

    int Ra, Rb, Rc, Rd;

    int D0, D1, D2;



    while (x < w) {

        int err, pred;



        /* compute gradients */

        Ra = x ? R(dst, x - stride) : R(last, x);

        Rb = R(last, x);

        Rc = x ? R(last, x - stride) : last2;

        Rd = (x >= w - stride) ? R(last, x) : R(last, x + stride);

        D0 = Rd - Rb;

        D1 = Rb - Rc;

        D2 = Rc - Ra;

        /* run mode */

        if ((FFABS(D0) <= state->near) &&

            (FFABS(D1) <= state->near) &&

            (FFABS(D2) <= state->near)) {

            int r;

            int RItype;



            /* decode full runs while available */

            while (get_bits1(&s->gb)) {

                int r;

                r = 1 << ff_log2_run[state->run_index[comp]];

                if (x + r * stride > w)

                    r = (w - x) / stride;

                for (i = 0; i < r; i++) {

                    W(dst, x, Ra);

                    x += stride;

                }

                /* if EOL reached, we stop decoding */

                if (r != 1 << ff_log2_run[state->run_index[comp]])

                    return;

                if (state->run_index[comp] < 31)

                    state->run_index[comp]++;

                if (x + stride > w)

                    return;

            }

            /* decode aborted run */

            r = ff_log2_run[state->run_index[comp]];

            if (r)

                r = get_bits_long(&s->gb, r);

            if (x + r * stride > w) {

                r = (w - x) / stride;

            }

            for (i = 0; i < r; i++) {

                W(dst, x, Ra);

                x += stride;

            }



            if (x >= w) {

                av_log(NULL, AV_LOG_ERROR, "run overflow\n");


                return;

            }



            /* decode run termination value */

            Rb     = R(last, x);

            RItype = (FFABS(Ra - Rb) <= state->near) ? 1 : 0;

            err    = ls_get_code_runterm(&s->gb, state, RItype,

                                         ff_log2_run[state->run_index[comp]]);

            if (state->run_index[comp])

                state->run_index[comp]--;



            if (state->near && RItype) {

                pred = Ra + err;

            } else {

                if (Rb < Ra)

                    pred = Rb - err;

                else

                    pred = Rb + err;

            }

        } else { /* regular mode */

            int context, sign;



            context = ff_jpegls_quantize(state, D0) * 81 +

                      ff_jpegls_quantize(state, D1) *  9 +

                      ff_jpegls_quantize(state, D2);

            pred    = mid_pred(Ra, Ra + Rb - Rc, Rb);



            if (context < 0) {

                context = -context;

                sign    = 1;

            } else {

                sign = 0;

            }



            if (sign) {

                pred = av_clip(pred - state->C[context], 0, state->maxval);

                err  = -ls_get_code_regular(&s->gb, state, context);

            } else {

                pred = av_clip(pred + state->C[context], 0, state->maxval);

                err  = ls_get_code_regular(&s->gb, state, context);

            }



            /* we have to do something more for near-lossless coding */

            pred += err;

        }

        if (state->near) {

            if (pred < -state->near)

                pred += state->range * state->twonear;

            else if (pred > state->maxval + state->near)

                pred -= state->range * state->twonear;

            pred = av_clip(pred, 0, state->maxval);

        }



        pred &= state->maxval;

        W(dst, x, pred);

        x += stride;

    }

}

dshow_read_close(AVFormatContext *s)

{

    struct dshow_ctx *ctx = s->priv_data;

    AVPacketList *pktl;



    if (ctx->control) {

        IMediaControl_Stop(ctx->control);

        IMediaControl_Release(ctx->control);

    }



    if (ctx->graph) {

        IEnumFilters *fenum;

        int r;

        r = IGraphBuilder_EnumFilters(ctx->graph, &fenum);

        if (r == S_OK) {

            IBaseFilter *f;

            IEnumFilters_Reset(fenum);

            while (IEnumFilters_Next(fenum, 1, &f, NULL) == S_OK) {

                if (IGraphBuilder_RemoveFilter(ctx->graph, f) == S_OK)

                    IEnumFilters_Reset(fenum); /* When a filter is removed,

                                                * the list must be reset. */

                IBaseFilter_Release(f);

            }

            IEnumFilters_Release(fenum);

        }

        IGraphBuilder_Release(ctx->graph);

    }



    if (ctx->capture_pin[VideoDevice])

        libAVPin_Release(ctx->capture_pin[VideoDevice]);

    if (ctx->capture_pin[AudioDevice])

        libAVPin_Release(ctx->capture_pin[AudioDevice]);

    if (ctx->capture_filter[VideoDevice])

        libAVFilter_Release(ctx->capture_filter[VideoDevice]);

    if (ctx->capture_filter[AudioDevice])

        libAVFilter_Release(ctx->capture_filter[AudioDevice]);



    if (ctx->device_pin[VideoDevice])

        IPin_Release(ctx->device_pin[VideoDevice]);

    if (ctx->device_pin[AudioDevice])

        IPin_Release(ctx->device_pin[AudioDevice]);

    if (ctx->device_filter[VideoDevice])

        IBaseFilter_Release(ctx->device_filter[VideoDevice]);

    if (ctx->device_filter[AudioDevice])

        IBaseFilter_Release(ctx->device_filter[AudioDevice]);



    if (ctx->device_name[0])

        av_free(ctx->device_name[0]);

    if (ctx->device_name[1])

        av_free(ctx->device_name[1]);



    if(ctx->mutex)

        CloseHandle(ctx->mutex);

    if(ctx->event)

        CloseHandle(ctx->event);



    pktl = ctx->pktl;

    while (pktl) {

        AVPacketList *next = pktl->next;

        av_destruct_packet(&pktl->pkt);

        av_free(pktl);

        pktl = next;

    }



    return 0;

}

void HELPER(set_cp15)(CPUState *env, uint32_t insn, uint32_t val)

{

    int op1;

    int op2;

    int crm;



    op1 = (insn >> 21) & 7;

    op2 = (insn >> 5) & 7;

    crm = insn & 0xf;

    switch ((insn >> 16) & 0xf) {

    case 0:

        /* ID codes.  */

        if (arm_feature(env, ARM_FEATURE_XSCALE))

            break;

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            break;

        if (arm_feature(env, ARM_FEATURE_V7)

                && op1 == 2 && crm == 0 && op2 == 0) {

            env->cp15.c0_cssel = val & 0xf;

            break;

        }

        goto bad_reg;

    case 1: /* System configuration.  */

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            op2 = 0;

        switch (op2) {

        case 0:

            if (!arm_feature(env, ARM_FEATURE_XSCALE) || crm == 0)

                env->cp15.c1_sys = val;

            /* ??? Lots of these bits are not implemented.  */

            /* This may enable/disable the MMU, so do a TLB flush.  */

            tlb_flush(env, 1);

            break;

        case 1: /* Auxiliary cotrol register.  */

            if (arm_feature(env, ARM_FEATURE_XSCALE)) {

                env->cp15.c1_xscaleauxcr = val;

                break;

            }

            /* Not implemented.  */

            break;

        case 2:

            if (arm_feature(env, ARM_FEATURE_XSCALE))

                goto bad_reg;

            if (env->cp15.c1_coproc != val) {

                env->cp15.c1_coproc = val;

                /* ??? Is this safe when called from within a TB?  */

                tb_flush(env);

            }

            break;

        default:

            goto bad_reg;

        }

        break;

    case 2: /* MMU Page table control / MPU cache control.  */

        if (arm_feature(env, ARM_FEATURE_MPU)) {

            switch (op2) {

            case 0:

                env->cp15.c2_data = val;

                break;

            case 1:

                env->cp15.c2_insn = val;

                break;

            default:

                goto bad_reg;

            }

        } else {

	    switch (op2) {

	    case 0:

		env->cp15.c2_base0 = val;

		break;

	    case 1:

		env->cp15.c2_base1 = val;

		break;

	    case 2:

                val &= 7;

                env->cp15.c2_control = val;

		env->cp15.c2_mask = ~(((uint32_t)0xffffffffu) >> val);

                env->cp15.c2_base_mask = ~((uint32_t)0x3fffu >> val);

		break;

	    default:

		goto bad_reg;

	    }

        }

        break;

    case 3: /* MMU Domain access control / MPU write buffer control.  */

        env->cp15.c3 = val;

        tlb_flush(env, 1); /* Flush TLB as domain not tracked in TLB */

        break;

    case 4: /* Reserved.  */

        goto bad_reg;

    case 5: /* MMU Fault status / MPU access permission.  */

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            op2 = 0;

        switch (op2) {

        case 0:

            if (arm_feature(env, ARM_FEATURE_MPU))

                val = extended_mpu_ap_bits(val);

            env->cp15.c5_data = val;

            break;

        case 1:

            if (arm_feature(env, ARM_FEATURE_MPU))

                val = extended_mpu_ap_bits(val);

            env->cp15.c5_insn = val;

            break;

        case 2:

            if (!arm_feature(env, ARM_FEATURE_MPU))

                goto bad_reg;

            env->cp15.c5_data = val;

            break;

        case 3:

            if (!arm_feature(env, ARM_FEATURE_MPU))

                goto bad_reg;

            env->cp15.c5_insn = val;

            break;

        default:

            goto bad_reg;

        }

        break;

    case 6: /* MMU Fault address / MPU base/size.  */

        if (arm_feature(env, ARM_FEATURE_MPU)) {

            if (crm >= 8)

                goto bad_reg;

            env->cp15.c6_region[crm] = val;

        } else {

            if (arm_feature(env, ARM_FEATURE_OMAPCP))

                op2 = 0;

            switch (op2) {

            case 0:

                env->cp15.c6_data = val;

                break;

            case 1: /* ??? This is WFAR on armv6 */

            case 2:

                env->cp15.c6_insn = val;

                break;

            default:

                goto bad_reg;

            }

        }

        break;

    case 7: /* Cache control.  */

        env->cp15.c15_i_max = 0x000;

        env->cp15.c15_i_min = 0xff0;

        /* No cache, so nothing to do.  */

        /* ??? MPCore has VA to PA translation functions.  */

        break;

    case 8: /* MMU TLB control.  */

        switch (op2) {

        case 0: /* Invalidate all.  */

            tlb_flush(env, 0);

            break;

        case 1: /* Invalidate single TLB entry.  */

#if 0

            /* ??? This is wrong for large pages and sections.  */

            /* As an ugly hack to make linux work we always flush a 4K

               pages.  */

            val &= 0xfffff000;

            tlb_flush_page(env, val);

            tlb_flush_page(env, val + 0x400);

            tlb_flush_page(env, val + 0x800);

            tlb_flush_page(env, val + 0xc00);

#else

            tlb_flush(env, 1);

#endif

            break;

        case 2: /* Invalidate on ASID.  */

            tlb_flush(env, val == 0);

            break;

        case 3: /* Invalidate single entry on MVA.  */

            /* ??? This is like case 1, but ignores ASID.  */

            tlb_flush(env, 1);

            break;

        default:

            goto bad_reg;

        }

        break;

    case 9:

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            break;

        switch (crm) {

        case 0: /* Cache lockdown.  */

	    switch (op1) {

	    case 0: /* L1 cache.  */

		switch (op2) {

		case 0:

		    env->cp15.c9_data = val;

		    break;

		case 1:

		    env->cp15.c9_insn = val;

		    break;

		default:

		    goto bad_reg;

		}

		break;

	    case 1: /* L2 cache.  */

		/* Ignore writes to L2 lockdown/auxiliary registers.  */

		break;

	    default:

		goto bad_reg;

	    }

	    break;

        case 1: /* TCM memory region registers.  */

            /* Not implemented.  */

            goto bad_reg;

        default:

            goto bad_reg;

        }

        break;

    case 10: /* MMU TLB lockdown.  */

        /* ??? TLB lockdown not implemented.  */

        break;

    case 12: /* Reserved.  */

        goto bad_reg;

    case 13: /* Process ID.  */

        switch (op2) {

        case 0:

            /* Unlike real hardware the qemu TLB uses virtual addresses,

               not modified virtual addresses, so this causes a TLB flush.

             */

            if (env->cp15.c13_fcse != val)

              tlb_flush(env, 1);

            env->cp15.c13_fcse = val;

            break;

        case 1:

            /* This changes the ASID, so do a TLB flush.  */

            if (env->cp15.c13_context != val

                && !arm_feature(env, ARM_FEATURE_MPU))

              tlb_flush(env, 0);

            env->cp15.c13_context = val;

            break;

        case 2:

            env->cp15.c13_tls1 = val;

            break;

        case 3:

            env->cp15.c13_tls2 = val;

            break;

        case 4:

            env->cp15.c13_tls3 = val;

            break;

        default:

            goto bad_reg;

        }

        break;

    case 14: /* Reserved.  */

        goto bad_reg;

    case 15: /* Implementation specific.  */

        if (arm_feature(env, ARM_FEATURE_XSCALE)) {

            if (op2 == 0 && crm == 1) {

                if (env->cp15.c15_cpar != (val & 0x3fff)) {

                    /* Changes cp0 to cp13 behavior, so needs a TB flush.  */

                    tb_flush(env);

                    env->cp15.c15_cpar = val & 0x3fff;

                }

                break;

            }

            goto bad_reg;

        }

        if (arm_feature(env, ARM_FEATURE_OMAPCP)) {

            switch (crm) {

            case 0:

                break;

            case 1: /* Set TI925T configuration.  */

                env->cp15.c15_ticonfig = val & 0xe7;

                env->cp15.c0_cpuid = (val & (1 << 5)) ? /* OS_TYPE bit */

                        ARM_CPUID_TI915T : ARM_CPUID_TI925T;

                break;

            case 2: /* Set I_max.  */

                env->cp15.c15_i_max = val;

                break;

            case 3: /* Set I_min.  */

                env->cp15.c15_i_min = val;

                break;

            case 4: /* Set thread-ID.  */

                env->cp15.c15_threadid = val & 0xffff;

                break;

            case 8: /* Wait-for-interrupt (deprecated).  */

                cpu_interrupt(env, CPU_INTERRUPT_HALT);

                break;

            default:

                goto bad_reg;

            }

        }

        break;

    }

    return;

bad_reg:

    /* ??? For debugging only.  Should raise illegal instruction exception.  */

    cpu_abort(env, "Unimplemented cp15 register write (c%d, c%d, {%d, %d})\n",

              (insn >> 16) & 0xf, crm, op1, op2);

}

void acpi_pcihp_init(Object *owner, AcpiPciHpState *s, PCIBus *root_bus,

                     MemoryRegion *address_space_io, bool bridges_enabled)

{

    s->io_len = ACPI_PCIHP_SIZE;

    s->io_base = ACPI_PCIHP_ADDR;



    s->root= root_bus;

    s->legacy_piix = !bridges_enabled;



    if (s->legacy_piix) {

        unsigned *bus_bsel = g_malloc(sizeof *bus_bsel);



        s->io_len = ACPI_PCIHP_LEGACY_SIZE;



        *bus_bsel = ACPI_PCIHP_BSEL_DEFAULT;

        object_property_add_uint32_ptr(OBJECT(root_bus), ACPI_PCIHP_PROP_BSEL,

                                       bus_bsel, NULL);

    }



    memory_region_init_io(&s->io, owner, &acpi_pcihp_io_ops, s,

                          "acpi-pci-hotplug", s->io_len);

    memory_region_add_subregion(address_space_io, s->io_base, &s->io);



    object_property_add_uint16_ptr(owner, ACPI_PCIHP_IO_BASE_PROP, &s->io_base,

                                   &error_abort);

    object_property_add_uint16_ptr(owner, ACPI_PCIHP_IO_LEN_PROP, &s->io_len,

                                   &error_abort);

}

void hmp_info_memory_devices(Monitor *mon, const QDict *qdict)

{

    Error *err = NULL;

    MemoryDeviceInfoList *info_list = qmp_query_memory_devices(&err);

    MemoryDeviceInfoList *info;

    MemoryDeviceInfo *value;

    PCDIMMDeviceInfo *di;



    for (info = info_list; info; info = info->next) {

        value = info->value;



        if (value) {

            switch (value->kind) {

            case MEMORY_DEVICE_INFO_KIND_DIMM:

                di = value->dimm;



                monitor_printf(mon, "Memory device [%s]: \"%s\"\n",

                               MemoryDeviceInfoKind_lookup[value->kind],

                               di->id ? di->id : "");

                monitor_printf(mon, "  addr: 0x%" PRIx64 "\n", di->addr);

                monitor_printf(mon, "  slot: %" PRId64 "\n", di->slot);

                monitor_printf(mon, "  node: %" PRId64 "\n", di->node);

                monitor_printf(mon, "  size: %" PRIu64 "\n", di->size);

                monitor_printf(mon, "  memdev: %s\n", di->memdev);

                monitor_printf(mon, "  hotplugged: %s\n",

                               di->hotplugged ? "true" : "false");

                monitor_printf(mon, "  hotpluggable: %s\n",

                               di->hotpluggable ? "true" : "false");

                break;

            default:

                break;

            }

        }

    }



    qapi_free_MemoryDeviceInfoList(info_list);

}

static int dot_product(const int16_t *a, const int16_t *b, int length)

{

    int i, sum = 0;



    for (i = 0; i < length; i++) {

        int64_t prod = av_clipl_int32(MUL64(a[i], b[i]) << 1);

        sum = av_clipl_int32(sum + prod);

    }

    return sum;

}

static void process_incoming_migration_bh(void *opaque)

{

    Error *local_err = NULL;

    MigrationIncomingState *mis = opaque;



    /* Make sure all file formats flush their mutable metadata.

     * If we get an error here, just don't restart the VM yet. */

    bdrv_invalidate_cache_all(&local_err);

    if (!local_err) {

        blk_resume_after_migration(&local_err);

    }

    if (local_err) {

        error_report_err(local_err);

        local_err = NULL;

        autostart = false;

    }



    /*

     * This must happen after all error conditions are dealt with and

     * we're sure the VM is going to be running on this host.

     */

    qemu_announce_self();



    /* If global state section was not received or we are in running

       state, we need to obey autostart. Any other state is set with

       runstate_set. */



    if (!global_state_received() ||

        global_state_get_runstate() == RUN_STATE_RUNNING) {

        if (autostart) {

            vm_start();

        } else {

            runstate_set(RUN_STATE_PAUSED);

        }

    } else {

        runstate_set(global_state_get_runstate());

    }

    migrate_decompress_threads_join();

    /*

     * This must happen after any state changes since as soon as an external

     * observer sees this event they might start to prod at the VM assuming

     * it's ready to use.

     */

    migrate_set_state(&mis->state, MIGRATION_STATUS_ACTIVE,

                      MIGRATION_STATUS_COMPLETED);

    qemu_bh_delete(mis->bh);

    migration_incoming_state_destroy();

}

static void vdadec_flush(AVCodecContext *avctx)

{

    return ff_h264_decoder.flush(avctx);

}

int ff_h2645_extract_rbsp(const uint8_t *src, int length,

                          H2645NAL *nal)

{

    int i, si, di;

    uint8_t *dst;



    nal->skipped_bytes = 0;

#define STARTCODE_TEST                                                  \

        if (i + 2 < length && src[i + 1] == 0 && src[i + 2] <= 3) {     \

            if (src[i + 2] != 3 && src[i + 2] != 0) {                   \

                /* startcode, so we must be past the end */             \

                length = i;                                             \

            }                                                           \

            break;                                                      \

        }

#if HAVE_FAST_UNALIGNED

#define FIND_FIRST_ZERO                                                 \

        if (i > 0 && !src[i])                                           \

            i--;                                                        \

        while (src[i])                                                  \

            i++

#if HAVE_FAST_64BIT

    for (i = 0; i + 1 < length; i += 9) {

        if (!((~AV_RN64A(src + i) &

               (AV_RN64A(src + i) - 0x0100010001000101ULL)) &

              0x8000800080008080ULL))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 7;

    }

#else

    for (i = 0; i + 1 < length; i += 5) {

        if (!((~AV_RN32A(src + i) &

               (AV_RN32A(src + i) - 0x01000101U)) &

              0x80008080U))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 3;

    }

#endif /* HAVE_FAST_64BIT */

#else

    for (i = 0; i + 1 < length; i += 2) {

        if (src[i])

            continue;

        if (i > 0 && src[i - 1] == 0)

            i--;

        STARTCODE_TEST;

    }

#endif /* HAVE_FAST_UNALIGNED */



    if (i >= length - 1) { // no escaped 0

        nal->data     =

        nal->raw_data = src;

        nal->size     =

        nal->raw_size = length;

        return length;

    }



    av_fast_malloc(&nal->rbsp_buffer, &nal->rbsp_buffer_size,

                   length + AV_INPUT_BUFFER_PADDING_SIZE);

    if (!nal->rbsp_buffer)

        return AVERROR(ENOMEM);



    dst = nal->rbsp_buffer;



    memcpy(dst, src, i);

    si = di = i;

    while (si + 2 < length) {

        // remove escapes (very rare 1:2^22)

        if (src[si + 2] > 3) {

            dst[di++] = src[si++];

            dst[di++] = src[si++];

        } else if (src[si] == 0 && src[si + 1] == 0 && src[si + 2] != 0) {

            if (src[si + 2] == 3) { // escape

                dst[di++] = 0;

                dst[di++] = 0;

                si       += 3;



                if (nal->skipped_bytes_pos) {

                    nal->skipped_bytes++;

                    if (nal->skipped_bytes_pos_size < nal->skipped_bytes) {

                        nal->skipped_bytes_pos_size *= 2;

                        av_assert0(nal->skipped_bytes_pos_size >= nal->skipped_bytes);

                        av_reallocp_array(&nal->skipped_bytes_pos,

                                nal->skipped_bytes_pos_size,

                                sizeof(*nal->skipped_bytes_pos));

                        if (!nal->skipped_bytes_pos) {

                            nal->skipped_bytes_pos_size = 0;

                            return AVERROR(ENOMEM);

                        }

                    }

                    if (nal->skipped_bytes_pos)

                        nal->skipped_bytes_pos[nal->skipped_bytes-1] = di - 1;

                }

                continue;

            } else // next start code

                goto nsc;

        }



        dst[di++] = src[si++];

    }

    while (si < length)

        dst[di++] = src[si++];



nsc:

    memset(dst + di, 0, AV_INPUT_BUFFER_PADDING_SIZE);



    nal->data = dst;

    nal->size = di;

    nal->raw_data = src;

    nal->raw_size = si;

    return si;

}

static inline int svq3_mc_dir(SVQ3Context *s, int size, int mode,

                              int dir, int avg)

{

    int i, j, k, mx, my, dx, dy, x, y;

    const int part_width    = ((size & 5) == 4) ? 4 : 16 >> (size & 1);

    const int part_height   = 16 >> ((unsigned)(size + 1) / 3);

    const int extra_width   = (mode == PREDICT_MODE) ? -16 * 6 : 0;

    const int h_edge_pos    = 6 * (s->h_edge_pos - part_width)  - extra_width;

    const int v_edge_pos    = 6 * (s->v_edge_pos - part_height) - extra_width;



    for (i = 0; i < 16; i += part_height)

        for (j = 0; j < 16; j += part_width) {

            const int b_xy = (4 * s->mb_x + (j >> 2)) +

                             (4 * s->mb_y + (i >> 2)) * s->b_stride;

            int dxy;

            x = 16 * s->mb_x + j;

            y = 16 * s->mb_y + i;

            k = (j >> 2 & 1) + (i >> 1 & 2) +

                (j >> 1 & 4) + (i      & 8);



            if (mode != PREDICT_MODE) {

                svq3_pred_motion(s, k, part_width >> 2, dir, 1, &mx, &my);

            } else {

                mx = s->next_pic->motion_val[0][b_xy][0] << 1;

                my = s->next_pic->motion_val[0][b_xy][1] << 1;



                if (dir == 0) {

                    mx = mx * s->frame_num_offset /

                         s->prev_frame_num_offset + 1 >> 1;

                    my = my * s->frame_num_offset /

                         s->prev_frame_num_offset + 1 >> 1;

                } else {

                    mx = mx * (s->frame_num_offset - s->prev_frame_num_offset) /

                         s->prev_frame_num_offset + 1 >> 1;

                    my = my * (s->frame_num_offset - s->prev_frame_num_offset) /

                         s->prev_frame_num_offset + 1 >> 1;

                }

            }



            /* clip motion vector prediction to frame border */

            mx = av_clip(mx, extra_width - 6 * x, h_edge_pos - 6 * x);

            my = av_clip(my, extra_width - 6 * y, v_edge_pos - 6 * y);



            /* get (optional) motion vector differential */

            if (mode == PREDICT_MODE) {

                dx = dy = 0;

            } else {

                dy = get_interleaved_se_golomb(&s->gb_slice);

                dx = get_interleaved_se_golomb(&s->gb_slice);



                if (dx != (int16_t)dx || dy != (int16_t)dy) {

                    av_log(s->avctx, AV_LOG_ERROR, "invalid MV vlc\n");

                    return -1;

                }

            }



            /* compute motion vector */

            if (mode == THIRDPEL_MODE) {

                int fx, fy;

                mx  = (mx + 1 >> 1) + dx;

                my  = (my + 1 >> 1) + dy;

                fx  = (unsigned)(mx + 0x30000) / 3 - 0x10000;

                fy  = (unsigned)(my + 0x30000) / 3 - 0x10000;

                dxy = (mx - 3 * fx) + 4 * (my - 3 * fy);



                svq3_mc_dir_part(s, x, y, part_width, part_height,

                                 fx, fy, dxy, 1, dir, avg);

                mx += mx;

                my += my;

            } else if (mode == HALFPEL_MODE || mode == PREDICT_MODE) {

                mx  = (unsigned)(mx + 1 + 0x30000) / 3 + dx - 0x10000;

                my  = (unsigned)(my + 1 + 0x30000) / 3 + dy - 0x10000;

                dxy = (mx & 1) + 2 * (my & 1);



                svq3_mc_dir_part(s, x, y, part_width, part_height,

                                 mx >> 1, my >> 1, dxy, 0, dir, avg);

                mx *= 3;

                my *= 3;

            } else {

                mx = (unsigned)(mx + 3 + 0x60000) / 6 + dx - 0x10000;

                my = (unsigned)(my + 3 + 0x60000) / 6 + dy - 0x10000;



                svq3_mc_dir_part(s, x, y, part_width, part_height,

                                 mx, my, 0, 0, dir, avg);

                mx *= 6;

                my *= 6;

            }



            /* update mv_cache */

            if (mode != PREDICT_MODE) {

                int32_t mv = pack16to32(mx, my);



                if (part_height == 8 && i < 8) {

                    AV_WN32A(s->mv_cache[dir][scan8[k] + 1 * 8], mv);



                    if (part_width == 8 && j < 8)

                        AV_WN32A(s->mv_cache[dir][scan8[k] + 1 + 1 * 8], mv);

                }

                if (part_width == 8 && j < 8)

                    AV_WN32A(s->mv_cache[dir][scan8[k] + 1], mv);

                if (part_width == 4 || part_height == 4)

                    AV_WN32A(s->mv_cache[dir][scan8[k]], mv);

            }



            /* write back motion vectors */

            fill_rectangle(s->cur_pic->motion_val[dir][b_xy],

                           part_width >> 2, part_height >> 2, s->b_stride,

                           pack16to32(mx, my), 4);

        }



    return 0;

}

static int hwmap_filter_frame(AVFilterLink *link, AVFrame *input)

{

    AVFilterContext *avctx = link->dst;

    AVFilterLink  *outlink = avctx->outputs[0];

    HWMapContext      *ctx = avctx->priv;

    AVFrame *map = NULL;

    int err;



    av_log(ctx, AV_LOG_DEBUG, "Filter input: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(input->format),

           input->width, input->height, input->pts);



    map = av_frame_alloc();

    if (!map) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    map->format = outlink->format;

    map->hw_frames_ctx = av_buffer_ref(ctx->hwframes_ref);

    if (!map->hw_frames_ctx) {

        err = AVERROR(ENOMEM);

        goto fail;

    }



    if (ctx->map_backwards && !input->hw_frames_ctx) {

        // If we mapped backwards from hardware to software, we need

        // to attach the hardware frame context to the input frame to

        // make the mapping visible to av_hwframe_map().

        input->hw_frames_ctx = av_buffer_ref(ctx->hwframes_ref);

        if (!input->hw_frames_ctx) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

    }



    err = av_hwframe_map(map, input, ctx->mode);

    if (err < 0) {

        av_log(avctx, AV_LOG_ERROR, "Failed to map frame: %d.\n", err);

        goto fail;

    }



    err = av_frame_copy_props(map, input);

    if (err < 0)

        goto fail;



    av_frame_free(&input);



    av_log(ctx, AV_LOG_DEBUG, "Filter output: %s, %ux%u (%"PRId64").\n",

           av_get_pix_fmt_name(map->format),

           map->width, map->height, map->pts);



    return ff_filter_frame(outlink, map);



fail:

    av_frame_free(&input);

    av_frame_free(&map);

    return err;

}

static int xio3130_upstream_initfn(PCIDevice *d)

{

    PCIEPort *p = PCIE_PORT(d);

    int rc;

    Error *err = NULL;



    pci_bridge_initfn(d, TYPE_PCIE_BUS);

    pcie_port_init_reg(d);



    rc = msi_init(d, XIO3130_MSI_OFFSET, XIO3130_MSI_NR_VECTOR,

                  XIO3130_MSI_SUPPORTED_FLAGS & PCI_MSI_FLAGS_64BIT,

                  XIO3130_MSI_SUPPORTED_FLAGS & PCI_MSI_FLAGS_MASKBIT, &err);

    if (rc < 0) {

        assert(rc == -ENOTSUP);

        error_report_err(err);

        goto err_bridge;

    }



    rc = pci_bridge_ssvid_init(d, XIO3130_SSVID_OFFSET,

                               XIO3130_SSVID_SVID, XIO3130_SSVID_SSID);

    if (rc < 0) {

        goto err_bridge;

    }



    rc = pcie_cap_init(d, XIO3130_EXP_OFFSET, PCI_EXP_TYPE_UPSTREAM,

                       p->port);

    if (rc < 0) {

        goto err_msi;

    }

    pcie_cap_flr_init(d);

    pcie_cap_deverr_init(d);



    rc = pcie_aer_init(d, XIO3130_AER_OFFSET, PCI_ERR_SIZEOF);

    if (rc < 0) {

        goto err;

    }



    return 0;



err:

    pcie_cap_exit(d);

err_msi:

    msi_uninit(d);

err_bridge:

    pci_bridge_exitfn(d);

    return rc;

}

static int csrhci_write(struct CharDriverState *chr,

                const uint8_t *buf, int len)

{

    struct csrhci_s *s = (struct csrhci_s *) chr->opaque;

    int plen = s->in_len;



    if (!s->enable)

        return 0;



    s->in_len += len;

    memcpy(s->inpkt + plen, buf, len);



    while (1) {

        if (s->in_len >= 2 && plen < 2)

            s->in_hdr = csrhci_header_len(s->inpkt) + 1;



        if (s->in_len >= s->in_hdr && plen < s->in_hdr)

            s->in_data = csrhci_data_len(s->inpkt) + s->in_hdr;



        if (s->in_len >= s->in_data) {

            csrhci_in_packet(s, s->inpkt);



            memmove(s->inpkt, s->inpkt + s->in_len, s->in_len - s->in_data);

            s->in_len -= s->in_data;

            s->in_hdr = INT_MAX;

            s->in_data = INT_MAX;

            plen = 0;

        } else

            break;

    }



    return len;

}

static void synth_block_fcb_acb(WMAVoiceContext *s, GetBitContext *gb,

                                int block_idx, int size,

                                int block_pitch_sh2,

                                const struct frame_type_desc *frame_desc,

                                float *excitation)

{

    static const float gain_coeff[6] = {

        0.8169, -0.06545, 0.1726, 0.0185, -0.0359, 0.0458

    };

    float pulses[MAX_FRAMESIZE / 2], pred_err, acb_gain, fcb_gain;

    int n, idx, gain_weight;

    AMRFixed fcb;



    assert(size <= MAX_FRAMESIZE / 2);

    memset(pulses, 0, sizeof(*pulses) * size);



    fcb.pitch_lag      = block_pitch_sh2 >> 2;

    fcb.pitch_fac      = 1.0;

    fcb.no_repeat_mask = 0;

    fcb.n              = 0;



    /* For the other frame types, this is where we apply the innovation

     * (fixed) codebook pulses of the speech signal. */

    if (frame_desc->fcb_type == FCB_TYPE_AW_PULSES) {

        aw_pulse_set1(s, gb, block_idx, &fcb);

        aw_pulse_set2(s, gb, block_idx, &fcb);

    } else /* FCB_TYPE_EXC_PULSES */ {

        int offset_nbits = 5 - frame_desc->log_n_blocks;



        fcb.no_repeat_mask = -1;

        /* similar to ff_decode_10_pulses_35bits(), but with single pulses

         * (instead of double) for a subset of pulses */

        for (n = 0; n < 5; n++) {

            float sign;

            int pos1, pos2;



            sign           = get_bits1(gb) ? 1.0 : -1.0;

            pos1           = get_bits(gb, offset_nbits);

            fcb.x[fcb.n]   = n + 5 * pos1;

            fcb.y[fcb.n++] = sign;

            if (n < frame_desc->dbl_pulses) {

                pos2           = get_bits(gb, offset_nbits);

                fcb.x[fcb.n]   = n + 5 * pos2;

                fcb.y[fcb.n++] = (pos1 < pos2) ? -sign : sign;

            }

        }

    }

    ff_set_fixed_vector(pulses, &fcb, 1.0, size);



    /* Calculate gain for adaptive & fixed codebook signal.

     * see ff_amr_set_fixed_gain(). */

    idx = get_bits(gb, 7);

    fcb_gain = expf(avpriv_scalarproduct_float_c(s->gain_pred_err,

                                                 gain_coeff, 6) -

                    5.2409161640 + wmavoice_gain_codebook_fcb[idx]);

    acb_gain = wmavoice_gain_codebook_acb[idx];

    pred_err = av_clipf(wmavoice_gain_codebook_fcb[idx],

                        -2.9957322736 /* log(0.05) */,

                         1.6094379124 /* log(5.0)  */);



    gain_weight = 8 >> frame_desc->log_n_blocks;

    memmove(&s->gain_pred_err[gain_weight], s->gain_pred_err,

            sizeof(*s->gain_pred_err) * (6 - gain_weight));

    for (n = 0; n < gain_weight; n++)

        s->gain_pred_err[n] = pred_err;



    /* Calculation of adaptive codebook */

    if (frame_desc->acb_type == ACB_TYPE_ASYMMETRIC) {

        int len;

        for (n = 0; n < size; n += len) {

            int next_idx_sh16;

            int abs_idx    = block_idx * size + n;

            int pitch_sh16 = (s->last_pitch_val << 16) +

                             s->pitch_diff_sh16 * abs_idx;

            int pitch      = (pitch_sh16 + 0x6FFF) >> 16;

            int idx_sh16   = ((pitch << 16) - pitch_sh16) * 8 + 0x58000;

            idx            = idx_sh16 >> 16;

            if (s->pitch_diff_sh16) {

                if (s->pitch_diff_sh16 > 0) {

                    next_idx_sh16 = (idx_sh16) &~ 0xFFFF;

                } else

                    next_idx_sh16 = (idx_sh16 + 0x10000) &~ 0xFFFF;

                len = av_clip((idx_sh16 - next_idx_sh16) / s->pitch_diff_sh16 / 8,

                              1, size - n);

            } else

                len = size;



            ff_acelp_interpolatef(&excitation[n], &excitation[n - pitch],

                                  wmavoice_ipol1_coeffs, 17,

                                  idx, 9, len);

        }

    } else /* ACB_TYPE_HAMMING */ {

        int block_pitch = block_pitch_sh2 >> 2;

        idx             = block_pitch_sh2 & 3;

        if (idx) {

            ff_acelp_interpolatef(excitation, &excitation[-block_pitch],

                                  wmavoice_ipol2_coeffs, 4,

                                  idx, 8, size);

        } else

            av_memcpy_backptr((uint8_t *) excitation, sizeof(float) * block_pitch,

                              sizeof(float) * size);

    }



    /* Interpolate ACB/FCB and use as excitation signal */

    ff_weighted_vector_sumf(excitation, excitation, pulses,

                            acb_gain, fcb_gain, size);

}

