{

    vp8_decode_flush_impl(avctx, 0, 0);

}

static uint16_t blizzard_reg_read(void *opaque, uint8_t reg)

{

    BlizzardState *s = (BlizzardState *) opaque;



    switch (reg) {

    case 0x00:	/* Revision Code */

        return 0xa5;



    case 0x02:	/* Configuration Readback */

        return 0x83;	/* Macrovision OK, CNF[2:0] = 3 */



    case 0x04:	/* PLL M-Divider */

        return (s->pll - 1) | (1 << 7);

    case 0x06:	/* PLL Lock Range Control */

        return s->pll_range;

    case 0x08:	/* PLL Lock Synthesis Control 0 */

        return s->pll_ctrl & 0xff;

    case 0x0a:	/* PLL Lock Synthesis Control 1 */

        return s->pll_ctrl >> 8;

    case 0x0c:	/* PLL Mode Control 0 */

        return s->pll_mode;



    case 0x0e:	/* Clock-Source Select */

        return s->clksel;



    case 0x10:	/* Memory Controller Activate */

    case 0x14:	/* Memory Controller Bank 0 Status Flag */

        return s->memenable;



    case 0x18:	/* Auto-Refresh Interval Setting 0 */

        return s->memrefresh & 0xff;

    case 0x1a:	/* Auto-Refresh Interval Setting 1 */

        return s->memrefresh >> 8;



    case 0x1c:	/* Power-On Sequence Timing Control */

        return s->timing[0];

    case 0x1e:	/* Timing Control 0 */

        return s->timing[1];

    case 0x20:	/* Timing Control 1 */

        return s->timing[2];



    case 0x24:	/* Arbitration Priority Control */

        return s->priority;



    case 0x28:	/* LCD Panel Configuration */

        return s->lcd_config;



    case 0x2a:	/* LCD Horizontal Display Width */

        return s->x >> 3;

    case 0x2c:	/* LCD Horizontal Non-display Period */

        return s->hndp;

    case 0x2e:	/* LCD Vertical Display Height 0 */

        return s->y & 0xff;

    case 0x30:	/* LCD Vertical Display Height 1 */

        return s->y >> 8;

    case 0x32:	/* LCD Vertical Non-display Period */

        return s->vndp;

    case 0x34:	/* LCD HS Pulse-width */

        return s->hsync;

    case 0x36:	/* LCd HS Pulse Start Position */

        return s->skipx >> 3;

    case 0x38:	/* LCD VS Pulse-width */

        return s->vsync;

    case 0x3a:	/* LCD VS Pulse Start Position */

        return s->skipy;



    case 0x3c:	/* PCLK Polarity */

        return s->pclk;



    case 0x3e:	/* High-speed Serial Interface Tx Configuration Port 0 */

        return s->hssi_config[0];

    case 0x40:	/* High-speed Serial Interface Tx Configuration Port 1 */

        return s->hssi_config[1];

    case 0x42:	/* High-speed Serial Interface Tx Mode */

        return s->hssi_config[2];

    case 0x44:	/* TV Display Configuration */

        return s->tv_config;

    case 0x46 ... 0x4c:	/* TV Vertical Blanking Interval Data bits */

        return s->tv_timing[(reg - 0x46) >> 1];

    case 0x4e:	/* VBI: Closed Caption / XDS Control / Status */

        return s->vbi;

    case 0x50:	/* TV Horizontal Start Position */

        return s->tv_x;

    case 0x52:	/* TV Vertical Start Position */

        return s->tv_y;

    case 0x54:	/* TV Test Pattern Setting */

        return s->tv_test;

    case 0x56:	/* TV Filter Setting */

        return s->tv_filter_config;

    case 0x58:	/* TV Filter Coefficient Index */

        return s->tv_filter_idx;

    case 0x5a:	/* TV Filter Coefficient Data */

        if (s->tv_filter_idx < 0x20)

            return s->tv_filter_coeff[s->tv_filter_idx ++];

        return 0;



    case 0x60:	/* Input YUV/RGB Translate Mode 0 */

        return s->yrc[0];

    case 0x62:	/* Input YUV/RGB Translate Mode 1 */

        return s->yrc[1];

    case 0x64:	/* U Data Fix */

        return s->u;

    case 0x66:	/* V Data Fix */

        return s->v;



    case 0x68:	/* Display Mode */

        return s->mode;



    case 0x6a:	/* Special Effects */

        return s->effect;



    case 0x6c:	/* Input Window X Start Position 0 */

        return s->ix[0] & 0xff;

    case 0x6e:	/* Input Window X Start Position 1 */

        return s->ix[0] >> 3;

    case 0x70:	/* Input Window Y Start Position 0 */

        return s->ix[0] & 0xff;

    case 0x72:	/* Input Window Y Start Position 1 */

        return s->ix[0] >> 3;

    case 0x74:	/* Input Window X End Position 0 */

        return s->ix[1] & 0xff;

    case 0x76:	/* Input Window X End Position 1 */

        return s->ix[1] >> 3;

    case 0x78:	/* Input Window Y End Position 0 */

        return s->ix[1] & 0xff;

    case 0x7a:	/* Input Window Y End Position 1 */

        return s->ix[1] >> 3;

    case 0x7c:	/* Output Window X Start Position 0 */

        return s->ox[0] & 0xff;

    case 0x7e:	/* Output Window X Start Position 1 */

        return s->ox[0] >> 3;

    case 0x80:	/* Output Window Y Start Position 0 */

        return s->oy[0] & 0xff;

    case 0x82:	/* Output Window Y Start Position 1 */

        return s->oy[0] >> 3;

    case 0x84:	/* Output Window X End Position 0 */

        return s->ox[1] & 0xff;

    case 0x86:	/* Output Window X End Position 1 */

        return s->ox[1] >> 3;

    case 0x88:	/* Output Window Y End Position 0 */

        return s->oy[1] & 0xff;

    case 0x8a:	/* Output Window Y End Position 1 */

        return s->oy[1] >> 3;



    case 0x8c:	/* Input Data Format */

        return s->iformat;

    case 0x8e:	/* Data Source Select */

        return s->source;

    case 0x90:	/* Display Memory Data Port */

        return 0;



    case 0xa8:	/* Border Color 0 */

        return s->border_r;

    case 0xaa:	/* Border Color 1 */

        return s->border_g;

    case 0xac:	/* Border Color 2 */

        return s->border_b;



    case 0xb4:	/* Gamma Correction Enable */

        return s->gamma_config;

    case 0xb6:	/* Gamma Correction Table Index */

        return s->gamma_idx;

    case 0xb8:	/* Gamma Correction Table Data */

        return s->gamma_lut[s->gamma_idx ++];



    case 0xba:	/* 3x3 Matrix Enable */

        return s->matrix_ena;

    case 0xbc ... 0xde:	/* Coefficient Registers */

        return s->matrix_coeff[(reg - 0xbc) >> 1];

    case 0xe0:	/* 3x3 Matrix Red Offset */

        return s->matrix_r;

    case 0xe2:	/* 3x3 Matrix Green Offset */

        return s->matrix_g;

    case 0xe4:	/* 3x3 Matrix Blue Offset */

        return s->matrix_b;



    case 0xe6:	/* Power-save */

        return s->pm;

    case 0xe8:	/* Non-display Period Control / Status */

        return s->status | (1 << 5);

    case 0xea:	/* RGB Interface Control */

        return s->rgbgpio_dir;

    case 0xec:	/* RGB Interface Status */

        return s->rgbgpio;

    case 0xee:	/* General-purpose IO Pins Configuration */

        return s->gpio_dir;

    case 0xf0:	/* General-purpose IO Pins Status / Control */

        return s->gpio;

    case 0xf2:	/* GPIO Positive Edge Interrupt Trigger */

        return s->gpio_edge[0];

    case 0xf4:	/* GPIO Negative Edge Interrupt Trigger */

        return s->gpio_edge[1];

    case 0xf6:	/* GPIO Interrupt Status */

        return s->gpio_irq;

    case 0xf8:	/* GPIO Pull-down Control */

        return s->gpio_pdown;



    default:

        fprintf(stderr, "%s: unknown register %02x\n", __FUNCTION__, reg);

        return 0;

    }

}

static int decode_slice(AVCodecContext *avctx, void *tdata)

{

    ProresThreadData *td = tdata;

    ProresContext *ctx = avctx->priv_data;

    int mb_x_pos  = td->x_pos;

    int mb_y_pos  = td->y_pos;

    int pic_num   = ctx->pic_num;

    int slice_num = td->slice_num;

    int mbs_per_slice = td->slice_width;

    const uint8_t *buf;

    uint8_t *y_data, *u_data, *v_data, *a_data;

    AVFrame *pic = ctx->frame;

    int i, sf, slice_width_factor;

    int slice_data_size, hdr_size;

    int y_data_size, u_data_size, v_data_size, a_data_size;

    int y_linesize, u_linesize, v_linesize, a_linesize;

    int coff[4];

    int ret;



    buf             = ctx->slice_data[slice_num].index;

    slice_data_size = ctx->slice_data[slice_num + 1].index - buf;



    slice_width_factor = av_log2(mbs_per_slice);



    y_data     = pic->data[0];

    u_data     = pic->data[1];

    v_data     = pic->data[2];

    a_data     = pic->data[3];

    y_linesize = pic->linesize[0];

    u_linesize = pic->linesize[1];

    v_linesize = pic->linesize[2];

    a_linesize = pic->linesize[3];



    if (pic->interlaced_frame) {

        if (!(pic_num ^ pic->top_field_first)) {

            y_data += y_linesize;

            u_data += u_linesize;

            v_data += v_linesize;

            if (a_data)

                a_data += a_linesize;

        }

        y_linesize <<= 1;

        u_linesize <<= 1;

        v_linesize <<= 1;

        a_linesize <<= 1;

    }

    y_data += (mb_y_pos << 4) * y_linesize + (mb_x_pos << 5);

    u_data += (mb_y_pos << 4) * u_linesize + (mb_x_pos << ctx->mb_chroma_factor);

    v_data += (mb_y_pos << 4) * v_linesize + (mb_x_pos << ctx->mb_chroma_factor);

    if (a_data)

        a_data += (mb_y_pos << 4) * a_linesize + (mb_x_pos << 5);



    if (slice_data_size < 6) {

        av_log(avctx, AV_LOG_ERROR, "slice data too small\n");

        return AVERROR_INVALIDDATA;

    }



    /* parse slice header */

    hdr_size    = buf[0] >> 3;

    coff[0]     = hdr_size;

    y_data_size = AV_RB16(buf + 2);

    coff[1]     = coff[0] + y_data_size;

    u_data_size = AV_RB16(buf + 4);

    coff[2]     = coff[1] + u_data_size;

    v_data_size = hdr_size > 7 ? AV_RB16(buf + 6) : slice_data_size - coff[2];

    coff[3]     = coff[2] + v_data_size;

    a_data_size = ctx->alpha_info ? slice_data_size - coff[3] : 0;



    /* if V or alpha component size is negative that means that previous

       component sizes are too large */

    if (v_data_size < 0 || a_data_size < 0 || hdr_size < 6) {

        av_log(avctx, AV_LOG_ERROR, "invalid data size\n");

        return AVERROR_INVALIDDATA;

    }



    sf = av_clip(buf[1], 1, 224);

    sf = sf > 128 ? (sf - 96) << 2 : sf;



    /* scale quantization matrixes according with slice's scale factor */

    /* TODO: this can be SIMD-optimized a lot */

    if (ctx->qmat_changed || sf != td->prev_slice_sf) {

        td->prev_slice_sf = sf;

        for (i = 0; i < 64; i++) {

            td->qmat_luma_scaled[ctx->dsp.idct_permutation[i]]   = ctx->qmat_luma[i]   * sf;

            td->qmat_chroma_scaled[ctx->dsp.idct_permutation[i]] = ctx->qmat_chroma[i] * sf;

        }

    }



    /* decode luma plane */

    ret = decode_slice_plane(ctx, td, buf + coff[0], y_data_size,

                             (uint16_t*) y_data, y_linesize,

                             mbs_per_slice, 4, slice_width_factor + 2,

                             td->qmat_luma_scaled, 0);



    if (ret < 0)

        return ret;



    /* decode U chroma plane */

    ret = decode_slice_plane(ctx, td, buf + coff[1], u_data_size,

                             (uint16_t*) u_data, u_linesize,

                             mbs_per_slice, ctx->num_chroma_blocks,

                             slice_width_factor + ctx->chroma_factor - 1,

                             td->qmat_chroma_scaled, 1);

    if (ret < 0)

        return ret;



    /* decode V chroma plane */

    ret = decode_slice_plane(ctx, td, buf + coff[2], v_data_size,

                             (uint16_t*) v_data, v_linesize,

                             mbs_per_slice, ctx->num_chroma_blocks,

                             slice_width_factor + ctx->chroma_factor - 1,

                             td->qmat_chroma_scaled, 1);

    if (ret < 0)

        return ret;



    /* decode alpha plane if available */

    if (a_data && a_data_size)

        decode_alpha_plane(ctx, td, buf + coff[3], a_data_size,

                           (uint16_t*) a_data, a_linesize,

                           mbs_per_slice);



    return 0;

}

void *qemu_malloc(size_t size)

{

    return malloc(size);

}

static int mov_read_strf(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    AVStream *st;



    if (c->fc->nb_streams < 1)

        return 0;

    if (atom.size <= 40)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];



    if ((uint64_t)atom.size > (1<<30))

        return AVERROR_INVALIDDATA;



    av_free(st->codec->extradata);

    st->codec->extradata = av_mallocz(atom.size - 40 + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!st->codec->extradata)

        return AVERROR(ENOMEM);

    st->codec->extradata_size = atom.size - 40;

    avio_skip(pb, 40);

    avio_read(pb, st->codec->extradata, atom.size - 40);

    return 0;

}

yuv2rgb_full_X_c_template(SwsContext *c, const int16_t *lumFilter,

                          const int16_t **lumSrc, int lumFilterSize,

                          const int16_t *chrFilter, const int16_t **chrUSrc,

                          const int16_t **chrVSrc, int chrFilterSize,

                          const int16_t **alpSrc, uint8_t *dest,

                          int dstW, int y, enum AVPixelFormat target, int hasAlpha)

{

    int i;

    int step = (target == AV_PIX_FMT_RGB24 || target == AV_PIX_FMT_BGR24) ? 3 : 4;

    int err[4] = {0};



    if(   target == AV_PIX_FMT_BGR4_BYTE || target == AV_PIX_FMT_RGB4_BYTE

       || target == AV_PIX_FMT_BGR8      || target == AV_PIX_FMT_RGB8)

        step = 1;



    for (i = 0; i < dstW; i++) {

        int j;

        int Y = 1<<9;

        int U = (1<<9)-(128 << 19);

        int V = (1<<9)-(128 << 19);

        int A;



        for (j = 0; j < lumFilterSize; j++) {

            Y += lumSrc[j][i] * lumFilter[j];

        }

        for (j = 0; j < chrFilterSize; j++) {

            U += chrUSrc[j][i] * chrFilter[j];

            V += chrVSrc[j][i] * chrFilter[j];

        }

        Y >>= 10;

        U >>= 10;

        V >>= 10;

        if (hasAlpha) {

            A = 1 << 18;

            for (j = 0; j < lumFilterSize; j++) {

                A += alpSrc[j][i] * lumFilter[j];

            }

            A >>= 19;

            if (A & 0x100)

                A = av_clip_uint8(A);

        }

        yuv2rgb_write_full(c, dest, i, Y, A, U, V, y, target, hasAlpha, err);

        dest += step;

    }

    c->dither_error[0][i] = err[0];

    c->dither_error[1][i] = err[1];

    c->dither_error[2][i] = err[2];

}

static void coroutine_fn mirror_pause(BlockJob *job)

{

    MirrorBlockJob *s = container_of(job, MirrorBlockJob, common);



    mirror_drain(s);

}

static void compute_exp_strategy(AC3EncodeContext *s)

{

    int ch, blk, blk1;



    for (ch = !s->cpl_on; ch <= s->fbw_channels; ch++) {

        uint8_t *exp_strategy = s->exp_strategy[ch];

        uint8_t *exp          = s->blocks[0].exp[ch];

        int exp_diff;



        /* estimate if the exponent variation & decide if they should be

           reused in the next frame */

        exp_strategy[0] = EXP_NEW;

        exp += AC3_MAX_COEFS;

        for (blk = 1; blk < AC3_MAX_BLOCKS; blk++, exp += AC3_MAX_COEFS) {

            if ((ch == CPL_CH && (!s->blocks[blk].cpl_in_use || !s->blocks[blk-1].cpl_in_use)) ||

                (ch  > CPL_CH && (s->blocks[blk].channel_in_cpl[ch] != s->blocks[blk-1].channel_in_cpl[ch]))) {

                exp_strategy[blk] = EXP_NEW;

                continue;

            }

            exp_diff = s->dsp.sad[0](NULL, exp, exp - AC3_MAX_COEFS, 16, 16);

            exp_strategy[blk] = EXP_REUSE;

            if (ch == CPL_CH && exp_diff > (EXP_DIFF_THRESHOLD * (s->blocks[blk].end_freq[ch] - s->start_freq[ch]) / AC3_MAX_COEFS))

                exp_strategy[blk] = EXP_NEW;

            else if (ch > CPL_CH && exp_diff > EXP_DIFF_THRESHOLD)

                exp_strategy[blk] = EXP_NEW;

        }



        /* now select the encoding strategy type : if exponents are often

           recoded, we use a coarse encoding */

        blk = 0;

        while (blk < AC3_MAX_BLOCKS) {

            blk1 = blk + 1;

            while (blk1 < AC3_MAX_BLOCKS && exp_strategy[blk1] == EXP_REUSE)

                blk1++;

            switch (blk1 - blk) {

            case 1:  exp_strategy[blk] = EXP_D45; break;

            case 2:

            case 3:  exp_strategy[blk] = EXP_D25; break;

            default: exp_strategy[blk] = EXP_D15; break;

            }

            blk = blk1;

        }

    }

    if (s->lfe_on) {

        ch = s->lfe_channel;

        s->exp_strategy[ch][0] = EXP_D15;

        for (blk = 1; blk < AC3_MAX_BLOCKS; blk++)

            s->exp_strategy[ch][blk] = EXP_REUSE;

    }

}

av_cold void ff_fft_init_arm(FFTContext *s)

{

    int cpu_flags = av_get_cpu_flags();



    if (have_vfp(cpu_flags) && !have_vfpv3(cpu_flags)) {

        s->fft_calc     = ff_fft_calc_vfp;

#if CONFIG_MDCT

        s->imdct_half   = ff_imdct_half_vfp;

#endif

    }



    if (have_neon(cpu_flags)) {

        s->fft_permute  = ff_fft_permute_neon;

        s->fft_calc     = ff_fft_calc_neon;

#if CONFIG_MDCT

        s->imdct_calc   = ff_imdct_calc_neon;

        s->imdct_half   = ff_imdct_half_neon;

        s->mdct_calc    = ff_mdct_calc_neon;

        s->mdct_permutation = FF_MDCT_PERM_INTERLEAVE;

#endif

    }

}

