static void floor_encode(venc_context_t * venc, floor_t * fc, PutBitContext * pb, int * posts, float * floor, int samples) {

    int range = 255 / fc->multiplier + 1;

    int coded[fc->values]; // first 2 values are unused

    int i, counter;

    int lx, ly;



    put_bits(pb, 1, 1); // non zero

    put_bits(pb, ilog(range - 1), posts[0]);

    put_bits(pb, ilog(range - 1), posts[1]);



    for (i = 2; i < fc->values; i++) {

        int predicted = render_point(fc->list[fc->list[i].low].x,

                                     posts[fc->list[i].low],

                                     fc->list[fc->list[i].high].x,

                                     posts[fc->list[i].high],

                                     fc->list[i].x);

        int highroom = range - predicted;

        int lowroom = predicted;

        int room = FFMIN(highroom, lowroom);

        if (predicted == posts[i]) {

            coded[i] = 0; // must be used later as flag!

            continue;

        } else {

            if (!coded[fc->list[i].low]) coded[fc->list[i].low] = -1;

            if (!coded[fc->list[i].high]) coded[fc->list[i].high] = -1;

        }

        if (posts[i] > predicted) {

            if (posts[i] - predicted > room) coded[i] = posts[i] - predicted + lowroom;

            else coded[i] = (posts[i] - predicted) << 1;

        } else {

            if (predicted - posts[i] > room) coded[i] = predicted - posts[i] + highroom - 1;

            else coded[i] = ((predicted - posts[i]) << 1) - 1;

        }

    }



    counter = 2;

    for (i = 0; i < fc->partitions; i++) {

        floor_class_t * c = &fc->classes[fc->partition_to_class[i]];

        int k, cval = 0, csub = 1<<c->subclass;

        if (c->subclass) {

            codebook_t * book = &venc->codebooks[c->masterbook];

            int cshift = 0;

            for (k = 0; k < c->dim; k++) {

                int l;

                for (l = 0; l < csub; l++) {

                    int maxval = 1;

                    if (c->books[l] != -1) maxval = venc->codebooks[c->books[l]].nentries;

                    // coded could be -1, but this still works, cause thats 0

                    if (coded[counter + k] < maxval) break;

                }

                assert(l != csub);

                cval |= l << cshift;

                cshift += c->subclass;

            }

            assert(cval < book->nentries);

            put_bits(pb, book->entries[cval].len, book->entries[cval].codeword);

        }

        for (k = 0; k < c->dim; k++) {

            int book = c->books[cval & (csub-1)];

            int entry = coded[counter++];

            cval >>= c->subclass;

            if (book == -1) continue;

            if (entry == -1) entry = 0;

            assert(entry < venc->codebooks[book].nentries);

            assert(entry >= 0);

            put_bits(pb, venc->codebooks[book].entries[entry].len, venc->codebooks[book].entries[entry].codeword);

        }

    }



    lx = 0;

    ly = posts[0] * fc->multiplier; // sorted 0 is still 0

    coded[0] = coded[1] = 1;

    for (i = 1; i < fc->values; i++) {

        int pos = fc->list[i].sort;

        if (coded[pos]) {

            render_line(lx, ly, fc->list[pos].x, posts[pos] * fc->multiplier, floor, samples);

            lx = fc->list[pos].x;

            ly = posts[pos] * fc->multiplier;

        }

        if (lx >= samples) break;

    }

    if (lx < samples) render_line(lx, ly, samples, ly, floor, samples);

}

Object *user_creatable_add_type(const char *type, const char *id,

                                const QDict *qdict,

                                Visitor *v, Error **errp)

{

    Object *obj;

    ObjectClass *klass;

    const QDictEntry *e;

    Error *local_err = NULL;



    klass = object_class_by_name(type);

    if (!klass) {

        error_setg(errp, "invalid object type: %s", type);

        return NULL;

    }



    if (!object_class_dynamic_cast(klass, TYPE_USER_CREATABLE)) {

        error_setg(errp, "object type '%s' isn't supported by object-add",

                   type);

        return NULL;

    }



    if (object_class_is_abstract(klass)) {

        error_setg(errp, "object type '%s' is abstract", type);

        return NULL;

    }



    obj = object_new(type);

    if (qdict) {

        for (e = qdict_first(qdict); e; e = qdict_next(qdict, e)) {

            object_property_set(obj, v, e->key, &local_err);

            if (local_err) {

                goto out;

            }

        }

    }



    object_property_add_child(object_get_objects_root(),

                              id, obj, &local_err);

    if (local_err) {

        goto out;

    }



    user_creatable_complete(obj, &local_err);

    if (local_err) {

        object_property_del(object_get_objects_root(),

                            id, &error_abort);

        goto out;

    }

out:

    if (local_err) {

        error_propagate(errp, local_err);

        object_unref(obj);

        return NULL;

    }

    return obj;

}

static int output_frame(H264Context *h, AVFrame *dst, H264Picture *srcp)

{

    AVFrame *src = srcp->f;

    int ret;



    if (src->format == AV_PIX_FMT_VIDEOTOOLBOX && src->buf[0]->size == 1)

        return AVERROR_EXTERNAL;



    ret = av_frame_ref(dst, src);

    if (ret < 0)

        return ret;



    av_dict_set(&dst->metadata, "stereo_mode", ff_h264_sei_stereo_mode(&h->sei.frame_packing), 0);



    if (srcp->sei_recovery_frame_cnt == 0)

        dst->key_frame = 1;



    return 0;

}

static int decode_subframe_fixed(FLACContext *s, int32_t *decoded,

                                 int pred_order, int bps)

{

    const int blocksize = s->blocksize;

    unsigned av_uninit(a), av_uninit(b), av_uninit(c), av_uninit(d);

    int i;

    int ret;



    /* warm up samples */

    for (i = 0; i < pred_order; i++) {

        decoded[i] = get_sbits_long(&s->gb, bps);

    }



    if ((ret = decode_residuals(s, decoded, pred_order)) < 0)

        return ret;



    if (pred_order > 0)

        a = decoded[pred_order-1];

    if (pred_order > 1)

        b = a - decoded[pred_order-2];

    if (pred_order > 2)

        c = b - decoded[pred_order-2] + decoded[pred_order-3];

    if (pred_order > 3)

        d = c - decoded[pred_order-2] + 2*decoded[pred_order-3] - decoded[pred_order-4];



    switch (pred_order) {

    case 0:

        break;

    case 1:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += decoded[i];

        break;

    case 2:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += decoded[i];

        break;

    case 3:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += c += decoded[i];

        break;

    case 4:

        for (i = pred_order; i < blocksize; i++)

            decoded[i] = a += b += c += d += decoded[i];

        break;

    default:

        av_log(s->avctx, AV_LOG_ERROR, "illegal pred order %d\n", pred_order);

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

void nbd_client_session_attach_aio_context(NbdClientSession *client,

                                           AioContext *new_context)

{

    aio_set_fd_handler(new_context, client->sock,

                       nbd_reply_ready, NULL, client);

}

int qio_channel_readv_all(QIOChannel *ioc,

                          const struct iovec *iov,

                          size_t niov,

                          Error **errp)

{

    int ret = -1;

    struct iovec *local_iov = g_new(struct iovec, niov);

    struct iovec *local_iov_head = local_iov;

    unsigned int nlocal_iov = niov;



    nlocal_iov = iov_copy(local_iov, nlocal_iov,

                          iov, niov,

                          0, iov_size(iov, niov));



    while (nlocal_iov > 0) {

        ssize_t len;

        len = qio_channel_readv(ioc, local_iov, nlocal_iov, errp);

        if (len == QIO_CHANNEL_ERR_BLOCK) {

            qio_channel_wait(ioc, G_IO_IN);

            continue;

        } else if (len < 0) {

            goto cleanup;

        } else if (len == 0) {

            error_setg(errp,

                       "Unexpected end-of-file before all bytes were read");

            goto cleanup;

        }



        iov_discard_front(&local_iov, &nlocal_iov, len);

    }



    ret = 0;



 cleanup:

    g_free(local_iov_head);

    return ret;

}

