static uint64_t get_cluster_offset(BlockDriverState *bs,

                                   uint64_t offset, int allocate)

{

    BDRVVmdkState *s = bs->opaque;

    unsigned int l1_index, l2_offset, l2_index;

    int min_index, i, j;

    uint32_t min_count, *l2_table, tmp;

    uint64_t cluster_offset;



    l1_index = (offset >> 9) / s->l1_entry_sectors;

    if (l1_index >= s->l1_size)

        return 0;

    l2_offset = s->l1_table[l1_index];

    if (!l2_offset)

        return 0;

    for(i = 0; i < L2_CACHE_SIZE; i++) {

        if (l2_offset == s->l2_cache_offsets[i]) {

            /* increment the hit count */

            if (++s->l2_cache_counts[i] == 0xffffffff) {

                for(j = 0; j < L2_CACHE_SIZE; j++) {

                    s->l2_cache_counts[j] >>= 1;

                }

            }

            l2_table = s->l2_cache + (i * s->l2_size);

            goto found;

        }

    }

    /* not found: load a new entry in the least used one */

    min_index = 0;

    min_count = 0xffffffff;

    for(i = 0; i < L2_CACHE_SIZE; i++) {

        if (s->l2_cache_counts[i] < min_count) {

            min_count = s->l2_cache_counts[i];

            min_index = i;

        }

    }

    l2_table = s->l2_cache + (min_index * s->l2_size);

    if (bdrv_pread(s->hd, (int64_t)l2_offset * 512, l2_table, s->l2_size * sizeof(uint32_t)) != 

                                                                        s->l2_size * sizeof(uint32_t))

        return 0;



    s->l2_cache_offsets[min_index] = l2_offset;

    s->l2_cache_counts[min_index] = 1;

 found:

    l2_index = ((offset >> 9) / s->cluster_sectors) % s->l2_size;

    cluster_offset = le32_to_cpu(l2_table[l2_index]);

    if (!cluster_offset) {

        struct stat file_buf;



        if (!allocate)

            return 0;

        stat(s->hd->filename, &file_buf);

        cluster_offset = file_buf.st_size;

        bdrv_truncate(s->hd, cluster_offset + (s->cluster_sectors << 9));



        cluster_offset >>= 9;

        /* update L2 table */

        tmp = cpu_to_le32(cluster_offset);

        l2_table[l2_index] = tmp;

        if (bdrv_pwrite(s->hd, ((int64_t)l2_offset * 512) + (l2_index * sizeof(tmp)), 

                        &tmp, sizeof(tmp)) != sizeof(tmp))

            return 0;

        /* update backup L2 table */

        if (s->l1_backup_table_offset != 0) {

            l2_offset = s->l1_backup_table[l1_index];

            if (bdrv_pwrite(s->hd, ((int64_t)l2_offset * 512) + (l2_index * sizeof(tmp)), 

                            &tmp, sizeof(tmp)) != sizeof(tmp))

                return 0;

        }



        if (get_whole_cluster(bs, cluster_offset, offset, allocate) == -1)

            return 0;

    }

    cluster_offset <<= 9;

    return cluster_offset;

}

static int binkb_decode_plane(BinkContext *c, AVFrame *frame, BitstreamContext *bc,

                              int plane_idx, int is_key, int is_chroma)

{

    int blk, ret;

    int i, j, bx, by;

    uint8_t *dst, *ref, *ref_start, *ref_end;

    int v, col[2];

    const uint8_t *scan;

    int xoff, yoff;

    LOCAL_ALIGNED_16(int16_t, block, [64]);

    LOCAL_ALIGNED_16(int32_t, dctblock, [64]);

    int coordmap[64];

    int ybias = is_key ? -15 : 0;

    int qp;



    const int stride = frame->linesize[plane_idx];

    int bw = is_chroma ? (c->avctx->width  + 15) >> 4 : (c->avctx->width  + 7) >> 3;

    int bh = is_chroma ? (c->avctx->height + 15) >> 4 : (c->avctx->height + 7) >> 3;



    binkb_init_bundles(c);

    ref_start = frame->data[plane_idx];

    ref_end   = frame->data[plane_idx] + (bh * frame->linesize[plane_idx] + bw) * 8;



    for (i = 0; i < 64; i++)

        coordmap[i] = (i & 7) + (i >> 3) * stride;



    for (by = 0; by < bh; by++) {

        for (i = 0; i < BINKB_NB_SRC; i++) {

            if ((ret = binkb_read_bundle(c, bc, i)) < 0)

                return ret;

        }



        dst  = frame->data[plane_idx]  + 8*by*stride;

        for (bx = 0; bx < bw; bx++, dst += 8) {

            blk = binkb_get_value(c, BINKB_SRC_BLOCK_TYPES);

            switch (blk) {

            case 0:

                break;

            case 1:

                scan = bink_patterns[bitstream_read(bc, 4)];

                i = 0;

                do {

                    int mode = bitstream_read_bit(bc);

                    int run  = bitstream_read(bc, binkb_runbits[i]) + 1;



                    i += run;

                    if (i > 64) {

                        av_log(c->avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                        return AVERROR_INVALIDDATA;

                    }

                    if (mode) {

                        v = binkb_get_value(c, BINKB_SRC_COLORS);

                        for (j = 0; j < run; j++)

                            dst[coordmap[*scan++]] = v;

                    } else {

                        for (j = 0; j < run; j++)

                            dst[coordmap[*scan++]] = binkb_get_value(c, BINKB_SRC_COLORS);

                    }

                } while (i < 63);

                if (i == 63)

                    dst[coordmap[*scan++]] = binkb_get_value(c, BINKB_SRC_COLORS);

                break;

            case 2:

                memset(dctblock, 0, sizeof(*dctblock) * 64);

                dctblock[0] = binkb_get_value(c, BINKB_SRC_INTRA_DC);

                qp = binkb_get_value(c, BINKB_SRC_INTRA_Q);

                read_dct_coeffs(bc, dctblock, bink_scan, binkb_intra_quant, qp);

                c->binkdsp.idct_put(dst, stride, dctblock);

                break;

            case 3:

                xoff = binkb_get_value(c, BINKB_SRC_X_OFF);

                yoff = binkb_get_value(c, BINKB_SRC_Y_OFF) + ybias;

                ref = dst + xoff + yoff * stride;

                if (ref < ref_start || ref + 8*stride > ref_end) {

                    av_log(c->avctx, AV_LOG_WARNING, "Reference block is out of bounds\n");

                } else if (ref + 8*stride < dst || ref >= dst + 8*stride) {

                    c->hdsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                } else {

                    put_pixels8x8_overlapped(dst, ref, stride);

                }

                c->bdsp.clear_block(block);

                v = binkb_get_value(c, BINKB_SRC_INTER_COEFS);

                read_residue(bc, block, v);

                c->binkdsp.add_pixels8(dst, block, stride);

                break;

            case 4:

                xoff = binkb_get_value(c, BINKB_SRC_X_OFF);

                yoff = binkb_get_value(c, BINKB_SRC_Y_OFF) + ybias;

                ref = dst + xoff + yoff * stride;

                if (ref < ref_start || ref + 8 * stride > ref_end) {

                    av_log(c->avctx, AV_LOG_WARNING, "Reference block is out of bounds\n");

                } else if (ref + 8*stride < dst || ref >= dst + 8*stride) {

                    c->hdsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                } else {

                    put_pixels8x8_overlapped(dst, ref, stride);

                }

                memset(dctblock, 0, sizeof(*dctblock) * 64);

                dctblock[0] = binkb_get_value(c, BINKB_SRC_INTER_DC);

                qp = binkb_get_value(c, BINKB_SRC_INTER_Q);

                read_dct_coeffs(bc, dctblock, bink_scan, binkb_inter_quant, qp);

                c->binkdsp.idct_add(dst, stride, dctblock);

                break;

            case 5:

                v = binkb_get_value(c, BINKB_SRC_COLORS);

                c->bdsp.fill_block_tab[1](dst, v, stride, 8);

                break;

            case 6:

                for (i = 0; i < 2; i++)

                    col[i] = binkb_get_value(c, BINKB_SRC_COLORS);

                for (i = 0; i < 8; i++) {

                    v = binkb_get_value(c, BINKB_SRC_PATTERN);

                    for (j = 0; j < 8; j++, v >>= 1)

                        dst[i*stride + j] = col[v & 1];

                }

                break;

            case 7:

                xoff = binkb_get_value(c, BINKB_SRC_X_OFF);

                yoff = binkb_get_value(c, BINKB_SRC_Y_OFF) + ybias;

                ref = dst + xoff + yoff * stride;

                if (ref < ref_start || ref + 8 * stride > ref_end) {

                    av_log(c->avctx, AV_LOG_WARNING, "Reference block is out of bounds\n");

                } else if (ref + 8*stride < dst || ref >= dst + 8*stride) {

                    c->hdsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                } else {

                    put_pixels8x8_overlapped(dst, ref, stride);

                }

                break;

            case 8:

                for (i = 0; i < 8; i++)

                    memcpy(dst + i*stride, c->bundle[BINKB_SRC_COLORS].cur_ptr + i*8, 8);

                c->bundle[BINKB_SRC_COLORS].cur_ptr += 64;

                break;

            default:

                av_log(c->avctx, AV_LOG_ERROR, "Unknown block type %d\n", blk);

                return AVERROR_INVALIDDATA;

            }

        }

    }

    if (bitstream_tell(bc) & 0x1F) // next plane data starts at 32-bit boundary

        bitstream_skip(bc, 32 - (bitstream_tell(bc) & 0x1F));



    return 0;

}

void HELPER(ucf64_cmpd)(float64 a, float64 b, uint32_t c, CPUUniCore32State *env)

{

    int flag;

    flag = float64_compare_quiet(a, b, &env->ucf64.fp_status);

    env->CF = 0;

    switch (c & 0x7) {

    case 0: /* F */

        break;

    case 1: /* UN */

        if (flag == 2) {

            env->CF = 1;

        }

        break;

    case 2: /* EQ */

        if (flag == 0) {

            env->CF = 1;

        }

        break;

    case 3: /* UEQ */

        if ((flag == 0) || (flag == 2)) {

            env->CF = 1;

        }

        break;

    case 4: /* OLT */

        if (flag == -1) {

            env->CF = 1;

        }

        break;

    case 5: /* ULT */

        if ((flag == -1) || (flag == 2)) {

            env->CF = 1;

        }

        break;

    case 6: /* OLE */

        if ((flag == -1) || (flag == 0)) {

            env->CF = 1;

        }

        break;

    case 7: /* ULE */

        if (flag != 1) {

            env->CF = 1;

        }

        break;

    }

    env->ucf64.xregs[UC32_UCF64_FPSCR] = (env->CF << 29)

                    | (env->ucf64.xregs[UC32_UCF64_FPSCR] & 0x0fffffff);

}

static inline void FUNC(idctRowCondDC_extrashift)(int16_t *row, int extra_shift)

#else

static inline void FUNC(idctRowCondDC)(int16_t *row, int extra_shift)

#endif

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



#if HAVE_FAST_64BIT

#define ROW0_MASK (0xffffLL << 48 * HAVE_BIGENDIAN)

    if (((AV_RN64A(row) & ~ROW0_MASK) | AV_RN64A(row+4)) == 0) {

        uint64_t temp;

        if (DC_SHIFT - extra_shift >= 0) {

            temp = (row[0] * (1 << (DC_SHIFT - extra_shift))) & 0xffff;

        } else {

            temp = ((row[0] + (1<<(extra_shift - DC_SHIFT-1))) >> (extra_shift - DC_SHIFT)) & 0xffff;

        }

        temp += temp * (1 << 16);

        temp += temp * ((uint64_t) 1 << 32);

        AV_WN64A(row, temp);

        AV_WN64A(row + 4, temp);

        return;

    }

#else

    if (!(AV_RN32A(row+2) |

          AV_RN32A(row+4) |

          AV_RN32A(row+6) |

          row[1])) {

        uint32_t temp;

        if (DC_SHIFT - extra_shift >= 0) {

            temp = (row[0] * (1 << (DC_SHIFT - extra_shift))) & 0xffff;

        } else {

            temp = ((row[0] + (1<<(extra_shift - DC_SHIFT-1))) >> (extra_shift - DC_SHIFT)) & 0xffff;

        }

        temp += temp * (1 << 16);

        AV_WN32A(row, temp);

        AV_WN32A(row+2, temp);

        AV_WN32A(row+4, temp);

        AV_WN32A(row+6, temp);

        return;

    }

#endif



    a0 = (W4 * row[0]) + (1 << (ROW_SHIFT + extra_shift - 1));

    a1 = a0;

    a2 = a0;

    a3 = a0;



    a0 += W2 * row[2];

    a1 += W6 * row[2];

    a2 -= W6 * row[2];

    a3 -= W2 * row[2];



    b0 = MUL(W1, row[1]);

    MAC(b0, W3, row[3]);

    b1 = MUL(W3, row[1]);

    MAC(b1, -W7, row[3]);

    b2 = MUL(W5, row[1]);

    MAC(b2, -W1, row[3]);

    b3 = MUL(W7, row[1]);

    MAC(b3, -W5, row[3]);



    if (AV_RN64A(row + 4)) {

        a0 +=   W4*row[4] + W6*row[6];

        a1 += - W4*row[4] - W2*row[6];

        a2 += - W4*row[4] + W2*row[6];

        a3 +=   W4*row[4] - W6*row[6];



        MAC(b0,  W5, row[5]);

        MAC(b0,  W7, row[7]);



        MAC(b1, -W1, row[5]);

        MAC(b1, -W5, row[7]);



        MAC(b2,  W7, row[5]);

        MAC(b2,  W3, row[7]);



        MAC(b3,  W3, row[5]);

        MAC(b3, -W1, row[7]);

    }



    row[0] = (a0 + b0) >> (ROW_SHIFT + extra_shift);

    row[7] = (a0 - b0) >> (ROW_SHIFT + extra_shift);

    row[1] = (a1 + b1) >> (ROW_SHIFT + extra_shift);

    row[6] = (a1 - b1) >> (ROW_SHIFT + extra_shift);

    row[2] = (a2 + b2) >> (ROW_SHIFT + extra_shift);

    row[5] = (a2 - b2) >> (ROW_SHIFT + extra_shift);

    row[3] = (a3 + b3) >> (ROW_SHIFT + extra_shift);

    row[4] = (a3 - b3) >> (ROW_SHIFT + extra_shift);

}

