static void mainstone_common_init(MemoryRegion *address_space_mem,

                                  MachineState *machine,

                                  enum mainstone_model_e model, int arm_id)

{

    uint32_t sector_len = 256 * 1024;

    hwaddr mainstone_flash_base[] = { MST_FLASH_0, MST_FLASH_1 };

    PXA2xxState *mpu;

    DeviceState *mst_irq;

    DriveInfo *dinfo;

    int i;

    int be;

    MemoryRegion *rom = g_new(MemoryRegion, 1);

    const char *cpu_model = machine->cpu_model;



    if (!cpu_model)

        cpu_model = "pxa270-c5";



    /* Setup CPU & memory */

    mpu = pxa270_init(address_space_mem, mainstone_binfo.ram_size, cpu_model);

    memory_region_init_ram(rom, NULL, "mainstone.rom", MAINSTONE_ROM,

                           &error_abort);

    vmstate_register_ram_global(rom);

    memory_region_set_readonly(rom, true);

    memory_region_add_subregion(address_space_mem, 0, rom);



#ifdef TARGET_WORDS_BIGENDIAN

    be = 1;

#else

    be = 0;

#endif

    /* There are two 32MiB flash devices on the board */

    for (i = 0; i < 2; i ++) {

        dinfo = drive_get(IF_PFLASH, 0, i);

        if (!dinfo) {

            if (qtest_enabled()) {

                break;

            }

            fprintf(stderr, "Two flash images must be given with the "

                    "'pflash' parameter\n");

            exit(1);

        }



        if (!pflash_cfi01_register(mainstone_flash_base[i], NULL,

                                   i ? "mainstone.flash1" : "mainstone.flash0",

                                   MAINSTONE_FLASH,

                                   blk_bs(blk_by_legacy_dinfo(dinfo)),

                                   sector_len, MAINSTONE_FLASH / sector_len,

                                   4, 0, 0, 0, 0, be)) {

            fprintf(stderr, "qemu: Error registering flash memory.\n");

            exit(1);

        }

    }



    mst_irq = sysbus_create_simple("mainstone-fpga", MST_FPGA_PHYS,

                    qdev_get_gpio_in(mpu->gpio, 0));



    /* setup keypad */

    pxa27x_register_keypad(mpu->kp, map, 0xe0);



    /* MMC/SD host */

    pxa2xx_mmci_handlers(mpu->mmc, NULL, qdev_get_gpio_in(mst_irq, MMC_IRQ));



    pxa2xx_pcmcia_set_irq_cb(mpu->pcmcia[0],

            qdev_get_gpio_in(mst_irq, S0_IRQ),

            qdev_get_gpio_in(mst_irq, S0_CD_IRQ));

    pxa2xx_pcmcia_set_irq_cb(mpu->pcmcia[1],

            qdev_get_gpio_in(mst_irq, S1_IRQ),

            qdev_get_gpio_in(mst_irq, S1_CD_IRQ));



    smc91c111_init(&nd_table[0], MST_ETH_PHYS,

                    qdev_get_gpio_in(mst_irq, ETHERNET_IRQ));



    mainstone_binfo.kernel_filename = machine->kernel_filename;

    mainstone_binfo.kernel_cmdline = machine->kernel_cmdline;

    mainstone_binfo.initrd_filename = machine->initrd_filename;

    mainstone_binfo.board_id = arm_id;

    arm_load_kernel(mpu->cpu, &mainstone_binfo);

}

static int fill_psinfo(struct target_elf_prpsinfo *psinfo, const TaskState *ts)

{

    char *filename, *base_filename;

    unsigned int i, len;



    (void) memset(psinfo, 0, sizeof (*psinfo));



    len = ts->info->arg_end - ts->info->arg_start;

    if (len >= ELF_PRARGSZ)

        len = ELF_PRARGSZ - 1;

    if (copy_from_user(&psinfo->pr_psargs, ts->info->arg_start, len))

        return -EFAULT;

    for (i = 0; i < len; i++)

        if (psinfo->pr_psargs[i] == 0)

            psinfo->pr_psargs[i] = ' ';

    psinfo->pr_psargs[len] = 0;



    psinfo->pr_pid = getpid();

    psinfo->pr_ppid = getppid();

    psinfo->pr_pgrp = getpgrp();

    psinfo->pr_sid = getsid(0);

    psinfo->pr_uid = getuid();

    psinfo->pr_gid = getgid();



    filename = strdup(ts->bprm->filename);

    base_filename = strdup(basename(filename));

    (void) strncpy(psinfo->pr_fname, base_filename,

                   sizeof(psinfo->pr_fname));

    free(base_filename);

    free(filename);



#ifdef BSWAP_NEEDED

    bswap_psinfo(psinfo);

#endif

    return (0);

}

static void i82374_isa_realize(DeviceState *dev, Error **errp)

{

    ISAi82374State *isa = I82374(dev);

    I82374State *s = &isa->state;

    PortioList *port_list = g_new(PortioList, 1);



    portio_list_init(port_list, OBJECT(isa), i82374_portio_list, s, "i82374");

    portio_list_add(port_list, isa_address_space_io(&isa->parent_obj),

                    isa->iobase);



    i82374_realize(s, errp);



    qdev_init_gpio_out(dev, &s->out, 1);

}

static void bt_submit_sco(struct HCIInfo *info,

                const uint8_t *data, int length)

{

    struct bt_hci_s *hci = hci_from_info(info);

    uint16_t handle;

    int datalen;



    if (length < 3)

        return;



    handle = acl_handle((data[1] << 8) | data[0]);

    datalen = data[2];

    length -= 3;



    if (bt_hci_handle_bad(hci, handle)) {

        fprintf(stderr, "%s: invalid SCO handle %03x\n",

                        __FUNCTION__, handle);

        return;

    }



    if (datalen > length) {

        fprintf(stderr, "%s: SCO packet too short (%iB < %iB)\n",

                        __FUNCTION__, length, datalen);

        return;

    }



    /* TODO */



    /* TODO: increase counter and send EVT_NUM_COMP_PKTS if synchronous

     * Flow Control is enabled.

     * (See Read/Write_Synchronous_Flow_Control_Enable on page 513 and

     * page 514.)  */

}

static void xhci_kick_ep(XHCIState *xhci, unsigned int slotid,

                         unsigned int epid, unsigned int streamid)

{

    XHCIStreamContext *stctx;

    XHCIEPContext *epctx;

    XHCIRing *ring;

    USBEndpoint *ep = NULL;

    uint64_t mfindex;

    int length;

    int i;



    trace_usb_xhci_ep_kick(slotid, epid, streamid);

    assert(slotid >= 1 && slotid <= xhci->numslots);

    assert(epid >= 1 && epid <= 31);



    if (!xhci->slots[slotid-1].enabled) {

        DPRINTF("xhci: xhci_kick_ep for disabled slot %d\n", slotid);

        return;

    }

    epctx = xhci->slots[slotid-1].eps[epid-1];

    if (!epctx) {

        DPRINTF("xhci: xhci_kick_ep for disabled endpoint %d,%d\n",

                epid, slotid);

        return;

    }



    /* If the device has been detached, but the guest has not noticed this

       yet the 2 above checks will succeed, but we must NOT continue */

    if (!xhci->slots[slotid - 1].uport ||

        !xhci->slots[slotid - 1].uport->dev ||

        !xhci->slots[slotid - 1].uport->dev->attached) {

        return;

    }



    if (epctx->retry) {

        XHCITransfer *xfer = epctx->retry;



        trace_usb_xhci_xfer_retry(xfer);

        assert(xfer->running_retry);

        if (xfer->timed_xfer) {

            /* time to kick the transfer? */

            mfindex = xhci_mfindex_get(xhci);

            xhci_check_intr_iso_kick(xhci, xfer, epctx, mfindex);

            if (xfer->running_retry) {

                return;

            }

            xfer->timed_xfer = 0;

            xfer->running_retry = 1;

        }

        if (xfer->iso_xfer) {

            /* retry iso transfer */

            if (xhci_setup_packet(xfer) < 0) {

                return;

            }

            usb_handle_packet(xfer->packet.ep->dev, &xfer->packet);

            assert(xfer->packet.status != USB_RET_NAK);

            xhci_complete_packet(xfer);

        } else {

            /* retry nak'ed transfer */

            if (xhci_setup_packet(xfer) < 0) {

                return;

            }

            usb_handle_packet(xfer->packet.ep->dev, &xfer->packet);

            if (xfer->packet.status == USB_RET_NAK) {

                return;

            }

            xhci_complete_packet(xfer);

        }

        assert(!xfer->running_retry);

        epctx->retry = NULL;

    }



    if (epctx->state == EP_HALTED) {

        DPRINTF("xhci: ep halted, not running schedule\n");

        return;

    }





    if (epctx->nr_pstreams) {

        uint32_t err;

        stctx = xhci_find_stream(epctx, streamid, &err);

        if (stctx == NULL) {

            return;

        }

        ring = &stctx->ring;

        xhci_set_ep_state(xhci, epctx, stctx, EP_RUNNING);

    } else {

        ring = &epctx->ring;

        streamid = 0;

        xhci_set_ep_state(xhci, epctx, NULL, EP_RUNNING);

    }

    assert(ring->dequeue != 0);



    while (1) {

        XHCITransfer *xfer = &epctx->transfers[epctx->next_xfer];

        if (xfer->running_async || xfer->running_retry) {

            break;

        }

        length = xhci_ring_chain_length(xhci, ring);

        if (length < 0) {

            break;

        } else if (length == 0) {

            break;

        }

        if (xfer->trbs && xfer->trb_alloced < length) {

            xfer->trb_count = 0;

            xfer->trb_alloced = 0;

            g_free(xfer->trbs);

            xfer->trbs = NULL;

        }

        if (!xfer->trbs) {

            xfer->trbs = g_new(XHCITRB, length);

            xfer->trb_alloced = length;

        }

        xfer->trb_count = length;



        for (i = 0; i < length; i++) {

            TRBType type;

            type = xhci_ring_fetch(xhci, ring, &xfer->trbs[i], NULL);

            assert(type);

        }

        xfer->streamid = streamid;



        if (epid == 1) {

            if (xhci_fire_ctl_transfer(xhci, xfer) >= 0) {

                epctx->next_xfer = (epctx->next_xfer + 1) % TD_QUEUE;

            } else {

                DPRINTF("xhci: error firing CTL transfer\n");

            }

        } else {

            if (xhci_fire_transfer(xhci, xfer, epctx) >= 0) {

                epctx->next_xfer = (epctx->next_xfer + 1) % TD_QUEUE;

            } else {

                if (!xfer->timed_xfer) {

                    DPRINTF("xhci: error firing data transfer\n");

                }

            }

        }



        if (epctx->state == EP_HALTED) {

            break;

        }

        if (xfer->running_retry) {

            DPRINTF("xhci: xfer nacked, stopping schedule\n");

            epctx->retry = xfer;

            break;

        }

    }



    ep = xhci_epid_to_usbep(xhci, slotid, epid);

    if (ep) {

        usb_device_flush_ep_queue(ep->dev, ep);

    }

}

qio_channel_websock_extract_headers(char *buffer,

                                    QIOChannelWebsockHTTPHeader *hdrs,

                                    size_t nhdrsalloc,

                                    Error **errp)

{

    char *nl, *sep, *tmp;

    size_t nhdrs = 0;



    /*

     * First parse the HTTP protocol greeting of format:

     *

     *   $METHOD $PATH $VERSION

     *

     * e.g.

     *

     *   GET / HTTP/1.1

     */



    nl = strstr(buffer, QIO_CHANNEL_WEBSOCK_HANDSHAKE_DELIM);

    if (!nl) {

        error_setg(errp, "Missing HTTP header delimiter");

        return 0;

    }

    *nl = '\0';



    tmp = strchr(buffer, ' ');

    if (!tmp) {

        error_setg(errp, "Missing HTTP path delimiter");

        return 0;

    }

    *tmp = '\0';



    if (!g_str_equal(buffer, QIO_CHANNEL_WEBSOCK_HTTP_METHOD)) {

        error_setg(errp, "Unsupported HTTP method %s", buffer);

        return 0;

    }



    buffer = tmp + 1;

    tmp = strchr(buffer, ' ');

    if (!tmp) {

        error_setg(errp, "Missing HTTP version delimiter");

        return 0;

    }

    *tmp = '\0';



    if (!g_str_equal(buffer, QIO_CHANNEL_WEBSOCK_HTTP_PATH)) {

        error_setg(errp, "Unexpected HTTP path %s", buffer);

        return 0;

    }



    buffer = tmp + 1;



    if (!g_str_equal(buffer, QIO_CHANNEL_WEBSOCK_HTTP_VERSION)) {

        error_setg(errp, "Unsupported HTTP version %s", buffer);

        return 0;

    }



    buffer = nl + strlen(QIO_CHANNEL_WEBSOCK_HANDSHAKE_DELIM);



    /*

     * Now parse all the header fields of format

     *

     *   $NAME: $VALUE

     *

     * e.g.

     *

     *   Cache-control: no-cache

     */

    do {

        QIOChannelWebsockHTTPHeader *hdr;



        nl = strstr(buffer, QIO_CHANNEL_WEBSOCK_HANDSHAKE_DELIM);

        if (nl) {

            *nl = '\0';

        }



        sep = strchr(buffer, ':');

        if (!sep) {

            error_setg(errp, "Malformed HTTP header");

            return 0;

        }

        *sep = '\0';

        sep++;

        while (*sep == ' ') {

            sep++;

        }



        if (nhdrs >= nhdrsalloc) {

            error_setg(errp, "Too many HTTP headers");

            return 0;

        }



        hdr = &hdrs[nhdrs++];

        hdr->name = buffer;

        hdr->value = sep;



        /* Canonicalize header name for easier identification later */

        for (tmp = hdr->name; *tmp; tmp++) {

            *tmp = g_ascii_tolower(*tmp);

        }



        if (nl) {

            buffer = nl + strlen(QIO_CHANNEL_WEBSOCK_HANDSHAKE_DELIM);

        }

    } while (nl != NULL);



    return nhdrs;

}

static GenericList *next_list(Visitor *v, GenericList *tail, size_t size)

{

    StringInputVisitor *siv = to_siv(v);

    Range *r;



    if (!siv->ranges || !siv->cur_range) {

        return NULL;

    }



    r = siv->cur_range->data;

    if (!r) {

        return NULL;

    }



    if (siv->cur < r->begin || siv->cur >= r->end) {

        siv->cur_range = g_list_next(siv->cur_range);

        if (!siv->cur_range) {

            return NULL;

        }

        r = siv->cur_range->data;

        if (!r) {

            return NULL;

        }

        siv->cur = r->begin;

    }



    tail->next = g_malloc0(size);

    return tail->next;

}

int pit_get_initial_count(PITState *pit, int channel)

{

