static int nvdec_vc1_decode_slice(AVCodecContext *avctx, const uint8_t *buffer, uint32_t size)

{

    NVDECContext *ctx = avctx->internal->hwaccel_priv_data;

    void *tmp;



    tmp = av_fast_realloc(ctx->slice_offsets, &ctx->slice_offsets_allocated,

                          (ctx->nb_slices + 1) * sizeof(*ctx->slice_offsets));

    if (!tmp)

        return AVERROR(ENOMEM);

    ctx->slice_offsets = tmp;



    if (!ctx->bitstream)

        ctx->bitstream = (uint8_t*)buffer;



    ctx->slice_offsets[ctx->nb_slices] = buffer - ctx->bitstream;

    ctx->bitstream_len += size;

    ctx->nb_slices++;



    return 0;

}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {

    const uint64_t fuzz_tag = FUZZ_TAG;

    FuzzDataBuffer buffer;

    const uint8_t *last = data;

    const uint8_t *end = data + size;

    uint32_t it = 0;



    if (!c)

        c = AVCodecInitialize(FFMPEG_CODEC);  // Done once.



    AVCodecContext* ctx = avcodec_alloc_context3(NULL);

    if (!ctx)

        error("Failed memory allocation");



    ctx->max_pixels = 4096 * 4096; //To reduce false positive OOM and hangs



    int res = avcodec_open2(ctx, c, NULL);

    if (res < 0)

        return res;



    FDBCreate(&buffer);

    int got_frame;

    AVFrame *frame = av_frame_alloc();

    if (!frame)

        error("Failed memory allocation");



    // Read very simple container

    AVPacket avpkt;

    while (data < end && it < maxiteration) {

        // Search for the TAG

        while (data + sizeof(fuzz_tag) < end) {

            if (data[0] == (fuzz_tag & 0xFF) && *(const uint64_t *)(data) == fuzz_tag)

                break;

            data++;

        }

        if (data + sizeof(fuzz_tag) > end)

            data = end;



        FDBPrepare(&buffer, &avpkt, last, data - last);

        data += sizeof(fuzz_tag);

        last = data;



        // Iterate through all data

        while (avpkt.size > 0 && it++ < maxiteration) {

            av_frame_unref(frame);

            int ret = decode_handler(ctx, frame, &got_frame, &avpkt);



            if (it > 20)

                ctx->error_concealment = 0;



            if (ret <= 0 || ret > avpkt.size)

               break;



            avpkt.data += ret;

            avpkt.size -= ret;

        }

    }



    av_init_packet(&avpkt);

    avpkt.data = NULL;

    avpkt.size = 0;



    do {

        got_frame = 0;

        decode_handler(ctx, frame, &got_frame, &avpkt);

    } while (got_frame == 1 && it++ < maxiteration);



    av_frame_free(&frame);

    avcodec_free_context(&ctx);

    av_freep(&ctx);

    FDBDesroy(&buffer);

    return 0;

}

static void show_packets(AVFormatContext *fmt_ctx)

{

    AVPacket pkt;



    av_init_packet(&pkt);



    while (!av_read_frame(fmt_ctx, &pkt))

        show_packet(fmt_ctx, &pkt);

}

static void vtd_context_device_invalidate(IntelIOMMUState *s,

                                          uint16_t source_id,

                                          uint16_t func_mask)

{

    uint16_t mask;

    VTDAddressSpace **pvtd_as;

    VTDAddressSpace *vtd_as;

    uint16_t devfn;

    uint16_t devfn_it;



    switch (func_mask & 3) {

    case 0:

        mask = 0;   /* No bits in the SID field masked */

        break;

    case 1:

        mask = 4;   /* Mask bit 2 in the SID field */

        break;

    case 2:

        mask = 6;   /* Mask bit 2:1 in the SID field */

        break;

    case 3:

        mask = 7;   /* Mask bit 2:0 in the SID field */

        break;

    }

    VTD_DPRINTF(INV, "device-selective invalidation source 0x%"PRIx16

                    " mask %"PRIu16, source_id, mask);

    pvtd_as = s->address_spaces[VTD_SID_TO_BUS(source_id)];

    if (pvtd_as) {

        devfn = VTD_SID_TO_DEVFN(source_id);

        for (devfn_it = 0; devfn_it < VTD_PCI_DEVFN_MAX; ++devfn_it) {

            vtd_as = pvtd_as[devfn_it];

            if (vtd_as && ((devfn_it & mask) == (devfn & mask))) {

                VTD_DPRINTF(INV, "invalidate context-cahce of devfn 0x%"PRIx16,

                            devfn_it);

                vtd_as->context_cache_entry.context_cache_gen = 0;

            }

        }

    }

}

static int load_dtb(target_phys_addr_t addr, const struct arm_boot_info *binfo)

{

#ifdef CONFIG_FDT

    uint32_t *mem_reg_property;

    uint32_t mem_reg_propsize;

    void *fdt = NULL;

    char *filename;

    int size, rc;

    uint32_t acells, scells, hival;



    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, binfo->dtb_filename);

    if (!filename) {

        fprintf(stderr, "Couldn't open dtb file %s\n", binfo->dtb_filename);

        return -1;

    }



    fdt = load_device_tree(filename, &size);

    if (!fdt) {

        fprintf(stderr, "Couldn't open dtb file %s\n", filename);

        g_free(filename);

        return -1;

    }

    g_free(filename);



    acells = qemu_devtree_getprop_cell(fdt, "/", "#address-cells");

    scells = qemu_devtree_getprop_cell(fdt, "/", "#size-cells");

    if (acells == 0 || scells == 0) {

        fprintf(stderr, "dtb file invalid (#address-cells or #size-cells 0)\n");

        return -1;

    }



    mem_reg_propsize = acells + scells;

    mem_reg_property = g_new0(uint32_t, mem_reg_propsize);

    mem_reg_property[acells - 1] = cpu_to_be32(binfo->loader_start);

    hival = cpu_to_be32(binfo->loader_start >> 32);

    if (acells > 1) {

        mem_reg_property[acells - 2] = hival;

    } else if (hival != 0) {

        fprintf(stderr, "qemu: dtb file not compatible with "

                "RAM start address > 4GB\n");

        exit(1);

    }

    mem_reg_property[acells + scells - 1] = cpu_to_be32(binfo->ram_size);

    hival = cpu_to_be32(binfo->ram_size >> 32);

    if (scells > 1) {

        mem_reg_property[acells + scells - 2] = hival;

    } else if (hival != 0) {

        fprintf(stderr, "qemu: dtb file not compatible with "

                "RAM size > 4GB\n");

        exit(1);

    }



    rc = qemu_devtree_setprop(fdt, "/memory", "reg", mem_reg_property,

                              mem_reg_propsize * sizeof(uint32_t));

    if (rc < 0) {

        fprintf(stderr, "couldn't set /memory/reg\n");

    }



    if (binfo->kernel_cmdline && *binfo->kernel_cmdline) {

        rc = qemu_devtree_setprop_string(fdt, "/chosen", "bootargs",

                                          binfo->kernel_cmdline);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/bootargs\n");

        }

    }



    if (binfo->initrd_size) {

        rc = qemu_devtree_setprop_cell(fdt, "/chosen", "linux,initrd-start",

                binfo->loader_start + INITRD_LOAD_ADDR);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/linux,initrd-start\n");

        }



        rc = qemu_devtree_setprop_cell(fdt, "/chosen", "linux,initrd-end",

                    binfo->loader_start + INITRD_LOAD_ADDR +

                    binfo->initrd_size);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/linux,initrd-end\n");

        }

    }



    cpu_physical_memory_write(addr, fdt, size);



    return 0;



#else

    fprintf(stderr, "Device tree requested, "

                "but qemu was compiled without fdt support\n");

    return -1;

#endif

}

static void rc4030_reset(DeviceState *dev)

{

    rc4030State *s = RC4030(dev);

    int i;



    s->config = 0x410; /* some boards seem to accept 0x104 too */

    s->revision = 1;

    s->invalid_address_register = 0;



    memset(s->dma_regs, 0, sizeof(s->dma_regs));

    rc4030_dma_tt_update(s, 0, 0);



    s->remote_failed_address = s->memory_failed_address = 0;

    s->cache_maint = 0;

    s->cache_ptag = s->cache_ltag = 0;

    s->cache_bmask = 0;



    s->memory_refresh_rate = 0x18186;

    s->nvram_protect = 7;

    for (i = 0; i < 15; i++)

        s->rem_speed[i] = 7;

    s->imr_jazz = 0x10; /* XXX: required by firmware, but why? */

    s->isr_jazz = 0;



    s->itr = 0;



    qemu_irq_lower(s->timer_irq);

    qemu_irq_lower(s->jazz_bus_irq);

}

static QObject *qmp_input_get_object(QmpInputVisitor *qiv,

                                     const char *name,

                                     bool consume, Error **errp)

{

    StackObject *tos;

    QObject *qobj;

    QObject *ret;



    if (QSLIST_EMPTY(&qiv->stack)) {

        /* Starting at root, name is ignored. */

        assert(qiv->root);

        return qiv->root;

    }



    /* We are in a container; find the next element. */

    tos = QSLIST_FIRST(&qiv->stack);

    qobj = tos->obj;

    assert(qobj);



    if (qobject_type(qobj) == QTYPE_QDICT) {

        assert(name);

        ret = qdict_get(qobject_to_qdict(qobj), name);

        if (tos->h && consume && ret) {

            bool removed = g_hash_table_remove(tos->h, name);

            assert(removed);

        }

        if (!ret) {

            error_setg(errp, QERR_MISSING_PARAMETER, name);

        }

    } else {

        assert(qobject_type(qobj) == QTYPE_QLIST);

        assert(!name);

        ret = qlist_entry_obj(tos->entry);

        assert(ret);

        if (consume) {

            tos->entry = qlist_next(tos->entry);

        }

    }



    return ret;

}

struct SwsContext *sws_getContext(int srcW, int srcH, int srcFormat,

                                  int dstW, int dstH, int dstFormat,

                                  int flags, SwsFilter *srcFilter,

                                  SwsFilter *dstFilter, double *param)

{

    struct SwsContext *ctx;



    ctx = av_malloc(sizeof(struct SwsContext));

    if (ctx)

        ctx->av_class = av_mallocz(sizeof(AVClass));

    if (!ctx || !ctx->av_class) {

        av_log(NULL, AV_LOG_ERROR, "Cannot allocate a resampling context!\n");



        return NULL;

    }



    if ((srcH != dstH) || (srcW != dstW)) {

        if ((srcFormat != PIX_FMT_YUV420P) || (dstFormat != PIX_FMT_YUV420P)) {

            av_log(NULL, AV_LOG_INFO, "PIX_FMT_YUV420P will be used as an intermediate format for rescaling\n");

        }

        ctx->resampling_ctx = img_resample_init(dstW, dstH, srcW, srcH);

    } else {

        ctx->resampling_ctx = av_malloc(sizeof(ImgReSampleContext));

        ctx->resampling_ctx->iheight = srcH;

        ctx->resampling_ctx->iwidth = srcW;

        ctx->resampling_ctx->oheight = dstH;

        ctx->resampling_ctx->owidth = dstW;

    }

    ctx->src_pix_fmt = srcFormat;

    ctx->dst_pix_fmt = dstFormat;



    return ctx;

}

long do_sigreturn(CPUS390XState *env)

{

    sigframe *frame;

    abi_ulong frame_addr = env->regs[15];

    target_sigset_t target_set;

    sigset_t set;



    trace_user_do_sigreturn(env, frame_addr);

    if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1)) {

        goto badframe;

    }

    __get_user(target_set.sig[0], &frame->sc.oldmask[0]);



    target_to_host_sigset_internal(&set, &target_set);

    set_sigmask(&set); /* ~_BLOCKABLE? */



    if (restore_sigregs(env, &frame->sregs)) {

        goto badframe;

    }



    unlock_user_struct(frame, frame_addr, 0);

    return -TARGET_QEMU_ESIGRETURN;



badframe:

    force_sig(TARGET_SIGSEGV);

    return 0;

}

static void test_qemu_strtoull_underflow(void)

{

    const char *str = "-99999999999999999999999999999999999999999999";

    char f = 'X';

    const char *endptr = &f;

    uint64_t res = 999;

    int err;



    err  = qemu_strtoull(str, &endptr, 0, &res);



    g_assert_cmpint(err, ==, -ERANGE);

    g_assert_cmpint(res, ==, -1);

    g_assert(endptr == str + strlen(str));

}

void do_unassigned_access(target_phys_addr_t addr, int is_write, int is_exec,

                          int is_asi, int size)

{

    CPUState *saved_env;

    /* XXX: hack to restore env in all cases, even if not called from

       generated code */

    saved_env = env;

    env = cpu_single_env;

    qemu_log("Unassigned " TARGET_FMT_plx " wr=%d exe=%d\n",

             addr, is_write, is_exec);

    if (!(env->sregs[SR_MSR] & MSR_EE)) {

        return;

    }



    if (is_exec) {

        if (!(env->pvr.regs[2] & PVR2_IOPB_BUS_EXC_MASK)) {

            env->sregs[SR_ESR] = ESR_EC_INSN_BUS;

            helper_raise_exception(EXCP_HW_EXCP);

        }

    } else {

        if (!(env->pvr.regs[2] & PVR2_DOPB_BUS_EXC_MASK)) {

            env->sregs[SR_ESR] = ESR_EC_DATA_BUS;

            helper_raise_exception(EXCP_HW_EXCP);

        }

    }

}

static int qcow2_create2(const char *filename, int64_t total_size,

                         const char *backing_file, const char *backing_format,

                         int flags, size_t cluster_size, PreallocMode prealloc,

                         QemuOpts *opts, int version, int refcount_order,

                         const char *encryptfmt, Error **errp)

{

    int cluster_bits;

    QDict *options;



    /* Calculate cluster_bits */

    cluster_bits = ctz32(cluster_size);

    if (cluster_bits < MIN_CLUSTER_BITS || cluster_bits > MAX_CLUSTER_BITS ||

        (1 << cluster_bits) != cluster_size)

    {

        error_setg(errp, "Cluster size must be a power of two between %d and "

                   "%dk", 1 << MIN_CLUSTER_BITS, 1 << (MAX_CLUSTER_BITS - 10));

        return -EINVAL;

    }



    /*

     * Open the image file and write a minimal qcow2 header.

     *

     * We keep things simple and start with a zero-sized image. We also

     * do without refcount blocks or a L1 table for now. We'll fix the

     * inconsistency later.

     *

     * We do need a refcount table because growing the refcount table means

     * allocating two new refcount blocks - the seconds of which would be at

     * 2 GB for 64k clusters, and we don't want to have a 2 GB initial file

     * size for any qcow2 image.

     */

    BlockBackend *blk;

    QCowHeader *header;

    uint64_t* refcount_table;

    Error *local_err = NULL;

    int ret;



    if (prealloc == PREALLOC_MODE_FULL || prealloc == PREALLOC_MODE_FALLOC) {

        int64_t prealloc_size =

            qcow2_calc_prealloc_size(total_size, cluster_size, refcount_order);

        qemu_opt_set_number(opts, BLOCK_OPT_SIZE, prealloc_size, &error_abort);

        qemu_opt_set(opts, BLOCK_OPT_PREALLOC, PreallocMode_lookup[prealloc],

                     &error_abort);

    }



    ret = bdrv_create_file(filename, opts, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        return ret;

    }



    blk = blk_new_open(filename, NULL, NULL,

                       BDRV_O_RDWR | BDRV_O_RESIZE | BDRV_O_PROTOCOL,

                       &local_err);

    if (blk == NULL) {

        error_propagate(errp, local_err);

        return -EIO;

    }



    blk_set_allow_write_beyond_eof(blk, true);



    /* Write the header */

    QEMU_BUILD_BUG_ON((1 << MIN_CLUSTER_BITS) < sizeof(*header));

    header = g_malloc0(cluster_size);

    *header = (QCowHeader) {

        .magic                      = cpu_to_be32(QCOW_MAGIC),

        .version                    = cpu_to_be32(version),

        .cluster_bits               = cpu_to_be32(cluster_bits),

        .size                       = cpu_to_be64(0),

        .l1_table_offset            = cpu_to_be64(0),

        .l1_size                    = cpu_to_be32(0),

        .refcount_table_offset      = cpu_to_be64(cluster_size),

        .refcount_table_clusters    = cpu_to_be32(1),

        .refcount_order             = cpu_to_be32(refcount_order),

        .header_length              = cpu_to_be32(sizeof(*header)),

    };



    /* We'll update this to correct value later */

    header->crypt_method = cpu_to_be32(QCOW_CRYPT_NONE);



    if (flags & BLOCK_FLAG_LAZY_REFCOUNTS) {

        header->compatible_features |=

            cpu_to_be64(QCOW2_COMPAT_LAZY_REFCOUNTS);

    }



    ret = blk_pwrite(blk, 0, header, cluster_size, 0);

    g_free(header);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not write qcow2 header");

        goto out;

    }



    /* Write a refcount table with one refcount block */

    refcount_table = g_malloc0(2 * cluster_size);

    refcount_table[0] = cpu_to_be64(2 * cluster_size);

    ret = blk_pwrite(blk, cluster_size, refcount_table, 2 * cluster_size, 0);

    g_free(refcount_table);



    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not write refcount table");

        goto out;

    }



    blk_unref(blk);

    blk = NULL;



    /*

     * And now open the image and make it consistent first (i.e. increase the

     * refcount of the cluster that is occupied by the header and the refcount

     * table)

     */

    options = qdict_new();

    qdict_put_str(options, "driver", "qcow2");

    blk = blk_new_open(filename, NULL, options,

                       BDRV_O_RDWR | BDRV_O_RESIZE | BDRV_O_NO_FLUSH,

                       &local_err);

    if (blk == NULL) {

        error_propagate(errp, local_err);

        ret = -EIO;

        goto out;

    }



    ret = qcow2_alloc_clusters(blk_bs(blk), 3 * cluster_size);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not allocate clusters for qcow2 "

                         "header and refcount table");

        goto out;



    } else if (ret != 0) {

        error_report("Huh, first cluster in empty image is already in use?");

        abort();

    }



    /* Create a full header (including things like feature table) */

    ret = qcow2_update_header(blk_bs(blk));

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Could not update qcow2 header");

        goto out;

    }



    /* Okay, now that we have a valid image, let's give it the right size */

    ret = blk_truncate(blk, total_size, errp);

    if (ret < 0) {

        error_prepend(errp, "Could not resize image: ");

        goto out;

    }



    /* Want a backing file? There you go.*/

    if (backing_file) {

        ret = bdrv_change_backing_file(blk_bs(blk), backing_file, backing_format);

        if (ret < 0) {

            error_setg_errno(errp, -ret, "Could not assign backing file '%s' "

                             "with format '%s'", backing_file, backing_format);

            goto out;

        }

    }



    /* Want encryption? There you go. */

    if (encryptfmt) {

        ret = qcow2_set_up_encryption(blk_bs(blk), encryptfmt, opts, errp);

        if (ret < 0) {

            goto out;

        }

    }



    /* And if we're supposed to preallocate metadata, do that now */

    if (prealloc != PREALLOC_MODE_OFF) {

        BDRVQcow2State *s = blk_bs(blk)->opaque;

        qemu_co_mutex_lock(&s->lock);

        ret = preallocate(blk_bs(blk));

        qemu_co_mutex_unlock(&s->lock);

        if (ret < 0) {

            error_setg_errno(errp, -ret, "Could not preallocate metadata");

            goto out;

        }

    }



    blk_unref(blk);

    blk = NULL;



    /* Reopen the image without BDRV_O_NO_FLUSH to flush it before returning.

     * Using BDRV_O_NO_IO, since encryption is now setup we don't want to

     * have to setup decryption context. We're not doing any I/O on the top

     * level BlockDriverState, only lower layers, where BDRV_O_NO_IO does

     * not have effect.

     */

    options = qdict_new();

    qdict_put_str(options, "driver", "qcow2");

    blk = blk_new_open(filename, NULL, options,

                       BDRV_O_RDWR | BDRV_O_NO_BACKING | BDRV_O_NO_IO,

                       &local_err);

    if (blk == NULL) {

        error_propagate(errp, local_err);

        ret = -EIO;

        goto out;

    }



    ret = 0;

out:

    if (blk) {

        blk_unref(blk);

    }

    return ret;

}

static bool block_is_active(void *opaque)

{

    return block_mig_state.blk_enable == 1;

}

static int sch_handle_start_func_passthrough(SubchDev *sch)

{



    PMCW *p = &sch->curr_status.pmcw;

    SCSW *s = &sch->curr_status.scsw;

    int ret;



    ORB *orb = &sch->orb;

    if (!(s->ctrl & SCSW_ACTL_SUSP)) {

        assert(orb != NULL);

        p->intparm = orb->intparm;

    }



    /*

     * Only support prefetch enable mode.

     * Only support 64bit addressing idal.

     */

    if (!(orb->ctrl0 & ORB_CTRL0_MASK_PFCH) ||

        !(orb->ctrl0 & ORB_CTRL0_MASK_C64)) {

        return -EINVAL;

    }



    ret = s390_ccw_cmd_request(orb, s, sch->driver_data);

    switch (ret) {

    /* Currently we don't update control block and just return the cc code. */

    case 0:

        break;

    case -EBUSY:

        break;

    case -ENODEV:

        break;

    case -EACCES:

        /* Let's reflect an inaccessible host device by cc 3. */

        ret = -ENODEV;

        break;

    default:

       /*

        * All other return codes will trigger a program check,

        * or set cc to 1.

        */

       break;

    };



    return ret;

}

static int rd_frame(CinepakEncContext *s, const AVFrame *frame, int isakeyframe, unsigned char *buf, int buf_size)

{

    int num_strips, strip, i, y, nexty, size, temp_size, best_size;

    AVPicture last_pict, pict, scratch_pict;

    int64_t best_score = 0, score, score_temp;

#ifdef CINEPAK_REPORT_SERR

    int64_t best_serr = 0, serr, serr_temp;

#endif



    int best_nstrips;



    if(s->pix_fmt == AV_PIX_FMT_RGB24) {

        int x;

// build a copy of the given frame in the correct colorspace

        for(y = 0; y < s->h; y += 2) {

            for(x = 0; x < s->w; x += 2) {

                uint8_t *ir[2]; int32_t r, g, b, rr, gg, bb;

                ir[0] = ((AVPicture*)frame)->data[0] + x*3 + y*((AVPicture*)frame)->linesize[0];

                ir[1] = ir[0] + ((AVPicture*)frame)->linesize[0];

                get_sub_picture(s, x, y, (AVPicture*)s->input_frame, &scratch_pict);

                r = g = b = 0;

                for(i=0; i<4; ++i) {

                    int i1, i2;

                    i1 = (i&1); i2 = (i>=2);

                    rr = ir[i2][i1*3+0];

                    gg = ir[i2][i1*3+1];

                    bb = ir[i2][i1*3+2];

                    r += rr; g += gg; b += bb;

// using fixed point arithmetic for portable repeatability, scaling by 2^23

// "Y"

//                    rr = 0.2857*rr + 0.5714*gg + 0.1429*bb;

                    rr = (2396625*rr + 4793251*gg + 1198732*bb) >> 23;

                    if(      rr <   0) rr =   0;

                    else if (rr > 255) rr = 255;

                    scratch_pict.data[0][i1 + i2*scratch_pict.linesize[0]] = rr;

                }

// let us scale down as late as possible

//                r /= 4; g /= 4; b /= 4;

// "U"

//                rr = -0.1429*r - 0.2857*g + 0.4286*b;

                rr = (-299683*r - 599156*g + 898839*b) >> 23;

                if(      rr < -128) rr = -128;

                else if (rr >  127) rr =  127;

                scratch_pict.data[1][0] = rr + 128; // quantize needs unsigned

// "V"

//                rr = 0.3571*r - 0.2857*g - 0.0714*b;

                rr = (748893*r - 599156*g - 149737*b) >> 23;

                if(      rr < -128) rr = -128;

                else if (rr >  127) rr =  127;

                scratch_pict.data[2][0] = rr + 128; // quantize needs unsigned

            }

        }

    }



    //would be nice but quite certainly incompatible with vintage players:

    // support encoding zero strips (meaning skip the whole frame)

    for(num_strips = s->min_strips; num_strips <= s->max_strips && num_strips <= s->h / MB_SIZE; num_strips++) {

        score = 0;

        size = 0;

#ifdef CINEPAK_REPORT_SERR

        serr = 0;

#endif



        for(y = 0, strip = 1; y < s->h; strip++, y = nexty) {

            int strip_height;



            nexty = strip * s->h / num_strips; // <= s->h

            //make nexty the next multiple of 4 if not already there

            if(nexty & 3)

                nexty += 4 - (nexty & 3);



            strip_height = nexty - y;

            if(strip_height <= 0) { // can this ever happen?

                av_log(s->avctx, AV_LOG_INFO, "skipping zero height strip %i of %i\n", strip, num_strips);

                continue;

            }



            if(s->pix_fmt == AV_PIX_FMT_RGB24)

                get_sub_picture(s, 0, y, (AVPicture*)s->input_frame,    &pict);

            else

                get_sub_picture(s, 0, y, (AVPicture*)frame,              &pict);

            get_sub_picture(s, 0, y, (AVPicture*)s->last_frame,    &last_pict);

            get_sub_picture(s, 0, y, (AVPicture*)s->scratch_frame, &scratch_pict);



            if((temp_size = rd_strip(s, y, strip_height, isakeyframe, &last_pict, &pict, &scratch_pict, s->frame_buf + size + CVID_HEADER_SIZE, &score_temp

#ifdef CINEPAK_REPORT_SERR

, &serr_temp

#endif

)) < 0)

                return temp_size;



            score += score_temp;

#ifdef CINEPAK_REPORT_SERR

            serr += serr_temp;

#endif

            size += temp_size;

            //av_log(s->avctx, AV_LOG_INFO, "strip %d, isakeyframe=%d", strip, isakeyframe);

            //av_log(s->avctx, AV_LOG_INFO, "\n");

        }



        if(best_score == 0 || score < best_score) {

            best_score = score;

#ifdef CINEPAK_REPORT_SERR

            best_serr = serr;

#endif

            best_size = size + write_cvid_header(s, s->frame_buf, num_strips, size, isakeyframe);

            //av_log(s->avctx, AV_LOG_INFO, "best number of strips so far: %2i, %12lli, %i B\n", num_strips, (long long int)score, best_size);

#ifdef CINEPAK_REPORT_SERR

            av_log(s->avctx, AV_LOG_INFO, "best number of strips so far: %2i, %12lli, %i B\n", num_strips, (long long int)serr, best_size);

#endif



            FFSWAP(AVFrame *, s->best_frame, s->scratch_frame);

            memcpy(buf, s->frame_buf, best_size);

            best_nstrips = num_strips;

        }

// avoid trying too many strip numbers without a real reason

// (this makes the processing of the very first frame faster)

        if(num_strips - best_nstrips > 4)

            break;

    }



// let the number of strips slowly adapt to the changes in the contents,

// compared to full bruteforcing every time this will occasionally lead

// to some r/d performance loss but makes encoding up to several times faster

    if(!s->strip_number_delta_range) {

        if(best_nstrips == s->max_strips) { // let us try to step up

            s->max_strips = best_nstrips + 1;

            if(s->max_strips >= s->max_max_strips)

                s->max_strips = s->max_max_strips;

        } else { // try to step down

            s->max_strips = best_nstrips;

        }

        s->min_strips = s->max_strips - 1;

        if(s->min_strips < s->min_min_strips)

            s->min_strips = s->min_min_strips;

    } else {

        s->max_strips = best_nstrips + s->strip_number_delta_range;

        if(s->max_strips >= s->max_max_strips)

            s->max_strips = s->max_max_strips;

        s->min_strips = best_nstrips - s->strip_number_delta_range;

        if(s->min_strips < s->min_min_strips)

            s->min_strips = s->min_min_strips;

    }



    return best_size;

}

void bdrv_img_create(const char *filename, const char *fmt,

                     const char *base_filename, const char *base_fmt,

                     char *options, uint64_t img_size, int flags, bool quiet,

                     Error **errp)

{

    QemuOptsList *create_opts = NULL;

    QemuOpts *opts = NULL;

    const char *backing_fmt, *backing_file;

    int64_t size;

    BlockDriver *drv, *proto_drv;

    Error *local_err = NULL;

    int ret = 0;



    /* Find driver and parse its options */

    drv = bdrv_find_format(fmt);

    if (!drv) {

        error_setg(errp, "Unknown file format '%s'", fmt);

        return;

    }



    proto_drv = bdrv_find_protocol(filename, true, errp);

    if (!proto_drv) {

        return;

    }



    if (!drv->create_opts) {

        error_setg(errp, "Format driver '%s' does not support image creation",

                   drv->format_name);

        return;

    }



    if (!proto_drv->create_opts) {

        error_setg(errp, "Protocol driver '%s' does not support image creation",

                   proto_drv->format_name);

        return;

    }



    create_opts = qemu_opts_append(create_opts, drv->create_opts);

    create_opts = qemu_opts_append(create_opts, proto_drv->create_opts);



    /* Create parameter list with default values */

    opts = qemu_opts_create(create_opts, NULL, 0, &error_abort);

    qemu_opt_set_number(opts, BLOCK_OPT_SIZE, img_size, &error_abort);



    /* Parse -o options */

    if (options) {

        qemu_opts_do_parse(opts, options, NULL, &local_err);

        if (local_err) {

            error_report_err(local_err);

            local_err = NULL;

            error_setg(errp, "Invalid options for file format '%s'", fmt);

            goto out;

        }

    }



    if (base_filename) {

        qemu_opt_set(opts, BLOCK_OPT_BACKING_FILE, base_filename, &local_err);

        if (local_err) {

            error_setg(errp, "Backing file not supported for file format '%s'",

                       fmt);

            goto out;

        }

    }



    if (base_fmt) {

        qemu_opt_set(opts, BLOCK_OPT_BACKING_FMT, base_fmt, &local_err);

        if (local_err) {

            error_setg(errp, "Backing file format not supported for file "

                             "format '%s'", fmt);

            goto out;

        }

    }



    backing_file = qemu_opt_get(opts, BLOCK_OPT_BACKING_FILE);

    if (backing_file) {

        if (!strcmp(filename, backing_file)) {

            error_setg(errp, "Error: Trying to create an image with the "

                             "same filename as the backing file");

            goto out;

        }

    }



    backing_fmt = qemu_opt_get(opts, BLOCK_OPT_BACKING_FMT);



    /* The size for the image must always be specified, unless we have a backing

     * file and we have not been forbidden from opening it. */

    size = qemu_opt_get_size(opts, BLOCK_OPT_SIZE, 0);

    if (backing_file && !(flags & BDRV_O_NO_BACKING)) {

        BlockDriverState *bs;

        char *full_backing = g_new0(char, PATH_MAX);

        int back_flags;

        QDict *backing_options = NULL;



        bdrv_get_full_backing_filename_from_filename(filename, backing_file,

                                                     full_backing, PATH_MAX,

                                                     &local_err);

        if (local_err) {

            g_free(full_backing);

            goto out;

        }



        /* backing files always opened read-only */

        back_flags = flags;

        back_flags &= ~(BDRV_O_RDWR | BDRV_O_SNAPSHOT | BDRV_O_NO_BACKING);



        if (backing_fmt) {

            backing_options = qdict_new();

            qdict_put_str(backing_options, "driver", backing_fmt);

        }



        bs = bdrv_open(full_backing, NULL, backing_options, back_flags,

                       &local_err);

        g_free(full_backing);

        if (!bs && size != -1) {

            /* Couldn't open BS, but we have a size, so it's nonfatal */

            warn_reportf_err(local_err,

                            "Could not verify backing image. "

                            "This may become an error in future versions.\n");

            local_err = NULL;

        } else if (!bs) {

            /* Couldn't open bs, do not have size */

            error_append_hint(&local_err,

                              "Could not open backing image to determine size.\n");

            goto out;

        } else {

            if (size == -1) {

                /* Opened BS, have no size */

                size = bdrv_getlength(bs);

                if (size < 0) {

                    error_setg_errno(errp, -size, "Could not get size of '%s'",

                                     backing_file);

                    bdrv_unref(bs);

                    goto out;

                }

                qemu_opt_set_number(opts, BLOCK_OPT_SIZE, size, &error_abort);

            }

            bdrv_unref(bs);

        }

    } /* (backing_file && !(flags & BDRV_O_NO_BACKING)) */



    if (size == -1) {

        error_setg(errp, "Image creation needs a size parameter");

        goto out;

    }



    if (!quiet) {

        printf("Formatting '%s', fmt=%s ", filename, fmt);

        qemu_opts_print(opts, " ");

        puts("");

    }



    ret = bdrv_create(drv, filename, opts, &local_err);



    if (ret == -EFBIG) {

        /* This is generally a better message than whatever the driver would

         * deliver (especially because of the cluster_size_hint), since that

         * is most probably not much different from "image too large". */

        const char *cluster_size_hint = "";

        if (qemu_opt_get_size(opts, BLOCK_OPT_CLUSTER_SIZE, 0)) {

            cluster_size_hint = " (try using a larger cluster size)";

        }

        error_setg(errp, "The image size is too large for file format '%s'"

                   "%s", fmt, cluster_size_hint);

        error_free(local_err);

        local_err = NULL;

    }



out:

    qemu_opts_del(opts);

    qemu_opts_free(create_opts);

    error_propagate(errp, local_err);

}

static void xics_reset(void *opaque)

{

    struct icp_state *icp = (struct icp_state *)opaque;

    struct ics_state *ics = icp->ics;

    int i;



    for (i = 0; i < icp->nr_servers; i++) {

        icp->ss[i].xirr = 0;

        icp->ss[i].pending_priority = 0;

        icp->ss[i].mfrr = 0xff;

        /* Make all outputs are deasserted */

        qemu_set_irq(icp->ss[i].output, 0);

    }



    for (i = 0; i < ics->nr_irqs; i++) {

        /* Reset everything *except* the type */

        ics->irqs[i].server = 0;

        ics->irqs[i].status = 0;

        ics->irqs[i].priority = 0xff;

        ics->irqs[i].saved_priority = 0xff;

    }

}

static void swap_channel_layouts_on_filter(AVFilterContext *filter)

{

    AVFilterLink *link = NULL;

    int i, j, k;



    for (i = 0; i < filter->nb_inputs; i++) {

        link = filter->inputs[i];



        if (link->type == AVMEDIA_TYPE_AUDIO &&

            link->out_channel_layouts->nb_channel_layouts == 1)

            break;

    }

    if (i == filter->nb_inputs)

        return;



    for (i = 0; i < filter->nb_outputs; i++) {

        AVFilterLink *outlink = filter->outputs[i];

        int best_idx, best_score = INT_MIN, best_count_diff = INT_MAX;



        if (outlink->type != AVMEDIA_TYPE_AUDIO ||

            outlink->in_channel_layouts->nb_channel_layouts < 2)

            continue;



        for (j = 0; j < outlink->in_channel_layouts->nb_channel_layouts; j++) {

            uint64_t  in_chlayout = link->out_channel_layouts->channel_layouts[0];

            uint64_t out_chlayout = outlink->in_channel_layouts->channel_layouts[j];

            int  in_channels      = av_get_channel_layout_nb_channels(in_chlayout);

            int out_channels      = av_get_channel_layout_nb_channels(out_chlayout);

            int count_diff        = out_channels - in_channels;

            int matched_channels, extra_channels;

            int score = 0;



            /* channel substitution */

            for (k = 0; k < FF_ARRAY_ELEMS(ch_subst); k++) {

                uint64_t cmp0 = ch_subst[k][0];

                uint64_t cmp1 = ch_subst[k][1];

                if (( in_chlayout & cmp0) && (!(out_chlayout & cmp0)) &&

                    (out_chlayout & cmp1) && (!( in_chlayout & cmp1))) {

                    in_chlayout  &= ~cmp0;

                    out_chlayout &= ~cmp1;

                    /* add score for channel match, minus a deduction for

                       having to do the substitution */

                    score += 10 * av_get_channel_layout_nb_channels(cmp1) - 2;

                }

            }



            /* no penalty for LFE channel mismatch */

            if ( (in_chlayout & AV_CH_LOW_FREQUENCY) &&

                (out_chlayout & AV_CH_LOW_FREQUENCY))

                score += 10;

            in_chlayout  &= ~AV_CH_LOW_FREQUENCY;

            out_chlayout &= ~AV_CH_LOW_FREQUENCY;



            matched_channels = av_get_channel_layout_nb_channels(in_chlayout &

                                                                 out_chlayout);

            extra_channels   = av_get_channel_layout_nb_channels(out_chlayout &

                                                                 (~in_chlayout));

            score += 10 * matched_channels - 5 * extra_channels;



            if (score > best_score ||

                (count_diff < best_count_diff && score == best_score)) {

                best_score = score;

                best_idx   = j;

                best_count_diff = count_diff;

            }

        }

        FFSWAP(uint64_t, outlink->in_channel_layouts->channel_layouts[0],

               outlink->in_channel_layouts->channel_layouts[best_idx]);

    }



}

void qemu_clock_warp(QEMUClockType type)

{

    int64_t deadline;



    /*

     * There are too many global variables to make the "warp" behavior

     * applicable to other clocks.  But a clock argument removes the

     * need for if statements all over the place.

     */

    if (type != QEMU_CLOCK_VIRTUAL || !use_icount) {

        return;

    }



    /*

     * If the CPUs have been sleeping, advance QEMU_CLOCK_VIRTUAL timer now.

     * This ensures that the deadline for the timer is computed correctly below.

     * This also makes sure that the insn counter is synchronized before the

     * CPU starts running, in case the CPU is woken by an event other than

     * the earliest QEMU_CLOCK_VIRTUAL timer.

     */

    icount_warp_rt(NULL);

    if (!all_cpu_threads_idle() || !qemu_clock_has_timers(QEMU_CLOCK_VIRTUAL)) {

        timer_del(icount_warp_timer);

        return;

    }



    if (qtest_enabled()) {

        /* When testing, qtest commands advance icount.  */

	return;

    }



    vm_clock_warp_start = qemu_clock_get_ns(QEMU_CLOCK_REALTIME);

    /* We want to use the earliest deadline from ALL vm_clocks */

    deadline = qemu_clock_deadline_ns_all(QEMU_CLOCK_VIRTUAL);



    /* Maintain prior (possibly buggy) behaviour where if no deadline

     * was set (as there is no QEMU_CLOCK_VIRTUAL timer) or it is more than

     * INT32_MAX nanoseconds ahead, we still use INT32_MAX

     * nanoseconds.

     */

    if ((deadline < 0) || (deadline > INT32_MAX)) {

        deadline = INT32_MAX;

    }



    if (deadline > 0) {

        /*

         * Ensure QEMU_CLOCK_VIRTUAL proceeds even when the virtual CPU goes to

         * sleep.  Otherwise, the CPU might be waiting for a future timer

         * interrupt to wake it up, but the interrupt never comes because

         * the vCPU isn't running any insns and thus doesn't advance the

         * QEMU_CLOCK_VIRTUAL.

         *

         * An extreme solution for this problem would be to never let VCPUs

         * sleep in icount mode if there is a pending QEMU_CLOCK_VIRTUAL

         * timer; rather time could just advance to the next QEMU_CLOCK_VIRTUAL

         * event.  Instead, we do stop VCPUs and only advance QEMU_CLOCK_VIRTUAL

         * after some e"real" time, (related to the time left until the next

         * event) has passed. The QEMU_CLOCK_REALTIME timer will do this.

         * This avoids that the warps are visible externally; for example,

         * you will not be sending network packets continuously instead of

         * every 100ms.

         */

        timer_mod(icount_warp_timer, vm_clock_warp_start + deadline);

    } else if (deadline == 0) {

        qemu_clock_notify(QEMU_CLOCK_VIRTUAL);

    }

}

static void xen_init_pv(QEMUMachineInitArgs *args)

{

    const char *cpu_model = args->cpu_model;

    const char *kernel_filename = args->kernel_filename;

    const char *kernel_cmdline = args->kernel_cmdline;

    const char *initrd_filename = args->initrd_filename;

    X86CPU *cpu;

    CPUState *cs;

    DriveInfo *dinfo;

    int i;



    /* Initialize a dummy CPU */

    if (cpu_model == NULL) {

#ifdef TARGET_X86_64

        cpu_model = "qemu64";

#else

        cpu_model = "qemu32";

#endif

    }

    cpu = cpu_x86_init(cpu_model);

    cs = CPU(cpu);

    cs->halted = 1;



    /* Initialize backend core & drivers */

    if (xen_be_init() != 0) {

        fprintf(stderr, "%s: xen backend core setup failed\n", __FUNCTION__);

        exit(1);

    }



    switch (xen_mode) {

    case XEN_ATTACH:

        /* nothing to do, xend handles everything */

        break;

    case XEN_CREATE:

        if (xen_domain_build_pv(kernel_filename, initrd_filename,

                                kernel_cmdline) < 0) {

            fprintf(stderr, "xen pv domain creation failed\n");

            exit(1);

        }

        break;

    case XEN_EMULATE:

        fprintf(stderr, "xen emulation not implemented (yet)\n");

        exit(1);

        break;

    }



    xen_be_register("console", &xen_console_ops);

    xen_be_register("vkbd", &xen_kbdmouse_ops);

    xen_be_register("vfb", &xen_framebuffer_ops);

    xen_be_register("qdisk", &xen_blkdev_ops);

    xen_be_register("qnic", &xen_netdev_ops);



    /* configure framebuffer */

    if (xenfb_enabled) {

        xen_config_dev_vfb(0, "vnc");

        xen_config_dev_vkbd(0);

    }



    /* configure disks */

    for (i = 0; i < 16; i++) {

        dinfo = drive_get(IF_XEN, 0, i);

        if (!dinfo)

            continue;

        xen_config_dev_blk(dinfo);

    }



    /* configure nics */

    for (i = 0; i < nb_nics; i++) {

        if (!nd_table[i].model || 0 != strcmp(nd_table[i].model, "xen"))

            continue;

        xen_config_dev_nic(nd_table + i);

    }



    /* config cleanup hook */

    atexit(xen_config_cleanup);



    /* setup framebuffer */

    xen_init_display(xen_domid);

}

void tlb_set_page(CPUState *env, target_ulong vaddr,

                  target_phys_addr_t paddr, int prot,

                  int mmu_idx, target_ulong size)

{

    PhysPageDesc *p;

    unsigned long pd;

    unsigned int index;

    target_ulong address;

    target_ulong code_address;

    unsigned long addend;

    CPUTLBEntry *te;

    CPUWatchpoint *wp;

    target_phys_addr_t iotlb;



    assert(size >= TARGET_PAGE_SIZE);

    if (size != TARGET_PAGE_SIZE) {

        tlb_add_large_page(env, vaddr, size);

    }

    p = phys_page_find(paddr >> TARGET_PAGE_BITS);

    if (!p) {

        pd = IO_MEM_UNASSIGNED;

    } else {

        pd = p->phys_offset;

    }

#if defined(DEBUG_TLB)

    printf("tlb_set_page: vaddr=" TARGET_FMT_lx " paddr=0x%08x prot=%x idx=%d smmu=%d pd=0x%08lx\n",

           vaddr, (int)paddr, prot, mmu_idx, is_softmmu, pd);

#endif



    address = vaddr;

    if ((pd & ~TARGET_PAGE_MASK) > IO_MEM_ROM && !(pd & IO_MEM_ROMD)) {

        /* IO memory case (romd handled later) */

        address |= TLB_MMIO;

    }

    addend = (unsigned long)qemu_get_ram_ptr(pd & TARGET_PAGE_MASK);

    if ((pd & ~TARGET_PAGE_MASK) <= IO_MEM_ROM) {

        /* Normal RAM.  */

        iotlb = pd & TARGET_PAGE_MASK;

        if ((pd & ~TARGET_PAGE_MASK) == IO_MEM_RAM)

            iotlb |= IO_MEM_NOTDIRTY;

        else

            iotlb |= IO_MEM_ROM;

    } else {

        /* IO handlers are currently passed a physical address.

           It would be nice to pass an offset from the base address

           of that region.  This would avoid having to special case RAM,

           and avoid full address decoding in every device.

           We can't use the high bits of pd for this because

           IO_MEM_ROMD uses these as a ram address.  */

        iotlb = (pd & ~TARGET_PAGE_MASK);

        if (p) {

            iotlb += p->region_offset;

        } else {

            iotlb += paddr;

        }

    }



    code_address = address;

    /* Make accesses to pages with watchpoints go via the

       watchpoint trap routines.  */

    QTAILQ_FOREACH(wp, &env->watchpoints, entry) {

        if (vaddr == (wp->vaddr & TARGET_PAGE_MASK)) {

            iotlb = io_mem_watch + paddr;

            /* TODO: The memory case can be optimized by not trapping

               reads of pages with a write breakpoint.  */

            address |= TLB_MMIO;

        }

    }



    index = (vaddr >> TARGET_PAGE_BITS) & (CPU_TLB_SIZE - 1);

    env->iotlb[mmu_idx][index] = iotlb - vaddr;

    te = &env->tlb_table[mmu_idx][index];

    te->addend = addend - vaddr;

    if (prot & PAGE_READ) {

        te->addr_read = address;

    } else {

        te->addr_read = -1;

    }



    if (prot & PAGE_EXEC) {

        te->addr_code = code_address;

    } else {

        te->addr_code = -1;

    }

    if (prot & PAGE_WRITE) {

        if ((pd & ~TARGET_PAGE_MASK) == IO_MEM_ROM ||

            (pd & IO_MEM_ROMD)) {

            /* Write access calls the I/O callback.  */

            te->addr_write = address | TLB_MMIO;

        } else if ((pd & ~TARGET_PAGE_MASK) == IO_MEM_RAM &&

                   !cpu_physical_memory_is_dirty(pd)) {

            te->addr_write = address | TLB_NOTDIRTY;

        } else {

            te->addr_write = address;

        }

    } else {

        te->addr_write = -1;

    }

}

void ppce500_init(MachineState *machine, PPCE500Params *params)

{

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    PCIBus *pci_bus;

    CPUPPCState *env = NULL;

    uint64_t loadaddr;

    hwaddr kernel_base = -1LL;

    int kernel_size = 0;

    hwaddr dt_base = 0;

    hwaddr initrd_base = 0;

    int initrd_size = 0;

    hwaddr cur_base = 0;

    char *filename;

    hwaddr bios_entry = 0;

    target_long bios_size;

    struct boot_info *boot_info;

    int dt_size;

    int i;

    /* irq num for pin INTA, INTB, INTC and INTD is 1, 2, 3 and

     * 4 respectively */

    unsigned int pci_irq_nrs[PCI_NUM_PINS] = {1, 2, 3, 4};

    qemu_irq **irqs, *mpic;

    DeviceState *dev;

    CPUPPCState *firstenv = NULL;

    MemoryRegion *ccsr_addr_space;

    SysBusDevice *s;

    PPCE500CCSRState *ccsr;



    /* Setup CPUs */

    if (machine->cpu_model == NULL) {

        machine->cpu_model = "e500v2_v30";

    }



    irqs = g_malloc0(smp_cpus * sizeof(qemu_irq *));

    irqs[0] = g_malloc0(smp_cpus * sizeof(qemu_irq) * OPENPIC_OUTPUT_NB);

    for (i = 0; i < smp_cpus; i++) {

        PowerPCCPU *cpu;

        CPUState *cs;

        qemu_irq *input;



        cpu = cpu_ppc_init(machine->cpu_model);

        if (cpu == NULL) {

            fprintf(stderr, "Unable to initialize CPU!\n");

            exit(1);

        }

        env = &cpu->env;

        cs = CPU(cpu);



        if (!firstenv) {

            firstenv = env;

        }



        irqs[i] = irqs[0] + (i * OPENPIC_OUTPUT_NB);

        input = (qemu_irq *)env->irq_inputs;

        irqs[i][OPENPIC_OUTPUT_INT] = input[PPCE500_INPUT_INT];

        irqs[i][OPENPIC_OUTPUT_CINT] = input[PPCE500_INPUT_CINT];

        env->spr_cb[SPR_BOOKE_PIR].default_value = cs->cpu_index = i;

        env->mpic_iack = params->ccsrbar_base +

                         MPC8544_MPIC_REGS_OFFSET + 0xa0;



        ppc_booke_timers_init(cpu, 400000000, PPC_TIMER_E500);



        /* Register reset handler */

        if (!i) {

            /* Primary CPU */

            struct boot_info *boot_info;

            boot_info = g_malloc0(sizeof(struct boot_info));

            qemu_register_reset(ppce500_cpu_reset, cpu);

            env->load_info = boot_info;

        } else {

            /* Secondary CPUs */

            qemu_register_reset(ppce500_cpu_reset_sec, cpu);

        }

    }



    env = firstenv;



    /* Fixup Memory size on a alignment boundary */

    ram_size &= ~(RAM_SIZES_ALIGN - 1);

    machine->ram_size = ram_size;



    /* Register Memory */

    memory_region_allocate_system_memory(ram, NULL, "mpc8544ds.ram", ram_size);

    memory_region_add_subregion(address_space_mem, 0, ram);



    dev = qdev_create(NULL, "e500-ccsr");

    object_property_add_child(qdev_get_machine(), "e500-ccsr",

                              OBJECT(dev), NULL);

    qdev_init_nofail(dev);

    ccsr = CCSR(dev);

    ccsr_addr_space = &ccsr->ccsr_space;

    memory_region_add_subregion(address_space_mem, params->ccsrbar_base,

                                ccsr_addr_space);



    mpic = ppce500_init_mpic(params, ccsr_addr_space, irqs);



    /* Serial */

    if (serial_hds[0]) {

        serial_mm_init(ccsr_addr_space, MPC8544_SERIAL0_REGS_OFFSET,

                       0, mpic[42], 399193,

                       serial_hds[0], DEVICE_BIG_ENDIAN);

    }



    if (serial_hds[1]) {

        serial_mm_init(ccsr_addr_space, MPC8544_SERIAL1_REGS_OFFSET,

                       0, mpic[42], 399193,

                       serial_hds[1], DEVICE_BIG_ENDIAN);

    }



    /* General Utility device */

    dev = qdev_create(NULL, "mpc8544-guts");

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);

    memory_region_add_subregion(ccsr_addr_space, MPC8544_UTIL_OFFSET,

                                sysbus_mmio_get_region(s, 0));



    /* PCI */

    dev = qdev_create(NULL, "e500-pcihost");

    qdev_prop_set_uint32(dev, "first_slot", params->pci_first_slot);

    qdev_prop_set_uint32(dev, "first_pin_irq", pci_irq_nrs[0]);

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);

    for (i = 0; i < PCI_NUM_PINS; i++) {

        sysbus_connect_irq(s, i, mpic[pci_irq_nrs[i]]);

    }



    memory_region_add_subregion(ccsr_addr_space, MPC8544_PCI_REGS_OFFSET,

                                sysbus_mmio_get_region(s, 0));



    pci_bus = (PCIBus *)qdev_get_child_bus(dev, "pci.0");

    if (!pci_bus)

        printf("couldn't create PCI controller!\n");



    if (pci_bus) {

        /* Register network interfaces. */

        for (i = 0; i < nb_nics; i++) {

            pci_nic_init_nofail(&nd_table[i], pci_bus, "virtio", NULL);

        }

    }



    /* Register spinning region */

    sysbus_create_simple("e500-spin", params->spin_base, NULL);



    if (cur_base < (32 * 1024 * 1024)) {

        /* u-boot occupies memory up to 32MB, so load blobs above */

        cur_base = (32 * 1024 * 1024);

    }



    if (params->has_mpc8xxx_gpio) {

        qemu_irq poweroff_irq;



        dev = qdev_create(NULL, "mpc8xxx_gpio");

        s = SYS_BUS_DEVICE(dev);

        qdev_init_nofail(dev);

        sysbus_connect_irq(s, 0, mpic[MPC8XXX_GPIO_IRQ]);

        memory_region_add_subregion(ccsr_addr_space, MPC8XXX_GPIO_OFFSET,

                                    sysbus_mmio_get_region(s, 0));



        /* Power Off GPIO at Pin 0 */

        poweroff_irq = qemu_allocate_irq(ppce500_power_off, NULL, 0);

        qdev_connect_gpio_out(dev, 0, poweroff_irq);

    }



    /* Platform Bus Device */

    if (params->has_platform_bus) {

        dev = qdev_create(NULL, TYPE_PLATFORM_BUS_DEVICE);

        dev->id = TYPE_PLATFORM_BUS_DEVICE;

        qdev_prop_set_uint32(dev, "num_irqs", params->platform_bus_num_irqs);

        qdev_prop_set_uint32(dev, "mmio_size", params->platform_bus_size);

        qdev_init_nofail(dev);

        s = SYS_BUS_DEVICE(dev);



        for (i = 0; i < params->platform_bus_num_irqs; i++) {

            int irqn = params->platform_bus_first_irq + i;

            sysbus_connect_irq(s, i, mpic[irqn]);

        }



        memory_region_add_subregion(address_space_mem,

                                    params->platform_bus_base,

                                    sysbus_mmio_get_region(s, 0));

    }



    /* Load kernel. */

    if (machine->kernel_filename) {

        kernel_base = cur_base;

        kernel_size = load_image_targphys(machine->kernel_filename,

                                          cur_base,

                                          ram_size - cur_base);

        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    machine->kernel_filename);

            exit(1);

        }



        cur_base += kernel_size;

    }



    /* Load initrd. */

    if (machine->initrd_filename) {

        initrd_base = (cur_base + INITRD_LOAD_PAD) & ~INITRD_PAD_MASK;

        initrd_size = load_image_targphys(machine->initrd_filename, initrd_base,

                                          ram_size - initrd_base);



        if (initrd_size < 0) {

            fprintf(stderr, "qemu: could not load initial ram disk '%s'\n",

                    machine->initrd_filename);

            exit(1);

        }



        cur_base = initrd_base + initrd_size;

    }



    /*

     * Smart firmware defaults ahead!

     *

     * We follow the following table to select which payload we execute.

     *

     *  -kernel | -bios | payload

     * ---------+-------+---------

     *     N    |   Y   | u-boot

     *     N    |   N   | u-boot

     *     Y    |   Y   | u-boot

     *     Y    |   N   | kernel

     *

     * This ensures backwards compatibility with how we used to expose

     * -kernel to users but allows them to run through u-boot as well.

     */

    if (bios_name == NULL) {

        if (machine->kernel_filename) {

            bios_name = machine->kernel_filename;

        } else {

            bios_name = "u-boot.e500";

        }

    }

    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);



    bios_size = load_elf(filename, NULL, NULL, &bios_entry, &loadaddr, NULL,

                         1, ELF_MACHINE, 0);

    if (bios_size < 0) {

        /*

         * Hrm. No ELF image? Try a uImage, maybe someone is giving us an

         * ePAPR compliant kernel

         */

        kernel_size = load_uimage(filename, &bios_entry, &loadaddr, NULL,

                                  NULL, NULL);

        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load firmware '%s'\n", filename);

            exit(1);

        }

    }



    /* Reserve space for dtb */

    dt_base = (loadaddr + bios_size + DTC_LOAD_PAD) & ~DTC_PAD_MASK;



    dt_size = ppce500_prep_device_tree(machine, params, dt_base,

                                       initrd_base, initrd_size,

                                       kernel_base, kernel_size);

    if (dt_size < 0) {

        fprintf(stderr, "couldn't load device tree\n");

        exit(1);

    }

    assert(dt_size < DTB_MAX_SIZE);



    boot_info = env->load_info;

    boot_info->entry = bios_entry;

    boot_info->dt_base = dt_base;

    boot_info->dt_size = dt_size;



    if (kvm_enabled()) {

        kvmppc_init();

    }

}

static int rm_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    RMDemuxContext *rm = s->priv_data;

    AVStream *st;

    int i, len, res, seq = 1;

    int64_t timestamp, pos;

    int flags;



    for (;;) {

        if (rm->audio_pkt_cnt) {

            // If there are queued audio packet return them first

            st = s->streams[rm->audio_stream_num];

            res = ff_rm_retrieve_cache(s, s->pb, st, st->priv_data, pkt);

            if(res < 0)

                return res;

            flags = 0;

        } else {

            if (rm->old_format) {

                RMStream *ast;



                st = s->streams[0];

                ast = st->priv_data;

                timestamp = AV_NOPTS_VALUE;

                len = !ast->audio_framesize ? RAW_PACKET_SIZE :

                    ast->coded_framesize * ast->sub_packet_h / 2;

                flags = (seq++ == 1) ? 2 : 0;

                pos = avio_tell(s->pb);

            } else {

                len=sync(s, &timestamp, &flags, &i, &pos);

                if (len > 0)

                    st = s->streams[i];

            }



            if(len<0 || url_feof(s->pb))

                return AVERROR(EIO);



            res = ff_rm_parse_packet (s, s->pb, st, st->priv_data, len, pkt,

                                      &seq, flags, timestamp);

            if((flags&2) && (seq&0x7F) == 1)

                av_add_index_entry(st, pos, timestamp, 0, 0, AVINDEX_KEYFRAME);

            if (res)

                continue;

        }



        if(  (st->discard >= AVDISCARD_NONKEY && !(flags&2))

           || st->discard >= AVDISCARD_ALL){

            av_free_packet(pkt);

        } else

            break;

    }



    return 0;

}

