static void escaped_string(void)

{

    int i;

    struct {

        const char *encoded;

        const char *decoded;

        int skip;

    } test_cases[] = {

        { "\"\\b\"", "\b" },

        { "\"\\f\"", "\f" },

        { "\"\\n\"", "\n" },

        { "\"\\r\"", "\r" },

        { "\"\\t\"", "\t" },

        { "\"/\"", "/" },

        { "\"\\/\"", "/", .skip = 1 },

        { "\"\\\\\"", "\\" },

        { "\"\\\"\"", "\"" },

        { "\"hello world \\\"embedded string\\\"\"",

          "hello world \"embedded string\"" },

        { "\"hello world\\nwith new line\"", "hello world\nwith new line" },

        { "\"single byte utf-8 \\u0020\"", "single byte utf-8  ", .skip = 1 },

        { "\"double byte utf-8 \\u00A2\"", "double byte utf-8 \xc2\xa2" },

        { "\"triple byte utf-8 \\u20AC\"", "triple byte utf-8 \xe2\x82\xac" },

        { "'\\b'", "\b", .skip = 1 },

        { "'\\f'", "\f", .skip = 1 },

        { "'\\n'", "\n", .skip = 1 },

        { "'\\r'", "\r", .skip = 1 },

        { "'\\t'", "\t", .skip = 1 },

        { "'\\/'", "/", .skip = 1 },

        { "'\\\\'", "\\", .skip = 1 },

        {}

    };



    for (i = 0; test_cases[i].encoded; i++) {

        QObject *obj;

        QString *str;



        obj = qobject_from_json(test_cases[i].encoded, NULL);

        str = qobject_to_qstring(obj);

        g_assert(str);

        g_assert_cmpstr(qstring_get_str(str), ==, test_cases[i].decoded);



        if (test_cases[i].skip == 0) {

            str = qobject_to_json(obj);

            g_assert_cmpstr(qstring_get_str(str), ==, test_cases[i].encoded);

            qobject_decref(obj);

        }



        QDECREF(str);

    }

}

static inline int vorbis_residue_decode(vorbis_context *vc, vorbis_residue *vr,

                                        unsigned ch,

                                        uint8_t *do_not_decode,

                                        float *vec, unsigned vlen)

{

    if (vr->type == 2)

        return vorbis_residue_decode_internal(vc, vr, ch, do_not_decode, vec, vlen, 2);

    else if (vr->type == 1)

        return vorbis_residue_decode_internal(vc, vr, ch, do_not_decode, vec, vlen, 1);

    else if (vr->type == 0)

        return vorbis_residue_decode_internal(vc, vr, ch, do_not_decode, vec, vlen, 0);

    else {

        av_log(vc->avccontext, AV_LOG_ERROR, " Invalid residue type while residue decode?! \n");

        return AVERROR_INVALIDDATA;

    }

}

static void decode_gain_info(GetBitContext *gb, int *gaininfo)

{

    int i, n;



    while (get_bits1(gb)) {

        /* NOTHING */

    }



    n = get_bits_count(gb) - 1;     // amount of elements*2 to update



    i = 0;

    while (n--) {

        int index = get_bits(gb, 3);

        int gain = get_bits1(gb) ? get_bits(gb, 4) - 7 : -1;



        while (i <= index)

            gaininfo[i++] = gain;

    }

    while (i <= 8)

        gaininfo[i++] = 0;

}

START_TEST(simple_string)

{

    int i;

    struct {

        const char *encoded;

        const char *decoded;

    } test_cases[] = {

        { "\"hello world\"", "hello world" },

        { "\"the quick brown fox jumped over the fence\"",

          "the quick brown fox jumped over the fence" },

        {}

    };



    for (i = 0; test_cases[i].encoded; i++) {

        QObject *obj;

        QString *str;



        obj = qobject_from_json(test_cases[i].encoded);



        fail_unless(obj != NULL);

        fail_unless(qobject_type(obj) == QTYPE_QSTRING);



        str = qobject_to_qstring(obj);

        fail_unless(strcmp(qstring_get_str(str), test_cases[i].decoded) == 0);



        str = qobject_to_json(obj);

        fail_unless(strcmp(qstring_get_str(str), test_cases[i].encoded) == 0);



        qobject_decref(obj);



        QDECREF(str);

    }

}

