const uint8_t *ff_h264_decode_nal(H264Context *h, const uint8_t *src,

                                  int *dst_length, int *consumed, int length)

{

    int i, si, di;

    uint8_t *dst;

    int bufidx;



    // src[0]&0x80; // forbidden bit

    h->nal_ref_idc   = src[0] >> 5;

    h->nal_unit_type = src[0] & 0x1F;



    src++;

    length--;



#define STARTCODE_TEST                                                  \

    if (i + 2 < length && src[i + 1] == 0 && src[i + 2] <= 3) {         \

        if (src[i + 2] != 3) {                                          \

            /* startcode, so we must be past the end */                 \

            length = i;                                                 \

        }                                                               \

        break;                                                          \

    }



#if HAVE_FAST_UNALIGNED

#define FIND_FIRST_ZERO                                                 \

    if (i > 0 && !src[i])                                               \

        i--;                                                            \

    while (src[i])                                                      \

        i++



#if HAVE_FAST_64BIT

    for (i = 0; i + 1 < length; i += 9) {

        if (!((~AV_RN64A(src + i) &

               (AV_RN64A(src + i) - 0x0100010001000101ULL)) &

              0x8000800080008080ULL))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 7;

    }

#else

    for (i = 0; i + 1 < length; i += 5) {

        if (!((~AV_RN32A(src + i) &

               (AV_RN32A(src + i) - 0x01000101U)) &

              0x80008080U))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 3;

    }

#endif

#else

    for (i = 0; i + 1 < length; i += 2) {

        if (src[i])

            continue;

        if (i > 0 && src[i - 1] == 0)

            i--;

        STARTCODE_TEST;

    }

#endif



    if (i >= length - 1) { // no escaped 0

        *dst_length = length;

        *consumed   = length + 1; // +1 for the header

        return src;

    }



    // use second escape buffer for inter data

    bufidx = h->nal_unit_type == NAL_DPC ? 1 : 0;

    av_fast_malloc(&h->rbsp_buffer[bufidx], &h->rbsp_buffer_size[bufidx],

                   length + FF_INPUT_BUFFER_PADDING_SIZE);

    dst = h->rbsp_buffer[bufidx];



    if (dst == NULL)

        return NULL;



    memcpy(dst, src, i);

    si = di = i;

    while (si + 2 < length) {

        // remove escapes (very rare 1:2^22)

        if (src[si + 2] > 3) {

            dst[di++] = src[si++];

            dst[di++] = src[si++];

        } else if (src[si] == 0 && src[si + 1] == 0) {

            if (src[si + 2] == 3) { // escape

                dst[di++]  = 0;

                dst[di++]  = 0;

                si        += 3;

                continue;

            } else // next start code

                goto nsc;

        }



        dst[di++] = src[si++];

    }

    while (si < length)

        dst[di++] = src[si++];



nsc:

    memset(dst + di, 0, FF_INPUT_BUFFER_PADDING_SIZE);



    *dst_length = di;

    *consumed   = si + 1; // +1 for the header

    /* FIXME store exact number of bits in the getbitcontext

     * (it is needed for decoding) */

    return dst;

}

static int find_video_stream_info(AVFormatContext *fmt_ctx, int decode)
{
    int ret = 0;
    int i, done = 0;
    AVPacket pkt;
    av_init_packet(&pkt);
    while (!done) {
        AVCodecContext *codec_ctx = NULL;
        AVStream *st;
        if ((ret = av_read_frame(fmt_ctx, &pkt)) < 0) {
            av_log(fmt_ctx, AV_LOG_ERROR, "Failed to read frame\n");
            goto end;
        st = fmt_ctx->streams[pkt.stream_index];
        codec_ctx = st->codec;
        /* Writing to AVStream.codec_info_nb_frames must not be done by
         * user applications. It is done here for testing purposing as
         * find_video_stream_info tries to mimic avformat_find_stream_info
         * which writes to this field.
         * */
        if (codec_ctx->codec_type != AVMEDIA_TYPE_VIDEO ||
            st->codec_info_nb_frames++ > 0) {
            av_packet_unref(&pkt);
            continue;
        ret = try_decode_video_frame(codec_ctx, &pkt, decode);
        if (ret < 0) {
            av_log(fmt_ctx, AV_LOG_ERROR, "Failed to decode video frame\n");
            goto end;
        av_packet_unref(&pkt);
        /* check if all video streams have demuxed a packet */
        done = 1;
            st = fmt_ctx->streams[i];
            codec_ctx = st->codec;
            if (codec_ctx->codec_type != AVMEDIA_TYPE_VIDEO)
                continue;
            done &= st->codec_info_nb_frames > 0;
end:
    av_packet_unref(&pkt);
    return ret < 0;

static int vc1t_read_header(AVFormatContext *s,

                           AVFormatParameters *ap)

{

    ByteIOContext *pb = s->pb;

    AVStream *st;

    int fps, frames;



    frames = get_le24(pb);

    if(get_byte(pb) != 0xC5 || get_le32(pb) != 4)

        return -1;



    /* init video codec */

    st = av_new_stream(s, 0);

    if (!st)

        return -1;



    st->codec->codec_type = CODEC_TYPE_VIDEO;

    st->codec->codec_id = CODEC_ID_WMV3;



    st->codec->extradata = av_malloc(VC1_EXTRADATA_SIZE);

    st->codec->extradata_size = VC1_EXTRADATA_SIZE;

    get_buffer(pb, st->codec->extradata, VC1_EXTRADATA_SIZE);

    st->codec->height = get_le32(pb);

    st->codec->width = get_le32(pb);

    if(get_le32(pb) != 0xC)

        return -1;

    url_fskip(pb, 8);

    fps = get_le32(pb);

    if(fps == -1)

        av_set_pts_info(st, 32, 1, 1000);

    else{

        av_set_pts_info(st, 24, 1, fps);

        st->duration = frames;

    }



    return 0;

}

void ich9_pm_init(PCIDevice *lpc_pci, ICH9LPCPMRegs *pm,

                  bool smm_enabled,

                  qemu_irq sci_irq)

{

    memory_region_init(&pm->io, OBJECT(lpc_pci), "ich9-pm", ICH9_PMIO_SIZE);

    memory_region_set_enabled(&pm->io, false);

    memory_region_add_subregion(pci_address_space_io(lpc_pci),

                                0, &pm->io);



    acpi_pm_tmr_init(&pm->acpi_regs, ich9_pm_update_sci_fn, &pm->io);

    acpi_pm1_evt_init(&pm->acpi_regs, ich9_pm_update_sci_fn, &pm->io);

    acpi_pm1_cnt_init(&pm->acpi_regs, &pm->io, pm->disable_s3, pm->disable_s4,

                      pm->s4_val);



    acpi_gpe_init(&pm->acpi_regs, ICH9_PMIO_GPE0_LEN);

    memory_region_init_io(&pm->io_gpe, OBJECT(lpc_pci), &ich9_gpe_ops, pm,

                          "acpi-gpe0", ICH9_PMIO_GPE0_LEN);

    memory_region_add_subregion(&pm->io, ICH9_PMIO_GPE0_STS, &pm->io_gpe);



    memory_region_init_io(&pm->io_smi, OBJECT(lpc_pci), &ich9_smi_ops, pm,

                          "acpi-smi", 8);

    memory_region_add_subregion(&pm->io, ICH9_PMIO_SMI_EN, &pm->io_smi);



    pm->smm_enabled = smm_enabled;



    pm->enable_tco = true;

    acpi_pm_tco_init(&pm->tco_regs, &pm->io);



    pm->irq = sci_irq;

    qemu_register_reset(pm_reset, pm);

    pm->powerdown_notifier.notify = pm_powerdown_req;

    qemu_register_powerdown_notifier(&pm->powerdown_notifier);



    legacy_acpi_cpu_hotplug_init(pci_address_space_io(lpc_pci),

        OBJECT(lpc_pci), &pm->gpe_cpu, ICH9_CPU_HOTPLUG_IO_BASE);



    if (pm->acpi_memory_hotplug.is_enabled) {

        acpi_memory_hotplug_init(pci_address_space_io(lpc_pci), OBJECT(lpc_pci),

                                 &pm->acpi_memory_hotplug);

    }

}

static void sigp_start(CPUState *cs, run_on_cpu_data arg)

{

    S390CPU *cpu = S390_CPU(cs);

    SigpInfo *si = arg.host_ptr;



    if (s390_cpu_get_state(cpu) != CPU_STATE_STOPPED) {

        si->cc = SIGP_CC_ORDER_CODE_ACCEPTED;

        return;

    }



    s390_cpu_set_state(CPU_STATE_OPERATING, cpu);

    si->cc = SIGP_CC_ORDER_CODE_ACCEPTED;

}

int ff_jpeg2000_init_component(Jpeg2000Component *comp,
                               Jpeg2000CodingStyle *codsty,
                               Jpeg2000QuantStyle *qntsty,
                               int cbps, int dx, int dy,
                               AVCodecContext *avctx)
{
    int reslevelno, bandno, gbandno = 0, ret, i, j;
    uint32_t csize;
    if (codsty->nreslevels2decode <= 0) {
        av_log(avctx, AV_LOG_ERROR, "nreslevels2decode %d invalid or uninitialized\n", codsty->nreslevels2decode);
        return AVERROR_INVALIDDATA;
    }
    if (ret = ff_jpeg2000_dwt_init(&comp->dwt, comp->coord,
                                   codsty->nreslevels2decode - 1,
                                   codsty->transform))
        return ret;
    if (av_image_check_size(comp->coord[0][1] - comp->coord[0][0],
                            comp->coord[1][1] - comp->coord[1][0], 0, avctx))
        return AVERROR_INVALIDDATA;
    csize = (comp->coord[0][1] - comp->coord[0][0]) *
            (comp->coord[1][1] - comp->coord[1][0]);
    if (comp->coord[0][1] - comp->coord[0][0] > 32768 ||
        comp->coord[1][1] - comp->coord[1][0] > 32768) {
        av_log(avctx, AV_LOG_ERROR, "component size too large\n");
        return AVERROR_PATCHWELCOME;
    }
    if (codsty->transform == FF_DWT97) {
        csize += AV_INPUT_BUFFER_PADDING_SIZE / sizeof(*comp->f_data);
        comp->i_data = NULL;
        comp->f_data = av_mallocz_array(csize, sizeof(*comp->f_data));
        if (!comp->f_data)
    } else {
        csize += AV_INPUT_BUFFER_PADDING_SIZE / sizeof(*comp->i_data);
        comp->f_data = NULL;
        comp->i_data = av_mallocz_array(csize, sizeof(*comp->i_data));
        if (!comp->i_data)
    }
    comp->reslevel = av_mallocz_array(codsty->nreslevels, sizeof(*comp->reslevel));
    if (!comp->reslevel)
    /* LOOP on resolution levels */
    for (reslevelno = 0; reslevelno < codsty->nreslevels; reslevelno++) {
        int declvl = codsty->nreslevels - reslevelno;    // N_L -r see  ISO/IEC 15444-1:2002 B.5
        Jpeg2000ResLevel *reslevel = comp->reslevel + reslevelno;
        /* Compute borders for each resolution level.
         * Computation of trx_0, trx_1, try_0 and try_1.
         * see ISO/IEC 15444-1:2002 eq. B.5 and B-14 */
        for (i = 0; i < 2; i++)
            for (j = 0; j < 2; j++)
                reslevel->coord[i][j] =
                    ff_jpeg2000_ceildivpow2(comp->coord_o[i][j], declvl - 1);
        // update precincts size: 2^n value
        reslevel->log2_prec_width  = codsty->log2_prec_widths[reslevelno];
        reslevel->log2_prec_height = codsty->log2_prec_heights[reslevelno];
        if (!reslevel->log2_prec_width || !reslevel->log2_prec_height) {
            return AVERROR_INVALIDDATA;
        }
        /* Number of bands for each resolution level */
        if (reslevelno == 0)
            reslevel->nbands = 1;
        else
            reslevel->nbands = 3;
        /* Number of precincts which span the tile for resolution level reslevelno
         * see B.6 in ISO/IEC 15444-1:2002 eq. B-16
         * num_precincts_x = |- trx_1 / 2 ^ log2_prec_width) -| - (trx_0 / 2 ^ log2_prec_width)
         * num_precincts_y = |- try_1 / 2 ^ log2_prec_width) -| - (try_0 / 2 ^ log2_prec_width)
         * for Dcinema profiles in JPEG 2000
         * num_precincts_x = |- trx_1 / 2 ^ log2_prec_width) -|
         * num_precincts_y = |- try_1 / 2 ^ log2_prec_width) -| */
        if (reslevel->coord[0][1] == reslevel->coord[0][0])
            reslevel->num_precincts_x = 0;
        else
            reslevel->num_precincts_x =
                ff_jpeg2000_ceildivpow2(reslevel->coord[0][1],
                                        reslevel->log2_prec_width) -
                (reslevel->coord[0][0] >> reslevel->log2_prec_width);
        if (reslevel->coord[1][1] == reslevel->coord[1][0])
            reslevel->num_precincts_y = 0;
        else
            reslevel->num_precincts_y =
                ff_jpeg2000_ceildivpow2(reslevel->coord[1][1],
                                        reslevel->log2_prec_height) -
                (reslevel->coord[1][0] >> reslevel->log2_prec_height);
        reslevel->band = av_mallocz_array(reslevel->nbands, sizeof(*reslevel->band));
        if (!reslevel->band)
        for (bandno = 0; bandno < reslevel->nbands; bandno++, gbandno++) {
            ret = init_band(avctx, reslevel,
                            comp, codsty, qntsty,
                            bandno, gbandno, reslevelno,
                            cbps, dx, dy);
            if (ret < 0)
                return ret;
        }
    }
    return 0;
}

static av_cold int rl2_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    AVStream *st;

    unsigned int frame_count;

    unsigned int audio_frame_counter = 0;

    unsigned int video_frame_counter = 0;

    unsigned int back_size;

    unsigned short sound_rate;

    unsigned short rate;

    unsigned short channels;

    unsigned short def_sound_size;

    unsigned int signature;

    unsigned int pts_den = 11025; /* video only case */

    unsigned int pts_num = 1103;

    unsigned int* chunk_offset = NULL;

    int* chunk_size = NULL;

    int* audio_size = NULL;

    int i;

    int ret = 0;



    avio_skip(pb,4);          /* skip FORM tag */

    back_size = avio_rl32(pb); /**< get size of the background frame */

    signature = avio_rb32(pb);

    avio_skip(pb, 4);         /* data size */

    frame_count = avio_rl32(pb);



    /* disallow back_sizes and frame_counts that may lead to overflows later */

    if(back_size > INT_MAX/2  || frame_count > INT_MAX / sizeof(uint32_t))




    avio_skip(pb, 2);         /* encoding mentod */

    sound_rate = avio_rl16(pb);

    rate = avio_rl16(pb);

    channels = avio_rl16(pb);

    def_sound_size = avio_rl16(pb);







    /** setup video stream */

    st = avformat_new_stream(s, NULL);

    if(!st)

         return AVERROR(ENOMEM);



    st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    st->codec->codec_id = AV_CODEC_ID_RL2;

    st->codec->codec_tag = 0;  /* no fourcc */

    st->codec->width = 320;

    st->codec->height = 200;



    /** allocate and fill extradata */

    st->codec->extradata_size = EXTRADATA1_SIZE;



    if(signature == RLV3_TAG && back_size > 0)

        st->codec->extradata_size += back_size;



    st->codec->extradata = av_mallocz(st->codec->extradata_size +

                                          FF_INPUT_BUFFER_PADDING_SIZE);

    if(!st->codec->extradata)

        return AVERROR(ENOMEM);



    if(avio_read(pb,st->codec->extradata,st->codec->extradata_size) !=

                      st->codec->extradata_size)

        return AVERROR(EIO);



    /** setup audio stream if present */

    if(sound_rate){

        pts_num = def_sound_size;

        pts_den = rate;



        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_id = AV_CODEC_ID_PCM_U8;

        st->codec->codec_tag = 1;

        st->codec->channels = channels;

        st->codec->bits_per_coded_sample = 8;

        st->codec->sample_rate = rate;

        st->codec->bit_rate = st->codec->channels * st->codec->sample_rate *

            st->codec->bits_per_coded_sample;

        st->codec->block_align = st->codec->channels *

            st->codec->bits_per_coded_sample / 8;

        avpriv_set_pts_info(st,32,1,rate);




    avpriv_set_pts_info(s->streams[0], 32, pts_num, pts_den);



    chunk_size =   av_malloc(frame_count * sizeof(uint32_t));

    audio_size =   av_malloc(frame_count * sizeof(uint32_t));

    chunk_offset = av_malloc(frame_count * sizeof(uint32_t));



    if(!chunk_size || !audio_size || !chunk_offset){

        av_free(chunk_size);

        av_free(audio_size);

        av_free(chunk_offset);

        return AVERROR(ENOMEM);




    /** read offset and size tables */

    for(i=0; i < frame_count;i++)

        chunk_size[i] = avio_rl32(pb);

    for(i=0; i < frame_count;i++)

        chunk_offset[i] = avio_rl32(pb);

    for(i=0; i < frame_count;i++)

        audio_size[i] = avio_rl32(pb) & 0xFFFF;



    /** build the sample index */

    for(i=0;i<frame_count;i++){

        if(chunk_size[i] < 0 || audio_size[i] > chunk_size[i]){

            ret = AVERROR_INVALIDDATA;

            break;




        if(sound_rate && audio_size[i]){

            av_add_index_entry(s->streams[1], chunk_offset[i],

                audio_frame_counter,audio_size[i], 0, AVINDEX_KEYFRAME);

            audio_frame_counter += audio_size[i] / channels;


        av_add_index_entry(s->streams[0], chunk_offset[i] + audio_size[i],

            video_frame_counter,chunk_size[i]-audio_size[i],0,AVINDEX_KEYFRAME);

        ++video_frame_counter;






    av_free(chunk_size);

    av_free(audio_size);

    av_free(chunk_offset);



    return ret;

static void vc1_inv_trans_4x8_c(uint8_t *dest, int linesize, DCTELEM *block)

{

    int i;

    register int t1,t2,t3,t4,t5,t6,t7,t8;

    DCTELEM *src, *dst;

    const uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    src = block;

    dst = block;

    for(i = 0; i < 8; i++){

        t1 = 17 * (src[0] + src[2]) + 4;

        t2 = 17 * (src[0] - src[2]) + 4;

        t3 = 22 * src[1] + 10 * src[3];

        t4 = 22 * src[3] - 10 * src[1];



        dst[0] = (t1 + t3) >> 3;

        dst[1] = (t2 - t4) >> 3;

        dst[2] = (t2 + t4) >> 3;

        dst[3] = (t1 - t3) >> 3;



        src += 8;

        dst += 8;

    }



    src = block;

    for(i = 0; i < 4; i++){

        t1 = 12 * (src[ 0] + src[32]) + 64;

        t2 = 12 * (src[ 0] - src[32]) + 64;

        t3 = 16 * src[16] +  6 * src[48];

        t4 =  6 * src[16] - 16 * src[48];



        t5 = t1 + t3;

        t6 = t2 + t4;

        t7 = t2 - t4;

        t8 = t1 - t3;



        t1 = 16 * src[ 8] + 15 * src[24] +  9 * src[40] +  4 * src[56];

        t2 = 15 * src[ 8] -  4 * src[24] - 16 * src[40] -  9 * src[56];

        t3 =  9 * src[ 8] - 16 * src[24] +  4 * src[40] + 15 * src[56];

        t4 =  4 * src[ 8] -  9 * src[24] + 15 * src[40] - 16 * src[56];



        dest[0*linesize] = cm[dest[0*linesize] + ((t5 + t1) >> 7)];

        dest[1*linesize] = cm[dest[1*linesize] + ((t6 + t2) >> 7)];

        dest[2*linesize] = cm[dest[2*linesize] + ((t7 + t3) >> 7)];

        dest[3*linesize] = cm[dest[3*linesize] + ((t8 + t4) >> 7)];

        dest[4*linesize] = cm[dest[4*linesize] + ((t8 - t4 + 1) >> 7)];

        dest[5*linesize] = cm[dest[5*linesize] + ((t7 - t3 + 1) >> 7)];

        dest[6*linesize] = cm[dest[6*linesize] + ((t6 - t2 + 1) >> 7)];

        dest[7*linesize] = cm[dest[7*linesize] + ((t5 - t1 + 1) >> 7)];



        src ++;

        dest++;

    }

}

static void nvdimm_build_nvdimm_devices(GSList *device_list, Aml *root_dev)

{

    for (; device_list; device_list = device_list->next) {

        DeviceState *dev = device_list->data;

        int slot = object_property_get_int(OBJECT(dev), PC_DIMM_SLOT_PROP,

                                           NULL);

        uint32_t handle = nvdimm_slot_to_handle(slot);

        Aml *nvdimm_dev;



        nvdimm_dev = aml_device("NV%02X", slot);



        /*

         * ACPI 6.0: 9.20 NVDIMM Devices:

         *

         * _ADR object that is used to supply OSPM with unique address

         * of the NVDIMM device. This is done by returning the NFIT Device

         * handle that is used to identify the associated entries in ACPI

         * table NFIT or _FIT.

         */

        aml_append(nvdimm_dev, aml_name_decl("_ADR", aml_int(handle)));



        nvdimm_build_device_dsm(nvdimm_dev);

        aml_append(root_dev, nvdimm_dev);

    }

}

bool qemu_peer_has_vnet_hdr_len(NetClientState *nc, int len)

{

    if (!nc->peer || !nc->peer->info->has_vnet_hdr_len) {

        return false;

    }



    return nc->peer->info->has_vnet_hdr_len(nc->peer, len);

}

static inline void RENAME(rgb24tobgr24)(const uint8_t *src, uint8_t *dst, long src_size)

{

	unsigned i;

#ifdef HAVE_MMX

	long mmx_size= 23 - src_size;

	asm volatile (

		"test %%"REG_a", %%"REG_a"	\n\t"

		"jns 2f				\n\t"

		"movq "MANGLE(mask24r)", %%mm5	\n\t"

		"movq "MANGLE(mask24g)", %%mm6	\n\t"

		"movq "MANGLE(mask24b)", %%mm7	\n\t"

		ASMALIGN(4)

		"1:				\n\t"

		PREFETCH" 32(%1, %%"REG_a")	\n\t"

		"movq   (%1, %%"REG_a"), %%mm0	\n\t" // BGR BGR BG

		"movq   (%1, %%"REG_a"), %%mm1	\n\t" // BGR BGR BG

		"movq  2(%1, %%"REG_a"), %%mm2	\n\t" // R BGR BGR B

		"psllq $16, %%mm0		\n\t" // 00 BGR BGR

		"pand %%mm5, %%mm0		\n\t"

		"pand %%mm6, %%mm1		\n\t"

		"pand %%mm7, %%mm2		\n\t"

		"por %%mm0, %%mm1		\n\t"

		"por %%mm2, %%mm1		\n\t"

		"movq  6(%1, %%"REG_a"), %%mm0	\n\t" // BGR BGR BG

		MOVNTQ" %%mm1,   (%2, %%"REG_a")\n\t" // RGB RGB RG

		"movq  8(%1, %%"REG_a"), %%mm1	\n\t" // R BGR BGR B

		"movq 10(%1, %%"REG_a"), %%mm2	\n\t" // GR BGR BGR

		"pand %%mm7, %%mm0		\n\t"

		"pand %%mm5, %%mm1		\n\t"

		"pand %%mm6, %%mm2		\n\t"

		"por %%mm0, %%mm1		\n\t"

		"por %%mm2, %%mm1		\n\t"

		"movq 14(%1, %%"REG_a"), %%mm0	\n\t" // R BGR BGR B

		MOVNTQ" %%mm1,  8(%2, %%"REG_a")\n\t" // B RGB RGB R

		"movq 16(%1, %%"REG_a"), %%mm1	\n\t" // GR BGR BGR

		"movq 18(%1, %%"REG_a"), %%mm2	\n\t" // BGR BGR BG

		"pand %%mm6, %%mm0		\n\t"

		"pand %%mm7, %%mm1		\n\t"

		"pand %%mm5, %%mm2		\n\t"

		"por %%mm0, %%mm1		\n\t"

		"por %%mm2, %%mm1		\n\t"

		MOVNTQ" %%mm1, 16(%2, %%"REG_a")\n\t"

		"add $24, %%"REG_a"		\n\t"

		" js 1b				\n\t"

		"2:				\n\t"

		: "+a" (mmx_size)

		: "r" (src-mmx_size), "r"(dst-mmx_size)

	);



	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");



	if(mmx_size==23) return; //finihsed, was multiple of 8



	src+= src_size;

	dst+= src_size;

	src_size= 23-mmx_size;

	src-= src_size;

	dst-= src_size;

#endif

	for(i=0; i<src_size; i+=3)

	{

		register uint8_t x;

		x          = src[i + 2];

		dst[i + 1] = src[i + 1];

		dst[i + 2] = src[i + 0];

		dst[i + 0] = x;

	}

}

static int mov_get_codec_tag(AVFormatContext *s, MOVTrack *track)

{

    int tag = track->enc->codec_tag;



    if (!tag || (track->enc->strict_std_compliance >= FF_COMPLIANCE_NORMAL &&

                 (tag == MKTAG('d','v','c','p') ||

                  track->enc->codec_id == CODEC_ID_RAWVIDEO ||

                  track->enc->codec_id == CODEC_ID_H263 ||

                  av_get_bits_per_sample(track->enc->codec_id)))) { // pcm audio

        if (track->enc->codec_id == CODEC_ID_DVVIDEO)

            tag = mov_get_dv_codec_tag(s, track);

        else if (track->enc->codec_id == CODEC_ID_RAWVIDEO)

            tag = mov_get_rawvideo_codec_tag(s, track);

        else if (track->enc->codec_type == AVMEDIA_TYPE_VIDEO) {

            tag = ff_codec_get_tag(codec_movvideo_tags, track->enc->codec_id);

            if (!tag) { // if no mac fcc found, try with Microsoft tags

                tag = ff_codec_get_tag(ff_codec_bmp_tags, track->enc->codec_id);

                if (tag)

                    av_log(s, AV_LOG_INFO, "Warning, using MS style video codec tag, "

                           "the file may be unplayable!\n");

            }

        } else if (track->enc->codec_type == AVMEDIA_TYPE_AUDIO) {

            tag = ff_codec_get_tag(codec_movaudio_tags, track->enc->codec_id);

            if (!tag) { // if no mac fcc found, try with Microsoft tags

                int ms_tag = ff_codec_get_tag(ff_codec_wav_tags, track->enc->codec_id);

                if (ms_tag) {

                    tag = MKTAG('m', 's', ((ms_tag >> 8) & 0xff), (ms_tag & 0xff));

                    av_log(s, AV_LOG_INFO, "Warning, using MS style audio codec tag, "

                           "the file may be unplayable!\n");

                }

            }

        } else if (track->enc->codec_type == AVMEDIA_TYPE_SUBTITLE)

            tag = ff_codec_get_tag(ff_codec_movsubtitle_tags, track->enc->codec_id);

    }



    return tag;

}

static unsigned int dec_addi_acr(DisasContext *dc)

{

	TCGv t0;

	DIS(fprintf (logfile, "addi.%c $r%u, $r%u, $acr\n",

		  memsize_char(memsize_zz(dc)), dc->op2, dc->op1));

	cris_cc_mask(dc, 0);

	t0 = tcg_temp_new(TCG_TYPE_TL);

	tcg_gen_shl_tl(t0, cpu_R[dc->op2], tcg_const_tl(dc->zzsize));

	tcg_gen_add_tl(cpu_R[R_ACR], cpu_R[dc->op1], t0);

	tcg_temp_free(t0);

	return 2;

}

static int vaapi_encode_h264_init_picture_params(AVCodecContext *avctx,

                                                 VAAPIEncodePicture *pic)

{

    VAAPIEncodeContext                *ctx = avctx->priv_data;

    VAEncSequenceParameterBufferH264 *vseq = ctx->codec_sequence_params;

    VAEncPictureParameterBufferH264  *vpic = pic->codec_picture_params;

    VAAPIEncodeH264Context           *priv = ctx->priv_data;

    int i;



    if (pic->type == PICTURE_TYPE_IDR) {

        av_assert0(pic->display_order == pic->encode_order);

        vpic->frame_num = 0;

        priv->next_frame_num = 1;

        priv->cpb_delay = 0;

    } else {

        vpic->frame_num = priv->next_frame_num;

        if (pic->type != PICTURE_TYPE_B) {

            // nal_ref_idc != 0

            ++priv->next_frame_num;

        }

        ++priv->cpb_delay;

    }

    priv->dpb_delay = pic->display_order - pic->encode_order + 1;



    vpic->frame_num = vpic->frame_num &

        ((1 << (4 + vseq->seq_fields.bits.log2_max_frame_num_minus4)) - 1);



    vpic->CurrPic.picture_id          = pic->recon_surface;

    vpic->CurrPic.frame_idx           = vpic->frame_num;

    vpic->CurrPic.flags               = 0;

    vpic->CurrPic.TopFieldOrderCnt    = pic->display_order;

    vpic->CurrPic.BottomFieldOrderCnt = pic->display_order;



    for (i = 0; i < pic->nb_refs; i++) {

        VAAPIEncodePicture *ref = pic->refs[i];

        av_assert0(ref && ref->encode_order < pic->encode_order);

        vpic->ReferenceFrames[i].picture_id = ref->recon_surface;

        vpic->ReferenceFrames[i].frame_idx  = ref->encode_order;

        vpic->ReferenceFrames[i].flags = VA_PICTURE_H264_SHORT_TERM_REFERENCE;

        vpic->ReferenceFrames[i].TopFieldOrderCnt    = ref->display_order;

        vpic->ReferenceFrames[i].BottomFieldOrderCnt = ref->display_order;

    }

    for (; i < FF_ARRAY_ELEMS(vpic->ReferenceFrames); i++) {

        vpic->ReferenceFrames[i].picture_id = VA_INVALID_ID;

        vpic->ReferenceFrames[i].flags = VA_PICTURE_H264_INVALID;

    }



    vpic->coded_buf = pic->output_buffer;



    vpic->pic_fields.bits.idr_pic_flag = (pic->type == PICTURE_TYPE_IDR);

    vpic->pic_fields.bits.reference_pic_flag = (pic->type != PICTURE_TYPE_B);



    pic->nb_slices = 1;



    return 0;

}

static av_always_inline void rv40_adaptive_loop_filter(uint8_t *src, const int step,

                                             const int stride, const int dmode,

                                             const int lim_q1, const int lim_p1,

                                             const int alpha,

                                             const int beta, const int beta2,

                                             const int chroma, const int edge)

{

    int diff_p1p0[4], diff_q1q0[4], diff_p1p2[4], diff_q1q2[4];

    int sum_p1p0 = 0, sum_q1q0 = 0, sum_p1p2 = 0, sum_q1q2 = 0;

    uint8_t *ptr;

    int flag_strong0 = 1, flag_strong1 = 1;

    int filter_p1, filter_q1;

    int i;

    int lims;



    for(i = 0, ptr = src; i < 4; i++, ptr += stride){

        diff_p1p0[i] = ptr[-2*step] - ptr[-1*step];

        diff_q1q0[i] = ptr[ 1*step] - ptr[ 0*step];

        sum_p1p0 += diff_p1p0[i];

        sum_q1q0 += diff_q1q0[i];

    }

    filter_p1 = FFABS(sum_p1p0) < (beta<<2);

    filter_q1 = FFABS(sum_q1q0) < (beta<<2);

    if(!filter_p1 && !filter_q1)

        return;



    for(i = 0, ptr = src; i < 4; i++, ptr += stride){

        diff_p1p2[i] = ptr[-2*step] - ptr[-3*step];

        diff_q1q2[i] = ptr[ 1*step] - ptr[ 2*step];

        sum_p1p2 += diff_p1p2[i];

        sum_q1q2 += diff_q1q2[i];

    }



    if(edge){

        flag_strong0 = filter_p1 && (FFABS(sum_p1p2) < beta2);

        flag_strong1 = filter_q1 && (FFABS(sum_q1q2) < beta2);

    }else{

        flag_strong0 = flag_strong1 = 0;

    }



    lims = filter_p1 + filter_q1 + ((lim_q1 + lim_p1) >> 1) + 1;

    if(flag_strong0 && flag_strong1){ /* strong filtering */

        for(i = 0; i < 4; i++, src += stride){

            int sflag, p0, q0, p1, q1;

            int t = src[0*step] - src[-1*step];



            if(!t) continue;

            sflag = (alpha * FFABS(t)) >> 7;

            if(sflag > 1) continue;



            p0 = (25*src[-3*step] + 26*src[-2*step]

                + 26*src[-1*step]

                + 26*src[ 0*step] + 25*src[ 1*step] + rv40_dither_l[dmode + i]) >> 7;

            q0 = (25*src[-2*step] + 26*src[-1*step]

                + 26*src[ 0*step]

                + 26*src[ 1*step] + 25*src[ 2*step] + rv40_dither_r[dmode + i]) >> 7;

            if(sflag){

                p0 = av_clip(p0, src[-1*step] - lims, src[-1*step] + lims);

                q0 = av_clip(q0, src[ 0*step] - lims, src[ 0*step] + lims);

            }

            p1 = (25*src[-4*step] + 26*src[-3*step]

                + 26*src[-2*step]

                + 26*p0           + 25*src[ 0*step] + rv40_dither_l[dmode + i]) >> 7;

            q1 = (25*src[-1*step] + 26*q0

                + 26*src[ 1*step]

                + 26*src[ 2*step] + 25*src[ 3*step] + rv40_dither_r[dmode + i]) >> 7;

            if(sflag){

                p1 = av_clip(p1, src[-2*step] - lims, src[-2*step] + lims);

                q1 = av_clip(q1, src[ 1*step] - lims, src[ 1*step] + lims);

            }

            src[-2*step] = p1;

            src[-1*step] = p0;

            src[ 0*step] = q0;

            src[ 1*step] = q1;

            if(!chroma){

                src[-3*step] = (25*src[-1*step] + 26*src[-2*step] + 51*src[-3*step] + 26*src[-4*step] + 64) >> 7;

                src[ 2*step] = (25*src[ 0*step] + 26*src[ 1*step] + 51*src[ 2*step] + 26*src[ 3*step] + 64) >> 7;

            }

        }

    }else if(filter_p1 && filter_q1){

        for(i = 0; i < 4; i++, src += stride)

            rv40_weak_loop_filter(src, step, 1, 1, alpha, beta, lims, lim_q1, lim_p1,

                                  diff_p1p0[i], diff_q1q0[i], diff_p1p2[i], diff_q1q2[i]);

    }else{

        for(i = 0; i < 4; i++, src += stride)

            rv40_weak_loop_filter(src, step, filter_p1, filter_q1,

                                  alpha, beta, lims>>1, lim_q1>>1, lim_p1>>1,

                                  diff_p1p0[i], diff_q1q0[i], diff_p1p2[i], diff_q1q2[i]);

    }

}

void mipsnet_init (int base, qemu_irq irq, NICInfo *nd)

{

    MIPSnetState *s;



    qemu_check_nic_model(nd, "mipsnet");



    s = qemu_mallocz(sizeof(MIPSnetState));



    register_ioport_write(base, 36, 1, mipsnet_ioport_write, s);

    register_ioport_read(base, 36, 1, mipsnet_ioport_read, s);

    register_ioport_write(base, 36, 2, mipsnet_ioport_write, s);

    register_ioport_read(base, 36, 2, mipsnet_ioport_read, s);

    register_ioport_write(base, 36, 4, mipsnet_ioport_write, s);

    register_ioport_read(base, 36, 4, mipsnet_ioport_read, s);



    s->io_base = base;

    s->irq = irq;

    if (nd && nd->vlan) {

        s->vc = qemu_new_vlan_client(nd->vlan, nd->model, nd->name,

                                     mipsnet_can_receive, mipsnet_receive, NULL,

                                     mipsnet_cleanup, s);

    } else {

        s->vc = NULL;

    }



    qemu_format_nic_info_str(s->vc, nd->macaddr);



    mipsnet_reset(s);

    register_savevm("mipsnet", 0, 0, mipsnet_save, mipsnet_load, s);

}

static void init_blk_migration(Monitor *mon, QEMUFile *f)

{

    BlkMigDevState *bmds;

    BlockDriverState *bs;



    block_mig_state.submitted = 0;

    block_mig_state.read_done = 0;

    block_mig_state.transferred = 0;

    block_mig_state.total_sector_sum = 0;

    block_mig_state.prev_progress = -1;



    for (bs = bdrv_first; bs != NULL; bs = bs->next) {

        if (bs->type == BDRV_TYPE_HD) {

            bmds = qemu_mallocz(sizeof(BlkMigDevState));

            bmds->bs = bs;

            bmds->bulk_completed = 0;

            bmds->total_sectors = bdrv_getlength(bs) >> BDRV_SECTOR_BITS;

            bmds->completed_sectors = 0;

            bmds->shared_base = block_mig_state.shared_base;



            block_mig_state.total_sector_sum += bmds->total_sectors;



            if (bmds->shared_base) {

                monitor_printf(mon, "Start migration for %s with shared base "

                                    "image\n",

                               bs->device_name);

            } else {

                monitor_printf(mon, "Start full migration for %s\n",

                               bs->device_name);

            }



            QSIMPLEQ_INSERT_TAIL(&block_mig_state.bmds_list, bmds, entry);

        }

    }

}

AVFilterBufferRef *avfilter_get_audio_buffer(AVFilterLink *link, int perms,

                                             enum AVSampleFormat sample_fmt, int size,

                                             int64_t channel_layout, int planar)

{

    AVFilterBufferRef *ret = NULL;



    if (link->dstpad->get_audio_buffer)

        ret = link->dstpad->get_audio_buffer(link, perms, sample_fmt, size, channel_layout, planar);



    if (!ret)

        ret = avfilter_default_get_audio_buffer(link, perms, sample_fmt, size, channel_layout, planar);



    if (ret)

        ret->type = AVMEDIA_TYPE_AUDIO;



    return ret;

}

static uint64_t a9_scu_read(void *opaque, target_phys_addr_t offset,

                            unsigned size)

{

    a9mp_priv_state *s = (a9mp_priv_state *)opaque;

    switch (offset) {

    case 0x00: /* Control */

        return s->scu_control;

    case 0x04: /* Configuration */

        return (((1 << s->num_cpu) - 1) << 4) | (s->num_cpu - 1);

    case 0x08: /* CPU Power Status */

        return s->scu_status;

    case 0x09: /* CPU status.  */

        return s->scu_status >> 8;

    case 0x0a: /* CPU status.  */

        return s->scu_status >> 16;

    case 0x0b: /* CPU status.  */

        return s->scu_status >> 24;

    case 0x0c: /* Invalidate All Registers In Secure State */

        return 0;

    case 0x40: /* Filtering Start Address Register */

    case 0x44: /* Filtering End Address Register */

        /* RAZ/WI, like an implementation with only one AXI master */

        return 0;

    case 0x50: /* SCU Access Control Register */

    case 0x54: /* SCU Non-secure Access Control Register */

        /* unimplemented, fall through */

    default:

        return 0;

    }

}

static int xan_decode_chroma(AVCodecContext *avctx, unsigned chroma_off)

{

    XanContext *s = avctx->priv_data;

    uint8_t *U, *V;

    int val, uval, vval;

    int i, j;

    const uint8_t *src, *src_end;

    const uint8_t *table;

    int mode, offset, dec_size;



    if (!chroma_off)

        return 0;

    if (chroma_off + 4 >= bytestream2_get_bytes_left(&s->gb)) {

        av_log(avctx, AV_LOG_ERROR, "Invalid chroma block position\n");

        return -1;

    }

    bytestream2_seek(&s->gb, chroma_off + 4, SEEK_SET);

    mode   = bytestream2_get_le16(&s->gb);

    table  = s->gb.buffer;

    offset = bytestream2_get_le16(&s->gb) * 2;



    if (offset >= bytestream2_get_bytes_left(&s->gb)) {

        av_log(avctx, AV_LOG_ERROR, "Invalid chroma block offset\n");

        return -1;

    }



    bytestream2_skip(&s->gb, offset);

    memset(s->scratch_buffer, 0, s->buffer_size);

    dec_size = xan_unpack(s, s->scratch_buffer, s->buffer_size);

    if (dec_size < 0) {

        av_log(avctx, AV_LOG_ERROR, "Chroma unpacking failed\n");

        return -1;

    }



    U = s->pic.data[1];

    V = s->pic.data[2];

    src     = s->scratch_buffer;

    src_end = src + dec_size;

    if (mode) {

        for (j = 0; j < avctx->height >> 1; j++) {

            for (i = 0; i < avctx->width >> 1; i++) {

                val = *src++;

                if (val) {

                    val  = AV_RL16(table + (val << 1));

                    uval = (val >> 3) & 0xF8;

                    vval = (val >> 8) & 0xF8;

                    U[i] = uval | (uval >> 5);

                    V[i] = vval | (vval >> 5);

                }

                if (src == src_end)

                    return 0;

            }

            U += s->pic.linesize[1];

            V += s->pic.linesize[2];

        }

    } else {

        uint8_t *U2 = U + s->pic.linesize[1];

        uint8_t *V2 = V + s->pic.linesize[2];



        for (j = 0; j < avctx->height >> 2; j++) {

            for (i = 0; i < avctx->width >> 1; i += 2) {

                val = *src++;

                if (val) {

                    val  = AV_RL16(table + (val << 1));

                    uval = (val >> 3) & 0xF8;

                    vval = (val >> 8) & 0xF8;

                    U[i] = U[i+1] = U2[i] = U2[i+1] = uval | (uval >> 5);

                    V[i] = V[i+1] = V2[i] = V2[i+1] = vval | (vval >> 5);

                }

            }

            U  += s->pic.linesize[1] * 2;

            V  += s->pic.linesize[2] * 2;

            U2 += s->pic.linesize[1] * 2;

            V2 += s->pic.linesize[2] * 2;

        }

    }



    return 0;

}

static void coroutine_fn sd_write_done(SheepdogAIOCB *acb)

{

    BDRVSheepdogState *s = acb->common.bs->opaque;

    struct iovec iov;

    AIOReq *aio_req;

    uint32_t offset, data_len, mn, mx;



    mn = s->min_dirty_data_idx;

    mx = s->max_dirty_data_idx;

    if (mn <= mx) {

        /* we need to update the vdi object. */

        offset = sizeof(s->inode) - sizeof(s->inode.data_vdi_id) +

            mn * sizeof(s->inode.data_vdi_id[0]);

        data_len = (mx - mn + 1) * sizeof(s->inode.data_vdi_id[0]);



        s->min_dirty_data_idx = UINT32_MAX;

        s->max_dirty_data_idx = 0;



        iov.iov_base = &s->inode;

        iov.iov_len = sizeof(s->inode);

        aio_req = alloc_aio_req(s, acb, vid_to_vdi_oid(s->inode.vdi_id),

                                data_len, offset, 0, false, 0, offset);

        QLIST_INSERT_HEAD(&s->inflight_aio_head, aio_req, aio_siblings);

        add_aio_request(s, aio_req, &iov, 1, AIOCB_WRITE_UDATA);



        acb->aio_done_func = sd_finish_aiocb;

        acb->aiocb_type = AIOCB_WRITE_UDATA;

        return;

    }



    sd_finish_aiocb(acb);

}

static void cdrom_change_cb(void *opaque, int reason)

{

    IDEState *s = opaque;

    uint64_t nb_sectors;



    if (!(reason & CHANGE_MEDIA)) {

        return;

    }



    bdrv_get_geometry(s->bs, &nb_sectors);

    s->nb_sectors = nb_sectors;



    s->sense_key = SENSE_UNIT_ATTENTION;

    s->asc = ASC_MEDIUM_MAY_HAVE_CHANGED;

    s->cdrom_changed = 1;

    s->events.new_media = true;

    ide_set_irq(s->bus);

}

