static av_cold int init(AVFilterContext *ctx, const char *args)

{

    GradFunContext *gf = ctx->priv;

    float thresh = 1.2;

    int radius = 16;



    if (args)

        sscanf(args, "%f:%d", &thresh, &radius);



    thresh = av_clipf(thresh, 0.51, 255);

    gf->thresh = (1 << 15) / thresh;

    gf->radius = av_clip((radius + 1) & ~1, 4, 32);



    gf->blur_line = ff_gradfun_blur_line_c;

    gf->filter_line = ff_gradfun_filter_line_c;



    if (ARCH_X86)

        ff_gradfun_init_x86(gf);



    av_log(ctx, AV_LOG_VERBOSE, "threshold:%.2f radius:%d\n", thresh, gf->radius);



    return 0;

}

static inline int read_line(AVFormatContext *s, char *rbuf, const int rbufsize,

                            int *rbuflen)

{

    RTSPState *rt = s->priv_data;

    int idx       = 0;

    int ret       = 0;

    *rbuflen      = 0;



    do {

        ret = ffurl_read_complete(rt->rtsp_hd, rbuf + idx, 1);

        if (ret < 0)

            return ret;

        if (rbuf[idx] == '\r') {

            /* Ignore */

        } else if (rbuf[idx] == '\n') {

            rbuf[idx] = '\0';

            *rbuflen  = idx;

            return 0;

        } else

            idx++;

    } while (idx < rbufsize);

    av_log(s, AV_LOG_ERROR, "Message too long\n");

    return AVERROR(EIO);

}

static void encode_header(SnowContext *s){

    int plane_index, level, orientation;



    put_cabac(&s->c, s->header_state, s->keyframe); // state clearing stuff?

    if(s->keyframe){

        put_symbol(&s->c, s->header_state, s->version, 0);

        put_symbol(&s->c, s->header_state, s->temporal_decomposition_type, 0);

        put_symbol(&s->c, s->header_state, s->temporal_decomposition_count, 0);

        put_symbol(&s->c, s->header_state, s->spatial_decomposition_count, 0);

        put_symbol(&s->c, s->header_state, s->colorspace_type, 0);

        put_symbol(&s->c, s->header_state, s->b_width, 0);

        put_symbol(&s->c, s->header_state, s->b_height, 0);

        put_symbol(&s->c, s->header_state, s->chroma_h_shift, 0);

        put_symbol(&s->c, s->header_state, s->chroma_v_shift, 0);

        put_cabac(&s->c, s->header_state, s->spatial_scalability);

//        put_cabac(&s->c, s->header_state, s->rate_scalability);



        for(plane_index=0; plane_index<2; plane_index++){

            for(level=0; level<s->spatial_decomposition_count; level++){

                for(orientation=level ? 1:0; orientation<4; orientation++){

                    if(orientation==2) continue;

                    put_symbol(&s->c, s->header_state, s->plane[plane_index].band[level][orientation].qlog, 1);

                }

            }

        }

    }

    put_symbol(&s->c, s->header_state, s->spatial_decomposition_type, 0);

    put_symbol(&s->c, s->header_state, s->qlog, 1); 

    put_symbol(&s->c, s->header_state, s->mv_scale, 0); 

    put_symbol(&s->c, s->header_state, s->qbias, 1);

}

static int cd_read_sector(IDEState *s, int lba, uint8_t *buf, int sector_size)

{

    int ret;



    switch(sector_size) {

    case 2048:

        block_acct_start(bdrv_get_stats(s->bs), &s->acct,

                         4 * BDRV_SECTOR_SIZE, BLOCK_ACCT_READ);

        ret = bdrv_read(s->bs, (int64_t)lba << 2, buf, 4);

        block_acct_done(bdrv_get_stats(s->bs), &s->acct);

        break;

    case 2352:

        block_acct_start(bdrv_get_stats(s->bs), &s->acct,

                         4 * BDRV_SECTOR_SIZE, BLOCK_ACCT_READ);

        ret = bdrv_read(s->bs, (int64_t)lba << 2, buf + 16, 4);

        block_acct_done(bdrv_get_stats(s->bs), &s->acct);

        if (ret < 0)

            return ret;

        cd_data_to_raw(buf, lba);

        break;

    default:

        ret = -EIO;

        break;

    }

    return ret;

}

static void bl_intrp(EVRCContext *e, float *ex, float delay)

{

    float *f;

    int offset, i, coef_idx;

    int16_t t;



    offset = lrintf(fabs(delay));



    t = (offset - delay + 0.5) * 8.0 + 0.5;

    if (t == 8) {

        t = 0;

        offset--;

    }



    f = ex - offset - 8;



    coef_idx = t * (2 * 8 + 1);



    ex[0] = 0.0;

    for (i = 0; i < 2 * 8 + 1; i++)

        ex[0] += e->interpolation_coeffs[coef_idx + i] * f[i];

}

