static int blk_mig_save_bulked_block(Monitor *mon, QEMUFile *f)

{

    int64_t completed_sector_sum = 0;

    BlkMigDevState *bmds;

    int progress;

    int ret = 0;



    QSIMPLEQ_FOREACH(bmds, &block_mig_state.bmds_list, entry) {

        if (bmds->bulk_completed == 0) {

            if (mig_save_device_bulk(mon, f, bmds) == 1) {

                /* completed bulk section for this device */

                bmds->bulk_completed = 1;

            }

            completed_sector_sum += bmds->completed_sectors;

            ret = 1;

            break;

        } else {

            completed_sector_sum += bmds->completed_sectors;

        }

    }



    progress = completed_sector_sum * 100 / block_mig_state.total_sector_sum;

    if (progress != block_mig_state.prev_progress) {

        block_mig_state.prev_progress = progress;

        qemu_put_be64(f, (progress << BDRV_SECTOR_BITS)

                         | BLK_MIG_FLAG_PROGRESS);

        monitor_printf(mon, "Completed %d %%\r", progress);

        monitor_flush(mon);

    }



    return ret;

}

int avpicture_fill(AVPicture *picture, uint8_t *ptr,

                   enum AVPixelFormat pix_fmt, int width, int height)

{

    int ret;



    if ((ret = av_image_check_size(width, height, 0, NULL)) < 0)

        return ret;



    if ((ret = av_image_fill_linesizes(picture->linesize, pix_fmt, width)) < 0)

        return ret;



    return av_image_fill_pointers(picture->data, pix_fmt,

                                  height, ptr, picture->linesize);

}

void msix_save(PCIDevice *dev, QEMUFile *f)

{

    unsigned n = dev->msix_entries_nr;



    if (!(dev->cap_present & QEMU_PCI_CAP_MSIX)) {

        return;

    }



    qemu_put_buffer(f, dev->msix_table_page, n * PCI_MSIX_ENTRY_SIZE);

    qemu_put_buffer(f, dev->msix_table_page + MSIX_PAGE_PENDING, (n + 7) / 8);

}

static int qemu_rbd_snap_list(BlockDriverState *bs,

                              QEMUSnapshotInfo **psn_tab)

{

    BDRVRBDState *s = bs->opaque;

    QEMUSnapshotInfo *sn_info, *sn_tab = NULL;

    int i, snap_count;

    rbd_snap_info_t *snaps;

    int max_snaps = RBD_MAX_SNAPS;



    do {

        snaps = g_malloc(sizeof(*snaps) * max_snaps);

        snap_count = rbd_snap_list(s->image, snaps, &max_snaps);

        if (snap_count <= 0) {

            g_free(snaps);

        }

    } while (snap_count == -ERANGE);



    if (snap_count <= 0) {

        goto done;

    }



    sn_tab = g_malloc0(snap_count * sizeof(QEMUSnapshotInfo));



    for (i = 0; i < snap_count; i++) {

        const char *snap_name = snaps[i].name;



        sn_info = sn_tab + i;

        pstrcpy(sn_info->id_str, sizeof(sn_info->id_str), snap_name);

        pstrcpy(sn_info->name, sizeof(sn_info->name), snap_name);



        sn_info->vm_state_size = snaps[i].size;

        sn_info->date_sec = 0;

        sn_info->date_nsec = 0;

        sn_info->vm_clock_nsec = 0;

    }

    rbd_snap_list_end(snaps);

    g_free(snaps);



 done:

    *psn_tab = sn_tab;

    return snap_count;

}

int ff_hls_write_file_entry(AVIOContext *out, int insert_discont,

                             int byterange_mode,

                             double duration, int round_duration,

                             int64_t size, int64_t pos, //Used only if HLS_SINGLE_FILE flag is set

                             char *baseurl, //Ignored if NULL

                             char *filename, double *prog_date_time) {

    if (!out || !filename)

        return AVERROR(EINVAL);



    if (insert_discont) {

        avio_printf(out, "#EXT-X-DISCONTINUITY\n");

    }

    if (round_duration)

        avio_printf(out, "#EXTINF:%ld,\n",  lrint(duration));

    else

        avio_printf(out, "#EXTINF:%f,\n", duration);

    if (byterange_mode)

        avio_printf(out, "#EXT-X-BYTERANGE:%"PRId64"@%"PRId64"\n", size, pos);



    if (prog_date_time) {

        time_t tt, wrongsecs;

        int milli;

        struct tm *tm, tmpbuf;

        char buf0[128], buf1[128];

        tt = (int64_t)*prog_date_time;

        milli = av_clip(lrint(1000*(*prog_date_time - tt)), 0, 999);

        tm = localtime_r(&tt, &tmpbuf);

        strftime(buf0, sizeof(buf0), "%Y-%m-%dT%H:%M:%S", tm);

        if (!strftime(buf1, sizeof(buf1), "%z", tm) || buf1[1]<'0' ||buf1[1]>'2') {

            int tz_min, dst = tm->tm_isdst;

            tm = gmtime_r(&tt, &tmpbuf);

            tm->tm_isdst = dst;

            wrongsecs = mktime(tm);

            tz_min = (FFABS(wrongsecs - tt) + 30) / 60;

            snprintf(buf1, sizeof(buf1),

                     "%c%02d%02d",

                     wrongsecs <= tt ? '+' : '-',

                     tz_min / 60,

                     tz_min % 60);

        }

        avio_printf(out, "#EXT-X-PROGRAM-DATE-TIME:%s.%03d%s\n", buf0, milli, buf1);

        *prog_date_time += duration;

    }

    if (baseurl)

        avio_printf(out, "%s", baseurl);

    avio_printf(out, "%s\n", filename);



    return 0;

}

static int libspeex_decode_frame(AVCodecContext *avctx, void *data,

                                 int *got_frame_ptr, AVPacket *avpkt)

{

    uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    LibSpeexContext *s = avctx->priv_data;

    int16_t *output;

    int ret, consumed = 0;



    /* get output buffer */

    s->frame.nb_samples = s->frame_size;

    if ((ret = ff_get_buffer(avctx, &s->frame)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    output = (int16_t *)s->frame.data[0];



    /* if there is not enough data left for the smallest possible frame or the

       next 5 bits are a terminator code, reset the libspeex buffer using the

       current packet, otherwise ignore the current packet and keep decoding

       frames from the libspeex buffer. */

    if (speex_bits_remaining(&s->bits) < 5 ||

        speex_bits_peek_unsigned(&s->bits, 5) == 0x1F) {

        /* check for flush packet */

        if (!buf || !buf_size) {

            *got_frame_ptr = 0;

            return buf_size;

        }

        /* set new buffer */

        speex_bits_read_from(&s->bits, buf, buf_size);

        consumed = buf_size;

    }



    /* decode a single frame */

    ret = speex_decode_int(s->dec_state, &s->bits, output);

    if (ret <= -2) {

        av_log(avctx, AV_LOG_ERROR, "Error decoding Speex frame.\n");

        return AVERROR_INVALIDDATA;

    }

    if (avctx->channels == 2)

        speex_decode_stereo_int(output, s->frame_size, &s->stereo);



    *got_frame_ptr   = 1;

    *(AVFrame *)data = s->frame;



    return consumed;

}

static void GCC_FMT_ATTR(2, 3) blkverify_err(BlkverifyAIOCB *acb,

                                             const char *fmt, ...)

{

    va_list ap;



    va_start(ap, fmt);

    fprintf(stderr, "blkverify: %s sector_num=%" PRId64 " nb_sectors=%d ",

            acb->is_write ? "write" : "read", acb->sector_num,

            acb->nb_sectors);

    vfprintf(stderr, fmt, ap);

    fprintf(stderr, "\n");

    va_end(ap);

    exit(1);

}

static ssize_t qsb_get_iovec(const QEMUSizedBuffer *qsb,

                             off_t pos, off_t *d_off)

{

    ssize_t i;

    off_t curr = 0;



    if (pos > qsb->used) {

        return -1;

    }



    for (i = 0; i < qsb->n_iov; i++) {

        if (curr + qsb->iov[i].iov_len > pos) {

            *d_off = pos - curr;

            return i;

        }

        curr += qsb->iov[i].iov_len;

    }

    return -1;

}

pci_ebus_init1(PCIDevice *s)

{

    isa_bus_new(&s->qdev);



    s->config[0x04] = 0x06; // command = bus master, pci mem

    s->config[0x05] = 0x00;

    s->config[0x06] = 0xa0; // status = fast back-to-back, 66MHz, no error

    s->config[0x07] = 0x03; // status = medium devsel

    s->config[0x09] = 0x00; // programming i/f

    s->config[0x0D] = 0x0a; // latency_timer



    pci_register_bar(s, 0, 0x1000000, PCI_BASE_ADDRESS_SPACE_MEMORY,

                           ebus_mmio_mapfunc);

    pci_register_bar(s, 1, 0x800000,  PCI_BASE_ADDRESS_SPACE_MEMORY,

                           ebus_mmio_mapfunc);

    return 0;

}

