}

static void parse_type_int64(Visitor *v, const char *name, int64_t *obj,

                             Error **errp)

{

    StringInputVisitor *siv = to_siv(v);



    if (!siv->string) {

        error_setg(errp, QERR_INVALID_PARAMETER_TYPE, name ? name : "null",

                   "integer");

        return;

    }



    if (parse_str(siv, name, errp) < 0) {

        return;

    }



    if (!siv->ranges) {

        goto error;

    }



    if (!siv->cur_range) {

        Range *r;



        siv->cur_range = g_list_first(siv->ranges);

        if (!siv->cur_range) {

            goto error;

        }



        r = siv->cur_range->data;

        if (!r) {

            goto error;

        }



        siv->cur = r->begin;

    }



    *obj = siv->cur;

    siv->cur++;

    return;



error:

    error_setg(errp, QERR_INVALID_PARAMETER_VALUE, name ? name : "null",

               "an int64 value or range");

}

target_ulong helper_madd32_suov(CPUTriCoreState *env, target_ulong r1,

                                target_ulong r2, target_ulong r3)

{

    uint64_t t1 = extract64(r1, 0, 32);

    uint64_t t2 = extract64(r2, 0, 32);

    uint64_t t3 = extract64(r3, 0, 32);

    int64_t result;



    result = t2 + (t1 * t3);

    return suov32(env, result);

}

int do_sigprocmask(int how, const sigset_t *set, sigset_t *oldset)

{

    int ret;

    sigset_t val;

    sigset_t *temp = NULL;

    CPUState *cpu = thread_cpu;

    TaskState *ts = (TaskState *)cpu->opaque;

    bool segv_was_blocked = ts->sigsegv_blocked;



    if (set) {

        bool has_sigsegv = sigismember(set, SIGSEGV);

        val = *set;

        temp = &val;



        sigdelset(temp, SIGSEGV);



        switch (how) {

        case SIG_BLOCK:

            if (has_sigsegv) {

                ts->sigsegv_blocked = true;

            }

            break;

        case SIG_UNBLOCK:

            if (has_sigsegv) {

                ts->sigsegv_blocked = false;

            }

            break;

        case SIG_SETMASK:

            ts->sigsegv_blocked = has_sigsegv;

            break;

        default:

            g_assert_not_reached();

        }

    }



    ret = sigprocmask(how, temp, oldset);



    if (oldset && segv_was_blocked) {

        sigaddset(oldset, SIGSEGV);

    }



    return ret;

}

static size_t pdu_unmarshal(V9fsPDU *pdu, size_t offset, const char *fmt, ...)

{

    size_t old_offset = offset;

    va_list ap;

    int i;



    va_start(ap, fmt);

    for (i = 0; fmt[i]; i++) {

        switch (fmt[i]) {

        case 'b': {

            uint8_t *valp = va_arg(ap, uint8_t *);

            offset += pdu_unpack(valp, pdu, offset, sizeof(*valp));

            break;

        }

        case 'w': {

            uint16_t val, *valp;

            valp = va_arg(ap, uint16_t *);

            offset += pdu_unpack(&val, pdu, offset, sizeof(val));

            *valp = le16_to_cpu(val);

            break;

        }

        case 'd': {

            uint32_t val, *valp;

            valp = va_arg(ap, uint32_t *);

            offset += pdu_unpack(&val, pdu, offset, sizeof(val));

            *valp = le32_to_cpu(val);

            break;

        }

        case 'q': {

            uint64_t val, *valp;

            valp = va_arg(ap, uint64_t *);

            offset += pdu_unpack(&val, pdu, offset, sizeof(val));

            *valp = le64_to_cpu(val);

            break;

        }

        case 'v': {

            struct iovec *iov = va_arg(ap, struct iovec *);

            int *iovcnt = va_arg(ap, int *);

            *iovcnt = pdu_copy_sg(pdu, offset, 0, iov);

            break;

        }

        case 's': {

            V9fsString *str = va_arg(ap, V9fsString *);

            offset += pdu_unmarshal(pdu, offset, "w", &str->size);

            /* FIXME: sanity check str->size */

            str->data = g_malloc(str->size + 1);

            offset += pdu_unpack(str->data, pdu, offset, str->size);

            str->data[str->size] = 0;

            break;

        }

        case 'Q': {

            V9fsQID *qidp = va_arg(ap, V9fsQID *);

            offset += pdu_unmarshal(pdu, offset, "bdq",

                        &qidp->type, &qidp->version, &qidp->path);

            break;

        }

        case 'S': {

            V9fsStat *statp = va_arg(ap, V9fsStat *);

            offset += pdu_unmarshal(pdu, offset, "wwdQdddqsssssddd",

                        &statp->size, &statp->type, &statp->dev,

                        &statp->qid, &statp->mode, &statp->atime,

                        &statp->mtime, &statp->length,

                        &statp->name, &statp->uid, &statp->gid,

                        &statp->muid, &statp->extension,

                        &statp->n_uid, &statp->n_gid,

                        &statp->n_muid);

            break;

        }

        case 'I': {

            V9fsIattr *iattr = va_arg(ap, V9fsIattr *);

            offset += pdu_unmarshal(pdu, offset, "ddddqqqqq",

                        &iattr->valid, &iattr->mode,

                        &iattr->uid, &iattr->gid, &iattr->size,

                        &iattr->atime_sec, &iattr->atime_nsec,

                        &iattr->mtime_sec, &iattr->mtime_nsec);

            break;

        }

        default:

            break;

        }

    }



    va_end(ap);



    return offset - old_offset;

}

static void qemu_kvm_start_vcpu(CPUState *env)

{

    env->thread = g_malloc0(sizeof(QemuThread));

    env->halt_cond = g_malloc0(sizeof(QemuCond));

    qemu_cond_init(env->halt_cond);

    qemu_thread_create(env->thread, qemu_kvm_cpu_thread_fn, env,

                       QEMU_THREAD_DETACHED);

    while (env->created == 0) {

        qemu_cond_wait(&qemu_cpu_cond, &qemu_global_mutex);

    }

}

static void kzm_init(MachineState *machine)

{

    IMX31KZM *s = g_new0(IMX31KZM, 1);

    unsigned int ram_size;

    unsigned int alias_offset;

    unsigned int i;



    object_initialize(&s->soc, sizeof(s->soc), TYPE_FSL_IMX31);

    object_property_add_child(OBJECT(machine), "soc", OBJECT(&s->soc),

                              &error_abort);



    object_property_set_bool(OBJECT(&s->soc), true, "realized", &error_fatal);



    /* Check the amount of memory is compatible with the SOC */

    if (machine->ram_size > (FSL_IMX31_SDRAM0_SIZE + FSL_IMX31_SDRAM1_SIZE)) {

        error_report("WARNING: RAM size " RAM_ADDR_FMT " above max supported, "

                     "reduced to %x", machine->ram_size,

                     FSL_IMX31_SDRAM0_SIZE + FSL_IMX31_SDRAM1_SIZE);

        machine->ram_size = FSL_IMX31_SDRAM0_SIZE + FSL_IMX31_SDRAM1_SIZE;

    }



    memory_region_allocate_system_memory(&s->ram, NULL, "kzm.ram",

                                         machine->ram_size);

    memory_region_add_subregion(get_system_memory(), FSL_IMX31_SDRAM0_ADDR,

                                &s->ram);



    /* initialize the alias memory if any */

    for (i = 0, ram_size = machine->ram_size, alias_offset = 0;

         (i < 2) && ram_size; i++) {

        unsigned int size;

        static const struct {

            hwaddr addr;

            unsigned int size;

        } ram[2] = {

            { FSL_IMX31_SDRAM0_ADDR, FSL_IMX31_SDRAM0_SIZE },

            { FSL_IMX31_SDRAM1_ADDR, FSL_IMX31_SDRAM1_SIZE },

        };



        size = MIN(ram_size, ram[i].size);



        ram_size -= size;



        if (size < ram[i].size) {

            memory_region_init_alias(&s->ram_alias, NULL, "ram.alias",

                                     &s->ram, alias_offset, ram[i].size - size);

            memory_region_add_subregion(get_system_memory(),

                                        ram[i].addr + size, &s->ram_alias);

        }



        alias_offset += ram[i].size;

    }



    if (nd_table[0].used) {

        lan9118_init(&nd_table[0], KZM_LAN9118_ADDR,

                     qdev_get_gpio_in(DEVICE(&s->soc.avic), 52));

    }



    if (serial_hds[2]) { /* touchscreen */

        serial_mm_init(get_system_memory(), KZM_FPGA_ADDR+0x10, 0,

                       qdev_get_gpio_in(DEVICE(&s->soc.avic), 52),

                       14745600, serial_hds[2], DEVICE_NATIVE_ENDIAN);

    }



    kzm_binfo.ram_size = machine->ram_size;

    kzm_binfo.kernel_filename = machine->kernel_filename;

    kzm_binfo.kernel_cmdline = machine->kernel_cmdline;

    kzm_binfo.initrd_filename = machine->initrd_filename;

    kzm_binfo.nb_cpus = 1;



    if (!qtest_enabled()) {

        arm_load_kernel(&s->soc.cpu, &kzm_binfo);

    }

}

static int process_input_packet(InputStream *ist, const AVPacket *pkt, int no_eof)

{

    int ret = 0, i;

    int got_output = 0;



    AVPacket avpkt;

    if (!ist->saw_first_ts) {

        ist->dts = ist->st->avg_frame_rate.num ? - ist->dec_ctx->has_b_frames * AV_TIME_BASE / av_q2d(ist->st->avg_frame_rate) : 0;

        ist->pts = 0;

        if (pkt && pkt->pts != AV_NOPTS_VALUE && !ist->decoding_needed) {

            ist->dts += av_rescale_q(pkt->pts, ist->st->time_base, AV_TIME_BASE_Q);

            ist->pts = ist->dts; //unused but better to set it to a value thats not totally wrong

        }

        ist->saw_first_ts = 1;

    }



    if (ist->next_dts == AV_NOPTS_VALUE)

        ist->next_dts = ist->dts;

    if (ist->next_pts == AV_NOPTS_VALUE)

        ist->next_pts = ist->pts;



    if (!pkt) {

        /* EOF handling */

        av_init_packet(&avpkt);

        avpkt.data = NULL;

        avpkt.size = 0;

        goto handle_eof;

    } else {

        avpkt = *pkt;

    }



    if (pkt->dts != AV_NOPTS_VALUE) {

        ist->next_dts = ist->dts = av_rescale_q(pkt->dts, ist->st->time_base, AV_TIME_BASE_Q);

        if (ist->dec_ctx->codec_type != AVMEDIA_TYPE_VIDEO || !ist->decoding_needed)

            ist->next_pts = ist->pts = ist->dts;

    }



    // while we have more to decode or while the decoder did output something on EOF

    while (ist->decoding_needed && (avpkt.size > 0 || (!pkt && got_output))) {

        int duration;

    handle_eof:



        ist->pts = ist->next_pts;

        ist->dts = ist->next_dts;



        switch (ist->dec_ctx->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            ret = decode_audio    (ist, &avpkt, &got_output);

            break;

        case AVMEDIA_TYPE_VIDEO:

            ret = decode_video    (ist, &avpkt, &got_output);

            if (avpkt.duration) {

                duration = av_rescale_q(avpkt.duration, ist->st->time_base, AV_TIME_BASE_Q);

            } else if(ist->dec_ctx->framerate.num != 0 && ist->dec_ctx->framerate.den != 0) {

                int ticks= av_stream_get_parser(ist->st) ? av_stream_get_parser(ist->st)->repeat_pict+1 : ist->dec_ctx->ticks_per_frame;

                duration = ((int64_t)AV_TIME_BASE *

                                ist->dec_ctx->framerate.den * ticks) /

                                ist->dec_ctx->framerate.num / ist->dec_ctx->ticks_per_frame;

            } else

                duration = 0;



            if(ist->dts != AV_NOPTS_VALUE && duration) {

                ist->next_dts += duration;

            }else

                ist->next_dts = AV_NOPTS_VALUE;



            if (got_output)

                ist->next_pts += duration; //FIXME the duration is not correct in some cases

            break;

        case AVMEDIA_TYPE_SUBTITLE:

            ret = transcode_subtitles(ist, &avpkt, &got_output);

            break;

        default:

            return -1;

        }



        if (ret < 0) {

            av_log(NULL, AV_LOG_ERROR, "Error while decoding stream #%d:%d: %s\n",

                   ist->file_index, ist->st->index, av_err2str(ret));

            if (exit_on_error)

                exit_program(1);

            break;

        }



        avpkt.dts=

        avpkt.pts= AV_NOPTS_VALUE;



        // touch data and size only if not EOF

        if (pkt) {

            if(ist->dec_ctx->codec_type != AVMEDIA_TYPE_AUDIO)

                ret = avpkt.size;

            avpkt.data += ret;

            avpkt.size -= ret;

        }

        if (!got_output) {

            continue;

        }

        if (got_output && !pkt)

            break;

    }



    /* after flushing, send an EOF on all the filter inputs attached to the stream */

    /* except when looping we need to flush but not to send an EOF */

    if (!pkt && ist->decoding_needed && !got_output && !no_eof) {

        int ret = send_filter_eof(ist);

        if (ret < 0) {

            av_log(NULL, AV_LOG_FATAL, "Error marking filters as finished\n");

            exit_program(1);

        }

    }



    /* handle stream copy */

    if (!ist->decoding_needed) {

        ist->dts = ist->next_dts;

        switch (ist->dec_ctx->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            ist->next_dts += ((int64_t)AV_TIME_BASE * ist->dec_ctx->frame_size) /

                             ist->dec_ctx->sample_rate;

            break;

        case AVMEDIA_TYPE_VIDEO:

            if (ist->framerate.num) {

                // TODO: Remove work-around for c99-to-c89 issue 7

                AVRational time_base_q = AV_TIME_BASE_Q;

                int64_t next_dts = av_rescale_q(ist->next_dts, time_base_q, av_inv_q(ist->framerate));

                ist->next_dts = av_rescale_q(next_dts + 1, av_inv_q(ist->framerate), time_base_q);

            } else if (pkt->duration) {

                ist->next_dts += av_rescale_q(pkt->duration, ist->st->time_base, AV_TIME_BASE_Q);

            } else if(ist->dec_ctx->framerate.num != 0) {

                int ticks= av_stream_get_parser(ist->st) ? av_stream_get_parser(ist->st)->repeat_pict + 1 : ist->dec_ctx->ticks_per_frame;

                ist->next_dts += ((int64_t)AV_TIME_BASE *

                                  ist->dec_ctx->framerate.den * ticks) /

                                  ist->dec_ctx->framerate.num / ist->dec_ctx->ticks_per_frame;

            }

            break;

        }

        ist->pts = ist->dts;

        ist->next_pts = ist->next_dts;

    }

    for (i = 0; pkt && i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];



        if (!check_output_constraints(ist, ost) || ost->encoding_needed)

            continue;



        do_streamcopy(ist, ost, pkt);

    }



    return got_output;

}

static uint32_t pm_ioport_readw(void *opaque, uint32_t addr)

{

    VT686PMState *s = opaque;

    uint32_t val;



    addr &= 0x0f;

    switch (addr) {

    case 0x00:

        val = acpi_pm1_evt_get_sts(&s->ar, s->ar.tmr.overflow_time);

        break;

    case 0x02:

        val = s->ar.pm1.evt.en;

        break;

    case 0x04:

        val = s->ar.pm1.cnt.cnt;

        break;

    default:

        val = 0;

        break;

    }

    DPRINTF("PM readw port=0x%04x val=0x%02x\n", addr, val);

    return val;

}

static int set_segment_filename(AVFormatContext *s)

{

    SegmentContext *seg = s->priv_data;

    AVFormatContext *oc = seg->avf;

    size_t size;



    if (seg->segment_idx_wrap)

        seg->segment_idx %= seg->segment_idx_wrap;

    if (seg->use_strftime) {

        time_t now0;

        struct tm *tm, tmpbuf;

        time(&now0);

        tm = localtime_r(&now0, &tmpbuf);

        if (!strftime(oc->filename, sizeof(oc->filename), s->filename, tm)) {

            av_log(oc, AV_LOG_ERROR, "Could not get segment filename with strftime\n");

            return AVERROR(EINVAL);

        }

    } else if (av_get_frame_filename(oc->filename, sizeof(oc->filename),

                                     s->filename, seg->segment_idx) < 0) {

        av_log(oc, AV_LOG_ERROR, "Invalid segment filename template '%s'\n", s->filename);

        return AVERROR(EINVAL);

    }



    /* copy modified name in list entry */

    size = strlen(av_basename(oc->filename)) + 1;

    if (seg->entry_prefix)

        size += strlen(seg->entry_prefix);



    seg->cur_entry.filename = av_mallocz(size);

    if (!seg->cur_entry.filename)

        return AVERROR(ENOMEM);

    snprintf(seg->cur_entry.filename, size, "%s%s",

             seg->entry_prefix ? seg->entry_prefix : "",

             av_basename(oc->filename));



    return 0;

}

static target_ulong h_send_logical_lan(CPUPPCState *env, sPAPREnvironment *spapr,

                                       target_ulong opcode, target_ulong *args)

{

    target_ulong reg = args[0];

    target_ulong *bufs = args + 1;

    target_ulong continue_token = args[7];

    VIOsPAPRDevice *sdev = spapr_vio_find_by_reg(spapr->vio_bus, reg);

    VIOsPAPRVLANDevice *dev = (VIOsPAPRVLANDevice *)sdev;

    unsigned total_len;

    uint8_t *lbuf, *p;

    int i, nbufs;

    int ret;



    dprintf("H_SEND_LOGICAL_LAN(0x" TARGET_FMT_lx ", <bufs>, 0x"

            TARGET_FMT_lx ")\n", reg, continue_token);



    if (!sdev) {

        return H_PARAMETER;

    }



    dprintf("rxbufs = %d\n", dev->rx_bufs);



    if (!dev->isopen) {

        return H_DROPPED;

    }



    if (continue_token) {

        return H_HARDWARE; /* FIXME actually handle this */

    }



    total_len = 0;

    for (i = 0; i < 6; i++) {

        dprintf("   buf desc: 0x" TARGET_FMT_lx "\n", bufs[i]);

        if (!(bufs[i] & VLAN_BD_VALID)) {

            break;

        }

        total_len += VLAN_BD_LEN(bufs[i]);

    }



    nbufs = i;

    dprintf("h_send_logical_lan() %d buffers, total length 0x%x\n",

            nbufs, total_len);



    if (total_len == 0) {

        return H_SUCCESS;

    }



    if (total_len > MAX_PACKET_SIZE) {

        /* Don't let the guest force too large an allocation */

        return H_RESOURCE;

    }



    lbuf = alloca(total_len);

    p = lbuf;

    for (i = 0; i < nbufs; i++) {

        ret = spapr_tce_dma_read(sdev, VLAN_BD_ADDR(bufs[i]),

                                 p, VLAN_BD_LEN(bufs[i]));

        if (ret < 0) {

            return ret;

        }



        p += VLAN_BD_LEN(bufs[i]);

    }



    qemu_send_packet(&dev->nic->nc, lbuf, total_len);



    return H_SUCCESS;

}

void gen_intermediate_code(CPUPPCState *env, struct TranslationBlock *tb)

{

    PowerPCCPU *cpu = ppc_env_get_cpu(env);

    CPUState *cs = CPU(cpu);

    DisasContext ctx, *ctxp = &ctx;

    opc_handler_t **table, *handler;

    target_ulong pc_start;

    int num_insns;

    int max_insns;



    pc_start = tb->pc;

    ctx.nip = pc_start;

    ctx.tb = tb;

    ctx.exception = POWERPC_EXCP_NONE;

    ctx.spr_cb = env->spr_cb;

    ctx.pr = msr_pr;

    ctx.mem_idx = env->dmmu_idx;

    ctx.dr = msr_dr;

#if !defined(CONFIG_USER_ONLY)

    ctx.hv = msr_hv || !env->has_hv_mode;

#endif

    ctx.insns_flags = env->insns_flags;

    ctx.insns_flags2 = env->insns_flags2;

    ctx.access_type = -1;

    ctx.le_mode = !!(env->hflags & (1 << MSR_LE));

    ctx.default_tcg_memop_mask = ctx.le_mode ? MO_LE : MO_BE;

#if defined(TARGET_PPC64)

    ctx.sf_mode = msr_is_64bit(env, env->msr);

    ctx.has_cfar = !!(env->flags & POWERPC_FLAG_CFAR);

#endif

    if (env->mmu_model == POWERPC_MMU_32B ||

        env->mmu_model == POWERPC_MMU_601 ||

        (env->mmu_model & POWERPC_MMU_64B))

            ctx.lazy_tlb_flush = true;



    ctx.fpu_enabled = !!msr_fp;

    if ((env->flags & POWERPC_FLAG_SPE) && msr_spe)

        ctx.spe_enabled = !!msr_spe;

    else

        ctx.spe_enabled = false;

    if ((env->flags & POWERPC_FLAG_VRE) && msr_vr)

        ctx.altivec_enabled = !!msr_vr;

    else

        ctx.altivec_enabled = false;

    if ((env->flags & POWERPC_FLAG_VSX) && msr_vsx) {

        ctx.vsx_enabled = !!msr_vsx;

    } else {

        ctx.vsx_enabled = false;

    }

#if defined(TARGET_PPC64)

    if ((env->flags & POWERPC_FLAG_TM) && msr_tm) {

        ctx.tm_enabled = !!msr_tm;

    } else {

        ctx.tm_enabled = false;

    }

#endif

    if ((env->flags & POWERPC_FLAG_SE) && msr_se)

        ctx.singlestep_enabled = CPU_SINGLE_STEP;

    else

        ctx.singlestep_enabled = 0;

    if ((env->flags & POWERPC_FLAG_BE) && msr_be)

        ctx.singlestep_enabled |= CPU_BRANCH_STEP;

    if (unlikely(cs->singlestep_enabled)) {

        ctx.singlestep_enabled |= GDBSTUB_SINGLE_STEP;

    }

#if defined (DO_SINGLE_STEP) && 0

    /* Single step trace mode */

    msr_se = 1;

#endif

    num_insns = 0;

    max_insns = tb->cflags & CF_COUNT_MASK;

    if (max_insns == 0) {

        max_insns = CF_COUNT_MASK;

    }

    if (max_insns > TCG_MAX_INSNS) {

        max_insns = TCG_MAX_INSNS;

    }



    gen_tb_start(tb);

    tcg_clear_temp_count();

    /* Set env in case of segfault during code fetch */

    while (ctx.exception == POWERPC_EXCP_NONE && !tcg_op_buf_full()) {

        tcg_gen_insn_start(ctx.nip);

        num_insns++;



        if (unlikely(cpu_breakpoint_test(cs, ctx.nip, BP_ANY))) {

            gen_debug_exception(ctxp);

            /* The address covered by the breakpoint must be included in

               [tb->pc, tb->pc + tb->size) in order to for it to be

               properly cleared -- thus we increment the PC here so that

               the logic setting tb->size below does the right thing.  */

            ctx.nip += 4;

            break;

        }



        LOG_DISAS("----------------\n");

        LOG_DISAS("nip=" TARGET_FMT_lx " super=%d ir=%d\n",

                  ctx.nip, ctx.mem_idx, (int)msr_ir);

        if (num_insns == max_insns && (tb->cflags & CF_LAST_IO))

            gen_io_start();

        if (unlikely(need_byteswap(&ctx))) {

            ctx.opcode = bswap32(cpu_ldl_code(env, ctx.nip));

        } else {

            ctx.opcode = cpu_ldl_code(env, ctx.nip);

        }

        LOG_DISAS("translate opcode %08x (%02x %02x %02x) (%s)\n",

                    ctx.opcode, opc1(ctx.opcode), opc2(ctx.opcode),

                    opc3(ctx.opcode), ctx.le_mode ? "little" : "big");

        ctx.nip += 4;

        table = env->opcodes;

        handler = table[opc1(ctx.opcode)];

        if (is_indirect_opcode(handler)) {

            table = ind_table(handler);

            handler = table[opc2(ctx.opcode)];

            if (is_indirect_opcode(handler)) {

                table = ind_table(handler);

                handler = table[opc3(ctx.opcode)];

            }

        }

        /* Is opcode *REALLY* valid ? */

        if (unlikely(handler->handler == &gen_invalid)) {

            qemu_log_mask(LOG_GUEST_ERROR, "invalid/unsupported opcode: "

                          "%02x - %02x - %02x (%08x) " TARGET_FMT_lx " %d\n",

                          opc1(ctx.opcode), opc2(ctx.opcode),

                          opc3(ctx.opcode), ctx.opcode, ctx.nip - 4, (int)msr_ir);

        } else {

            uint32_t inval;



            if (unlikely(handler->type & (PPC_SPE | PPC_SPE_SINGLE | PPC_SPE_DOUBLE) && Rc(ctx.opcode))) {

                inval = handler->inval2;

            } else {

                inval = handler->inval1;

            }



            if (unlikely((ctx.opcode & inval) != 0)) {

                qemu_log_mask(LOG_GUEST_ERROR, "invalid bits: %08x for opcode: "

                              "%02x - %02x - %02x (%08x) " TARGET_FMT_lx "\n",

                              ctx.opcode & inval, opc1(ctx.opcode),

                              opc2(ctx.opcode), opc3(ctx.opcode),

                              ctx.opcode, ctx.nip - 4);

                gen_inval_exception(ctxp, POWERPC_EXCP_INVAL_INVAL);

                break;

            }

        }

        (*(handler->handler))(&ctx);

#if defined(DO_PPC_STATISTICS)

        handler->count++;

#endif

        /* Check trace mode exceptions */

        if (unlikely(ctx.singlestep_enabled & CPU_SINGLE_STEP &&

                     (ctx.nip <= 0x100 || ctx.nip > 0xF00) &&

                     ctx.exception != POWERPC_SYSCALL &&

                     ctx.exception != POWERPC_EXCP_TRAP &&

                     ctx.exception != POWERPC_EXCP_BRANCH)) {

            gen_exception(ctxp, POWERPC_EXCP_TRACE);

        } else if (unlikely(((ctx.nip & (TARGET_PAGE_SIZE - 1)) == 0) ||

                            (cs->singlestep_enabled) ||

                            singlestep ||

                            num_insns >= max_insns)) {

            /* if we reach a page boundary or are single stepping, stop

             * generation

             */

            break;

        }

        if (tcg_check_temp_count()) {

            fprintf(stderr, "Opcode %02x %02x %02x (%08x) leaked temporaries\n",

                    opc1(ctx.opcode), opc2(ctx.opcode), opc3(ctx.opcode),

                    ctx.opcode);

            exit(1);

        }

    }

    if (tb->cflags & CF_LAST_IO)

        gen_io_end();

    if (ctx.exception == POWERPC_EXCP_NONE) {

        gen_goto_tb(&ctx, 0, ctx.nip);

    } else if (ctx.exception != POWERPC_EXCP_BRANCH) {

        if (unlikely(cs->singlestep_enabled)) {

            gen_debug_exception(ctxp);

        }

        /* Generate the return instruction */

        tcg_gen_exit_tb(0);

    }

    gen_tb_end(tb, num_insns);



    tb->size = ctx.nip - pc_start;

    tb->icount = num_insns;



#if defined(DEBUG_DISAS)

    if (qemu_loglevel_mask(CPU_LOG_TB_IN_ASM)

        && qemu_log_in_addr_range(pc_start)) {

        int flags;

        flags = env->bfd_mach;

        flags |= ctx.le_mode << 16;

        qemu_log("IN: %s\n", lookup_symbol(pc_start));

        log_target_disas(cs, pc_start, ctx.nip - pc_start, flags);

        qemu_log("\n");

    }

#endif

}

static void openpic_src_write(void *opaque, hwaddr addr, uint64_t val,

                              unsigned len)

{

    OpenPICState *opp = opaque;

    int idx;



    DPRINTF("%s: addr %#" HWADDR_PRIx " <= %08" PRIx64 "\n",

            __func__, addr, val);

    if (addr & 0xF) {

        return;

    }

    addr = addr & 0xFFF0;

    idx = addr >> 5;

    if (addr & 0x10) {

        /* EXDE / IFEDE / IEEDE */

        write_IRQreg_idr(opp, idx, val);

    } else {

        /* EXVP / IFEVP / IEEVP */

        write_IRQreg_ivpr(opp, idx, val);

    }

}

static int packed_vscale(SwsContext *c, SwsFilterDescriptor *desc, int sliceY, int sliceH)

{

    VScalerContext *inst = desc->instance;

    int dstW = desc->dst->width;

    int chrSliceY = sliceY >> desc->dst->v_chr_sub_sample;



    int lum_fsize = inst[0].filter_size;

    int chr_fsize = inst[1].filter_size;

    uint16_t *lum_filter = inst[0].filter[0];

    uint16_t *chr_filter = inst[1].filter[0];



    int firstLum = FFMAX(1-lum_fsize, inst[0].filter_pos[chrSliceY]);

    int firstChr = FFMAX(1-chr_fsize, inst[1].filter_pos[chrSliceY]);



    int sp0 = firstLum - desc->src->plane[0].sliceY;

    int sp1 = firstChr - desc->src->plane[1].sliceY;

    int sp2 = firstChr - desc->src->plane[2].sliceY;

    int sp3 = firstLum - desc->src->plane[3].sliceY;

    int dp = sliceY - desc->dst->plane[0].sliceY;

    uint8_t **src0 = desc->src->plane[0].line + sp0;

    uint8_t **src1 = desc->src->plane[1].line + sp1;

    uint8_t **src2 = desc->src->plane[2].line + sp2;

    uint8_t **src3 = desc->alpha ? desc->src->plane[3].line + sp3 : NULL;

    uint8_t **dst = desc->dst->plane[0].line + dp;





    if (c->yuv2packed1 && lum_fsize == 1 && chr_fsize <= 2) { // unscaled RGB

        int chrAlpha = chr_fsize == 1 ? 0 : chr_filter[2 * sliceY + 1];

        ((yuv2packed1_fn)inst->pfn)(c, (const int16_t*)*src0, (const int16_t**)src1, (const int16_t**)src2, (const int16_t*)(desc->alpha ? *src3 : NULL),  *dst, dstW, chrAlpha, sliceY);

    } else if (c->yuv2packed2 && lum_fsize == 2 && chr_fsize == 2) { // bilinear upscale RGB

        int lumAlpha = lum_filter[2 * sliceY + 1];

        int chrAlpha = chr_filter[2 * sliceY + 1];

        c->lumMmxFilter[2] =

        c->lumMmxFilter[3] = lum_filter[2 * sliceY]    * 0x10001;

        c->chrMmxFilter[2] =

        c->chrMmxFilter[3] = chr_filter[2 * chrSliceY] * 0x10001;

        ((yuv2packed2_fn)inst->pfn)(c, (const int16_t**)src0, (const int16_t**)src1, (const int16_t**)src2, (const int16_t**)src3,

                    *dst, dstW, lumAlpha, chrAlpha, sliceY);

    } else { // general RGB

        ((yuv2packedX_fn)inst->pfn)(c, lum_filter + sliceY * lum_fsize,

                    (const int16_t**)src0, lum_fsize, chr_filter + sliceY * chr_fsize,

                    (const int16_t**)src1, (const int16_t**)src2, chr_fsize, (const int16_t**)src3, *dst, dstW, sliceY);

    }

    return 1;

}

static int pcx_decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    AVFrame *const p   = data;

    int compressed, xmin, ymin, xmax, ymax;

    unsigned int w, h, bits_per_pixel, bytes_per_line, nplanes, stride, y, x,

                 bytes_per_scanline;

    uint8_t *ptr;

    const uint8_t *buf_end = buf + buf_size;

    const uint8_t *bufstart = buf;

    uint8_t *scanline;

    int ret = -1;



    if (buf[0] != 0x0a || buf[1] > 5) {

        av_log(avctx, AV_LOG_ERROR, "this is not PCX encoded data\n");

        return AVERROR_INVALIDDATA;

    }



    compressed = buf[2];

    xmin       = AV_RL16(buf + 4);

    ymin       = AV_RL16(buf + 6);

    xmax       = AV_RL16(buf + 8);

    ymax       = AV_RL16(buf + 10);



    if (xmax < xmin || ymax < ymin) {

        av_log(avctx, AV_LOG_ERROR, "invalid image dimensions\n");

        return AVERROR_INVALIDDATA;

    }



    w = xmax - xmin + 1;

    h = ymax - ymin + 1;



    bits_per_pixel     = buf[3];

    bytes_per_line     = AV_RL16(buf + 66);

    nplanes            = buf[65];

    bytes_per_scanline = nplanes * bytes_per_line;



    if (bytes_per_scanline < (w * bits_per_pixel * nplanes + 7) / 8 ||

        (!compressed && bytes_per_scanline > buf_size / h)) {

        av_log(avctx, AV_LOG_ERROR, "PCX data is corrupted\n");

        return AVERROR_INVALIDDATA;

    }



    switch ((nplanes << 8) + bits_per_pixel) {

    case 0x0308:

        avctx->pix_fmt = AV_PIX_FMT_RGB24;

        break;

    case 0x0108:

    case 0x0104:

    case 0x0102:

    case 0x0101:

    case 0x0401:

    case 0x0301:

    case 0x0201:

        avctx->pix_fmt = AV_PIX_FMT_PAL8;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "invalid PCX file\n");

        return AVERROR_INVALIDDATA;

    }



    buf += 128;



    if ((ret = ff_set_dimensions(avctx, w, h)) < 0)

        return ret;



    if ((ret = ff_get_buffer(avctx, p, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    p->pict_type = AV_PICTURE_TYPE_I;



    ptr    = p->data[0];

    stride = p->linesize[0];



    scanline = av_malloc(bytes_per_scanline);

    if (!scanline)

        return AVERROR(ENOMEM);



    if (nplanes == 3 && bits_per_pixel == 8) {

        for (y = 0; y < h; y++) {

            buf = pcx_rle_decode(buf, buf_end,

                                 scanline, bytes_per_scanline, compressed);



            for (x = 0; x < w; x++) {

                ptr[3 * x]     = scanline[x];

                ptr[3 * x + 1] = scanline[x + bytes_per_line];

                ptr[3 * x + 2] = scanline[x + (bytes_per_line << 1)];

            }



            ptr += stride;

        }

    } else if (nplanes == 1 && bits_per_pixel == 8) {

        const uint8_t *palstart = bufstart + buf_size - 769;



        if (buf_size < 769) {

            av_log(avctx, AV_LOG_ERROR, "File is too short\n");

            ret = avctx->err_recognition & AV_EF_EXPLODE ?

                  AVERROR_INVALIDDATA : buf_size;

            goto end;

        }



        for (y = 0; y < h; y++, ptr += stride) {

            buf = pcx_rle_decode(buf, buf_end,

                                 scanline, bytes_per_scanline, compressed);

            memcpy(ptr, scanline, w);

        }



        if (buf != palstart) {

            av_log(avctx, AV_LOG_WARNING, "image data possibly corrupted\n");

            buf = palstart;

        }

        if (*buf++ != 12) {

            av_log(avctx, AV_LOG_ERROR, "expected palette after image data\n");

            ret = avctx->err_recognition & AV_EF_EXPLODE ?

                  AVERROR_INVALIDDATA : buf_size;

            goto end;

        }

    } else if (nplanes == 1) {   /* all packed formats, max. 16 colors */

        GetBitContext s;



        for (y = 0; y < h; y++) {

            init_get_bits(&s, scanline, bytes_per_scanline << 3);



            buf = pcx_rle_decode(buf, buf_end,

                                 scanline, bytes_per_scanline, compressed);



            for (x = 0; x < w; x++)

                ptr[x] = get_bits(&s, bits_per_pixel);

            ptr += stride;

        }

    } else {    /* planar, 4, 8 or 16 colors */

        int i;



        for (y = 0; y < h; y++) {

            buf = pcx_rle_decode(buf, buf_end,

                                 scanline, bytes_per_scanline, compressed);



            for (x = 0; x < w; x++) {

                int m = 0x80 >> (x & 7), v = 0;

                for (i = nplanes - 1; i >= 0; i--) {

                    v <<= 1;

                    v  += !!(scanline[i * bytes_per_line + (x >> 3)] & m);

                }

                ptr[x] = v;

            }

            ptr += stride;

        }

    }



    if (nplanes == 1 && bits_per_pixel == 8) {

        pcx_palette(&buf, (uint32_t *)p->data[1], 256);

    } else if (bits_per_pixel < 8) {

        const uint8_t *palette = bufstart + 16;

        pcx_palette(&palette, (uint32_t *)p->data[1], 16);

    }



    *got_frame = 1;



    ret = buf - bufstart;

end:

    av_free(scanline);

    return ret;

}

static int dec_scc_r(CPUCRISState *env, DisasContext *dc)

{

    int cond = dc->op2;



    LOG_DIS("s%s $r%u\n",

            cc_name(cond), dc->op1);



    if (cond != CC_A) {

        int l1;



        gen_tst_cc(dc, cpu_R[dc->op1], cond);

        l1 = gen_new_label();

        tcg_gen_brcondi_tl(TCG_COND_EQ, cpu_R[dc->op1], 0, l1);

        tcg_gen_movi_tl(cpu_R[dc->op1], 1);

        gen_set_label(l1);

    } else {

        tcg_gen_movi_tl(cpu_R[dc->op1], 1);

    }



    cris_cc_mask(dc, 0);

    return 2;

}

static int64_t getutime(void)

{

#ifdef HAVE_GETRUSAGE

    struct rusage rusage;



    getrusage(RUSAGE_SELF, &rusage);

    return (rusage.ru_utime.tv_sec * 1000000LL) + rusage.ru_utime.tv_usec;

#elif defined(__MINGW32__)

  return av_gettime();

#endif

}

static int decode_rle(AVCodecContext *avctx, AVSubtitle *sub,

                      const uint8_t *buf, unsigned int buf_size)

{

    const uint8_t *rle_bitmap_end;

    int pixel_count, line_count;



    rle_bitmap_end = buf + buf_size;



    sub->rects[0]->pict.data[0] = av_malloc(sub->rects[0]->w * sub->rects[0]->h);



    if (!sub->rects[0]->pict.data[0])

        return -1;



    pixel_count = 0;

    line_count  = 0;



    while (buf < rle_bitmap_end && line_count < sub->rects[0]->h) {

        uint8_t flags, color;

        int run;



        color = bytestream_get_byte(&buf);

        run   = 1;



        if (color == 0x00) {

            flags = bytestream_get_byte(&buf);

            run   = flags & 0x3f;

            if (flags & 0x40)

                run = (run << 8) + bytestream_get_byte(&buf);

            color = flags & 0x80 ? bytestream_get_byte(&buf) : 0;

        }



        if (run > 0 && pixel_count + run <= sub->rects[0]->w * sub->rects[0]->h) {

            memset(sub->rects[0]->pict.data[0] + pixel_count, color, run);

            pixel_count += run;

        } else if (!run) {

            /*

             * New Line. Check if correct pixels decoded, if not display warning

             * and adjust bitmap pointer to correct new line position.

             */

            if (pixel_count % sub->rects[0]->w > 0)

                av_log(avctx, AV_LOG_ERROR, "Decoded %d pixels, when line should be %d pixels\n",

                       pixel_count % sub->rects[0]->w, sub->rects[0]->w);

            line_count++;

        }

    }



    if (pixel_count < sub->rects[0]->w * sub->rects[0]->h) {

        av_log(avctx, AV_LOG_ERROR, "Insufficient RLE data for subtitle\n");

        return -1;

    }



    av_dlog(avctx, "Pixel Count = %d, Area = %d\n", pixel_count, sub->rects[0]->w * sub->rects[0]->h);



    return 0;

}

MigrationState *tcp_start_outgoing_migration(Monitor *mon,

                                             const char *host_port,

                                             int64_t bandwidth_limit,

                                             int detach,

					     int blk,

					     int inc)

{

    struct sockaddr_in addr;

    FdMigrationState *s;

    int ret;



    if (parse_host_port(&addr, host_port) < 0)

        return NULL;



    s = qemu_mallocz(sizeof(*s));



    s->get_error = socket_errno;

    s->write = socket_write;

    s->close = tcp_close;

    s->mig_state.cancel = migrate_fd_cancel;

    s->mig_state.get_status = migrate_fd_get_status;

    s->mig_state.release = migrate_fd_release;



    s->mig_state.blk = blk;

    s->mig_state.shared = inc;



    s->state = MIG_STATE_ACTIVE;

    s->mon = NULL;

    s->bandwidth_limit = bandwidth_limit;

    s->fd = socket(PF_INET, SOCK_STREAM, 0);

    if (s->fd == -1) {

        qemu_free(s);

        return NULL;

    }



    socket_set_nonblock(s->fd);



    if (!detach) {

        migrate_fd_monitor_suspend(s, mon);

    }



    do {

        ret = connect(s->fd, (struct sockaddr *)&addr, sizeof(addr));

        if (ret == -1)

            ret = -(s->get_error(s));



        if (ret == -EINPROGRESS || ret == -EWOULDBLOCK)

            qemu_set_fd_handler2(s->fd, NULL, NULL, tcp_wait_for_connect, s);

    } while (ret == -EINTR);



    if (ret < 0 && ret != -EINPROGRESS && ret != -EWOULDBLOCK) {

        dprintf("connect failed\n");

        close(s->fd);

        qemu_free(s);

        return NULL;

    } else if (ret >= 0)

        migrate_fd_connect(s);



    return &s->mig_state;

}

const char *av_get_string(void *obj, const char *name, const AVOption **o_out, char *buf, int buf_len){

    const AVOption *o= av_find_opt(obj, name, NULL, 0, 0);

    void *dst;

    if(!o || o->offset<=0)

        return NULL;

    if(o->type != FF_OPT_TYPE_STRING && (!buf || !buf_len))

        return NULL;



    dst= ((uint8_t*)obj) + o->offset;

    if(o_out) *o_out= o;



    if(o->type == FF_OPT_TYPE_STRING)

        return dst;



    switch(o->type){

    case FF_OPT_TYPE_FLAGS:     snprintf(buf, buf_len, "0x%08X",*(int    *)dst);break;

    case FF_OPT_TYPE_INT:       snprintf(buf, buf_len, "%d" , *(int    *)dst);break;

    case FF_OPT_TYPE_INT64:     snprintf(buf, buf_len, "%"PRId64, *(int64_t*)dst);break;

    case FF_OPT_TYPE_FLOAT:     snprintf(buf, buf_len, "%f" , *(float  *)dst);break;

    case FF_OPT_TYPE_DOUBLE:    snprintf(buf, buf_len, "%f" , *(double *)dst);break;

    case FF_OPT_TYPE_RATIONAL:  snprintf(buf, buf_len, "%d/%d", ((AVRational*)dst)->num, ((AVRational*)dst)->den);break;

    default: return NULL;

    }

    return buf;

}

static int mon_init_func(QemuOpts *opts, void *opaque)

{

    CharDriverState *chr;

    const char *chardev;

    const char *mode;

    int flags;



    mode = qemu_opt_get(opts, "mode");

    if (mode == NULL) {

        mode = "readline";

    }

    if (strcmp(mode, "readline") == 0) {

        flags = MONITOR_USE_READLINE;

    } else if (strcmp(mode, "control") == 0) {

        flags = MONITOR_USE_CONTROL;

    } else {

        fprintf(stderr, "unknown monitor mode \"%s\"\n", mode);

        exit(1);

    }



    if (qemu_opt_get_bool(opts, "pretty", 0))

        flags |= MONITOR_USE_PRETTY;



    if (qemu_opt_get_bool(opts, "default", 0))

        flags |= MONITOR_IS_DEFAULT;



    chardev = qemu_opt_get(opts, "chardev");

    chr = qemu_chr_find(chardev);

    if (chr == NULL) {

        fprintf(stderr, "chardev \"%s\" not found\n", chardev);

        exit(1);

    }




    monitor_init(chr, flags);

    return 0;

}

GuestExec *qmp_guest_exec(const char *path,

                       bool has_arg, strList *arg,

                       bool has_env, strList *env,

                       bool has_input_data, const char *input_data,

                       bool has_capture_output, bool capture_output,

                       Error **err)

{

    GPid pid;

    GuestExec *ge = NULL;

    GuestExecInfo *gei;

    char **argv, **envp;

    strList arglist;

    gboolean ret;

    GError *gerr = NULL;

    gint in_fd, out_fd, err_fd;

    GIOChannel *in_ch, *out_ch, *err_ch;

    GSpawnFlags flags;

    bool has_output = (has_capture_output && capture_output);

    uint8_t *input = NULL;

    size_t ninput = 0;



    arglist.value = (char *)path;

    arglist.next = has_arg ? arg : NULL;



    if (has_input_data) {

        input = qbase64_decode(input_data, -1, &ninput, err);

        if (!input) {

            return NULL;

        }

    }



    argv = guest_exec_get_args(&arglist, true);

    envp = has_env ? guest_exec_get_args(env, false) : NULL;



    flags = G_SPAWN_SEARCH_PATH | G_SPAWN_DO_NOT_REAP_CHILD;

#if GLIB_CHECK_VERSION(2, 33, 2)

    flags |= G_SPAWN_SEARCH_PATH_FROM_ENVP;

#endif

    if (!has_output) {

        flags |= G_SPAWN_STDOUT_TO_DEV_NULL | G_SPAWN_STDERR_TO_DEV_NULL;

    }



    ret = g_spawn_async_with_pipes(NULL, argv, envp, flags,

            guest_exec_task_setup, NULL, &pid, has_input_data ? &in_fd : NULL,

            has_output ? &out_fd : NULL, has_output ? &err_fd : NULL, &gerr);

    if (!ret) {

        error_setg(err, QERR_QGA_COMMAND_FAILED, gerr->message);

        g_error_free(gerr);

        goto done;

    }



    ge = g_new0(GuestExec, 1);

    ge->pid = gpid_to_int64(pid);



    gei = guest_exec_info_add(pid);

    gei->has_output = has_output;

    g_child_watch_add(pid, guest_exec_child_watch, gei);



    if (has_input_data) {

        gei->in.data = input;

        gei->in.size = ninput;

#ifdef G_OS_WIN32

        in_ch = g_io_channel_win32_new_fd(in_fd);

#else

        in_ch = g_io_channel_unix_new(in_fd);

#endif

        g_io_channel_set_encoding(in_ch, NULL, NULL);

        g_io_channel_set_buffered(in_ch, false);

        g_io_channel_set_flags(in_ch, G_IO_FLAG_NONBLOCK, NULL);


        g_io_add_watch(in_ch, G_IO_OUT, guest_exec_input_watch, &gei->in);

    }



    if (has_output) {

#ifdef G_OS_WIN32

        out_ch = g_io_channel_win32_new_fd(out_fd);

        err_ch = g_io_channel_win32_new_fd(err_fd);

#else

        out_ch = g_io_channel_unix_new(out_fd);

        err_ch = g_io_channel_unix_new(err_fd);

#endif

        g_io_channel_set_encoding(out_ch, NULL, NULL);

        g_io_channel_set_encoding(err_ch, NULL, NULL);

        g_io_channel_set_buffered(out_ch, false);

        g_io_channel_set_buffered(err_ch, false);

        g_io_channel_set_close_on_unref(out_ch, true);

        g_io_channel_set_close_on_unref(err_ch, true);

        g_io_add_watch(out_ch, G_IO_IN | G_IO_HUP,

                guest_exec_output_watch, &gei->out);

        g_io_add_watch(err_ch, G_IO_IN | G_IO_HUP,

                guest_exec_output_watch, &gei->err);

    }



done:

    g_free(argv);

    g_free(envp);



    return ge;

}

envlist_create(void)

{

	envlist_t *envlist;



	if ((envlist = malloc(sizeof (*envlist))) == NULL)

		return (NULL);



	LIST_INIT(&envlist->el_entries);

	envlist->el_count = 0;



	return (envlist);

}

static int ioh3420_initfn(PCIDevice *d)

{

    PCIBridge* br = DO_UPCAST(PCIBridge, dev, d);

    PCIEPort *p = DO_UPCAST(PCIEPort, br, br);

    PCIESlot *s = DO_UPCAST(PCIESlot, port, p);

    int rc;

    int tmp;



    rc = pci_bridge_initfn(d);

    if (rc < 0) {

        return rc;

    }



    d->config[PCI_REVISION_ID] = PCI_DEVICE_ID_IOH_REV;

    pcie_port_init_reg(d);



    pci_config_set_vendor_id(d->config, PCI_VENDOR_ID_INTEL);

    pci_config_set_device_id(d->config, PCI_DEVICE_ID_IOH_EPORT);



    rc = pci_bridge_ssvid_init(d, IOH_EP_SSVID_OFFSET,

                               IOH_EP_SSVID_SVID, IOH_EP_SSVID_SSID);

    if (rc < 0) {

        goto err_bridge;

    }

    rc = msi_init(d, IOH_EP_MSI_OFFSET, IOH_EP_MSI_NR_VECTOR,

                  IOH_EP_MSI_SUPPORTED_FLAGS & PCI_MSI_FLAGS_64BIT,

                  IOH_EP_MSI_SUPPORTED_FLAGS & PCI_MSI_FLAGS_MASKBIT);

    if (rc < 0) {

        goto err_bridge;

    }

    rc = pcie_cap_init(d, IOH_EP_EXP_OFFSET, PCI_EXP_TYPE_ROOT_PORT, p->port);

    if (rc < 0) {

        goto err_msi;

    }

    pcie_cap_deverr_init(d);

    pcie_cap_slot_init(d, s->slot);

    pcie_chassis_create(s->chassis);

    rc = pcie_chassis_add_slot(s);

    if (rc < 0) {

        goto err_pcie_cap;

        return rc;

    }

    pcie_cap_root_init(d);

    rc = pcie_aer_init(d, IOH_EP_AER_OFFSET);

    if (rc < 0) {

        goto err;

    }

    pcie_aer_root_init(d);

    ioh3420_aer_vector_update(d);

    return 0;



err:

    pcie_chassis_del_slot(s);

err_pcie_cap:

    pcie_cap_exit(d);

err_msi:

    msi_uninit(d);

err_bridge:

    tmp = pci_bridge_exitfn(d);

    assert(!tmp);

    return rc;

}

int kvm_init(MachineClass *mc)

{

    static const char upgrade_note[] =

        "Please upgrade to at least kernel 2.6.29 or recent kvm-kmod\n"

        "(see http://sourceforge.net/projects/kvm).\n";

    struct {

        const char *name;

        int num;

    } num_cpus[] = {

        { "SMP",          smp_cpus },

        { "hotpluggable", max_cpus },

        { NULL, }

    }, *nc = num_cpus;

    int soft_vcpus_limit, hard_vcpus_limit;

    KVMState *s;

    const KVMCapabilityInfo *missing_cap;

    int ret;

    int i, type = 0;

    const char *kvm_type;



    s = g_malloc0(sizeof(KVMState));



    /*

     * On systems where the kernel can support different base page

     * sizes, host page size may be different from TARGET_PAGE_SIZE,

     * even with KVM.  TARGET_PAGE_SIZE is assumed to be the minimum

     * page size for the system though.

     */

    assert(TARGET_PAGE_SIZE <= getpagesize());

    page_size_init();



#ifdef KVM_CAP_SET_GUEST_DEBUG

    QTAILQ_INIT(&s->kvm_sw_breakpoints);

#endif

    s->vmfd = -1;

    s->fd = qemu_open("/dev/kvm", O_RDWR);

    if (s->fd == -1) {

        fprintf(stderr, "Could not access KVM kernel module: %m\n");

        ret = -errno;

        goto err;

    }



    ret = kvm_ioctl(s, KVM_GET_API_VERSION, 0);

    if (ret < KVM_API_VERSION) {

        if (ret > 0) {

            ret = -EINVAL;

        }

        fprintf(stderr, "kvm version too old\n");

        goto err;

    }



    if (ret > KVM_API_VERSION) {

        ret = -EINVAL;

        fprintf(stderr, "kvm version not supported\n");

        goto err;

    }



    s->nr_slots = kvm_check_extension(s, KVM_CAP_NR_MEMSLOTS);



    /* If unspecified, use the default value */

    if (!s->nr_slots) {

        s->nr_slots = 32;

    }



    s->slots = g_malloc0(s->nr_slots * sizeof(KVMSlot));



    for (i = 0; i < s->nr_slots; i++) {

        s->slots[i].slot = i;

    }



    /* check the vcpu limits */

    soft_vcpus_limit = kvm_recommended_vcpus(s);

    hard_vcpus_limit = kvm_max_vcpus(s);



    while (nc->name) {

        if (nc->num > soft_vcpus_limit) {

            fprintf(stderr,

                    "Warning: Number of %s cpus requested (%d) exceeds "

                    "the recommended cpus supported by KVM (%d)\n",

                    nc->name, nc->num, soft_vcpus_limit);



            if (nc->num > hard_vcpus_limit) {

                fprintf(stderr, "Number of %s cpus requested (%d) exceeds "

                        "the maximum cpus supported by KVM (%d)\n",

                        nc->name, nc->num, hard_vcpus_limit);

                exit(1);

            }

        }

        nc++;

    }



    kvm_type = qemu_opt_get(qemu_get_machine_opts(), "kvm-type");

    if (mc->kvm_type) {

        type = mc->kvm_type(kvm_type);

    } else if (kvm_type) {

        fprintf(stderr, "Invalid argument kvm-type=%s\n", kvm_type);

        goto err;

    }



    do {

        ret = kvm_ioctl(s, KVM_CREATE_VM, type);

    } while (ret == -EINTR);



    if (ret < 0) {

        fprintf(stderr, "ioctl(KVM_CREATE_VM) failed: %d %s\n", -ret,

                strerror(-ret));



#ifdef TARGET_S390X

        fprintf(stderr, "Please add the 'switch_amode' kernel parameter to "

                        "your host kernel command line\n");

#endif

        goto err;

    }



    s->vmfd = ret;

    missing_cap = kvm_check_extension_list(s, kvm_required_capabilites);

    if (!missing_cap) {

        missing_cap =

            kvm_check_extension_list(s, kvm_arch_required_capabilities);

    }

    if (missing_cap) {

        ret = -EINVAL;

        fprintf(stderr, "kvm does not support %s\n%s",

                missing_cap->name, upgrade_note);

        goto err;

    }



    s->coalesced_mmio = kvm_check_extension(s, KVM_CAP_COALESCED_MMIO);



    s->broken_set_mem_region = 1;

    ret = kvm_check_extension(s, KVM_CAP_JOIN_MEMORY_REGIONS_WORKS);

    if (ret > 0) {

        s->broken_set_mem_region = 0;

    }



#ifdef KVM_CAP_VCPU_EVENTS

    s->vcpu_events = kvm_check_extension(s, KVM_CAP_VCPU_EVENTS);

#endif



    s->robust_singlestep =

        kvm_check_extension(s, KVM_CAP_X86_ROBUST_SINGLESTEP);



#ifdef KVM_CAP_DEBUGREGS

    s->debugregs = kvm_check_extension(s, KVM_CAP_DEBUGREGS);

#endif



#ifdef KVM_CAP_XSAVE

    s->xsave = kvm_check_extension(s, KVM_CAP_XSAVE);

#endif



#ifdef KVM_CAP_XCRS

    s->xcrs = kvm_check_extension(s, KVM_CAP_XCRS);

#endif



#ifdef KVM_CAP_PIT_STATE2

    s->pit_state2 = kvm_check_extension(s, KVM_CAP_PIT_STATE2);

#endif



#ifdef KVM_CAP_IRQ_ROUTING

    s->direct_msi = (kvm_check_extension(s, KVM_CAP_SIGNAL_MSI) > 0);

#endif



    s->intx_set_mask = kvm_check_extension(s, KVM_CAP_PCI_2_3);



    s->irq_set_ioctl = KVM_IRQ_LINE;

    if (kvm_check_extension(s, KVM_CAP_IRQ_INJECT_STATUS)) {

        s->irq_set_ioctl = KVM_IRQ_LINE_STATUS;

    }



#ifdef KVM_CAP_READONLY_MEM

    kvm_readonly_mem_allowed =

        (kvm_check_extension(s, KVM_CAP_READONLY_MEM) > 0);

#endif



    ret = kvm_arch_init(s);

    if (ret < 0) {

        goto err;

    }



    ret = kvm_irqchip_create(s);

    if (ret < 0) {

        goto err;

    }



    kvm_state = s;

    memory_listener_register(&kvm_memory_listener, &address_space_memory);

    memory_listener_register(&kvm_io_listener, &address_space_io);



    s->many_ioeventfds = kvm_check_many_ioeventfds();



    cpu_interrupt_handler = kvm_handle_interrupt;



    return 0;



err:

    if (s->vmfd >= 0) {

        close(s->vmfd);

    }

    if (s->fd != -1) {

        close(s->fd);

    }

    g_free(s->slots);

    g_free(s);



    return ret;

}

int bdrv_eject(BlockDriverState *bs, int eject_flag)

{

    BlockDriver *drv = bs->drv;



    if (bs->locked) {

        return -EBUSY;

    }



    if (drv && drv->bdrv_eject) {

        drv->bdrv_eject(bs, eject_flag);

    }

    bs->tray_open = eject_flag;

    return 0;

}

void avfilter_start_frame(AVFilterLink *link, AVFilterPicRef *picref)

{

    void (*start_frame)(AVFilterLink *, AVFilterPicRef *);

    AVFilterPad *dst = &link_dpad(link);



    if(!(start_frame = dst->start_frame))

        start_frame = avfilter_default_start_frame;



    /* prepare to copy the picture if it has insufficient permissions */

    if((dst->min_perms & picref->perms) != dst->min_perms ||

        dst->rej_perms & picref->perms) {

        /*

        av_log(link->dst, AV_LOG_INFO,

                "frame copy needed (have perms %x, need %x, reject %x)\n",

                picref->perms,

                link_dpad(link).min_perms, link_dpad(link).rej_perms);

        */



        link->cur_pic = avfilter_default_get_video_buffer(link, dst->min_perms);

        link->srcpic = picref;

        link->cur_pic->pts = link->srcpic->pts;


    }

    else

        link->cur_pic = picref;



    start_frame(link, link->cur_pic);

}

static void virtser_port_device_realize(DeviceState *dev, Error **errp)

{

    VirtIOSerialPort *port = VIRTIO_SERIAL_PORT(dev);

    VirtIOSerialPortClass *vsc = VIRTIO_SERIAL_PORT_GET_CLASS(port);

    VirtIOSerialBus *bus = VIRTIO_SERIAL_BUS(qdev_get_parent_bus(dev));

    VirtIODevice *vdev = VIRTIO_DEVICE(bus->vser);

    int max_nr_ports;

    bool plugging_port0;

    Error *err = NULL;



    port->vser = bus->vser;

    port->bh = qemu_bh_new(flush_queued_data_bh, port);



    assert(vsc->have_data);



    /*

     * Is the first console port we're seeing? If so, put it up at

     * location 0. This is done for backward compatibility (old

     * kernel, new qemu).

     */

    plugging_port0 = vsc->is_console && !find_port_by_id(port->vser, 0);



    if (find_port_by_id(port->vser, port->id)) {

        error_setg(errp, "virtio-serial-bus: A port already exists at id %u",

                   port->id);

        return;

    }



    if (find_port_by_name(port->name)) {

        error_setg(errp, "virtio-serial-bus: A port already exists by name %s",

                   port->name);

        return;

    }



    if (port->id == VIRTIO_CONSOLE_BAD_ID) {

        if (plugging_port0) {

            port->id = 0;

        } else {

            port->id = find_free_port_id(port->vser);

            if (port->id == VIRTIO_CONSOLE_BAD_ID) {

                error_setg(errp, "virtio-serial-bus: Maximum port limit for "

                                 "this device reached");

                return;

            }

        }

    }



    max_nr_ports = virtio_tswap32(vdev, port->vser->config.max_nr_ports);

    if (port->id >= max_nr_ports) {

        error_setg(errp, "virtio-serial-bus: Out-of-range port id specified, "

                         "max. allowed: %u", max_nr_ports - 1);

        return;

    }



    vsc->realize(dev, &err);

    if (err != NULL) {

        error_propagate(errp, err);

        return;

    }



    port->elem.out_num = 0;

}

void av_opt_set_defaults(void *s)

{

    av_opt_set_defaults2(s, 0, 0);

}

static void start_frame(AVFilterLink *inlink, AVFilterBufferRef *picref)

{

    AVFilterContext *ctx = inlink->dst;

    TInterlaceContext *tinterlace = ctx->priv;



    if (tinterlace->cur)

        avfilter_unref_buffer(tinterlace->cur);

    tinterlace->cur  = tinterlace->next;

    tinterlace->next = picref;

}

static int alloc_buffer(InputStream *ist, FrameBuffer **pbuf)

{

    AVCodecContext *s = ist->st->codec;

    FrameBuffer  *buf = av_mallocz(sizeof(*buf));

    int ret;

    const int pixel_size = av_pix_fmt_descriptors[s->pix_fmt].comp[0].step_minus1+1;

    int h_chroma_shift, v_chroma_shift;

    int edge = 32; // XXX should be avcodec_get_edge_width(), but that fails on svq1

    int w = s->width, h = s->height;



    if (!buf)

        return AVERROR(ENOMEM);



    if (!(s->flags & CODEC_FLAG_EMU_EDGE)) {

        w += 2*edge;

        h += 2*edge;

    }



    avcodec_align_dimensions(s, &w, &h);

    if ((ret = av_image_alloc(buf->base, buf->linesize, w, h,

                              s->pix_fmt, 32)) < 0) {

        av_freep(&buf);

        return ret;

    }

    /* XXX this shouldn't be needed, but some tests break without this line

     * those decoders are buggy and need to be fixed.

     * the following tests fail:

     * bethsoft-vid, cdgraphics, ansi, aasc, fraps-v1, qtrle-1bit

     */

    memset(buf->base[0], 128, ret);



    avcodec_get_chroma_sub_sample(s->pix_fmt, &h_chroma_shift, &v_chroma_shift);

    for (int i = 0; i < FF_ARRAY_ELEMS(buf->data); i++) {

        const int h_shift = i==0 ? 0 : h_chroma_shift;

        const int v_shift = i==0 ? 0 : v_chroma_shift;

        if (s->flags & CODEC_FLAG_EMU_EDGE)

            buf->data[i] = buf->base[i];

        else

            buf->data[i] = buf->base[i] +

                           FFALIGN((buf->linesize[i]*edge >> v_shift) +

                                   (pixel_size*edge >> h_shift), 32);

    }

    buf->w       = s->width;

    buf->h       = s->height;

    buf->pix_fmt = s->pix_fmt;

    buf->ist     = ist;



    *pbuf = buf;

    return 0;

}

static av_cold int decode_init(WMAProDecodeCtx *s, AVCodecContext *avctx)

{

    uint8_t *edata_ptr = avctx->extradata;

    unsigned int channel_mask;

    int i, bits;

    int log2_max_num_subframes;

    int num_possible_block_sizes;



    if (avctx->codec_id == AV_CODEC_ID_XMA1 || avctx->codec_id == AV_CODEC_ID_XMA2)

        avctx->block_align = 2048;



    if (!avctx->block_align) {

        av_log(avctx, AV_LOG_ERROR, "block_align is not set\n");

        return AVERROR(EINVAL);

    }



    s->avctx = avctx;

    s->fdsp = avpriv_float_dsp_alloc(avctx->flags & AV_CODEC_FLAG_BITEXACT);

    if (!s->fdsp)

        return AVERROR(ENOMEM);



    init_put_bits(&s->pb, s->frame_data, MAX_FRAMESIZE);



    avctx->sample_fmt = AV_SAMPLE_FMT_FLTP;



    /** dump the extradata */

    av_log(avctx, AV_LOG_DEBUG, "extradata:\n");

    for (i = 0; i < avctx->extradata_size; i++)

        av_log(avctx, AV_LOG_DEBUG, "[%x] ", avctx->extradata[i]);

    av_log(avctx, AV_LOG_DEBUG, "\n");

    if (avctx->codec_id == AV_CODEC_ID_XMA2 && (!avctx->extradata || avctx->extradata_size >= 6)) {

        s->decode_flags    = 0x10d6;

        channel_mask       = avctx->extradata ? AV_RL32(edata_ptr+2) : 0;

        s->bits_per_sample = 16;

     } else if (avctx->codec_id == AV_CODEC_ID_XMA1) {

        s->decode_flags    = 0x10d6;

        s->bits_per_sample = 16;

        channel_mask       = 0;

     } else if (avctx->codec_id == AV_CODEC_ID_WMAPRO && avctx->extradata_size >= 18) {

        s->decode_flags    = AV_RL16(edata_ptr+14);

        channel_mask       = AV_RL32(edata_ptr+2);

        s->bits_per_sample = AV_RL16(edata_ptr);



        if (s->bits_per_sample > 32 || s->bits_per_sample < 1) {

            avpriv_request_sample(avctx, "bits per sample is %d", s->bits_per_sample);

            return AVERROR_PATCHWELCOME;

        }

    } else {

        avpriv_request_sample(avctx, "Unknown extradata size");

        return AVERROR_PATCHWELCOME;

    }



    if (avctx->codec_id != AV_CODEC_ID_WMAPRO && avctx->channels > 2) {

        s->nb_channels = 2;

    } else {

        s->nb_channels = avctx->channels;

    }



    /** generic init */

    s->log2_frame_size = av_log2(avctx->block_align) + 4;

    if (s->log2_frame_size > 25) {

        avpriv_request_sample(avctx, "Large block align");

        return AVERROR_PATCHWELCOME;

    }



    /** frame info */

    if (avctx->codec_id != AV_CODEC_ID_WMAPRO)

        s->skip_frame = 0;

    else

        s->skip_frame = 1; /* skip first frame */



    s->packet_loss = 1;

    s->len_prefix  = (s->decode_flags & 0x40);



    /** get frame len */

    if (avctx->codec_id == AV_CODEC_ID_WMAPRO) {

        bits = ff_wma_get_frame_len_bits(avctx->sample_rate, 3, s->decode_flags);

        if (bits > WMAPRO_BLOCK_MAX_BITS) {

            avpriv_request_sample(avctx, "14-bit block sizes");

            return AVERROR_PATCHWELCOME;

        }

        s->samples_per_frame = 1 << bits;

    } else {

        s->samples_per_frame = 512;

    }



    /** subframe info */

    log2_max_num_subframes       = ((s->decode_flags & 0x38) >> 3);

    s->max_num_subframes         = 1 << log2_max_num_subframes;

    if (s->max_num_subframes == 16 || s->max_num_subframes == 4)

        s->max_subframe_len_bit = 1;

    s->subframe_len_bits = av_log2(log2_max_num_subframes) + 1;



    num_possible_block_sizes     = log2_max_num_subframes + 1;

    s->min_samples_per_subframe  = s->samples_per_frame / s->max_num_subframes;

    s->dynamic_range_compression = (s->decode_flags & 0x80);



    if (s->max_num_subframes > MAX_SUBFRAMES) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of subframes %"PRId8"\n",

               s->max_num_subframes);

        return AVERROR_INVALIDDATA;

    }



    if (s->min_samples_per_subframe < WMAPRO_BLOCK_MIN_SIZE) {

        av_log(avctx, AV_LOG_ERROR, "min_samples_per_subframe of %d too small\n",

               s->min_samples_per_subframe);

        return AVERROR_INVALIDDATA;

    }



    if (s->avctx->sample_rate <= 0) {

        av_log(avctx, AV_LOG_ERROR, "invalid sample rate\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->nb_channels <= 0) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of channels %d\n",

               s->nb_channels);

        return AVERROR_INVALIDDATA;

    } else if (s->nb_channels > WMAPRO_MAX_CHANNELS) {

        avpriv_request_sample(avctx,

                              "More than %d channels", WMAPRO_MAX_CHANNELS);

        return AVERROR_PATCHWELCOME;

    }



    /** init previous block len */

    for (i = 0; i < s->nb_channels; i++)

        s->channel[i].prev_block_len = s->samples_per_frame;



    /** extract lfe channel position */

    s->lfe_channel = -1;



    if (channel_mask & 8) {

        unsigned int mask;

        for (mask = 1; mask < 16; mask <<= 1) {

            if (channel_mask & mask)

                ++s->lfe_channel;

        }

    }



    INIT_VLC_STATIC(&sf_vlc, SCALEVLCBITS, HUFF_SCALE_SIZE,

                    scale_huffbits, 1, 1,

                    scale_huffcodes, 2, 2, 616);



    INIT_VLC_STATIC(&sf_rl_vlc, VLCBITS, HUFF_SCALE_RL_SIZE,

                    scale_rl_huffbits, 1, 1,

                    scale_rl_huffcodes, 4, 4, 1406);



    INIT_VLC_STATIC(&coef_vlc[0], VLCBITS, HUFF_COEF0_SIZE,

                    coef0_huffbits, 1, 1,

                    coef0_huffcodes, 4, 4, 2108);



    INIT_VLC_STATIC(&coef_vlc[1], VLCBITS, HUFF_COEF1_SIZE,

                    coef1_huffbits, 1, 1,

                    coef1_huffcodes, 4, 4, 3912);



    INIT_VLC_STATIC(&vec4_vlc, VLCBITS, HUFF_VEC4_SIZE,

                    vec4_huffbits, 1, 1,

                    vec4_huffcodes, 2, 2, 604);



    INIT_VLC_STATIC(&vec2_vlc, VLCBITS, HUFF_VEC2_SIZE,

                    vec2_huffbits, 1, 1,

                    vec2_huffcodes, 2, 2, 562);



    INIT_VLC_STATIC(&vec1_vlc, VLCBITS, HUFF_VEC1_SIZE,

                    vec1_huffbits, 1, 1,

                    vec1_huffcodes, 2, 2, 562);



    /** calculate number of scale factor bands and their offsets

        for every possible block size */

    for (i = 0; i < num_possible_block_sizes; i++) {

        int subframe_len = s->samples_per_frame >> i;

        int x;

        int band = 1;

        int rate = get_rate(avctx);



        s->sfb_offsets[i][0] = 0;



        for (x = 0; x < MAX_BANDS-1 && s->sfb_offsets[i][band - 1] < subframe_len; x++) {

            int offset = (subframe_len * 2 * critical_freq[x]) / rate + 2;

            offset &= ~3;

            if (offset > s->sfb_offsets[i][band - 1])

                s->sfb_offsets[i][band++] = offset;



            if (offset >= subframe_len)

                break;

        }

        s->sfb_offsets[i][band - 1] = subframe_len;

        s->num_sfb[i]               = band - 1;

        if (s->num_sfb[i] <= 0) {

            av_log(avctx, AV_LOG_ERROR, "num_sfb invalid\n");

            return AVERROR_INVALIDDATA;

        }

    }





    /** Scale factors can be shared between blocks of different size

        as every block has a different scale factor band layout.

        The matrix sf_offsets is needed to find the correct scale factor.

     */



    for (i = 0; i < num_possible_block_sizes; i++) {

        int b;

        for (b = 0; b < s->num_sfb[i]; b++) {

            int x;

            int offset = ((s->sfb_offsets[i][b]

                           + s->sfb_offsets[i][b + 1] - 1) << i) >> 1;

            for (x = 0; x < num_possible_block_sizes; x++) {

                int v = 0;

                while (s->sfb_offsets[x][v + 1] << x < offset) {

                    v++;

                    av_assert0(v < MAX_BANDS);

                }

                s->sf_offsets[i][x][b] = v;

            }

        }

    }



    /** init MDCT, FIXME: only init needed sizes */

    for (i = 0; i < WMAPRO_BLOCK_SIZES; i++)

        ff_mdct_init(&s->mdct_ctx[i], WMAPRO_BLOCK_MIN_BITS+1+i, 1,

                     1.0 / (1 << (WMAPRO_BLOCK_MIN_BITS + i - 1))

                     / (1 << (s->bits_per_sample - 1)));



    /** init MDCT windows: simple sine window */

    for (i = 0; i < WMAPRO_BLOCK_SIZES; i++) {

        const int win_idx = WMAPRO_BLOCK_MAX_BITS - i;

        ff_init_ff_sine_windows(win_idx);

        s->windows[WMAPRO_BLOCK_SIZES - i - 1] = ff_sine_windows[win_idx];

    }



    /** calculate subwoofer cutoff values */

    for (i = 0; i < num_possible_block_sizes; i++) {

        int block_size = s->samples_per_frame >> i;

        int cutoff = (440*block_size + 3LL * (s->avctx->sample_rate >> 1) - 1)

                     / s->avctx->sample_rate;

        s->subwoofer_cutoffs[i] = av_clip(cutoff, 4, block_size);

    }



    /** calculate sine values for the decorrelation matrix */

    for (i = 0; i < 33; i++)

        sin64[i] = sin(i*M_PI / 64.0);



    if (avctx->debug & FF_DEBUG_BITSTREAM)

        dump_context(s);



    avctx->channel_layout = channel_mask;



    return 0;

}

void ff_release_unused_pictures(MpegEncContext *s, int remove_current)

{

    int i;



    /* release non reference frames */

    for(i=0; i<s->picture_count; i++){

        if(s->picture[i].data[0] && !s->picture[i].reference

           && s->picture[i].owner2 == s

           && (remove_current || &s->picture[i] != s->current_picture_ptr)

           /*&& s->picture[i].type!=FF_BUFFER_TYPE_SHARED*/){

            free_frame_buffer(s, &s->picture[i]);

        }

    }

}

static int decode_blocks_ind(ALSDecContext *ctx, unsigned int ra_frame,

                             unsigned int c, const unsigned int *div_blocks,

                             unsigned int *js_blocks)

{

    unsigned int b;

    ALSBlockData bd = { 0 };



    bd.ra_block         = ra_frame;

    bd.const_block      = ctx->const_block;

    bd.shift_lsbs       = ctx->shift_lsbs;

    bd.opt_order        = ctx->opt_order;

    bd.store_prev_samples = ctx->store_prev_samples;

    bd.use_ltp          = ctx->use_ltp;

    bd.ltp_lag          = ctx->ltp_lag;

    bd.ltp_gain         = ctx->ltp_gain[0];

    bd.quant_cof        = ctx->quant_cof[0];

    bd.lpc_cof          = ctx->lpc_cof[0];

    bd.prev_raw_samples = ctx->prev_raw_samples;

    bd.raw_samples      = ctx->raw_samples[c];





    for (b = 0; b < ctx->num_blocks; b++) {

        bd.block_length     = div_blocks[b];



        if (read_decode_block(ctx, &bd)) {

            // damaged block, write zero for the rest of the frame

            zero_remaining(b, ctx->num_blocks, div_blocks, bd.raw_samples);

            return -1;

        }

        bd.raw_samples += div_blocks[b];

        bd.ra_block     = 0;

    }



    return 0;

}

