uint64_t helper_fnmsub (uint64_t arg1, uint64_t arg2, uint64_t arg3)

{

    CPU_DoubleU farg1, farg2, farg3;



    farg1.ll = arg1;

    farg2.ll = arg2;

    farg3.ll = arg3;



    if (unlikely(float64_is_signaling_nan(farg1.d) ||

                 float64_is_signaling_nan(farg2.d) ||

                 float64_is_signaling_nan(farg3.d))) {

        /* sNaN operation */

        farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXSNAN);

    } else if (unlikely((float64_is_infinity(farg1.d) && float64_is_zero(farg2.d)) ||

                        (float64_is_zero(farg1.d) && float64_is_infinity(farg2.d)))) {

        /* Multiplication of zero by infinity */

        farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXIMZ);

    } else {

#if USE_PRECISE_EMULATION

#ifdef FLOAT128

        /* This is the way the PowerPC specification defines it */

        float128 ft0_128, ft1_128;



        ft0_128 = float64_to_float128(farg1.d, &env->fp_status);

        ft1_128 = float64_to_float128(farg2.d, &env->fp_status);

        ft0_128 = float128_mul(ft0_128, ft1_128, &env->fp_status);

        if (unlikely(float128_is_infinity(ft0_128) && float64_is_infinity(farg3.d) &&

                     float128_is_neg(ft0_128) == float64_is_neg(farg3.d))) {

            /* Magnitude subtraction of infinities */

            farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXISI);

        } else {

            ft1_128 = float64_to_float128(farg3.d, &env->fp_status);

            ft0_128 = float128_sub(ft0_128, ft1_128, &env->fp_status);

            farg1.d = float128_to_float64(ft0_128, &env->fp_status);

        }

#else

        /* This is OK on x86 hosts */

        farg1.d = (farg1.d * farg2.d) - farg3.d;

#endif

#else

        farg1.d = float64_mul(farg1.d, farg2.d, &env->fp_status);

        farg1.d = float64_sub(farg1.d, farg3.d, &env->fp_status);

#endif

        if (likely(!float64_is_nan(farg1.d)))

            farg1.d = float64_chs(farg1.d);

    }

    return farg1.ll;

}

ff_rm_parse_packet (AVFormatContext *s, ByteIOContext *pb,

                    AVStream *st, RMStream *ast, int len, AVPacket *pkt,

                    int *seq, int *flags, int64_t *timestamp)

{

    RMDemuxContext *rm = s->priv_data;



    if (st->codec->codec_type == CODEC_TYPE_VIDEO) {

        rm->current_stream= st->id;

        if(rm_assemble_video_frame(s, pb, rm, ast, pkt, len))

            return -1; //got partial frame

    } else if (st->codec->codec_type == CODEC_TYPE_AUDIO) {

        if ((st->codec->codec_id == CODEC_ID_RA_288) ||

            (st->codec->codec_id == CODEC_ID_COOK) ||

            (st->codec->codec_id == CODEC_ID_ATRAC3) ||

            (st->codec->codec_id == CODEC_ID_SIPR)) {

            int x;

            int sps = ast->sub_packet_size;

            int cfs = ast->coded_framesize;

            int h = ast->sub_packet_h;

            int y = ast->sub_packet_cnt;

            int w = ast->audio_framesize;



            if (*flags & 2)

                y = ast->sub_packet_cnt = 0;

            if (!y)

                ast->audiotimestamp = *timestamp;



            switch(st->codec->codec_id) {

                case CODEC_ID_RA_288:

                    for (x = 0; x < h/2; x++)

                        get_buffer(pb, ast->pkt.data+x*2*w+y*cfs, cfs);

                    break;

                case CODEC_ID_ATRAC3:

                case CODEC_ID_COOK:

                    for (x = 0; x < w/sps; x++)

                        get_buffer(pb, ast->pkt.data+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), sps);

                    break;

            }



            if (++(ast->sub_packet_cnt) < h)

                return -1;

            else {

                ast->sub_packet_cnt = 0;

                rm->audio_stream_num = st->index;

                rm->audio_pkt_cnt = h * w / st->codec->block_align - 1;

                // Release first audio packet

                av_new_packet(pkt, st->codec->block_align);

                memcpy(pkt->data, ast->pkt.data, st->codec->block_align); //FIXME avoid this

                *timestamp = ast->audiotimestamp;

                *flags = 2; // Mark first packet as keyframe

            }

        } else if (st->codec->codec_id == CODEC_ID_AAC) {

            int x;

            rm->audio_stream_num = st->index;

            ast->sub_packet_cnt = (get_be16(pb) & 0xf0) >> 4;

            if (ast->sub_packet_cnt) {

                for (x = 0; x < ast->sub_packet_cnt; x++)

                    ast->sub_packet_lengths[x] = get_be16(pb);

                // Release first audio packet

                rm->audio_pkt_cnt = ast->sub_packet_cnt - 1;

                av_get_packet(pb, pkt, ast->sub_packet_lengths[0]);

                *flags = 2; // Mark first packet as keyframe

            }

        } else {

            av_get_packet(pb, pkt, len);

            rm_ac3_swap_bytes(st, pkt);

        }

    } else

        av_get_packet(pb, pkt, len);



    if(  (st->discard >= AVDISCARD_NONKEY && !(*flags&2))

       || st->discard >= AVDISCARD_ALL){

        av_free_packet(pkt);

        return -1;

    }



    pkt->stream_index = st->index;



#if 0

    if (st->codec->codec_type == CODEC_TYPE_VIDEO) {

        if(st->codec->codec_id == CODEC_ID_RV20){

            int seq= 128*(pkt->data[2]&0x7F) + (pkt->data[3]>>1);

            av_log(s, AV_LOG_DEBUG, "%d %"PRId64" %d\n", *timestamp, *timestamp*512LL/25, seq);



            seq |= (*timestamp&~0x3FFF);

            if(seq - *timestamp >  0x2000) seq -= 0x4000;

            if(seq - *timestamp < -0x2000) seq += 0x4000;

        }

    }

#endif



    pkt->pts= *timestamp;

    if (*flags & 2)

        pkt->flags |= PKT_FLAG_KEY;



    return st->codec->codec_type == CODEC_TYPE_AUDIO ? rm->audio_pkt_cnt : 0;

}

static int hda_audio_post_load(void *opaque, int version)

{

    HDAAudioState *a = opaque;

    HDAAudioStream *st;

    int i;



    dprint(a, 1, "%s\n", __FUNCTION__);

    if (version == 1) {

        /* assume running_compat[] is for output streams */

        for (i = 0; i < ARRAY_SIZE(a->running_compat); i++)

            a->running_real[16 + i] = a->running_compat[i];

    }



    for (i = 0; i < ARRAY_SIZE(a->st); i++) {

        st = a->st + i;

        if (st->node == NULL)

            continue;

        hda_codec_parse_fmt(st->format, &st->as);

        hda_audio_setup(st);

        hda_audio_set_amp(st);

        hda_audio_set_running(st, a->running_real[st->output * 16 + st->stream]);

    }

    return 0;

}

static int http_connect(URLContext *h, const char *path, const char *hoststr)

{

    HTTPContext *s = h->priv_data;

    int post, err, ch;

    char line[1024], *q;





    /* send http header */

    post = h->flags & URL_WRONLY;



    snprintf(s->buffer, sizeof(s->buffer),

             "%s %s HTTP/1.0\r\n"

             "User-Agent: %s\r\n"

             "Accept: */*\r\n"

             "Host: %s\r\n"

             "\r\n",

             post ? "POST" : "GET",

             path,

             LIBAVFORMAT_IDENT,

             hoststr);



    if (http_write(h, s->buffer, strlen(s->buffer)) < 0)

        return AVERROR_IO;



    /* init input buffer */

    s->buf_ptr = s->buffer;

    s->buf_end = s->buffer;

    s->line_count = 0;

    s->location[0] = '\0';

    if (post) {

        sleep(1);

        return 0;

    }



    /* wait for header */

    q = line;

    for(;;) {

        ch = http_getc(s);

        if (ch < 0)

            return AVERROR_IO;

        if (ch == '\n') {

            /* process line */

            if (q > line && q[-1] == '\r')

                q--;

            *q = '\0';

#ifdef DEBUG

            printf("header='%s'\n", line);

#endif

            err = process_line(s, line, s->line_count);

            if (err < 0)

                return err;

            if (err == 0)

                return 0;

            s->line_count++;

            q = line;

        } else {

            if ((q - line) < sizeof(line) - 1)

                *q++ = ch;

        }

    }

}

static int qemu_signal_init(void)

{

    int sigfd;

    sigset_t set;



#ifdef CONFIG_IOTHREAD

    /* SIGUSR2 used by posix-aio-compat.c */

    sigemptyset(&set);

    sigaddset(&set, SIGUSR2);

    pthread_sigmask(SIG_UNBLOCK, &set, NULL);



    /*

     * SIG_IPI must be blocked in the main thread and must not be caught

     * by sigwait() in the signal thread. Otherwise, the cpu thread will

     * not catch it reliably.

     */

    sigemptyset(&set);

    sigaddset(&set, SIG_IPI);

    pthread_sigmask(SIG_BLOCK, &set, NULL);



    sigemptyset(&set);

    sigaddset(&set, SIGIO);

    sigaddset(&set, SIGALRM);

    sigaddset(&set, SIGBUS);

#else

    sigemptyset(&set);

    sigaddset(&set, SIGBUS);

    if (kvm_enabled()) {

        /*

         * We need to process timer signals synchronously to avoid a race

         * between exit_request check and KVM vcpu entry.

         */

        sigaddset(&set, SIGIO);

        sigaddset(&set, SIGALRM);

    }

#endif

    pthread_sigmask(SIG_BLOCK, &set, NULL);



    sigfd = qemu_signalfd(&set);

    if (sigfd == -1) {

        fprintf(stderr, "failed to create signalfd\n");

        return -errno;

    }



    fcntl_setfl(sigfd, O_NONBLOCK);



    qemu_set_fd_handler2(sigfd, NULL, sigfd_handler, NULL,

                         (void *)(intptr_t)sigfd);



    return 0;

}

