}

static av_cold int alac_encode_init(AVCodecContext *avctx)

{

    AlacEncodeContext *s = avctx->priv_data;

    int ret;

    uint8_t *alac_extradata;



    avctx->frame_size = s->frame_size = DEFAULT_FRAME_SIZE;



    if (avctx->sample_fmt != AV_SAMPLE_FMT_S16) {

        av_log(avctx, AV_LOG_ERROR, "only pcm_s16 input samples are supported\n");

        return -1;

    }



    /* TODO: Correctly implement multi-channel ALAC.

             It is similar to multi-channel AAC, in that it has a series of

             single-channel (SCE), channel-pair (CPE), and LFE elements. */

    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "only mono or stereo input is currently supported\n");

        return AVERROR_PATCHWELCOME;

    }



    // Set default compression level

    if (avctx->compression_level == FF_COMPRESSION_DEFAULT)

        s->compression_level = 2;

    else

        s->compression_level = av_clip(avctx->compression_level, 0, 2);



    // Initialize default Rice parameters

    s->rc.history_mult    = 40;

    s->rc.initial_history = 10;

    s->rc.k_modifier      = 14;

    s->rc.rice_modifier   = 4;



    s->max_coded_frame_size = get_max_frame_size(avctx->frame_size,

                                                 avctx->channels,

                                                 DEFAULT_SAMPLE_SIZE);



    // FIXME: consider wasted_bytes

    s->write_sample_size  = DEFAULT_SAMPLE_SIZE + avctx->channels - 1;



    avctx->extradata = av_mallocz(ALAC_EXTRADATA_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!avctx->extradata) {

        ret = AVERROR(ENOMEM);

        goto error;

    }

    avctx->extradata_size = ALAC_EXTRADATA_SIZE;



    alac_extradata = avctx->extradata;

    AV_WB32(alac_extradata,    ALAC_EXTRADATA_SIZE);

    AV_WB32(alac_extradata+4,  MKBETAG('a','l','a','c'));

    AV_WB32(alac_extradata+12, avctx->frame_size);

    AV_WB8 (alac_extradata+17, DEFAULT_SAMPLE_SIZE);

    AV_WB8 (alac_extradata+21, avctx->channels);

    AV_WB32(alac_extradata+24, s->max_coded_frame_size);

    AV_WB32(alac_extradata+28,

            avctx->sample_rate * avctx->channels * DEFAULT_SAMPLE_SIZE); // average bitrate

    AV_WB32(alac_extradata+32, avctx->sample_rate);



    // Set relevant extradata fields

    if (s->compression_level > 0) {

        AV_WB8(alac_extradata+18, s->rc.history_mult);

        AV_WB8(alac_extradata+19, s->rc.initial_history);

        AV_WB8(alac_extradata+20, s->rc.k_modifier);

    }



    s->min_prediction_order = DEFAULT_MIN_PRED_ORDER;

    if (avctx->min_prediction_order >= 0) {

        if (avctx->min_prediction_order < MIN_LPC_ORDER ||

           avctx->min_prediction_order > ALAC_MAX_LPC_ORDER) {

            av_log(avctx, AV_LOG_ERROR, "invalid min prediction order: %d\n",

                   avctx->min_prediction_order);

            ret = AVERROR(EINVAL);

            goto error;

        }



        s->min_prediction_order = avctx->min_prediction_order;

    }



    s->max_prediction_order = DEFAULT_MAX_PRED_ORDER;

    if (avctx->max_prediction_order >= 0) {

        if (avctx->max_prediction_order < MIN_LPC_ORDER ||

            avctx->max_prediction_order > ALAC_MAX_LPC_ORDER) {

            av_log(avctx, AV_LOG_ERROR, "invalid max prediction order: %d\n",

                   avctx->max_prediction_order);

            ret = AVERROR(EINVAL);

            goto error;

        }



        s->max_prediction_order = avctx->max_prediction_order;

    }



    if (s->max_prediction_order < s->min_prediction_order) {

        av_log(avctx, AV_LOG_ERROR,

               "invalid prediction orders: min=%d max=%d\n",

               s->min_prediction_order, s->max_prediction_order);

        ret = AVERROR(EINVAL);

        goto error;

    }



    avctx->coded_frame = avcodec_alloc_frame();

    if (!avctx->coded_frame) {

        ret = AVERROR(ENOMEM);

        goto error;

    }



    s->avctx = avctx;



    if ((ret = ff_lpc_init(&s->lpc_ctx, avctx->frame_size,

                           s->max_prediction_order,

                           FF_LPC_TYPE_LEVINSON)) < 0) {

        goto error;

    }



    return 0;

error:

    alac_encode_close(avctx);

    return ret;

}

make_setup_request (AVFormatContext *s, const char *host, int port,

                    int lower_transport, const char *real_challenge)

{

    RTSPState *rt = s->priv_data;

    int rtx, j, i, err, interleave = 0;

    RTSPStream *rtsp_st;

    RTSPMessageHeader reply1, *reply = &reply1;

    char cmd[2048];

    const char *trans_pref;



    if (rt->transport == RTSP_TRANSPORT_RDT)

        trans_pref = "x-pn-tng";

    else

        trans_pref = "RTP/AVP";



    /* default timeout: 1 minute */

    rt->timeout = 60;



    /* for each stream, make the setup request */

    /* XXX: we assume the same server is used for the control of each

       RTSP stream */



    for(j = RTSP_RTP_PORT_MIN, i = 0; i < rt->nb_rtsp_streams; ++i) {

        char transport[2048];



        /**

         * WMS serves all UDP data over a single connection, the RTX, which

         * isn't necessarily the first in the SDP but has to be the first

         * to be set up, else the second/third SETUP will fail with a 461.

         */

        if (lower_transport == RTSP_LOWER_TRANSPORT_UDP &&

             rt->server_type == RTSP_SERVER_WMS) {

            if (i == 0) {

                /* rtx first */

                for (rtx = 0; rtx < rt->nb_rtsp_streams; rtx++) {

                    int len = strlen(rt->rtsp_streams[rtx]->control_url);

                    if (len >= 4 &&

                        !strcmp(rt->rtsp_streams[rtx]->control_url + len - 4, "/rtx"))

                        break;

                }

                if (rtx == rt->nb_rtsp_streams)

                    return -1; /* no RTX found */

                rtsp_st = rt->rtsp_streams[rtx];

            } else

                rtsp_st = rt->rtsp_streams[i > rtx ? i : i - 1];

        } else

            rtsp_st = rt->rtsp_streams[i];



        /* RTP/UDP */

        if (lower_transport == RTSP_LOWER_TRANSPORT_UDP) {

            char buf[256];



            if (rt->server_type == RTSP_SERVER_WMS && i > 1) {

                port = reply->transports[0].client_port_min;

                goto have_port;

            }



            /* first try in specified port range */

            if (RTSP_RTP_PORT_MIN != 0) {

                while(j <= RTSP_RTP_PORT_MAX) {

                    snprintf(buf, sizeof(buf), "rtp://%s?localport=%d", host, j);

                    j += 2; /* we will use two port by rtp stream (rtp and rtcp) */

                    if (url_open(&rtsp_st->rtp_handle, buf, URL_RDWR) == 0) {

                        goto rtp_opened;

                    }

                }

            }



/*            then try on any port

**            if (url_open(&rtsp_st->rtp_handle, "rtp://", URL_RDONLY) < 0) {

**                err = AVERROR_INVALIDDATA;

**                goto fail;

**            }

*/



        rtp_opened:

            port = rtp_get_local_port(rtsp_st->rtp_handle);

        have_port:

            snprintf(transport, sizeof(transport) - 1,

                     "%s/UDP;", trans_pref);

            if (rt->server_type != RTSP_SERVER_REAL)

                av_strlcat(transport, "unicast;", sizeof(transport));

            av_strlcatf(transport, sizeof(transport),

                     "client_port=%d", port);

            if (rt->transport == RTSP_TRANSPORT_RTP &&

                !(rt->server_type == RTSP_SERVER_WMS && i > 0))

                av_strlcatf(transport, sizeof(transport), "-%d", port + 1);

        }



        /* RTP/TCP */

        else if (lower_transport == RTSP_LOWER_TRANSPORT_TCP) {

            /** For WMS streams, the application streams are only used for

             * UDP. When trying to set it up for TCP streams, the server

             * will return an error. Therefore, we skip those streams. */

            if (rt->server_type == RTSP_SERVER_WMS &&

                s->streams[rtsp_st->stream_index]->codec->codec_type == CODEC_TYPE_DATA)

                continue;

            snprintf(transport, sizeof(transport) - 1,

                     "%s/TCP;", trans_pref);

            if (rt->server_type == RTSP_SERVER_WMS)

                av_strlcat(transport, "unicast;", sizeof(transport));

            av_strlcatf(transport, sizeof(transport),

                        "interleaved=%d-%d",

                        interleave, interleave + 1);

            interleave += 2;

        }



        else if (lower_transport == RTSP_LOWER_TRANSPORT_UDP_MULTICAST) {

            snprintf(transport, sizeof(transport) - 1,

                     "%s/UDP;multicast", trans_pref);

        }

        if (rt->server_type == RTSP_SERVER_REAL ||

            rt->server_type == RTSP_SERVER_WMS)

            av_strlcat(transport, ";mode=play", sizeof(transport));

        snprintf(cmd, sizeof(cmd),

                 "SETUP %s RTSP/1.0\r\n"

                 "Transport: %s\r\n",

                 rtsp_st->control_url, transport);

        if (i == 0 && rt->server_type == RTSP_SERVER_REAL) {

            char real_res[41], real_csum[9];

            ff_rdt_calc_response_and_checksum(real_res, real_csum,

                                              real_challenge);

            av_strlcatf(cmd, sizeof(cmd),

                        "If-Match: %s\r\n"

                        "RealChallenge2: %s, sd=%s\r\n",

                        rt->session_id, real_res, real_csum);

        }

        rtsp_send_cmd(s, cmd, reply, NULL);

        if (reply->status_code == 461 /* Unsupported protocol */ && i == 0) {

            err = 1;

            goto fail;

        } else if (reply->status_code != RTSP_STATUS_OK ||

                   reply->nb_transports != 1) {

            err = AVERROR_INVALIDDATA;

            goto fail;

        }



        /* XXX: same protocol for all streams is required */

        if (i > 0) {

            if (reply->transports[0].lower_transport != rt->lower_transport ||

                reply->transports[0].transport != rt->transport) {

                err = AVERROR_INVALIDDATA;

                goto fail;

            }

        } else {

            rt->lower_transport = reply->transports[0].lower_transport;

            rt->transport = reply->transports[0].transport;

        }



        /* close RTP connection if not choosen */

        if (reply->transports[0].lower_transport != RTSP_LOWER_TRANSPORT_UDP &&

            (lower_transport == RTSP_LOWER_TRANSPORT_UDP)) {

            url_close(rtsp_st->rtp_handle);

            rtsp_st->rtp_handle = NULL;

        }



        switch(reply->transports[0].lower_transport) {

        case RTSP_LOWER_TRANSPORT_TCP:

            rtsp_st->interleaved_min = reply->transports[0].interleaved_min;

            rtsp_st->interleaved_max = reply->transports[0].interleaved_max;

            break;



        case RTSP_LOWER_TRANSPORT_UDP:

            {

                char url[1024];



                /* XXX: also use address if specified */

                snprintf(url, sizeof(url), "rtp://%s:%d",

                         host, reply->transports[0].server_port_min);

                if (!(rt->server_type == RTSP_SERVER_WMS && i > 1) &&

                    rtp_set_remote_url(rtsp_st->rtp_handle, url) < 0) {

                    err = AVERROR_INVALIDDATA;

                    goto fail;

                }

            }

            break;

        case RTSP_LOWER_TRANSPORT_UDP_MULTICAST:

            {

                char url[1024];

                struct in_addr in;

                int port, ttl;



                if (reply->transports[0].destination) {

                    in.s_addr = htonl(reply->transports[0].destination);

                    port      = reply->transports[0].port_min;

                    ttl       = reply->transports[0].ttl;

                } else {

                    in        = rtsp_st->sdp_ip;

                    port      = rtsp_st->sdp_port;

                    ttl       = rtsp_st->sdp_ttl;

                }

                snprintf(url, sizeof(url), "rtp://%s:%d?ttl=%d",

                         inet_ntoa(in), port, ttl);

                if (url_open(&rtsp_st->rtp_handle, url, URL_RDWR) < 0) {

                    err = AVERROR_INVALIDDATA;

                    goto fail;

                }

            }

            break;

        }



        if ((err = rtsp_open_transport_ctx(s, rtsp_st)))

            goto fail;

    }



    if (reply->timeout > 0)

        rt->timeout = reply->timeout;



    if (rt->server_type == RTSP_SERVER_REAL)

        rt->need_subscription = 1;



    return 0;



fail:

    for (i=0; i<rt->nb_rtsp_streams; i++) {

        if (rt->rtsp_streams[i]->rtp_handle) {

            url_close(rt->rtsp_streams[i]->rtp_handle);

            rt->rtsp_streams[i]->rtp_handle = NULL;

        }

    }

    return err;

}

ff_rm_parse_packet (AVFormatContext *s, AVIOContext *pb,

                    AVStream *st, RMStream *ast, int len, AVPacket *pkt,

                    int *seq, int flags, int64_t timestamp)

{

    RMDemuxContext *rm = s->priv_data;

    int ret;



    if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        rm->current_stream= st->id;

        ret = rm_assemble_video_frame(s, pb, rm, ast, pkt, len, seq, &timestamp);

        if(ret)

            return ret < 0 ? ret : -1; //got partial frame or error

    } else if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO) {

        if ((ast->deint_id == DEINT_ID_GENR) ||

            (ast->deint_id == DEINT_ID_INT4) ||

            (ast->deint_id == DEINT_ID_SIPR)) {

            int x;

            int sps = ast->sub_packet_size;

            int cfs = ast->coded_framesize;

            int h = ast->sub_packet_h;

            int y = ast->sub_packet_cnt;

            int w = ast->audio_framesize;



            if (flags & 2)

                y = ast->sub_packet_cnt = 0;

            if (!y)

                ast->audiotimestamp = timestamp;



            switch (ast->deint_id) {

                case DEINT_ID_INT4:

                    for (x = 0; x < h/2; x++)

                        readfull(s, pb, ast->pkt.data+x*2*w+y*cfs, cfs);

                    break;

                case DEINT_ID_GENR:

                    for (x = 0; x < w/sps; x++)

                        readfull(s, pb, ast->pkt.data+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), sps);

                    break;

                case DEINT_ID_SIPR:

                    readfull(s, pb, ast->pkt.data + y * w, w);

                    break;

            }



            if (++(ast->sub_packet_cnt) < h)

                return -1;

            if (ast->deint_id == DEINT_ID_SIPR)

                ff_rm_reorder_sipr_data(ast->pkt.data, h, w);



             ast->sub_packet_cnt = 0;

             rm->audio_stream_num = st->index;

             rm->audio_pkt_cnt = h * w / st->codec->block_align;

        } else if ((ast->deint_id == DEINT_ID_VBRF) ||

                   (ast->deint_id == DEINT_ID_VBRS)) {

            int x;

            rm->audio_stream_num = st->index;

            ast->sub_packet_cnt = (avio_rb16(pb) & 0xf0) >> 4;

            if (ast->sub_packet_cnt) {

                for (x = 0; x < ast->sub_packet_cnt; x++)

                    ast->sub_packet_lengths[x] = avio_rb16(pb);

                rm->audio_pkt_cnt = ast->sub_packet_cnt;

                ast->audiotimestamp = timestamp;

            } else

                return -1;

        } else {

            av_get_packet(pb, pkt, len);

            rm_ac3_swap_bytes(st, pkt);

        }

    } else

        av_get_packet(pb, pkt, len);



    pkt->stream_index = st->index;



#if 0

    if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO) {

        if(st->codec->codec_id == AV_CODEC_ID_RV20){

            int seq= 128*(pkt->data[2]&0x7F) + (pkt->data[3]>>1);

            av_log(s, AV_LOG_DEBUG, "%d %"PRId64" %d\n", *timestamp, *timestamp*512LL/25, seq);



            seq |= (timestamp&~0x3FFF);

            if(seq - timestamp >  0x2000) seq -= 0x4000;

            if(seq - timestamp < -0x2000) seq += 0x4000;

        }

    }

#endif



    pkt->pts = timestamp;

    if (flags & 2)

        pkt->flags |= AV_PKT_FLAG_KEY;



    return st->codec->codec_type == AVMEDIA_TYPE_AUDIO ? rm->audio_pkt_cnt : 0;

}

static uint32_t mb_add_cmdline(MultibootState *s, const char *cmdline)

{

    target_phys_addr_t p = s->offset_cmdlines;

    char *b = (char *)s->mb_buf + p;



    get_opt_value(b, strlen(cmdline) + 1, cmdline);

    s->offset_cmdlines += strlen(b) + 1;

    return s->mb_buf_phys + p;

}

static void find_best_tables(MpegEncContext * s)

{

    int i;

    int best       =-1, best_size       =9999999;

    int chroma_best=-1, best_chroma_size=9999999;



    for(i=0; i<3; i++){

        int level;

        int chroma_size=0;

        int size=0;



        if(i>0){// ;)

            size++;

            chroma_size++;

        }

        for(level=0; level<=MAX_LEVEL; level++){

            int run;

            for(run=0; run<=MAX_RUN; run++){

                int last;

                const int last_size= size + chroma_size;

                for(last=0; last<2; last++){

                    int inter_count       = s->ac_stats[0][0][level][run][last] + s->ac_stats[0][1][level][run][last];

                    int intra_luma_count  = s->ac_stats[1][0][level][run][last];

                    int intra_chroma_count= s->ac_stats[1][1][level][run][last];



                    if(s->pict_type==AV_PICTURE_TYPE_I){

                        size       += intra_luma_count  *rl_length[i  ][level][run][last];

                        chroma_size+= intra_chroma_count*rl_length[i+3][level][run][last];

                    }else{

                        size+=        intra_luma_count  *rl_length[i  ][level][run][last]

                                     +intra_chroma_count*rl_length[i+3][level][run][last]

                                     +inter_count       *rl_length[i+3][level][run][last];

                    }

                }

                if(last_size == size+chroma_size) break;

            }

        }

        if(size<best_size){

            best_size= size;

            best= i;

        }

        if(chroma_size<best_chroma_size){

            best_chroma_size= chroma_size;

            chroma_best= i;

        }

    }



//    printf("type:%d, best:%d, qp:%d, var:%d, mcvar:%d, size:%d //\n",

//           s->pict_type, best, s->qscale, s->mb_var_sum, s->mc_mb_var_sum, best_size);



    if(s->pict_type==AV_PICTURE_TYPE_P) chroma_best= best;



    memset(s->ac_stats, 0, sizeof(int)*(MAX_LEVEL+1)*(MAX_RUN+1)*2*2*2);



    s->rl_table_index       =        best;

    s->rl_chroma_table_index= chroma_best;



    if(s->pict_type != s->last_non_b_pict_type){

        s->rl_table_index= 2;

        if(s->pict_type==AV_PICTURE_TYPE_I)

            s->rl_chroma_table_index= 1;

        else

            s->rl_chroma_table_index= 2;

    }



}

static void qmp_deserialize(void **native_out, void *datap,

                            VisitorFunc visit, Error **errp)

{

    QmpSerializeData *d = datap;

    QString *output_json = qobject_to_json(qmp_output_get_qobject(d->qov));

    QObject *obj = qobject_from_json(qstring_get_str(output_json));



    QDECREF(output_json);

    d->qiv = qmp_input_visitor_new(obj);

    qobject_decref(obj);

    visit(qmp_input_get_visitor(d->qiv), native_out, errp);

}

static void fill_table(uint8_t* table[256 + 2*YUVRGB_TABLE_HEADROOM], const int elemsize,

                       const int inc, void *y_tab)

{

    int i;

    uint8_t *y_table = y_tab;



    y_table -= elemsize * (inc >> 9);



    for (i = 0; i < 256 + 2*YUVRGB_TABLE_HEADROOM; i++) {

        int64_t cb = av_clip(i-YUVRGB_TABLE_HEADROOM, 0, 255)*inc;

        table[i] = y_table + elemsize * (cb >> 16);

    }

}

static void build_udp_url(char *buf, int buf_size,

                          const char *hostname, int port,

                          int local_port, int ttl)

{

    snprintf(buf, buf_size, "udp://%s:%d", hostname, port);

    if (local_port >= 0)

        url_add_option(buf, buf_size, "localport=%d", local_port);

    if (ttl >= 0)

        url_add_option(buf, buf_size, "ttl=%d", ttl);

}

static int dct_quantize_refine(MpegEncContext *s, //FIXME breaks denoise?

                        DCTELEM *block, int16_t *weight, DCTELEM *orig,

                        int n, int qscale){

    int16_t rem[64];

    DCTELEM d1[64];

    const int *qmat;

    const uint8_t *scantable= s->intra_scantable.scantable;

    const uint8_t *perm_scantable= s->intra_scantable.permutated;

//    unsigned int threshold1, threshold2;

//    int bias=0;

    int run_tab[65];

    int prev_run=0;

    int prev_level=0;

    int qmul, qadd, start_i, last_non_zero, i, dc;

    uint8_t * length;

    uint8_t * last_length;

    int lambda;

    int rle_index, run, q, sum;

#ifdef REFINE_STATS

static int count=0;

static int after_last=0;

static int to_zero=0;

static int from_zero=0;

static int raise=0;

static int lower=0;

static int messed_sign=0;

#endif



    if(basis[0][0] == 0)

        build_basis(s->dsp.idct_permutation);



    qmul= qscale*2;

    qadd= (qscale-1)|1;

    if (s->mb_intra) {

        if (!s->h263_aic) {

            if (n < 4)

                q = s->y_dc_scale;

            else

                q = s->c_dc_scale;

        } else{

            /* For AIC we skip quant/dequant of INTRADC */

            q = 1;

            qadd=0;

        }

        q <<= RECON_SHIFT-3;

        /* note: block[0] is assumed to be positive */

        dc= block[0]*q;

//        block[0] = (block[0] + (q >> 1)) / q;

        start_i = 1;

        qmat = s->q_intra_matrix[qscale];

//        if(s->mpeg_quant || s->out_format == FMT_MPEG1)

//            bias= 1<<(QMAT_SHIFT-1);

        length     = s->intra_ac_vlc_length;

        last_length= s->intra_ac_vlc_last_length;

    } else {

        dc= 0;

        start_i = 0;

        qmat = s->q_inter_matrix[qscale];

        length     = s->inter_ac_vlc_length;

        last_length= s->inter_ac_vlc_last_length;

    }

    last_non_zero = s->block_last_index[n];



#ifdef REFINE_STATS

{START_TIMER

#endif

    dc += (1<<(RECON_SHIFT-1));

    for(i=0; i<64; i++){

        rem[i]= dc - (orig[i]<<RECON_SHIFT); //FIXME  use orig dirrectly insteadof copying to rem[]

    }

#ifdef REFINE_STATS

STOP_TIMER("memset rem[]")}

#endif

    sum=0;

    for(i=0; i<64; i++){

        int one= 36;

        int qns=4;

        int w;



        w= ABS(weight[i]) + qns*one;

        w= 15 + (48*qns*one + w/2)/w; // 16 .. 63



        weight[i] = w;

//        w=weight[i] = (63*qns + (w/2)) / w;



        assert(w>0);

        assert(w<(1<<6));

        sum += w*w;

    }

    lambda= sum*(uint64_t)s->lambda2 >> (FF_LAMBDA_SHIFT - 6 + 6 + 6 + 6);

#ifdef REFINE_STATS

{START_TIMER

#endif

    run=0;

    rle_index=0;

    for(i=start_i; i<=last_non_zero; i++){

        int j= perm_scantable[i];

        const int level= block[j];

        int coeff;



        if(level){

            if(level<0) coeff= qmul*level - qadd;

            else        coeff= qmul*level + qadd;

            run_tab[rle_index++]=run;

            run=0;



            s->dsp.add_8x8basis(rem, basis[j], coeff);

        }else{

            run++;

        }

    }

#ifdef REFINE_STATS

if(last_non_zero>0){

STOP_TIMER("init rem[]")

}

}



{START_TIMER

#endif

    for(;;){

        int best_score=s->dsp.try_8x8basis(rem, weight, basis[0], 0);

        int best_coeff=0;

        int best_change=0;

        int run2, best_unquant_change=0, analyze_gradient;

#ifdef REFINE_STATS

{START_TIMER

#endif

        analyze_gradient = last_non_zero > 2 || s->avctx->quantizer_noise_shaping >= 3;



        if(analyze_gradient){

#ifdef REFINE_STATS

{START_TIMER

#endif

            for(i=0; i<64; i++){

                int w= weight[i];



                d1[i] = (rem[i]*w*w + (1<<(RECON_SHIFT+12-1)))>>(RECON_SHIFT+12);

            }

#ifdef REFINE_STATS

STOP_TIMER("rem*w*w")}

{START_TIMER

#endif

            s->dsp.fdct(d1);

#ifdef REFINE_STATS

STOP_TIMER("dct")}

#endif

        }



        if(start_i){

            const int level= block[0];

            int change, old_coeff;



            assert(s->mb_intra);



            old_coeff= q*level;



            for(change=-1; change<=1; change+=2){

                int new_level= level + change;

                int score, new_coeff;



                new_coeff= q*new_level;

                if(new_coeff >= 2048 || new_coeff < 0)

                    continue;



                score= s->dsp.try_8x8basis(rem, weight, basis[0], new_coeff - old_coeff);

                if(score<best_score){

                    best_score= score;

                    best_coeff= 0;

                    best_change= change;

                    best_unquant_change= new_coeff - old_coeff;

                }

            }

        }



        run=0;

        rle_index=0;

        run2= run_tab[rle_index++];

        prev_level=0;

        prev_run=0;



        for(i=start_i; i<64; i++){

            int j= perm_scantable[i];

            const int level= block[j];

            int change, old_coeff;



            if(s->avctx->quantizer_noise_shaping < 3 && i > last_non_zero + 1)

                break;



            if(level){

                if(level<0) old_coeff= qmul*level - qadd;

                else        old_coeff= qmul*level + qadd;

                run2= run_tab[rle_index++]; //FIXME ! maybe after last

            }else{

                old_coeff=0;

                run2--;

                assert(run2>=0 || i >= last_non_zero );

            }



            for(change=-1; change<=1; change+=2){

                int new_level= level + change;

                int score, new_coeff, unquant_change;



                score=0;

                if(s->avctx->quantizer_noise_shaping < 2 && ABS(new_level) > ABS(level))

                   continue;



                if(new_level){

                    if(new_level<0) new_coeff= qmul*new_level - qadd;

                    else            new_coeff= qmul*new_level + qadd;

                    if(new_coeff >= 2048 || new_coeff <= -2048)

                        continue;

                    //FIXME check for overflow



                    if(level){

                        if(level < 63 && level > -63){

                            if(i < last_non_zero)

                                score +=   length[UNI_AC_ENC_INDEX(run, new_level+64)]

                                         - length[UNI_AC_ENC_INDEX(run, level+64)];

                            else

                                score +=   last_length[UNI_AC_ENC_INDEX(run, new_level+64)]

                                         - last_length[UNI_AC_ENC_INDEX(run, level+64)];

                        }

                    }else{

                        assert(ABS(new_level)==1);



                        if(analyze_gradient){

                            int g= d1[ scantable[i] ];

                            if(g && (g^new_level) >= 0)

                                continue;

                        }



                        if(i < last_non_zero){

                            int next_i= i + run2 + 1;

                            int next_level= block[ perm_scantable[next_i] ] + 64;



                            if(next_level&(~127))

                                next_level= 0;



                            if(next_i < last_non_zero)

                                score +=   length[UNI_AC_ENC_INDEX(run, 65)]

                                         + length[UNI_AC_ENC_INDEX(run2, next_level)]

                                         - length[UNI_AC_ENC_INDEX(run + run2 + 1, next_level)];

                            else

                                score +=  length[UNI_AC_ENC_INDEX(run, 65)]

                                        + last_length[UNI_AC_ENC_INDEX(run2, next_level)]

                                        - last_length[UNI_AC_ENC_INDEX(run + run2 + 1, next_level)];

                        }else{

                            score += last_length[UNI_AC_ENC_INDEX(run, 65)];

                            if(prev_level){

                                score +=  length[UNI_AC_ENC_INDEX(prev_run, prev_level)]

                                        - last_length[UNI_AC_ENC_INDEX(prev_run, prev_level)];

                            }

                        }

                    }

                }else{

                    new_coeff=0;

                    assert(ABS(level)==1);



                    if(i < last_non_zero){

                        int next_i= i + run2 + 1;

                        int next_level= block[ perm_scantable[next_i] ] + 64;



                        if(next_level&(~127))

                            next_level= 0;



                        if(next_i < last_non_zero)

                            score +=   length[UNI_AC_ENC_INDEX(run + run2 + 1, next_level)]

                                     - length[UNI_AC_ENC_INDEX(run2, next_level)]

                                     - length[UNI_AC_ENC_INDEX(run, 65)];

                        else

                            score +=   last_length[UNI_AC_ENC_INDEX(run + run2 + 1, next_level)]

                                     - last_length[UNI_AC_ENC_INDEX(run2, next_level)]

                                     - length[UNI_AC_ENC_INDEX(run, 65)];

                    }else{

                        score += -last_length[UNI_AC_ENC_INDEX(run, 65)];

                        if(prev_level){

                            score +=  last_length[UNI_AC_ENC_INDEX(prev_run, prev_level)]

                                    - length[UNI_AC_ENC_INDEX(prev_run, prev_level)];

                        }

                    }

                }



                score *= lambda;



                unquant_change= new_coeff - old_coeff;

                assert((score < 100*lambda && score > -100*lambda) || lambda==0);



                score+= s->dsp.try_8x8basis(rem, weight, basis[j], unquant_change);

                if(score<best_score){

                    best_score= score;

                    best_coeff= i;

                    best_change= change;

                    best_unquant_change= unquant_change;

                }

            }

            if(level){

                prev_level= level + 64;

                if(prev_level&(~127))

                    prev_level= 0;

                prev_run= run;

                run=0;

            }else{

                run++;

            }

        }

#ifdef REFINE_STATS

STOP_TIMER("iterative step")}

#endif



        if(best_change){

            int j= perm_scantable[ best_coeff ];



            block[j] += best_change;



            if(best_coeff > last_non_zero){

                last_non_zero= best_coeff;

                assert(block[j]);

#ifdef REFINE_STATS

after_last++;

#endif

            }else{

#ifdef REFINE_STATS

if(block[j]){

    if(block[j] - best_change){

        if(ABS(block[j]) > ABS(block[j] - best_change)){

            raise++;

        }else{

            lower++;

        }

    }else{

        from_zero++;

    }

}else{

    to_zero++;

}

#endif

                for(; last_non_zero>=start_i; last_non_zero--){

                    if(block[perm_scantable[last_non_zero]])

                        break;

                }

            }

#ifdef REFINE_STATS

count++;

if(256*256*256*64 % count == 0){

    printf("after_last:%d to_zero:%d from_zero:%d raise:%d lower:%d sign:%d xyp:%d/%d/%d\n", after_last, to_zero, from_zero, raise, lower, messed_sign, s->mb_x, s->mb_y, s->picture_number);

}

#endif

            run=0;

            rle_index=0;

            for(i=start_i; i<=last_non_zero; i++){

                int j= perm_scantable[i];

                const int level= block[j];



                 if(level){

                     run_tab[rle_index++]=run;

                     run=0;

                 }else{

                     run++;

                 }

            }



            s->dsp.add_8x8basis(rem, basis[j], best_unquant_change);

        }else{

            break;

        }

    }

#ifdef REFINE_STATS

if(last_non_zero>0){

STOP_TIMER("iterative search")

}

}

#endif



    return last_non_zero;

}

static int nut_write_header(AVFormatContext * avf) {

    NUTContext * priv = avf->priv_data;

    AVIOContext * bc = avf->pb;

    nut_muxer_opts_tt mopts = {

        .output = {

            .priv = bc,

            .write = av_write,

        },

        .alloc = { av_malloc, av_realloc, av_free },

        .write_index = 1,

        .realtime_stream = 0,

        .max_distance = 32768,

        .fti = NULL,

    };

    nut_stream_header_tt * s;

    int i;



    priv->s = s = av_mallocz((avf->nb_streams + 1) * sizeof*s);





    for (i = 0; i < avf->nb_streams; i++) {

        AVCodecContext * codec = avf->streams[i]->codec;

        int j;

        int fourcc = 0;

        int num, denom, ssize;



        s[i].type = codec->codec_type == AVMEDIA_TYPE_VIDEO ? NUT_VIDEO_CLASS : NUT_AUDIO_CLASS;



        if (codec->codec_tag) fourcc = codec->codec_tag;

        else fourcc = ff_codec_get_tag(nut_tags, codec->codec_id);



        if (!fourcc) {

            if (codec->codec_type == AVMEDIA_TYPE_VIDEO) fourcc = ff_codec_get_tag(ff_codec_bmp_tags, codec->codec_id);

            if (codec->codec_type == AVMEDIA_TYPE_AUDIO) fourcc = ff_codec_get_tag(ff_codec_wav_tags, codec->codec_id);

        }



        s[i].fourcc_len = 4;

        s[i].fourcc = av_malloc(s[i].fourcc_len);

        for (j = 0; j < s[i].fourcc_len; j++) s[i].fourcc[j] = (fourcc >> (j*8)) & 0xFF;



        ff_parse_specific_params(codec, &num, &ssize, &denom);

        avpriv_set_pts_info(avf->streams[i], 60, denom, num);



        s[i].time_base.num = denom;

        s[i].time_base.den = num;



        s[i].fixed_fps = 0;

        s[i].decode_delay = codec->has_b_frames;

        s[i].codec_specific_len = codec->extradata_size;

        s[i].codec_specific = codec->extradata;



        if (codec->codec_type == AVMEDIA_TYPE_VIDEO) {

            s[i].width = codec->width;

            s[i].height = codec->height;

            s[i].sample_width = 0;

            s[i].sample_height = 0;

            s[i].colorspace_type = 0;

        } else {

            s[i].samplerate_num = codec->sample_rate;

            s[i].samplerate_denom = 1;

            s[i].channel_count = codec->channels;

        }

    }



    s[avf->nb_streams].type = -1;

    priv->nut = nut_muxer_init(&mopts, s, NULL);



    return 0;

}

static inline void memcpy_tofs(void * to, const void * from, unsigned long n)

{

	memcpy(to, from, n);

}

void net_slirp_hostfwd_remove(Monitor *mon, const QDict *qdict)

{

    struct in_addr host_addr = { .s_addr = INADDR_ANY };

    int host_port;

    char buf[256] = "";

    const char *src_str, *p;

    SlirpState *s;

    int is_udp = 0;

    int err;

    const char *arg1 = qdict_get_str(qdict, "arg1");

    const char *arg2 = qdict_get_try_str(qdict, "arg2");

    const char *arg3 = qdict_get_try_str(qdict, "arg3");



    if (arg2) {

        s = slirp_lookup(mon, arg1, arg2);

        src_str = arg3;

    } else {

        s = slirp_lookup(mon, NULL, NULL);

        src_str = arg1;

    }

    if (!s) {

        return;

    }



    if (!src_str || !src_str[0])

        goto fail_syntax;



    p = src_str;

    get_str_sep(buf, sizeof(buf), &p, ':');



    if (!strcmp(buf, "tcp") || buf[0] == '\0') {

        is_udp = 0;

    } else if (!strcmp(buf, "udp")) {

        is_udp = 1;

    } else {

        goto fail_syntax;

    }



    if (get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

        goto fail_syntax;

    }

    if (buf[0] != '\0' && !inet_aton(buf, &host_addr)) {

        goto fail_syntax;

    }



    host_port = atoi(p);



    err = slirp_remove_hostfwd(QTAILQ_FIRST(&slirp_stacks)->slirp, is_udp,

                               host_addr, host_port);



    monitor_printf(mon, "host forwarding rule for %s %s\n", src_str,

                   err ? "removed" : "not found");

    return;



 fail_syntax:

    monitor_printf(mon, "invalid format\n");

}

static uint64_t qvirtio_scsi_alloc(QVirtIOSCSI *vs, size_t alloc_size,

                                   const void *data)

{

    uint64_t addr;



    addr = guest_alloc(vs->alloc, alloc_size);

    if (data) {

        memwrite(addr, data, alloc_size);

    }



    return addr;

}

int av_parse_color(uint8_t *rgba_color, const char *color_string, void *log_ctx)

{

    if (!strcasecmp(color_string, "random") || !strcasecmp(color_string, "bikeshed")) {

        int rgba = ff_random_get_seed();

        rgba_color[0] = rgba >> 24;

        rgba_color[1] = rgba >> 16;

        rgba_color[2] = rgba >> 8;

        rgba_color[3] = rgba;

    } else

    if (!strncmp(color_string, "0x", 2)) {

        char *tail;

        int len = strlen(color_string);

        int rgba = strtol(color_string, &tail, 16);



        if (*tail || (len != 8 && len != 10)) {

            av_log(log_ctx, AV_LOG_ERROR, "Invalid 0xRRGGBB[AA] color string: '%s'\n", color_string);

            return -1;

        }

        if (len == 10) {

            rgba_color[3] = rgba;

            rgba >>= 8;

        }

        rgba_color[0] = rgba >> 16;

        rgba_color[1] = rgba >> 8;

        rgba_color[2] = rgba;

    } else {

        const ColorEntry *entry = bsearch(color_string,

                                          color_table,

                                          FF_ARRAY_ELEMS(color_table),

                                          sizeof(ColorEntry),

                                          color_table_compare);

        if (!entry) {

            av_log(log_ctx, AV_LOG_ERROR, "Cannot find color '%s'\n", color_string);

            return -1;

        }

        memcpy(rgba_color, entry->rgba_color, 4);

    }



    return 0;

}

void cpu_physical_memory_write_rom(hwaddr addr,

                                   const uint8_t *buf, int len)

{

    hwaddr l;

    uint8_t *ptr;

    hwaddr addr1;

    MemoryRegion *mr;



    while (len > 0) {

        l = len;

        mr = address_space_translate(&address_space_memory,

                                     addr, &addr1, &l, true);



        if (!(memory_region_is_ram(mr) ||

              memory_region_is_romd(mr))) {

            /* do nothing */

        } else {

            addr1 += memory_region_get_ram_addr(mr);

            /* ROM/RAM case */

            ptr = qemu_get_ram_ptr(addr1);

            memcpy(ptr, buf, l);

            invalidate_and_set_dirty(addr1, l);

        }

        len -= l;

        buf += l;

        addr += l;

    }

}

static void avc_luma_vt_4w_msa(const uint8_t *src, int32_t src_stride,

                               uint8_t *dst, int32_t dst_stride,

                               int32_t height)

{

    int32_t loop_cnt;

    int16_t filt_const0 = 0xfb01;

    int16_t filt_const1 = 0x1414;

    int16_t filt_const2 = 0x1fb;

    v16i8 src0, src1, src2, src3, src4, src5, src6, src7, src8;

    v16i8 src10_r, src32_r, src54_r, src76_r, src21_r, src43_r, src65_r;

    v16i8 src87_r, src2110, src4332, src6554, src8776;

    v16i8 filt0, filt1, filt2;

    v8i16 out10, out32;

    v16u8 out;



    filt0 = (v16i8) __msa_fill_h(filt_const0);

    filt1 = (v16i8) __msa_fill_h(filt_const1);

    filt2 = (v16i8) __msa_fill_h(filt_const2);



    LD_SB5(src, src_stride, src0, src1, src2, src3, src4);

    src += (5 * src_stride);



    ILVR_B4_SB(src1, src0, src2, src1, src3, src2, src4, src3,

               src10_r, src21_r, src32_r, src43_r);

    ILVR_D2_SB(src21_r, src10_r, src43_r, src32_r, src2110, src4332);

    XORI_B2_128_SB(src2110, src4332);



    for (loop_cnt = (height >> 2); loop_cnt--;) {

        LD_SB4(src, src_stride, src5, src6, src7, src8);

        src += (4 * src_stride);



        ILVR_B4_SB(src5, src4, src6, src5, src7, src6, src8, src7,

                   src54_r, src65_r, src76_r, src87_r);

        ILVR_D2_SB(src65_r, src54_r, src87_r, src76_r, src6554, src8776);

        XORI_B2_128_SB(src6554, src8776);

        out10 = DPADD_SH3_SH(src2110, src4332, src6554, filt0, filt1, filt2);

        out32 = DPADD_SH3_SH(src4332, src6554, src8776, filt0, filt1, filt2);

        SRARI_H2_SH(out10, out32, 5);

        SAT_SH2_SH(out10, out32, 7);

        out = PCKEV_XORI128_UB(out10, out32);

        ST4x4_UB(out, out, 0, 1, 2, 3, dst, dst_stride);



        dst += (4 * dst_stride);

        src2110 = src6554;

        src4332 = src8776;

        src4 = src8;

    }

}

static void spapr_add_lmbs(DeviceState *dev, uint64_t addr_start, uint64_t size,

                           uint32_t node, bool dedicated_hp_event_source,

                           Error **errp)

{

    sPAPRDRConnector *drc;

    uint32_t nr_lmbs = size/SPAPR_MEMORY_BLOCK_SIZE;

    int i, fdt_offset, fdt_size;

    void *fdt;

    uint64_t addr = addr_start;



    for (i = 0; i < nr_lmbs; i++) {

        drc = spapr_drc_by_id(TYPE_SPAPR_DRC_LMB,

                              addr / SPAPR_MEMORY_BLOCK_SIZE);

        g_assert(drc);



        fdt = create_device_tree(&fdt_size);

        fdt_offset = spapr_populate_memory_node(fdt, node, addr,

                                                SPAPR_MEMORY_BLOCK_SIZE);



        spapr_drc_attach(drc, dev, fdt, fdt_offset, !dev->hotplugged, errp);

        addr += SPAPR_MEMORY_BLOCK_SIZE;

        if (!dev->hotplugged) {

            sPAPRDRConnectorClass *drck = SPAPR_DR_CONNECTOR_GET_CLASS(drc);

            /* guests expect coldplugged LMBs to be pre-allocated */

            drck->set_allocation_state(drc, SPAPR_DR_ALLOCATION_STATE_USABLE);

            drck->set_isolation_state(drc, SPAPR_DR_ISOLATION_STATE_UNISOLATED);

        }

    }

    /* send hotplug notification to the

     * guest only in case of hotplugged memory

     */

    if (dev->hotplugged) {

        if (dedicated_hp_event_source) {

            drc = spapr_drc_by_id(TYPE_SPAPR_DRC_LMB,

                                  addr_start / SPAPR_MEMORY_BLOCK_SIZE);

            spapr_hotplug_req_add_by_count_indexed(SPAPR_DR_CONNECTOR_TYPE_LMB,

                                                   nr_lmbs,

                                                   spapr_drc_index(drc));

        } else {

            spapr_hotplug_req_add_by_count(SPAPR_DR_CONNECTOR_TYPE_LMB,

                                           nr_lmbs);

        }

    }

}

static void virtio_net_set_config(VirtIODevice *vdev, const uint8_t *config)

{

    VirtIONet *n = VIRTIO_NET(vdev);

    struct virtio_net_config netcfg = {};



    memcpy(&netcfg, config, n->config_size);



    if (!(vdev->guest_features >> VIRTIO_NET_F_CTRL_MAC_ADDR & 1) &&

        memcmp(netcfg.mac, n->mac, ETH_ALEN)) {

        memcpy(n->mac, netcfg.mac, ETH_ALEN);

        qemu_format_nic_info_str(qemu_get_queue(n->nic), n->mac);

    }

}

static int lag_decode_arith_plane(LagarithContext *l, uint8_t *dst,

                                  int width, int height, int stride,

                                  const uint8_t *src, int src_size)

{

    int i = 0;

    int read = 0;

    uint32_t length;

    uint32_t offset = 1;

    int esc_count;

    GetBitContext gb;

    lag_rac rac;

    const uint8_t *src_end = src + src_size;



    rac.avctx = l->avctx;

    l->zeros = 0;



    if(src_size < 2)

        return AVERROR_INVALIDDATA;



    esc_count = src[0];

    if (esc_count < 4) {

        length = width * height;

        if(src_size < 5)

            return AVERROR_INVALIDDATA;

        if (esc_count && AV_RL32(src + 1) < length) {

            length = AV_RL32(src + 1);

            offset += 4;

        }



        init_get_bits8(&gb, src + offset, src_size - offset);



        if (lag_read_prob_header(&rac, &gb) < 0)

            return -1;



        ff_lag_rac_init(&rac, &gb, length - stride);



        for (i = 0; i < height; i++)

            read += lag_decode_line(l, &rac, dst + (i * stride), width,

                                    stride, esc_count);



        if (read > length)

            av_log(l->avctx, AV_LOG_WARNING,

                   "Output more bytes than length (%d of %d)\n", read,

                   length);

    } else if (esc_count < 8) {

        esc_count -= 4;

        src ++;

        src_size --;

        if (esc_count > 0) {

            /* Zero run coding only, no range coding. */

            for (i = 0; i < height; i++) {

                int res = lag_decode_zero_run_line(l, dst + (i * stride), src,

                                                   src_end, width, esc_count);

                if (res < 0)

                    return res;

                src += res;

            }

        } else {

            if (src_size < width * height)

                return AVERROR_INVALIDDATA; // buffer not big enough

            /* Plane is stored uncompressed */

            for (i = 0; i < height; i++) {

                memcpy(dst + (i * stride), src, width);

                src += width;

            }

        }

    } else if (esc_count == 0xff) {

        /* Plane is a solid run of given value */

        for (i = 0; i < height; i++)

            memset(dst + i * stride, src[1], width);

        /* Do not apply prediction.

           Note: memset to 0 above, setting first value to src[1]

           and applying prediction gives the same result. */

        return 0;

    } else {

        av_log(l->avctx, AV_LOG_ERROR,

               "Invalid zero run escape code! (%#x)\n", esc_count);

        return -1;

    }



    if (l->avctx->pix_fmt != AV_PIX_FMT_YUV422P) {

        for (i = 0; i < height; i++) {

            lag_pred_line(l, dst, width, stride, i);

            dst += stride;

        }

    } else {

        for (i = 0; i < height; i++) {

            lag_pred_line_yuy2(l, dst, width, stride, i,

                               width == l->avctx->width);

            dst += stride;

        }

    }



    return 0;

}

void avg_pixels8_altivec(uint8_t * block, const uint8_t * pixels, int line_size, int h)

{

POWERPC_TBL_DECLARE(altivec_avg_pixels8_num, 1);

#ifdef ALTIVEC_USE_REFERENCE_C_CODE

    int i;

POWERPC_TBL_START_COUNT(altivec_avg_pixels8_num, 1);

    for (i = 0; i < h; i++) {

        *((uint32_t *) (block)) =

            (((*((uint32_t *) (block))) |

              ((((const struct unaligned_32 *) (pixels))->l))) -

             ((((*((uint32_t *) (block))) ^

                ((((const struct unaligned_32 *) (pixels))->

                  l))) & 0xFEFEFEFEUL) >> 1));

        *((uint32_t *) (block + 4)) =

            (((*((uint32_t *) (block + 4))) |

              ((((const struct unaligned_32 *) (pixels + 4))->l))) -

             ((((*((uint32_t *) (block + 4))) ^

                ((((const struct unaligned_32 *) (pixels +

                                                  4))->

                  l))) & 0xFEFEFEFEUL) >> 1));

        pixels += line_size;

        block += line_size;

    }

POWERPC_TBL_STOP_COUNT(altivec_avg_pixels8_num, 1);



#else /* ALTIVEC_USE_REFERENCE_C_CODE */

    register vector unsigned char pixelsv1, pixelsv2, pixelsv, blockv;

    int i;



POWERPC_TBL_START_COUNT(altivec_avg_pixels8_num, 1);



   for (i = 0; i < h; i++) {

     /*

       block is 8 bytes-aligned, so we're either in the

       left block (16 bytes-aligned) or in the right block (not)

     */

     int rightside = ((unsigned long)block & 0x0000000F);



     blockv = vec_ld(0, block);

     pixelsv1 = vec_ld(0, (unsigned char*)pixels);

     pixelsv2 = vec_ld(16, (unsigned char*)pixels);

     pixelsv = vec_perm(pixelsv1, pixelsv2, vec_lvsl(0, pixels));



     if (rightside)

     {

       pixelsv = vec_perm(blockv, pixelsv, vcprm(0,1,s0,s1));

     }

     else

     {

       pixelsv = vec_perm(blockv, pixelsv, vcprm(s0,s1,2,3));

     }



     blockv = vec_avg(blockv, pixelsv);



     vec_st(blockv, 0, block);



     pixels += line_size;

     block += line_size;

   }



POWERPC_TBL_STOP_COUNT(altivec_avg_pixels8_num, 1);



#endif /* ALTIVEC_USE_REFERENCE_C_CODE */

}

static int mpegts_set_stream_info(AVStream *st, PESContext *pes,

                                  uint32_t stream_type, uint32_t prog_reg_desc)

{

    int old_codec_type= st->codec->codec_type;

    int old_codec_id  = st->codec->codec_id;



    if (old_codec_id != AV_CODEC_ID_NONE && avcodec_is_open(st->codec)) {

        av_log(pes->stream, AV_LOG_DEBUG, "cannot set stream info, codec is open\n");

        return 0;

    }



    avpriv_set_pts_info(st, 33, 1, 90000);

    st->priv_data = pes;

    st->codec->codec_type = AVMEDIA_TYPE_DATA;

    st->codec->codec_id   = AV_CODEC_ID_NONE;

    st->need_parsing = AVSTREAM_PARSE_FULL;

    pes->st = st;

    pes->stream_type = stream_type;



    av_log(pes->stream, AV_LOG_DEBUG,

           "stream=%d stream_type=%x pid=%x prog_reg_desc=%.4s\n",

           st->index, pes->stream_type, pes->pid, (char*)&prog_reg_desc);



    st->codec->codec_tag = pes->stream_type;



    mpegts_find_stream_type(st, pes->stream_type, ISO_types);

    if ((prog_reg_desc == AV_RL32("HDMV") ||

         prog_reg_desc == AV_RL32("HDPR")) &&

        st->codec->codec_id == AV_CODEC_ID_NONE) {

        mpegts_find_stream_type(st, pes->stream_type, HDMV_types);

        if (pes->stream_type == 0x83) {

            // HDMV TrueHD streams also contain an AC3 coded version of the

            // audio track - add a second stream for this

            AVStream *sub_st;

            // priv_data cannot be shared between streams

            PESContext *sub_pes = av_malloc(sizeof(*sub_pes));

            if (!sub_pes)

                return AVERROR(ENOMEM);

            memcpy(sub_pes, pes, sizeof(*sub_pes));



            sub_st = avformat_new_stream(pes->stream, NULL);

            if (!sub_st) {

                av_free(sub_pes);

                return AVERROR(ENOMEM);

            }



            sub_st->id = pes->pid;

            avpriv_set_pts_info(sub_st, 33, 1, 90000);

            sub_st->priv_data = sub_pes;

            sub_st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

            sub_st->codec->codec_id   = AV_CODEC_ID_AC3;

            sub_st->need_parsing = AVSTREAM_PARSE_FULL;

            sub_pes->sub_st = pes->sub_st = sub_st;

        }

    }

    if (st->codec->codec_id == AV_CODEC_ID_NONE)

        mpegts_find_stream_type(st, pes->stream_type, MISC_types);

    if (st->codec->codec_id == AV_CODEC_ID_NONE){

        st->codec->codec_id  = old_codec_id;

        st->codec->codec_type= old_codec_type;

    }



    return 0;

}

yuv2planeX_16_c_template(const int16_t *filter, int filterSize,

                         const int32_t **src, uint16_t *dest, int dstW,

                         int big_endian, int output_bits)

{

    int i;

    int shift = 15;

    av_assert0(output_bits == 16);



    for (i = 0; i < dstW; i++) {

        int val = 1 << (shift - 1);

        int j;



        /* range of val is [0,0x7FFFFFFF], so 31 bits, but with lanczos/spline

         * filters (or anything with negative coeffs, the range can be slightly

         * wider in both directions. To account for this overflow, we subtract

         * a constant so it always fits in the signed range (assuming a

         * reasonable filterSize), and re-add that at the end. */

        val -= 0x40000000;

        for (j = 0; j < filterSize; j++)

            val += src[j][i] * filter[j];



        output_pixel(&dest[i], val, 0x8000, int);

    }

}

static void nbd_refresh_filename(BlockDriverState *bs, QDict *options)

{

    BDRVNBDState *s = bs->opaque;

    QDict *opts = qdict_new();

    QObject *saddr_qdict;

    Visitor *ov;

    const char *host = NULL, *port = NULL, *path = NULL;



    if (s->saddr->type == SOCKET_ADDRESS_KIND_INET) {

        const InetSocketAddress *inet = s->saddr->u.inet.data;

        if (!inet->has_ipv4 && !inet->has_ipv6 && !inet->has_to) {

            host = inet->host;

            port = inet->port;

        }

    } else if (s->saddr->type == SOCKET_ADDRESS_KIND_UNIX) {

        path = s->saddr->u.q_unix.data->path;

    }



    qdict_put(opts, "driver", qstring_from_str("nbd"));



    if (path && s->export) {

        snprintf(bs->exact_filename, sizeof(bs->exact_filename),

                 "nbd+unix:///%s?socket=%s", s->export, path);

    } else if (path && !s->export) {

        snprintf(bs->exact_filename, sizeof(bs->exact_filename),

                 "nbd+unix://?socket=%s", path);

    } else if (host && s->export) {

        snprintf(bs->exact_filename, sizeof(bs->exact_filename),

                 "nbd://%s:%s/%s", host, port, s->export);

    } else if (host && !s->export) {

        snprintf(bs->exact_filename, sizeof(bs->exact_filename),

                 "nbd://%s:%s", host, port);

    }



    ov = qobject_output_visitor_new(&saddr_qdict);

    visit_type_SocketAddress(ov, NULL, &s->saddr, &error_abort);

    visit_complete(ov, &saddr_qdict);


    assert(qobject_type(saddr_qdict) == QTYPE_QDICT);



    qdict_put_obj(opts, "server", saddr_qdict);



    if (s->export) {

        qdict_put(opts, "export", qstring_from_str(s->export));

    }

    if (s->tlscredsid) {

        qdict_put(opts, "tls-creds", qstring_from_str(s->tlscredsid));

    }



    qdict_flatten(opts);

    bs->full_open_options = opts;

}

static void qdm2_fft_decode_tones (QDM2Context *q, int duration, GetBitContext *gb, int b)

{

    int channel, stereo, phase, exp;

    int local_int_4,  local_int_8,  stereo_phase,  local_int_10;

    int local_int_14, stereo_exp, local_int_20, local_int_28;

    int n, offset;



    local_int_4 = 0;

    local_int_28 = 0;

    local_int_20 = 2;

    local_int_8 = (4 - duration);

    local_int_10 = 1 << (q->group_order - duration - 1);

    offset = 1;



    while (1) {

        if (q->superblocktype_2_3) {

            while ((n = qdm2_get_vlc(gb, &vlc_tab_fft_tone_offset[local_int_8], 1, 2)) < 2) {

                offset = 1;

                if (n == 0) {

                    local_int_4 += local_int_10;

                    local_int_28 += (1 << local_int_8);

                } else {

                    local_int_4 += 8*local_int_10;

                    local_int_28 += (8 << local_int_8);

                }

            }

            offset += (n - 2);

        } else {

            offset += qdm2_get_vlc(gb, &vlc_tab_fft_tone_offset[local_int_8], 1, 2);

            while (offset >= (local_int_10 - 1)) {

                offset += (1 - (local_int_10 - 1));

                local_int_4  += local_int_10;

                local_int_28 += (1 << local_int_8);

            }

        }



        if (local_int_4 >= q->group_size)




        local_int_14 = (offset >> local_int_8);





        if (q->nb_channels > 1) {

            channel = get_bits1(gb);

            stereo = get_bits1(gb);

        } else {

            channel = 0;

            stereo = 0;

        }



        exp = qdm2_get_vlc(gb, (b ? &fft_level_exp_vlc : &fft_level_exp_alt_vlc), 0, 2);

        exp += q->fft_level_exp[fft_level_index_table[local_int_14]];

        exp = (exp < 0) ? 0 : exp;



        phase = get_bits(gb, 3);

        stereo_exp = 0;

        stereo_phase = 0;



        if (stereo) {

            stereo_exp = (exp - qdm2_get_vlc(gb, &fft_stereo_exp_vlc, 0, 1));

            stereo_phase = (phase - qdm2_get_vlc(gb, &fft_stereo_phase_vlc, 0, 1));

            if (stereo_phase < 0)

                stereo_phase += 8;

        }



        if (q->frequency_range > (local_int_14 + 1)) {

            int sub_packet = (local_int_20 + local_int_28);



            qdm2_fft_init_coefficient(q, sub_packet, offset, duration, channel, exp, phase);

            if (stereo)

                qdm2_fft_init_coefficient(q, sub_packet, offset, duration, (1 - channel), stereo_exp, stereo_phase);

        }



        offset++;

    }

}

static void usb_msd_realize_storage(USBDevice *dev, Error **errp)

{

    MSDState *s = DO_UPCAST(MSDState, dev, dev);

    BlockDriverState *bs = s->conf.bs;

    SCSIDevice *scsi_dev;

    Error *err = NULL;



    if (!bs) {

        error_setg(errp, "drive property not set");

        return;

    }



    blkconf_serial(&s->conf, &dev->serial);



    /*

     * Hack alert: this pretends to be a block device, but it's really

     * a SCSI bus that can serve only a single device, which it

     * creates automatically.  But first it needs to detach from its

     * blockdev, or else scsi_bus_legacy_add_drive() dies when it

     * attaches again.

     *

     * The hack is probably a bad idea.

     */

    bdrv_detach_dev(bs, &s->dev.qdev);

    s->conf.bs = NULL;



    usb_desc_create_serial(dev);

    usb_desc_init(dev);

    scsi_bus_new(&s->bus, sizeof(s->bus), DEVICE(dev),

                 &usb_msd_scsi_info_storage, NULL);

    scsi_dev = scsi_bus_legacy_add_drive(&s->bus, bs, 0, !!s->removable,

                                         s->conf.bootindex, dev->serial,

                                         &err);

    if (!scsi_dev) {

        error_propagate(errp, err);

        return;

    }

    s->bus.qbus.allow_hotplug = 0;

    usb_msd_handle_reset(dev);



    if (bdrv_key_required(bs)) {

        if (cur_mon) {

            monitor_read_bdrv_key_start(cur_mon, bs, usb_msd_password_cb, s);

            s->dev.auto_attach = 0;

        } else {

            autostart = 0;

        }

    }

}

static int read_var_block_data(ALSDecContext *ctx, ALSBlockData *bd)

{

    ALSSpecificConfig *sconf = &ctx->sconf;

    AVCodecContext *avctx    = ctx->avctx;

    GetBitContext *gb        = &ctx->gb;

    unsigned int k;

    unsigned int s[8];

    unsigned int sx[8];

    unsigned int sub_blocks, log2_sub_blocks, sb_length;

    unsigned int start      = 0;

    unsigned int opt_order;

    int          sb;

    int32_t      *quant_cof = bd->quant_cof;

    int32_t      *current_res;





    // ensure variable block decoding by reusing this field

    *bd->const_block = 0;



    *bd->opt_order  = 1;

    bd->js_blocks   = get_bits1(gb);



    opt_order       = *bd->opt_order;



    // determine the number of subblocks for entropy decoding

    if (!sconf->bgmc && !sconf->sb_part) {

        log2_sub_blocks = 0;

    } else {

        if (sconf->bgmc && sconf->sb_part)

            log2_sub_blocks = get_bits(gb, 2);

        else

            log2_sub_blocks = 2 * get_bits1(gb);




    sub_blocks = 1 << log2_sub_blocks;



    // do not continue in case of a damaged stream since

    // block_length must be evenly divisible by sub_blocks

    if (bd->block_length & (sub_blocks - 1)) {

        av_log(avctx, AV_LOG_WARNING,

               "Block length is not evenly divisible by the number of subblocks.\n");





    sb_length = bd->block_length >> log2_sub_blocks;



    if (sconf->bgmc) {

        s[0] = get_bits(gb, 8 + (sconf->resolution > 1));


            s[k] = s[k - 1] + decode_rice(gb, 2);



        for (k = 0; k < sub_blocks; k++) {

            sx[k]   = s[k] & 0x0F;

            s [k] >>= 4;


    } else {

        s[0] = get_bits(gb, 4 + (sconf->resolution > 1));


            s[k] = s[k - 1] + decode_rice(gb, 0);









    if (get_bits1(gb))

        *bd->shift_lsbs = get_bits(gb, 4) + 1;



    *bd->store_prev_samples = (bd->js_blocks && bd->raw_other) || *bd->shift_lsbs;





    if (!sconf->rlslms) {

        if (sconf->adapt_order) {

            int opt_order_length = av_ceil_log2(av_clip((bd->block_length >> 3) - 1,

                                                2, sconf->max_order + 1));

            *bd->opt_order       = get_bits(gb, opt_order_length);

            if (*bd->opt_order > sconf->max_order) {

                *bd->opt_order = sconf->max_order;

                av_log(avctx, AV_LOG_ERROR, "Predictor order too large!\n");



        } else {

            *bd->opt_order = sconf->max_order;




        opt_order = *bd->opt_order;



        if (opt_order) {

            int add_base;



            if (sconf->coef_table == 3) {

                add_base = 0x7F;



                // read coefficient 0

                quant_cof[0] = 32 * parcor_scaled_values[get_bits(gb, 7)];



                // read coefficient 1

                if (opt_order > 1)

                    quant_cof[1] = -32 * parcor_scaled_values[get_bits(gb, 7)];



                // read coefficients 2 to opt_order

                for (k = 2; k < opt_order; k++)

                    quant_cof[k] = get_bits(gb, 7);

            } else {

                int k_max;

                add_base = 1;



                // read coefficient 0 to 19

                k_max = FFMIN(opt_order, 20);

                for (k = 0; k < k_max; k++) {

                    int rice_param = parcor_rice_table[sconf->coef_table][k][1];

                    int offset     = parcor_rice_table[sconf->coef_table][k][0];

                    quant_cof[k] = decode_rice(gb, rice_param) + offset;

                    if (quant_cof[k] < -64 || quant_cof[k] > 63) {

                        av_log(avctx, AV_LOG_ERROR, "Quantization coefficient %d is out of range!\n", quant_cof[k]);

                        return AVERROR_INVALIDDATA;





                // read coefficients 20 to 126

                k_max = FFMIN(opt_order, 127);

                for (; k < k_max; k++)

                    quant_cof[k] = decode_rice(gb, 2) + (k & 1);



                // read coefficients 127 to opt_order

                for (; k < opt_order; k++)

                    quant_cof[k] = decode_rice(gb, 1);



                quant_cof[0] = 32 * parcor_scaled_values[quant_cof[0] + 64];



                if (opt_order > 1)

                    quant_cof[1] = -32 * parcor_scaled_values[quant_cof[1] + 64];




            for (k = 2; k < opt_order; k++)

                quant_cof[k] = (quant_cof[k] << 14) + (add_base << 13);





    // read LTP gain and lag values

    if (sconf->long_term_prediction) {

        *bd->use_ltp = get_bits1(gb);



        if (*bd->use_ltp) {

            int r, c;



            bd->ltp_gain[0]   = decode_rice(gb, 1) << 3;

            bd->ltp_gain[1]   = decode_rice(gb, 2) << 3;



            r                 = get_unary(gb, 0, 3);

            c                 = get_bits(gb, 2);

            bd->ltp_gain[2]   = ltp_gain_values[r][c];



            bd->ltp_gain[3]   = decode_rice(gb, 2) << 3;

            bd->ltp_gain[4]   = decode_rice(gb, 1) << 3;



            *bd->ltp_lag      = get_bits(gb, ctx->ltp_lag_length);

            *bd->ltp_lag     += FFMAX(4, opt_order + 1);





    // read first value and residuals in case of a random access block

    if (bd->ra_block) {

        if (opt_order)

            bd->raw_samples[0] = decode_rice(gb, avctx->bits_per_raw_sample - 4);

        if (opt_order > 1)

            bd->raw_samples[1] = decode_rice(gb, FFMIN(s[0] + 3, ctx->s_max));

        if (opt_order > 2)

            bd->raw_samples[2] = decode_rice(gb, FFMIN(s[0] + 1, ctx->s_max));



        start = FFMIN(opt_order, 3);




    // read all residuals

    if (sconf->bgmc) {

        int          delta[8];

        unsigned int k    [8];

        unsigned int b = av_clip((av_ceil_log2(bd->block_length) - 3) >> 1, 0, 5);

        unsigned int i = start;



        // read most significant bits

        unsigned int high;

        unsigned int low;

        unsigned int value;



        ff_bgmc_decode_init(gb, &high, &low, &value);



        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, i = 0) {

            k    [sb] = s[sb] > b ? s[sb] - b : 0;

            delta[sb] = 5 - s[sb] + k[sb];



            ff_bgmc_decode(gb, sb_length, current_res,

                        delta[sb], sx[sb], &high, &low, &value, ctx->bgmc_lut, ctx->bgmc_lut_status);



            current_res += sb_length;




        ff_bgmc_decode_end(gb);





        // read least significant bits and tails

        i = start;

        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, i = 0) {

            unsigned int cur_tail_code = tail_code[sx[sb]][delta[sb]];

            unsigned int cur_k         = k[sb];

            unsigned int cur_s         = s[sb];



            for (; i < sb_length; i++) {

                int32_t res = *current_res;



                if (res == cur_tail_code) {

                    unsigned int max_msb =   (2 + (sx[sb] > 2) + (sx[sb] > 10))

                                          << (5 - delta[sb]);



                    res = decode_rice(gb, cur_s);



                    if (res >= 0) {

                        res += (max_msb    ) << cur_k;

                    } else {

                        res -= (max_msb - 1) << cur_k;


                } else {

                    if (res > cur_tail_code)

                        res--;



                    if (res & 1)

                        res = -res;



                    res >>= 1;



                    if (cur_k) {

                        res <<= cur_k;

                        res  |= get_bits_long(gb, cur_k);





                *current_res++ = res;



    } else {

        current_res = bd->raw_samples + start;



        for (sb = 0; sb < sub_blocks; sb++, start = 0)

            for (; start < sb_length; start++)

                *current_res++ = decode_rice(gb, s[sb]);




    if (!sconf->mc_coding || ctx->js_switch)

        align_get_bits(gb);



    return 0;

static void do_rematrixing(AC3DecodeContext *ctx)

{

    ac3_audio_block *ab = &ctx->audio_block;

    uint8_t bnd1 = 13, bnd2 = 25, bnd3 = 37, bnd4 = 61;

    uint8_t bndend;



    bndend = FFMIN(ab->endmant[0], ab->endmant[1]);

    if (ab->rematflg & 1)

        _do_rematrixing(ctx, bnd1, bnd2);

    if (ab->rematflg & 2)

        _do_rematrixing(ctx, bnd2, bnd3);

    if (ab->rematflg & 4) {

        if (ab->cplbegf > 0 && ab->cplbegf <= 2 && (ab->flags & AC3_AB_CPLINU))

            _do_rematrixing(ctx, bnd3, bndend);

        else {

            _do_rematrixing(ctx, bnd3, bnd4);

            if (ab->rematflg & 8)

                _do_rematrixing(ctx, bnd4, bndend);

        }

    }

}

static int cdxl_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame, AVPacket *pkt)

{

    CDXLVideoContext *c = avctx->priv_data;

    AVFrame * const p = data;

    int ret, w, h, encoding, aligned_width, buf_size = pkt->size;

    const uint8_t *buf = pkt->data;



    if (buf_size < 32)

        return AVERROR_INVALIDDATA;

    encoding        = buf[1] & 7;

    c->format       = buf[1] & 0xE0;

    w               = AV_RB16(&buf[14]);

    h               = AV_RB16(&buf[16]);

    c->bpp          = buf[19];

    c->palette_size = AV_RB16(&buf[20]);

    c->palette      = buf + 32;

    c->video        = c->palette + c->palette_size;

    c->video_size   = buf_size - c->palette_size - 32;



    if (c->palette_size > 512)

        return AVERROR_INVALIDDATA;

    if (buf_size < c->palette_size + 32)

        return AVERROR_INVALIDDATA;

    if (c->bpp < 1)

        return AVERROR_INVALIDDATA;

    if (c->format != BIT_PLANAR && c->format != BIT_LINE && c->format != CHUNKY) {

        avpriv_request_sample(avctx, "Pixel format 0x%0x", c->format);

        return AVERROR_PATCHWELCOME;

    }



    if ((ret = ff_set_dimensions(avctx, w, h)) < 0)

        return ret;



    if (c->format == CHUNKY)

        aligned_width = avctx->width;

    else

        aligned_width = FFALIGN(c->avctx->width, 16);

    c->padded_bits  = aligned_width - c->avctx->width;

    if (c->video_size < aligned_width * avctx->height * c->bpp / 8)

        return AVERROR_INVALIDDATA;

    if (!encoding && c->palette_size && c->bpp <= 8) {

        avctx->pix_fmt = AV_PIX_FMT_PAL8;

    } else if (encoding == 1 && (c->bpp == 6 || c->bpp == 8)) {

        if (c->palette_size != (1 << (c->bpp - 1)))

            return AVERROR_INVALIDDATA;

        avctx->pix_fmt = AV_PIX_FMT_BGR24;

    } else if (!encoding && c->bpp == 24 && c->format == CHUNKY &&

               !c->palette_size) {

        avctx->pix_fmt = AV_PIX_FMT_RGB24;

    } else {

        avpriv_request_sample(avctx, "Encoding %d, bpp %d and format 0x%x",

                              encoding, c->bpp, c->format);

        return AVERROR_PATCHWELCOME;

    }



    if ((ret = ff_get_buffer(avctx, p, 0)) < 0)

        return ret;

    p->pict_type = AV_PICTURE_TYPE_I;



    if (encoding) {

        av_fast_padded_malloc(&c->new_video, &c->new_video_size,

                              h * w + AV_INPUT_BUFFER_PADDING_SIZE);

        if (!c->new_video)

            return AVERROR(ENOMEM);

        if (c->bpp == 8)

            cdxl_decode_ham8(c, p);

        else

            cdxl_decode_ham6(c, p);

    } else if (avctx->pix_fmt == AV_PIX_FMT_PAL8) {

        cdxl_decode_rgb(c, p);

    } else {

        cdxl_decode_raw(c, p);

    }

    *got_frame = 1;



    return buf_size;

}

static void xen_read_physmap(XenIOState *state)

{

    XenPhysmap *physmap = NULL;

    unsigned int len, num, i;

    char path[80], *value = NULL;

    char **entries = NULL;



    snprintf(path, sizeof(path),

            "/local/domain/0/device-model/%d/physmap", xen_domid);

    entries = xs_directory(state->xenstore, 0, path, &num);

    if (entries == NULL)

        return;



    for (i = 0; i < num; i++) {

        physmap = g_malloc(sizeof (XenPhysmap));

        physmap->phys_offset = strtoull(entries[i], NULL, 16);

        snprintf(path, sizeof(path),

                "/local/domain/0/device-model/%d/physmap/%s/start_addr",

                xen_domid, entries[i]);

        value = xs_read(state->xenstore, 0, path, &len);

        if (value == NULL) {

            free(physmap);

            continue;

        }

        physmap->start_addr = strtoull(value, NULL, 16);

        free(value);



        snprintf(path, sizeof(path),

                "/local/domain/0/device-model/%d/physmap/%s/size",

                xen_domid, entries[i]);

        value = xs_read(state->xenstore, 0, path, &len);

        if (value == NULL) {

            free(physmap);

            continue;

        }

        physmap->size = strtoull(value, NULL, 16);

        free(value);



        snprintf(path, sizeof(path),

                "/local/domain/0/device-model/%d/physmap/%s/name",

                xen_domid, entries[i]);

        physmap->name = xs_read(state->xenstore, 0, path, &len);



        QLIST_INSERT_HEAD(&state->physmap, physmap, list);

    }

    free(entries);

}

static av_cold int oggvorbis_encode_init(AVCodecContext *avccontext)

{

    OggVorbisContext *context = avccontext->priv_data;

    ogg_packet header, header_comm, header_code;

    uint8_t *p;

    unsigned int offset;



    vorbis_info_init(&context->vi);

    if (oggvorbis_init_encoder(&context->vi, avccontext) < 0) {

        av_log(avccontext, AV_LOG_ERROR, "oggvorbis_encode_init: init_encoder failed\n");

        return -1;

    }

    vorbis_analysis_init(&context->vd, &context->vi);

    vorbis_block_init(&context->vd, &context->vb);



    vorbis_comment_init(&context->vc);

    vorbis_comment_add_tag(&context->vc, "encoder", LIBAVCODEC_IDENT);



    vorbis_analysis_headerout(&context->vd, &context->vc, &header,

                              &header_comm, &header_code);



    avccontext->extradata_size =

        1 + xiph_len(header.bytes) + xiph_len(header_comm.bytes) +

        header_code.bytes;

    p = avccontext->extradata =

            av_malloc(avccontext->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

    p[0]    = 2;

    offset  = 1;

    offset += av_xiphlacing(&p[offset], header.bytes);

    offset += av_xiphlacing(&p[offset], header_comm.bytes);

    memcpy(&p[offset], header.packet, header.bytes);

    offset += header.bytes;

    memcpy(&p[offset], header_comm.packet, header_comm.bytes);

    offset += header_comm.bytes;

    memcpy(&p[offset], header_code.packet, header_code.bytes);

    offset += header_code.bytes;

    assert(offset == avccontext->extradata_size);



#if 0

    vorbis_block_clear(&context->vb);

    vorbis_dsp_clear(&context->vd);

    vorbis_info_clear(&context->vi);

#endif

    vorbis_comment_clear(&context->vc);



    avccontext->frame_size = OGGVORBIS_FRAME_SIZE;



    avccontext->coded_frame = avcodec_alloc_frame();



    return 0;

}

static char *choose_pix_fmts(OutputStream *ost)

{

     if (ost->keep_pix_fmt) {

        if (ost->filter)

            avfilter_graph_set_auto_convert(ost->filter->graph->graph,

                                            AVFILTER_AUTO_CONVERT_NONE);

        if (ost->st->codec->pix_fmt == PIX_FMT_NONE)

            return NULL;

        return av_strdup(av_get_pix_fmt_name(ost->st->codec->pix_fmt));

    }

    if (ost->st->codec->pix_fmt != PIX_FMT_NONE) {

        return av_strdup(av_get_pix_fmt_name(choose_pixel_fmt(ost->st, ost->enc, ost->st->codec->pix_fmt)));

    } else if (ost->enc->pix_fmts) {

        const enum PixelFormat *p;

        AVIOContext *s = NULL;

        uint8_t *ret;

        int len;



        if (avio_open_dyn_buf(&s) < 0)

            exit_program(1);



        p = ost->enc->pix_fmts;

        if (ost->st->codec->strict_std_compliance <= FF_COMPLIANCE_UNOFFICIAL) {

            if (ost->st->codec->codec_id == CODEC_ID_MJPEG) {

                p = (const enum PixelFormat[]) { PIX_FMT_YUVJ420P, PIX_FMT_YUVJ422P, PIX_FMT_YUV420P, PIX_FMT_YUV422P, PIX_FMT_NONE };

            } else if (ost->st->codec->codec_id == CODEC_ID_LJPEG) {

                p = (const enum PixelFormat[]) { PIX_FMT_YUVJ420P, PIX_FMT_YUVJ422P, PIX_FMT_YUVJ444P, PIX_FMT_YUV420P,

                                                    PIX_FMT_YUV422P, PIX_FMT_YUV444P, PIX_FMT_BGRA, PIX_FMT_NONE };

            }

        }



        for (; *p != PIX_FMT_NONE; p++) {

            const char *name = av_get_pix_fmt_name(*p);

            avio_printf(s, "%s:", name);

        }

        len = avio_close_dyn_buf(s, &ret);

        ret[len - 1] = 0;

        return ret;

    } else

        return NULL;

}

void ff_h264_filter_mb(const H264Context *h, H264SliceContext *sl,

                       int mb_x, int mb_y,

                       uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr,

                       unsigned int linesize, unsigned int uvlinesize)

{

    const int mb_xy= mb_x + mb_y*h->mb_stride;

    const int mb_type = h->cur_pic.mb_type[mb_xy];

    const int mvy_limit = IS_INTERLACED(mb_type) ? 2 : 4;

    int first_vertical_edge_done = 0;

    int chroma = !(CONFIG_GRAY && (h->flags & AV_CODEC_FLAG_GRAY));

    int qp_bd_offset = 6 * (h->sps.bit_depth_luma - 8);

    int a = 52 + sl->slice_alpha_c0_offset - qp_bd_offset;

    int b = 52 + sl->slice_beta_offset - qp_bd_offset;



    if (FRAME_MBAFF(h)

            // and current and left pair do not have the same interlaced type

            && IS_INTERLACED(mb_type ^ sl->left_type[LTOP])

            // and left mb is in available to us

            && sl->left_type[LTOP]) {

        /* First vertical edge is different in MBAFF frames

         * There are 8 different bS to compute and 2 different Qp

         */

        DECLARE_ALIGNED(8, int16_t, bS)[8];

        int qp[2];

        int bqp[2];

        int rqp[2];

        int mb_qp, mbn0_qp, mbn1_qp;

        int i;

        first_vertical_edge_done = 1;



        if( IS_INTRA(mb_type) ) {

            AV_WN64A(&bS[0], 0x0004000400040004ULL);

            AV_WN64A(&bS[4], 0x0004000400040004ULL);

        } else {

            static const uint8_t offset[2][2][8]={

                {

                    {3+4*0, 3+4*0, 3+4*0, 3+4*0, 3+4*1, 3+4*1, 3+4*1, 3+4*1},

                    {3+4*2, 3+4*2, 3+4*2, 3+4*2, 3+4*3, 3+4*3, 3+4*3, 3+4*3},

                },{

                    {3+4*0, 3+4*1, 3+4*2, 3+4*3, 3+4*0, 3+4*1, 3+4*2, 3+4*3},

                    {3+4*0, 3+4*1, 3+4*2, 3+4*3, 3+4*0, 3+4*1, 3+4*2, 3+4*3},

                }

            };

            const uint8_t *off= offset[MB_FIELD(sl)][mb_y&1];

            for( i = 0; i < 8; i++ ) {

                int j= MB_FIELD(sl) ? i>>2 : i&1;

                int mbn_xy = sl->left_mb_xy[LEFT(j)];

                int mbn_type = sl->left_type[LEFT(j)];



                if( IS_INTRA( mbn_type ) )

                    bS[i] = 4;

                else{

                    bS[i] = 1 + !!(sl->non_zero_count_cache[12+8*(i>>1)] |

                         ((!h->pps.cabac && IS_8x8DCT(mbn_type)) ?

                            (h->cbp_table[mbn_xy] & (((MB_FIELD(sl) ? (i&2) : (mb_y&1)) ? 8 : 2) << 12))

                                                                       :

                            h->non_zero_count[mbn_xy][ off[i] ]));

                }

            }

        }



        mb_qp   = h->cur_pic.qscale_table[mb_xy];

        mbn0_qp = h->cur_pic.qscale_table[sl->left_mb_xy[0]];

        mbn1_qp = h->cur_pic.qscale_table[sl->left_mb_xy[1]];

        qp[0] = ( mb_qp + mbn0_qp + 1 ) >> 1;

        bqp[0] = ( get_chroma_qp( h, 0, mb_qp ) +

                   get_chroma_qp( h, 0, mbn0_qp ) + 1 ) >> 1;

        rqp[0] = ( get_chroma_qp( h, 1, mb_qp ) +

                   get_chroma_qp( h, 1, mbn0_qp ) + 1 ) >> 1;

        qp[1] = ( mb_qp + mbn1_qp + 1 ) >> 1;

        bqp[1] = ( get_chroma_qp( h, 0, mb_qp ) +

                   get_chroma_qp( h, 0, mbn1_qp ) + 1 ) >> 1;

        rqp[1] = ( get_chroma_qp( h, 1, mb_qp ) +

                   get_chroma_qp( h, 1, mbn1_qp ) + 1 ) >> 1;



        /* Filter edge */

        ff_tlog(h->avctx, "filter mb:%d/%d MBAFF, QPy:%d/%d, QPb:%d/%d QPr:%d/%d ls:%d uvls:%d", mb_x, mb_y, qp[0], qp[1], bqp[0], bqp[1], rqp[0], rqp[1], linesize, uvlinesize);

        { int i; for (i = 0; i < 8; i++) ff_tlog(h->avctx, " bS[%d]:%d", i, bS[i]); ff_tlog(h->avctx, "\n"); }

        if (MB_FIELD(sl)) {

            filter_mb_mbaff_edgev ( h, img_y                ,   linesize, bS  , 1, qp [0], a, b, 1 );

            filter_mb_mbaff_edgev ( h, img_y  + 8*  linesize,   linesize, bS+4, 1, qp [1], a, b, 1 );

            if (chroma){

                if (CHROMA444(h)) {

                    filter_mb_mbaff_edgev ( h, img_cb,                uvlinesize, bS  , 1, bqp[0], a, b, 1 );

                    filter_mb_mbaff_edgev ( h, img_cb + 8*uvlinesize, uvlinesize, bS+4, 1, bqp[1], a, b, 1 );

                    filter_mb_mbaff_edgev ( h, img_cr,                uvlinesize, bS  , 1, rqp[0], a, b, 1 );

                    filter_mb_mbaff_edgev ( h, img_cr + 8*uvlinesize, uvlinesize, bS+4, 1, rqp[1], a, b, 1 );

                } else if (CHROMA422(h)) {

                    filter_mb_mbaff_edgecv(h, img_cb,                uvlinesize, bS  , 1, bqp[0], a, b, 1);

                    filter_mb_mbaff_edgecv(h, img_cb + 8*uvlinesize, uvlinesize, bS+4, 1, bqp[1], a, b, 1);

                    filter_mb_mbaff_edgecv(h, img_cr,                uvlinesize, bS  , 1, rqp[0], a, b, 1);

                    filter_mb_mbaff_edgecv(h, img_cr + 8*uvlinesize, uvlinesize, bS+4, 1, rqp[1], a, b, 1);

                }else{

                    filter_mb_mbaff_edgecv( h, img_cb,                uvlinesize, bS  , 1, bqp[0], a, b, 1 );

                    filter_mb_mbaff_edgecv( h, img_cb + 4*uvlinesize, uvlinesize, bS+4, 1, bqp[1], a, b, 1 );

                    filter_mb_mbaff_edgecv( h, img_cr,                uvlinesize, bS  , 1, rqp[0], a, b, 1 );

                    filter_mb_mbaff_edgecv( h, img_cr + 4*uvlinesize, uvlinesize, bS+4, 1, rqp[1], a, b, 1 );

                }

            }

        }else{

            filter_mb_mbaff_edgev ( h, img_y              , 2*  linesize, bS  , 2, qp [0], a, b, 1 );

            filter_mb_mbaff_edgev ( h, img_y  +   linesize, 2*  linesize, bS+1, 2, qp [1], a, b, 1 );

            if (chroma){

                if (CHROMA444(h)) {

                    filter_mb_mbaff_edgev ( h, img_cb,              2*uvlinesize, bS  , 2, bqp[0], a, b, 1 );

                    filter_mb_mbaff_edgev ( h, img_cb + uvlinesize, 2*uvlinesize, bS+1, 2, bqp[1], a, b, 1 );

                    filter_mb_mbaff_edgev ( h, img_cr,              2*uvlinesize, bS  , 2, rqp[0], a, b, 1 );

                    filter_mb_mbaff_edgev ( h, img_cr + uvlinesize, 2*uvlinesize, bS+1, 2, rqp[1], a, b, 1 );

                }else{

                    filter_mb_mbaff_edgecv( h, img_cb,              2*uvlinesize, bS  , 2, bqp[0], a, b, 1 );

                    filter_mb_mbaff_edgecv( h, img_cb + uvlinesize, 2*uvlinesize, bS+1, 2, bqp[1], a, b, 1 );

                    filter_mb_mbaff_edgecv( h, img_cr,              2*uvlinesize, bS  , 2, rqp[0], a, b, 1 );

                    filter_mb_mbaff_edgecv( h, img_cr + uvlinesize, 2*uvlinesize, bS+1, 2, rqp[1], a, b, 1 );

                }

            }

        }

    }



#if CONFIG_SMALL

    {

        int dir;

        for (dir = 0; dir < 2; dir++)

            filter_mb_dir(h, sl, mb_x, mb_y, img_y, img_cb, img_cr, linesize,

                          uvlinesize, mb_xy, mb_type, mvy_limit,

                          dir ? 0 : first_vertical_edge_done, a, b,

                          chroma, dir);

    }

#else

    filter_mb_dir(h, sl, mb_x, mb_y, img_y, img_cb, img_cr, linesize, uvlinesize, mb_xy, mb_type, mvy_limit, first_vertical_edge_done, a, b, chroma, 0);

    filter_mb_dir(h, sl, mb_x, mb_y, img_y, img_cb, img_cr, linesize, uvlinesize, mb_xy, mb_type, mvy_limit, 0,                        a, b, chroma, 1);

#endif

}

void qmp_cont(Error **errp)

{

    Error *local_err = NULL;

    BlockBackend *blk;

    BlockDriverState *bs;

    BdrvNextIterator it;



    /* if there is a dump in background, we should wait until the dump

     * finished */

    if (dump_in_progress()) {

        error_setg(errp, "There is a dump in process, please wait.");

        return;

    }



    if (runstate_needs_reset()) {

        error_setg(errp, "Resetting the Virtual Machine is required");

        return;

    } else if (runstate_check(RUN_STATE_SUSPENDED)) {

        return;

    }



    for (blk = blk_next(NULL); blk; blk = blk_next(blk)) {

        blk_iostatus_reset(blk);

    }



    for (bs = bdrv_first(&it); bs; bs = bdrv_next(&it)) {

        bdrv_add_key(bs, NULL, &local_err);

        if (local_err) {

            error_propagate(errp, local_err);

            return;

        }

    }



    /* Continuing after completed migration. Images have been inactivated to

     * allow the destination to take control. Need to get control back now.

     *

     * If there are no inactive block nodes (e.g. because the VM was just

     * paused rather than completing a migration), bdrv_inactivate_all() simply

     * doesn't do anything. */

    bdrv_invalidate_cache_all(&local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    blk_resume_after_migration(&local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    if (runstate_check(RUN_STATE_INMIGRATE)) {

        autostart = 1;

    } else {

        vm_start();

    }

}

