static int decode_band(IVI45DecContext *ctx, int plane_num,

                       IVIBandDesc *band, AVCodecContext *avctx)

{

    int         result, i, t, idx1, idx2, pos;

    IVITile     *tile;



    band->buf     = band->bufs[ctx->dst_buf];

    if (!band->buf) {

        av_log(avctx, AV_LOG_ERROR, "Band buffer points to no data!\n");

        return AVERROR_INVALIDDATA;

    }

    band->ref_buf = band->bufs[ctx->ref_buf];

    band->data_ptr = ctx->frame_data + (get_bits_count(&ctx->gb) >> 3);



    result = ctx->decode_band_hdr(ctx, band, avctx);

    if (result) {

        av_log(avctx, AV_LOG_ERROR, "Error while decoding band header: %d\n",

               result);

        return result;

    }



    if (band->is_empty) {

        av_log(avctx, AV_LOG_ERROR, "Empty band encountered!\n");

        return AVERROR_INVALIDDATA;

    }



    band->rv_map = &ctx->rvmap_tabs[band->rvmap_sel];



    /* apply corrections to the selected rvmap table if present */

    for (i = 0; i < band->num_corr; i++) {

        idx1 = band->corr[i * 2];

        idx2 = band->corr[i * 2 + 1];

        FFSWAP(uint8_t, band->rv_map->runtab[idx1], band->rv_map->runtab[idx2]);

        FFSWAP(int16_t, band->rv_map->valtab[idx1], band->rv_map->valtab[idx2]);

    }



    pos = get_bits_count(&ctx->gb);



    for (t = 0; t < band->num_tiles; t++) {

        tile = &band->tiles[t];



        if (tile->mb_size != band->mb_size) {

            av_log(avctx, AV_LOG_ERROR, "MB sizes mismatch: %d vs. %d\n",

                   band->mb_size, tile->mb_size);

            return AVERROR_INVALIDDATA;

        }

        tile->is_empty = get_bits1(&ctx->gb);

        if (tile->is_empty) {

            ivi_process_empty_tile(avctx, band, tile,

                                      (ctx->planes[0].bands[0].mb_size >> 3) - (band->mb_size >> 3));

            av_dlog(avctx, "Empty tile encountered!\n");

        } else {

            tile->data_size = ff_ivi_dec_tile_data_size(&ctx->gb);

            if (!tile->data_size) {

                av_log(avctx, AV_LOG_ERROR, "Tile data size is zero!\n");

                return AVERROR_INVALIDDATA;

            }



            result = ctx->decode_mb_info(ctx, band, tile, avctx);

            if (result < 0)

                break;



            result = ff_ivi_decode_blocks(&ctx->gb, band, tile);

            if (result < 0 || ((get_bits_count(&ctx->gb) - pos) >> 3) != tile->data_size) {

                av_log(avctx, AV_LOG_ERROR, "Corrupted tile data encountered!\n");

                break;

            }



            pos += tile->data_size << 3; // skip to next tile

        }

    }



    /* restore the selected rvmap table by applying its corrections in reverse order */

    for (i = band->num_corr-1; i >= 0; i--) {

        idx1 = band->corr[i*2];

        idx2 = band->corr[i*2+1];

        FFSWAP(uint8_t, band->rv_map->runtab[idx1], band->rv_map->runtab[idx2]);

        FFSWAP(int16_t, band->rv_map->valtab[idx1], band->rv_map->valtab[idx2]);

    }



#ifdef DEBUG

    if (band->checksum_present) {

        uint16_t chksum = ivi_calc_band_checksum(band);

        if (chksum != band->checksum) {

            av_log(avctx, AV_LOG_ERROR,

                   "Band checksum mismatch! Plane %d, band %d, received: %x, calculated: %x\n",

                   band->plane, band->band_num, band->checksum, chksum);

        }

    }

#endif



    align_get_bits(&ctx->gb);



    return result;

}

int ff_qsv_enc_init(AVCodecContext *avctx, QSVEncContext *q)

{

    int opaque_alloc = 0;

    int ret;



    q->param.IOPattern  = MFX_IOPATTERN_IN_SYSTEM_MEMORY;

    q->param.AsyncDepth = q->async_depth;



    q->async_fifo = av_fifo_alloc((1 + q->async_depth) *

                                  (sizeof(AVPacket) + sizeof(mfxSyncPoint) + sizeof(mfxBitstream*)));

    if (!q->async_fifo)

        return AVERROR(ENOMEM);



    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;



        q->session         = qsv->session;

        q->param.IOPattern = qsv->iopattern;



        opaque_alloc = qsv->opaque_alloc;

    }



    if (!q->session) {

        ret = ff_qsv_init_internal_session(avctx, &q->internal_session,

                                           q->load_plugins);

        if (ret < 0)

            return ret;



        q->session = q->internal_session;

    }



    ret = init_video_param(avctx, q);

    if (ret < 0)

        return ret;



    ret = MFXVideoENCODE_QueryIOSurf(q->session, &q->param, &q->req);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error querying the encoding parameters\n");

        return ff_qsv_error(ret);

    }



    if (opaque_alloc) {

        ret = qsv_init_opaque_alloc(avctx, q);

        if (ret < 0)

            return ret;

    }



    if (avctx->hwaccel_context) {

        AVQSVContext *qsv = avctx->hwaccel_context;

        int i, j;



        q->extparam = av_mallocz_array(qsv->nb_ext_buffers + q->nb_extparam_internal,

                                       sizeof(*q->extparam));

        if (!q->extparam)

            return AVERROR(ENOMEM);



        q->param.ExtParam = q->extparam;

        for (i = 0; i < qsv->nb_ext_buffers; i++)

            q->param.ExtParam[i] = qsv->ext_buffers[i];

        q->param.NumExtParam = qsv->nb_ext_buffers;



        for (i = 0; i < q->nb_extparam_internal; i++) {

            for (j = 0; j < qsv->nb_ext_buffers; j++) {

                if (qsv->ext_buffers[j]->BufferId == q->extparam_internal[i]->BufferId)

                    break;

            }

            if (j < qsv->nb_ext_buffers)

                continue;



            q->param.ExtParam[q->param.NumExtParam++] = q->extparam_internal[i];

        }

    } else {

        q->param.ExtParam    = q->extparam_internal;

        q->param.NumExtParam = q->nb_extparam_internal;

    }



    ret = MFXVideoENCODE_Init(q->session, &q->param);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing the encoder\n");

        return ff_qsv_error(ret);

    }



    ret = qsv_retrieve_enc_params(avctx, q);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error retrieving encoding parameters.\n");

        return ret;

    }



    q->avctx = avctx;



    return 0;

}

unsigned long virtio_load_direct(ulong rec_list1, ulong rec_list2,

				 ulong subchan_id, void *load_addr)

{

    u8 status;

    int sec = rec_list1;

    int sec_num = ((rec_list2 >> 32) & 0xffff) + 1;

    int sec_len = rec_list2 >> 48;

    ulong addr = (ulong)load_addr;



    if (sec_len != SECTOR_SIZE) {

        return -1;

    }



    sclp_print(".");

    status = virtio_read_many(sec, (void*)addr, sec_num);

    if (status) {

        virtio_panic("I/O Error");

    }

    addr += sec_num * SECTOR_SIZE;



    return addr;

}

