static void test_qemu_strtoul_max(void)

{

    char *str = g_strdup_printf("%lu", ULONG_MAX);

    char f = 'X';

    const char *endptr = &f;

    unsigned long res = 999;

    int err;



    err = qemu_strtoul(str, &endptr, 0, &res);



    g_assert_cmpint(err, ==, 0);

    g_assert_cmpint(res, ==, ULONG_MAX);

    g_assert(endptr == str + strlen(str));

    g_free(str);

}

static RawAIOCB *raw_aio_setup(BlockDriverState *bs, int64_t sector_num,

        QEMUIOVector *qiov, int nb_sectors,

        BlockDriverCompletionFunc *cb, void *opaque)

{

    BDRVRawState *s = bs->opaque;

    RawAIOCB *acb;



    if (fd_open(bs) < 0)

        return NULL;



    acb = qemu_aio_get(&raw_aio_pool, bs, cb, opaque);

    if (!acb)

        return NULL;

    acb->aiocb.aio_fildes = s->fd;

    acb->aiocb.ev_signo = SIGUSR2;

    acb->aiocb.aio_iov = qiov->iov;

    acb->aiocb.aio_niov = qiov->niov;

    acb->aiocb.aio_nbytes = nb_sectors * 512;

    acb->aiocb.aio_offset = sector_num * 512;

    acb->aiocb.aio_flags = 0;



    /*

     * If O_DIRECT is used the buffer needs to be aligned on a sector

     * boundary. Tell the low level code to ensure that in case it's

     * not done yet.

     */

    if (s->aligned_buf)

        acb->aiocb.aio_flags |= QEMU_AIO_SECTOR_ALIGNED;



    acb->next = posix_aio_state->first_aio;

    posix_aio_state->first_aio = acb;

    return acb;

}

static int vp3_decode_end(AVCodecContext *avctx)
{
    Vp3DecodeContext *s = avctx->priv_data;
    int i;
    av_free(s->superblock_coding);
    av_free(s->all_fragments);
    av_free(s->coeffs);
    av_free(s->coded_fragment_list);
    av_free(s->superblock_fragments);
    av_free(s->superblock_macroblocks);
    av_free(s->macroblock_fragments);
    av_free(s->macroblock_coding);
    /* release all frames */
    if (s->golden_frame.data[0] && s->golden_frame.data[0] != s->last_frame.data[0])
        avctx->release_buffer(avctx, &s->golden_frame);
    if (s->last_frame.data[0])
        avctx->release_buffer(avctx, &s->last_frame);
    /* no need to release the current_frame since it will always be pointing
     * to the same frame as either the golden or last frame */
    return 0;

static int flac_encode_frame(AVCodecContext *avctx, uint8_t *frame,

                             int buf_size, void *data)

{

    FlacEncodeContext *s;

    const int16_t *samples = data;

    int frame_bytes, out_bytes;



    s = avctx->priv_data;



    /* when the last block is reached, update the header in extradata */

    if (!data) {

        s->max_framesize = s->max_encoded_framesize;

        av_md5_final(s->md5ctx, s->md5sum);

        write_streaminfo(s, avctx->extradata);

        return 0;

    }



    /* change max_framesize for small final frame */

    if (avctx->frame_size < s->frame.blocksize) {

        s->max_framesize = ff_flac_get_max_frame_size(avctx->frame_size,

                                                      s->channels, 16);

    }



    init_frame(s);



    copy_samples(s, samples);



    channel_decorrelation(s);



    frame_bytes = encode_frame(s);

    if (buf_size < frame_bytes) {

        av_log(avctx, AV_LOG_ERROR, "output buffer too small\n");

        return 0;

    }

    out_bytes = write_frame(s, frame, buf_size);



    /* fallback to verbatim mode if the compressed frame is larger than it

       would be if encoded uncompressed. */

    if (out_bytes > s->max_framesize) {

        s->frame.verbatim_only = 1;

        frame_bytes = encode_frame(s);

        if (buf_size < frame_bytes) {

            av_log(avctx, AV_LOG_ERROR, "output buffer too small\n");

            return 0;

        }

        out_bytes = write_frame(s, frame, buf_size);

    }



    s->frame_count++;

    avctx->coded_frame->pts = s->sample_count;

    s->sample_count += avctx->frame_size;

    update_md5_sum(s, samples);

    if (out_bytes > s->max_encoded_framesize)

        s->max_encoded_framesize = out_bytes;

    if (out_bytes < s->min_framesize)

        s->min_framesize = out_bytes;



    return out_bytes;

}

build_rsdt(GArray *table_data, GArray *linker, GArray *table_offsets)

{

    AcpiRsdtDescriptorRev1 *rsdt;

    size_t rsdt_len;

    int i;

    const int table_data_len = (sizeof(uint32_t) * table_offsets->len);



    rsdt_len = sizeof(*rsdt) + table_data_len;

    rsdt = acpi_data_push(table_data, rsdt_len);

    memcpy(rsdt->table_offset_entry, table_offsets->data, table_data_len);

    for (i = 0; i < table_offsets->len; ++i) {

        /* rsdt->table_offset_entry to be filled by Guest linker */

        bios_linker_loader_add_pointer(linker,

                                       ACPI_BUILD_TABLE_FILE,

                                       ACPI_BUILD_TABLE_FILE,

                                       table_data, &rsdt->table_offset_entry[i],

                                       sizeof(uint32_t));

    }

    build_header(linker, table_data,

                 (void *)rsdt, "RSDT", rsdt_len, 1, NULL, NULL);

}

static int X264_frame(AVCodecContext *ctx, AVPacket *pkt, const AVFrame *frame,

                      int *got_packet)

{

    X264Context *x4 = ctx->priv_data;

    x264_nal_t *nal;

    int nnal, i, ret;

    x264_picture_t pic_out = {0};

    int pict_type;



    x264_picture_init( &x4->pic );

    x4->pic.img.i_csp   = x4->params.i_csp;

    if (x264_bit_depth > 8)

        x4->pic.img.i_csp |= X264_CSP_HIGH_DEPTH;

    x4->pic.img.i_plane = avfmt2_num_planes(ctx->pix_fmt);



    if (frame) {

        for (i = 0; i < x4->pic.img.i_plane; i++) {

            x4->pic.img.plane[i]    = frame->data[i];

            x4->pic.img.i_stride[i] = frame->linesize[i];

        }



        x4->pic.i_pts  = frame->pts;



        switch (frame->pict_type) {

        case AV_PICTURE_TYPE_I:

            x4->pic.i_type = x4->forced_idr > 0 ? X264_TYPE_IDR

                                                : X264_TYPE_KEYFRAME;

            break;

        case AV_PICTURE_TYPE_P:

            x4->pic.i_type = X264_TYPE_P;

            break;

        case AV_PICTURE_TYPE_B:

            x4->pic.i_type = X264_TYPE_B;

            break;

        default:

            x4->pic.i_type = X264_TYPE_AUTO;

            break;

        }

        reconfig_encoder(ctx, frame);



        if (x4->a53_cc) {

            void *sei_data;

            size_t sei_size;



            ret = ff_alloc_a53_sei(frame, 0, &sei_data, &sei_size);

            if (ret < 0) {

                av_log(ctx, AV_LOG_ERROR, "Not enough memory for closed captions, skipping\n");

            } else if (sei_data) {

                x4->pic.extra_sei.payloads = av_mallocz(sizeof(x4->pic.extra_sei.payloads[0]));

                if (x4->pic.extra_sei.payloads == NULL) {

                    av_log(ctx, AV_LOG_ERROR, "Not enough memory for closed captions, skipping\n");

                    av_free(sei_data);

                } else {

                    x4->pic.extra_sei.sei_free = av_free;



                    x4->pic.extra_sei.payloads[0].payload_size = sei_size;

                    x4->pic.extra_sei.payloads[0].payload = sei_data;

                    x4->pic.extra_sei.num_payloads = 1;

                    x4->pic.extra_sei.payloads[0].payload_type = 4;

                }

            }

        }

    }



    do {

        if (x264_encoder_encode(x4->enc, &nal, &nnal, frame? &x4->pic: NULL, &pic_out) < 0)

            return AVERROR_EXTERNAL;



        ret = encode_nals(ctx, pkt, nal, nnal);

        if (ret < 0)

            return ret;

    } while (!ret && !frame && x264_encoder_delayed_frames(x4->enc));



    pkt->pts = pic_out.i_pts;

    pkt->dts = pic_out.i_dts;





    switch (pic_out.i_type) {

    case X264_TYPE_IDR:

    case X264_TYPE_I:

        pict_type = AV_PICTURE_TYPE_I;

        break;

    case X264_TYPE_P:

        pict_type = AV_PICTURE_TYPE_P;

        break;

    case X264_TYPE_B:

    case X264_TYPE_BREF:

        pict_type = AV_PICTURE_TYPE_B;

        break;

    default:

        pict_type = AV_PICTURE_TYPE_NONE;

    }

#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

    ctx->coded_frame->pict_type = pict_type;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    pkt->flags |= AV_PKT_FLAG_KEY*pic_out.b_keyframe;

    if (ret) {

        ff_side_data_set_encoder_stats(pkt, (pic_out.i_qpplus1 - 1) * FF_QP2LAMBDA, NULL, 0, pict_type);



#if FF_API_CODED_FRAME

FF_DISABLE_DEPRECATION_WARNINGS

        ctx->coded_frame->quality = (pic_out.i_qpplus1 - 1) * FF_QP2LAMBDA;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

    }



    *got_packet = ret;

    return 0;

}

static int xen_host_pci_get_value(XenHostPCIDevice *d, const char *name,

                                  unsigned int *pvalue, int base)

{

    char path[PATH_MAX];

    char buf[XEN_HOST_PCI_GET_VALUE_BUFFER_SIZE];

    int fd, rc;

    unsigned long value;

    char *endptr;



    rc = xen_host_pci_sysfs_path(d, name, path, sizeof (path));

    if (rc) {

        return rc;

    }

    fd = open(path, O_RDONLY);

    if (fd == -1) {

        XEN_HOST_PCI_LOG("Error: Can't open %s: %s\n", path, strerror(errno));

        return -errno;

    }

    do {

        rc = read(fd, &buf, sizeof (buf) - 1);

        if (rc < 0 && errno != EINTR) {

            rc = -errno;

            goto out;

        }

    } while (rc < 0);

    buf[rc] = 0;

    value = strtol(buf, &endptr, base);

    if (endptr == buf || *endptr != '\n') {

        rc = -1;

    } else if ((value == LONG_MIN || value == LONG_MAX) && errno == ERANGE) {

        rc = -errno;

    } else {

        rc = 0;

        *pvalue = value;

    }

out:

    close(fd);

    return rc;

}

static int get_packetheader(NUTContext *nut, ByteIOContext *bc, int prefix_length)

{

    int64_t start, size, last_size;

    start= url_ftell(bc) - prefix_length;



    if(start != nut->packet_start + nut->written_packet_size){

        av_log(nut->avf, AV_LOG_ERROR, "get_packetheader called at weird position\n");

        return -1;

    }



    size= get_v(bc);

    last_size= get_v(bc);

    if(nut->written_packet_size != last_size){

        av_log(nut->avf, AV_LOG_ERROR, "packet size missmatch %d != %lld at %lld\n", nut->written_packet_size, last_size, start);

        return -1;

    }



    nut->last_packet_start = nut->packet_start;

    nut->packet_start = start;

    nut->written_packet_size= size;



    return size;

}

av_cold void ff_hpeldsp_init_x86(HpelDSPContext *c, int flags)

{

    int cpu_flags = av_get_cpu_flags();



    if (INLINE_MMX(cpu_flags))

        hpeldsp_init_mmx(c, flags);



    if (EXTERNAL_AMD3DNOW(cpu_flags))

        hpeldsp_init_3dnow(c, flags);



    if (EXTERNAL_MMXEXT(cpu_flags))

        hpeldsp_init_mmxext(c, flags);



    if (EXTERNAL_SSE2_FAST(cpu_flags))

        hpeldsp_init_sse2_fast(c, flags);



    if (CONFIG_VP3_DECODER)

        ff_hpeldsp_vp3_init_x86(c, cpu_flags, flags);

}

