static int kvm_put_msr_feature_control(X86CPU *cpu)

{

    struct {

        struct kvm_msrs info;

        struct kvm_msr_entry entry;

    } msr_data;



    kvm_msr_entry_set(&msr_data.entry, MSR_IA32_FEATURE_CONTROL,

                      cpu->env.msr_ia32_feature_control);

    msr_data.info.nmsrs = 1;

    return kvm_vcpu_ioctl(CPU(cpu), KVM_SET_MSRS, &msr_data);

}

int MPV_common_init(MpegEncContext *s)

{

    int c_size, i;

    UINT8 *pict;



    s->dct_unquantize_h263 = dct_unquantize_h263_c;

    s->dct_unquantize_mpeg1 = dct_unquantize_mpeg1_c;

    s->dct_unquantize_mpeg2 = dct_unquantize_mpeg2_c;



#ifdef HAVE_MMX

    MPV_common_init_mmx(s);

#endif

    //setup default unquantizers (mpeg4 might change it later)

    if(s->out_format == FMT_H263)

        s->dct_unquantize = s->dct_unquantize_h263;

    else

        s->dct_unquantize = s->dct_unquantize_mpeg1;



    s->mb_width = (s->width + 15) / 16;

    s->mb_height = (s->height + 15) / 16;

    s->mb_num = s->mb_width * s->mb_height;

    s->linesize = s->mb_width * 16 + 2 * EDGE_WIDTH;



    for(i=0;i<3;i++) {

        int w, h, shift, pict_start;



        w = s->linesize;

        h = s->mb_height * 16 + 2 * EDGE_WIDTH;

        shift = (i == 0) ? 0 : 1;

        c_size = (w >> shift) * (h >> shift);

        pict_start = (w >> shift) * (EDGE_WIDTH >> shift) + (EDGE_WIDTH >> shift);



        pict = av_mallocz(c_size);

        if (pict == NULL)

            goto fail;

        s->last_picture_base[i] = pict;

        s->last_picture[i] = pict + pict_start;



        pict = av_mallocz(c_size);

        if (pict == NULL)

            goto fail;

        s->next_picture_base[i] = pict;

        s->next_picture[i] = pict + pict_start;



        if (s->has_b_frames || s->codec_id==CODEC_ID_MPEG4) {

        /* Note the MPEG4 stuff is here cuz of buggy encoders which dont set the low_delay flag but 

           do low-delay encoding, so we cant allways distinguish b-frame containing streams from low_delay streams */

            pict = av_mallocz(c_size);

            if (pict == NULL) 

                goto fail;

            s->aux_picture_base[i] = pict;

            s->aux_picture[i] = pict + pict_start;

        }

    }



    if (s->encoding) {

        int j;

        int mv_table_size= (s->mb_width+2)*(s->mb_height+2);



        /* Allocate MB type table */

        s->mb_type = av_mallocz(s->mb_num * sizeof(char));

        if (s->mb_type == NULL) {

            perror("malloc");

            goto fail;

        }



        s->mb_var = av_mallocz(s->mb_num * sizeof(INT16));

        if (s->mb_var == NULL) {

            perror("malloc");

            goto fail;

        }



        /* Allocate MV tables */

        s->p_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->p_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->last_p_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->last_p_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_forw_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_forw_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_back_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_back_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_bidir_forw_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_bidir_forw_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_bidir_back_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_bidir_back_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_direct_forw_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_direct_forw_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_direct_back_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_direct_back_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }

        s->b_direct_mv_table = av_mallocz(mv_table_size * 2 * sizeof(INT16));

        if (s->b_direct_mv_table == NULL) {

            perror("malloc");

            goto fail;

        }



        s->me_scratchpad = av_mallocz( s->linesize*16*3*sizeof(uint8_t));

        if (s->me_scratchpad == NULL) {

            perror("malloc");

            goto fail;

        }



        if(s->max_b_frames){

            for(j=0; j<REORDER_BUFFER_SIZE; j++){

                int i;

                for(i=0;i<3;i++) {

                    int w, h, shift;



                    w = s->linesize;

                    h = s->mb_height * 16;

                    shift = (i == 0) ? 0 : 1;

                    c_size = (w >> shift) * (h >> shift);



                    pict = av_mallocz(c_size);

                    if (pict == NULL)

                        goto fail;

                    s->picture_buffer[j][i] = pict;

                }

            }

        }

    }



    if (s->out_format == FMT_H263 || s->encoding) {

        int size;

        /* MV prediction */

        size = (2 * s->mb_width + 2) * (2 * s->mb_height + 2);

        s->motion_val = av_malloc(size * 2 * sizeof(INT16));

        if (s->motion_val == NULL)

            goto fail;

        memset(s->motion_val, 0, size * 2 * sizeof(INT16));

    }



    if (s->h263_pred || s->h263_plus) {

        int y_size, c_size, i, size;



        /* dc values */



        y_size = (2 * s->mb_width + 2) * (2 * s->mb_height + 2);

        c_size = (s->mb_width + 2) * (s->mb_height + 2);

        size = y_size + 2 * c_size;

        s->dc_val[0] = av_malloc(size * sizeof(INT16));

        if (s->dc_val[0] == NULL)

            goto fail;

        s->dc_val[1] = s->dc_val[0] + y_size;

        s->dc_val[2] = s->dc_val[1] + c_size;

        for(i=0;i<size;i++)

            s->dc_val[0][i] = 1024;



        /* ac values */

        s->ac_val[0] = av_mallocz(size * sizeof(INT16) * 16);

        if (s->ac_val[0] == NULL)

            goto fail;

        s->ac_val[1] = s->ac_val[0] + y_size;

        s->ac_val[2] = s->ac_val[1] + c_size;



        /* cbp values */

        s->coded_block = av_mallocz(y_size);

        if (!s->coded_block)

            goto fail;



        /* which mb is a intra block */

        s->mbintra_table = av_mallocz(s->mb_num);

        if (!s->mbintra_table)

            goto fail;

        memset(s->mbintra_table, 1, s->mb_num);



        /* divx501 bitstream reorder buffer */

        s->bitstream_buffer= av_mallocz(BITSTREAM_BUFFER_SIZE);

        if (!s->bitstream_buffer)

            goto fail;

    }

    /* default structure is frame */

    s->picture_structure = PICT_FRAME;



    /* init macroblock skip table */

    s->mbskip_table = av_mallocz(s->mb_num);

    if (!s->mbskip_table)

        goto fail;



    s->block= s->blocks[0];



    s->context_initialized = 1;

    return 0;

 fail:

    MPV_common_end(s);

    return -1;

}

static void sun4m_common_init(int ram_size, int boot_device, DisplayState *ds,

                              const char *kernel_filename, const char *kernel_cmdline,

                              const char *initrd_filename, const char *cpu_model,

                              unsigned int machine, int max_ram)

{

    if ((unsigned int)ram_size > (unsigned int)max_ram) {

        fprintf(stderr, "qemu: Too much memory for this machine: %d, maximum %d\n",

                (unsigned int)ram_size / (1024 * 1024),

                (unsigned int)max_ram / (1024 * 1024));

        exit(1);

    }

    sun4m_hw_init(&hwdefs[machine], ram_size, ds, cpu_model);



    sun4m_load_kernel(hwdefs[machine].vram_size, ram_size, boot_device,

                      kernel_filename, kernel_cmdline, initrd_filename,

                      hwdefs[machine].machine_id);

}

static int tiff_unpack_strip(TiffContext *s, AVFrame *p, uint8_t *dst, int stride,

                             const uint8_t *src, int size, int strip_start, int lines)

{

    PutByteContext pb;

    int c, line, pixels, code, ret;

    const uint8_t *ssrc = src;

    int width = ((s->width * s->bpp) + 7) >> 3;

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(p->format);

    int is_yuv = !(desc->flags & AV_PIX_FMT_FLAG_RGB) && desc->nb_components >= 2;



    if (s->planar)

        width /= s->bppcount;



    if (size <= 0)

        return AVERROR_INVALIDDATA;



    if (is_yuv) {

        int bytes_per_row = (((s->width - 1) / s->subsampling[0] + 1) * s->bpp *

                            s->subsampling[0] * s->subsampling[1] + 7) >> 3;

        av_fast_padded_malloc(&s->yuv_line, &s->yuv_line_size, bytes_per_row);

        if (s->yuv_line == NULL) {

            av_log(s->avctx, AV_LOG_ERROR, "Not enough memory\n");

            return AVERROR(ENOMEM);

        }

        dst = s->yuv_line;

        stride = 0;

        width = s->width * s->subsampling[1] + 2*(s->width / s->subsampling[0]);

        av_assert0(width <= bytes_per_row);

        av_assert0(s->bpp == 24);

    }



    if (s->compr == TIFF_DEFLATE || s->compr == TIFF_ADOBE_DEFLATE) {

#if CONFIG_ZLIB

        return tiff_unpack_zlib(s, p, dst, stride, src, size, width, lines,

                                strip_start, is_yuv);

#else

        av_log(s->avctx, AV_LOG_ERROR,

               "zlib support not enabled, "

               "deflate compression not supported\n");

        return AVERROR(ENOSYS);

#endif

    }

    if (s->compr == TIFF_LZMA) {

#if CONFIG_LZMA

        return tiff_unpack_lzma(s, p, dst, stride, src, size, width, lines,

                                strip_start, is_yuv);

#else

        av_log(s->avctx, AV_LOG_ERROR,

               "LZMA support not enabled\n");

        return AVERROR(ENOSYS);

#endif

    }

    if (s->compr == TIFF_LZW) {

        if (s->fill_order) {

            if ((ret = deinvert_buffer(s, src, size)) < 0)

                return ret;

            ssrc = src = s->deinvert_buf;

        }

        if (size > 1 && !src[0] && (src[1]&1)) {

            av_log(s->avctx, AV_LOG_ERROR, "Old style LZW is unsupported\n");

        }

        if ((ret = ff_lzw_decode_init(s->lzw, 8, src, size, FF_LZW_TIFF)) < 0) {

            av_log(s->avctx, AV_LOG_ERROR, "Error initializing LZW decoder\n");

            return ret;

        }

        for (line = 0; line < lines; line++) {

            pixels = ff_lzw_decode(s->lzw, dst, width);

            if (pixels < width) {

                av_log(s->avctx, AV_LOG_ERROR, "Decoded only %i bytes of %i\n",

                       pixels, width);

                return AVERROR_INVALIDDATA;

            }

            if (s->bpp < 8 && s->avctx->pix_fmt == AV_PIX_FMT_PAL8)

                horizontal_fill(s->bpp, dst, 1, dst, 0, width, 0);

            if (is_yuv) {

                unpack_yuv(s, p, dst, strip_start + line);

                line += s->subsampling[1] - 1;

            }

            dst += stride;

        }

        return 0;

    }

    if (s->compr == TIFF_CCITT_RLE ||

        s->compr == TIFF_G3        ||

        s->compr == TIFF_G4) {

        if (is_yuv)

            return AVERROR_INVALIDDATA;



        return tiff_unpack_fax(s, dst, stride, src, size, width, lines);

    }



    bytestream2_init(&s->gb, src, size);

    bytestream2_init_writer(&pb, dst, is_yuv ? s->yuv_line_size : (stride * lines));



    for (line = 0; line < lines; line++) {

        if (src - ssrc > size) {

            av_log(s->avctx, AV_LOG_ERROR, "Source data overread\n");

            return AVERROR_INVALIDDATA;

        }



        if (bytestream2_get_bytes_left(&s->gb) == 0 || bytestream2_get_eof(&pb))

            break;

        bytestream2_seek_p(&pb, stride * line, SEEK_SET);

        switch (s->compr) {

        case TIFF_RAW:

            if (ssrc + size - src < width)

                return AVERROR_INVALIDDATA;



            if (!s->fill_order) {

                horizontal_fill(s->bpp * (s->avctx->pix_fmt == AV_PIX_FMT_PAL8),

                                dst, 1, src, 0, width, 0);

            } else {

                int i;

                for (i = 0; i < width; i++)

                    dst[i] = ff_reverse[src[i]];

            }

            src += width;

            break;

        case TIFF_PACKBITS:

            for (pixels = 0; pixels < width;) {

                if (ssrc + size - src < 2) {

                    av_log(s->avctx, AV_LOG_ERROR, "Read went out of bounds\n");

                    return AVERROR_INVALIDDATA;

                }

                code = s->fill_order ? (int8_t) ff_reverse[*src++]: (int8_t) *src++;

                if (code >= 0) {

                    code++;

                    if (pixels + code > width ||

                        ssrc + size - src < code) {

                        av_log(s->avctx, AV_LOG_ERROR,

                               "Copy went out of bounds\n");

                        return AVERROR_INVALIDDATA;

                    }

                    horizontal_fill(s->bpp * (s->avctx->pix_fmt == AV_PIX_FMT_PAL8),

                                    dst, 1, src, 0, code, pixels);

                    src    += code;

                    pixels += code;

                } else if (code != -128) { // -127..-1

                    code = (-code) + 1;

                    if (pixels + code > width) {

                        av_log(s->avctx, AV_LOG_ERROR,

                               "Run went out of bounds\n");

                        return AVERROR_INVALIDDATA;

                    }

                    c = *src++;

                    horizontal_fill(s->bpp * (s->avctx->pix_fmt == AV_PIX_FMT_PAL8),

                                    dst, 0, NULL, c, code, pixels);

                    pixels += code;

                }

            }

            if (s->fill_order) {

                int i;

                for (i = 0; i < width; i++)

                    dst[i] = ff_reverse[dst[i]];

            }

            break;

        }

        if (is_yuv) {

            unpack_yuv(s, p, dst, strip_start + line);

            line += s->subsampling[1] - 1;

        }

        dst += stride;

    }

    return 0;

}

void parse_option_size(const char *name, const char *value,

                       uint64_t *ret, Error **errp)

{

    uint64_t size;

    int err;



    err = qemu_strtosz(value, NULL, &size);

    if (err == -ERANGE) {

        error_setg(errp, "Value '%s' is too large for parameter '%s'",

                   value, name);

        return;

    }

    if (err) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, name,

                   "a non-negative number below 2^64");

        error_append_hint(errp, "Optional suffix k, M, G, T, P or E means"

                          " kilo-, mega-, giga-, tera-, peta-\n"

                          "and exabytes, respectively.\n");

        return;

    }

    *ret = size;

}

void arm_cpu_realize(ARMCPU *cpu)

{

    /* This function is called by cpu_arm_init() because it

     * needs to do common actions based on feature bits, etc

     * that have been set by the subclass init functions.

     * When we have QOM realize support it should become

     * a true realize function instead.

     */

    CPUARMState *env = &cpu->env;

    /* Some features automatically imply others: */

    if (arm_feature(env, ARM_FEATURE_V7)) {

        set_feature(env, ARM_FEATURE_VAPA);

        set_feature(env, ARM_FEATURE_THUMB2);

        set_feature(env, ARM_FEATURE_MPIDR);

        if (!arm_feature(env, ARM_FEATURE_M)) {

            set_feature(env, ARM_FEATURE_V6K);

        } else {

            set_feature(env, ARM_FEATURE_V6);



    if (arm_feature(env, ARM_FEATURE_V6K)) {

        set_feature(env, ARM_FEATURE_V6);

        set_feature(env, ARM_FEATURE_MVFR);


    if (arm_feature(env, ARM_FEATURE_V6)) {

        set_feature(env, ARM_FEATURE_V5);

        if (!arm_feature(env, ARM_FEATURE_M)) {

            set_feature(env, ARM_FEATURE_AUXCR);



    if (arm_feature(env, ARM_FEATURE_V5)) {

        set_feature(env, ARM_FEATURE_V4T);


    if (arm_feature(env, ARM_FEATURE_M)) {

        set_feature(env, ARM_FEATURE_THUMB_DIV);


    if (arm_feature(env, ARM_FEATURE_ARM_DIV)) {

        set_feature(env, ARM_FEATURE_THUMB_DIV);


    if (arm_feature(env, ARM_FEATURE_VFP4)) {

        set_feature(env, ARM_FEATURE_VFP3);


    if (arm_feature(env, ARM_FEATURE_VFP3)) {

        set_feature(env, ARM_FEATURE_VFP);







    register_cp_regs_for_features(cpu);

static VirtIOBlockReq *virtio_blk_alloc_request(VirtIOBlock *s)

{

    VirtIOBlockReq *req = g_slice_new(VirtIOBlockReq);

    req->dev = s;

    req->qiov.size = 0;

    req->next = NULL;

    req->elem = g_slice_new(VirtQueueElement);

    return req;

}

static inline void get_limits(MpegEncContext *s, int *range, int *xmin, int *ymin, int *xmax, int *ymax, int f_code)

{

    *range = 8 * (1 << (f_code - 1));

    /* XXX: temporary kludge to avoid overflow for msmpeg4 */

    if (s->out_format == FMT_H263 && !s->h263_msmpeg4)

	*range *= 2;



    if (s->unrestricted_mv) {

        *xmin = -16;

        *ymin = -16;

        if (s->h263_plus)

            *range *= 2;

        if(s->avctx->codec->id!=CODEC_ID_MPEG4){

            *xmax = s->mb_width*16;

            *ymax = s->mb_height*16;

        }else {

            *xmax = s->width;

            *ymax = s->height;

        }

    } else {

        *xmin = 0;

        *ymin = 0;

        *xmax = s->mb_width*16 - 16;

        *ymax = s->mb_height*16 - 16;

    }

}

opts_type_uint64(Visitor *v, uint64_t *obj, const char *name, Error **errp)

{

    OptsVisitor *ov = DO_UPCAST(OptsVisitor, visitor, v);

    const QemuOpt *opt;

    const char *str;

    unsigned long long val;

    char *endptr;



    if (ov->list_mode == LM_UNSIGNED_INTERVAL) {

        *obj = ov->range_next.u;

        return;

    }



    opt = lookup_scalar(ov, name, errp);

    if (!opt) {

        return;

    }

    str = opt->str;



    /* we've gotten past lookup_scalar() */

    assert(ov->list_mode == LM_NONE || ov->list_mode == LM_IN_PROGRESS);



    if (parse_uint(str, &val, &endptr, 0) == 0 && val <= UINT64_MAX) {

        if (*endptr == '\0') {

            *obj = val;

            processed(ov, name);

            return;

        }

        if (*endptr == '-' && ov->list_mode == LM_IN_PROGRESS) {

            unsigned long long val2;



            str = endptr + 1;

            if (parse_uint_full(str, &val2, 0) == 0 &&

                val2 <= UINT64_MAX && val <= val2) {

                ov->range_next.u = val;

                ov->range_limit.u = val2;

                ov->list_mode = LM_UNSIGNED_INTERVAL;



                /* as if entering on the top */

                *obj = ov->range_next.u;

                return;

            }

        }

    }

    error_set(errp, QERR_INVALID_PARAMETER_VALUE, opt->name,

              (ov->list_mode == LM_NONE) ? "a uint64 value" :

                                           "a uint64 value or range");

}

void do_POWER_dozo (void)

{

    if (Ts1 > Ts0) {

        T2 = T0;

        T0 = T1 - T0;

        if (((~T2) ^ T1 ^ (-1)) & ((~T2) ^ T0) & (1 << 31)) {

            xer_so = 1;

            xer_ov = 1;

        } else {

            xer_ov = 0;

        }

    } else {

        T0 = 0;

        xer_ov = 0;

    }

}

