static void onenand_reset(OneNANDState *s, int cold)

{

    memset(&s->addr, 0, sizeof(s->addr));

    s->command = 0;

    s->count = 1;

    s->bufaddr = 0;

    s->config[0] = 0x40c0;

    s->config[1] = 0x0000;

    onenand_intr_update(s);

    qemu_irq_raise(s->rdy);

    s->status = 0x0000;

    s->intstatus = cold ? 0x8080 : 0x8010;

    s->unladdr[0] = 0;

    s->unladdr[1] = 0;

    s->wpstatus = 0x0002;

    s->cycle = 0;

    s->otpmode = 0;

    s->bdrv_cur = s->bdrv;

    s->current = s->image;

    s->secs_cur = s->secs;



    if (cold) {

        /* Lock the whole flash */

        memset(s->blockwp, ONEN_LOCK_LOCKED, s->blocks);



        if (s->bdrv_cur && bdrv_read(s->bdrv_cur, 0, s->boot[0], 8) < 0) {

            hw_error("%s: Loading the BootRAM failed.\n", __func__);

        }

    }

}

int kvm_arch_on_sigbus_vcpu(CPUState *env, int code, void *addr)

{

#ifdef KVM_CAP_MCE

    ram_addr_t ram_addr;

    target_phys_addr_t paddr;



    if ((env->mcg_cap & MCG_SER_P) && addr

        && (code == BUS_MCEERR_AR || code == BUS_MCEERR_AO)) {

        if (qemu_ram_addr_from_host(addr, &ram_addr) ||

            !kvm_physical_memory_addr_from_ram(env->kvm_state, ram_addr,

                                               &paddr)) {

            fprintf(stderr, "Hardware memory error for memory used by "

                    "QEMU itself instead of guest system!\n");

            /* Hope we are lucky for AO MCE */

            if (code == BUS_MCEERR_AO) {

                return 0;

            } else {

                hardware_memory_error();

            }

        }


        kvm_mce_inject(env, paddr, code);

    } else

#endif /* KVM_CAP_MCE */

    {

        if (code == BUS_MCEERR_AO) {

            return 0;

        } else if (code == BUS_MCEERR_AR) {

            hardware_memory_error();

        } else {

            return 1;

        }

    }

    return 0;

}

static int open_f(BlockBackend *blk, int argc, char **argv)

{

    int flags = BDRV_O_UNMAP;

    int readonly = 0;

    bool writethrough = true;

    int c;

    QemuOpts *qopts;

    QDict *opts;

    bool force_share = false;



    while ((c = getopt(argc, argv, "snro:kt:d:U")) != -1) {

        switch (c) {

        case 's':

            flags |= BDRV_O_SNAPSHOT;

            break;

        case 'n':

            flags |= BDRV_O_NOCACHE;

            writethrough = false;

            break;

        case 'r':

            readonly = 1;

            break;

        case 'k':

            flags |= BDRV_O_NATIVE_AIO;

            break;

        case 't':

            if (bdrv_parse_cache_mode(optarg, &flags, &writethrough) < 0) {

                error_report("Invalid cache option: %s", optarg);

                qemu_opts_reset(&empty_opts);

                return 0;

            }

            break;

        case 'd':

            if (bdrv_parse_discard_flags(optarg, &flags) < 0) {

                error_report("Invalid discard option: %s", optarg);

                qemu_opts_reset(&empty_opts);

                return 0;

            }

            break;

        case 'o':

            if (imageOpts) {

                printf("--image-opts and 'open -o' are mutually exclusive\n");

                qemu_opts_reset(&empty_opts);

                return 0;

            }

            if (!qemu_opts_parse_noisily(&empty_opts, optarg, false)) {

                qemu_opts_reset(&empty_opts);

                return 0;

            }

            break;

        case 'U':

            force_share = true;

            break;

        default:

            qemu_opts_reset(&empty_opts);

            return qemuio_command_usage(&open_cmd);

        }

    }



    if (!readonly) {

        flags |= BDRV_O_RDWR;

    }



    if (imageOpts && (optind == argc - 1)) {

        if (!qemu_opts_parse_noisily(&empty_opts, argv[optind], false)) {

            qemu_opts_reset(&empty_opts);

            return 0;

        }

        optind++;

    }



    qopts = qemu_opts_find(&empty_opts, NULL);

    opts = qopts ? qemu_opts_to_qdict(qopts, NULL) : NULL;

    qemu_opts_reset(&empty_opts);



    if (optind == argc - 1) {

        openfile(argv[optind], flags, writethrough, force_share, opts);

    } else if (optind == argc) {

        openfile(NULL, flags, writethrough, force_share, opts);

    } else {

        QDECREF(opts);

        qemuio_command_usage(&open_cmd);

    }

    return 0;

}

static void commit_complete(BlockJob *job, void *opaque)

{

    CommitBlockJob *s = container_of(job, CommitBlockJob, common);

    CommitCompleteData *data = opaque;

    BlockDriverState *active = s->active;

    BlockDriverState *top = blk_bs(s->top);

    BlockDriverState *base = blk_bs(s->base);

    BlockDriverState *overlay_bs = bdrv_find_overlay(active, top);

    int ret = data->ret;



    if (!block_job_is_cancelled(&s->common) && ret == 0) {

        /* success */

        ret = bdrv_drop_intermediate(active, top, base, s->backing_file_str);

    }



    /* restore base open flags here if appropriate (e.g., change the base back

     * to r/o). These reopens do not need to be atomic, since we won't abort

     * even on failure here */

    if (s->base_flags != bdrv_get_flags(base)) {

        bdrv_reopen(base, s->base_flags, NULL);

    }

    if (overlay_bs && s->orig_overlay_flags != bdrv_get_flags(overlay_bs)) {

        bdrv_reopen(overlay_bs, s->orig_overlay_flags, NULL);

    }

    g_free(s->backing_file_str);

    blk_unref(s->top);

    blk_unref(s->base);

    block_job_completed(&s->common, ret);

    g_free(data);

}

uint32_t HELPER(msa)(CPUS390XState *env, uint32_t r1, uint32_t r2, uint32_t r3,

                     uint32_t type)

{

    const uintptr_t ra = GETPC();

    const uint8_t mod = env->regs[0] & 0x80ULL;

    const uint8_t fc = env->regs[0] & 0x7fULL;

    CPUState *cs = CPU(s390_env_get_cpu(env));

    uint8_t subfunc[16] = { 0 };

    uint64_t param_addr;

    int i;



    switch (type) {

    case S390_FEAT_TYPE_KMAC:

    case S390_FEAT_TYPE_KIMD:

    case S390_FEAT_TYPE_KLMD:

    case S390_FEAT_TYPE_PCKMO:

    case S390_FEAT_TYPE_PCC:

        if (mod) {

            cpu_restore_state(cs, ra);

            program_interrupt(env, PGM_SPECIFICATION, 4);

            return 0;

        }

        break;

    }



    s390_get_feat_block(type, subfunc);

    if (!test_be_bit(fc, subfunc)) {

        cpu_restore_state(cs, ra);

        program_interrupt(env, PGM_SPECIFICATION, 4);

        return 0;

    }



    switch (fc) {

    case 0: /* query subfunction */

        for (i = 0; i < 16; i++) {

            param_addr = wrap_address(env, env->regs[1] + i);

            cpu_stb_data_ra(env, param_addr, subfunc[i], ra);

        }

        break;

    default:

        /* we don't implement any other subfunction yet */

        g_assert_not_reached();

    }



    return 0;

}

AVStream *add_av_stream1(FFStream *stream, AVCodecContext *codec)

{

    AVStream *fst;



    fst = av_mallocz(sizeof(AVStream));

    if (!fst)

        return NULL;

    fst->priv_data = av_mallocz(sizeof(FeedData));

    memcpy(&fst->codec, codec, sizeof(AVCodecContext));


    stream->streams[stream->nb_streams++] = fst;

    return fst;

}

void cpu_x86_cpuid(CPUX86State *env, uint32_t index, uint32_t count,

                   uint32_t *eax, uint32_t *ebx,

                   uint32_t *ecx, uint32_t *edx)

{

    X86CPU *cpu = x86_env_get_cpu(env);

    CPUState *cs = CPU(cpu);



    /* test if maximum index reached */

    if (index & 0x80000000) {

        if (index > env->cpuid_xlevel) {

            if (env->cpuid_xlevel2 > 0) {

                /* Handle the Centaur's CPUID instruction. */

                if (index > env->cpuid_xlevel2) {

                    index = env->cpuid_xlevel2;

                } else if (index < 0xC0000000) {

                    index = env->cpuid_xlevel;


            } else {

                /* Intel documentation states that invalid EAX input will

                 * return the same information as EAX=cpuid_level

                 * (Intel SDM Vol. 2A - Instruction Set Reference - CPUID)

                 */

                index =  env->cpuid_level;



    } else {

        if (index > env->cpuid_level)

            index = env->cpuid_level;




    switch(index) {

    case 0:

        *eax = env->cpuid_level;

        get_cpuid_vendor(env, ebx, ecx, edx);


    case 1:

        *eax = env->cpuid_version;

        *ebx = (env->cpuid_apic_id << 24) | 8 << 8; /* CLFLUSH size in quad words, Linux wants it. */

        *ecx = env->features[FEAT_1_ECX];

        *edx = env->features[FEAT_1_EDX];

        if (cs->nr_cores * cs->nr_threads > 1) {

            *ebx |= (cs->nr_cores * cs->nr_threads) << 16;

            *edx |= 1 << 28;    /* HTT bit */



    case 2:

        /* cache info: needed for Pentium Pro compatibility */


            host_cpuid(index, 0, eax, ebx, ecx, edx);



        *eax = 1; /* Number of CPUID[EAX=2] calls required */

        *ebx = 0;

        *ecx = 0;

        *edx = (L1D_DESCRIPTOR << 16) | \

               (L1I_DESCRIPTOR <<  8) | \

               (L2_DESCRIPTOR);


    case 4:

        /* cache info: needed for Core compatibility */





        if (cs->nr_cores > 1) {

            *eax = (cs->nr_cores - 1) << 26;

        } else {

            *eax = 0;


        switch (count) {

            case 0: /* L1 dcache info */

                *eax |= CPUID_4_TYPE_DCACHE | \

                        CPUID_4_LEVEL(1) | \

                        CPUID_4_SELF_INIT_LEVEL;

                *ebx = (L1D_LINE_SIZE - 1) | \

                       ((L1D_PARTITIONS - 1) << 12) | \

                       ((L1D_ASSOCIATIVITY - 1) << 22);

                *ecx = L1D_SETS - 1;

                *edx = CPUID_4_NO_INVD_SHARING;


            case 1: /* L1 icache info */

                *eax |= CPUID_4_TYPE_ICACHE | \

                        CPUID_4_LEVEL(1) | \

                        CPUID_4_SELF_INIT_LEVEL;

                *ebx = (L1I_LINE_SIZE - 1) | \

                       ((L1I_PARTITIONS - 1) << 12) | \

                       ((L1I_ASSOCIATIVITY - 1) << 22);

                *ecx = L1I_SETS - 1;

                *edx = CPUID_4_NO_INVD_SHARING;


            case 2: /* L2 cache info */

                *eax |= CPUID_4_TYPE_UNIFIED | \

                        CPUID_4_LEVEL(2) | \

                        CPUID_4_SELF_INIT_LEVEL;

                if (cs->nr_threads > 1) {

                    *eax |= (cs->nr_threads - 1) << 14;


                *ebx = (L2_LINE_SIZE - 1) | \

                       ((L2_PARTITIONS - 1) << 12) | \

                       ((L2_ASSOCIATIVITY - 1) << 22);

                *ecx = L2_SETS - 1;

                *edx = CPUID_4_NO_INVD_SHARING;


            default: /* end of info */

                *eax = 0;

                *ebx = 0;

                *ecx = 0;

                *edx = 0;




    case 5:

        /* mwait info: needed for Core compatibility */

        *eax = 0; /* Smallest monitor-line size in bytes */

        *ebx = 0; /* Largest monitor-line size in bytes */

        *ecx = CPUID_MWAIT_EMX | CPUID_MWAIT_IBE;

        *edx = 0;


    case 6:

        /* Thermal and Power Leaf */

        *eax = 0;

        *ebx = 0;

        *ecx = 0;

        *edx = 0;


    case 7:

        /* Structured Extended Feature Flags Enumeration Leaf */

        if (count == 0) {

            *eax = 0; /* Maximum ECX value for sub-leaves */

            *ebx = env->features[FEAT_7_0_EBX]; /* Feature flags */

            *ecx = 0; /* Reserved */

            *edx = 0; /* Reserved */

        } else {

            *eax = 0;

            *ebx = 0;

            *ecx = 0;

            *edx = 0;



    case 9:

        /* Direct Cache Access Information Leaf */

        *eax = 0; /* Bits 0-31 in DCA_CAP MSR */

        *ebx = 0;

        *ecx = 0;

        *edx = 0;


    case 0xA:

        /* Architectural Performance Monitoring Leaf */

        if (kvm_enabled() && cpu->enable_pmu) {

            KVMState *s = cs->kvm_state;



            *eax = kvm_arch_get_supported_cpuid(s, 0xA, count, R_EAX);

            *ebx = kvm_arch_get_supported_cpuid(s, 0xA, count, R_EBX);

            *ecx = kvm_arch_get_supported_cpuid(s, 0xA, count, R_ECX);

            *edx = kvm_arch_get_supported_cpuid(s, 0xA, count, R_EDX);

        } else {

            *eax = 0;

            *ebx = 0;

            *ecx = 0;

            *edx = 0;



    case 0xD:

        /* Processor Extended State */

        if (!(env->features[FEAT_1_ECX] & CPUID_EXT_XSAVE)) {

            *eax = 0;

            *ebx = 0;

            *ecx = 0;

            *edx = 0;



        if (kvm_enabled()) {

            KVMState *s = cs->kvm_state;



            *eax = kvm_arch_get_supported_cpuid(s, 0xd, count, R_EAX);

            *ebx = kvm_arch_get_supported_cpuid(s, 0xd, count, R_EBX);

            *ecx = kvm_arch_get_supported_cpuid(s, 0xd, count, R_ECX);

            *edx = kvm_arch_get_supported_cpuid(s, 0xd, count, R_EDX);

        } else {

            *eax = 0;

            *ebx = 0;

            *ecx = 0;

            *edx = 0;



    case 0x80000000:

        *eax = env->cpuid_xlevel;

        *ebx = env->cpuid_vendor1;

        *edx = env->cpuid_vendor2;

        *ecx = env->cpuid_vendor3;


    case 0x80000001:

        *eax = env->cpuid_version;

        *ebx = 0;

        *ecx = env->features[FEAT_8000_0001_ECX];

        *edx = env->features[FEAT_8000_0001_EDX];



        /* The Linux kernel checks for the CMPLegacy bit and

         * discards multiple thread information if it is set.

         * So dont set it here for Intel to make Linux guests happy.

         */

        if (cs->nr_cores * cs->nr_threads > 1) {

            uint32_t tebx, tecx, tedx;

            get_cpuid_vendor(env, &tebx, &tecx, &tedx);

            if (tebx != CPUID_VENDOR_INTEL_1 ||

                tedx != CPUID_VENDOR_INTEL_2 ||

                tecx != CPUID_VENDOR_INTEL_3) {

                *ecx |= 1 << 1;    /* CmpLegacy bit */




    case 0x80000002:

    case 0x80000003:

    case 0x80000004:

        *eax = env->cpuid_model[(index - 0x80000002) * 4 + 0];

        *ebx = env->cpuid_model[(index - 0x80000002) * 4 + 1];

        *ecx = env->cpuid_model[(index - 0x80000002) * 4 + 2];

        *edx = env->cpuid_model[(index - 0x80000002) * 4 + 3];


    case 0x80000005:

        /* cache info (L1 cache) */


            host_cpuid(index, 0, eax, ebx, ecx, edx);



        *eax = (L1_DTLB_2M_ASSOC << 24) | (L1_DTLB_2M_ENTRIES << 16) | \

               (L1_ITLB_2M_ASSOC <<  8) | (L1_ITLB_2M_ENTRIES);

        *ebx = (L1_DTLB_4K_ASSOC << 24) | (L1_DTLB_4K_ENTRIES << 16) | \

               (L1_ITLB_4K_ASSOC <<  8) | (L1_ITLB_4K_ENTRIES);

        *ecx = (L1D_SIZE_KB_AMD << 24) | (L1D_ASSOCIATIVITY_AMD << 16) | \

               (L1D_LINES_PER_TAG << 8) | (L1D_LINE_SIZE);

        *edx = (L1I_SIZE_KB_AMD << 24) | (L1I_ASSOCIATIVITY_AMD << 16) | \

               (L1I_LINES_PER_TAG << 8) | (L1I_LINE_SIZE);


    case 0x80000006:

        /* cache info (L2 cache) */


            host_cpuid(index, 0, eax, ebx, ecx, edx);



        *eax = (AMD_ENC_ASSOC(L2_DTLB_2M_ASSOC) << 28) | \

               (L2_DTLB_2M_ENTRIES << 16) | \

               (AMD_ENC_ASSOC(L2_ITLB_2M_ASSOC) << 12) | \

               (L2_ITLB_2M_ENTRIES);

        *ebx = (AMD_ENC_ASSOC(L2_DTLB_4K_ASSOC) << 28) | \

               (L2_DTLB_4K_ENTRIES << 16) | \

               (AMD_ENC_ASSOC(L2_ITLB_4K_ASSOC) << 12) | \

               (L2_ITLB_4K_ENTRIES);

        *ecx = (L2_SIZE_KB_AMD << 16) | \

               (AMD_ENC_ASSOC(L2_ASSOCIATIVITY) << 12) | \

               (L2_LINES_PER_TAG << 8) | (L2_LINE_SIZE);

        *edx = ((L3_SIZE_KB/512) << 18) | \

               (AMD_ENC_ASSOC(L3_ASSOCIATIVITY) << 12) | \

               (L3_LINES_PER_TAG << 8) | (L3_LINE_SIZE);


    case 0x80000008:

        /* virtual & phys address size in low 2 bytes. */

/* XXX: This value must match the one used in the MMU code. */

        if (env->features[FEAT_8000_0001_EDX] & CPUID_EXT2_LM) {

            /* 64 bit processor */

/* XXX: The physical address space is limited to 42 bits in exec.c. */

            *eax = 0x00003028; /* 48 bits virtual, 40 bits physical */

        } else {

            if (env->features[FEAT_1_EDX] & CPUID_PSE36) {

                *eax = 0x00000024; /* 36 bits physical */

            } else {

                *eax = 0x00000020; /* 32 bits physical */



        *ebx = 0;

        *ecx = 0;

        *edx = 0;

        if (cs->nr_cores * cs->nr_threads > 1) {

            *ecx |= (cs->nr_cores * cs->nr_threads) - 1;



    case 0x8000000A:

        if (env->features[FEAT_8000_0001_ECX] & CPUID_EXT3_SVM) {

            *eax = 0x00000001; /* SVM Revision */

            *ebx = 0x00000010; /* nr of ASIDs */

            *ecx = 0;

            *edx = env->features[FEAT_SVM]; /* optional features */

        } else {

            *eax = 0;

            *ebx = 0;

            *ecx = 0;

            *edx = 0;



    case 0xC0000000:

        *eax = env->cpuid_xlevel2;

        *ebx = 0;

        *ecx = 0;

        *edx = 0;


    case 0xC0000001:

        /* Support for VIA CPU's CPUID instruction */

        *eax = env->cpuid_version;

        *ebx = 0;

        *ecx = 0;

        *edx = env->features[FEAT_C000_0001_EDX];


    case 0xC0000002:

    case 0xC0000003:

    case 0xC0000004:

        /* Reserved for the future, and now filled with zero */

        *eax = 0;

        *ebx = 0;

        *ecx = 0;

        *edx = 0;


    default:

        /* reserved values: zero */

        *eax = 0;

        *ebx = 0;

        *ecx = 0;

        *edx = 0;

static void bonito_spciconf_writew(void *opaque, target_phys_addr_t addr,

                                   uint32_t val)

{

    PCIBonitoState *s = opaque;

    PCIDevice *d = PCI_DEVICE(s);

    PCIHostState *phb = PCI_HOST_BRIDGE(s->pcihost);

    uint32_t pciaddr;

    uint16_t status;



    DPRINTF("bonito_spciconf_writew "TARGET_FMT_plx" val %x\n", addr, val);

    assert((addr & 0x1) == 0);



    pciaddr = bonito_sbridge_pciaddr(s, addr);



    if (pciaddr == 0xffffffff) {

        return;

    }



    /* set the pci address in s->config_reg */

    phb->config_reg = (pciaddr) | (1u << 31);

    pci_data_write(phb->bus, phb->config_reg, val, 2);



    /* clear PCI_STATUS_REC_MASTER_ABORT and PCI_STATUS_REC_TARGET_ABORT */

    status = pci_get_word(d->config + PCI_STATUS);

    status &= ~(PCI_STATUS_REC_MASTER_ABORT | PCI_STATUS_REC_TARGET_ABORT);

    pci_set_word(d->config + PCI_STATUS, status);

}

static void qerror_set_data(QError *qerr, const char *fmt, va_list *va)

{

    QObject *obj;



    obj = qobject_from_jsonv(fmt, va);

    if (!obj) {

        qerror_abort(qerr, "invalid format '%s'", fmt);

    }

    if (qobject_type(obj) != QTYPE_QDICT) {

        qerror_abort(qerr, "error format is not a QDict '%s'", fmt);

    }



    qerr->error = qobject_to_qdict(obj);



    obj = qdict_get(qerr->error, "class");

    if (!obj) {

        qerror_abort(qerr, "missing 'class' key in '%s'", fmt);

    }

    if (qobject_type(obj) != QTYPE_QSTRING) {

        qerror_abort(qerr, "'class' key value should be a QString");

    }



    obj = qdict_get(qerr->error, "data");

    if (!obj) {

        qerror_abort(qerr, "missing 'data' key in '%s'", fmt);

    }

    if (qobject_type(obj) != QTYPE_QDICT) {

        qerror_abort(qerr, "'data' key value should be a QDICT");

    }

}

static inline bool vtd_iova_range_check(uint64_t iova, VTDContextEntry *ce)

{

    /*

     * Check if @iova is above 2^X-1, where X is the minimum of MGAW

     * in CAP_REG and AW in context-entry.

     */

    return !(iova & ~(vtd_iova_limit(ce) - 1));

}

static void put_bool(QEMUFile *f, void *pv, size_t size)

{

    bool *v = pv;

    qemu_put_byte(f, *v);

}

static int local_lremovexattr(FsContext *ctx,

                              const char *path, const char *name)

{

    if ((ctx->fs_sm == SM_MAPPED) &&

        (strncmp(name, "user.virtfs.", 12) == 0)) {

        /*

         * Don't allow fetch of user.virtfs namesapce

         * in case of mapped security

         */

        errno = EACCES;

        return -1;

    }

    return lremovexattr(rpath(ctx, path), name);

}

int ff_hevc_decode_nal_vps(HEVCContext *s)

{

    int i,j;

    GetBitContext *gb = &s->HEVClc.gb;

    int vps_id = 0;

    HEVCVPS *vps;

    AVBufferRef *vps_buf = av_buffer_allocz(sizeof(*vps));



    if (!vps_buf)

      return AVERROR(ENOMEM);

    vps = (HEVCVPS*)vps_buf->data;



    av_log(s->avctx, AV_LOG_DEBUG, "Decoding VPS\n");



    vps_id = get_bits(gb, 4);

    if (vps_id >= MAX_VPS_COUNT) {

        av_log(s->avctx, AV_LOG_ERROR, "VPS id out of range: %d\n", vps_id);

        goto err;

    }



    if (get_bits(gb, 2) != 3) { // vps_reserved_three_2bits

        av_log(s->avctx, AV_LOG_ERROR, "vps_reserved_three_2bits is not three\n");

        goto err;

    }



    vps->vps_max_layers               = get_bits(gb, 6) + 1;

    vps->vps_max_sub_layers           = get_bits(gb, 3) + 1;

    vps->vps_temporal_id_nesting_flag = get_bits1(gb);



    if (get_bits(gb, 16) != 0xffff) { // vps_reserved_ffff_16bits

        av_log(s->avctx, AV_LOG_ERROR, "vps_reserved_ffff_16bits is not 0xffff\n");

        goto err;

    }



    if (vps->vps_max_sub_layers > MAX_SUB_LAYERS) {

        av_log(s->avctx, AV_LOG_ERROR, "vps_max_sub_layers out of range: %d\n",

               vps->vps_max_sub_layers);

        goto err;

    }



    if (decode_profile_tier_level(&s->HEVClc, &vps->ptl, vps->vps_max_sub_layers) < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Error decoding profile tier level.\n");

        goto err;

    }

    vps->vps_sub_layer_ordering_info_present_flag = get_bits1(gb);



    i = vps->vps_sub_layer_ordering_info_present_flag ? 0 : vps->vps_max_sub_layers - 1;

    for (; i < vps->vps_max_sub_layers; i++) {

        vps->vps_max_dec_pic_buffering[i] = get_ue_golomb_long(gb) + 1;

        vps->vps_num_reorder_pics[i]      = get_ue_golomb_long(gb);

        vps->vps_max_latency_increase[i]  = get_ue_golomb_long(gb) - 1;



        if (vps->vps_max_dec_pic_buffering[i] > MAX_DPB_SIZE) {

            av_log(s->avctx, AV_LOG_ERROR, "vps_max_dec_pic_buffering_minus1 out of range: %d\n",

                   vps->vps_max_dec_pic_buffering[i] - 1);

            goto err;

        }

        if (vps->vps_num_reorder_pics[i] > vps->vps_max_dec_pic_buffering[i] - 1) {

            av_log(s->avctx, AV_LOG_ERROR, "vps_max_num_reorder_pics out of range: %d\n",

                   vps->vps_num_reorder_pics[i]);

            goto err;

        }

    }



    vps->vps_max_layer_id   = get_bits(gb, 6);

    vps->vps_num_layer_sets = get_ue_golomb_long(gb) + 1;

    for (i = 1; i < vps->vps_num_layer_sets; i++)

        for (j = 0; j <= vps->vps_max_layer_id; j++)

            skip_bits(gb, 1);  // layer_id_included_flag[i][j]



    vps->vps_timing_info_present_flag = get_bits1(gb);

    if (vps->vps_timing_info_present_flag) {

        vps->vps_num_units_in_tick               = get_bits_long(gb, 32);

        vps->vps_time_scale                      = get_bits_long(gb, 32);

        vps->vps_poc_proportional_to_timing_flag = get_bits1(gb);

        if (vps->vps_poc_proportional_to_timing_flag)

            vps->vps_num_ticks_poc_diff_one = get_ue_golomb_long(gb) + 1;

        vps->vps_num_hrd_parameters = get_ue_golomb_long(gb);

        for (i = 0; i < vps->vps_num_hrd_parameters; i++) {

            int common_inf_present = 1;



            get_ue_golomb_long(gb); // hrd_layer_set_idx

            if (i)

                common_inf_present = get_bits1(gb);

            decode_hrd(s, common_inf_present, vps->vps_max_sub_layers);

        }

    }

    get_bits1(gb); /* vps_extension_flag */



    av_buffer_unref(&s->vps_list[vps_id]);

    s->vps_list[vps_id] = vps_buf;

    return 0;



err:

    av_buffer_unref(&vps_buf);

    return AVERROR_INVALIDDATA;

}

static int mss2_decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                             AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    MSS2Context *ctx = avctx->priv_data;

    MSS12Context *c  = &ctx->c;

    AVFrame *frame   = data;

    GetBitContext gb;

    GetByteContext gB;

    ArithCoder acoder;



    int keyframe, has_wmv9, has_mv, is_rle, is_555, ret;



    Rectangle wmv9rects[MAX_WMV9_RECTANGLES], *r;

    int used_rects = 0, i, implicit_rect = 0, av_uninit(wmv9_mask);



    if ((ret = init_get_bits8(&gb, buf, buf_size)) < 0)

        return ret;



    if (keyframe = get_bits1(&gb))

        skip_bits(&gb, 7);

    has_wmv9 = get_bits1(&gb);

    has_mv   = keyframe ? 0 : get_bits1(&gb);

    is_rle   = get_bits1(&gb);

    is_555   = is_rle && get_bits1(&gb);

    if (c->slice_split > 0)

        ctx->split_position = c->slice_split;

    else if (c->slice_split < 0) {

        if (get_bits1(&gb)) {

            if (get_bits1(&gb)) {

                if (get_bits1(&gb))

                    ctx->split_position = get_bits(&gb, 16);

                else

                    ctx->split_position = get_bits(&gb, 12);

            } else

                ctx->split_position = get_bits(&gb, 8) << 4;

        } else {

            if (keyframe)

                ctx->split_position = avctx->height / 2;

        }

    } else

        ctx->split_position = avctx->height;



    if (c->slice_split && (ctx->split_position < 1 - is_555 ||

                           ctx->split_position > avctx->height - 1))

        return AVERROR_INVALIDDATA;



    align_get_bits(&gb);

    buf      += get_bits_count(&gb) >> 3;

    buf_size -= get_bits_count(&gb) >> 3;



    if (buf_size < 1)

        return AVERROR_INVALIDDATA;



    if (is_555 && (has_wmv9 || has_mv || c->slice_split && ctx->split_position))

        return AVERROR_INVALIDDATA;



    avctx->pix_fmt = is_555 ? AV_PIX_FMT_RGB555 : AV_PIX_FMT_RGB24;

    if (ctx->last_pic->format != avctx->pix_fmt)

        av_frame_unref(ctx->last_pic);



    if (has_wmv9) {

        bytestream2_init(&gB, buf, buf_size + ARITH2_PADDING);

        arith2_init(&acoder, &gB);



        implicit_rect = !arith2_get_bit(&acoder);



        while (arith2_get_bit(&acoder)) {

            if (used_rects == MAX_WMV9_RECTANGLES)

                return AVERROR_INVALIDDATA;

            r = &wmv9rects[used_rects];

            if (!used_rects)

                r->x = arith2_get_number(&acoder, avctx->width);

            else

                r->x = arith2_get_number(&acoder, avctx->width -

                                         wmv9rects[used_rects - 1].x) +

                       wmv9rects[used_rects - 1].x;

            r->y = arith2_get_number(&acoder, avctx->height);

            r->w = arith2_get_number(&acoder, avctx->width  - r->x) + 1;

            r->h = arith2_get_number(&acoder, avctx->height - r->y) + 1;

            used_rects++;

        }



        if (implicit_rect && used_rects) {

            av_log(avctx, AV_LOG_ERROR, "implicit_rect && used_rects > 0\n");

            return AVERROR_INVALIDDATA;

        }



        if (implicit_rect) {

            wmv9rects[0].x = 0;

            wmv9rects[0].y = 0;

            wmv9rects[0].w = avctx->width;

            wmv9rects[0].h = avctx->height;



            used_rects = 1;

        }

        for (i = 0; i < used_rects; i++) {

            if (!implicit_rect && arith2_get_bit(&acoder)) {

                av_log(avctx, AV_LOG_ERROR, "Unexpected grandchildren\n");

                return AVERROR_INVALIDDATA;

            }

            if (!i) {

                wmv9_mask = arith2_get_bit(&acoder) - 1;

                if (!wmv9_mask)

                    wmv9_mask = arith2_get_number(&acoder, 256);

            }

            wmv9rects[i].coded = arith2_get_number(&acoder, 2);

        }



        buf      += arith2_get_consumed_bytes(&acoder);

        buf_size -= arith2_get_consumed_bytes(&acoder);

        if (buf_size < 1)

            return AVERROR_INVALIDDATA;

    }



    c->mvX = c->mvY = 0;

    if (keyframe && !is_555) {

        if ((i = decode_pal_v2(c, buf, buf_size)) < 0)

            return AVERROR_INVALIDDATA;

        buf      += i;

        buf_size -= i;

    } else if (has_mv) {

        buf      += 4;

        buf_size -= 4;

        if (buf_size < 1)

            return AVERROR_INVALIDDATA;

        c->mvX = AV_RB16(buf - 4) - avctx->width;

        c->mvY = AV_RB16(buf - 2) - avctx->height;

    }



    if (c->mvX < 0 || c->mvY < 0) {

        FFSWAP(uint8_t *, c->pal_pic, c->last_pal_pic);



        if ((ret = ff_get_buffer(avctx, frame, AV_GET_BUFFER_FLAG_REF)) < 0)

            return ret;



        if (ctx->last_pic->data[0]) {

            av_assert0(frame->linesize[0] == ctx->last_pic->linesize[0]);

            c->last_rgb_pic = ctx->last_pic->data[0] +

                              ctx->last_pic->linesize[0] * (avctx->height - 1);

        } else {

            av_log(avctx, AV_LOG_ERROR, "Missing keyframe\n");

            return AVERROR_INVALIDDATA;

        }

    } else {

        if ((ret = ff_reget_buffer(avctx, ctx->last_pic)) < 0)

            return ret;

        if ((ret = av_frame_ref(frame, ctx->last_pic)) < 0)

            return ret;



        c->last_rgb_pic = NULL;

    }

    c->rgb_pic    = frame->data[0] +

                    frame->linesize[0] * (avctx->height - 1);

    c->rgb_stride = -frame->linesize[0];



    frame->key_frame = keyframe;

    frame->pict_type = keyframe ? AV_PICTURE_TYPE_I : AV_PICTURE_TYPE_P;



    if (is_555) {

        bytestream2_init(&gB, buf, buf_size);



        if (decode_555(&gB, (uint16_t *)c->rgb_pic, c->rgb_stride >> 1,

                       keyframe, avctx->width, avctx->height))

            return AVERROR_INVALIDDATA;



        buf_size -= bytestream2_tell(&gB);

    } else {

        if (keyframe) {

            c->corrupted = 0;

            ff_mss12_slicecontext_reset(&ctx->sc[0]);

            if (c->slice_split)

                ff_mss12_slicecontext_reset(&ctx->sc[1]);

        }

        if (is_rle) {

            if ((ret = init_get_bits8(&gb, buf, buf_size)) < 0)

                return ret;

            if (ret = decode_rle(&gb, c->pal_pic, c->pal_stride,

                                 c->rgb_pic, c->rgb_stride, c->pal, keyframe,

                                 ctx->split_position, 0,

                                 avctx->width, avctx->height))

                return ret;

            align_get_bits(&gb);



            if (c->slice_split)

                if (ret = decode_rle(&gb, c->pal_pic, c->pal_stride,

                                     c->rgb_pic, c->rgb_stride, c->pal, keyframe,

                                     ctx->split_position, 1,

                                     avctx->width, avctx->height))

                    return ret;



            align_get_bits(&gb);

            buf      += get_bits_count(&gb) >> 3;

            buf_size -= get_bits_count(&gb) >> 3;

        } else if (!implicit_rect || wmv9_mask != -1) {

            if (c->corrupted)

                return AVERROR_INVALIDDATA;

            bytestream2_init(&gB, buf, buf_size + ARITH2_PADDING);

            arith2_init(&acoder, &gB);

            c->keyframe = keyframe;

            if (c->corrupted = ff_mss12_decode_rect(&ctx->sc[0], &acoder, 0, 0,

                                                    avctx->width,

                                                    ctx->split_position))

                return AVERROR_INVALIDDATA;



            buf      += arith2_get_consumed_bytes(&acoder);

            buf_size -= arith2_get_consumed_bytes(&acoder);

            if (c->slice_split) {

                if (buf_size < 1)

                    return AVERROR_INVALIDDATA;

                bytestream2_init(&gB, buf, buf_size + ARITH2_PADDING);

                arith2_init(&acoder, &gB);

                if (c->corrupted = ff_mss12_decode_rect(&ctx->sc[1], &acoder, 0,

                                                        ctx->split_position,

                                                        avctx->width,

                                                        avctx->height - ctx->split_position))

                    return AVERROR_INVALIDDATA;



                buf      += arith2_get_consumed_bytes(&acoder);

                buf_size -= arith2_get_consumed_bytes(&acoder);

            }

        } else

            memset(c->pal_pic, 0, c->pal_stride * avctx->height);

    }



    if (has_wmv9) {

        for (i = 0; i < used_rects; i++) {

            int x = wmv9rects[i].x;

            int y = wmv9rects[i].y;

            int w = wmv9rects[i].w;

            int h = wmv9rects[i].h;

            if (wmv9rects[i].coded) {

                int WMV9codedFrameSize;

                if (buf_size < 4 || !(WMV9codedFrameSize = AV_RL24(buf)))

                    return AVERROR_INVALIDDATA;

                if (ret = decode_wmv9(avctx, buf + 3, buf_size - 3,

                                      x, y, w, h, wmv9_mask))

                    return ret;

                buf      += WMV9codedFrameSize + 3;

                buf_size -= WMV9codedFrameSize + 3;

            } else {

                uint8_t *dst = c->rgb_pic + y * c->rgb_stride + x * 3;

                if (wmv9_mask != -1) {

                    ctx->dsp.mss2_gray_fill_masked(dst, c->rgb_stride,

                                                   wmv9_mask,

                                                   c->pal_pic + y * c->pal_stride + x,

                                                   c->pal_stride,

                                                   w, h);

                } else {

                    do {

                        memset(dst, 0x80, w * 3);

                        dst += c->rgb_stride;

                    } while (--h);

                }

            }

        }

    }



    if (buf_size)

        av_log(avctx, AV_LOG_WARNING, "buffer not fully consumed\n");



    if (c->mvX < 0 || c->mvY < 0) {

        av_frame_unref(ctx->last_pic);

        ret = av_frame_ref(ctx->last_pic, frame);

        if (ret < 0)

            return ret;

    }



    *got_frame       = 1;



    return avpkt->size;

}

static int encode_bitstream(FlashSVContext *s, const AVFrame *p, uint8_t *buf,

                            int buf_size, int block_width, int block_height,

                            uint8_t *previous_frame, int *I_frame)

{



    PutBitContext pb;

    int h_blocks, v_blocks, h_part, v_part, i, j;

    int buf_pos, res;

    int pred_blocks = 0;



    init_put_bits(&pb, buf, buf_size * 8);



    put_bits(&pb,  4, block_width / 16 - 1);

    put_bits(&pb, 12, s->image_width);

    put_bits(&pb,  4, block_height / 16 - 1);

    put_bits(&pb, 12, s->image_height);

    flush_put_bits(&pb);

    buf_pos = 4;



    h_blocks = s->image_width  / block_width;

    h_part   = s->image_width  % block_width;

    v_blocks = s->image_height / block_height;

    v_part   = s->image_height % block_height;



    /* loop over all block columns */

    for (j = 0; j < v_blocks + (v_part ? 1 : 0); j++) {



        int y_pos = j * block_height; // vertical position in frame

        int cur_blk_height = (j < v_blocks) ? block_height : v_part;



        /* loop over all block rows */

        for (i = 0; i < h_blocks + (h_part ? 1 : 0); i++) {

            int x_pos = i * block_width; // horizontal position in frame

            int cur_blk_width = (i < h_blocks) ? block_width : h_part;

            int ret = Z_OK;

            uint8_t *ptr = buf + buf_pos;



            /* copy the block to the temp buffer before compression

             * (if it differs from the previous frame's block) */

            res = copy_region_enc(p->data[0], s->tmpblock,

                                  s->image_height - (y_pos + cur_blk_height + 1),

                                  x_pos, cur_blk_height, cur_blk_width,

                                  p->linesize[0], previous_frame);



            if (res || *I_frame) {

                unsigned long zsize = 3 * block_width * block_height;

                ret = compress2(ptr + 2, &zsize, s->tmpblock,

                                3 * cur_blk_width * cur_blk_height, 9);



                //ret = deflateReset(&s->zstream);

                if (ret != Z_OK)

                    av_log(s->avctx, AV_LOG_ERROR,

                           "error while compressing block %dx%d\n", i, j);



                bytestream_put_be16(&ptr, zsize);

                buf_pos += zsize + 2;

                av_dlog(s->avctx, "buf_pos = %d\n", buf_pos);

            } else {

                pred_blocks++;

                bytestream_put_be16(&ptr, 0);

                buf_pos += 2;

            }

        }

    }



    if (pred_blocks)

        *I_frame = 0;

    else

        *I_frame = 1;



    return buf_pos;

}

