int kvm_arm_sync_mpstate_to_kvm(ARMCPU *cpu)

{

    if (cap_has_mp_state) {

        struct kvm_mp_state mp_state = {

            .mp_state =

            cpu->powered_off ? KVM_MP_STATE_STOPPED : KVM_MP_STATE_RUNNABLE

        };

        int ret = kvm_vcpu_ioctl(CPU(cpu), KVM_SET_MP_STATE, &mp_state);

        if (ret) {

            fprintf(stderr, "%s: failed to set MP_STATE %d/%s\n",

                    __func__, ret, strerror(-ret));

            return -1;

        }

    }



    return 0;

}

static int nbd_co_readv_1(BlockDriverState *bs, int64_t sector_num,

                          int nb_sectors, QEMUIOVector *qiov,

                          int offset)

{

    BDRVNBDState *s = bs->opaque;

    struct nbd_request request;

    struct nbd_reply reply;



    request.type = NBD_CMD_READ;

    request.from = sector_num * 512;

    request.len = nb_sectors * 512;



    nbd_coroutine_start(s, &request);

    if (nbd_co_send_request(s, &request, NULL, 0) == -1) {

        reply.error = errno;

    } else {

        nbd_co_receive_reply(s, &request, &reply, qiov->iov, offset);

    }

    nbd_coroutine_end(s, &request);

    return -reply.error;



}

static void kvm_arm_machine_init_done(Notifier *notifier, void *data)

{

    KVMDevice *kd, *tkd;



    memory_listener_unregister(&devlistener);

    QSLIST_FOREACH_SAFE(kd, &kvm_devices_head, entries, tkd) {

        if (kd->kda.addr != -1) {

            if (kvm_vm_ioctl(kvm_state, KVM_ARM_SET_DEVICE_ADDR,

                             &kd->kda) < 0) {

                fprintf(stderr, "KVM_ARM_SET_DEVICE_ADDRESS failed: %s\n",

                        strerror(errno));

                abort();

            }

        }

        memory_region_unref(kd->mr);

        g_free(kd);

    }

}

static int imc_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    int ret, i;



    IMCContext *q = avctx->priv_data;



    LOCAL_ALIGNED_16(uint16_t, buf16, [IMC_BLOCK_SIZE / 2]);



    if (buf_size < IMC_BLOCK_SIZE * avctx->channels) {

        av_log(avctx, AV_LOG_ERROR, "frame too small!\n");

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    frame->nb_samples = COEFFS;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;



    for (i = 0; i < avctx->channels; i++) {

        q->out_samples = (float *)frame->extended_data[i];



        q->bdsp.bswap16_buf(buf16, (const uint16_t *) buf, IMC_BLOCK_SIZE / 2);



        init_get_bits(&q->gb, (const uint8_t*)buf16, IMC_BLOCK_SIZE * 8);



        buf += IMC_BLOCK_SIZE;



        if ((ret = imc_decode_block(avctx, q, i)) < 0)

            return ret;

    }



    if (avctx->channels == 2) {

        q->fdsp.butterflies_float((float *)frame->extended_data[0],

                                  (float *)frame->extended_data[1], COEFFS);

    }



    *got_frame_ptr = 1;



    return IMC_BLOCK_SIZE * avctx->channels;

}

