static inline int onenand_prog_spare(OneNANDState *s, int sec, int secn,

                void *src)

{

    int result = 0;

    if (secn > 0) {

        const uint8_t *sp = (const uint8_t *)src;

        uint8_t *dp = 0, *dpp = 0;

        if (s->bdrv_cur) {

            dp = g_malloc(512);

            if (!dp || bdrv_read(s->bdrv_cur,

                                 s->secs_cur + (sec >> 5),

                                 dp, 1) < 0) {

                result = 1;

            } else {

                dpp = dp + ((sec & 31) << 4);

            }

        } else {

            if (sec + secn > s->secs_cur) {

                result = 1;

            } else {

                dpp = s->current + (s->secs_cur << 9) + (sec << 4);

            }

        }

        if (!result) {

            uint32_t i;

            for (i = 0; i < (secn << 4); i++) {

                dpp[i] &= sp[i];

            }

            if (s->bdrv_cur) {

                result = bdrv_write(s->bdrv_cur, s->secs_cur + (sec >> 5),

                                    dp, 1) < 0;

            }

        }

        g_free(dp);

    }

    return result;

}

static int matroska_parse_rm_audio(MatroskaDemuxContext *matroska,

                                   MatroskaTrack *track,

                                   AVStream *st,

                                   uint8_t *data, int size,

                                   uint64_t timecode,

                                   int64_t pos)

{

    int a = st->codec->block_align;

    int sps = track->audio.sub_packet_size;

    int cfs = track->audio.coded_framesize;

    int h = track->audio.sub_packet_h;

    int y = track->audio.sub_packet_cnt;

    int w = track->audio.frame_size;

    int x;



    if (!track->audio.pkt_cnt) {

        if (track->audio.sub_packet_cnt == 0)

            track->audio.buf_timecode = timecode;

        if (st->codec->codec_id == AV_CODEC_ID_RA_288) {

            if (size < cfs * h / 2) {

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Corrupt int4 RM-style audio packet size\n");

                return AVERROR_INVALIDDATA;

            }

            for (x=0; x<h/2; x++)

                memcpy(track->audio.buf+x*2*w+y*cfs,

                       data+x*cfs, cfs);

        } else if (st->codec->codec_id == AV_CODEC_ID_SIPR) {

            if (size < w) {

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Corrupt sipr RM-style audio packet size\n");

                return AVERROR_INVALIDDATA;

            }

            memcpy(track->audio.buf + y*w, data, w);

        } else {

            if (size < sps * w / sps) {

                av_log(matroska->ctx, AV_LOG_ERROR,

                       "Corrupt generic RM-style audio packet size\n");

                return AVERROR_INVALIDDATA;

            }

            for (x=0; x<w/sps; x++)

                memcpy(track->audio.buf+sps*(h*x+((h+1)/2)*(y&1)+(y>>1)), data+x*sps, sps);

        }



        if (++track->audio.sub_packet_cnt >= h) {

            if (st->codec->codec_id == AV_CODEC_ID_SIPR)

                ff_rm_reorder_sipr_data(track->audio.buf, h, w);

            track->audio.sub_packet_cnt = 0;

            track->audio.pkt_cnt = h*w / a;

        }

    }



    while (track->audio.pkt_cnt) {

        AVPacket *pkt = NULL;

        if (!(pkt = av_mallocz(sizeof(AVPacket))) || av_new_packet(pkt, a) < 0){

            av_free(pkt);

            return AVERROR(ENOMEM);

        }

        memcpy(pkt->data, track->audio.buf

               + a * (h*w / a - track->audio.pkt_cnt--), a);

        pkt->pts = track->audio.buf_timecode;

        track->audio.buf_timecode = AV_NOPTS_VALUE;

        pkt->pos = pos;

        pkt->stream_index = st->index;

        dynarray_add(&matroska->packets,&matroska->num_packets,pkt);

    }



    return 0;

}

static int vmd_read_header(AVFormatContext *s)

{

    VmdDemuxContext *vmd = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st = NULL, *vst;

    unsigned int toc_offset;

    unsigned char *raw_frame_table;

    int raw_frame_table_size;

    int64_t current_offset;

    int i, j;

    unsigned int total_frames;

    int64_t current_audio_pts = 0;

    unsigned char chunk[BYTES_PER_FRAME_RECORD];

    int num, den;

    int sound_buffers;



    /* fetch the main header, including the 2 header length bytes */

    avio_seek(pb, 0, SEEK_SET);

    if (avio_read(pb, vmd->vmd_header, VMD_HEADER_SIZE) != VMD_HEADER_SIZE)

        return AVERROR(EIO);



    if(vmd->vmd_header[24] == 'i' && vmd->vmd_header[25] == 'v' && vmd->vmd_header[26] == '3')

        vmd->is_indeo3 = 1;

    else

        vmd->is_indeo3 = 0;

    /* start up the decoders */

    vst = avformat_new_stream(s, NULL);

    if (!vst)

        return AVERROR(ENOMEM);

    avpriv_set_pts_info(vst, 33, 1, 10);

    vmd->video_stream_index = vst->index;

    vst->codec->codec_type = AVMEDIA_TYPE_VIDEO;

    vst->codec->codec_id = vmd->is_indeo3 ? AV_CODEC_ID_INDEO3 : AV_CODEC_ID_VMDVIDEO;

    vst->codec->codec_tag = 0;  /* no fourcc */

    vst->codec->width = AV_RL16(&vmd->vmd_header[12]);

    vst->codec->height = AV_RL16(&vmd->vmd_header[14]);

    if(vmd->is_indeo3 && vst->codec->width > 320){

        vst->codec->width >>= 1;

        vst->codec->height >>= 1;

    }

    vst->codec->extradata_size = VMD_HEADER_SIZE;

    vst->codec->extradata = av_mallocz(VMD_HEADER_SIZE + FF_INPUT_BUFFER_PADDING_SIZE);

    memcpy(vst->codec->extradata, vmd->vmd_header, VMD_HEADER_SIZE);



    /* if sample rate is 0, assume no audio */

    vmd->sample_rate = AV_RL16(&vmd->vmd_header[804]);

    if (vmd->sample_rate) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        vmd->audio_stream_index = st->index;

        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_id = AV_CODEC_ID_VMDAUDIO;

        st->codec->codec_tag = 0;  /* no fourcc */

        if (vmd->vmd_header[811] & 0x80) {

            st->codec->channels       = 2;

            st->codec->channel_layout = AV_CH_LAYOUT_STEREO;

        } else {

            st->codec->channels       = 1;

            st->codec->channel_layout = AV_CH_LAYOUT_MONO;

        }

        st->codec->sample_rate = vmd->sample_rate;

        st->codec->block_align = AV_RL16(&vmd->vmd_header[806]);

        if (st->codec->block_align & 0x8000) {

            st->codec->bits_per_coded_sample = 16;

            st->codec->block_align = -(st->codec->block_align - 0x10000);

        } else {

            st->codec->bits_per_coded_sample = 8;

        }

        st->codec->bit_rate = st->codec->sample_rate *

            st->codec->bits_per_coded_sample * st->codec->channels;



        /* calculate pts */

        num = st->codec->block_align;

        den = st->codec->sample_rate * st->codec->channels;

        av_reduce(&den, &num, den, num, (1UL<<31)-1);

        avpriv_set_pts_info(vst, 33, num, den);

        avpriv_set_pts_info(st, 33, num, den);

    }



    toc_offset = AV_RL32(&vmd->vmd_header[812]);

    vmd->frame_count = AV_RL16(&vmd->vmd_header[6]);

    vmd->frames_per_block = AV_RL16(&vmd->vmd_header[18]);

    avio_seek(pb, toc_offset, SEEK_SET);



    raw_frame_table = NULL;

    vmd->frame_table = NULL;

    sound_buffers = AV_RL16(&vmd->vmd_header[808]);

    raw_frame_table_size = vmd->frame_count * 6;

    if(vmd->frame_count * vmd->frames_per_block >= UINT_MAX / sizeof(vmd_frame) - sound_buffers){

        av_log(s, AV_LOG_ERROR, "vmd->frame_count * vmd->frames_per_block too large\n");

        return -1;

    }

    raw_frame_table = av_malloc(raw_frame_table_size);

    vmd->frame_table = av_malloc((vmd->frame_count * vmd->frames_per_block + sound_buffers) * sizeof(vmd_frame));

    if (!raw_frame_table || !vmd->frame_table) {

        av_free(raw_frame_table);

        av_free(vmd->frame_table);

        return AVERROR(ENOMEM);

    }

    if (avio_read(pb, raw_frame_table, raw_frame_table_size) !=

        raw_frame_table_size) {

        av_free(raw_frame_table);

        av_free(vmd->frame_table);

        return AVERROR(EIO);

    }



    total_frames = 0;

    for (i = 0; i < vmd->frame_count; i++) {



        current_offset = AV_RL32(&raw_frame_table[6 * i + 2]);



        /* handle each entry in index block */

        for (j = 0; j < vmd->frames_per_block; j++) {

            int type;

            uint32_t size;



            avio_read(pb, chunk, BYTES_PER_FRAME_RECORD);

            type = chunk[0];

            size = AV_RL32(&chunk[2]);

            if(!size && type != 1)

                continue;

            switch(type) {

            case 1: /* Audio Chunk */

                if (!st) break;

                /* first audio chunk contains several audio buffers */

                vmd->frame_table[total_frames].frame_offset = current_offset;

                vmd->frame_table[total_frames].stream_index = vmd->audio_stream_index;

                vmd->frame_table[total_frames].frame_size = size;

                memcpy(vmd->frame_table[total_frames].frame_record, chunk, BYTES_PER_FRAME_RECORD);

                vmd->frame_table[total_frames].pts = current_audio_pts;

                total_frames++;

                if(!current_audio_pts)

                    current_audio_pts += sound_buffers - 1;

                else

                    current_audio_pts++;

                break;

            case 2: /* Video Chunk */

                vmd->frame_table[total_frames].frame_offset = current_offset;

                vmd->frame_table[total_frames].stream_index = vmd->video_stream_index;

                vmd->frame_table[total_frames].frame_size = size;

                memcpy(vmd->frame_table[total_frames].frame_record, chunk, BYTES_PER_FRAME_RECORD);

                vmd->frame_table[total_frames].pts = i;

                total_frames++;

                break;

            }

            current_offset += size;

        }

    }



    av_free(raw_frame_table);



    vmd->current_frame = 0;

    vmd->frame_count = total_frames;



    return 0;

}

int bdrv_set_key(BlockDriverState *bs, const char *key)

{

    int ret;

    if (bs->backing_hd && bs->backing_hd->encrypted) {

        ret = bdrv_set_key(bs->backing_hd, key);

        if (ret < 0)

            return ret;

        if (!bs->encrypted)

            return 0;

    }

    if (!bs->encrypted) {

        return -EINVAL;

    } else if (!bs->drv || !bs->drv->bdrv_set_key) {

        return -ENOMEDIUM;

    }

    ret = bs->drv->bdrv_set_key(bs, key);

    if (ret < 0) {

        bs->valid_key = 0;

    } else if (!bs->valid_key) {

        bs->valid_key = 1;

        if (bs->blk) {

            /* call the change callback now, we skipped it on open */

            blk_dev_change_media_cb(bs->blk, true);

        }

    }

    return ret;

}

static int virtio_blk_handle_scsi_req(VirtIOBlockReq *req)

{

    int status = VIRTIO_BLK_S_OK;

    struct virtio_scsi_inhdr *scsi = NULL;

    VirtIODevice *vdev = VIRTIO_DEVICE(req->dev);

    VirtQueueElement *elem = &req->elem;

    VirtIOBlock *blk = req->dev;



#ifdef __linux__

    int i;

    VirtIOBlockIoctlReq *ioctl_req;

#endif



    /*

     * We require at least one output segment each for the virtio_blk_outhdr

     * and the SCSI command block.

     *

     * We also at least require the virtio_blk_inhdr, the virtio_scsi_inhdr

     * and the sense buffer pointer in the input segments.

     */

    if (elem->out_num < 2 || elem->in_num < 3) {

        status = VIRTIO_BLK_S_IOERR;

        goto fail;

    }



    /*

     * The scsi inhdr is placed in the second-to-last input segment, just

     * before the regular inhdr.

     */

    scsi = (void *)elem->in_sg[elem->in_num - 2].iov_base;



    if (!blk->conf.scsi) {

        status = VIRTIO_BLK_S_UNSUPP;

        goto fail;

    }



    /*

     * No support for bidirection commands yet.

     */

    if (elem->out_num > 2 && elem->in_num > 3) {

        status = VIRTIO_BLK_S_UNSUPP;

        goto fail;

    }



#ifdef __linux__

    ioctl_req = g_new0(VirtIOBlockIoctlReq, 1);

    ioctl_req->req = req;

    ioctl_req->hdr.interface_id = 'S';

    ioctl_req->hdr.cmd_len = elem->out_sg[1].iov_len;

    ioctl_req->hdr.cmdp = elem->out_sg[1].iov_base;

    ioctl_req->hdr.dxfer_len = 0;



    if (elem->out_num > 2) {

        /*

         * If there are more than the minimally required 2 output segments

         * there is write payload starting from the third iovec.

         */

        ioctl_req->hdr.dxfer_direction = SG_DXFER_TO_DEV;

        ioctl_req->hdr.iovec_count = elem->out_num - 2;



        for (i = 0; i < ioctl_req->hdr.iovec_count; i++) {

            ioctl_req->hdr.dxfer_len += elem->out_sg[i + 2].iov_len;

        }



        ioctl_req->hdr.dxferp = elem->out_sg + 2;



    } else if (elem->in_num > 3) {

        /*

         * If we have more than 3 input segments the guest wants to actually

         * read data.

         */

        ioctl_req->hdr.dxfer_direction = SG_DXFER_FROM_DEV;

        ioctl_req->hdr.iovec_count = elem->in_num - 3;

        for (i = 0; i < ioctl_req->hdr.iovec_count; i++) {

            ioctl_req->hdr.dxfer_len += elem->in_sg[i].iov_len;

        }



        ioctl_req->hdr.dxferp = elem->in_sg;

    } else {

        /*

         * Some SCSI commands don't actually transfer any data.

         */

        ioctl_req->hdr.dxfer_direction = SG_DXFER_NONE;

    }



    ioctl_req->hdr.sbp = elem->in_sg[elem->in_num - 3].iov_base;

    ioctl_req->hdr.mx_sb_len = elem->in_sg[elem->in_num - 3].iov_len;



    blk_aio_ioctl(blk->blk, SG_IO, &ioctl_req->hdr,

                  virtio_blk_ioctl_complete, ioctl_req);

    return -EINPROGRESS;

#else

    abort();

#endif



fail:

    /* Just put anything nonzero so that the ioctl fails in the guest.  */

    if (scsi) {

        virtio_stl_p(vdev, &scsi->errors, 255);

    }

    return status;

}

abi_long do_sigaltstack(abi_ulong uss_addr, abi_ulong uoss_addr, abi_ulong sp)

{

    int ret;

    struct target_sigaltstack oss;



    /* XXX: test errors */

    if(uoss_addr)

    {

        __put_user(target_sigaltstack_used.ss_sp, &oss.ss_sp);

        __put_user(target_sigaltstack_used.ss_size, &oss.ss_size);

        __put_user(sas_ss_flags(sp), &oss.ss_flags);

    }



    if(uss_addr)

    {

        struct target_sigaltstack *uss;

        struct target_sigaltstack ss;



	ret = -TARGET_EFAULT;

        if (!lock_user_struct(VERIFY_READ, uss, uss_addr, 1)

	    || __get_user(ss.ss_sp, &uss->ss_sp)

	    || __get_user(ss.ss_size, &uss->ss_size)

	    || __get_user(ss.ss_flags, &uss->ss_flags))

            goto out;

        unlock_user_struct(uss, uss_addr, 0);



	ret = -TARGET_EPERM;

	if (on_sig_stack(sp))

            goto out;



	ret = -TARGET_EINVAL;

	if (ss.ss_flags != TARGET_SS_DISABLE

            && ss.ss_flags != TARGET_SS_ONSTACK

            && ss.ss_flags != 0)

            goto out;



	if (ss.ss_flags == TARGET_SS_DISABLE) {

            ss.ss_size = 0;

            ss.ss_sp = 0;

	} else {

            ret = -TARGET_ENOMEM;

            if (ss.ss_size < MINSIGSTKSZ)

                goto out;

	}



        target_sigaltstack_used.ss_sp = ss.ss_sp;

        target_sigaltstack_used.ss_size = ss.ss_size;

    }



    if (uoss_addr) {

        ret = -TARGET_EFAULT;

        if (copy_to_user(uoss_addr, &oss, sizeof(oss)))

            goto out;

    }



    ret = 0;

out:

    return ret;

}

int s390_cpu_handle_mmu_fault(CPUState *cs, vaddr orig_vaddr,

                              int rw, int mmu_idx)

{

    S390CPU *cpu = S390_CPU(cs);

    CPUS390XState *env = &cpu->env;

    uint64_t asc = cpu_mmu_idx_to_asc(mmu_idx);

    target_ulong vaddr, raddr;

    int prot;



    DPRINTF("%s: address 0x%" VADDR_PRIx " rw %d mmu_idx %d\n",

            __func__, orig_vaddr, rw, mmu_idx);



    orig_vaddr &= TARGET_PAGE_MASK;

    vaddr = orig_vaddr;



    /* 31-Bit mode */

    if (!(env->psw.mask & PSW_MASK_64)) {

        vaddr &= 0x7fffffff;

    }



    if (mmu_translate(env, vaddr, rw, asc, &raddr, &prot, true)) {

        /* Translation ended in exception */

        return 1;

    }



    /* check out of RAM access */

    if (raddr > ram_size) {

        DPRINTF("%s: raddr %" PRIx64 " > ram_size %" PRIx64 "\n", __func__,

                (uint64_t)raddr, (uint64_t)ram_size);

        trigger_pgm_exception(env, PGM_ADDRESSING, ILEN_AUTO);

        return 1;

    }



    qemu_log_mask(CPU_LOG_MMU, "%s: set tlb %" PRIx64 " -> %" PRIx64 " (%x)\n",

            __func__, (uint64_t)vaddr, (uint64_t)raddr, prot);



    tlb_set_page(cs, orig_vaddr, raddr, prot,

                 mmu_idx, TARGET_PAGE_SIZE);



    return 0;

}

static int oss_ctl_in (HWVoiceIn *hw, int cmd, ...)

{

    OSSVoiceIn *oss = (OSSVoiceIn *) hw;



    switch (cmd) {

    case VOICE_ENABLE:

        {

            va_list ap;

            int poll_mode;



            va_start (ap, cmd);

            poll_mode = va_arg (ap, int);

            va_end (ap);



            if (poll_mode && oss_poll_in (hw)) {

                poll_mode = 0;

            }

            hw->poll_mode = poll_mode;

        }

        break;



    case VOICE_DISABLE:

        if (hw->poll_mode) {

            hw->poll_mode = 0;

            qemu_set_fd_handler (oss->fd, NULL, NULL, NULL);

        }

        break;

    }

    return 0;

}

int cpu_s390x_handle_mmu_fault (CPUState *env, target_ulong address, int rw,

                                int mmu_idx, int is_softmmu)

{

    target_ulong phys;

    int prot;



    /* XXX: implement mmu */



    phys = address;

    prot = PAGE_READ | PAGE_WRITE;



    return tlb_set_page(env, address & TARGET_PAGE_MASK,

                        phys & TARGET_PAGE_MASK, prot,

                        mmu_idx, is_softmmu);

}

static void tcp_chr_tls_init(Chardev *chr)

{

    SocketChardev *s = SOCKET_CHARDEV(chr);

    QIOChannelTLS *tioc;

    Error *err = NULL;

    gchar *name;



    if (s->is_listen) {

        tioc = qio_channel_tls_new_server(

            s->ioc, s->tls_creds,

            NULL, /* XXX Use an ACL */

            &err);

    } else {

        tioc = qio_channel_tls_new_client(

            s->ioc, s->tls_creds,

            s->addr->u.inet.data->host,

            &err);

    }

    if (tioc == NULL) {

        error_free(err);

        tcp_chr_disconnect(chr);

        return;

    }

    name = g_strdup_printf("chardev-tls-%s-%s",

                           s->is_listen ? "server" : "client",

                           chr->label);

    qio_channel_set_name(QIO_CHANNEL(tioc), name);

    g_free(name);

    object_unref(OBJECT(s->ioc));

    s->ioc = QIO_CHANNEL(tioc);



    qio_channel_tls_handshake(tioc,

                              tcp_chr_tls_handshake,

                              chr,

                              NULL);

}

static void netfilter_finalize(Object *obj)

{

    NetFilterState *nf = NETFILTER(obj);

    NetFilterClass *nfc = NETFILTER_GET_CLASS(obj);



    if (nfc->cleanup) {

        nfc->cleanup(nf);

    }



    if (nf->netdev && !QTAILQ_EMPTY(&nf->netdev->filters)) {

        QTAILQ_REMOVE(&nf->netdev->filters, nf, next);

    }


}

int attribute_align_arg avcodec_decode_audio4(AVCodecContext *avctx,
                                              AVFrame *frame,
                                              int *got_frame_ptr,
                                              AVPacket *avpkt)
{
    int planar, channels;
    int ret = 0;
    *got_frame_ptr = 0;
    avctx->pkt = avpkt;
    if (!avpkt->data && avpkt->size) {
        av_log(avctx, AV_LOG_ERROR, "invalid packet: NULL data, size != 0\n");
        return AVERROR(EINVAL);
    }
    apply_param_change(avctx, avpkt);
    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size) {
        ret = avctx->codec->decode(avctx, frame, got_frame_ptr, avpkt);
        if (ret >= 0 && *got_frame_ptr) {
            avctx->frame_number++;
            frame->pkt_dts = avpkt->dts;
            if (frame->format == AV_SAMPLE_FMT_NONE)
                frame->format = avctx->sample_fmt;
        }
    }
    /* many decoders assign whole AVFrames, thus overwriting extended_data;
     * make sure it's set correctly; assume decoders that actually use
     * extended_data are doing it correctly */
    planar   = av_sample_fmt_is_planar(frame->format);
    channels = av_get_channel_layout_nb_channels(frame->channel_layout);
    if (!(planar && channels > AV_NUM_DATA_POINTERS))
        frame->extended_data = frame->data;
    return ret;
}

static int armv7m_nvic_init(SysBusDevice *dev)

{

    nvic_state *s = NVIC(dev);

    NVICClass *nc = NVIC_GET_CLASS(s);



    /* The NVIC always has only one CPU */

    s->gic.num_cpu = 1;

    /* Tell the common code we're an NVIC */

    s->gic.revision = 0xffffffff;

    s->num_irq = s->gic.num_irq;

    nc->parent_init(dev);

    gic_init_irqs_and_distributor(&s->gic, s->num_irq);

    /* The NVIC and system controller register area looks like this:

     *  0..0xff : system control registers, including systick

     *  0x100..0xcff : GIC-like registers

     *  0xd00..0xfff : system control registers

     * We use overlaying to put the GIC like registers

     * over the top of the system control register region.

     */

    memory_region_init(&s->container, "nvic", 0x1000);

    /* The system register region goes at the bottom of the priority

     * stack as it covers the whole page.

     */

    memory_region_init_io(&s->sysregmem, &nvic_sysreg_ops, s,

                          "nvic_sysregs", 0x1000);

    memory_region_add_subregion(&s->container, 0, &s->sysregmem);

    /* Alias the GIC region so we can get only the section of it

     * we need, and layer it on top of the system register region.

     */

    memory_region_init_alias(&s->gic_iomem_alias, "nvic-gic", &s->gic.iomem,

                             0x100, 0xc00);

    memory_region_add_subregion_overlap(&s->container, 0x100,

                                        &s->gic_iomem_alias, 1);

    /* Map the whole thing into system memory at the location required

     * by the v7M architecture.

     */

    memory_region_add_subregion(get_system_memory(), 0xe000e000, &s->container);

    s->systick.timer = qemu_new_timer_ns(vm_clock, systick_timer_tick, s);

    return 0;

}

static av_cold int aac_decode_init(AVCodecContext * avccontext) {

    AACContext * ac = avccontext->priv_data;

    int i;



    ac->avccontext = avccontext;



    if (avccontext->extradata_size <= 0 ||

        decode_audio_specific_config(ac, avccontext->extradata, avccontext->extradata_size))

        return -1;



    avccontext->sample_fmt  = SAMPLE_FMT_S16;

    avccontext->sample_rate = ac->m4ac.sample_rate;

    avccontext->frame_size  = 1024;



    AAC_INIT_VLC_STATIC( 0, 144);

    AAC_INIT_VLC_STATIC( 1, 114);

    AAC_INIT_VLC_STATIC( 2, 188);

    AAC_INIT_VLC_STATIC( 3, 180);

    AAC_INIT_VLC_STATIC( 4, 172);

    AAC_INIT_VLC_STATIC( 5, 140);

    AAC_INIT_VLC_STATIC( 6, 168);

    AAC_INIT_VLC_STATIC( 7, 114);

    AAC_INIT_VLC_STATIC( 8, 262);

    AAC_INIT_VLC_STATIC( 9, 248);

    AAC_INIT_VLC_STATIC(10, 384);



    dsputil_init(&ac->dsp, avccontext);



    ac->random_state = 0x1f2e3d4c;



    // -1024 - Compensate wrong IMDCT method.

    // 32768 - Required to scale values to the correct range for the bias method

    //         for float to int16 conversion.



    if(ac->dsp.float_to_int16 == ff_float_to_int16_c) {

        ac->add_bias = 385.0f;

        ac->sf_scale = 1. / (-1024. * 32768.);

        ac->sf_offset = 0;

    } else {

        ac->add_bias = 0.0f;

        ac->sf_scale = 1. / -1024.;

        ac->sf_offset = 60;

    }



#ifndef CONFIG_HARDCODED_TABLES

    for (i = 0; i < 428; i++)

        ff_aac_pow2sf_tab[i] = pow(2, (i - 200)/4.);

#endif /* CONFIG_HARDCODED_TABLES */



    INIT_VLC_STATIC(&vlc_scalefactors,7,FF_ARRAY_ELEMS(ff_aac_scalefactor_code),

        ff_aac_scalefactor_bits, sizeof(ff_aac_scalefactor_bits[0]), sizeof(ff_aac_scalefactor_bits[0]),

        ff_aac_scalefactor_code, sizeof(ff_aac_scalefactor_code[0]), sizeof(ff_aac_scalefactor_code[0]),

        352);



    ff_mdct_init(&ac->mdct, 11, 1);

    ff_mdct_init(&ac->mdct_small, 8, 1);

    // window initialization

    ff_kbd_window_init(ff_aac_kbd_long_1024, 4.0, 1024);

    ff_kbd_window_init(ff_aac_kbd_short_128, 6.0, 128);

    ff_sine_window_init(ff_sine_1024, 1024);

    ff_sine_window_init(ff_sine_128, 128);



    return 0;

}

