static void virtio_net_save(QEMUFile *f, void *opaque)

{

    VirtIONet *n = opaque;



    virtio_save(&n->vdev, f);



    qemu_put_buffer(f, n->mac, ETH_ALEN);

    qemu_put_be32(f, n->tx_timer_active);

    qemu_put_be32(f, n->mergeable_rx_bufs);

    qemu_put_be16(f, n->status);

    qemu_put_byte(f, n->promisc);

    qemu_put_byte(f, n->allmulti);

    qemu_put_be32(f, n->mac_table.in_use);

    qemu_put_buffer(f, n->mac_table.macs, n->mac_table.in_use * ETH_ALEN);

    qemu_put_buffer(f, (uint8_t *)n->vlans, MAX_VLAN >> 3);

    qemu_put_be32(f, 0); /* vnet-hdr placeholder */

    qemu_put_byte(f, n->mac_table.multi_overflow);

    qemu_put_byte(f, n->mac_table.uni_overflow);

    qemu_put_byte(f, n->alluni);

    qemu_put_byte(f, n->nomulti);

    qemu_put_byte(f, n->nouni);

    qemu_put_byte(f, n->nobcast);

}

static void destroy_l2_mapping(PhysPageEntry *lp, unsigned level)

{

    unsigned i;

    PhysPageEntry *p = lp->u.node;



    if (!p) {

        return;

    }



    for (i = 0; i < L2_SIZE; ++i) {

        if (level > 0) {

            destroy_l2_mapping(&p[i], level - 1);

        } else {

            destroy_page_desc(p[i].u.leaf);

        }

    }

    g_free(p);

    lp->u.node = NULL;

}

static inline void FUNC(idctRowCondDC)(DCTELEM *row)

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



#if HAVE_FAST_64BIT

#define ROW0_MASK (0xffffLL << 48 * HAVE_BIGENDIAN)

    if (((((uint64_t *)row)[0] & ~ROW0_MASK) | ((uint64_t *)row)[1]) == 0) {

        uint64_t temp = (row[0] << DC_SHIFT) & 0xffff;

        temp += temp << 16;

        temp += temp << 32;

        ((uint64_t *)row)[0] = temp;

        ((uint64_t *)row)[1] = temp;

        return;

    }

#else

    if (!(((uint32_t*)row)[1] |

          ((uint32_t*)row)[2] |

          ((uint32_t*)row)[3] |

          row[1])) {

        uint32_t temp = (row[0] << DC_SHIFT) & 0xffff;

        temp += temp << 16;

        ((uint32_t*)row)[0]=((uint32_t*)row)[1] =

            ((uint32_t*)row)[2]=((uint32_t*)row)[3] = temp;

        return;

    }

#endif



    a0 = (W4 * row[0]) + (1 << (ROW_SHIFT - 1));

    a1 = a0;

    a2 = a0;

    a3 = a0;



    a0 += W2 * row[2];

    a1 += W6 * row[2];

    a2 -= W6 * row[2];

    a3 -= W2 * row[2];



    b0 = MUL(W1, row[1]);

    MAC(b0, W3, row[3]);

    b1 = MUL(W3, row[1]);

    MAC(b1, -W7, row[3]);

    b2 = MUL(W5, row[1]);

    MAC(b2, -W1, row[3]);

    b3 = MUL(W7, row[1]);

    MAC(b3, -W5, row[3]);



    if (AV_RN64A(row + 4)) {

        a0 +=   W4*row[4] + W6*row[6];

        a1 += - W4*row[4] - W2*row[6];

        a2 += - W4*row[4] + W2*row[6];

        a3 +=   W4*row[4] - W6*row[6];



        MAC(b0,  W5, row[5]);

        MAC(b0,  W7, row[7]);



        MAC(b1, -W1, row[5]);

        MAC(b1, -W5, row[7]);



        MAC(b2,  W7, row[5]);

        MAC(b2,  W3, row[7]);



        MAC(b3,  W3, row[5]);

        MAC(b3, -W1, row[7]);

    }



    row[0] = (a0 + b0) >> ROW_SHIFT;

    row[7] = (a0 - b0) >> ROW_SHIFT;

    row[1] = (a1 + b1) >> ROW_SHIFT;

    row[6] = (a1 - b1) >> ROW_SHIFT;

    row[2] = (a2 + b2) >> ROW_SHIFT;

    row[5] = (a2 - b2) >> ROW_SHIFT;

    row[3] = (a3 + b3) >> ROW_SHIFT;

    row[4] = (a3 - b3) >> ROW_SHIFT;

}

void ff_rtsp_undo_setup(AVFormatContext *s, int send_packets)

{

    RTSPState *rt = s->priv_data;

    int i;



    for (i = 0; i < rt->nb_rtsp_streams; i++) {

        RTSPStream *rtsp_st = rt->rtsp_streams[i];

        if (!rtsp_st)

            continue;

        if (rtsp_st->transport_priv) {

            if (s->oformat) {

                AVFormatContext *rtpctx = rtsp_st->transport_priv;

                av_write_trailer(rtpctx);

                if (rt->lower_transport == RTSP_LOWER_TRANSPORT_TCP) {

                    uint8_t *ptr;

                    if (CONFIG_RTSP_MUXER && rtpctx->pb && send_packets)

                        ff_rtsp_tcp_write_packet(s, rtsp_st);

                    avio_close_dyn_buf(rtpctx->pb, &ptr);

                    av_free(ptr);

                } else {

                    avio_close(rtpctx->pb);

                }

                avformat_free_context(rtpctx);

            } else if (rt->transport == RTSP_TRANSPORT_RDT && CONFIG_RTPDEC)

                ff_rdt_parse_close(rtsp_st->transport_priv);

            else if (rt->transport == RTSP_TRANSPORT_RTP && CONFIG_RTPDEC)

                ff_rtp_parse_close(rtsp_st->transport_priv);

        }

        rtsp_st->transport_priv = NULL;

        if (rtsp_st->rtp_handle)

            ffurl_close(rtsp_st->rtp_handle);

        rtsp_st->rtp_handle = NULL;

    }

}

static void opt_mb_qmax(const char *arg)

{

    video_mb_qmax = atoi(arg);

    if (video_mb_qmax < 0 ||

        video_mb_qmax > 31) {

        fprintf(stderr, "qmax must be >= 1 and <= 31\n");

        exit(1);

    }

}

static void *nbd_client_thread(void *arg)

{

    int fd = *(int *)arg;

    off_t size;

    size_t blocksize;

    uint32_t nbdflags;

    int sock;

    int ret;

    pthread_t show_parts_thread;



    do {

        sock = unix_socket_outgoing(sockpath);

        if (sock == -1) {

            goto out;

        }

    } while (sock == -1);



    ret = nbd_receive_negotiate(sock, NULL, &nbdflags,

                                &size, &blocksize);

    if (ret == -1) {

        goto out;

    }



    ret = nbd_init(fd, sock, nbdflags, size, blocksize);

    if (ret == -1) {

        goto out;

    }



    /* update partition table */

    pthread_create(&show_parts_thread, NULL, show_parts, NULL);



    if (verbose) {

        fprintf(stderr, "NBD device %s is now connected to %s\n",

                device, srcpath);

    } else {

        /* Close stderr so that the qemu-nbd process exits.  */

        dup2(STDOUT_FILENO, STDERR_FILENO);

    }



    ret = nbd_client(fd);

    if (ret) {

        goto out;

    }

    close(fd);

    kill(getpid(), SIGTERM);

    return (void *) EXIT_SUCCESS;



out:

    kill(getpid(), SIGTERM);

    return (void *) EXIT_FAILURE;

}

static coroutine_fn int qcow_co_writev(BlockDriverState *bs, int64_t sector_num,

                          int nb_sectors, QEMUIOVector *qiov)

{

    BDRVQcowState *s = bs->opaque;

    int index_in_cluster;

    uint64_t cluster_offset;

    int ret = 0, n;

    struct iovec hd_iov;

    QEMUIOVector hd_qiov;

    uint8_t *buf;

    void *orig_buf;



    s->cluster_cache_offset = -1; /* disable compressed cache */



    /* We must always copy the iov when encrypting, so we

     * don't modify the original data buffer during encryption */

    if (bs->encrypted || qiov->niov > 1) {

        buf = orig_buf = qemu_try_blockalign(bs, qiov->size);

        if (buf == NULL) {

            return -ENOMEM;

        }

        qemu_iovec_to_buf(qiov, 0, buf, qiov->size);

    } else {

        orig_buf = NULL;

        buf = (uint8_t *)qiov->iov->iov_base;

    }



    qemu_co_mutex_lock(&s->lock);



    while (nb_sectors != 0) {



        index_in_cluster = sector_num & (s->cluster_sectors - 1);

        n = s->cluster_sectors - index_in_cluster;

        if (n > nb_sectors) {

            n = nb_sectors;

        }

        cluster_offset = get_cluster_offset(bs, sector_num << 9, 1, 0,

                                            index_in_cluster,

                                            index_in_cluster + n);

        if (!cluster_offset || (cluster_offset & 511) != 0) {

            ret = -EIO;

            break;

        }

        if (bs->encrypted) {

            assert(s->crypto);

            if (qcrypto_block_encrypt(s->crypto, sector_num, buf,

                                      n * BDRV_SECTOR_SIZE, NULL) < 0) {

                ret = -EIO;

                break;

            }

        }



        hd_iov.iov_base = (void *)buf;

        hd_iov.iov_len = n * 512;

        qemu_iovec_init_external(&hd_qiov, &hd_iov, 1);

        qemu_co_mutex_unlock(&s->lock);

        ret = bdrv_co_writev(bs->file,

                             (cluster_offset >> 9) + index_in_cluster,

                             n, &hd_qiov);

        qemu_co_mutex_lock(&s->lock);

        if (ret < 0) {

            break;

        }

        ret = 0;



        nb_sectors -= n;

        sector_num += n;

        buf += n * 512;

    }

    qemu_co_mutex_unlock(&s->lock);



    qemu_vfree(orig_buf);



    return ret;

}

static int vhdx_create_bat(BlockDriverState *bs, BDRVVHDXState *s,

                           uint64_t image_size, VHDXImageType type,

                           bool use_zero_blocks, uint64_t file_offset,

                           uint32_t length)

{

    int ret = 0;

    uint64_t data_file_offset;

    uint64_t total_sectors = 0;

    uint64_t sector_num = 0;

    uint64_t unused;

    int block_state;

    VHDXSectorInfo sinfo;



    assert(s->bat == NULL);



    /* this gives a data start after BAT/bitmap entries, and well

     * past any metadata entries (with a 4 MB buffer for future

     * expansion */

    data_file_offset = file_offset + length + 5 * MiB;

    total_sectors = image_size >> s->logical_sector_size_bits;



    if (type == VHDX_TYPE_DYNAMIC) {

        /* All zeroes, so we can just extend the file - the end of the BAT

         * is the furthest thing we have written yet */

        ret = bdrv_truncate(bs, data_file_offset);

        if (ret < 0) {

            goto exit;

        }

    } else if (type == VHDX_TYPE_FIXED) {

        ret = bdrv_truncate(bs, data_file_offset + image_size);

        if (ret < 0) {

            goto exit;

        }

    } else {

        ret = -ENOTSUP;

        goto exit;

    }



    if (type == VHDX_TYPE_FIXED ||

                use_zero_blocks ||

                bdrv_has_zero_init(bs) == 0) {

        /* for a fixed file, the default BAT entry is not zero */

        s->bat = g_malloc0(length);

        block_state = type == VHDX_TYPE_FIXED ? PAYLOAD_BLOCK_FULLY_PRESENT :

                                                PAYLOAD_BLOCK_NOT_PRESENT;

        block_state = use_zero_blocks ? PAYLOAD_BLOCK_ZERO : block_state;

        /* fill the BAT by emulating sector writes of sectors_per_block size */

        while (sector_num < total_sectors) {

            vhdx_block_translate(s, sector_num, s->sectors_per_block, &sinfo);

            sinfo.file_offset = data_file_offset +

                                (sector_num << s->logical_sector_size_bits);

            sinfo.file_offset = ROUND_UP(sinfo.file_offset, MiB);

            vhdx_update_bat_table_entry(bs, s, &sinfo, &unused, &unused,

                                        block_state);

            cpu_to_le64s(&s->bat[sinfo.bat_idx]);

            sector_num += s->sectors_per_block;

        }

        ret = bdrv_pwrite(bs, file_offset, s->bat, length);

        if (ret < 0) {

            goto exit;

        }

    }







exit:

    g_free(s->bat);

    return ret;

}

static BlockBackend *blockdev_init(const char *file, QDict *bs_opts,
                                   Error **errp)
{
    const char *buf;
    int bdrv_flags = 0;
    int on_read_error, on_write_error;
    bool account_invalid, account_failed;
    BlockBackend *blk;
    BlockDriverState *bs;
    ThrottleConfig cfg;
    int snapshot = 0;
    Error *error = NULL;
    QemuOpts *opts;
    const char *id;
    bool has_driver_specific_opts;
    BlockdevDetectZeroesOptions detect_zeroes =
        BLOCKDEV_DETECT_ZEROES_OPTIONS_OFF;
    const char *throttling_group = NULL;
    /* Check common options by copying from bs_opts to opts, all other options
     * stay in bs_opts for processing by bdrv_open(). */
    id = qdict_get_try_str(bs_opts, "id");
    opts = qemu_opts_create(&qemu_common_drive_opts, id, 1, &error);
    if (error) {
        error_propagate(errp, error);
        goto err_no_opts;
    }
    qemu_opts_absorb_qdict(opts, bs_opts, &error);
    if (error) {
        error_propagate(errp, error);
        goto early_err;
    }
    if (id) {
        qdict_del(bs_opts, "id");
    }
    has_driver_specific_opts = !!qdict_size(bs_opts);
    /* extract parameters */
    snapshot = qemu_opt_get_bool(opts, "snapshot", 0);
    extract_common_blockdev_options(opts, &bdrv_flags, &throttling_group, &cfg,
                                    &detect_zeroes, &error);
    if (error) {
        error_propagate(errp, error);
        goto early_err;
    }
    if ((buf = qemu_opt_get(opts, "format")) != NULL) {
        if (is_help_option(buf)) {
            error_printf("Supported formats:");
            bdrv_iterate_format(bdrv_format_print, NULL);
            error_printf("\n");
            goto early_err;
        }
        if (qdict_haskey(bs_opts, "driver")) {
            error_setg(errp, "Cannot specify both 'driver' and 'format'");
            goto early_err;
        }
        qdict_put(bs_opts, "driver", qstring_from_str(buf));
    }
    on_write_error = BLOCKDEV_ON_ERROR_ENOSPC;
    if ((buf = qemu_opt_get(opts, "werror")) != NULL) {
        on_write_error = parse_block_error_action(buf, 0, &error);
        if (error) {
            error_propagate(errp, error);
            goto early_err;
        }
    }
    on_read_error = BLOCKDEV_ON_ERROR_REPORT;
    if ((buf = qemu_opt_get(opts, "rerror")) != NULL) {
        on_read_error = parse_block_error_action(buf, 1, &error);
        if (error) {
            error_propagate(errp, error);
            goto early_err;
        }
    }
    if (snapshot) {
        /* always use cache=unsafe with snapshot */
        bdrv_flags &= ~BDRV_O_CACHE_MASK;
        bdrv_flags |= (BDRV_O_SNAPSHOT|BDRV_O_CACHE_WB|BDRV_O_NO_FLUSH);
    }
    /* init */
    if ((!file || !*file) && !has_driver_specific_opts) {
        BlockBackendRootState *blk_rs;
        blk = blk_new(qemu_opts_id(opts), errp);
        if (!blk) {
            goto early_err;
        }
        blk_rs = blk_get_root_state(blk);
        blk_rs->open_flags    = bdrv_flags;
        blk_rs->read_only     = !(bdrv_flags & BDRV_O_RDWR);
        blk_rs->detect_zeroes = detect_zeroes;
        if (throttle_enabled(&cfg)) {
            if (!throttling_group) {
                throttling_group = blk_name(blk);
            }
            blk_rs->throttle_group = g_strdup(throttling_group);
            blk_rs->throttle_state = throttle_group_incref(throttling_group);
            blk_rs->throttle_state->cfg = cfg;
        }
        QDECREF(bs_opts);
    } else {
        if (file && !*file) {
            file = NULL;
        }
        blk = blk_new_open(qemu_opts_id(opts), file, NULL, bs_opts, bdrv_flags,
                           errp);
        if (!blk) {
            goto err_no_bs_opts;
        }
        bs = blk_bs(blk);
        bs->detect_zeroes = detect_zeroes;
        /* disk I/O throttling */
        if (throttle_enabled(&cfg)) {
            if (!throttling_group) {
                throttling_group = blk_name(blk);
            }
            bdrv_io_limits_enable(bs, throttling_group);
            bdrv_set_io_limits(bs, &cfg);
        }
        if (bdrv_key_required(bs)) {
            autostart = 0;
        }
        block_acct_init(blk_get_stats(blk), account_invalid, account_failed);
    }
    blk_set_on_error(blk, on_read_error, on_write_error);
err_no_bs_opts:
    qemu_opts_del(opts);
    return blk;
early_err:
    qemu_opts_del(opts);
err_no_opts:
    QDECREF(bs_opts);
    return NULL;
}

static void json_print_chapter_header(WriterContext *wctx, const char *chapter)

{

    JSONContext *json = wctx->priv;

    char *chapter_esc;



    if (wctx->nb_chapter)

        printf(",");

    json->multiple_entries = !strcmp(chapter, "packets") || !strcmp(chapter, "streams");

    chapter_esc = json_escape_str(chapter);

    printf("\n  \"%s\":%s", chapter_esc ? chapter_esc : "",

           json->multiple_entries ? " [" : " ");

    av_free(chapter_esc);

}

int nbd_client_co_pwritev(BlockDriverState *bs, uint64_t offset,

                          uint64_t bytes, QEMUIOVector *qiov, int flags)

{

    NbdClientSession *client = nbd_get_client_session(bs);

    struct nbd_request request = {

        .type = NBD_CMD_WRITE,

        .from = offset,

        .len = bytes,

    };

    struct nbd_reply reply;

    ssize_t ret;



    if (flags & BDRV_REQ_FUA) {

        assert(client->nbdflags & NBD_FLAG_SEND_FUA);

        request.type |= NBD_CMD_FLAG_FUA;

    }



    assert(bytes <= NBD_MAX_BUFFER_SIZE);



    nbd_coroutine_start(client, &request);

    ret = nbd_co_send_request(bs, &request, qiov);

    if (ret < 0) {

        reply.error = -ret;

    } else {

        nbd_co_receive_reply(client, &request, &reply, NULL);

    }

    nbd_coroutine_end(client, &request);

    return -reply.error;

}

int ff_h263_decode_mb(MpegEncContext *s,

                      DCTELEM block[6][64])

{

    int cbpc, cbpy, i, cbp, pred_x, pred_y, mx, my, dquant;

    INT16 *mot_val;

    static INT8 quant_tab[4] = { -1, -2, 1, 2 };



    s->error_status_table[s->mb_x + s->mb_y*s->mb_width]= 0;



    if(s->mb_x==0) PRINT_MB_TYPE("\n");



    if (s->pict_type == P_TYPE || s->pict_type==S_TYPE) {

        if (get_bits1(&s->gb)) {

            /* skip mb */

            s->mb_intra = 0;

            for(i=0;i<6;i++)

                s->block_last_index[i] = -1;

            s->mv_dir = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

            if(s->pict_type==S_TYPE && s->vol_sprite_usage==GMC_SPRITE){

                PRINT_MB_TYPE("G");

                s->mcsel=1;

                s->mv[0][0][0]= get_amv(s, 0);

                s->mv[0][0][1]= get_amv(s, 1);



                s->mb_skiped = 0;

            }else{

                PRINT_MB_TYPE("S");

                s->mcsel=0;

                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->mb_skiped = 1;

            }

            goto end;

        }

        cbpc = get_vlc2(&s->gb, inter_MCBPC_vlc.table, INTER_MCBPC_VLC_BITS, 2);

        //fprintf(stderr, "\tCBPC: %d", cbpc);

        if (cbpc < 0)

            return -1;

        if (cbpc > 20)

            cbpc+=3;

        else if (cbpc == 20)

            fprintf(stderr, "Stuffing !");



        dquant = cbpc & 8;

        s->mb_intra = ((cbpc & 4) != 0);

        if (s->mb_intra) goto intra;



        if(s->pict_type==S_TYPE && s->vol_sprite_usage==GMC_SPRITE && (cbpc & 16) == 0)

            s->mcsel= get_bits1(&s->gb);

        else s->mcsel= 0;

        cbpy = get_vlc2(&s->gb, cbpy_vlc.table, CBPY_VLC_BITS, 1);

        cbp = (cbpc & 3) | ((cbpy ^ 0xf) << 2);

        if (dquant) {

            change_qscale(s, quant_tab[get_bits(&s->gb, 2)]);

        }

        if((!s->progressive_sequence) && (cbp || (s->workaround_bugs&FF_BUG_XVID_ILACE)))

            s->interlaced_dct= get_bits1(&s->gb);



        s->mv_dir = MV_DIR_FORWARD;

        if ((cbpc & 16) == 0) {

            if(s->mcsel){

                PRINT_MB_TYPE("G");

                /* 16x16 global motion prediction */

                s->mv_type = MV_TYPE_16X16;

                mx= get_amv(s, 0);

                my= get_amv(s, 1);

                s->mv[0][0][0] = mx;

                s->mv[0][0][1] = my;

            }else if((!s->progressive_sequence) && get_bits1(&s->gb)){

                PRINT_MB_TYPE("f");

                /* 16x8 field motion prediction */

                s->mv_type= MV_TYPE_FIELD;



                s->field_select[0][0]= get_bits1(&s->gb);

                s->field_select[0][1]= get_bits1(&s->gb);



                h263_pred_motion(s, 0, &pred_x, &pred_y);



                for(i=0; i<2; i++){

                    mx = h263_decode_motion(s, pred_x, s->f_code);

                    if (mx >= 0xffff)

                        return -1;



                    my = h263_decode_motion(s, pred_y/2, s->f_code);

                    if (my >= 0xffff)

                        return -1;



                    s->mv[0][i][0] = mx;

                    s->mv[0][i][1] = my;

                }

            }else{

                PRINT_MB_TYPE("P");

                /* 16x16 motion prediction */

                s->mv_type = MV_TYPE_16X16;

                h263_pred_motion(s, 0, &pred_x, &pred_y);

                if (s->umvplus_dec)

                   mx = h263p_decode_umotion(s, pred_x);

                else

                   mx = h263_decode_motion(s, pred_x, s->f_code);



                if (mx >= 0xffff)

                    return -1;



                if (s->umvplus_dec)

                   my = h263p_decode_umotion(s, pred_y);

                else

                   my = h263_decode_motion(s, pred_y, s->f_code);



                if (my >= 0xffff)

                    return -1;

                s->mv[0][0][0] = mx;

                s->mv[0][0][1] = my;



                if (s->umvplus_dec && (mx - pred_x) == 1 && (my - pred_y) == 1)

                   skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */                   

            }

        } else {

            PRINT_MB_TYPE("4");

            s->mv_type = MV_TYPE_8X8;

            for(i=0;i<4;i++) {

                mot_val = h263_pred_motion(s, i, &pred_x, &pred_y);

                if (s->umvplus_dec)

                  mx = h263p_decode_umotion(s, pred_x);

                else

                  mx = h263_decode_motion(s, pred_x, s->f_code);

                if (mx >= 0xffff)

                    return -1;



                if (s->umvplus_dec)

                  my = h263p_decode_umotion(s, pred_y);

                else    

                  my = h263_decode_motion(s, pred_y, s->f_code);

                if (my >= 0xffff)

                    return -1;

                s->mv[0][i][0] = mx;

                s->mv[0][i][1] = my;

                if (s->umvplus_dec && (mx - pred_x) == 1 && (my - pred_y) == 1)

                  skip_bits1(&s->gb); /* Bit stuffing to prevent PSC */

                mot_val[0] = mx;

                mot_val[1] = my;

            }

        }

    } else if(s->pict_type==B_TYPE) {

        int modb1; // first bit of modb

        int modb2; // second bit of modb

        int mb_type;

        int xy;



        s->mb_intra = 0; //B-frames never contain intra blocks

        s->mcsel=0;      //     ...               true gmc blocks



        if(s->mb_x==0){

            for(i=0; i<2; i++){

                s->last_mv[i][0][0]= 

                s->last_mv[i][0][1]= 

                s->last_mv[i][1][0]= 

                s->last_mv[i][1][1]= 0;

            }

        }



        /* if we skipped it in the future P Frame than skip it now too */

        s->mb_skiped= s->next_picture.mbskip_table[s->mb_y * s->mb_width + s->mb_x]; // Note, skiptab=0 if last was GMC



        if(s->mb_skiped){

                /* skip mb */

            for(i=0;i<6;i++)

                s->block_last_index[i] = -1;



            s->mv_dir = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

            s->mv[0][0][0] = 0;

            s->mv[0][0][1] = 0;

            s->mv[1][0][0] = 0;

            s->mv[1][0][1] = 0;

            PRINT_MB_TYPE("s");

            goto end;

        }



        modb1= get_bits1(&s->gb); 

        if(modb1){

            mb_type=4; //like MB_TYPE_B_DIRECT but no vectors coded

            cbp=0;

        }else{

            int field_mv;



            modb2= get_bits1(&s->gb);

            mb_type= get_vlc2(&s->gb, mb_type_b_vlc.table, MB_TYPE_B_VLC_BITS, 1);

            if(modb2) cbp= 0;

            else      cbp= get_bits(&s->gb, 6);



            if (mb_type!=MB_TYPE_B_DIRECT && cbp) {

                if(get_bits1(&s->gb)){

                    change_qscale(s, get_bits1(&s->gb)*4 - 2);

                }

            }

            field_mv=0;



            if(!s->progressive_sequence){

                if(cbp)

                    s->interlaced_dct= get_bits1(&s->gb);



                if(mb_type!=MB_TYPE_B_DIRECT && get_bits1(&s->gb)){

                    field_mv=1;



                    if(mb_type!=MB_TYPE_B_BACKW){

                        s->field_select[0][0]= get_bits1(&s->gb);

                        s->field_select[0][1]= get_bits1(&s->gb);

                    }

                    if(mb_type!=MB_TYPE_B_FORW){

                        s->field_select[1][0]= get_bits1(&s->gb);

                        s->field_select[1][1]= get_bits1(&s->gb);

                    }

                }

            }



            s->mv_dir = 0;

            if(mb_type!=MB_TYPE_B_DIRECT && !field_mv){

                s->mv_type= MV_TYPE_16X16;

                if(mb_type!=MB_TYPE_B_BACKW){

                    s->mv_dir = MV_DIR_FORWARD;



                    mx = h263_decode_motion(s, s->last_mv[0][0][0], s->f_code);

                    my = h263_decode_motion(s, s->last_mv[0][0][1], s->f_code);

                    s->last_mv[0][1][0]= s->last_mv[0][0][0]= s->mv[0][0][0] = mx;

                    s->last_mv[0][1][1]= s->last_mv[0][0][1]= s->mv[0][0][1] = my;

                }



                if(mb_type!=MB_TYPE_B_FORW){

                    s->mv_dir |= MV_DIR_BACKWARD;



                    mx = h263_decode_motion(s, s->last_mv[1][0][0], s->b_code);

                    my = h263_decode_motion(s, s->last_mv[1][0][1], s->b_code);

                    s->last_mv[1][1][0]= s->last_mv[1][0][0]= s->mv[1][0][0] = mx;

                    s->last_mv[1][1][1]= s->last_mv[1][0][1]= s->mv[1][0][1] = my;

                }

                if(mb_type!=MB_TYPE_B_DIRECT)

                    PRINT_MB_TYPE(mb_type==MB_TYPE_B_FORW ? "F" : (mb_type==MB_TYPE_B_BACKW ? "B" : "T"));

            }else if(mb_type!=MB_TYPE_B_DIRECT){

                s->mv_type= MV_TYPE_FIELD;



                if(mb_type!=MB_TYPE_B_BACKW){

                    s->mv_dir = MV_DIR_FORWARD;



                    for(i=0; i<2; i++){

                        mx = h263_decode_motion(s, s->last_mv[0][i][0]  , s->f_code);

                        my = h263_decode_motion(s, s->last_mv[0][i][1]/2, s->f_code);

                        s->last_mv[0][i][0]=  s->mv[0][i][0] = mx;

                        s->last_mv[0][i][1]= (s->mv[0][i][1] = my)*2;

                    }

                }



                if(mb_type!=MB_TYPE_B_FORW){

                    s->mv_dir |= MV_DIR_BACKWARD;



                    for(i=0; i<2; i++){

                        mx = h263_decode_motion(s, s->last_mv[1][i][0]  , s->b_code);

                        my = h263_decode_motion(s, s->last_mv[1][i][1]/2, s->b_code);

                        s->last_mv[1][i][0]=  s->mv[1][i][0] = mx;

                        s->last_mv[1][i][1]= (s->mv[1][i][1] = my)*2;

                    }

                }

                if(mb_type!=MB_TYPE_B_DIRECT)

                    PRINT_MB_TYPE(mb_type==MB_TYPE_B_FORW ? "f" : (mb_type==MB_TYPE_B_BACKW ? "b" : "t"));

            }

        }



        if(mb_type==4 || mb_type==MB_TYPE_B_DIRECT){

            if(mb_type==4)

                mx=my=0;

            else{

                mx = h263_decode_motion(s, 0, 1);

                my = h263_decode_motion(s, 0, 1);

            }



            s->mv_dir = MV_DIR_FORWARD | MV_DIR_BACKWARD | MV_DIRECT;

            ff_mpeg4_set_direct_mv(s, mx, my);

        }



        if(mb_type<0 || mb_type>4){

            printf("illegal MB_type\n");

            return -1;

        }

    } else { /* I-Frame */

        cbpc = get_vlc2(&s->gb, intra_MCBPC_vlc.table, INTRA_MCBPC_VLC_BITS, 1);

        if (cbpc < 0)

            return -1;

        dquant = cbpc & 4;

        s->mb_intra = 1;

intra:

        s->ac_pred = 0;

        if (s->h263_pred || s->h263_aic) {

            s->ac_pred = get_bits1(&s->gb);

            if (s->ac_pred && s->h263_aic)

                s->h263_aic_dir = get_bits1(&s->gb);

        }

        PRINT_MB_TYPE(s->ac_pred ? "A" : "I");



        cbpy = get_vlc2(&s->gb, cbpy_vlc.table, CBPY_VLC_BITS, 1);

        if(cbpy<0) return -1;

        cbp = (cbpc & 3) | (cbpy << 2);

        if (dquant) {

            change_qscale(s, quant_tab[get_bits(&s->gb, 2)]);

        }



        if(!s->progressive_sequence)

            s->interlaced_dct= get_bits1(&s->gb);



        /* decode each block */

        if (s->h263_pred) {

            for (i = 0; i < 6; i++) {

                if (mpeg4_decode_block(s, block[i], i, cbp&32, 1) < 0)

                    return -1;

                cbp+=cbp;

            }

        } else {

            for (i = 0; i < 6; i++) {

                if (h263_decode_block(s, block[i], i, cbp&32) < 0)

                    return -1;

                cbp+=cbp;

            }

        }

        goto end;

    }



    /* decode each block */

    if (s->h263_pred) {

        for (i = 0; i < 6; i++) {

            if (mpeg4_decode_block(s, block[i], i, cbp&32, 0) < 0)

                return -1;

            cbp+=cbp;

        }

    } else {

        for (i = 0; i < 6; i++) {

            if (h263_decode_block(s, block[i], i, cbp&32) < 0)

                return -1;

            cbp+=cbp;

        }

    }

end:



        /* per-MB end of slice check */

    if(s->codec_id==CODEC_ID_MPEG4){

        if(mpeg4_is_resync(s)){

            if(s->pict_type==B_TYPE && s->next_picture.mbskip_table[s->mb_y * s->mb_width + s->mb_x+1])

                return SLICE_OK;

            return SLICE_END;

        }

    }else{

        int v= show_bits(&s->gb, 16);



        if(get_bits_count(&s->gb) + 16 > s->gb.size*8){

            v>>= get_bits_count(&s->gb) + 16 - s->gb.size*8;

        }



        if(v==0)

            return SLICE_END;

    }



    return SLICE_OK;     

}

int vnc_display_password(DisplayState *ds, const char *password)

{

    VncDisplay *vs = vnc_display;



    if (!vs) {

        return -EINVAL;

    }



    if (!password) {

        /* This is not the intention of this interface but err on the side

           of being safe */

        return vnc_display_disable_login(ds);

    }



    if (vs->password) {

        g_free(vs->password);

        vs->password = NULL;

    }

    vs->password = g_strdup(password);

    if (vs->auth == VNC_AUTH_NONE) {

        vs->auth = VNC_AUTH_VNC;

    }



    return 0;

}

void ff_vdpau_h264_picture_complete(MpegEncContext *s)

{

    H264Context *h = s->avctx->priv_data;

    struct vdpau_render_state *render;

    int i;



    render = (struct vdpau_render_state *)s->current_picture_ptr->data[0];

    assert(render);



    render->info.h264.slice_count = h->slice_num;

    if (render->info.h264.slice_count < 1)

        return;



    for (i = 0; i < 2; ++i) {

        int foc = s->current_picture_ptr->field_poc[i];

        if (foc == INT_MAX)

            foc = 0;

        render->info.h264.field_order_cnt[i] = foc;

    }



    render->info.h264.is_reference                           = (s->current_picture_ptr->reference & 3) ? VDP_TRUE : VDP_FALSE;

    render->info.h264.frame_num                              = h->frame_num;

    render->info.h264.field_pic_flag                         = s->picture_structure != PICT_FRAME;

    render->info.h264.bottom_field_flag                      = s->picture_structure == PICT_BOTTOM_FIELD;

    render->info.h264.num_ref_frames                         = h->sps.ref_frame_count;

    render->info.h264.mb_adaptive_frame_field_flag           = h->sps.mb_aff && !render->info.h264.field_pic_flag;

    render->info.h264.constrained_intra_pred_flag            = h->pps.constrained_intra_pred;

    render->info.h264.weighted_pred_flag                     = h->pps.weighted_pred;

    render->info.h264.weighted_bipred_idc                    = h->pps.weighted_bipred_idc;

    render->info.h264.frame_mbs_only_flag                    = h->sps.frame_mbs_only_flag;

    render->info.h264.transform_8x8_mode_flag                = h->pps.transform_8x8_mode;

    render->info.h264.chroma_qp_index_offset                 = h->pps.chroma_qp_index_offset[0];

    render->info.h264.second_chroma_qp_index_offset          = h->pps.chroma_qp_index_offset[1];

    render->info.h264.pic_init_qp_minus26                    = h->pps.init_qp - 26;

    render->info.h264.num_ref_idx_l0_active_minus1           = h->pps.ref_count[0] - 1;

    render->info.h264.num_ref_idx_l1_active_minus1           = h->pps.ref_count[1] - 1;

    render->info.h264.log2_max_frame_num_minus4              = h->sps.log2_max_frame_num - 4;

    render->info.h264.pic_order_cnt_type                     = h->sps.poc_type;

    render->info.h264.log2_max_pic_order_cnt_lsb_minus4      = h->sps.log2_max_poc_lsb - 4;

    render->info.h264.delta_pic_order_always_zero_flag       = h->sps.delta_pic_order_always_zero_flag;

    render->info.h264.direct_8x8_inference_flag              = h->sps.direct_8x8_inference_flag;

    render->info.h264.entropy_coding_mode_flag               = h->pps.cabac;

    render->info.h264.pic_order_present_flag                 = h->pps.pic_order_present;

    render->info.h264.deblocking_filter_control_present_flag = h->pps.deblocking_filter_parameters_present;

    render->info.h264.redundant_pic_cnt_present_flag         = h->pps.redundant_pic_cnt_present;

    memcpy(render->info.h264.scaling_lists_4x4, h->pps.scaling_matrix4, sizeof(render->info.h264.scaling_lists_4x4));

    memcpy(render->info.h264.scaling_lists_8x8, h->pps.scaling_matrix8, sizeof(render->info.h264.scaling_lists_8x8));



    ff_draw_horiz_band(s, 0, s->avctx->height);

    render->bitstream_buffers_used = 0;

}

static int htab_save_complete(QEMUFile *f, void *opaque)

{

    sPAPRMachineState *spapr = opaque;



    /* Iteration header */

    qemu_put_be32(f, 0);



    if (!spapr->htab) {

        int rc;



        assert(kvm_enabled());



        rc = spapr_check_htab_fd(spapr);

        if (rc < 0) {

            return rc;

        }



        rc = kvmppc_save_htab(f, spapr->htab_fd, MAX_KVM_BUF_SIZE, -1);

        if (rc < 0) {

            return rc;

        }

        close(spapr->htab_fd);

        spapr->htab_fd = -1;

    } else {

        htab_save_later_pass(f, spapr, -1);

    }



    /* End marker */

    qemu_put_be32(f, 0);

    qemu_put_be16(f, 0);

    qemu_put_be16(f, 0);



    return 0;

}

DriveInfo *drive_init(QemuOpts *opts, int default_to_scsi, int *fatal_error)

{

    const char *buf;

    const char *file = NULL;

    char devname[128];

    const char *serial;

    const char *mediastr = "";

    BlockInterfaceType type;

    enum { MEDIA_DISK, MEDIA_CDROM } media;

    int bus_id, unit_id;

    int cyls, heads, secs, translation;

    BlockDriver *drv = NULL;

    int max_devs;

    int index;

    int ro = 0;

    int bdrv_flags = 0;

    int on_read_error, on_write_error;

    const char *devaddr;

    DriveInfo *dinfo;

    int snapshot = 0;

    int ret;



    *fatal_error = 1;



    translation = BIOS_ATA_TRANSLATION_AUTO;



    if (default_to_scsi) {

        type = IF_SCSI;

        max_devs = MAX_SCSI_DEVS;

        pstrcpy(devname, sizeof(devname), "scsi");

    } else {

        type = IF_IDE;

        max_devs = MAX_IDE_DEVS;

        pstrcpy(devname, sizeof(devname), "ide");

    }

    media = MEDIA_DISK;



    /* extract parameters */

    bus_id  = qemu_opt_get_number(opts, "bus", 0);

    unit_id = qemu_opt_get_number(opts, "unit", -1);

    index   = qemu_opt_get_number(opts, "index", -1);



    cyls  = qemu_opt_get_number(opts, "cyls", 0);

    heads = qemu_opt_get_number(opts, "heads", 0);

    secs  = qemu_opt_get_number(opts, "secs", 0);



    snapshot = qemu_opt_get_bool(opts, "snapshot", 0);

    ro = qemu_opt_get_bool(opts, "readonly", 0);



    file = qemu_opt_get(opts, "file");

    serial = qemu_opt_get(opts, "serial");



    if ((buf = qemu_opt_get(opts, "if")) != NULL) {

        pstrcpy(devname, sizeof(devname), buf);

        if (!strcmp(buf, "ide")) {

	    type = IF_IDE;

            max_devs = MAX_IDE_DEVS;

        } else if (!strcmp(buf, "scsi")) {

	    type = IF_SCSI;

            max_devs = MAX_SCSI_DEVS;

        } else if (!strcmp(buf, "floppy")) {

	    type = IF_FLOPPY;

            max_devs = 0;

        } else if (!strcmp(buf, "pflash")) {

	    type = IF_PFLASH;

            max_devs = 0;

	} else if (!strcmp(buf, "mtd")) {

	    type = IF_MTD;

            max_devs = 0;

	} else if (!strcmp(buf, "sd")) {

	    type = IF_SD;

            max_devs = 0;

        } else if (!strcmp(buf, "virtio")) {

            type = IF_VIRTIO;

            max_devs = 0;

	} else if (!strcmp(buf, "xen")) {

	    type = IF_XEN;

            max_devs = 0;

	} else if (!strcmp(buf, "none")) {

	    type = IF_NONE;

            max_devs = 0;

	} else {

            fprintf(stderr, "qemu: unsupported bus type '%s'\n", buf);

            return NULL;

	}

    }



    if (cyls || heads || secs) {

        if (cyls < 1 || (type == IF_IDE && cyls > 16383)) {

            fprintf(stderr, "qemu: '%s' invalid physical cyls number\n", buf);

	    return NULL;

	}

        if (heads < 1 || (type == IF_IDE && heads > 16)) {

            fprintf(stderr, "qemu: '%s' invalid physical heads number\n", buf);

	    return NULL;

	}

        if (secs < 1 || (type == IF_IDE && secs > 63)) {

            fprintf(stderr, "qemu: '%s' invalid physical secs number\n", buf);

	    return NULL;

	}

    }



    if ((buf = qemu_opt_get(opts, "trans")) != NULL) {

        if (!cyls) {

            fprintf(stderr,

                    "qemu: '%s' trans must be used with cyls,heads and secs\n",

                    buf);

            return NULL;

        }

        if (!strcmp(buf, "none"))

            translation = BIOS_ATA_TRANSLATION_NONE;

        else if (!strcmp(buf, "lba"))

            translation = BIOS_ATA_TRANSLATION_LBA;

        else if (!strcmp(buf, "auto"))

            translation = BIOS_ATA_TRANSLATION_AUTO;

	else {

            fprintf(stderr, "qemu: '%s' invalid translation type\n", buf);

	    return NULL;

	}

    }



    if ((buf = qemu_opt_get(opts, "media")) != NULL) {

        if (!strcmp(buf, "disk")) {

	    media = MEDIA_DISK;

	} else if (!strcmp(buf, "cdrom")) {

            if (cyls || secs || heads) {

                fprintf(stderr,

                        "qemu: '%s' invalid physical CHS format\n", buf);

	        return NULL;

            }

	    media = MEDIA_CDROM;

	} else {

	    fprintf(stderr, "qemu: '%s' invalid media\n", buf);

	    return NULL;

	}

    }



    if ((buf = qemu_opt_get(opts, "cache")) != NULL) {

        if (!strcmp(buf, "off") || !strcmp(buf, "none")) {

            bdrv_flags |= BDRV_O_NOCACHE;

        } else if (!strcmp(buf, "writeback")) {

            bdrv_flags |= BDRV_O_CACHE_WB;

        } else if (!strcmp(buf, "unsafe")) {

            bdrv_flags |= BDRV_O_CACHE_WB;

            bdrv_flags |= BDRV_O_NO_FLUSH;

        } else if (!strcmp(buf, "writethrough")) {

            /* this is the default */

        } else {

           fprintf(stderr, "qemu: invalid cache option\n");

           return NULL;

        }

    }



#ifdef CONFIG_LINUX_AIO

    if ((buf = qemu_opt_get(opts, "aio")) != NULL) {

        if (!strcmp(buf, "native")) {

            bdrv_flags |= BDRV_O_NATIVE_AIO;

        } else if (!strcmp(buf, "threads")) {

            /* this is the default */

        } else {

           fprintf(stderr, "qemu: invalid aio option\n");

           return NULL;

        }

    }

#endif



    if ((buf = qemu_opt_get(opts, "format")) != NULL) {

       if (strcmp(buf, "?") == 0) {

            fprintf(stderr, "qemu: Supported formats:");

            bdrv_iterate_format(bdrv_format_print, NULL);

            fprintf(stderr, "\n");

	    return NULL;

        }

        drv = bdrv_find_whitelisted_format(buf);

        if (!drv) {

            fprintf(stderr, "qemu: '%s' invalid format\n", buf);

            return NULL;

        }

    }



    on_write_error = BLOCK_ERR_STOP_ENOSPC;

    if ((buf = qemu_opt_get(opts, "werror")) != NULL) {

        if (type != IF_IDE && type != IF_SCSI && type != IF_VIRTIO && type != IF_NONE) {

            fprintf(stderr, "werror is no supported by this format\n");

            return NULL;

        }



        on_write_error = parse_block_error_action(buf, 0);

        if (on_write_error < 0) {

            return NULL;

        }

    }



    on_read_error = BLOCK_ERR_REPORT;

    if ((buf = qemu_opt_get(opts, "rerror")) != NULL) {

        if (type != IF_IDE && type != IF_VIRTIO && type != IF_NONE) {

            fprintf(stderr, "rerror is no supported by this format\n");

            return NULL;

        }



        on_read_error = parse_block_error_action(buf, 1);

        if (on_read_error < 0) {

            return NULL;

        }

    }



    if ((devaddr = qemu_opt_get(opts, "addr")) != NULL) {

        if (type != IF_VIRTIO) {

            fprintf(stderr, "addr is not supported\n");

            return NULL;

        }

    }



    /* compute bus and unit according index */



    if (index != -1) {

        if (bus_id != 0 || unit_id != -1) {

            fprintf(stderr,

                    "qemu: index cannot be used with bus and unit\n");

            return NULL;

        }

        if (max_devs == 0)

        {

            unit_id = index;

            bus_id = 0;

        } else {

            unit_id = index % max_devs;

            bus_id = index / max_devs;

        }

    }



    /* if user doesn't specify a unit_id,

     * try to find the first free

     */



    if (unit_id == -1) {

       unit_id = 0;

       while (drive_get(type, bus_id, unit_id) != NULL) {

           unit_id++;

           if (max_devs && unit_id >= max_devs) {

               unit_id -= max_devs;

               bus_id++;

           }

       }

    }



    /* check unit id */



    if (max_devs && unit_id >= max_devs) {

        fprintf(stderr, "qemu: unit %d too big (max is %d)\n",

                unit_id, max_devs - 1);

        return NULL;

    }



    /*

     * ignore multiple definitions

     */



    if (drive_get(type, bus_id, unit_id) != NULL) {

        *fatal_error = 0;

        return NULL;

    }



    /* init */



    dinfo = qemu_mallocz(sizeof(*dinfo));

    if ((buf = qemu_opts_id(opts)) != NULL) {

        dinfo->id = qemu_strdup(buf);

    } else {

        /* no id supplied -> create one */

        dinfo->id = qemu_mallocz(32);

        if (type == IF_IDE || type == IF_SCSI)

            mediastr = (media == MEDIA_CDROM) ? "-cd" : "-hd";

        if (max_devs)

            snprintf(dinfo->id, 32, "%s%i%s%i",

                     devname, bus_id, mediastr, unit_id);

        else

            snprintf(dinfo->id, 32, "%s%s%i",

                     devname, mediastr, unit_id);

    }

    dinfo->bdrv = bdrv_new(dinfo->id);

    dinfo->devaddr = devaddr;

    dinfo->type = type;

    dinfo->bus = bus_id;

    dinfo->unit = unit_id;

    dinfo->on_read_error = on_read_error;

    dinfo->on_write_error = on_write_error;

    dinfo->opts = opts;

    if (serial)

        strncpy(dinfo->serial, serial, sizeof(serial));

    QTAILQ_INSERT_TAIL(&drives, dinfo, next);



    switch(type) {

    case IF_IDE:

    case IF_SCSI:

    case IF_XEN:

    case IF_NONE:

        switch(media) {

	case MEDIA_DISK:

            if (cyls != 0) {

                bdrv_set_geometry_hint(dinfo->bdrv, cyls, heads, secs);

                bdrv_set_translation_hint(dinfo->bdrv, translation);

            }

	    break;

	case MEDIA_CDROM:

            bdrv_set_type_hint(dinfo->bdrv, BDRV_TYPE_CDROM);

	    break;

	}

        break;

    case IF_SD:

        /* FIXME: This isn't really a floppy, but it's a reasonable

           approximation.  */

    case IF_FLOPPY:

        bdrv_set_type_hint(dinfo->bdrv, BDRV_TYPE_FLOPPY);

        break;

    case IF_PFLASH:

    case IF_MTD:

        break;

    case IF_VIRTIO:

        /* add virtio block device */

        opts = qemu_opts_create(&qemu_device_opts, NULL, 0);

        qemu_opt_set(opts, "driver", "virtio-blk-pci");

        qemu_opt_set(opts, "drive", dinfo->id);

        if (devaddr)

            qemu_opt_set(opts, "addr", devaddr);

        break;

    case IF_COUNT:

        abort();

    }

    if (!file) {

        *fatal_error = 0;

        return NULL;

    }

    if (snapshot) {

        /* always use cache=unsafe with snapshot */

        bdrv_flags &= ~BDRV_O_CACHE_MASK;

        bdrv_flags |= (BDRV_O_SNAPSHOT|BDRV_O_CACHE_WB|BDRV_O_NO_FLUSH);

    }



    if (media == MEDIA_CDROM) {

        /* CDROM is fine for any interface, don't check.  */

        ro = 1;

    } else if (ro == 1) {

        if (type != IF_SCSI && type != IF_VIRTIO && type != IF_FLOPPY && type != IF_NONE) {

            fprintf(stderr, "qemu: readonly flag not supported for drive with this interface\n");

            return NULL;

        }

    }



    bdrv_flags |= ro ? 0 : BDRV_O_RDWR;



    ret = bdrv_open(dinfo->bdrv, file, bdrv_flags, drv);

    if (ret < 0) {

        fprintf(stderr, "qemu: could not open disk image %s: %s\n",

                        file, strerror(-ret));

        return NULL;

    }



    if (bdrv_key_required(dinfo->bdrv))

        autostart = 0;

    *fatal_error = 0;

    return dinfo;

}

