static void dynticks_rearm_timer(struct qemu_alarm_timer *t)

{

    timer_t host_timer = (timer_t)(long)t->priv;

    struct itimerspec timeout;

    int64_t nearest_delta_us = INT64_MAX;

    int64_t current_us;



    if (!active_timers[QEMU_TIMER_REALTIME] &&

                !active_timers[QEMU_TIMER_VIRTUAL])

        return;



    nearest_delta_us = qemu_next_deadline_dyntick();



    /* check whether a timer is already running */

    if (timer_gettime(host_timer, &timeout)) {

        perror("gettime");

        fprintf(stderr, "Internal timer error: aborting\n");

        exit(1);

    }

    current_us = timeout.it_value.tv_sec * 1000000 + timeout.it_value.tv_nsec/1000;

    if (current_us && current_us <= nearest_delta_us)

        return;



    timeout.it_interval.tv_sec = 0;

    timeout.it_interval.tv_nsec = 0; /* 0 for one-shot timer */

    timeout.it_value.tv_sec =  nearest_delta_us / 1000000;

    timeout.it_value.tv_nsec = (nearest_delta_us % 1000000) * 1000;

    if (timer_settime(host_timer, 0 /* RELATIVE */, &timeout, NULL)) {

        perror("settime");

        fprintf(stderr, "Internal timer error: aborting\n");

        exit(1);

    }

}

static void exit_program(void)

{

    int i, j;



    for (i = 0; i < nb_filtergraphs; i++) {

        avfilter_graph_free(&filtergraphs[i]->graph);

        for (j = 0; j < filtergraphs[i]->nb_inputs; j++) {

            av_freep(&filtergraphs[i]->inputs[j]->name);

            av_freep(&filtergraphs[i]->inputs[j]);

        }

        av_freep(&filtergraphs[i]->inputs);

        for (j = 0; j < filtergraphs[i]->nb_outputs; j++) {

            av_freep(&filtergraphs[i]->outputs[j]->name);

            av_freep(&filtergraphs[i]->outputs[j]);

        }

        av_freep(&filtergraphs[i]->outputs);

        av_freep(&filtergraphs[i]->graph_desc);

        av_freep(&filtergraphs[i]);

    }

    av_freep(&filtergraphs);



    /* close files */

    for (i = 0; i < nb_output_files; i++) {

        AVFormatContext *s = output_files[i]->ctx;

        if (s && s->oformat && !(s->oformat->flags & AVFMT_NOFILE) && s->pb)

            avio_close(s->pb);

        avformat_free_context(s);

        av_dict_free(&output_files[i]->opts);

        av_freep(&output_files[i]);

    }

    for (i = 0; i < nb_output_streams; i++) {

        AVBitStreamFilterContext *bsfc = output_streams[i]->bitstream_filters;

        while (bsfc) {

            AVBitStreamFilterContext *next = bsfc->next;

            av_bitstream_filter_close(bsfc);

            bsfc = next;

        }

        output_streams[i]->bitstream_filters = NULL;

        avcodec_free_frame(&output_streams[i]->filtered_frame);



        av_freep(&output_streams[i]->forced_keyframes);

        av_freep(&output_streams[i]->avfilter);

        av_freep(&output_streams[i]->logfile_prefix);

        av_freep(&output_streams[i]);

    }

    for (i = 0; i < nb_input_files; i++) {

        avformat_close_input(&input_files[i]->ctx);

        av_freep(&input_files[i]);

    }

    for (i = 0; i < nb_input_streams; i++) {

        av_frame_free(&input_streams[i]->decoded_frame);

        av_frame_free(&input_streams[i]->filter_frame);

        av_dict_free(&input_streams[i]->opts);

        av_freep(&input_streams[i]->filters);

        av_freep(&input_streams[i]);

    }



    if (vstats_file)

        fclose(vstats_file);

    av_free(vstats_filename);



    av_freep(&input_streams);

    av_freep(&input_files);

    av_freep(&output_streams);

    av_freep(&output_files);



    uninit_opts();



    avformat_network_deinit();



    if (received_sigterm) {

        av_log(NULL, AV_LOG_INFO, "Received signal %d: terminating.\n",

               (int) received_sigterm);

        exit (255);

    }

}

static int mkv_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    MatroskaMuxContext *mkv = s->priv_data;

    int codec_type          = s->streams[pkt->stream_index]->codec->codec_type;

    int keyframe            = !!(pkt->flags & AV_PKT_FLAG_KEY);

    int cluster_size;

    int cluster_size_limit;

    int64_t cluster_time;

    int64_t cluster_time_limit;

    AVIOContext *pb;

    int ret;



    if (mkv->tracks[pkt->stream_index].write_dts)

        cluster_time = pkt->dts - mkv->cluster_pts;

    else

        cluster_time = pkt->pts - mkv->cluster_pts;



    // start a new cluster every 5 MB or 5 sec, or 32k / 1 sec for streaming or

    // after 4k and on a keyframe

    if (s->pb->seekable) {

        pb = s->pb;

        cluster_size = avio_tell(pb) - mkv->cluster_pos;

        cluster_time_limit = 5000;

        cluster_size_limit = 5 * 1024 * 1024;

    } else {

        pb = mkv->dyn_bc;

        cluster_size = avio_tell(pb);

        cluster_time_limit = 1000;

        cluster_size_limit = 32 * 1024;

    }



    if (mkv->cluster_pos &&

        (cluster_size > cluster_size_limit ||

         cluster_time > cluster_time_limit ||

         (codec_type == AVMEDIA_TYPE_VIDEO && keyframe &&

          cluster_size > 4 * 1024))) {

        av_log(s, AV_LOG_DEBUG, "Starting new cluster at offset %" PRIu64

               " bytes, pts %" PRIu64 "dts %" PRIu64 "\n",

               avio_tell(pb), pkt->pts, pkt->dts);

        end_ebml_master(pb, mkv->cluster);

        mkv->cluster_pos = 0;

        if (mkv->dyn_bc)

            mkv_flush_dynbuf(s);

    }



    // check if we have an audio packet cached

    if (mkv->cur_audio_pkt.size > 0) {

        ret = mkv_write_packet_internal(s, &mkv->cur_audio_pkt);

        av_free_packet(&mkv->cur_audio_pkt);

        if (ret < 0) {

            av_log(s, AV_LOG_ERROR, "Could not write cached audio packet ret:%d\n", ret);

            return ret;

        }

    }



    // buffer an audio packet to ensure the packet containing the video

    // keyframe's timecode is contained in the same cluster for WebM

    if (codec_type == AVMEDIA_TYPE_AUDIO) {

        mkv->cur_audio_pkt = *pkt;

        if (pkt->buf) {

            mkv->cur_audio_pkt.buf = av_buffer_ref(pkt->buf);

            ret = mkv->cur_audio_pkt.buf ? 0 : AVERROR(ENOMEM);

        } else

            ret = av_dup_packet(&mkv->cur_audio_pkt);

    } else

        ret = mkv_write_packet_internal(s, pkt);

    return ret;

}

int av_open_input_stream(AVFormatContext **ic_ptr,

                         AVIOContext *pb, const char *filename,

                         AVInputFormat *fmt, AVFormatParameters *ap)

{

    int err;

    AVDictionary *opts;

    AVFormatContext *ic;

    AVFormatParameters default_ap;



    if(!ap){

        ap=&default_ap;

        memset(ap, 0, sizeof(default_ap));

    }

    opts = convert_format_parameters(ap);



    if(!ap->prealloced_context)

        ic = avformat_alloc_context();

    else

        ic = *ic_ptr;

    if (!ic) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    if (pb && fmt && fmt->flags & AVFMT_NOFILE)

        av_log(ic, AV_LOG_WARNING, "Custom AVIOContext makes no sense and "

                                   "will be ignored with AVFMT_NOFILE format.\n");

    else

        ic->pb = pb;



    err = avformat_open_input(&ic, filename, fmt, &opts);

    ic->pb = ic->pb ? ic->pb : pb; // don't leak custom pb if it wasn't set above



    *ic_ptr = ic;

fail:

    av_dict_free(&opts);

    return err;

}

static void do_subtitle_out(AVFormatContext *s,

                            OutputStream *ost,

                            InputStream *ist,

                            AVSubtitle *sub)

{

    int subtitle_out_max_size = 1024 * 1024;

    int subtitle_out_size, nb, i;

    AVCodecContext *enc;

    AVPacket pkt;

    int64_t pts;



    if (sub->pts == AV_NOPTS_VALUE) {

        av_log(NULL, AV_LOG_ERROR, "Subtitle packets must have a pts\n");

        if (exit_on_error)

            exit_program(1);

        return;

    }



    enc = ost->enc_ctx;



    if (!subtitle_out) {

        subtitle_out = av_malloc(subtitle_out_max_size);

        if (!subtitle_out) {

            av_log(NULL, AV_LOG_FATAL, "Failed to allocate subtitle_out\n");

            exit_program(1);

        }

    }



    /* Note: DVB subtitle need one packet to draw them and one other

       packet to clear them */

    /* XXX: signal it in the codec context ? */

    if (enc->codec_id == AV_CODEC_ID_DVB_SUBTITLE)

        nb = 2;

    else

        nb = 1;



    /* shift timestamp to honor -ss and make check_recording_time() work with -t */

    pts = sub->pts;

    if (output_files[ost->file_index]->start_time != AV_NOPTS_VALUE)

        pts -= output_files[ost->file_index]->start_time;

    for (i = 0; i < nb; i++) {

        unsigned save_num_rects = sub->num_rects;



        ost->sync_opts = av_rescale_q(pts, AV_TIME_BASE_Q, enc->time_base);

        if (!check_recording_time(ost))

            return;



        sub->pts = pts;

        // start_display_time is required to be 0

        sub->pts               += av_rescale_q(sub->start_display_time, (AVRational){ 1, 1000 }, AV_TIME_BASE_Q);

        sub->end_display_time  -= sub->start_display_time;

        sub->start_display_time = 0;

        if (i == 1)

            sub->num_rects = 0;



        ost->frames_encoded++;



        subtitle_out_size = avcodec_encode_subtitle(enc, subtitle_out,

                                                    subtitle_out_max_size, sub);

        if (i == 1)

            sub->num_rects = save_num_rects;

        if (subtitle_out_size < 0) {

            av_log(NULL, AV_LOG_FATAL, "Subtitle encoding failed\n");

            exit_program(1);

        }



        av_init_packet(&pkt);

        pkt.data = subtitle_out;

        pkt.size = subtitle_out_size;

        pkt.pts  = av_rescale_q(sub->pts, AV_TIME_BASE_Q, ost->st->time_base);

        pkt.duration = av_rescale_q(sub->end_display_time, (AVRational){ 1, 1000 }, ost->st->time_base);

        if (enc->codec_id == AV_CODEC_ID_DVB_SUBTITLE) {

            /* XXX: the pts correction is handled here. Maybe handling

               it in the codec would be better */

            if (i == 0)

                pkt.pts += 90 * sub->start_display_time;

            else

                pkt.pts += 90 * sub->end_display_time;

        }

        pkt.dts = pkt.pts;

        write_frame(s, &pkt, ost);

    }

}

static void mct_decode(Jpeg2000DecoderContext *s, Jpeg2000Tile *tile)
{
    int i, csize = 1;
    int32_t *src[3],  i0,  i1,  i2;
    float   *srcf[3], i0f, i1f, i2f;
    for (i = 0; i < 3; i++)
        if (tile->codsty[0].transform == FF_DWT97)
            srcf[i] = tile->comp[i].f_data;
        else
            src [i] = tile->comp[i].i_data;
    for (i = 0; i < 2; i++)
        csize *= tile->comp[0].coord[i][1] - tile->comp[0].coord[i][0];
    switch (tile->codsty[0].transform) {
    case FF_DWT97:
        for (i = 0; i < csize; i++) {
            i0f = *srcf[0] + (f_ict_params[0] * *srcf[2]);
            i1f = *srcf[0] - (f_ict_params[1] * *srcf[1])
                           - (f_ict_params[2] * *srcf[2]);
            i2f = *srcf[0] + (f_ict_params[3] * *srcf[1]);
            *srcf[0]++ = i0f;
            *srcf[1]++ = i1f;
            *srcf[2]++ = i2f;
        break;
    case FF_DWT97_INT:
        for (i = 0; i < csize; i++) {
            i0 = *src[0] + (((i_ict_params[0] * *src[2]) + (1 << 15)) >> 16);
            i1 = *src[0] - (((i_ict_params[1] * *src[1]) + (1 << 15)) >> 16)
                         - (((i_ict_params[2] * *src[2]) + (1 << 15)) >> 16);
            i2 = *src[0] + (((i_ict_params[3] * *src[1]) + (1 << 15)) >> 16);
            *src[0]++ = i0;
            *src[1]++ = i1;
            *src[2]++ = i2;
        break;
    case FF_DWT53:
        for (i = 0; i < csize; i++) {
            i1 = *src[0] - (*src[2] + *src[1] >> 2);
            i0 = i1 + *src[2];
            i2 = i1 + *src[1];
            *src[0]++ = i0;
            *src[1]++ = i1;
            *src[2]++ = i2;
        break;

