static int vnc_update_stats(VncDisplay *vd,  struct timeval * tv)

{

    int width = pixman_image_get_width(vd->guest.fb);

    int height = pixman_image_get_height(vd->guest.fb);

    int x, y;

    struct timeval res;

    int has_dirty = 0;



    for (y = 0; y < height; y += VNC_STAT_RECT) {

        for (x = 0; x < width; x += VNC_STAT_RECT) {

            VncRectStat *rect = vnc_stat_rect(vd, x, y);



            rect->updated = false;

        }

    }



    qemu_timersub(tv, &VNC_REFRESH_STATS, &res);



    if (timercmp(&vd->guest.last_freq_check, &res, >)) {

        return has_dirty;

    }

    vd->guest.last_freq_check = *tv;



    for (y = 0; y < height; y += VNC_STAT_RECT) {

        for (x = 0; x < width; x += VNC_STAT_RECT) {

            VncRectStat *rect= vnc_stat_rect(vd, x, y);

            int count = ARRAY_SIZE(rect->times);

            struct timeval min, max;



            if (!timerisset(&rect->times[count - 1])) {

                continue ;

            }



            max = rect->times[(rect->idx + count - 1) % count];

            qemu_timersub(tv, &max, &res);



            if (timercmp(&res, &VNC_REFRESH_LOSSY, >)) {

                rect->freq = 0;

                has_dirty += vnc_refresh_lossy_rect(vd, x, y);

                memset(rect->times, 0, sizeof (rect->times));

                continue ;

            }



            min = rect->times[rect->idx];

            max = rect->times[(rect->idx + count - 1) % count];

            qemu_timersub(&max, &min, &res);



            rect->freq = res.tv_sec + res.tv_usec / 1000000.;

            rect->freq /= count;

            rect->freq = 1. / rect->freq;

        }

    }

    return has_dirty;

}

static int qxl_init_common(PCIQXLDevice *qxl)

{

    uint8_t* config = qxl->pci.config;

    uint32_t pci_device_rev;

    uint32_t io_size;



    qxl->mode = QXL_MODE_UNDEFINED;

    qxl->generation = 1;

    qxl->num_memslots = NUM_MEMSLOTS;

    qemu_mutex_init(&qxl->track_lock);

    qemu_mutex_init(&qxl->async_lock);

    qxl->current_async = QXL_UNDEFINED_IO;

    qxl->guest_bug = 0;



    switch (qxl->revision) {

    case 1: /* spice 0.4 -- qxl-1 */

        pci_device_rev = QXL_REVISION_STABLE_V04;

        io_size = 8;

        break;

    case 2: /* spice 0.6 -- qxl-2 */

        pci_device_rev = QXL_REVISION_STABLE_V06;

        io_size = 16;

        break;

    case 3: /* qxl-3 */

        pci_device_rev = QXL_REVISION_STABLE_V10;

        io_size = 32; /* PCI region size must be pow2 */

        break;

/* 0x000b01 == 0.11.1 */

#if SPICE_SERVER_VERSION >= 0x000b01 && \

        defined(CONFIG_QXL_IO_MONITORS_CONFIG_ASYNC)

    case 4: /* qxl-4 */

        pci_device_rev = QXL_REVISION_STABLE_V12;

        io_size = msb_mask(QXL_IO_RANGE_SIZE * 2 - 1);

        break;

#endif

    default:

        error_report("Invalid revision %d for qxl device (max %d)",

                     qxl->revision, QXL_DEFAULT_REVISION);

        return -1;

    }



    pci_set_byte(&config[PCI_REVISION_ID], pci_device_rev);

    pci_set_byte(&config[PCI_INTERRUPT_PIN], 1);



    qxl->rom_size = qxl_rom_size();

    memory_region_init_ram(&qxl->rom_bar, "qxl.vrom", qxl->rom_size);

    vmstate_register_ram(&qxl->rom_bar, &qxl->pci.qdev);

    init_qxl_rom(qxl);

    init_qxl_ram(qxl);



    qxl->guest_surfaces.cmds = g_new0(QXLPHYSICAL, qxl->ssd.num_surfaces);

    memory_region_init_ram(&qxl->vram_bar, "qxl.vram", qxl->vram_size);

    vmstate_register_ram(&qxl->vram_bar, &qxl->pci.qdev);

    memory_region_init_alias(&qxl->vram32_bar, "qxl.vram32", &qxl->vram_bar,

                             0, qxl->vram32_size);



    memory_region_init_io(&qxl->io_bar, &qxl_io_ops, qxl,

                          "qxl-ioports", io_size);

    if (qxl->id == 0) {

        vga_dirty_log_start(&qxl->vga);

    }

    memory_region_set_flush_coalesced(&qxl->io_bar);





    pci_register_bar(&qxl->pci, QXL_IO_RANGE_INDEX,

                     PCI_BASE_ADDRESS_SPACE_IO, &qxl->io_bar);



    pci_register_bar(&qxl->pci, QXL_ROM_RANGE_INDEX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &qxl->rom_bar);



    pci_register_bar(&qxl->pci, QXL_RAM_RANGE_INDEX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &qxl->vga.vram);



    pci_register_bar(&qxl->pci, QXL_VRAM_RANGE_INDEX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &qxl->vram32_bar);



    if (qxl->vram32_size < qxl->vram_size) {

        /*

         * Make the 64bit vram bar show up only in case it is

         * configured to be larger than the 32bit vram bar.

         */

        pci_register_bar(&qxl->pci, QXL_VRAM64_RANGE_INDEX,

                         PCI_BASE_ADDRESS_SPACE_MEMORY |

                         PCI_BASE_ADDRESS_MEM_TYPE_64 |

                         PCI_BASE_ADDRESS_MEM_PREFETCH,

                         &qxl->vram_bar);

    }



    /* print pci bar details */

    dprint(qxl, 1, "ram/%s: %d MB [region 0]\n",

           qxl->id == 0 ? "pri" : "sec",

           qxl->vga.vram_size / (1024*1024));

    dprint(qxl, 1, "vram/32: %d MB [region 1]\n",

           qxl->vram32_size / (1024*1024));

    dprint(qxl, 1, "vram/64: %d MB %s\n",

           qxl->vram_size / (1024*1024),

           qxl->vram32_size < qxl->vram_size ? "[region 4]" : "[unmapped]");



    qxl->ssd.qxl.base.sif = &qxl_interface.base;

    qxl->ssd.qxl.id = qxl->id;

    qemu_spice_add_interface(&qxl->ssd.qxl.base);

    qemu_add_vm_change_state_handler(qxl_vm_change_state_handler, qxl);



    init_pipe_signaling(qxl);

    qxl_reset_state(qxl);



    qxl->update_area_bh = qemu_bh_new(qxl_render_update_area_bh, qxl);



    return 0;

}

static void qemu_wait_io_event(CPUState *env)

{

    while (!tcg_has_work())

        qemu_cond_timedwait(env->halt_cond, &qemu_global_mutex, 1000);



    qemu_mutex_unlock(&qemu_global_mutex);



    /*

     * Users of qemu_global_mutex can be starved, having no chance

     * to acquire it since this path will get to it first.

     * So use another lock to provide fairness.

     */

    qemu_mutex_lock(&qemu_fair_mutex);

    qemu_mutex_unlock(&qemu_fair_mutex);



    qemu_mutex_lock(&qemu_global_mutex);

    qemu_wait_io_event_common(env);

}

uint64_t HELPER(neon_sub_saturate_s64)(uint64_t src1, uint64_t src2)

{

    uint64_t res;



    res = src1 - src2;

    if (((res ^ src1) & SIGNBIT64) && ((src1 ^ src2) & SIGNBIT64)) {

        env->QF = 1;

        res = ((int64_t)src1 >> 63) ^ ~SIGNBIT64;

    }

    return res;

}

void pci_default_write_config(PCIDevice *d, uint32_t addr, uint32_t val, int l)

{

    int i, was_irq_disabled = pci_irq_disabled(d);

    uint32_t config_size = pci_config_size(d);



    for (i = 0; i < l && addr + i < config_size; val >>= 8, ++i) {

        uint8_t wmask = d->wmask[addr + i];

        uint8_t w1cmask = d->w1cmask[addr + i];

        assert(!(wmask & w1cmask));

        d->config[addr + i] = (d->config[addr + i] & ~wmask) | (val & wmask);

        d->config[addr + i] &= ~(val & w1cmask); /* W1C: Write 1 to Clear */

    }

    if (ranges_overlap(addr, l, PCI_BASE_ADDRESS_0, 24) ||

        ranges_overlap(addr, l, PCI_ROM_ADDRESS, 4) ||

        ranges_overlap(addr, l, PCI_ROM_ADDRESS1, 4) ||

        range_covers_byte(addr, l, PCI_COMMAND))

        pci_update_mappings(d);



    if (range_covers_byte(addr, l, PCI_COMMAND))

        pci_update_irq_disabled(d, was_irq_disabled);

}

static void mb_add_mod(MultibootState *s,

                       target_phys_addr_t start, target_phys_addr_t end,

                       target_phys_addr_t cmdline_phys)

{

    char *p;

    assert(s->mb_mods_count < s->mb_mods_avail);



    p = (char *)s->mb_buf + s->offset_mbinfo + MB_MOD_SIZE * s->mb_mods_count;



    stl_p(p + MB_MOD_START,   start);

    stl_p(p + MB_MOD_END,     end);

    stl_p(p + MB_MOD_CMDLINE, cmdline_phys);



    mb_debug("mod%02d: "TARGET_FMT_plx" - "TARGET_FMT_plx"\n",

             s->mb_mods_count, start, end);



    s->mb_mods_count++;

}

static void mpeg_decode_sequence_extension(Mpeg1Context *s1)

{

    MpegEncContext *s = &s1->mpeg_enc_ctx;

    int horiz_size_ext, vert_size_ext;

    int bit_rate_ext;



    skip_bits(&s->gb, 1); /* profile and level esc*/

    s->avctx->profile       = get_bits(&s->gb, 3);

    s->avctx->level         = get_bits(&s->gb, 4);

    s->progressive_sequence = get_bits1(&s->gb);   /* progressive_sequence */

    s->chroma_format        = get_bits(&s->gb, 2); /* chroma_format 1=420, 2=422, 3=444 */



    if (!s->chroma_format) {

        s->chroma_format = 1;

        av_log(s->avctx, AV_LOG_WARNING, "Chroma format invalid\n");

    }



    horiz_size_ext          = get_bits(&s->gb, 2);

    vert_size_ext           = get_bits(&s->gb, 2);

    s->width  |= (horiz_size_ext << 12);

    s->height |= (vert_size_ext  << 12);

    bit_rate_ext = get_bits(&s->gb, 12);  /* XXX: handle it */

    s->bit_rate += (bit_rate_ext << 18) * 400;

    check_marker(&s->gb, "after bit rate extension");

    s->avctx->rc_buffer_size += get_bits(&s->gb, 8) * 1024 * 16 << 10;



    s->low_delay = get_bits1(&s->gb);

    if (s->avctx->flags & AV_CODEC_FLAG_LOW_DELAY)

        s->low_delay = 1;



    s1->frame_rate_ext.num = get_bits(&s->gb, 2) + 1;

    s1->frame_rate_ext.den = get_bits(&s->gb, 5) + 1;



    ff_dlog(s->avctx, "sequence extension\n");

    s->codec_id = s->avctx->codec_id = AV_CODEC_ID_MPEG2VIDEO;



    if (s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_DEBUG,

               "profile: %d, level: %d ps: %d cf:%d vbv buffer: %d, bitrate:%"PRId64"\n",

               s->avctx->profile, s->avctx->level, s->progressive_sequence, s->chroma_format,

               s->avctx->rc_buffer_size, s->bit_rate);

}

static const uint8_t *pcx_rle_decode(const uint8_t *src, uint8_t *dst,

                                     unsigned int bytes_per_scanline,

                                     int compressed)

{

    unsigned int i = 0;

    unsigned char run, value;



    if (compressed) {

        while (i < bytes_per_scanline) {

            run   = 1;

            value = *src++;

            if (value >= 0xc0) {

                run   = value & 0x3f;

                value = *src++;

            }

            while (i < bytes_per_scanline && run--)

                dst[i++] = value;

        }

    } else {

        memcpy(dst, src, bytes_per_scanline);

        src += bytes_per_scanline;

    }



    return src;

}

static int smacker_decode_header_tree(SmackVContext *smk, GetBitContext *gb, int **recodes, int *last, int size)

{

    int res;

    HuffContext huff;

    HuffContext tmp1, tmp2;

    VLC vlc[2] = { { 0 } };

    int escapes[3];

    DBCtx ctx;

    int err = 0;



    if(size >= UINT_MAX>>4){ // (((size + 3) >> 2) + 3) << 2 must not overflow

        av_log(smk->avctx, AV_LOG_ERROR, "size too large\n");

        return AVERROR_INVALIDDATA;

    }



    tmp1.length = 256;

    tmp1.maxlength = 0;

    tmp1.current = 0;

    tmp1.bits = av_mallocz(256 * 4);

    tmp1.lengths = av_mallocz(256 * sizeof(int));

    tmp1.values = av_mallocz(256 * sizeof(int));



    tmp2.length = 256;

    tmp2.maxlength = 0;

    tmp2.current = 0;

    tmp2.bits = av_mallocz(256 * 4);

    tmp2.lengths = av_mallocz(256 * sizeof(int));

    tmp2.values = av_mallocz(256 * sizeof(int));



    if(get_bits1(gb)) {

        smacker_decode_tree(gb, &tmp1, 0, 0);

        skip_bits1(gb);

        if(tmp1.current > 1) {

            res = init_vlc(&vlc[0], SMKTREE_BITS, tmp1.length,

                        tmp1.lengths, sizeof(int), sizeof(int),

                        tmp1.bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

            if(res < 0) {

                av_log(smk->avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

                return AVERROR_INVALIDDATA;

            }

        }

    }

    if (!vlc[0].table) {

        av_log(smk->avctx, AV_LOG_ERROR, "Skipping low bytes tree\n");

    }

    if(get_bits1(gb)){

        smacker_decode_tree(gb, &tmp2, 0, 0);

        skip_bits1(gb);

        if(tmp2.current > 1) {

            res = init_vlc(&vlc[1], SMKTREE_BITS, tmp2.length,

                        tmp2.lengths, sizeof(int), sizeof(int),

                        tmp2.bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

            if(res < 0) {

                av_log(smk->avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

                return AVERROR_INVALIDDATA;

            }

        }

    }

    if (!vlc[1].table) {

        av_log(smk->avctx, AV_LOG_ERROR, "Skipping high bytes tree\n");

    }



    escapes[0]  = get_bits(gb, 16);

    escapes[1]  = get_bits(gb, 16);

    escapes[2]  = get_bits(gb, 16);



    last[0] = last[1] = last[2] = -1;



    ctx.escapes[0] = escapes[0];

    ctx.escapes[1] = escapes[1];

    ctx.escapes[2] = escapes[2];

    ctx.v1 = &vlc[0];

    ctx.v2 = &vlc[1];

    ctx.recode1 = tmp1.values;

    ctx.recode2 = tmp2.values;

    ctx.last = last;



    huff.length = ((size + 3) >> 2) + 3;

    huff.maxlength = 0;

    huff.current = 0;

    huff.values = av_mallocz(huff.length * sizeof(int));



    if (smacker_decode_bigtree(gb, &huff, &ctx) < 0)

        err = -1;

    skip_bits1(gb);

    if(ctx.last[0] == -1) ctx.last[0] = huff.current++;

    if(ctx.last[1] == -1) ctx.last[1] = huff.current++;

    if(ctx.last[2] == -1) ctx.last[2] = huff.current++;

    if(huff.current > huff.length){

        ctx.last[0] = ctx.last[1] = ctx.last[2] = 1;

        av_log(smk->avctx, AV_LOG_ERROR, "bigtree damaged\n");

        return AVERROR_INVALIDDATA;

    }



    *recodes = huff.values;



    if(vlc[0].table)

        ff_free_vlc(&vlc[0]);

    if(vlc[1].table)

        ff_free_vlc(&vlc[1]);

    av_free(tmp1.bits);

    av_free(tmp1.lengths);

    av_free(tmp1.values);

    av_free(tmp2.bits);

    av_free(tmp2.lengths);

    av_free(tmp2.values);



    return err;

}

void pci_default_write_config(PCIDevice *d, 

                              uint32_t address, uint32_t val, int len)

{

    int can_write, i;

    uint32_t end, addr;



    if (len == 4 && ((address >= 0x10 && address < 0x10 + 4 * 6) || 

                     (address >= 0x30 && address < 0x34))) {

        PCIIORegion *r;

        int reg;



        if ( address >= 0x30 ) {

            reg = PCI_ROM_SLOT;

        }else{

            reg = (address - 0x10) >> 2;

        }

        r = &d->io_regions[reg];

        if (r->size == 0)

            goto default_config;

        /* compute the stored value */

        if (reg == PCI_ROM_SLOT) {

            /* keep ROM enable bit */

            val &= (~(r->size - 1)) | 1;

        } else {

            val &= ~(r->size - 1);

            val |= r->type;

        }

        *(uint32_t *)(d->config + address) = cpu_to_le32(val);

        pci_update_mappings(d);

        return;

    }

 default_config:

    /* not efficient, but simple */

    addr = address;

    for(i = 0; i < len; i++) {

        /* default read/write accesses */

        switch(d->config[0x0e]) {

        case 0x00:

        case 0x80:

            switch(addr) {

            case 0x00:

            case 0x01:

            case 0x02:

            case 0x03:

            case 0x08:

            case 0x09:

            case 0x0a:

            case 0x0b:

            case 0x0e:

            case 0x10 ... 0x27: /* base */

            case 0x30 ... 0x33: /* rom */

            case 0x3d:

                can_write = 0;

                break;

            default:

                can_write = 1;

                break;

            }

            break;

        default:

        case 0x01:

            switch(addr) {

            case 0x00:

            case 0x01:

            case 0x02:

            case 0x03:

            case 0x08:

            case 0x09:

            case 0x0a:

            case 0x0b:

            case 0x0e:

            case 0x38 ... 0x3b: /* rom */

            case 0x3d:

                can_write = 0;

                break;

            default:

                can_write = 1;

                break;

            }

            break;

        }

        if (can_write) {

            d->config[addr] = val;

        }

        addr++;

        val >>= 8;

    }



    end = address + len;

    if (end > PCI_COMMAND && address < (PCI_COMMAND + 2)) {

        /* if the command register is modified, we must modify the mappings */

        pci_update_mappings(d);

    }

}

static inline void FUNC(idctSparseCol_extrashift)(int16_t *col)

#else

static inline void FUNC(idctSparseColPut)(pixel *dest, int line_size,

                                          int16_t *col)

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



    IDCT_COLS;



    dest[0] = av_clip_pixel((a0 + b0) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a1 + b1) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a2 + b2) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a3 + b3) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a3 - b3) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a2 - b2) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a1 - b1) >> COL_SHIFT);

    dest += line_size;

    dest[0] = av_clip_pixel((a0 - b0) >> COL_SHIFT);

}



static inline void FUNC(idctSparseColAdd)(pixel *dest, int line_size,

                                          int16_t *col)

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



    IDCT_COLS;



    dest[0] = av_clip_pixel(dest[0] + ((a0 + b0) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a1 + b1) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a2 + b2) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a3 + b3) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a3 - b3) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a2 - b2) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a1 - b1) >> COL_SHIFT));

    dest += line_size;

    dest[0] = av_clip_pixel(dest[0] + ((a0 - b0) >> COL_SHIFT));

}



static inline void FUNC(idctSparseCol)(int16_t *col)

#endif

{

    int a0, a1, a2, a3, b0, b1, b2, b3;



    IDCT_COLS;



    col[0 ] = ((a0 + b0) >> COL_SHIFT);

    col[8 ] = ((a1 + b1) >> COL_SHIFT);

    col[16] = ((a2 + b2) >> COL_SHIFT);

    col[24] = ((a3 + b3) >> COL_SHIFT);

    col[32] = ((a3 - b3) >> COL_SHIFT);

    col[40] = ((a2 - b2) >> COL_SHIFT);

    col[48] = ((a1 - b1) >> COL_SHIFT);

    col[56] = ((a0 - b0) >> COL_SHIFT);

}

static void vmxnet3_process_tx_queue(VMXNET3State *s, int qidx)

{

    struct Vmxnet3_TxDesc txd;

    uint32_t txd_idx;

    uint32_t data_len;

    hwaddr data_pa;



    for (;;) {

        if (!vmxnet3_pop_next_tx_descr(s, qidx, &txd, &txd_idx)) {

            break;

        }



        vmxnet3_dump_tx_descr(&txd);



        if (!s->skip_current_tx_pkt) {

            data_len = (txd.len > 0) ? txd.len : VMXNET3_MAX_TX_BUF_SIZE;

            data_pa = le64_to_cpu(txd.addr);



            if (!net_tx_pkt_add_raw_fragment(s->tx_pkt,

                                                data_pa,

                                                data_len)) {

                s->skip_current_tx_pkt = true;

            }

        }



        if (s->tx_sop) {

            vmxnet3_tx_retrieve_metadata(s, &txd);

            s->tx_sop = false;

        }



        if (txd.eop) {

            if (!s->skip_current_tx_pkt && net_tx_pkt_parse(s->tx_pkt)) {

                if (s->needs_vlan) {

                    net_tx_pkt_setup_vlan_header(s->tx_pkt, s->tci);

                }



                vmxnet3_send_packet(s, qidx);

            } else {

                vmxnet3_on_tx_done_update_stats(s, qidx,

                                                VMXNET3_PKT_STATUS_ERROR);

            }



            vmxnet3_complete_packet(s, qidx, txd_idx);

            s->tx_sop = true;

            s->skip_current_tx_pkt = false;

            net_tx_pkt_reset(s->tx_pkt);

        }

    }

}

static int vmdk_write(BlockDriverState *bs, int64_t sector_num, 

                     const uint8_t *buf, int nb_sectors)

{

    BDRVVmdkState *s = bs->opaque;

    int index_in_cluster, n;

    uint64_t cluster_offset;

    static int cid_update = 0;



    while (nb_sectors > 0) {

        index_in_cluster = sector_num & (s->cluster_sectors - 1);

        n = s->cluster_sectors - index_in_cluster;

        if (n > nb_sectors)

            n = nb_sectors;

        cluster_offset = get_cluster_offset(bs, sector_num << 9, 1);

        if (!cluster_offset)

            return -1;

        if (bdrv_pwrite(s->hd, cluster_offset + index_in_cluster * 512, buf, n * 512) != n * 512)

            return -1;

        nb_sectors -= n;

        sector_num += n;

        buf += n * 512;



        // update CID on the first write every time the virtual disk is opened

        if (!cid_update) {

            vmdk_write_cid(bs, time(NULL));

            cid_update++;

        }

    }

    return 0;

}

void migrate_fd_error(MigrationState *s)

{

    DPRINTF("setting error state\n");

    s->state = MIG_STATE_ERROR;

    notifier_list_notify(&migration_state_notifiers, s);

    migrate_fd_cleanup(s);

}

static int is_intra_more_likely(ERContext *s)

{

    int is_intra_likely, i, j, undamaged_count, skip_amount, mb_x, mb_y;



    if (!s->last_pic.f || !s->last_pic.f->data[0])

        return 1; // no previous frame available -> use spatial prediction



    undamaged_count = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        const int error = s->error_status_table[mb_xy];

        if (!((error & ER_DC_ERROR) && (error & ER_MV_ERROR)))

            undamaged_count++;

    }



    if (s->avctx->codec_id == AV_CODEC_ID_H264 && s->ref_count <= 0)

        return 1;



    if (undamaged_count < 5)

        return 0; // almost all MBs damaged -> use temporal prediction



#if FF_API_XVMC

FF_DISABLE_DEPRECATION_WARNINGS

    // prevent dsp.sad() check, that requires access to the image

    if (CONFIG_MPEG_XVMC_DECODER    &&

        s->avctx->xvmc_acceleration &&

        s->cur_pic.f->pict_type == AV_PICTURE_TYPE_I)

        return 1;

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */



    skip_amount     = FFMAX(undamaged_count / 50, 1); // check only up to 50 MBs

    is_intra_likely = 0;



    j = 0;

    for (mb_y = 0; mb_y < s->mb_height - 1; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            int error;

            const int mb_xy = mb_x + mb_y * s->mb_stride;



            error = s->error_status_table[mb_xy];

            if ((error & ER_DC_ERROR) && (error & ER_MV_ERROR))

                continue; // skip damaged



            j++;

            // skip a few to speed things up

            if ((j % skip_amount) != 0)

                continue;



            if (s->cur_pic.f->pict_type == AV_PICTURE_TYPE_I) {

                int *linesize = s->cur_pic.f->linesize;

                uint8_t *mb_ptr      = s->cur_pic.f->data[0] +

                                       mb_x * 16 + mb_y * 16 * linesize[0];

                uint8_t *last_mb_ptr = s->last_pic.f->data[0] +

                                       mb_x * 16 + mb_y * 16 * linesize[0];



                if (s->avctx->codec_id == AV_CODEC_ID_H264) {

                    // FIXME

                } else {

                    ff_thread_await_progress(s->last_pic.tf, mb_y, 0);

                }

                is_intra_likely += s->mecc->sad[0](NULL, last_mb_ptr, mb_ptr,

                                                   linesize[0], 16);

                is_intra_likely -= s->mecc->sad[0](NULL, last_mb_ptr,

                                                   last_mb_ptr + linesize[0] * 16,

                                                   linesize[0], 16);

            } else {

                if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

                   is_intra_likely++;

                else

                   is_intra_likely--;

            }

        }

    }

    return is_intra_likely > 0;

}

static inline PageDesc *page_find(target_ulong index)

{

    PageDesc *p;



    p = l1_map[index >> L2_BITS];

    if (!p)

        return 0;

    return p + (index & (L2_SIZE - 1));

}

static void xilinx_spips_reset(DeviceState *d)

{

    XilinxSPIPS *s = XILINX_SPIPS(d);



    int i;

    for (i = 0; i < XLNX_SPIPS_R_MAX; i++) {

        s->regs[i] = 0;

    }



    fifo8_reset(&s->rx_fifo);

    fifo8_reset(&s->rx_fifo);

    /* non zero resets */

    s->regs[R_CONFIG] |= MODEFAIL_GEN_EN;

    s->regs[R_SLAVE_IDLE_COUNT] = 0xFF;

    s->regs[R_TX_THRES] = 1;

    s->regs[R_RX_THRES] = 1;

    /* FIXME: move magic number definition somewhere sensible */

    s->regs[R_MOD_ID] = 0x01090106;

    s->regs[R_LQSPI_CFG] = R_LQSPI_CFG_RESET;

    s->link_state = 1;

    s->link_state_next = 1;

    s->link_state_next_when = 0;

    s->snoop_state = SNOOP_CHECKING;

    s->cmd_dummies = 0;

    s->man_start_com = false;

    xilinx_spips_update_ixr(s);

    xilinx_spips_update_cs_lines(s);

}

static inline void RENAME(yuv2yuvX_ar)(SwsContext *c, const int16_t *lumFilter,

                                       const int16_t **lumSrc, int lumFilterSize,

                                       const int16_t *chrFilter, const int16_t **chrUSrc,

                                       const int16_t **chrVSrc,

                                       int chrFilterSize, const int16_t **alpSrc,

                                       uint8_t *dest, uint8_t *uDest, uint8_t *vDest,

                                       uint8_t *aDest, long dstW, long chrDstW)

{

    if (uDest) {

        YSCALEYUV2YV12X_ACCURATE(CHR_MMX_FILTER_OFFSET, uDest, chrDstW, 0)

        YSCALEYUV2YV12X_ACCURATE(CHR_MMX_FILTER_OFFSET, vDest, chrDstW + c->uv_off, c->uv_off)

    }

    if (CONFIG_SWSCALE_ALPHA && aDest) {

        YSCALEYUV2YV12X_ACCURATE(ALP_MMX_FILTER_OFFSET, aDest, dstW, 0)

    }



    YSCALEYUV2YV12X_ACCURATE(LUM_MMX_FILTER_OFFSET, dest, dstW, 0)

}

static int init(AVFilterContext *ctx, const char *args)

{

    EvalContext *eval = ctx->priv;

    char *args1 = av_strdup(eval->exprs);

    char *expr, *buf;

    int ret, i;



    if (!args1) {

        av_log(ctx, AV_LOG_ERROR, "Channels expressions list is empty\n");

        ret = args ? AVERROR(ENOMEM) : AVERROR(EINVAL);

        goto end;

    }



    /* parse expressions */

    buf = args1;

    i = 0;

    while (i < FF_ARRAY_ELEMS(eval->expr) && (expr = av_strtok(buf, "|", &buf))) {

        ret = av_expr_parse(&eval->expr[i], expr, var_names,

                            NULL, NULL, NULL, NULL, 0, ctx);

        if (ret < 0)

            goto end;

        i++;

    }

    eval->nb_channels = i;



    if (eval->chlayout_str) {

        int n;

        ret = ff_parse_channel_layout(&eval->chlayout, eval->chlayout_str, ctx);

        if (ret < 0)

            goto end;



        n = av_get_channel_layout_nb_channels(eval->chlayout);

        if (n != eval->nb_channels) {

            av_log(ctx, AV_LOG_ERROR,

                   "Mismatch between the specified number of channels '%d' "

                   "and the number of channels '%d' in the specified channel layout '%s'\n",

                   eval->nb_channels, n, eval->chlayout_str);

            ret = AVERROR(EINVAL);

            goto end;

        }

    } else {

        /* guess channel layout from nb expressions/channels */

        eval->chlayout = av_get_default_channel_layout(eval->nb_channels);

        if (!eval->chlayout) {

            av_log(ctx, AV_LOG_ERROR, "Invalid number of channels '%d' provided\n",

                   eval->nb_channels);

            ret = AVERROR(EINVAL);

            goto end;

        }

    }



    if ((ret = ff_parse_sample_rate(&eval->sample_rate, eval->sample_rate_str, ctx)))

        goto end;



    eval->duration = -1;

    if (eval->duration_str) {

        int64_t us = -1;

        if ((ret = av_parse_time(&us, eval->duration_str, 1)) < 0) {

            av_log(ctx, AV_LOG_ERROR, "Invalid duration: '%s'\n", eval->duration_str);

            goto end;

        }

        eval->duration = (double)us / 1000000;

    }

    eval->n = 0;



end:

    av_free(args1);

    return ret;

}

