}

uint32_t HELPER(get_cp15)(CPUARMState *env, uint32_t insn)

{

    int op1;

    int op2;

    int crm;



    op1 = (insn >> 21) & 7;

    op2 = (insn >> 5) & 7;

    crm = insn & 0xf;

    switch ((insn >> 16) & 0xf) {

    case 0: /* ID codes.  */

        switch (op1) {

        case 0:

            switch (crm) {

            case 0:

                switch (op2) {

                case 0: /* Device ID.  */

                    return env->cp15.c0_cpuid;

                case 1: /* Cache Type.  */

		    return env->cp15.c0_cachetype;

                case 2: /* TCM status.  */

                    return 0;

                case 3: /* TLB type register.  */

                    return 0; /* No lockable TLB entries.  */

                case 5: /* MPIDR */

                    /* The MPIDR was standardised in v7; prior to

                     * this it was implemented only in the 11MPCore.

                     * For all other pre-v7 cores it does not exist.

                     */

                    if (arm_feature(env, ARM_FEATURE_V7) ||

                        ARM_CPUID(env) == ARM_CPUID_ARM11MPCORE) {

                        int mpidr = env->cpu_index;

                        /* We don't support setting cluster ID ([8..11])

                         * so these bits always RAZ.

                         */

                        if (arm_feature(env, ARM_FEATURE_V7MP)) {

                            mpidr |= (1 << 31);

                            /* Cores which are uniprocessor (non-coherent)

                             * but still implement the MP extensions set

                             * bit 30. (For instance, A9UP.) However we do

                             * not currently model any of those cores.

                             */

                        }

                        return mpidr;

                    }

                    /* otherwise fall through to the unimplemented-reg case */

                default:

                    goto bad_reg;

                }

            case 3: case 4: case 5: case 6: case 7:

                return 0;

            default:

                goto bad_reg;

            }

        default:

            goto bad_reg;

        }

    case 4: /* Reserved.  */

        goto bad_reg;

    case 11: /* TCM DMA control.  */

    case 12: /* Reserved.  */

        goto bad_reg;

    }

bad_reg:

    /* ??? For debugging only.  Should raise illegal instruction exception.  */

    cpu_abort(env, "Unimplemented cp15 register read (c%d, c%d, {%d, %d})\n",

              (insn >> 16) & 0xf, crm, op1, op2);

    return 0;

}

static void pxa2xx_pwrmode_write(CPUARMState *env, const ARMCPRegInfo *ri,

                                 uint64_t value)

{

    PXA2xxState *s = (PXA2xxState *)ri->opaque;

    static const char *pwrmode[8] = {

        "Normal", "Idle", "Deep-idle", "Standby",

        "Sleep", "reserved (!)", "reserved (!)", "Deep-sleep",

    };



    if (value & 8) {

        printf("%s: CPU voltage change attempt\n", __func__);

    }

    switch (value & 7) {

    case 0:

        /* Do nothing */

        break;



    case 1:

        /* Idle */

        if (!(s->cm_regs[CCCR >> 2] & (1U << 31))) { /* CPDIS */

            cpu_interrupt(CPU(s->cpu), CPU_INTERRUPT_HALT);

            break;

        }

        /* Fall through.  */



    case 2:

        /* Deep-Idle */

        cpu_interrupt(CPU(s->cpu), CPU_INTERRUPT_HALT);

        s->pm_regs[RCSR >> 2] |= 0x8; /* Set GPR */

        goto message;



    case 3:

        s->cpu->env.uncached_cpsr = ARM_CPU_MODE_SVC;

        s->cpu->env.daif = PSTATE_A | PSTATE_F | PSTATE_I;

        s->cpu->env.cp15.sctlr_ns = 0;

        s->cpu->env.cp15.c1_coproc = 0;

        s->cpu->env.cp15.ttbr0_el[1] = 0;

        s->cpu->env.cp15.c3 = 0;

        s->pm_regs[PSSR >> 2] |= 0x8; /* Set STS */

        s->pm_regs[RCSR >> 2] |= 0x8; /* Set GPR */



        /*

         * The scratch-pad register is almost universally used

         * for storing the return address on suspend.  For the

         * lack of a resuming bootloader, perform a jump

         * directly to that address.

         */

        memset(s->cpu->env.regs, 0, 4 * 15);

        s->cpu->env.regs[15] = s->pm_regs[PSPR >> 2];



#if 0

        buffer = 0xe59ff000; /* ldr     pc, [pc, #0] */

        cpu_physical_memory_write(0, &buffer, 4);

        buffer = s->pm_regs[PSPR >> 2];

        cpu_physical_memory_write(8, &buffer, 4);

#endif



        /* Suspend */

        cpu_interrupt(current_cpu, CPU_INTERRUPT_HALT);



        goto message;



    default:

    message:

        printf("%s: machine entered %s mode\n", __func__,

               pwrmode[value & 7]);

    }

}

