static int epzs_motion_search(MpegEncContext * s,

                             int *mx_ptr, int *my_ptr,

                             int P[5][2], int pred_x, int pred_y,

                             int xmin, int ymin, int xmax, int ymax)

{

    int best[2]={0, 0};

    int d, dmin; 

    UINT8 *new_pic, *old_pic;

    const int pic_stride= s->linesize;

    const int pic_xy= (s->mb_y*pic_stride + s->mb_x)*16;

    UINT16 *mv_penalty= s->mv_penalty[s->f_code] + MAX_MV; // f_code of the prev frame

    int quant= s->qscale; // qscale of the prev frame

    const int shift= 1+s->quarter_sample;



    new_pic = s->new_picture[0] + pic_xy;

    old_pic = s->last_picture[0] + pic_xy;

//printf("%d %d %d %d\n", xmin, ymin, xmax, ymax);



    dmin = pix_abs16x16(new_pic, old_pic, pic_stride, 16);

    if(dmin<Z_THRESHOLD){

        *mx_ptr= 0;

        *my_ptr= 0;

//printf("Z");

        return dmin;

    }



    /* first line */

    if ((s->mb_y == 0 || s->first_slice_line || s->first_gob_line)) {

        CHECK_MV(P[1][0]>>shift, P[1][1]>>shift)

    }else{

        CHECK_MV(P[4][0]>>shift, P[4][1]>>shift)

        if(dmin<Z_THRESHOLD){

            *mx_ptr= P[4][0]>>shift;

            *my_ptr= P[4][1]>>shift;

//printf("M\n");

            return dmin;

        }

        CHECK_MV(P[1][0]>>shift, P[1][1]>>shift)

        CHECK_MV(P[2][0]>>shift, P[2][1]>>shift)

        CHECK_MV(P[3][0]>>shift, P[3][1]>>shift)

    }

    CHECK_MV(P[0][0]>>shift, P[0][1]>>shift)



    dmin= small_diamond_search(s, best, dmin, new_pic, old_pic, pic_stride, 

                               pred_x, pred_y, mv_penalty, quant, xmin, ymin, xmax, ymax, shift);

    *mx_ptr= best[0];

    *my_ptr= best[1];    



//    printf("%d %d %d \n", best[0], best[1], dmin);



    return dmin;

}

static int ir2_decode_plane_inter(Ir2Context *ctx, int width, int height, uint8_t *dst,

                                  int pitch, const uint8_t *table)

{

    int j;

    int out = 0;

    int c;

    int t;



    if (width & 1)




    for (j = 0; j < height; j++) {

        out = 0;



        while (out < width) {

            c = ir2_get_code(&ctx->gb);

            if (c >= 0x80) { /* we have a skip */

                c   -= 0x7F;

                out += c * 2;

            } else { /* add two deltas from table */

                t        = dst[out] + (((table[c * 2] - 128)*3) >> 2);

                t        = av_clip_uint8(t);

                dst[out] = t;

                out++;

                t        = dst[out] + (((table[(c * 2) + 1] - 128)*3) >> 2);

                t        = av_clip_uint8(t);

                dst[out] = t;

                out++;

            }

        }

        dst += pitch;

    }

    return 0;

}

static void video_encode_example(const char *filename, int codec_id)

{

    AVCodec *codec;

    AVCodecContext *c= NULL;

    int i, ret, x, y, got_output;

    FILE *f;

    AVFrame *picture;

    AVPacket pkt;

    uint8_t endcode[] = { 0, 0, 1, 0xb7 };



    printf("Encode video file %s\n", filename);



    /* find the mpeg1 video encoder */

    codec = avcodec_find_encoder(codec_id);

    if (!codec) {

        fprintf(stderr, "codec not found\n");

        exit(1);

    }



    c = avcodec_alloc_context3(codec);

    picture= avcodec_alloc_frame();



    /* put sample parameters */

    c->bit_rate = 400000;

    /* resolution must be a multiple of two */

    c->width = 352;

    c->height = 288;

    /* frames per second */

    c->time_base= (AVRational){1,25};

    c->gop_size = 10; /* emit one intra frame every ten frames */

    c->max_b_frames=1;

    c->pix_fmt = PIX_FMT_YUV420P;



    if(codec_id == AV_CODEC_ID_H264)

        av_opt_set(c->priv_data, "preset", "slow", 0);



    /* open it */

    if (avcodec_open2(c, codec, NULL) < 0) {

        fprintf(stderr, "could not open codec\n");

        exit(1);

    }



    f = fopen(filename, "wb");

    if (!f) {

        fprintf(stderr, "could not open %s\n", filename);

        exit(1);

    }



    /* the image can be allocated by any means and av_image_alloc() is

     * just the most convenient way if av_malloc() is to be used */

    ret = av_image_alloc(picture->data, picture->linesize, c->width, c->height,

                         c->pix_fmt, 32);

    if (ret < 0) {

        fprintf(stderr, "could not alloc raw picture buffer\n");

        exit(1);

    }



    picture->format = c->pix_fmt;

    picture->width  = c->width;

    picture->height = c->height;



    /* encode 1 second of video */

    for(i=0;i<25;i++) {

        av_init_packet(&pkt);

        pkt.data = NULL;    // packet data will be allocated by the encoder

        pkt.size = 0;



        fflush(stdout);

        /* prepare a dummy image */

        /* Y */

        for(y=0;y<c->height;y++) {

            for(x=0;x<c->width;x++) {

                picture->data[0][y * picture->linesize[0] + x] = x + y + i * 3;

            }

        }



        /* Cb and Cr */

        for(y=0;y<c->height/2;y++) {

            for(x=0;x<c->width/2;x++) {

                picture->data[1][y * picture->linesize[1] + x] = 128 + y + i * 2;

                picture->data[2][y * picture->linesize[2] + x] = 64 + x + i * 5;

            }

        }



        picture->pts = i;



        /* encode the image */

        ret = avcodec_encode_video2(c, &pkt, picture, &got_output);

        if (ret < 0) {

            fprintf(stderr, "error encoding frame\n");

            exit(1);

        }



        if (got_output) {

            printf("encoding frame %3d (size=%5d)\n", i, pkt.size);

            fwrite(pkt.data, 1, pkt.size, f);

            av_free_packet(&pkt);

        }

    }



    /* get the delayed frames */

    for (got_output = 1; got_output; i++) {

        fflush(stdout);



        ret = avcodec_encode_video2(c, &pkt, NULL, &got_output);

        if (ret < 0) {

            fprintf(stderr, "error encoding frame\n");

            exit(1);

        }



        if (got_output) {

            printf("write frame %3d (size=%5d)\n", i, pkt.size);

            fwrite(pkt.data, 1, pkt.size, f);

            av_free_packet(&pkt);

        }

    }



    /* add sequence end code to have a real mpeg file */

    fwrite(endcode, 1, sizeof(endcode), f);

    fclose(f);



    avcodec_close(c);

    av_free(c);

    av_freep(&picture->data[0]);

    av_free(picture);

    printf("\n");

}

void cpu_dump_state(CPUState *env, FILE *f,

                    int (*cpu_fprintf)(FILE *f, const char *fmt, ...),

                    int flags)

{

    int i, x;



    cpu_fprintf(f, "pc: " TARGET_FMT_lx "  npc: " TARGET_FMT_lx "\n", env->pc,

                env->npc);

    cpu_fprintf(f, "General Registers:\n");

    for (i = 0; i < 4; i++)

        cpu_fprintf(f, "%%g%c: " TARGET_FMT_lx "\t", i + '0', env->gregs[i]);

    cpu_fprintf(f, "\n");

    for (; i < 8; i++)

        cpu_fprintf(f, "%%g%c: " TARGET_FMT_lx "\t", i + '0', env->gregs[i]);

    cpu_fprintf(f, "\nCurrent Register Window:\n");

    for (x = 0; x < 3; x++) {

        for (i = 0; i < 4; i++)

            cpu_fprintf(f, "%%%c%d: " TARGET_FMT_lx "\t",

                    (x == 0 ? 'o' : (x == 1 ? 'l' : 'i')), i,

                    env->regwptr[i + x * 8]);

        cpu_fprintf(f, "\n");

        for (; i < 8; i++)

            cpu_fprintf(f, "%%%c%d: " TARGET_FMT_lx "\t",

                    (x == 0 ? 'o' : x == 1 ? 'l' : 'i'), i,

                    env->regwptr[i + x * 8]);

        cpu_fprintf(f, "\n");

    }

    cpu_fprintf(f, "\nFloating Point Registers:\n");

    for (i = 0; i < 32; i++) {

        if ((i & 3) == 0)

            cpu_fprintf(f, "%%f%02d:", i);

        cpu_fprintf(f, " %016lf", env->fpr[i]);

        if ((i & 3) == 3)

            cpu_fprintf(f, "\n");

    }

#ifdef TARGET_SPARC64

    cpu_fprintf(f, "pstate: 0x%08x ccr: 0x%02x asi: 0x%02x tl: %d fprs: %d\n",

                env->pstate, GET_CCR(env), env->asi, env->tl, env->fprs);

    cpu_fprintf(f, "cansave: %d canrestore: %d otherwin: %d wstate %d "

                "cleanwin %d cwp %d\n",

                env->cansave, env->canrestore, env->otherwin, env->wstate,

                env->cleanwin, env->nwindows - 1 - env->cwp);

#else

    cpu_fprintf(f, "psr: 0x%08x -> %c%c%c%c %c%c%c wim: 0x%08x\n",

                GET_PSR(env), GET_FLAG(PSR_ZERO, 'Z'), GET_FLAG(PSR_OVF, 'V'),

                GET_FLAG(PSR_NEG, 'N'), GET_FLAG(PSR_CARRY, 'C'),

                env->psrs?'S':'-', env->psrps?'P':'-',

                env->psret?'E':'-', env->wim);

#endif

    cpu_fprintf(f, "fsr: 0x%08x\n", GET_FSR32(env));

}

