static int make_ydt15_entry(int p2, int p1, int16_t *ydt)

#else

static int make_ydt15_entry(int p1, int p2, int16_t *ydt)

#endif

{

    int lo, hi;



    lo = ydt[p1];

    lo += (lo * 32) + (lo * 1024);

    hi = ydt[p2];

    hi += (hi * 32) + (hi * 1024);

    return (lo + (hi * (1 << 16))) * 2;

}

static int jpeg2000_decode_frame(AVCodecContext *avctx, void *data,

                                 int *got_frame, AVPacket *avpkt)

{

    Jpeg2000DecoderContext *s = avctx->priv_data;

    ThreadFrame frame = { .f = data };

    AVFrame *picture = data;

    int tileno, ret;



    s->avctx     = avctx;

    s->buf       = s->buf_start = avpkt->data;

    s->buf_end   = s->buf_start + avpkt->size;

    s->curtileno = 0; // TODO: only one tile in DCI JP2K. to implement for more tiles



    // reduction factor, i.e number of resolution levels to skip

    s->reduction_factor = s->lowres;



    if (s->buf_end - s->buf < 2)

        return AVERROR_INVALIDDATA;



    // check if the image is in jp2 format

    if ((AV_RB32(s->buf) == 12) &&

        (AV_RB32(s->buf + 4) == JP2_SIG_TYPE) &&

        (AV_RB32(s->buf + 8) == JP2_SIG_VALUE)) {

        if (!jp2_find_codestream(s)) {

            av_log(avctx, AV_LOG_ERROR,

                   "Could not find Jpeg2000 codestream atom.\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (bytestream_get_be16(&s->buf) != JPEG2000_SOC) {

        av_log(avctx, AV_LOG_ERROR, "SOC marker not present\n");

        return AVERROR_INVALIDDATA;

    }

    if (ret = jpeg2000_read_main_headers(s))

        goto end;



    /* get picture buffer */

    if ((ret = ff_thread_get_buffer(avctx, &frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "ff_thread_get_buffer() failed.\n");

        goto end;

    }

    picture->pict_type = AV_PICTURE_TYPE_I;

    picture->key_frame = 1;



    if (ret = jpeg2000_read_bitstream_packets(s))

        goto end;

    for (tileno = 0; tileno < s->numXtiles * s->numYtiles; tileno++)

        if (ret = jpeg2000_decode_tile(s, s->tile + tileno, picture))

            goto end;



    *got_frame = 1;



end:

    jpeg2000_dec_cleanup(s);

    return ret ? ret : s->buf - s->buf_start;

}

static int readv_f(BlockBackend *blk, int argc, char **argv)

{

    struct timeval t1, t2;

    int Cflag = 0, qflag = 0, vflag = 0;

    int c, cnt;

    char *buf;

    int64_t offset;

    /* Some compilers get confused and warn if this is not initialized.  */

    int total = 0;

    int nr_iov;

    QEMUIOVector qiov;

    int pattern = 0;

    int Pflag = 0;



    while ((c = getopt(argc, argv, "CP:qv")) != EOF) {

        switch (c) {

        case 'C':

            Cflag = 1;

            break;

        case 'P':

            Pflag = 1;

            pattern = parse_pattern(optarg);

            if (pattern < 0) {

                return 0;

            }

            break;

        case 'q':

            qflag = 1;

            break;

        case 'v':

            vflag = 1;

            break;

        default:

            return qemuio_command_usage(&readv_cmd);

        }

    }



    if (optind > argc - 2) {

        return qemuio_command_usage(&readv_cmd);

    }





    offset = cvtnum(argv[optind]);

    if (offset < 0) {

        printf("non-numeric length argument -- %s\n", argv[optind]);

        return 0;

    }

    optind++;



    if (offset & 0x1ff) {

        printf("offset %" PRId64 " is not sector aligned\n",

               offset);

        return 0;

    }



    nr_iov = argc - optind;

    buf = create_iovec(blk, &qiov, &argv[optind], nr_iov, 0xab);

    if (buf == NULL) {

        return 0;

    }



    gettimeofday(&t1, NULL);

    cnt = do_aio_readv(blk, &qiov, offset, &total);

    gettimeofday(&t2, NULL);



    if (cnt < 0) {

        printf("readv failed: %s\n", strerror(-cnt));

        goto out;

    }



    if (Pflag) {

        void *cmp_buf = g_malloc(qiov.size);

        memset(cmp_buf, pattern, qiov.size);

        if (memcmp(buf, cmp_buf, qiov.size)) {

            printf("Pattern verification failed at offset %"

                   PRId64 ", %zd bytes\n", offset, qiov.size);

        }

        g_free(cmp_buf);

    }



    if (qflag) {

        goto out;

    }



    if (vflag) {

        dump_buffer(buf, offset, qiov.size);

    }



    /* Finally, report back -- -C gives a parsable format */

    t2 = tsub(t2, t1);

    print_report("read", &t2, offset, qiov.size, total, cnt, Cflag);



out:

    qemu_iovec_destroy(&qiov);

    qemu_io_free(buf);

    return 0;

}

static void kvm_do_inject_x86_mce(void *_data)

{

    struct kvm_x86_mce_data *data = _data;

    int r;



    /* If there is an MCE exception being processed, ignore this SRAO MCE */

    if ((data->env->mcg_cap & MCG_SER_P) &&

        !(data->mce->status & MCI_STATUS_AR)) {

        r = kvm_mce_in_exception(data->env);

        if (r == -1) {

            fprintf(stderr, "Failed to get MCE status\n");

        } else if (r) {

            return;

        }

    }



    r = kvm_set_mce(data->env, data->mce);

    if (r < 0) {

        perror("kvm_set_mce FAILED");

        if (data->abort_on_error) {

            abort();

        }

    }

}

int rtjpeg_decode_frame_yuv420(RTJpegContext *c, AVFrame *f,

                               const uint8_t *buf, int buf_size) {

    GetBitContext gb;

    int w = c->w / 16, h = c->h / 16;

    int x, y;

    uint8_t *y1 = f->data[0], *y2 = f->data[0] + 8 * f->linesize[0];

    uint8_t *u = f->data[1], *v = f->data[2];

    init_get_bits(&gb, buf, buf_size * 8);

    for (y = 0; y < h; y++) {

        for (x = 0; x < w; x++) {

            DCTELEM *block = c->block;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y1, f->linesize[0], block);

            y1 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y1, f->linesize[0], block);

            y1 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y2, f->linesize[0], block);

            y2 += 8;

            if (get_block(&gb, block, c->scan, c->lquant) > 0)

                c->dsp->idct_put(y2, f->linesize[0], block);

            y2 += 8;

            if (get_block(&gb, block, c->scan, c->cquant) > 0)

                c->dsp->idct_put(u, f->linesize[1], block);

            u += 8;

            if (get_block(&gb, block, c->scan, c->cquant) > 0)

                c->dsp->idct_put(v, f->linesize[2], block);

            v += 8;

        }

        y1 += 2 * 8 * (f->linesize[0] - w);

        y2 += 2 * 8 * (f->linesize[0] - w);

        u += 8 * (f->linesize[1] - w);

        v += 8 * (f->linesize[2] - w);

    }

    return get_bits_count(&gb) / 8;

}

static void ahci_init_d2h(AHCIDevice *ad)

{

    IDEState *ide_state = &ad->port.ifs[0];

    AHCIPortRegs *pr = &ad->port_regs;



    if (ad->init_d2h_sent) {

        return;

    }



    if (ahci_write_fis_d2h(ad)) {

        ad->init_d2h_sent = true;

        /* We're emulating receiving the first Reg H2D Fis from the device;

         * Update the SIG register, but otherwise proceed as normal. */

        pr->sig = (ide_state->hcyl << 24) |

            (ide_state->lcyl << 16) |

            (ide_state->sector << 8) |

            (ide_state->nsector & 0xFF);

    }

}

void st_set_trace_file_enabled(bool enable)

{

    if (enable == !!trace_fp) {

        return; /* no change */

    }



    /* Halt trace writeout */

    flush_trace_file(true);

    trace_writeout_enabled = false;

    flush_trace_file(true);



    if (enable) {

        static const TraceRecord header = {

            .event = HEADER_EVENT_ID,

            .timestamp_ns = HEADER_MAGIC,

            .x1 = HEADER_VERSION,

        };



        trace_fp = fopen(trace_file_name, "w");

        if (!trace_fp) {

            return;

        }



        if (fwrite(&header, sizeof header, 1, trace_fp) != 1) {

            fclose(trace_fp);

            trace_fp = NULL;

            return;

        }



        /* Resume trace writeout */

        trace_writeout_enabled = true;

        flush_trace_file(false);

    } else {

        fclose(trace_fp);

        trace_fp = NULL;

    }

}

