static int decode_frame(AVCodecContext *avctx, 

                        void *data, int *data_size,

                        uint8_t *buf, int buf_size)

{

    MDECContext * const a = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame * const p= (AVFrame*)&a->picture;

    int i;



    /* special case for last picture */

    if (buf_size == 0) {

        return 0;

    }



    if(p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference= 0;

    if(avctx->get_buffer(avctx, p) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    p->pict_type= I_TYPE;

    p->key_frame= 1;

    a->last_dc[0]=

    a->last_dc[1]=

    a->last_dc[2]= 0;



    a->bitstream_buffer= av_fast_realloc(a->bitstream_buffer, &a->bitstream_buffer_size, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

    for(i=0; i<buf_size; i+=2){

        a->bitstream_buffer[i]  = buf[i+1];

        a->bitstream_buffer[i+1]= buf[i  ];

    }

    init_get_bits(&a->gb, a->bitstream_buffer, buf_size*8);



    /* skip over 4 preamble bytes in stream (typically 0xXX 0xXX 0x00 0x38) */

    skip_bits(&a->gb, 32);



    a->qscale=  get_bits(&a->gb, 16);

    a->version= get_bits(&a->gb, 16);



//    printf("qscale:%d (0x%X), version:%d (0x%X)\n", a->qscale, a->qscale, a->version, a->version);



    for(a->mb_x=0; a->mb_x<a->mb_width; a->mb_x++){

        for(a->mb_y=0; a->mb_y<a->mb_height; a->mb_y++){

            if( decode_mb(a, a->block) <0)

                return -1;



            idct_put(a, a->mb_x, a->mb_y);

        }

    }



//    p->quality= (32 + a->inv_qscale/2)/a->inv_qscale;

//    memset(p->qscale_table, p->quality, p->qstride*a->mb_height);



    *picture= *(AVFrame*)&a->picture;

    *data_size = sizeof(AVPicture);



    emms_c();



    return (get_bits_count(&a->gb)+31)/32*4;

}

TranslationBlock *tb_gen_code(CPUState *cpu,

                              target_ulong pc, target_ulong cs_base,

                              int flags, int cflags)

{

    CPUArchState *env = cpu->env_ptr;

    TranslationBlock *tb;

    tb_page_addr_t phys_pc, phys_page2;

    target_ulong virt_page2;

    tcg_insn_unit *gen_code_buf;

    int gen_code_size, search_size;

#ifdef CONFIG_PROFILER

    int64_t ti;

#endif



    phys_pc = get_page_addr_code(env, pc);

    if (use_icount) {

        cflags |= CF_USE_ICOUNT;

    }

    tb = tb_alloc(pc);

    if (!tb) {

        /* flush must be done */

        tb_flush(cpu);

        /* cannot fail at this point */

        tb = tb_alloc(pc);

        /* Don't forget to invalidate previous TB info.  */

        tcg_ctx.tb_ctx.tb_invalidated_flag = 1;

    }



    gen_code_buf = tcg_ctx.code_gen_ptr;

    tb->tc_ptr = gen_code_buf;

    tb->cs_base = cs_base;

    tb->flags = flags;

    tb->cflags = cflags;



#ifdef CONFIG_PROFILER

    tcg_ctx.tb_count1++; /* includes aborted translations because of

                       exceptions */

    ti = profile_getclock();

#endif



    tcg_func_start(&tcg_ctx);



    gen_intermediate_code(env, tb);



    trace_translate_block(tb, tb->pc, tb->tc_ptr);



    /* generate machine code */

    tb->tb_next_offset[0] = 0xffff;

    tb->tb_next_offset[1] = 0xffff;

    tcg_ctx.tb_next_offset = tb->tb_next_offset;

#ifdef USE_DIRECT_JUMP

    tcg_ctx.tb_jmp_offset = tb->tb_jmp_offset;

    tcg_ctx.tb_next = NULL;

#else

    tcg_ctx.tb_jmp_offset = NULL;

    tcg_ctx.tb_next = tb->tb_next;

#endif



#ifdef CONFIG_PROFILER

    tcg_ctx.tb_count++;

    tcg_ctx.interm_time += profile_getclock() - ti;

    tcg_ctx.code_time -= profile_getclock();

#endif



    gen_code_size = tcg_gen_code(&tcg_ctx, gen_code_buf);

    search_size = encode_search(tb, (void *)gen_code_buf + gen_code_size);



#ifdef CONFIG_PROFILER

    tcg_ctx.code_time += profile_getclock();

    tcg_ctx.code_in_len += tb->size;

    tcg_ctx.code_out_len += gen_code_size;

    tcg_ctx.search_out_len += search_size;

#endif



#ifdef DEBUG_DISAS

    if (qemu_loglevel_mask(CPU_LOG_TB_OUT_ASM)) {

        qemu_log("OUT: [size=%d]\n", gen_code_size);

        log_disas(tb->tc_ptr, gen_code_size);

        qemu_log("\n");

        qemu_log_flush();

    }

#endif



    tcg_ctx.code_gen_ptr = (void *)

        ROUND_UP((uintptr_t)gen_code_buf + gen_code_size + search_size,

                 CODE_GEN_ALIGN);



    /* check next page if needed */

    virt_page2 = (pc + tb->size - 1) & TARGET_PAGE_MASK;

    phys_page2 = -1;

    if ((pc & TARGET_PAGE_MASK) != virt_page2) {

        phys_page2 = get_page_addr_code(env, virt_page2);

    }

    tb_link_page(tb, phys_pc, phys_page2);

    return tb;

}

