static int monitor_check_qmp_args(const mon_cmd_t *cmd, QDict *args)

{

    int err;

    const char *p;

    CmdArgs cmd_args;

    QemuOptsList *opts_list;



    if (cmd->args_type == NULL) {

        return (qdict_size(args) == 0 ? 0 : -1);

    }



    err = 0;

    cmd_args_init(&cmd_args);

    opts_list = NULL;



    for (p = cmd->args_type;; p++) {

        if (*p == ':') {

            cmd_args.type = *++p;

            p++;

            if (cmd_args.type == '-') {

                cmd_args.flag = *p++;

                cmd_args.optional = 1;

            } else if (cmd_args.type == 'O') {

                opts_list = qemu_find_opts(qstring_get_str(cmd_args.name));

                assert(opts_list);

            } else if (*p == '?') {

                cmd_args.optional = 1;

                p++;

            }



            assert(*p == ',' || *p == '\0');

            if (opts_list) {

                err = check_opts(opts_list, args);

                opts_list = NULL;

            } else {

                err = check_arg(&cmd_args, args);

                QDECREF(cmd_args.name);

                cmd_args_init(&cmd_args);

            }



            if (err < 0) {

                break;

            }

        } else {

            qstring_append_chr(cmd_args.name, *p);

        }



        if (*p == '\0') {

            break;

        }

    }



    QDECREF(cmd_args.name);

    return err;

}

static void term_up_char(void)

{

    int idx;



    if (term_hist_entry == 0)

	return;

    if (term_hist_entry == -1) {

	/* Find latest entry */

	for (idx = 0; idx < TERM_MAX_CMDS; idx++) {

	    if (term_history[idx] == NULL)

		break;

	}

	term_hist_entry = idx;

    }

    term_hist_entry--;

    if (term_hist_entry >= 0) {

	strcpy(term_cmd_buf, term_history[term_hist_entry]);

	term_printf("\n");

	term_print_cmdline(term_cmd_buf);

	term_cmd_buf_index = term_cmd_buf_size = strlen(term_cmd_buf);

    }

}

static int h264_frame_start(H264Context *h)

{

    H264Picture *pic;

    int i, ret;

    const int pixel_shift = h->pixel_shift;



    ret = initialize_cur_frame(h);

    if (ret < 0)

        return ret;



    pic = h->cur_pic_ptr;

    pic->reference              = h->droppable ? 0 : h->picture_structure;

    pic->f->coded_picture_number = h->coded_picture_number++;

    pic->field_picture          = h->picture_structure != PICT_FRAME;

    pic->frame_num               = h->frame_num;

    /*

     * Zero key_frame here; IDR markings per slice in frame or fields are ORed

     * in later.

     * See decode_nal_units().

     */

    pic->f->key_frame = 0;

    pic->mmco_reset  = 0;

    pic->recovered   = 0;



    if (CONFIG_ERROR_RESILIENCE && h->enable_er)

        ff_er_frame_start(&h->slice_ctx[0].er);



    for (i = 0; i < 16; i++) {

        h->block_offset[i]           = (4 * ((scan8[i] - scan8[0]) & 7) << pixel_shift) + 4 * pic->f->linesize[0] * ((scan8[i] - scan8[0]) >> 3);

        h->block_offset[48 + i]      = (4 * ((scan8[i] - scan8[0]) & 7) << pixel_shift) + 8 * pic->f->linesize[0] * ((scan8[i] - scan8[0]) >> 3);

    }

    for (i = 0; i < 16; i++) {

        h->block_offset[16 + i]      =

        h->block_offset[32 + i]      = (4 * ((scan8[i] - scan8[0]) & 7) << pixel_shift) + 4 * pic->f->linesize[1] * ((scan8[i] - scan8[0]) >> 3);

        h->block_offset[48 + 16 + i] =

        h->block_offset[48 + 32 + i] = (4 * ((scan8[i] - scan8[0]) & 7) << pixel_shift) + 8 * pic->f->linesize[1] * ((scan8[i] - scan8[0]) >> 3);

    }



    /* Some macroblocks can be accessed before they're available in case

     * of lost slices, MBAFF or threading. */

    memset(h->slice_table, -1,

           (h->mb_height * h->mb_stride - 1) * sizeof(*h->slice_table));



    /* We mark the current picture as non-reference after allocating it, so

     * that if we break out due to an error it can be released automatically

     * in the next ff_mpv_frame_start().

     */

    h->cur_pic_ptr->reference = 0;



    h->cur_pic_ptr->field_poc[0] = h->cur_pic_ptr->field_poc[1] = INT_MAX;



    h->next_output_pic = NULL;



    assert(h->cur_pic_ptr->long_ref == 0);



    return 0;

}

static void receive_from_chr_layer(SCLPConsoleLM *scon, const uint8_t *buf,

                                   int size)

{

    assert(size == 1);



    if (*buf == '\r' || *buf == '\n') {

        scon->event.event_pending = true;

        return;

    }

    scon->buf[scon->length] = *buf;

    scon->length += 1;

    if (scon->echo) {

        qemu_chr_fe_write(scon->chr, buf, size);

    }

}

static void ff_h264_idct_add16_mmx2(uint8_t *dst, const int *block_offset, DCTELEM *block, int stride, const uint8_t nnzc[6*8]){

    int i;

    for(i=0; i<16; i++){

        int nnz = nnzc[ scan8[i] ];

        if(nnz){

            if(nnz==1 && block[i*16]) ff_h264_idct_dc_add_mmx2(dst + block_offset[i], block + i*16, stride);

            else                      ff_h264_idct_add_mmx    (dst + block_offset[i], block + i*16, stride);

        }

    }

}

