    return 0;

}

int64_t xbzrle_cache_resize(int64_t new_size)

{

    if (new_size < TARGET_PAGE_SIZE) {

        return -1;

    }



    if (XBZRLE.cache != NULL) {

        return cache_resize(XBZRLE.cache, new_size / TARGET_PAGE_SIZE) *

            TARGET_PAGE_SIZE;

    }

    return pow2floor(new_size);

}

static inline TranslationBlock *tb_find_fast(CPUState *cpu,

                                             TranslationBlock *last_tb,

                                             int tb_exit)

{

    CPUArchState *env = (CPUArchState *)cpu->env_ptr;

    TranslationBlock *tb;

    target_ulong cs_base, pc;

    uint32_t flags;



    /* we record a subset of the CPU state. It will

       always be the same before a given translated block

       is executed. */

    cpu_get_tb_cpu_state(env, &pc, &cs_base, &flags);

    tb_lock();

    tb = atomic_rcu_read(&cpu->tb_jmp_cache[tb_jmp_cache_hash_func(pc)]);

    if (unlikely(!tb || tb->pc != pc || tb->cs_base != cs_base ||

                 tb->flags != flags)) {

        tb = tb_find_slow(cpu, pc, cs_base, flags);

    }

#ifndef CONFIG_USER_ONLY

    /* We don't take care of direct jumps when address mapping changes in

     * system emulation. So it's not safe to make a direct jump to a TB

     * spanning two pages because the mapping for the second page can change.

     */

    if (tb->page_addr[1] != -1) {

        last_tb = NULL;

    }

#endif

    /* See if we can patch the calling TB. */

    if (last_tb && !qemu_loglevel_mask(CPU_LOG_TB_NOCHAIN)) {

        /* Check if translation buffer has been flushed */

        if (cpu->tb_flushed) {

            cpu->tb_flushed = false;

        } else {

            tb_add_jump(last_tb, tb_exit, tb);

        }

    }

    tb_unlock();

    return tb;

}

static int h261_decode_picture_header(H261Context *h)

{

    MpegEncContext *const s = &h->s;

    int format, i;

    uint32_t startcode = 0;



    for (i = get_bits_left(&s->gb); i > 24; i -= 1) {

        startcode = ((startcode << 1) | get_bits(&s->gb, 1)) & 0x000FFFFF;



        if (startcode == 0x10)

            break;

    }



    if (startcode != 0x10) {

        av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");

        return -1;

    }



    /* temporal reference */

    i = get_bits(&s->gb, 5); /* picture timestamp */

    if (i < (s->picture_number & 31))

        i += 32;

    s->picture_number = (s->picture_number & ~31) + i;



    s->avctx->time_base      = (AVRational) { 1001, 30000 };



    /* PTYPE starts here */

    skip_bits1(&s->gb); /* split screen off */

    skip_bits1(&s->gb); /* camera  off */

    skip_bits1(&s->gb); /* freeze picture release off */



    format = get_bits1(&s->gb);



    // only 2 formats possible

    if (format == 0) { // QCIF

        s->width     = 176;

        s->height    = 144;

        s->mb_width  = 11;

        s->mb_height = 9;

    } else { // CIF

        s->width     = 352;

        s->height    = 288;

        s->mb_width  = 22;

        s->mb_height = 18;

    }



    s->mb_num = s->mb_width * s->mb_height;



    skip_bits1(&s->gb); /* still image mode off */

    skip_bits1(&s->gb); /* Reserved */



    /* PEI */

    while (get_bits1(&s->gb) != 0)

        skip_bits(&s->gb, 8);



    /* H.261 has no I-frames, but if we pass AV_PICTURE_TYPE_I for the first

     * frame, the codec crashes if it does not contain all I-blocks

     * (e.g. when a packet is lost). */

    s->pict_type = AV_PICTURE_TYPE_P;



    h->gob_number = 0;

    return 0;

}

int avpicture_layout(const AVPicture* src, enum AVPixelFormat pix_fmt,

                     int width, int height,

                     unsigned char *dest, int dest_size)

{

    int i, j, nb_planes = 0, linesizes[4];

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(pix_fmt);

    int size = avpicture_get_size(pix_fmt, width, height);



    if (size > dest_size || size < 0)

        return AVERROR(EINVAL);



    for (i = 0; i < desc->nb_components; i++)

        nb_planes = FFMAX(desc->comp[i].plane, nb_planes);



    nb_planes++;



    av_image_fill_linesizes(linesizes, pix_fmt, width);

    for (i = 0; i < nb_planes; i++) {

        int h, shift = (i == 1 || i == 2) ? desc->log2_chroma_h : 0;

        const unsigned char *s = src->data[i];

        h = (height + (1 << shift) - 1) >> shift;



        for (j = 0; j < h; j++) {

            memcpy(dest, s, linesizes[i]);

            dest += linesizes[i];

            s += src->linesize[i];

        }

    }



    if (desc->flags & AV_PIX_FMT_FLAG_PAL)

        memcpy((unsigned char *)(((size_t)dest + 3) & ~3),

               src->data[1], 256 * 4);



    return size;

}

void avfilter_free(AVFilterContext *filter)

{

    int i;

    AVFilterLink *link;



    if (filter->filter->uninit)

        filter->filter->uninit(filter);



    for (i = 0; i < filter->input_count; i++) {

        if ((link = filter->inputs[i])) {

            if (link->src)

                link->src->outputs[link->srcpad - link->src->output_pads] = NULL;

            avfilter_formats_unref(&link->in_formats);

            avfilter_formats_unref(&link->out_formats);

        }

        av_freep(&link);

    }

    for (i = 0; i < filter->output_count; i++) {

        if ((link = filter->outputs[i])) {

            if (link->dst)

                link->dst->inputs[link->dstpad - link->dst->input_pads] = NULL;

            avfilter_formats_unref(&link->in_formats);

            avfilter_formats_unref(&link->out_formats);

        }

        av_freep(&link);

    }



    av_freep(&filter->name);

    av_freep(&filter->input_pads);

    av_freep(&filter->output_pads);

    av_freep(&filter->inputs);

    av_freep(&filter->outputs);

    av_freep(&filter->priv);

    av_free(filter);

}

static void fw_cfg_io_class_init(ObjectClass *klass, void *data)

{

    DeviceClass *dc = DEVICE_CLASS(klass);



    dc->realize = fw_cfg_io_realize;

    dc->props = fw_cfg_io_properties;






}

static void rom_reset(void *unused)

{

    Rom *rom;



    QTAILQ_FOREACH(rom, &roms, next) {

        if (rom->fw_file) {

            continue;

        }

        if (rom->data == NULL)

            continue;

        cpu_physical_memory_write_rom(rom->addr, rom->data, rom->romsize);

        if (rom->isrom) {

            /* rom needs to be written only once */

            qemu_free(rom->data);

            rom->data = NULL;

        }

    }

}

static int audio_decode_frame(VideoState *is)

{

    AVPacket *pkt_temp = &is->audio_pkt_temp;

    AVPacket *pkt = &is->audio_pkt;

    AVCodecContext *dec = is->audio_st->codec;

    int len1, data_size, resampled_data_size;

    int64_t dec_channel_layout;

    int got_frame;

    av_unused double audio_clock0;

    int new_packet = 0;

    int flush_complete = 0;

    int wanted_nb_samples;

    AVRational tb;

    int ret;

    int reconfigure;



    for (;;) {

        /* NOTE: the audio packet can contain several frames */

        while (pkt_temp->size > 0 || (!pkt_temp->data && new_packet) || is->audio_buf_frames_pending) {

            if (!is->frame) {

                if (!(is->frame = avcodec_alloc_frame()))

                    return AVERROR(ENOMEM);

            } else {

                av_frame_unref(is->frame);

                avcodec_get_frame_defaults(is->frame);

            }



            if (is->audioq.serial != is->audio_pkt_temp_serial)

                break;



            if (is->paused)

                return -1;



            if (!is->audio_buf_frames_pending) {

                if (flush_complete)

                    break;

                new_packet = 0;

                len1 = avcodec_decode_audio4(dec, is->frame, &got_frame, pkt_temp);

                if (len1 < 0) {

                    /* if error, we skip the frame */

                    pkt_temp->size = 0;

                    break;

                }



                pkt_temp->data += len1;

                pkt_temp->size -= len1;



                if (!got_frame) {

                    /* stop sending empty packets if the decoder is finished */

                    if (!pkt_temp->data && dec->codec->capabilities & CODEC_CAP_DELAY)

                        flush_complete = 1;

                    continue;

                }



                tb = (AVRational){1, is->frame->sample_rate};

                if (is->frame->pts != AV_NOPTS_VALUE)

                    is->frame->pts = av_rescale_q(is->frame->pts, dec->time_base, tb);

                else if (is->frame->pkt_pts != AV_NOPTS_VALUE)

                    is->frame->pts = av_rescale_q(is->frame->pkt_pts, is->audio_st->time_base, tb);

                if (pkt_temp->pts != AV_NOPTS_VALUE)

                    pkt_temp->pts += (double) is->frame->nb_samples / is->frame->sample_rate / av_q2d(is->audio_st->time_base);



#if CONFIG_AVFILTER

                dec_channel_layout = get_valid_channel_layout(is->frame->channel_layout, av_frame_get_channels(is->frame));



                reconfigure =

                    cmp_audio_fmts(is->audio_filter_src.fmt, is->audio_filter_src.channels,

                                   is->frame->format, av_frame_get_channels(is->frame))    ||

                    is->audio_filter_src.channel_layout != dec_channel_layout ||

                    is->audio_filter_src.freq           != is->frame->sample_rate ||

                    is->audio_pkt_temp_serial           != is->audio_last_serial;



                if (reconfigure) {

                    char buf1[1024], buf2[1024];

                    av_get_channel_layout_string(buf1, sizeof(buf1), -1, is->audio_filter_src.channel_layout);

                    av_get_channel_layout_string(buf2, sizeof(buf2), -1, dec_channel_layout);

                    av_log(NULL, AV_LOG_DEBUG,

                           "Audio frame changed from rate:%d ch:%d fmt:%s layout:%s serial:%d to rate:%d ch:%d fmt:%s layout:%s serial:%d\n",

                           is->audio_filter_src.freq, is->audio_filter_src.channels, av_get_sample_fmt_name(is->audio_filter_src.fmt), buf1, is->audio_last_serial,

                           is->frame->sample_rate, av_frame_get_channels(is->frame), av_get_sample_fmt_name(is->frame->format), buf2, is->audio_pkt_temp_serial);



                    is->audio_filter_src.fmt            = is->frame->format;

                    is->audio_filter_src.channels       = av_frame_get_channels(is->frame);

                    is->audio_filter_src.channel_layout = dec_channel_layout;

                    is->audio_filter_src.freq           = is->frame->sample_rate;

                    is->audio_last_serial               = is->audio_pkt_temp_serial;



                    if ((ret = configure_audio_filters(is, afilters, 1)) < 0)

                        return ret;

                }



                if ((ret = av_buffersrc_add_frame(is->in_audio_filter, is->frame)) < 0)

                    return ret;

                av_frame_unref(is->frame);

#endif

            }

#if CONFIG_AVFILTER

            if ((ret = av_buffersink_get_frame_flags(is->out_audio_filter, is->frame, 0)) < 0) {

                if (ret == AVERROR(EAGAIN)) {

                    is->audio_buf_frames_pending = 0;

                    continue;

                }

                return ret;

            }

            is->audio_buf_frames_pending = 1;

            tb = is->out_audio_filter->inputs[0]->time_base;

#endif



            data_size = av_samples_get_buffer_size(NULL, av_frame_get_channels(is->frame),

                                                   is->frame->nb_samples,

                                                   is->frame->format, 1);



            dec_channel_layout =

                (is->frame->channel_layout && av_frame_get_channels(is->frame) == av_get_channel_layout_nb_channels(is->frame->channel_layout)) ?

                is->frame->channel_layout : av_get_default_channel_layout(av_frame_get_channels(is->frame));

            wanted_nb_samples = synchronize_audio(is, is->frame->nb_samples);



            if (is->frame->format        != is->audio_src.fmt            ||

                dec_channel_layout       != is->audio_src.channel_layout ||

                is->frame->sample_rate   != is->audio_src.freq           ||

                (wanted_nb_samples       != is->frame->nb_samples && !is->swr_ctx)) {

                swr_free(&is->swr_ctx);

                is->swr_ctx = swr_alloc_set_opts(NULL,

                                                 is->audio_tgt.channel_layout, is->audio_tgt.fmt, is->audio_tgt.freq,

                                                 dec_channel_layout,           is->frame->format, is->frame->sample_rate,

                                                 0, NULL);

                if (!is->swr_ctx || swr_init(is->swr_ctx) < 0) {

                    av_log(NULL, AV_LOG_ERROR,

                           "Cannot create sample rate converter for conversion of %d Hz %s %d channels to %d Hz %s %d channels!\n",

                            is->frame->sample_rate, av_get_sample_fmt_name(is->frame->format), av_frame_get_channels(is->frame),

                            is->audio_tgt.freq, av_get_sample_fmt_name(is->audio_tgt.fmt), is->audio_tgt.channels);

                    break;

                }

                is->audio_src.channel_layout = dec_channel_layout;

                is->audio_src.channels       = av_frame_get_channels(is->frame);

                is->audio_src.freq = is->frame->sample_rate;

                is->audio_src.fmt = is->frame->format;

            }



            if (is->swr_ctx) {

                const uint8_t **in = (const uint8_t **)is->frame->extended_data;

                uint8_t **out = &is->audio_buf1;

                int out_count = (int64_t)wanted_nb_samples * is->audio_tgt.freq / is->frame->sample_rate + 256;

                int out_size  = av_samples_get_buffer_size(NULL, is->audio_tgt.channels, out_count, is->audio_tgt.fmt, 0);

                int len2;

                if (out_size < 0) {

                    av_log(NULL, AV_LOG_ERROR, "av_samples_get_buffer_size() failed\n");

                    break;

                }

                if (wanted_nb_samples != is->frame->nb_samples) {

                    if (swr_set_compensation(is->swr_ctx, (wanted_nb_samples - is->frame->nb_samples) * is->audio_tgt.freq / is->frame->sample_rate,

                                                wanted_nb_samples * is->audio_tgt.freq / is->frame->sample_rate) < 0) {

                        av_log(NULL, AV_LOG_ERROR, "swr_set_compensation() failed\n");

                        break;

                    }

                }

                av_fast_malloc(&is->audio_buf1, &is->audio_buf1_size, out_size);

                if (!is->audio_buf1)

                    return AVERROR(ENOMEM);

                len2 = swr_convert(is->swr_ctx, out, out_count, in, is->frame->nb_samples);

                if (len2 < 0) {

                    av_log(NULL, AV_LOG_ERROR, "swr_convert() failed\n");

                    break;

                }

                if (len2 == out_count) {

                    av_log(NULL, AV_LOG_WARNING, "audio buffer is probably too small\n");

                    swr_init(is->swr_ctx);

                }

                is->audio_buf = is->audio_buf1;

                resampled_data_size = len2 * is->audio_tgt.channels * av_get_bytes_per_sample(is->audio_tgt.fmt);

            } else {

                is->audio_buf = is->frame->data[0];

                resampled_data_size = data_size;

            }



            audio_clock0 = is->audio_clock;

            /* update the audio clock with the pts */

            if (is->frame->pts != AV_NOPTS_VALUE)

                is->audio_clock = is->frame->pts * av_q2d(tb) + (double) is->frame->nb_samples / is->frame->sample_rate;

            else

                is->audio_clock = NAN;

            is->audio_clock_serial = is->audio_pkt_temp_serial;

#ifdef DEBUG

            {

                static double last_clock;

                printf("audio: delay=%0.3f clock=%0.3f clock0=%0.3f\n",

                       is->audio_clock - last_clock,

                       is->audio_clock, audio_clock0);

                last_clock = is->audio_clock;

            }

#endif

            return resampled_data_size;

        }



        /* free the current packet */

        if (pkt->data)

            av_free_packet(pkt);

        memset(pkt_temp, 0, sizeof(*pkt_temp));



        if (is->audioq.abort_request) {

            return -1;

        }



        if (is->audioq.nb_packets == 0)

            SDL_CondSignal(is->continue_read_thread);



        /* read next packet */

        if ((new_packet = packet_queue_get(&is->audioq, pkt, 1, &is->audio_pkt_temp_serial)) < 0)

            return -1;



        if (pkt->data == flush_pkt.data) {

            avcodec_flush_buffers(dec);

            flush_complete = 0;

            is->audio_buf_frames_pending = 0;

        }



        *pkt_temp = *pkt;

    }

}

static void init_mbr(BDRVVVFATState* s)

{

    /* TODO: if the files mbr.img and bootsect.img exist, use them */

    mbr_t* real_mbr=(mbr_t*)s->first_sectors;

    partition_t* partition = &(real_mbr->partition[0]);

    int lba;



    memset(s->first_sectors,0,512);



    /* Win NT Disk Signature */

    real_mbr->nt_id= cpu_to_le32(0xbe1afdfa);



    partition->attributes=0x80; /* bootable */



    /* LBA is used when partition is outside the CHS geometry */

    lba = sector2CHS(s->bs, &partition->start_CHS, s->first_sectors_number-1);

    lba|= sector2CHS(s->bs, &partition->end_CHS,   s->sector_count);



    /*LBA partitions are identified only by start/length_sector_long not by CHS*/

    partition->start_sector_long =cpu_to_le32(s->first_sectors_number-1);

    partition->length_sector_long=cpu_to_le32(s->sector_count - s->first_sectors_number+1);



    /* FAT12/FAT16/FAT32 */

    /* DOS uses different types when partition is LBA,

       probably to prevent older versions from using CHS on them */

    partition->fs_type= s->fat_type==12 ? 0x1:

                        s->fat_type==16 ? (lba?0xe:0x06):

                         /*fat_tyoe==32*/ (lba?0xc:0x0b);



    real_mbr->magic[0]=0x55; real_mbr->magic[1]=0xaa;

}

void pc_cpus_init(PCMachineState *pcms)

{

    int i;

    CPUClass *cc;

    ObjectClass *oc;

    const char *typename;

    gchar **model_pieces;

    X86CPU *cpu = NULL;

    MachineState *machine = MACHINE(pcms);



    /* init CPUs */

    if (machine->cpu_model == NULL) {

#ifdef TARGET_X86_64

        machine->cpu_model = "qemu64";

#else

        machine->cpu_model = "qemu32";

#endif

    }



    model_pieces = g_strsplit(machine->cpu_model, ",", 2);

    if (!model_pieces[0]) {

        error_report("Invalid/empty CPU model name");

        exit(1);

    }



    oc = cpu_class_by_name(TYPE_X86_CPU, model_pieces[0]);

    if (oc == NULL) {

        error_report("Unable to find CPU definition: %s", model_pieces[0]);

        exit(1);

    }

    typename = object_class_get_name(oc);

    cc = CPU_CLASS(oc);

    cc->parse_features(typename, model_pieces[1], &error_fatal);

    g_strfreev(model_pieces);



    /* Calculates the limit to CPU APIC ID values

     *

     * Limit for the APIC ID value, so that all

     * CPU APIC IDs are < pcms->apic_id_limit.

     *

     * This is used for FW_CFG_MAX_CPUS. See comments on bochs_bios_init().

     */

    pcms->apic_id_limit = x86_cpu_apic_id_from_index(max_cpus - 1) + 1;

    if (pcms->apic_id_limit > ACPI_CPU_HOTPLUG_ID_LIMIT) {

        error_report("max_cpus is too large. APIC ID of last CPU is %u",

                     pcms->apic_id_limit - 1);

        exit(1);

    }



    pcms->possible_cpus = g_malloc0(sizeof(CPUArchIdList) +

                                    sizeof(CPUArchId) * max_cpus);

    for (i = 0; i < max_cpus; i++) {

        pcms->possible_cpus->cpus[i].arch_id = x86_cpu_apic_id_from_index(i);

        pcms->possible_cpus->len++;

        if (i < smp_cpus) {

            cpu = pc_new_cpu(typename, x86_cpu_apic_id_from_index(i),

                             &error_fatal);

            object_unref(OBJECT(cpu));

        }

    }



    /* tell smbios about cpuid version and features */

    smbios_set_cpuid(cpu->env.cpuid_version, cpu->env.features[FEAT_1_EDX]);

}

