static int asf_read_generic_value(AVFormatContext *s, uint8_t *name, uint16_t name_len,

                                  int type, AVDictionary **met)

{

    AVIOContext *pb = s->pb;

    uint64_t value;

    char buf[32];



    switch (type) {

    case ASF_BOOL:

        value = avio_rl32(pb);

        break;

    case ASF_DWORD:

        value = avio_rl32(pb);

        break;

    case ASF_QWORD:

        value = avio_rl64(pb);

        break;

    case ASF_WORD:

        value = avio_rl16(pb);

        break;

    default:

        av_freep(&name);

        return AVERROR_INVALIDDATA;

    }

    snprintf(buf, sizeof(buf), "%"PRIu64, value);

    if (av_dict_set(met, name, buf, 0) < 0)

        av_log(s, AV_LOG_WARNING, "av_dict_set failed.\n");



    return 0;

}

static int ram_save_complete(QEMUFile *f, void *opaque)

{

    rcu_read_lock();



    migration_bitmap_sync();



    ram_control_before_iterate(f, RAM_CONTROL_FINISH);



    /* try transferring iterative blocks of memory */



    /* flush all remaining blocks regardless of rate limiting */

    while (true) {

        int pages;



        pages = ram_find_and_save_block(f, true, &bytes_transferred);

        /* no more blocks to sent */

        if (pages == 0) {

            break;

        }

    }



    flush_compressed_data(f);

    ram_control_after_iterate(f, RAM_CONTROL_FINISH);

    migration_end();



    rcu_read_unlock();

    qemu_put_be64(f, RAM_SAVE_FLAG_EOS);



    return 0;

}

int ff_srtp_decrypt(struct SRTPContext *s, uint8_t *buf, int *lenptr)

{

    uint8_t iv[16] = { 0 }, hmac[20];

    int len = *lenptr;

    int ext, seq_largest;

    uint32_t ssrc, roc;

    uint64_t index;

    int rtcp;



    // TODO: Missing replay protection



    if (len < s->hmac_size)

        return AVERROR_INVALIDDATA;



    rtcp = RTP_PT_IS_RTCP(buf[1]);



    // Authentication HMAC

    av_hmac_init(s->hmac, rtcp ? s->rtcp_auth : s->rtp_auth, sizeof(s->rtp_auth));

    // If MKI is used, this should exclude the MKI as well

    av_hmac_update(s->hmac, buf, len - s->hmac_size);



    if (!rtcp) {

        int seq = AV_RB16(buf + 2);

        uint32_t v;

        uint8_t rocbuf[4];



        // RFC 3711 section 3.3.1, appendix A

        seq_largest = s->seq_initialized ? s->seq_largest : seq;

        v = roc = s->roc;

        if (seq_largest < 32768) {

            if (seq - seq_largest > 32768)

                v = roc - 1;

        } else {

            if (seq_largest - 32768 > seq)

                v = roc + 1;

        }

        if (v == roc) {

            seq_largest = FFMAX(seq_largest, seq);

        } else if (v == roc + 1) {

            seq_largest = seq;

            roc = v;

        }

        index = seq + (((uint64_t)v) << 16);



        AV_WB32(rocbuf, roc);

        av_hmac_update(s->hmac, rocbuf, 4);

    }



    av_hmac_final(s->hmac, hmac, sizeof(hmac));

    if (memcmp(hmac, buf + len - s->hmac_size, s->hmac_size)) {

        av_log(NULL, AV_LOG_WARNING, "HMAC mismatch\n");

        return AVERROR_INVALIDDATA;

    }



    len -= s->hmac_size;

    *lenptr = len;



    if (len < 12)

        return AVERROR_INVALIDDATA;



    if (rtcp) {

        uint32_t srtcp_index = AV_RB32(buf + len - 4);

        len -= 4;

        *lenptr = len;



        ssrc = AV_RB32(buf + 4);

        index = srtcp_index & 0x7fffffff;



        buf += 8;

        len -= 8;

        if (!(srtcp_index & 0x80000000))

            return 0;

    } else {

        s->seq_initialized = 1;

        s->seq_largest     = seq_largest;

        s->roc             = roc;



        ext  = buf[0] & 0x10;

        ssrc = AV_RB32(buf + 8);



        buf += 12;

        len -= 12;



        if (ext) {

            if (len < 4)

                return AVERROR_INVALIDDATA;

            ext = (AV_RB16(buf + 2) + 1) * 4;

            if (len < ext)

                return AVERROR_INVALIDDATA;

            len -= ext;

            buf += ext;

        }

    }



    create_iv(iv, rtcp ? s->rtcp_salt : s->rtp_salt, index, ssrc);

    av_aes_init(s->aes, rtcp ? s->rtcp_key : s->rtp_key, 128, 0);

    encrypt_counter(s->aes, iv, buf, len);



    return 0;

}

int qcow2_update_snapshot_refcount(BlockDriverState *bs,

    int64_t l1_table_offset, int l1_size, int addend)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t *l1_table, *l2_table, l2_offset, offset, l1_size2, refcount;

    bool l1_allocated = false;

    int64_t old_offset, old_l2_offset;

    int i, j, l1_modified = 0, nb_csectors;

    int ret;



    assert(addend >= -1 && addend <= 1);



    l2_table = NULL;

    l1_table = NULL;

    l1_size2 = l1_size * sizeof(uint64_t);



    s->cache_discards = true;



    /* WARNING: qcow2_snapshot_goto relies on this function not using the

     * l1_table_offset when it is the current s->l1_table_offset! Be careful

     * when changing this! */

    if (l1_table_offset != s->l1_table_offset) {

        l1_table = g_try_malloc0(align_offset(l1_size2, 512));

        if (l1_size2 && l1_table == NULL) {

            ret = -ENOMEM;

            goto fail;

        }

        l1_allocated = true;



        ret = bdrv_pread(bs->file, l1_table_offset, l1_table, l1_size2);

        if (ret < 0) {

            goto fail;

        }



        for(i = 0;i < l1_size; i++)

            be64_to_cpus(&l1_table[i]);

    } else {

        assert(l1_size == s->l1_size);

        l1_table = s->l1_table;

        l1_allocated = false;

    }



    for(i = 0; i < l1_size; i++) {

        l2_offset = l1_table[i];

        if (l2_offset) {

            old_l2_offset = l2_offset;

            l2_offset &= L1E_OFFSET_MASK;



            if (offset_into_cluster(s, l2_offset)) {

                qcow2_signal_corruption(bs, true, -1, -1, "L2 table offset %#"

                                        PRIx64 " unaligned (L1 index: %#x)",

                                        l2_offset, i);

                ret = -EIO;

                goto fail;

            }



            ret = qcow2_cache_get(bs, s->l2_table_cache, l2_offset,

                (void**) &l2_table);

            if (ret < 0) {

                goto fail;

            }



            for(j = 0; j < s->l2_size; j++) {

                uint64_t cluster_index;



                offset = be64_to_cpu(l2_table[j]);

                old_offset = offset;

                offset &= ~QCOW_OFLAG_COPIED;



                switch (qcow2_get_cluster_type(offset)) {

                    case QCOW2_CLUSTER_COMPRESSED:

                        nb_csectors = ((offset >> s->csize_shift) &

                                       s->csize_mask) + 1;

                        if (addend != 0) {

                            ret = update_refcount(bs,

                                (offset & s->cluster_offset_mask) & ~511,

                                nb_csectors * 512, abs(addend), addend < 0,

                                QCOW2_DISCARD_SNAPSHOT);

                            if (ret < 0) {

                                goto fail;

                            }

                        }

                        /* compressed clusters are never modified */

                        refcount = 2;

                        break;



                    case QCOW2_CLUSTER_NORMAL:

                    case QCOW2_CLUSTER_ZERO:

                        if (offset_into_cluster(s, offset & L2E_OFFSET_MASK)) {

                            qcow2_signal_corruption(bs, true, -1, -1, "Data "

                                                    "cluster offset %#llx "

                                                    "unaligned (L2 offset: %#"

                                                    PRIx64 ", L2 index: %#x)",

                                                    offset & L2E_OFFSET_MASK,

                                                    l2_offset, j);

                            ret = -EIO;

                            goto fail;

                        }



                        cluster_index = (offset & L2E_OFFSET_MASK) >> s->cluster_bits;

                        if (!cluster_index) {

                            /* unallocated */

                            refcount = 0;

                            break;

                        }

                        if (addend != 0) {

                            ret = qcow2_update_cluster_refcount(bs,

                                    cluster_index, abs(addend), addend < 0,

                                    QCOW2_DISCARD_SNAPSHOT);

                            if (ret < 0) {

                                goto fail;

                            }

                        }



                        ret = qcow2_get_refcount(bs, cluster_index, &refcount);

                        if (ret < 0) {

                            goto fail;

                        }

                        break;



                    case QCOW2_CLUSTER_UNALLOCATED:

                        refcount = 0;

                        break;



                    default:

                        abort();

                }



                if (refcount == 1) {

                    offset |= QCOW_OFLAG_COPIED;

                }

                if (offset != old_offset) {

                    if (addend > 0) {

                        qcow2_cache_set_dependency(bs, s->l2_table_cache,

                            s->refcount_block_cache);

                    }

                    l2_table[j] = cpu_to_be64(offset);

                    qcow2_cache_entry_mark_dirty(bs, s->l2_table_cache,

                                                 l2_table);

                }

            }



            qcow2_cache_put(bs, s->l2_table_cache, (void **) &l2_table);



            if (addend != 0) {

                ret = qcow2_update_cluster_refcount(bs, l2_offset >>

                                                        s->cluster_bits,

                                                    abs(addend), addend < 0,

                                                    QCOW2_DISCARD_SNAPSHOT);

                if (ret < 0) {

                    goto fail;

                }

            }

            ret = qcow2_get_refcount(bs, l2_offset >> s->cluster_bits,

                                     &refcount);

            if (ret < 0) {

                goto fail;

            } else if (refcount == 1) {

                l2_offset |= QCOW_OFLAG_COPIED;

            }

            if (l2_offset != old_l2_offset) {

                l1_table[i] = l2_offset;

                l1_modified = 1;

            }

        }

    }



    ret = bdrv_flush(bs);

fail:

    if (l2_table) {

        qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

    }



    s->cache_discards = false;

    qcow2_process_discards(bs, ret);



    /* Update L1 only if it isn't deleted anyway (addend = -1) */

    if (ret == 0 && addend >= 0 && l1_modified) {

        for (i = 0; i < l1_size; i++) {

            cpu_to_be64s(&l1_table[i]);

        }



        ret = bdrv_pwrite_sync(bs->file, l1_table_offset,

                               l1_table, l1_size2);



        for (i = 0; i < l1_size; i++) {

            be64_to_cpus(&l1_table[i]);

        }

    }

    if (l1_allocated)

        g_free(l1_table);

    return ret;

}

void ich9_pm_init(PCIDevice *lpc_pci, ICH9LPCPMRegs *pm,

                  qemu_irq sci_irq)

{

    memory_region_init(&pm->io, OBJECT(lpc_pci), "ich9-pm", ICH9_PMIO_SIZE);

    memory_region_set_enabled(&pm->io, false);

    memory_region_add_subregion(pci_address_space_io(lpc_pci),

                                0, &pm->io);



    acpi_pm_tmr_init(&pm->acpi_regs, ich9_pm_update_sci_fn, &pm->io);

    acpi_pm1_evt_init(&pm->acpi_regs, ich9_pm_update_sci_fn, &pm->io);

    acpi_pm1_cnt_init(&pm->acpi_regs, &pm->io, pm->s4_val);



    acpi_gpe_init(&pm->acpi_regs, ICH9_PMIO_GPE0_LEN);

    memory_region_init_io(&pm->io_gpe, OBJECT(lpc_pci), &ich9_gpe_ops, pm,

                          "acpi-gpe0", ICH9_PMIO_GPE0_LEN);

    memory_region_add_subregion(&pm->io, ICH9_PMIO_GPE0_STS, &pm->io_gpe);



    memory_region_init_io(&pm->io_smi, OBJECT(lpc_pci), &ich9_smi_ops, pm,

                          "acpi-smi", 8);

    memory_region_add_subregion(&pm->io, ICH9_PMIO_SMI_EN, &pm->io_smi);



    pm->irq = sci_irq;

    qemu_register_reset(pm_reset, pm);

    pm->powerdown_notifier.notify = pm_powerdown_req;

    qemu_register_powerdown_notifier(&pm->powerdown_notifier);



    acpi_cpu_hotplug_init(pci_address_space_io(lpc_pci), OBJECT(lpc_pci),

                          &pm->gpe_cpu, ICH9_CPU_HOTPLUG_IO_BASE);



    if (pm->acpi_memory_hotplug.is_enabled) {

        acpi_memory_hotplug_init(pci_address_space_io(lpc_pci), OBJECT(lpc_pci),

                                 &pm->acpi_memory_hotplug);

    }

}

