void ff_aac_search_for_ltp(AACEncContext *s, SingleChannelElement *sce,

                           int common_window)

{

    int w, g, w2, i, start = 0, count = 0;

    int saved_bits = -(15 + FFMIN(sce->ics.max_sfb, MAX_LTP_LONG_SFB));

    float *C34 = &s->scoefs[128*0], *PCD = &s->scoefs[128*1];

    float *PCD34 = &s->scoefs[128*2];

    const int max_ltp = FFMIN(sce->ics.max_sfb, MAX_LTP_LONG_SFB);



    if (sce->ics.window_sequence[0] == EIGHT_SHORT_SEQUENCE ||

        !sce->ics.ltp.lag)

        return;



    for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

        start = 0;

        for (g = 0;  g < sce->ics.num_swb; g++) {

            int bits1 = 0, bits2 = 0;

            float dist1 = 0.0f, dist2 = 0.0f;

            if (w*16+g > max_ltp) {

                start += sce->ics.swb_sizes[g];

                continue;

            }

            for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                int bits_tmp1, bits_tmp2;

                FFPsyBand *band = &s->psy.ch[s->cur_channel].psy_bands[(w+w2)*16+g];

                for (i = 0; i < sce->ics.swb_sizes[g]; i++)

                    PCD[i] = sce->coeffs[start+(w+w2)*128+i] - sce->lcoeffs[start+(w+w2)*128+i];

                abs_pow34_v(C34,  &sce->coeffs[start+(w+w2)*128],  sce->ics.swb_sizes[g]);

                abs_pow34_v(PCD34, PCD, sce->ics.swb_sizes[g]);

                dist1 += quantize_band_cost(s, &sce->coeffs[start+(w+w2)*128], C34, sce->ics.swb_sizes[g],

                                            sce->sf_idx[(w+w2)*16+g], sce->band_type[(w+w2)*16+g],

                                            s->lambda/band->threshold, INFINITY, &bits_tmp1, NULL, 0);

                dist2 += quantize_band_cost(s, PCD, PCD34, sce->ics.swb_sizes[g],

                                            sce->sf_idx[(w+w2)*16+g],

                                            sce->band_type[(w+w2)*16+g],

                                            s->lambda/band->threshold, INFINITY, &bits_tmp2, NULL, 0);

                bits1 += bits_tmp1;

                bits2 += bits_tmp2;

            }

            if (dist2 < dist1 && bits2 < bits1) {

                for (w2 = 0; w2 < sce->ics.group_len[w]; w2++)

                    for (i = 0; i < sce->ics.swb_sizes[g]; i++)

                        sce->coeffs[start+(w+w2)*128+i] -= sce->lcoeffs[start+(w+w2)*128+i];

                sce->ics.ltp.used[w*16+g] = 1;

                saved_bits += bits1 - bits2;

                count++;

            }

            start += sce->ics.swb_sizes[g];

        }

    }



    sce->ics.ltp.present = !!count && (saved_bits >= 0);

    sce->ics.predictor_present = !!sce->ics.ltp.present;



    /* Reset any marked sfbs */

    if (!sce->ics.ltp.present && !!count) {

        for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

            start = 0;

            for (g = 0;  g < sce->ics.num_swb; g++) {

                if (sce->ics.ltp.used[w*16+g]) {

                    for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                        for (i = 0; i < sce->ics.swb_sizes[g]; i++) {

                            sce->coeffs[start+(w+w2)*128+i] += sce->lcoeffs[start+(w+w2)*128+i];

                        }

                    }

                }

                start += sce->ics.swb_sizes[g];

            }

        }

    }

}

static void vfio_listener_region_del(MemoryListener *listener,

                                     MemoryRegionSection *section)

{

    VFIOContainer *container = container_of(listener, VFIOContainer,

                                            iommu_data.listener);

    hwaddr iova, end;

    int ret;



    if (vfio_listener_skipped_section(section)) {

        DPRINTF("SKIPPING region_del %"HWADDR_PRIx" - %"PRIx64"\n",

                section->offset_within_address_space,

                section->offset_within_address_space + section->size - 1);

        return;

    }



    if (unlikely((section->offset_within_address_space & ~TARGET_PAGE_MASK) !=

                 (section->offset_within_region & ~TARGET_PAGE_MASK))) {

        error_report("%s received unaligned region", __func__);

        return;

    }



    iova = TARGET_PAGE_ALIGN(section->offset_within_address_space);

    end = (section->offset_within_address_space + int128_get64(section->size)) &

          TARGET_PAGE_MASK;



    if (iova >= end) {

        return;

    }



    DPRINTF("region_del %"HWADDR_PRIx" - %"HWADDR_PRIx"\n",

            iova, end - 1);



    ret = vfio_dma_unmap(container, iova, end - iova);

    memory_region_unref(section->mr);

    if (ret) {

        error_report("vfio_dma_unmap(%p, 0x%"HWADDR_PRIx", "

                     "0x%"HWADDR_PRIx") = %d (%m)",

                     container, iova, end - iova, ret);

    }

}

static int ape_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    APEContext *s = avctx->priv_data;

    int16_t *samples = data;

    uint32_t nblocks;

    int i;

    int blockstodecode;

    int bytes_used;



    /* should not happen but who knows */

    if (BLOCKS_PER_LOOP * 2 * avctx->channels > *data_size) {

        av_log (avctx, AV_LOG_ERROR, "Output buffer is too small.\n");

        return AVERROR(EINVAL);

    }



    /* this should never be negative, but bad things will happen if it is, so

       check it just to make sure. */

    av_assert0(s->samples >= 0);



    if(!s->samples){

        uint32_t offset;

        void *tmp_data;



        if (buf_size < 8) {

            av_log(avctx, AV_LOG_ERROR, "Packet is too small\n");

            return AVERROR_INVALIDDATA;

        }



        tmp_data = av_realloc(s->data, FFALIGN(buf_size, 4));

        if (!tmp_data)

            return AVERROR(ENOMEM);

        s->data = tmp_data;

        s->dsp.bswap_buf((uint32_t*)s->data, (const uint32_t*)buf, buf_size >> 2);

        s->ptr = s->last_ptr = s->data;

        s->data_end = s->data + buf_size;



        nblocks = bytestream_get_be32(&s->ptr);

        offset  = bytestream_get_be32(&s->ptr);

        if (offset > 3) {

            av_log(avctx, AV_LOG_ERROR, "Incorrect offset passed\n");

            s->data = NULL;

            return AVERROR_INVALIDDATA;

        }

        if (s->data_end - s->ptr < offset) {

            av_log(avctx, AV_LOG_ERROR, "Packet is too small\n");

            return AVERROR_INVALIDDATA;

        }

        s->ptr += offset;



        if (!nblocks || nblocks > INT_MAX) {

            av_log(avctx, AV_LOG_ERROR, "Invalid sample count: %u.\n", nblocks);

            return AVERROR_INVALIDDATA;

        }

        s->samples = nblocks;



        memset(s->decoded0,  0, sizeof(s->decoded0));

        memset(s->decoded1,  0, sizeof(s->decoded1));



        /* Initialize the frame decoder */

        if (init_frame_decoder(s) < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error reading frame header\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (!s->data) {

        *data_size = 0;

        return buf_size;

    }



    nblocks = s->samples;

    blockstodecode = FFMIN(BLOCKS_PER_LOOP, nblocks);



    s->error=0;



    if ((s->channels == 1) || (s->frameflags & APE_FRAMECODE_PSEUDO_STEREO))

        ape_unpack_mono(s, blockstodecode);

    else

        ape_unpack_stereo(s, blockstodecode);

    emms_c();



    if (s->error) {

        s->samples=0;

        av_log(avctx, AV_LOG_ERROR, "Error decoding frame\n");

        return AVERROR_INVALIDDATA;

    }



    for (i = 0; i < blockstodecode; i++) {

        *samples++ = s->decoded0[i];

        if(s->channels == 2)

            *samples++ = s->decoded1[i];

    }



    s->samples -= blockstodecode;



    *data_size = blockstodecode * 2 * s->channels;

    bytes_used = s->samples ? s->ptr - s->last_ptr : buf_size;

    s->last_ptr = s->ptr;

    return bytes_used;

}

static int unpack_vectors(Vp3DecodeContext *s, GetBitContext *gb)

{

    int j, k, l, sb_x, sb_y;

    int coding_mode;

    int motion_x[6];

    int motion_y[6];

    int last_motion_x = 0;

    int last_motion_y = 0;

    int prior_last_motion_x = 0;

    int prior_last_motion_y = 0;

    int current_macroblock;

    int current_fragment;



    if (s->keyframe)

        return 0;



    memset(motion_x, 0, 6 * sizeof(int));

    memset(motion_y, 0, 6 * sizeof(int));



    /* coding mode 0 is the VLC scheme; 1 is the fixed code scheme */

    coding_mode = get_bits1(gb);



    /* iterate through all of the macroblocks that contain 1 or more

     * coded fragments */

    for (sb_y = 0; sb_y < s->y_superblock_height; sb_y++) {

        for (sb_x = 0; sb_x < s->y_superblock_width; sb_x++) {



        for (j = 0; j < 4; j++) {

            int mb_x = 2*sb_x +   (j>>1);

            int mb_y = 2*sb_y + (((j>>1)+j)&1);

            current_macroblock = mb_y * s->macroblock_width + mb_x;



            if (mb_x >= s->macroblock_width || mb_y >= s->macroblock_height ||

                (s->macroblock_coding[current_macroblock] == MODE_COPY))

                continue;



            switch (s->macroblock_coding[current_macroblock]) {



            case MODE_INTER_PLUS_MV:

            case MODE_GOLDEN_MV:

                /* all 6 fragments use the same motion vector */

                if (coding_mode == 0) {

                    motion_x[0] = motion_vector_table[get_vlc2(gb, s->motion_vector_vlc.table, 6, 2)];

                    motion_y[0] = motion_vector_table[get_vlc2(gb, s->motion_vector_vlc.table, 6, 2)];

                } else {

                    motion_x[0] = fixed_motion_vector_table[get_bits(gb, 6)];

                    motion_y[0] = fixed_motion_vector_table[get_bits(gb, 6)];

                }



                /* vector maintenance, only on MODE_INTER_PLUS_MV */

                if (s->macroblock_coding[current_macroblock] ==

                    MODE_INTER_PLUS_MV) {

                    prior_last_motion_x = last_motion_x;

                    prior_last_motion_y = last_motion_y;

                    last_motion_x = motion_x[0];

                    last_motion_y = motion_y[0];

                }

                break;



            case MODE_INTER_FOURMV:

                /* vector maintenance */

                prior_last_motion_x = last_motion_x;

                prior_last_motion_y = last_motion_y;



                /* fetch 4 vectors from the bitstream, one for each

                 * Y fragment, then average for the C fragment vectors */

                motion_x[4] = motion_y[4] = 0;

                for (k = 0; k < 4; k++) {

                    current_fragment = BLOCK_Y*s->fragment_width + BLOCK_X;

                    for (l = 0; l < s->coded_fragment_list_index; l++)

                        if (s->coded_fragment_list[l] == current_fragment)

                            break;

                    if (l < s->coded_fragment_list_index) {

                        if (coding_mode == 0) {

                            motion_x[k] = motion_vector_table[get_vlc2(gb, s->motion_vector_vlc.table, 6, 2)];

                            motion_y[k] = motion_vector_table[get_vlc2(gb, s->motion_vector_vlc.table, 6, 2)];

                        } else {

                            motion_x[k] = fixed_motion_vector_table[get_bits(gb, 6)];

                            motion_y[k] = fixed_motion_vector_table[get_bits(gb, 6)];

                        }

                        last_motion_x = motion_x[k];

                        last_motion_y = motion_y[k];

                    } else {

                        motion_x[k] = 0;

                        motion_y[k] = 0;

                    }

                    motion_x[4] += motion_x[k];

                    motion_y[4] += motion_y[k];

                }



                motion_x[5]=

                motion_x[4]= RSHIFT(motion_x[4], 2);

                motion_y[5]=

                motion_y[4]= RSHIFT(motion_y[4], 2);

                break;



            case MODE_INTER_LAST_MV:

                /* all 6 fragments use the last motion vector */

                motion_x[0] = last_motion_x;

                motion_y[0] = last_motion_y;



                /* no vector maintenance (last vector remains the

                 * last vector) */

                break;



            case MODE_INTER_PRIOR_LAST:

                /* all 6 fragments use the motion vector prior to the

                 * last motion vector */

                motion_x[0] = prior_last_motion_x;

                motion_y[0] = prior_last_motion_y;



                /* vector maintenance */

                prior_last_motion_x = last_motion_x;

                prior_last_motion_y = last_motion_y;

                last_motion_x = motion_x[0];

                last_motion_y = motion_y[0];

                break;



            default:

                /* covers intra, inter without MV, golden without MV */

                motion_x[0] = 0;

                motion_y[0] = 0;



                /* no vector maintenance */

                break;

            }



            /* assign the motion vectors to the correct fragments */

            for (k = 0; k < 4; k++) {

                current_fragment =

                    BLOCK_Y*s->fragment_width + BLOCK_X;

                if (s->macroblock_coding[current_macroblock] == MODE_INTER_FOURMV) {

                    s->all_fragments[current_fragment].motion_x = motion_x[k];

                    s->all_fragments[current_fragment].motion_y = motion_y[k];

                } else {

                    s->all_fragments[current_fragment].motion_x = motion_x[0];

                    s->all_fragments[current_fragment].motion_y = motion_y[0];

                }

            }

            for (k = 0; k < 2; k++) {

                current_fragment = s->fragment_start[k+1] +

                    mb_y*(s->fragment_width>>1) + mb_x;

                if (s->macroblock_coding[current_macroblock] == MODE_INTER_FOURMV) {

                    s->all_fragments[current_fragment].motion_x = motion_x[k+4];

                    s->all_fragments[current_fragment].motion_y = motion_y[k+4];

                } else {

                    s->all_fragments[current_fragment].motion_x = motion_x[0];

                    s->all_fragments[current_fragment].motion_y = motion_y[0];

                }

            }

        }

        }

    }



    return 0;

}

static int flac_decode_frame(AVCodecContext *avctx,

                            void *data, int *data_size,

                            uint8_t *buf, int buf_size)

{

    FLACContext *s = avctx->priv_data;

    int metadata_last, metadata_type, metadata_size;

    int tmp = 0, i, j = 0, input_buf_size;

    int16_t *samples = data, *left, *right;



    *data_size = 0;



    s->avctx = avctx;



    if(s->max_framesize == 0){

        s->max_framesize= 8192; // should hopefully be enough for the first header

        s->bitstream= av_fast_realloc(s->bitstream, &s->allocated_bitstream_size, s->max_framesize);

    }



    if(1 && s->max_framesize){//FIXME truncated

            buf_size= FFMIN(buf_size, s->max_framesize - s->bitstream_size);

            input_buf_size= buf_size;



            if(s->bitstream_index + s->bitstream_size + buf_size > s->allocated_bitstream_size){

//                printf("memmove\n");

                memmove(s->bitstream, &s->bitstream[s->bitstream_index], s->bitstream_size);

                s->bitstream_index=0;

            }

            memcpy(&s->bitstream[s->bitstream_index + s->bitstream_size], buf, buf_size);

            buf= &s->bitstream[s->bitstream_index];

            buf_size += s->bitstream_size;

            s->bitstream_size= buf_size;



            if(buf_size < s->max_framesize){

//                printf("wanna more data ...\n");

                return input_buf_size;

            }

    }



    init_get_bits(&s->gb, buf, buf_size*8);



    /* fLaC signature (be) */

    if (show_bits_long(&s->gb, 32) == bswap_32(ff_get_fourcc("fLaC")))

    {

        skip_bits(&s->gb, 32);



        av_log(s->avctx, AV_LOG_DEBUG, "STREAM HEADER\n");

        do {

            metadata_last = get_bits(&s->gb, 1);

            metadata_type = get_bits(&s->gb, 7);

            metadata_size = get_bits_long(&s->gb, 24);



            av_log(s->avctx, AV_LOG_DEBUG, " metadata block: flag = %d, type = %d, size = %d\n",

                metadata_last, metadata_type,

                metadata_size);

            if(metadata_size){

                switch(metadata_type)

                {

                case METADATA_TYPE_STREAMINFO:

                    if(metadata_size == 0)

                        av_log(s->avctx, AV_LOG_DEBUG, "size= 0 WTF!?\n");



                    metadata_streaminfo(s);

                    dump_headers(s);

                    break;

                default:

                    for(i=0; i<metadata_size; i++)

                        skip_bits(&s->gb, 8);

                }

            }

        } while(!metadata_last);

    }

    else

    {



         tmp = show_bits(&s->gb, 16);

        if(tmp != 0xFFF8){

            av_log(s->avctx, AV_LOG_ERROR, "FRAME HEADER not here\n");

            while(get_bits_count(&s->gb)/8+2 < buf_size && show_bits(&s->gb, 16) != 0xFFF8)

                skip_bits(&s->gb, 8);

            goto end; // we may not have enough bits left to decode a frame, so try next time

        }

        skip_bits(&s->gb, 16);

        if (decode_frame(s) < 0)

            return -1;

    }





#if 0

    /* fix the channel order here */

    if (s->order == MID_SIDE)

    {

        short *left = samples;

        short *right = samples + s->blocksize;

        for (i = 0; i < s->blocksize; i += 2)

        {

            uint32_t x = s->decoded[0][i];

            uint32_t y = s->decoded[0][i+1];



            right[i] = x - (y / 2);

            left[i] = right[i] + y;

        }

        *data_size = 2 * s->blocksize;

    }

    else

    {

    for (i = 0; i < s->channels; i++)

    {

        switch(s->order)

        {

            case INDEPENDENT:

                for (j = 0; j < s->blocksize; j++)

                    samples[(s->blocksize*i)+j] = s->decoded[i][j];

                break;

            case LEFT_SIDE:

            case RIGHT_SIDE:

                if (i == 0)

                    for (j = 0; j < s->blocksize; j++)

                        samples[(s->blocksize*i)+j] = s->decoded[0][j];

                else

                    for (j = 0; j < s->blocksize; j++)

                        samples[(s->blocksize*i)+j] = s->decoded[0][j] - s->decoded[i][j];

                break;

//            case MID_SIDE:

//                av_log(s->avctx, AV_LOG_DEBUG, "mid-side unsupported\n");

        }

        *data_size += s->blocksize;

    }

    }

#else

    switch(s->order)

    {

        case INDEPENDENT:

            for (j = 0; j < s->blocksize; j++)

            {

                for (i = 0; i < s->channels; i++)

                    *(samples++) = s->decoded[i][j];

            }

            break;

        case LEFT_SIDE:

            assert(s->channels == 2);

            for (i = 0; i < s->blocksize; i++)

            {

                *(samples++) = s->decoded[0][i];

                *(samples++) = s->decoded[0][i] - s->decoded[1][i];

            }

            break;

        case RIGHT_SIDE:

            assert(s->channels == 2);

            for (i = 0; i < s->blocksize; i++)

            {

                *(samples++) = s->decoded[0][i] + s->decoded[1][i];

                *(samples++) = s->decoded[1][i];

            }

            break;

        case MID_SIDE:

            assert(s->channels == 2);

            for (i = 0; i < s->blocksize; i++)

            {

                int mid, side;

                mid = s->decoded[0][i];

                side = s->decoded[1][i];



                mid <<= 1;

                if (side & 1)

                    mid++;

                *(samples++) = (mid + side) >> 1;

                *(samples++) = (mid - side) >> 1;

            }

            break;

    }

#endif



    *data_size = (int8_t *)samples - (int8_t *)data;

    av_log(s->avctx, AV_LOG_DEBUG, "data size: %d\n", *data_size);



//    s->last_blocksize = s->blocksize;

end:

    i= (get_bits_count(&s->gb)+7)/8;;

    if(i > buf_size){

        av_log(s->avctx, AV_LOG_ERROR, "overread: %d\n", i - buf_size);

        return -1;

    }



    if(s->bitstream_size){

        s->bitstream_index += i;

        s->bitstream_size  -= i;

        return input_buf_size;

    }else 

        return i;

}

static void mp_decode_frame_helper(MotionPixelsContext *mp, GetBitContext *gb)
{
    YuvPixel p;
    int y, y0;
    for (y = 0; y < mp->avctx->height; ++y) {
        if (mp->changes_map[y * mp->avctx->width] != 0) {
            memset(mp->gradient_scale, 1, sizeof(mp->gradient_scale));
            p = mp_get_yuv_from_rgb(mp, 0, y);
        } else {
            p.y += mp_gradient(mp, 0, mp_get_vlc(mp, gb));
            p.y = av_clip(p.y, 0, 31);
            if ((y & 3) == 0) {
                p.v += mp_gradient(mp, 1, mp_get_vlc(mp, gb));
                p.v = av_clip(p.v, -32, 31);
                p.u += mp_gradient(mp, 2, mp_get_vlc(mp, gb));
                p.u = av_clip(p.u, -32, 31);
            }
            mp->vpt[y] = p;
            mp_set_rgb_from_yuv(mp, 0, y, &p);
        }
    }
    for (y0 = 0; y0 < 2; ++y0)
        for (y = y0; y < mp->avctx->height; y += 2)
            mp_decode_line(mp, gb, y);
}

static void qemu_aio_complete(void *opaque, int ret)

{

    struct ioreq *ioreq = opaque;



    if (ret != 0) {

        xen_be_printf(&ioreq->blkdev->xendev, 0, "%s I/O error\n",

                      ioreq->req.operation == BLKIF_OP_READ ? "read" : "write");

        ioreq->aio_errors++;

    }



    ioreq->aio_inflight--;

    if (ioreq->presync) {

        ioreq->presync = 0;

        ioreq_runio_qemu_aio(ioreq);

        return;

    }

    if (ioreq->aio_inflight > 0) {

        return;

    }

    if (ioreq->postsync) {

        ioreq->postsync = 0;

        ioreq->aio_inflight++;

        blk_aio_flush(ioreq->blkdev->blk, qemu_aio_complete, ioreq);

        return;

    }



    ioreq->status = ioreq->aio_errors ? BLKIF_RSP_ERROR : BLKIF_RSP_OKAY;

    ioreq_unmap(ioreq);

    ioreq_finish(ioreq);

    switch (ioreq->req.operation) {

    case BLKIF_OP_WRITE:

    case BLKIF_OP_FLUSH_DISKCACHE:

        if (!ioreq->req.nr_segments) {

            break;

        }

    case BLKIF_OP_READ:

        block_acct_done(blk_get_stats(ioreq->blkdev->blk), &ioreq->acct);

        break;

    case BLKIF_OP_DISCARD:

    default:

        break;

    }

    qemu_bh_schedule(ioreq->blkdev->bh);

}

void esp_init(target_phys_addr_t espaddr, int it_shift,

              ESPDMAMemoryReadWriteFunc dma_memory_read,

              ESPDMAMemoryReadWriteFunc dma_memory_write,

              void *dma_opaque, qemu_irq irq, qemu_irq *reset,

              qemu_irq *dma_enable)

{

    DeviceState *dev;

    SysBusDevice *s;

    SysBusESPState *sysbus;

    ESPState *esp;



    dev = qdev_create(NULL, "esp");

    sysbus = DO_UPCAST(SysBusESPState, busdev.qdev, dev);

    esp = &sysbus->esp;

    esp->dma_memory_read = dma_memory_read;

    esp->dma_memory_write = dma_memory_write;

    esp->dma_opaque = dma_opaque;

    sysbus->it_shift = it_shift;

    /* XXX for now until rc4030 has been changed to use DMA enable signal */

    esp->dma_enabled = 1;

    qdev_init_nofail(dev);

    s = sysbus_from_qdev(dev);

    sysbus_connect_irq(s, 0, irq);

    sysbus_mmio_map(s, 0, espaddr);

    *reset = qdev_get_gpio_in(dev, 0);

    *dma_enable = qdev_get_gpio_in(dev, 1);

}

static int rtc_initfn(ISADevice *dev)

{

    RTCState *s = DO_UPCAST(RTCState, dev, dev);

    int base = 0x70;

    int isairq = 8;



    isa_init_irq(dev, &s->irq, isairq);



    s->cmos_data[RTC_REG_A] = 0x26;

    s->cmos_data[RTC_REG_B] = 0x02;

    s->cmos_data[RTC_REG_C] = 0x00;

    s->cmos_data[RTC_REG_D] = 0x80;



    rtc_set_date_from_host(s);



    s->periodic_timer = qemu_new_timer(rtc_clock, rtc_periodic_timer, s);

#ifdef TARGET_I386

    if (rtc_td_hack)

        s->coalesced_timer =

            qemu_new_timer(rtc_clock, rtc_coalesced_timer, s);

#endif

    s->second_timer = qemu_new_timer(rtc_clock, rtc_update_second, s);

    s->second_timer2 = qemu_new_timer(rtc_clock, rtc_update_second2, s);



    s->next_second_time =

        qemu_get_clock(rtc_clock) + (get_ticks_per_sec() * 99) / 100;

    qemu_mod_timer(s->second_timer2, s->next_second_time);



    register_ioport_write(base, 2, 1, cmos_ioport_write, s);

    register_ioport_read(base, 2, 1, cmos_ioport_read, s);



    register_savevm("mc146818rtc", base, 1, rtc_save, rtc_load, s);

#ifdef TARGET_I386

    if (rtc_td_hack)

        register_savevm("mc146818rtc-td", base, 1, rtc_save_td, rtc_load_td, s);

#endif

    qemu_register_reset(rtc_reset, s);

    return 0;

}

static int get_pci_config_device(QEMUFile *f, void *pv, size_t size)

{

    PCIDevice *s = container_of(pv, PCIDevice, config);

    uint8_t config[size];

    int i;



    qemu_get_buffer(f, config, size);

    for (i = 0; i < size; ++i)

        if ((config[i] ^ s->config[i]) & s->cmask[i] & ~s->wmask[i])

            return -EINVAL;

    memcpy(s->config, config, size);



    pci_update_mappings(s);



    return 0;

}

static int asf_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    ASFContext *asf = s->priv_data;

    ff_asf_guid g;

    ByteIOContext *pb = s->pb;

    AVStream *st;

    ASFStream *asf_st;

    int size, i;

    int64_t gsize;

    AVRational dar[128];

    uint32_t bitrate[128];



    memset(dar, 0, sizeof(dar));

    memset(bitrate, 0, sizeof(bitrate));



    get_guid(pb, &g);

    if (guidcmp(&g, &ff_asf_header))

        return -1;

    get_le64(pb);

    get_le32(pb);

    get_byte(pb);

    get_byte(pb);

    memset(&asf->asfid2avid, -1, sizeof(asf->asfid2avid));

    for(;;) {

        uint64_t gpos= url_ftell(pb);

        get_guid(pb, &g);

        gsize = get_le64(pb);

        dprintf(s, "%08"PRIx64": ", gpos);

        print_guid(&g);

        dprintf(s, "  size=0x%"PRIx64"\n", gsize);

        if (!guidcmp(&g, &ff_asf_data_header)) {

            asf->data_object_offset = url_ftell(pb);

            // if not streaming, gsize is not unlimited (how?), and there is enough space in the file..

            if (!(asf->hdr.flags & 0x01) && gsize >= 100) {

                asf->data_object_size = gsize - 24;

            } else {

                asf->data_object_size = (uint64_t)-1;

            }

            break;

        }

        if (gsize < 24)

            return -1;

        if (!guidcmp(&g, &ff_asf_file_header)) {

            get_guid(pb, &asf->hdr.guid);

            asf->hdr.file_size          = get_le64(pb);

            asf->hdr.create_time        = get_le64(pb);

            asf->nb_packets             = get_le64(pb);

            asf->hdr.play_time          = get_le64(pb);

            asf->hdr.send_time          = get_le64(pb);

            asf->hdr.preroll            = get_le32(pb);

            asf->hdr.ignore             = get_le32(pb);

            asf->hdr.flags              = get_le32(pb);

            asf->hdr.min_pktsize        = get_le32(pb);

            asf->hdr.max_pktsize        = get_le32(pb);

            asf->hdr.max_bitrate        = get_le32(pb);

            s->packet_size = asf->hdr.max_pktsize;

        } else if (!guidcmp(&g, &ff_asf_stream_header)) {

            enum AVMediaType type;

            int type_specific_size, sizeX;

            uint64_t total_size;

            unsigned int tag1;

            int64_t pos1, pos2, start_time;

            int test_for_ext_stream_audio, is_dvr_ms_audio=0;



            if (s->nb_streams == ASF_MAX_STREAMS) {

                av_log(s, AV_LOG_ERROR, "too many streams\n");

                return AVERROR(EINVAL);

            }



            pos1 = url_ftell(pb);



            st = av_new_stream(s, 0);

            if (!st)

                return AVERROR(ENOMEM);

            av_set_pts_info(st, 32, 1, 1000); /* 32 bit pts in ms */

            asf_st = av_mallocz(sizeof(ASFStream));

            if (!asf_st)

                return AVERROR(ENOMEM);

            st->priv_data = asf_st;

            start_time = asf->hdr.preroll;



            asf_st->stream_language_index = 128; // invalid stream index means no language info



            if(!(asf->hdr.flags & 0x01)) { // if we aren't streaming...

                st->duration = asf->hdr.play_time /

                    (10000000 / 1000) - start_time;

            }

            get_guid(pb, &g);



            test_for_ext_stream_audio = 0;

            if (!guidcmp(&g, &ff_asf_audio_stream)) {

                type = AVMEDIA_TYPE_AUDIO;

            } else if (!guidcmp(&g, &ff_asf_video_stream)) {

                type = AVMEDIA_TYPE_VIDEO;

            } else if (!guidcmp(&g, &ff_asf_command_stream)) {

                type = AVMEDIA_TYPE_DATA;

            } else if (!guidcmp(&g, &ff_asf_ext_stream_embed_stream_header)) {

                test_for_ext_stream_audio = 1;

                type = AVMEDIA_TYPE_UNKNOWN;

            } else {

                return -1;

            }

            get_guid(pb, &g);

            total_size = get_le64(pb);

            type_specific_size = get_le32(pb);

            get_le32(pb);

            st->id = get_le16(pb) & 0x7f; /* stream id */

            // mapping of asf ID to AV stream ID;

            asf->asfid2avid[st->id] = s->nb_streams - 1;



            get_le32(pb);



            if (test_for_ext_stream_audio) {

                get_guid(pb, &g);

                if (!guidcmp(&g, &ff_asf_ext_stream_audio_stream)) {

                    type = AVMEDIA_TYPE_AUDIO;

                    is_dvr_ms_audio=1;

                    get_guid(pb, &g);

                    get_le32(pb);

                    get_le32(pb);

                    get_le32(pb);

                    get_guid(pb, &g);

                    get_le32(pb);

                }

            }



            st->codec->codec_type = type;

            if (type == AVMEDIA_TYPE_AUDIO) {

                ff_get_wav_header(pb, st->codec, type_specific_size);

                if (is_dvr_ms_audio) {

                    // codec_id and codec_tag are unreliable in dvr_ms

                    // files. Set them later by probing stream.

                    st->codec->codec_id = CODEC_ID_PROBE;

                    st->codec->codec_tag = 0;

                }

                if (st->codec->codec_id == CODEC_ID_AAC) {

                    st->need_parsing = AVSTREAM_PARSE_NONE;

                } else {

                    st->need_parsing = AVSTREAM_PARSE_FULL;

                }

                /* We have to init the frame size at some point .... */

                pos2 = url_ftell(pb);

                if (gsize >= (pos2 + 8 - pos1 + 24)) {

                    asf_st->ds_span = get_byte(pb);

                    asf_st->ds_packet_size = get_le16(pb);

                    asf_st->ds_chunk_size = get_le16(pb);

                    get_le16(pb); //ds_data_size

                    get_byte(pb); //ds_silence_data

                }

                //printf("Descrambling: ps:%d cs:%d ds:%d s:%d  sd:%d\n",

                //       asf_st->ds_packet_size, asf_st->ds_chunk_size,

                //       asf_st->ds_data_size, asf_st->ds_span, asf_st->ds_silence_data);

                if (asf_st->ds_span > 1) {

                    if (!asf_st->ds_chunk_size

                        || (asf_st->ds_packet_size/asf_st->ds_chunk_size <= 1)

                        || asf_st->ds_packet_size % asf_st->ds_chunk_size)

                        asf_st->ds_span = 0; // disable descrambling

                }

                switch (st->codec->codec_id) {

                case CODEC_ID_MP3:

                    st->codec->frame_size = MPA_FRAME_SIZE;

                    break;

                case CODEC_ID_PCM_S16LE:

                case CODEC_ID_PCM_S16BE:

                case CODEC_ID_PCM_U16LE:

                case CODEC_ID_PCM_U16BE:

                case CODEC_ID_PCM_S8:

                case CODEC_ID_PCM_U8:

                case CODEC_ID_PCM_ALAW:

                case CODEC_ID_PCM_MULAW:

                    st->codec->frame_size = 1;

                    break;

                default:

                    /* This is probably wrong, but it prevents a crash later */

                    st->codec->frame_size = 1;

                    break;

                }

            } else if (type == AVMEDIA_TYPE_VIDEO) {

                get_le32(pb);

                get_le32(pb);

                get_byte(pb);

                size = get_le16(pb); /* size */

                sizeX= get_le32(pb); /* size */

                st->codec->width = get_le32(pb);

                st->codec->height = get_le32(pb);

                /* not available for asf */

                get_le16(pb); /* panes */

                st->codec->bits_per_coded_sample = get_le16(pb); /* depth */

                tag1 = get_le32(pb);

                url_fskip(pb, 20);

//                av_log(s, AV_LOG_DEBUG, "size:%d tsize:%d sizeX:%d\n", size, total_size, sizeX);

                size= sizeX;

                if (size > 40) {

                    st->codec->extradata_size = size - 40;

                    st->codec->extradata = av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                    get_buffer(pb, st->codec->extradata, st->codec->extradata_size);

                }



                /* Extract palette from extradata if bpp <= 8 */

                /* This code assumes that extradata contains only palette */

                /* This is true for all paletted codecs implemented in ffmpeg */

                if (st->codec->extradata_size && (st->codec->bits_per_coded_sample <= 8)) {

                    st->codec->palctrl = av_mallocz(sizeof(AVPaletteControl));

#if HAVE_BIGENDIAN

                    for (i = 0; i < FFMIN(st->codec->extradata_size, AVPALETTE_SIZE)/4; i++)

                        st->codec->palctrl->palette[i] = bswap_32(((uint32_t*)st->codec->extradata)[i]);

#else

                    memcpy(st->codec->palctrl->palette, st->codec->extradata,

                           FFMIN(st->codec->extradata_size, AVPALETTE_SIZE));

#endif

                    st->codec->palctrl->palette_changed = 1;

                }



                st->codec->codec_tag = tag1;

                st->codec->codec_id = ff_codec_get_id(ff_codec_bmp_tags, tag1);

                if(tag1 == MKTAG('D', 'V', 'R', ' '))

                    st->need_parsing = AVSTREAM_PARSE_FULL;

                if(st->codec->codec_id == CODEC_ID_H264)

                    st->need_parsing = AVSTREAM_PARSE_FULL_ONCE;

            }

            pos2 = url_ftell(pb);

            url_fskip(pb, gsize - (pos2 - pos1 + 24));

        } else if (!guidcmp(&g, &ff_asf_comment_header)) {

            int len1, len2, len3, len4, len5;



            len1 = get_le16(pb);

            len2 = get_le16(pb);

            len3 = get_le16(pb);

            len4 = get_le16(pb);

            len5 = get_le16(pb);

            get_tag(s, "title"    , 0, len1);

            get_tag(s, "author"   , 0, len2);

            get_tag(s, "copyright", 0, len3);

            get_tag(s, "comment"  , 0, len4);

            url_fskip(pb, len5);

        } else if (!guidcmp(&g, &stream_bitrate_guid)) {

            int stream_count = get_le16(pb);

            int j;



//            av_log(s, AV_LOG_ERROR, "stream bitrate properties\n");

//            av_log(s, AV_LOG_ERROR, "streams %d\n", streams);

            for(j = 0; j < stream_count; j++) {

                int flags, bitrate, stream_id;



                flags= get_le16(pb);

                bitrate= get_le32(pb);

                stream_id= (flags & 0x7f);

//                av_log(s, AV_LOG_ERROR, "flags: 0x%x stream id %d, bitrate %d\n", flags, stream_id, bitrate);

                asf->stream_bitrates[stream_id]= bitrate;

            }

        } else if (!guidcmp(&g, &ff_asf_language_guid)) {

            int j;

            int stream_count = get_le16(pb);

            for(j = 0; j < stream_count; j++) {

                char lang[6];

                unsigned int lang_len = get_byte(pb);

                get_str16_nolen(pb, lang_len, lang, sizeof(lang));

                if (j < 128)

                    av_strlcpy(asf->stream_languages[j], lang, sizeof(*asf->stream_languages));

            }

        } else if (!guidcmp(&g, &ff_asf_extended_content_header)) {

            int desc_count, i;



            desc_count = get_le16(pb);

            for(i=0;i<desc_count;i++) {

                    int name_len,value_type,value_len;

                    char name[1024];



                    name_len = get_le16(pb);

                    if (name_len%2)     // must be even, broken lavf versions wrote len-1

                        name_len += 1;

                    get_str16_nolen(pb, name_len, name, sizeof(name));

                    value_type = get_le16(pb);

                    value_len  = get_le16(pb);

                    if (!value_type && value_len%2)

                        value_len += 1;

                    get_tag(s, name, value_type, value_len);

            }

        } else if (!guidcmp(&g, &ff_asf_metadata_header)) {

            int n, stream_num, name_len, value_len, value_type, value_num;

            n = get_le16(pb);



            for(i=0;i<n;i++) {

                char name[1024];



                get_le16(pb); //lang_list_index

                stream_num= get_le16(pb);

                name_len=   get_le16(pb);

                value_type= get_le16(pb);

                value_len=  get_le32(pb);



                get_str16_nolen(pb, name_len, name, sizeof(name));

//av_log(s, AV_LOG_ERROR, "%d %d %d %d %d <%s>\n", i, stream_num, name_len, value_type, value_len, name);

                value_num= get_le16(pb);//we should use get_value() here but it does not work 2 is le16 here but le32 elsewhere

                url_fskip(pb, value_len - 2);



                if(stream_num<128){

                    if     (!strcmp(name, "AspectRatioX")) dar[stream_num].num= value_num;

                    else if(!strcmp(name, "AspectRatioY")) dar[stream_num].den= value_num;

                }

            }

        } else if (!guidcmp(&g, &ff_asf_ext_stream_header)) {

            int ext_len, payload_ext_ct, stream_ct;

            uint32_t ext_d, leak_rate, stream_num;

            unsigned int stream_languageid_index;



            get_le64(pb); // starttime

            get_le64(pb); // endtime

            leak_rate = get_le32(pb); // leak-datarate

            get_le32(pb); // bucket-datasize

            get_le32(pb); // init-bucket-fullness

            get_le32(pb); // alt-leak-datarate

            get_le32(pb); // alt-bucket-datasize

            get_le32(pb); // alt-init-bucket-fullness

            get_le32(pb); // max-object-size

            get_le32(pb); // flags (reliable,seekable,no_cleanpoints?,resend-live-cleanpoints, rest of bits reserved)

            stream_num = get_le16(pb); // stream-num



            stream_languageid_index = get_le16(pb); // stream-language-id-index

            if (stream_num < 128)

                asf->streams[stream_num].stream_language_index = stream_languageid_index;



            get_le64(pb); // avg frametime in 100ns units

            stream_ct = get_le16(pb); //stream-name-count

            payload_ext_ct = get_le16(pb); //payload-extension-system-count



            if (stream_num < 128)

                bitrate[stream_num] = leak_rate;



            for (i=0; i<stream_ct; i++){

                get_le16(pb);

                ext_len = get_le16(pb);

                url_fseek(pb, ext_len, SEEK_CUR);

            }



            for (i=0; i<payload_ext_ct; i++){

                get_guid(pb, &g);

                ext_d=get_le16(pb);

                ext_len=get_le32(pb);

                url_fseek(pb, ext_len, SEEK_CUR);

            }



            // there could be a optional stream properties object to follow

            // if so the next iteration will pick it up

            continue;

        } else if (!guidcmp(&g, &ff_asf_head1_guid)) {

            int v1, v2;

            get_guid(pb, &g);

            v1 = get_le32(pb);

            v2 = get_le16(pb);

            continue;

        } else if (!guidcmp(&g, &ff_asf_marker_header)) {

            int i, count, name_len;

            char name[1024];



            get_le64(pb);            // reserved 16 bytes

            get_le64(pb);            // ...

            count = get_le32(pb);    // markers count

            get_le16(pb);            // reserved 2 bytes

            name_len = get_le16(pb); // name length

            for(i=0;i<name_len;i++){

                get_byte(pb); // skip the name

            }



            for(i=0;i<count;i++){

                int64_t pres_time;

                int name_len;



                get_le64(pb);             // offset, 8 bytes

                pres_time = get_le64(pb); // presentation time

                get_le16(pb);             // entry length

                get_le32(pb);             // send time

                get_le32(pb);             // flags

                name_len = get_le32(pb);  // name length

                get_str16_nolen(pb, name_len * 2, name, sizeof(name));

                ff_new_chapter(s, i, (AVRational){1, 10000000}, pres_time, AV_NOPTS_VALUE, name );

            }

#if 0

        } else if (!guidcmp(&g, &ff_asf_codec_comment_header)) {

            int len, v1, n, num;

            char str[256], *q;

            char tag[16];



            get_guid(pb, &g);

            print_guid(&g);



            n = get_le32(pb);

            for(i=0;i<n;i++) {

                num = get_le16(pb); /* stream number */

                get_str16(pb, str, sizeof(str));

                get_str16(pb, str, sizeof(str));

                len = get_le16(pb);

                q = tag;

                while (len > 0) {

                    v1 = get_byte(pb);

                    if ((q - tag) < sizeof(tag) - 1)

                        *q++ = v1;

                    len--;

                }

                *q = '\0';

            }

#endif

        } else if (url_feof(pb)) {

            return -1;

        } else {

            if (!s->keylen) {

                if (!guidcmp(&g, &ff_asf_content_encryption)) {

                    av_log(s, AV_LOG_WARNING, "DRM protected stream detected, decoding will likely fail!\n");

                } else if (!guidcmp(&g, &ff_asf_ext_content_encryption)) {

                    av_log(s, AV_LOG_WARNING, "Ext DRM protected stream detected, decoding will likely fail!\n");

                } else if (!guidcmp(&g, &ff_asf_digital_signature)) {

                    av_log(s, AV_LOG_WARNING, "Digital signature detected, decoding will likely fail!\n");

                }

            }

        }

        if(url_ftell(pb) != gpos + gsize)

            av_log(s, AV_LOG_DEBUG, "gpos mismatch our pos=%"PRIu64", end=%"PRIu64"\n", url_ftell(pb)-gpos, gsize);

        url_fseek(pb, gpos + gsize, SEEK_SET);

    }

    get_guid(pb, &g);

    get_le64(pb);

    get_byte(pb);

    get_byte(pb);

    if (url_feof(pb))

        return -1;

    asf->data_offset = url_ftell(pb);

    asf->packet_size_left = 0;





    for(i=0; i<128; i++){

        int stream_num= asf->asfid2avid[i];

        if(stream_num>=0){

            AVStream *st = s->streams[stream_num];

            if (!st->codec->bit_rate)

                st->codec->bit_rate = bitrate[i];

            if (dar[i].num > 0 && dar[i].den > 0)

                av_reduce(&st->sample_aspect_ratio.num,

                          &st->sample_aspect_ratio.den,

                          dar[i].num, dar[i].den, INT_MAX);

//av_log(s, AV_LOG_ERROR, "dar %d:%d sar=%d:%d\n", dar[i].num, dar[i].den, st->sample_aspect_ratio.num, st->sample_aspect_ratio.den);



            // copy and convert language codes to the frontend

            if (asf->streams[i].stream_language_index < 128) {

                const char *rfc1766 = asf->stream_languages[asf->streams[i].stream_language_index];

                if (rfc1766 && strlen(rfc1766) > 1) {

                    const char primary_tag[3] = { rfc1766[0], rfc1766[1], '\0' }; // ignore country code if any

                    const char *iso6392 = av_convert_lang_to(primary_tag, AV_LANG_ISO639_2_BIBL);

                    if (iso6392)

                        av_metadata_set2(&st->metadata, "language", iso6392, 0);

                }

            }

        }

    }



    return 0;

}

static BlockDriverAIOCB *curl_aio_readv(BlockDriverState *bs,

        int64_t sector_num, QEMUIOVector *qiov, int nb_sectors,

        BlockDriverCompletionFunc *cb, void *opaque)

{

    BDRVCURLState *s = bs->opaque;

    CURLAIOCB *acb;

    size_t start = sector_num * SECTOR_SIZE;

    size_t end;

    CURLState *state;



    acb = qemu_aio_get(&curl_aio_pool, bs, cb, opaque);

    if (!acb)

        return NULL;



    acb->qiov = qiov;



    // In case we have the requested data already (e.g. read-ahead),

    // we can just call the callback and be done.



    switch (curl_find_buf(s, start, nb_sectors * SECTOR_SIZE, acb)) {

        case FIND_RET_OK:

            qemu_aio_release(acb);

            // fall through

        case FIND_RET_WAIT:

            return &acb->common;

        default:

            break;

    }



    // No cache found, so let's start a new request



    state = curl_init_state(s);

    if (!state)

        return NULL;



    acb->start = 0;

    acb->end = (nb_sectors * SECTOR_SIZE);



    state->buf_off = 0;

    if (state->orig_buf)

        qemu_free(state->orig_buf);

    state->buf_start = start;

    state->buf_len = acb->end + READ_AHEAD_SIZE;

    end = MIN(start + state->buf_len, s->len) - 1;

    state->orig_buf = qemu_malloc(state->buf_len);

    state->acb[0] = acb;



    snprintf(state->range, 127, "%lld-%lld", (long long)start, (long long)end);

    dprintf("CURL (AIO): Reading %d at %lld (%s)\n", (nb_sectors * SECTOR_SIZE), start, state->range);

    curl_easy_setopt(state->curl, CURLOPT_RANGE, state->range);



    curl_multi_add_handle(s->multi, state->curl);

    curl_multi_do(s);



    return &acb->common;

}

static void ppc4xx_pob_reset (void *opaque)

{

    ppc4xx_pob_t *pob;



    pob = opaque;

    /* No error */

    pob->bear = 0x00000000;

    pob->besr[0] = 0x0000000;

    pob->besr[1] = 0x0000000;

}

