}

static int mxf_read_index_entry_array(AVIOContext *pb, MXFIndexTableSegment *segment)

{

    int i, length;



    segment->nb_index_entries = avio_rb32(pb);



    length = avio_rb32(pb);





    if (!(segment->temporal_offset_entries=av_calloc(segment->nb_index_entries, sizeof(*segment->temporal_offset_entries))) ||

        !(segment->flag_entries          = av_calloc(segment->nb_index_entries, sizeof(*segment->flag_entries))) ||

        !(segment->stream_offset_entries = av_calloc(segment->nb_index_entries, sizeof(*segment->stream_offset_entries)))) {

        av_freep(&segment->temporal_offset_entries);

        av_freep(&segment->flag_entries);

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < segment->nb_index_entries; i++) {

        if(avio_feof(pb))


        segment->temporal_offset_entries[i] = avio_r8(pb);

        avio_r8(pb);                                        /* KeyFrameOffset */

        segment->flag_entries[i] = avio_r8(pb);

        segment->stream_offset_entries[i] = avio_rb64(pb);

        avio_skip(pb, length - 11);

    }

    return 0;

}

static int qcow2_save_vmstate(BlockDriverState *bs, QEMUIOVector *qiov,

                              int64_t pos)

{

    BDRVQcow2State *s = bs->opaque;

    int64_t total_sectors = bs->total_sectors;

    bool zero_beyond_eof = bs->zero_beyond_eof;

    int ret;



    BLKDBG_EVENT(bs->file, BLKDBG_VMSTATE_SAVE);

    bs->zero_beyond_eof = false;

    ret = bdrv_pwritev(bs, qcow2_vm_state_offset(s) + pos, qiov);

    bs->zero_beyond_eof = zero_beyond_eof;



    /* bdrv_co_do_writev will have increased the total_sectors value to include

     * the VM state - the VM state is however not an actual part of the block

     * device, therefore, we need to restore the old value. */

    bs->total_sectors = total_sectors;



    return ret;

}

static void qemu_kvm_eat_signal(CPUState *env, int timeout)

{

    struct timespec ts;

    int r, e;

    siginfo_t siginfo;

    sigset_t waitset;



    ts.tv_sec = timeout / 1000;

    ts.tv_nsec = (timeout % 1000) * 1000000;



    sigemptyset(&waitset);

    sigaddset(&waitset, SIG_IPI);



    qemu_mutex_unlock(&qemu_global_mutex);

    r = sigtimedwait(&waitset, &siginfo, &ts);

    e = errno;

    qemu_mutex_lock(&qemu_global_mutex);



    if (r == -1 && !(e == EAGAIN || e == EINTR)) {

        fprintf(stderr, "sigtimedwait: %s\n", strerror(e));

        exit(1);

    }

}

static int cinepak_decode (CinepakContext *s)

{

    const uint8_t  *eod = (s->data + s->size);

    int           i, result, strip_size, frame_flags, num_strips;

    int           y0 = 0;

    int           encoded_buf_size;



    if (s->size < 10)

        return -1;



    frame_flags = s->data[0];

    num_strips  = AV_RB16 (&s->data[8]);

    encoded_buf_size = ((s->data[1] << 16) | AV_RB16 (&s->data[2]));



    /* if this is the first frame, check for deviant Sega FILM data */

    if (s->sega_film_skip_bytes == -1) {

        if (encoded_buf_size != s->size) {

            /* If the encoded frame size differs from the frame size as indicated

             * by the container file, this data likely comes from a Sega FILM/CPK file.

             * If the frame header is followed by the bytes FE 00 00 06 00 00 then

             * this is probably one of the two known files that have 6 extra bytes

             * after the frame header. Else, assume 2 extra bytes. */

            if ((s->data[10] == 0xFE) &&

                (s->data[11] == 0x00) &&

                (s->data[12] == 0x00) &&

                (s->data[13] == 0x06) &&

                (s->data[14] == 0x00) &&

                (s->data[15] == 0x00))

                s->sega_film_skip_bytes = 6;

            else

                s->sega_film_skip_bytes = 2;

        } else

            s->sega_film_skip_bytes = 0;

    }



    s->data += 10 + s->sega_film_skip_bytes;



    if (num_strips > MAX_STRIPS)

        num_strips = MAX_STRIPS;



    for (i=0; i < num_strips; i++) {

        if ((s->data + 12) > eod)

            return -1;



        s->strips[i].id = s->data[0];

        s->strips[i].y1 = y0;

        s->strips[i].x1 = 0;

        s->strips[i].y2 = y0 + AV_RB16 (&s->data[8]);

        s->strips[i].x2 = s->avctx->width;



        strip_size = AV_RB24 (&s->data[1]) - 12;

        s->data   += 12;

        strip_size = ((s->data + strip_size) > eod) ? (eod - s->data) : strip_size;



        if ((i > 0) && !(frame_flags & 0x01)) {

            memcpy (s->strips[i].v4_codebook, s->strips[i-1].v4_codebook,

                sizeof(s->strips[i].v4_codebook));

            memcpy (s->strips[i].v1_codebook, s->strips[i-1].v1_codebook,

                sizeof(s->strips[i].v1_codebook));

        }



        result = cinepak_decode_strip (s, &s->strips[i], s->data, strip_size);



        if (result != 0)

            return result;



        s->data += strip_size;

        y0    = s->strips[i].y2;

    }

    return 0;

}

static void pxa2xx_rtc_swupdate(PXA2xxRTCState *s)

{

    int64_t rt = qemu_get_clock(rt_clock);

    if (s->rtsr & (1 << 12))

        s->last_swcr += (rt - s->last_sw) / 10;

    s->last_sw = rt;

}

void idct_put_altivec(uint8_t* dest, int stride, vector_s16_t* block)

{

POWERPC_TBL_DECLARE(altivec_idct_put_num, 1);

#ifdef ALTIVEC_USE_REFERENCE_C_CODE

POWERPC_TBL_START_COUNT(altivec_idct_put_num, 1);

    void simple_idct_put(uint8_t *dest, int line_size, int16_t *block);

    simple_idct_put(dest, stride, (int16_t*)block);

POWERPC_TBL_STOP_COUNT(altivec_idct_put_num, 1);

#else /* ALTIVEC_USE_REFERENCE_C_CODE */

    vector_u8_t tmp;



POWERPC_TBL_START_COUNT(altivec_idct_put_num, 1);



    IDCT



#define COPY(dest,src)						\

    tmp = vec_packsu (src, src);				\

    vec_ste ((vector_u32_t)tmp, 0, (unsigned int *)dest);	\

    vec_ste ((vector_u32_t)tmp, 4, (unsigned int *)dest);



    COPY (dest, vx0)	dest += stride;

    COPY (dest, vx1)	dest += stride;

    COPY (dest, vx2)	dest += stride;

    COPY (dest, vx3)	dest += stride;

    COPY (dest, vx4)	dest += stride;

    COPY (dest, vx5)	dest += stride;

    COPY (dest, vx6)	dest += stride;

    COPY (dest, vx7)



POWERPC_TBL_STOP_COUNT(altivec_idct_put_num, 1);

#endif /* ALTIVEC_USE_REFERENCE_C_CODE */

}

static int dvbsub_display_end_segment(AVCodecContext *avctx, const uint8_t *buf,

                                        int buf_size, AVSubtitle *sub)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubDisplayDefinition *display_def = ctx->display_definition;



    DVBSubRegion *region;

    DVBSubRegionDisplay *display;

    AVSubtitleRect *rect;

    DVBSubCLUT *clut;

    uint32_t *clut_table;

    int i;

    int offset_x=0, offset_y=0;



    sub->rects = NULL;

    sub->start_display_time = 0;

    sub->end_display_time = ctx->time_out * 1000;

    sub->format = 0;



    if (display_def) {

        offset_x = display_def->x;

        offset_y = display_def->y;

    }



    sub->num_rects = ctx->display_list_size;

    if (sub->num_rects <= 0)

        return AVERROR_INVALIDDATA;



    sub->rects = av_mallocz_array(sub->num_rects * sub->num_rects,

                                  sizeof(*sub->rects));

    if (!sub->rects)

        return AVERROR(ENOMEM);



    i = 0;



    for (display = ctx->display_list; display; display = display->next) {

        region = get_region(ctx, display->region_id);

        rect = sub->rects[i];



        if (!region)

            continue;



        rect->x = display->x_pos + offset_x;

        rect->y = display->y_pos + offset_y;

        rect->w = region->width;

        rect->h = region->height;

        rect->nb_colors = 16;

        rect->type      = SUBTITLE_BITMAP;

        rect->pict.linesize[0] = region->width;



        clut = get_clut(ctx, region->clut);



        if (!clut)

            clut = &default_clut;



        switch (region->depth) {

        case 2:

            clut_table = clut->clut4;

            break;

        case 8:

            clut_table = clut->clut256;

            break;

        case 4:

        default:

            clut_table = clut->clut16;

            break;

        }



        rect->pict.data[1] = av_mallocz(AVPALETTE_SIZE);

        if (!rect->pict.data[1]) {

            av_free(sub->rects);

            return AVERROR(ENOMEM);

        }

        memcpy(rect->pict.data[1], clut_table, (1 << region->depth) * sizeof(uint32_t));



        rect->pict.data[0] = av_malloc(region->buf_size);

        if (!rect->pict.data[0]) {

            av_free(rect->pict.data[1]);

            av_free(sub->rects);

            return AVERROR(ENOMEM);

        }

        memcpy(rect->pict.data[0], region->pbuf, region->buf_size);



        i++;

    }



    sub->num_rects = i;



#ifdef DEBUG

    save_display_set(ctx);

#endif



    return 1;

}

