static void test_mirror(void)

{

    int send_sock[2], recv_sock;

    char *cmdline;

    uint32_t ret = 0, len = 0;

    char send_buf[] = "Hello! filter-mirror~";

    char sock_path[] = "filter-mirror.XXXXXX";

    char *recv_buf;

    uint32_t size = sizeof(send_buf);

    size = htonl(size);



    ret = socketpair(PF_UNIX, SOCK_STREAM, 0, send_sock);

    g_assert_cmpint(ret, !=, -1);



    ret = mkstemp(sock_path);

    g_assert_cmpint(ret, !=, -1);



    cmdline = g_strdup_printf("-netdev socket,id=qtest-bn0,fd=%d "

                 "-device e1000,netdev=qtest-bn0,id=qtest-e0 "

                 "-chardev socket,id=mirror0,path=%s,server,nowait "

                 "-object filter-mirror,id=qtest-f0,netdev=qtest-bn0,queue=tx,outdev=mirror0 "

                 , send_sock[1], sock_path);

    qtest_start(cmdline);

    g_free(cmdline);



    recv_sock = unix_connect(sock_path, NULL);

    g_assert_cmpint(recv_sock, !=, -1);



    struct iovec iov[] = {

        {

            .iov_base = &size,

            .iov_len = sizeof(size),

        }, {

            .iov_base = send_buf,

            .iov_len = sizeof(send_buf),

        },

    };



    /* send a qmp command to guarantee that 'connected' is setting to true. */

    qmp_discard_response("{ 'execute' : 'query-status'}");

    ret = iov_send(send_sock[0], iov, 2, 0, sizeof(size) + sizeof(send_buf));

    g_assert_cmpint(ret, ==, sizeof(send_buf) + sizeof(size));

    close(send_sock[0]);



    ret = qemu_recv(recv_sock, &len, sizeof(len), 0);

    g_assert_cmpint(ret, ==, sizeof(len));

    len = ntohl(len);



    g_assert_cmpint(len, ==, sizeof(send_buf));

    recv_buf = g_malloc(len);

    ret = qemu_recv(recv_sock, recv_buf, len, 0);

    g_assert_cmpstr(recv_buf, ==, send_buf);



    g_free(recv_buf);

    close(recv_sock);

    unlink(sock_path);

}

static int iscsi_truncate(BlockDriverState *bs, int64_t offset)

{

    IscsiLun *iscsilun = bs->opaque;

    Error *local_err = NULL;



    if (iscsilun->type != TYPE_DISK) {

        return -ENOTSUP;

    }



    iscsi_readcapacity_sync(iscsilun, &local_err);

    if (local_err != NULL) {

        error_free(local_err);

        return -EIO;

    }



    if (offset > iscsi_getlength(bs)) {

        return -EINVAL;

    }



    if (iscsilun->allocationmap != NULL) {

        g_free(iscsilun->allocationmap);

        iscsilun->allocationmap =

            bitmap_new(DIV_ROUND_UP(bs->total_sectors,

                                    iscsilun->cluster_sectors));

    }



    return 0;

}

static int gif_parse_next_image(GifState *s)

{

    ByteIOContext *f = s->f;

    int ret, code;



    for (;;) {

        code = url_fgetc(f);

#ifdef DEBUG

        printf("gif: code=%02x '%c'\n", code, code);

#endif

        switch (code) {

        case ',':

            if (gif_read_image(s) < 0)

                return AVERROR(EIO);

            ret = 0;

            goto the_end;

        case ';':

            /* end of image */

            ret = AVERROR(EIO);

            goto the_end;

        case '!':

            if (gif_read_extension(s) < 0)

                return AVERROR(EIO);

            break;

        case EOF:

        default:

            /* error or errneous EOF */

            ret = AVERROR(EIO);

            goto the_end;

        }

    }

  the_end:

    return ret;

}

static int mkv_write_codecprivate(AVFormatContext *s, AVIOContext *pb,

                                  AVCodecParameters *par,

                                  int native_id, int qt_id)

{

    AVIOContext *dyn_cp;

    uint8_t *codecpriv;

    int ret, codecpriv_size;



    ret = avio_open_dyn_buf(&dyn_cp);

    if (ret < 0)

        return ret;



    if (native_id) {

        ret = mkv_write_native_codecprivate(s, par, dyn_cp);

    } else if (par->codec_type == AVMEDIA_TYPE_VIDEO) {

        if (qt_id) {

            if (!par->codec_tag)

                par->codec_tag = ff_codec_get_tag(ff_codec_movvideo_tags,

                                                    par->codec_id);

            if (   ff_codec_get_id(ff_codec_movvideo_tags, par->codec_tag) == par->codec_id

                && (!par->extradata_size || ff_codec_get_id(ff_codec_movvideo_tags, AV_RL32(par->extradata + 4)) != par->codec_id)

            ) {

                int i;

                avio_wb32(dyn_cp, 0x5a + par->extradata_size);

                avio_wl32(dyn_cp, par->codec_tag);

                for(i = 0; i < 0x5a - 8; i++)

                    avio_w8(dyn_cp, 0);

            }

            avio_write(dyn_cp, par->extradata, par->extradata_size);

        } else {

            if (!ff_codec_get_tag(ff_codec_bmp_tags, par->codec_id))

                av_log(s, AV_LOG_WARNING, "codec %s is not supported by this format\n",

                       avcodec_get_name(par->codec_id));



            if (!par->codec_tag)

                par->codec_tag = ff_codec_get_tag(ff_codec_bmp_tags,

                                                  par->codec_id);

            if (!par->codec_tag && par->codec_id != AV_CODEC_ID_RAWVIDEO) {

                av_log(s, AV_LOG_ERROR, "No bmp codec tag found for codec %s\n",

                       avcodec_get_name(par->codec_id));

                ret = AVERROR(EINVAL);

            }



            ff_put_bmp_header(dyn_cp, par, ff_codec_bmp_tags, 0, 0);

        }

    } else if (par->codec_type == AVMEDIA_TYPE_AUDIO) {

        unsigned int tag;

        tag = ff_codec_get_tag(ff_codec_wav_tags, par->codec_id);

        if (!tag) {

            av_log(s, AV_LOG_ERROR, "No wav codec tag found for codec %s\n",

                   avcodec_get_name(par->codec_id));

            ret = AVERROR(EINVAL);

        }

        if (!par->codec_tag)

            par->codec_tag = tag;



        ff_put_wav_header(s, dyn_cp, par, FF_PUT_WAV_HEADER_FORCE_WAVEFORMATEX);

    }



    codecpriv_size = avio_close_dyn_buf(dyn_cp, &codecpriv);

    if (codecpriv_size)

        put_ebml_binary(pb, MATROSKA_ID_CODECPRIVATE, codecpriv,

                        codecpriv_size);

    av_free(codecpriv);

    return ret;

}

static void add_entry(TiffEncoderContext * s,

                      enum TiffTags tag, enum TiffTypes type, int count,

                      const void *ptr_val)

{

    uint8_t *entries_ptr = s->entries + 12 * s->num_entries;



    av_assert0(s->num_entries < TIFF_MAX_ENTRY);



    bytestream_put_le16(&entries_ptr, tag);

    bytestream_put_le16(&entries_ptr, type);

    bytestream_put_le32(&entries_ptr, count);



    if (type_sizes[type] * count <= 4) {

        tnput(&entries_ptr, count, ptr_val, type, 0);

    } else {

        bytestream_put_le32(&entries_ptr, *s->buf - s->buf_start);

        check_size(s, count * type_sizes2[type]);

        tnput(s->buf, count, ptr_val, type, 0);

    }



    s->num_entries++;

}

static int pick_formats(AVFilterGraph *graph)

{

    int i, j, ret;

    int change;



    do{

        change = 0;

        for (i = 0; i < graph->filter_count; i++) {

            AVFilterContext *filter = graph->filters[i];

            if (filter->nb_inputs){

                for (j = 0; j < filter->nb_inputs; j++){

                    if(filter->inputs[j]->in_formats && filter->inputs[j]->in_formats->format_count == 1) {

                        pick_format(filter->inputs[j], NULL);

                        change = 1;

                    }

                }

            }

            if (filter->nb_outputs){

                for (j = 0; j < filter->nb_outputs; j++){

                    if(filter->outputs[j]->in_formats && filter->outputs[j]->in_formats->format_count == 1) {

                        pick_format(filter->outputs[j], NULL);

                        change = 1;

                    }

                }

            }

            if (filter->nb_inputs && filter->nb_outputs && filter->inputs[0]->format>=0) {

                for (j = 0; j < filter->nb_outputs; j++) {

                    if(filter->outputs[j]->format<0) {

                        pick_format(filter->outputs[j], filter->inputs[0]);

                        change = 1;

                    }

                }

            }

        }

    }while(change);



    for (i = 0; i < graph->filter_count; i++) {

        AVFilterContext *filter = graph->filters[i];



        for (j = 0; j < filter->nb_inputs; j++)

            if ((ret = pick_format(filter->inputs[j], NULL)) < 0)

                return ret;

        for (j = 0; j < filter->nb_outputs; j++)

            if ((ret = pick_format(filter->outputs[j], NULL)) < 0)

                return ret;

    }

    return 0;

}

