static void external_snapshot_prepare(BlkActionState *common,

                                      Error **errp)

{

    int flags = 0;

    QDict *options = NULL;

    Error *local_err = NULL;

    /* Device and node name of the image to generate the snapshot from */

    const char *device;

    const char *node_name;

    /* Reference to the new image (for 'blockdev-snapshot') */

    const char *snapshot_ref;

    /* File name of the new image (for 'blockdev-snapshot-sync') */

    const char *new_image_file;

    ExternalSnapshotState *state =

                             DO_UPCAST(ExternalSnapshotState, common, common);

    TransactionAction *action = common->action;



    /* 'blockdev-snapshot' and 'blockdev-snapshot-sync' have similar

     * purpose but a different set of parameters */

    switch (action->type) {

    case TRANSACTION_ACTION_KIND_BLOCKDEV_SNAPSHOT:

        {

            BlockdevSnapshot *s = action->u.blockdev_snapshot.data;

            device = s->node;

            node_name = s->node;

            new_image_file = NULL;

            snapshot_ref = s->overlay;

        }

        break;

    case TRANSACTION_ACTION_KIND_BLOCKDEV_SNAPSHOT_SYNC:

        {

            BlockdevSnapshotSync *s = action->u.blockdev_snapshot_sync.data;

            device = s->has_device ? s->device : NULL;

            node_name = s->has_node_name ? s->node_name : NULL;

            new_image_file = s->snapshot_file;

            snapshot_ref = NULL;

        }

        break;

    default:

        g_assert_not_reached();

    }



    /* start processing */

    if (action_check_completion_mode(common, errp) < 0) {

        return;

    }



    state->old_bs = bdrv_lookup_bs(device, node_name, errp);

    if (!state->old_bs) {

        return;

    }



    /* Acquire AioContext now so any threads operating on old_bs stop */

    state->aio_context = bdrv_get_aio_context(state->old_bs);

    aio_context_acquire(state->aio_context);

    bdrv_drained_begin(state->old_bs);



    if (!bdrv_is_inserted(state->old_bs)) {

        error_setg(errp, QERR_DEVICE_HAS_NO_MEDIUM, device);

        return;

    }



    if (bdrv_op_is_blocked(state->old_bs,

                           BLOCK_OP_TYPE_EXTERNAL_SNAPSHOT, errp)) {

        return;

    }



    if (!bdrv_is_read_only(state->old_bs)) {

        if (bdrv_flush(state->old_bs)) {

            error_setg(errp, QERR_IO_ERROR);

            return;

        }

    }



    if (!bdrv_is_first_non_filter(state->old_bs)) {

        error_setg(errp, QERR_FEATURE_DISABLED, "snapshot");

        return;

    }



    if (action->type == TRANSACTION_ACTION_KIND_BLOCKDEV_SNAPSHOT_SYNC) {

        BlockdevSnapshotSync *s = action->u.blockdev_snapshot_sync.data;

        const char *format = s->has_format ? s->format : "qcow2";

        enum NewImageMode mode;

        const char *snapshot_node_name =

            s->has_snapshot_node_name ? s->snapshot_node_name : NULL;



        if (node_name && !snapshot_node_name) {

            error_setg(errp, "New snapshot node name missing");

            return;

        }



        if (snapshot_node_name &&

            bdrv_lookup_bs(snapshot_node_name, snapshot_node_name, NULL)) {

            error_setg(errp, "New snapshot node name already in use");

            return;

        }



        flags = state->old_bs->open_flags;

        flags &= ~(BDRV_O_SNAPSHOT | BDRV_O_NO_BACKING | BDRV_O_COPY_ON_READ);



        /* create new image w/backing file */

        mode = s->has_mode ? s->mode : NEW_IMAGE_MODE_ABSOLUTE_PATHS;

        if (mode != NEW_IMAGE_MODE_EXISTING) {

            int64_t size = bdrv_getlength(state->old_bs);

            if (size < 0) {

                error_setg_errno(errp, -size, "bdrv_getlength failed");

                return;

            }

            bdrv_img_create(new_image_file, format,

                            state->old_bs->filename,

                            state->old_bs->drv->format_name,

                            NULL, size, flags, false, &local_err);

            if (local_err) {

                error_propagate(errp, local_err);

                return;

            }

        }



        options = qdict_new();

        if (s->has_snapshot_node_name) {

            qdict_put_str(options, "node-name", snapshot_node_name);

        }

        qdict_put_str(options, "driver", format);



        flags |= BDRV_O_NO_BACKING;

    }



    state->new_bs = bdrv_open(new_image_file, snapshot_ref, options, flags,

                              errp);

    /* We will manually add the backing_hd field to the bs later */

    if (!state->new_bs) {

        return;

    }



    if (bdrv_has_blk(state->new_bs)) {

        error_setg(errp, "The snapshot is already in use");

        return;

    }



    if (bdrv_op_is_blocked(state->new_bs, BLOCK_OP_TYPE_EXTERNAL_SNAPSHOT,

                           errp)) {

        return;

    }



    if (state->new_bs->backing != NULL) {

        error_setg(errp, "The snapshot already has a backing image");

        return;

    }



    if (!state->new_bs->drv->supports_backing) {

        error_setg(errp, "The snapshot does not support backing images");

        return;

    }



    bdrv_set_aio_context(state->new_bs, state->aio_context);



    /* This removes our old bs and adds the new bs. This is an operation that

     * can fail, so we need to do it in .prepare; undoing it for abort is

     * always possible. */

    bdrv_ref(state->new_bs);

    bdrv_append(state->new_bs, state->old_bs, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }

    state->overlay_appended = true;

}

void cpu_outb(pio_addr_t addr, uint8_t val)

{

    LOG_IOPORT("outb: %04"FMT_pioaddr" %02"PRIx8"\n", addr, val);

    trace_cpu_out(addr, val);

    ioport_write(0, addr, val);

}

static int cow_test_bit(int64_t bitnum, const uint8_t *bitmap)

{

    return (bitmap[bitnum / 8] & (1 << (bitnum & 7))) != 0;

}

int ff_draw_init(FFDrawContext *draw, enum AVPixelFormat format, unsigned flags)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(format);

    const AVComponentDescriptor *c;

    unsigned i, nb_planes = 0;

    int pixelstep[MAX_PLANES] = { 0 };



    if (!desc->name)

        return AVERROR(EINVAL);

    if (desc->flags & ~(AV_PIX_FMT_FLAG_PLANAR | AV_PIX_FMT_FLAG_RGB | AV_PIX_FMT_FLAG_PSEUDOPAL | AV_PIX_FMT_FLAG_ALPHA))

        return AVERROR(ENOSYS);

    for (i = 0; i < desc->nb_components; i++) {

        c = &desc->comp[i];

        /* for now, only 8-bits formats */

        if (c->depth_minus1 != 8 - 1)

            return AVERROR(ENOSYS);

        if (c->plane >= MAX_PLANES)

            return AVERROR(ENOSYS);

        /* strange interleaving */

        if (pixelstep[c->plane] != 0 &&

            pixelstep[c->plane] != c->step_minus1 + 1)

            return AVERROR(ENOSYS);

        pixelstep[c->plane] = c->step_minus1 + 1;

        if (pixelstep[c->plane] >= 8)

            return AVERROR(ENOSYS);

        nb_planes = FFMAX(nb_planes, c->plane + 1);

    }

    if ((desc->log2_chroma_w || desc->log2_chroma_h) && nb_planes < 3)

        return AVERROR(ENOSYS); /* exclude NV12 and NV21 */

    memset(draw, 0, sizeof(*draw));

    draw->desc      = desc;

    draw->format    = format;

    draw->nb_planes = nb_planes;

    memcpy(draw->pixelstep, pixelstep, sizeof(draw->pixelstep));

    draw->hsub[1] = draw->hsub[2] = draw->hsub_max = desc->log2_chroma_w;

    draw->vsub[1] = draw->vsub[2] = draw->vsub_max = desc->log2_chroma_h;

    for (i = 0; i < ((desc->nb_components - 1) | 1); i++)

        draw->comp_mask[desc->comp[i].plane] |=

            1 << (desc->comp[i].offset_plus1 - 1);

    return 0;

}

static int yop_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    YopDecContext *yop = s->priv_data;

    AVIOContext *pb  = s->pb;



    int ret;

    int actual_video_data_size = yop->frame_size -

                                 yop->audio_block_length - yop->palette_size;



    yop->video_packet.stream_index = 1;



    if (yop->video_packet.data) {

        *pkt                   =  yop->video_packet;

        yop->video_packet.data =  NULL;

        yop->video_packet.size =  0;

        pkt->data[0]           =  yop->odd_frame;

        pkt->flags             |= AV_PKT_FLAG_KEY;

        yop->odd_frame         ^= 1;

        return pkt->size;

    }

    ret = av_new_packet(&yop->video_packet,

                        yop->frame_size - yop->audio_block_length);

    if (ret < 0)

        return ret;



    yop->video_packet.pos = avio_tell(pb);



    ret = avio_read(pb, yop->video_packet.data, yop->palette_size);

    if (ret < 0) {

        goto err_out;

    }else if (ret < yop->palette_size) {

        ret = AVERROR_EOF;

        goto err_out;

    }



    ret = av_get_packet(pb, pkt, 920);

    if (ret < 0)

        goto err_out;



    // Set position to the start of the frame

    pkt->pos = yop->video_packet.pos;



    avio_skip(pb, yop->audio_block_length - ret);



    ret = avio_read(pb, yop->video_packet.data + yop->palette_size,

                     actual_video_data_size);

    if (ret < 0)

        goto err_out;

    else if (ret < actual_video_data_size)

        av_shrink_packet(&yop->video_packet, yop->palette_size + ret);



    // Arbitrarily return the audio data first

    return yop->audio_block_length;



err_out:

    av_free_packet(&yop->video_packet);

    return ret;

}

static void get_downmix_coeffs(AC3DecodeContext *ctx)

{

    int from = ctx->bsi.acmod;

    int to = ctx->output;

    float clev = clevs[ctx->bsi.cmixlev];

    float slev = slevs[ctx->bsi.surmixlev];

    ac3_audio_block *ab = &ctx->audio_block;



    if (to == AC3_OUTPUT_UNMODIFIED)

        return 0;



    switch (from) {

        case AC3_INPUT_DUALMONO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                case AC3_OUTPUT_STEREO: /* We Assume that sum of both mono channels is requested */

                    ab->chcoeffs[0] *= LEVEL_MINUS_6DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_6DB;

                    break;

            }

            break;

        case AC3_INPUT_MONO:

            switch (to) {

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_STEREO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_3F:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= clev * LEVEL_PLUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[1] *= clev;

                    break;

            }

            break;

        case AC3_INPUT_2F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[2] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_3F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= clev * LEVEL_PLUS_3DB;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[1] *= clev;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_2F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= slev * LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[2] *= slev;

                    ab->chcoeffs[3] *= slev;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

        case AC3_INPUT_3F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    ab->chcoeffs[0] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[2] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[1] *= clev * LEVEL_PLUS_3DB;

                    ab->chcoeffs[3] *= slev * LEVEL_MINUS_3DB;

                    ab->chcoeffs[4] *= slev * LEVEL_MINUS_3DB;

                    break;

                case AC3_OUTPUT_STEREO:

                    ab->chcoeffs[1] *= clev;

                    ab->chcoeffs[3] *= slev;

                    ab->chcoeffs[4] *= slev;

                    break;

                case AC3_OUTPUT_DOLBY:

                    ab->chcoeffs[1] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[3] *= LEVEL_MINUS_3DB;

                    ab->chcoeffs[4] *= LEVEL_MINUS_3DB;

                    break;

            }

            break;

    }

}

static av_always_inline av_flatten void FUNCC(h264_loop_filter_luma)(uint8_t *p_pix, int xstride, int ystride, int inner_iters, int alpha, int beta, int8_t *tc0)

{

    pixel *pix = (pixel*)p_pix;

    int i, d;

    xstride >>= sizeof(pixel)-1;

    ystride >>= sizeof(pixel)-1;

    alpha <<= BIT_DEPTH - 8;

    beta  <<= BIT_DEPTH - 8;

    for( i = 0; i < 4; i++ ) {

        const int tc_orig = tc0[i] << (BIT_DEPTH - 8);

        if( tc_orig < 0 ) {

            pix += inner_iters*ystride;

            continue;

        }

        for( d = 0; d < inner_iters; d++ ) {

            const int p0 = pix[-1*xstride];

            const int p1 = pix[-2*xstride];

            const int p2 = pix[-3*xstride];

            const int q0 = pix[0];

            const int q1 = pix[1*xstride];

            const int q2 = pix[2*xstride];



            if( FFABS( p0 - q0 ) < alpha &&

                FFABS( p1 - p0 ) < beta &&

                FFABS( q1 - q0 ) < beta ) {



                int tc = tc_orig;

                int i_delta;



                if( FFABS( p2 - p0 ) < beta ) {

                    if(tc_orig)

                    pix[-2*xstride] = p1 + av_clip( (( p2 + ( ( p0 + q0 + 1 ) >> 1 ) ) >> 1) - p1, -tc_orig, tc_orig );

                    tc++;

                }

                if( FFABS( q2 - q0 ) < beta ) {

                    if(tc_orig)

                    pix[   xstride] = q1 + av_clip( (( q2 + ( ( p0 + q0 + 1 ) >> 1 ) ) >> 1) - q1, -tc_orig, tc_orig );

                    tc++;

                }



                i_delta = av_clip( (((q0 - p0 ) << 2) + (p1 - q1) + 4) >> 3, -tc, tc );

                pix[-xstride] = av_clip_pixel( p0 + i_delta );    /* p0' */

                pix[0]        = av_clip_pixel( q0 - i_delta );    /* q0' */

            }

            pix += ystride;

        }

    }

}

static void rv34_idct_add_c(uint8_t *dst, ptrdiff_t stride, DCTELEM *block){

    int      temp[16];

    uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;

    int      i;



    rv34_row_transform(temp, block);

    memset(block, 0, 16*sizeof(DCTELEM));



    for(i = 0; i < 4; i++){

        const int z0 = 13*(temp[4*0+i] +    temp[4*2+i]) + 0x200;

        const int z1 = 13*(temp[4*0+i] -    temp[4*2+i]) + 0x200;

        const int z2 =  7* temp[4*1+i] - 17*temp[4*3+i];

        const int z3 = 17* temp[4*1+i] +  7*temp[4*3+i];



        dst[0] = cm[ dst[0] + ( (z0 + z3) >> 10 ) ];

        dst[1] = cm[ dst[1] + ( (z1 + z2) >> 10 ) ];

        dst[2] = cm[ dst[2] + ( (z1 - z2) >> 10 ) ];

        dst[3] = cm[ dst[3] + ( (z0 - z3) >> 10 ) ];



        dst  += stride;

    }

}

static av_cold int set_channel_info(AC3EncodeContext *s, int channels,

                                    int64_t *channel_layout)

{

    int ch_layout;



    if (channels < 1 || channels > AC3_MAX_CHANNELS)

        return AVERROR(EINVAL);

    if ((uint64_t)*channel_layout > 0x7FF)

        return AVERROR(EINVAL);

    ch_layout = *channel_layout;

    if (!ch_layout)

        ch_layout = avcodec_guess_channel_layout(channels, CODEC_ID_AC3, NULL);

    if (av_get_channel_layout_nb_channels(ch_layout) != channels)

        return AVERROR(EINVAL);



    s->lfe_on       = !!(ch_layout & AV_CH_LOW_FREQUENCY);

    s->channels     = channels;

    s->fbw_channels = channels - s->lfe_on;

    s->lfe_channel  = s->lfe_on ? s->fbw_channels : -1;

    if (s->lfe_on)

        ch_layout -= AV_CH_LOW_FREQUENCY;



    switch (ch_layout) {

    case AV_CH_LAYOUT_MONO:           s->channel_mode = AC3_CHMODE_MONO;   break;

    case AV_CH_LAYOUT_STEREO:         s->channel_mode = AC3_CHMODE_STEREO; break;

    case AV_CH_LAYOUT_SURROUND:       s->channel_mode = AC3_CHMODE_3F;     break;

    case AV_CH_LAYOUT_2_1:            s->channel_mode = AC3_CHMODE_2F1R;   break;

    case AV_CH_LAYOUT_4POINT0:        s->channel_mode = AC3_CHMODE_3F1R;   break;

    case AV_CH_LAYOUT_QUAD:

    case AV_CH_LAYOUT_2_2:            s->channel_mode = AC3_CHMODE_2F2R;   break;

    case AV_CH_LAYOUT_5POINT0:

    case AV_CH_LAYOUT_5POINT0_BACK:   s->channel_mode = AC3_CHMODE_3F2R;   break;

    default:

        return AVERROR(EINVAL);

    }

    s->has_center   = (s->channel_mode & 0x01) && s->channel_mode != AC3_CHMODE_MONO;

    s->has_surround =  s->channel_mode & 0x04;



    s->channel_map  = ff_ac3_enc_channel_map[s->channel_mode][s->lfe_on];

    *channel_layout = ch_layout;

    if (s->lfe_on)

        *channel_layout |= AV_CH_LOW_FREQUENCY;



    return 0;

}

static void scsi_aio_complete(void *opaque, int ret)

{

    SCSIDiskReq *r = (SCSIDiskReq *)opaque;

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);



    assert(r->req.aiocb != NULL);

    r->req.aiocb = NULL;

    block_acct_done(bdrv_get_stats(s->qdev.conf.bs), &r->acct);

    if (r->req.io_canceled) {

        scsi_req_cancel_complete(&r->req);

        goto done;

    }



    if (ret < 0) {

        if (scsi_handle_rw_error(r, -ret)) {

            goto done;

        }

    }



    scsi_req_complete(&r->req, GOOD);



done:

    scsi_req_unref(&r->req);

}

static void return_frame(AVFilterContext *ctx, int is_second)

{

    YADIFContext *yadif = ctx->priv;

    AVFilterLink *link= ctx->outputs[0];

    int tff;



    if (yadif->parity == -1) {

        tff = yadif->cur->video->interlaced ?

            yadif->cur->video->top_field_first : 1;

    } else {

        tff = yadif->parity^1;

    }



    if (is_second) {

        yadif->out = ff_get_video_buffer(link, AV_PERM_WRITE | AV_PERM_PRESERVE |

                                         AV_PERM_REUSE, link->w, link->h);

        avfilter_copy_buffer_ref_props(yadif->out, yadif->cur);

        yadif->out->video->interlaced = 0;

    }



    if (!yadif->csp)

        yadif->csp = &av_pix_fmt_descriptors[link->format];

    if (yadif->csp->comp[0].depth_minus1 / 8 == 1)

        yadif->filter_line = filter_line_c_16bit;



    filter(ctx, yadif->out, tff ^ !is_second, tff);



    if (is_second) {

        int64_t cur_pts  = yadif->cur->pts;

        int64_t next_pts = yadif->next->pts;



        if (next_pts != AV_NOPTS_VALUE && cur_pts != AV_NOPTS_VALUE) {

            yadif->out->pts = cur_pts + next_pts;

        } else {

            yadif->out->pts = AV_NOPTS_VALUE;

        }

        ff_start_frame(ctx->outputs[0], yadif->out);

    }

    ff_draw_slice(ctx->outputs[0], 0, link->h, 1);

    ff_end_frame(ctx->outputs[0]);



    yadif->frame_pending = (yadif->mode&1) && !is_second;

}

static int qemu_chr_open_pipe(QemuOpts *opts, CharDriverState **_chr)

{

    int fd_in, fd_out;

    char filename_in[256], filename_out[256];

    const char *filename = qemu_opt_get(opts, "path");



    if (filename == NULL) {

        fprintf(stderr, "chardev: pipe: no filename given\n");

        return -EINVAL;

    }



    snprintf(filename_in, 256, "%s.in", filename);

    snprintf(filename_out, 256, "%s.out", filename);

    TFR(fd_in = qemu_open(filename_in, O_RDWR | O_BINARY));

    TFR(fd_out = qemu_open(filename_out, O_RDWR | O_BINARY));

    if (fd_in < 0 || fd_out < 0) {

	if (fd_in >= 0)

	    close(fd_in);

	if (fd_out >= 0)

	    close(fd_out);

        TFR(fd_in = fd_out = qemu_open(filename, O_RDWR | O_BINARY));

        if (fd_in < 0) {

            return -errno;

        }

    }



    *_chr = qemu_chr_open_fd(fd_in, fd_out);

    return 0;

}

static int add_string_metadata(int count, const char *name,

                               TiffContext *s)

{

    char *value;



    if (bytestream2_get_bytes_left(&s->gb) < count || count < 0)

        return AVERROR_INVALIDDATA;



    value = av_malloc(count + 1);

    if (!value)

        return AVERROR(ENOMEM);



    bytestream2_get_bufferu(&s->gb, value, count);

    value[count] = 0;



    av_dict_set(avpriv_frame_get_metadatap(&s->picture), name, value, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

static int qemu_rdma_dest_init(RDMAContext *rdma, Error **errp)

{

    int ret = -EINVAL, idx;

    struct rdma_cm_id *listen_id;

    char ip[40] = "unknown";

    struct addrinfo *res;

    char port_str[16];



    for (idx = 0; idx < RDMA_WRID_MAX; idx++) {

        rdma->wr_data[idx].control_len = 0;

        rdma->wr_data[idx].control_curr = NULL;

    }



    if (rdma->host == NULL) {

        ERROR(errp, "RDMA host is not set!");

        rdma->error_state = -EINVAL;

        return -1;

    }

    /* create CM channel */

    rdma->channel = rdma_create_event_channel();

    if (!rdma->channel) {

        ERROR(errp, "could not create rdma event channel");

        rdma->error_state = -EINVAL;

        return -1;

    }



    /* create CM id */

    ret = rdma_create_id(rdma->channel, &listen_id, NULL, RDMA_PS_TCP);

    if (ret) {

        ERROR(errp, "could not create cm_id!");

        goto err_dest_init_create_listen_id;

    }



    snprintf(port_str, 16, "%d", rdma->port);

    port_str[15] = '\0';



    if (rdma->host && strcmp("", rdma->host)) {

        struct addrinfo *e;



        ret = getaddrinfo(rdma->host, port_str, NULL, &res);

        if (ret < 0) {

            ERROR(errp, "could not getaddrinfo address %s", rdma->host);

            goto err_dest_init_bind_addr;

        }



        for (e = res; e != NULL; e = e->ai_next) {

            inet_ntop(e->ai_family,

                &((struct sockaddr_in *) e->ai_addr)->sin_addr, ip, sizeof ip);

            DPRINTF("Trying %s => %s\n", rdma->host, ip);

            ret = rdma_bind_addr(listen_id, e->ai_addr);

            if (!ret) {

                goto listen;

            }

        }



        ERROR(errp, "Error: could not rdma_bind_addr!");

        goto err_dest_init_bind_addr;

    } else {

        ERROR(errp, "migration host and port not specified!");

        ret = -EINVAL;

        goto err_dest_init_bind_addr;

    }

listen:



    rdma->listen_id = listen_id;

    qemu_rdma_dump_gid("dest_init", listen_id);

    return 0;



err_dest_init_bind_addr:

    rdma_destroy_id(listen_id);

err_dest_init_create_listen_id:

    rdma_destroy_event_channel(rdma->channel);

    rdma->channel = NULL;

    rdma->error_state = ret;

    return ret;



}

void ppc_store_msr_32 (CPUPPCState *env, uint32_t value)

{

    do_store_msr(env,

                 (do_load_msr(env) & ~0xFFFFFFFFULL) | (value & 0xFFFFFFFF));

}

PXA2xxState *pxa270_init(MemoryRegion *address_space,

                         unsigned int sdram_size, const char *revision)

{

    PXA2xxState *s;

    int i;

    DriveInfo *dinfo;

    s = (PXA2xxState *) g_malloc0(sizeof(PXA2xxState));



    if (revision && strncmp(revision, "pxa27", 5)) {

        fprintf(stderr, "Machine requires a PXA27x processor.\n");

        exit(1);

    }

    if (!revision)

        revision = "pxa270";



    s->cpu = cpu_arm_init(revision);

    if (s->cpu == NULL) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }

    s->reset = qemu_allocate_irq(pxa2xx_reset, s, 0);



    /* SDRAM & Internal Memory Storage */

    memory_region_init_ram(&s->sdram, NULL, "pxa270.sdram", sdram_size,

                           &error_abort);

    vmstate_register_ram_global(&s->sdram);

    memory_region_add_subregion(address_space, PXA2XX_SDRAM_BASE, &s->sdram);

    memory_region_init_ram(&s->internal, NULL, "pxa270.internal", 0x40000,

                           &error_abort);

    vmstate_register_ram_global(&s->internal);

    memory_region_add_subregion(address_space, PXA2XX_INTERNAL_BASE,

                                &s->internal);



    s->pic = pxa2xx_pic_init(0x40d00000, s->cpu);



    s->dma = pxa27x_dma_init(0x40000000,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_DMA));



    sysbus_create_varargs("pxa27x-timer", 0x40a00000,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_OST_0 + 0),

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_OST_0 + 1),

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_OST_0 + 2),

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_OST_0 + 3),

                    qdev_get_gpio_in(s->pic, PXA27X_PIC_OST_4_11),

                    NULL);



    s->gpio = pxa2xx_gpio_init(0x40e00000, s->cpu, s->pic, 121);



    dinfo = drive_get(IF_SD, 0, 0);

    if (!dinfo) {

        fprintf(stderr, "qemu: missing SecureDigital device\n");

        exit(1);

    }

    s->mmc = pxa2xx_mmci_init(address_space, 0x41100000,

                    blk_by_legacy_dinfo(dinfo),

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_MMC),

                    qdev_get_gpio_in(s->dma, PXA2XX_RX_RQ_MMCI),

                    qdev_get_gpio_in(s->dma, PXA2XX_TX_RQ_MMCI));



    for (i = 0; pxa270_serial[i].io_base; i++) {

        if (serial_hds[i]) {

            serial_mm_init(address_space, pxa270_serial[i].io_base, 2,

                           qdev_get_gpio_in(s->pic, pxa270_serial[i].irqn),

                           14857000 / 16, serial_hds[i],

                           DEVICE_NATIVE_ENDIAN);

        } else {

            break;

        }

    }

    if (serial_hds[i])

        s->fir = pxa2xx_fir_init(address_space, 0x40800000,

                        qdev_get_gpio_in(s->pic, PXA2XX_PIC_ICP),

                        qdev_get_gpio_in(s->dma, PXA2XX_RX_RQ_ICP),

                        qdev_get_gpio_in(s->dma, PXA2XX_TX_RQ_ICP),

                        serial_hds[i]);



    s->lcd = pxa2xx_lcdc_init(address_space, 0x44000000,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_LCD));



    s->cm_base = 0x41300000;

    s->cm_regs[CCCR >> 2] = 0x02000210;	/* 416.0 MHz */

    s->clkcfg = 0x00000009;		/* Turbo mode active */

    memory_region_init_io(&s->cm_iomem, NULL, &pxa2xx_cm_ops, s, "pxa2xx-cm", 0x1000);

    memory_region_add_subregion(address_space, s->cm_base, &s->cm_iomem);

    vmstate_register(NULL, 0, &vmstate_pxa2xx_cm, s);



    pxa2xx_setup_cp14(s);



    s->mm_base = 0x48000000;

    s->mm_regs[MDMRS >> 2] = 0x00020002;

    s->mm_regs[MDREFR >> 2] = 0x03ca4000;

    s->mm_regs[MECR >> 2] = 0x00000001;	/* Two PC Card sockets */

    memory_region_init_io(&s->mm_iomem, NULL, &pxa2xx_mm_ops, s, "pxa2xx-mm", 0x1000);

    memory_region_add_subregion(address_space, s->mm_base, &s->mm_iomem);

    vmstate_register(NULL, 0, &vmstate_pxa2xx_mm, s);



    s->pm_base = 0x40f00000;

    memory_region_init_io(&s->pm_iomem, NULL, &pxa2xx_pm_ops, s, "pxa2xx-pm", 0x100);

    memory_region_add_subregion(address_space, s->pm_base, &s->pm_iomem);

    vmstate_register(NULL, 0, &vmstate_pxa2xx_pm, s);



    for (i = 0; pxa27x_ssp[i].io_base; i ++);

    s->ssp = (SSIBus **)g_malloc0(sizeof(SSIBus *) * i);

    for (i = 0; pxa27x_ssp[i].io_base; i ++) {

        DeviceState *dev;

        dev = sysbus_create_simple(TYPE_PXA2XX_SSP, pxa27x_ssp[i].io_base,

                        qdev_get_gpio_in(s->pic, pxa27x_ssp[i].irqn));

        s->ssp[i] = (SSIBus *)qdev_get_child_bus(dev, "ssi");

    }



    if (usb_enabled()) {

        sysbus_create_simple("sysbus-ohci", 0x4c000000,

                        qdev_get_gpio_in(s->pic, PXA2XX_PIC_USBH1));

    }



    s->pcmcia[0] = pxa2xx_pcmcia_init(address_space, 0x20000000);

    s->pcmcia[1] = pxa2xx_pcmcia_init(address_space, 0x30000000);



    sysbus_create_simple(TYPE_PXA2XX_RTC, 0x40900000,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_RTCALARM));



    s->i2c[0] = pxa2xx_i2c_init(0x40301600,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_I2C), 0xffff);

    s->i2c[1] = pxa2xx_i2c_init(0x40f00100,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_PWRI2C), 0xff);



    s->i2s = pxa2xx_i2s_init(address_space, 0x40400000,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_I2S),

                    qdev_get_gpio_in(s->dma, PXA2XX_RX_RQ_I2S),

                    qdev_get_gpio_in(s->dma, PXA2XX_TX_RQ_I2S));



    s->kp = pxa27x_keypad_init(address_space, 0x41500000,

                    qdev_get_gpio_in(s->pic, PXA2XX_PIC_KEYPAD));



    /* GPIO1 resets the processor */

    /* The handler can be overridden by board-specific code */

    qdev_connect_gpio_out(s->gpio, 1, s->reset);

    return s;

}

static uint32_t nam_readw (void *opaque, uint32_t addr)

{

    PCIAC97LinkState *d = opaque;

    AC97LinkState *s = &d->ac97;

    uint32_t val = ~0U;

    uint32_t index = addr - s->base[0];

    s->cas = 0;

    val = mixer_load (s, index);

    return val;

}

void virtio_scsi_handle_ctrl_req(VirtIOSCSI *s, VirtIOSCSIReq *req)

{

    VirtIODevice *vdev = (VirtIODevice *)s;

    int type;

    int r = 0;



    if (iov_to_buf(req->elem.out_sg, req->elem.out_num, 0,

                &type, sizeof(type)) < sizeof(type)) {

        virtio_scsi_bad_req();

        return;

    }



    virtio_tswap32s(vdev, &req->req.tmf.type);

    if (req->req.tmf.type == VIRTIO_SCSI_T_TMF) {

        if (virtio_scsi_parse_req(req, sizeof(VirtIOSCSICtrlTMFReq),

                    sizeof(VirtIOSCSICtrlTMFResp)) < 0) {

            virtio_scsi_bad_req();

        } else {

            r = virtio_scsi_do_tmf(s, req);

        }



    } else if (req->req.tmf.type == VIRTIO_SCSI_T_AN_QUERY ||

            req->req.tmf.type == VIRTIO_SCSI_T_AN_SUBSCRIBE) {

        if (virtio_scsi_parse_req(req, sizeof(VirtIOSCSICtrlANReq),

                    sizeof(VirtIOSCSICtrlANResp)) < 0) {

            virtio_scsi_bad_req();

        } else {

            req->resp.an.event_actual = 0;

            req->resp.an.response = VIRTIO_SCSI_S_OK;

        }

    }

    if (r == 0) {

        virtio_scsi_complete_req(req);

    } else {

        assert(r == -EINPROGRESS);

    }

}

static int teletext_close_decoder(AVCodecContext *avctx)

{

    TeletextContext *ctx = avctx->priv_data;



    av_dlog(avctx, "lines_total=%u\n", ctx->lines_processed);

    while (ctx->nb_pages)

        subtitle_rect_free(&ctx->pages[--ctx->nb_pages].sub_rect);

    av_freep(&ctx->pages);



    vbi_dvb_demux_delete(ctx->dx);

    vbi_decoder_delete(ctx->vbi);

    ctx->dx = NULL;

    ctx->vbi = NULL;

    ctx->pts = AV_NOPTS_VALUE;

    return 0;

}

void framebuffer_update_display(

    DisplaySurface *ds,

    MemoryRegionSection *mem_section,

    int cols, /* Width in pixels.  */

    int rows, /* Height in pixels.  */

    int src_width, /* Length of source line, in bytes.  */

    int dest_row_pitch, /* Bytes between adjacent horizontal output pixels.  */

    int dest_col_pitch, /* Bytes between adjacent vertical output pixels.  */

    int invalidate, /* nonzero to redraw the whole image.  */

    drawfn fn,

    void *opaque,

    int *first_row, /* Input and output.  */

    int *last_row /* Output only */)

{

    hwaddr src_len;

    uint8_t *dest;

    uint8_t *src;

    int first, last = 0;

    int dirty;

    int i;

    ram_addr_t addr;

    MemoryRegion *mem;



    i = *first_row;

    *first_row = -1;

    src_len = src_width * rows;



    mem = mem_section->mr;

    if (!mem) {

        return;

    }

    memory_region_sync_dirty_bitmap(mem);



    addr = mem_section->offset_within_region;

    src = memory_region_get_ram_ptr(mem) + addr;



    dest = surface_data(ds);

    if (dest_col_pitch < 0) {

        dest -= dest_col_pitch * (cols - 1);

    }

    if (dest_row_pitch < 0) {

        dest -= dest_row_pitch * (rows - 1);

    }

    first = -1;



    addr += i * src_width;

    src += i * src_width;

    dest += i * dest_row_pitch;



    for (; i < rows; i++) {

        dirty = memory_region_get_dirty(mem, addr, src_width,

                                             DIRTY_MEMORY_VGA);

        if (dirty || invalidate) {

            fn(opaque, dest, src, cols, dest_col_pitch);

            if (first == -1)

                first = i;

            last = i;

        }

        addr += src_width;

        src += src_width;

        dest += dest_row_pitch;

    }

    if (first < 0) {

        return;

    }

    memory_region_reset_dirty(mem, mem_section->offset_within_region, src_len,

                              DIRTY_MEMORY_VGA);

    *first_row = first;

    *last_row = last;

}

m48t59_t *m48t59_init (qemu_irq IRQ, target_phys_addr_t mem_base,

                       uint32_t io_base, uint16_t size,

                       int type)

{

    DeviceState *dev;

    SysBusDevice *s;

    M48t59SysBusState *d;



    dev = qdev_create(NULL, "m48t59");

    qdev_prop_set_uint32(dev, "type", type);

    qdev_prop_set_uint32(dev, "size", size);

    qdev_prop_set_uint32(dev, "io_base", io_base);

    qdev_init(dev);

    s = sysbus_from_qdev(dev);

    sysbus_connect_irq(s, 0, IRQ);

    if (io_base != 0) {

        register_ioport_read(io_base, 0x04, 1, NVRAM_readb, s);

        register_ioport_write(io_base, 0x04, 1, NVRAM_writeb, s);

    }

    if (mem_base != 0) {

        sysbus_mmio_map(s, 0, mem_base);

    }



    d = FROM_SYSBUS(M48t59SysBusState, s);



    return &d->state;

}

