static void main_loop(void)

{

    int r;



#ifdef CONFIG_IOTHREAD

    qemu_system_ready = 1;

    qemu_cond_broadcast(&qemu_system_cond);

#endif



    for (;;) {

        do {

#ifdef CONFIG_PROFILER

            int64_t ti;

#endif

#ifndef CONFIG_IOTHREAD

            tcg_cpu_exec();

#endif

#ifdef CONFIG_PROFILER

            ti = profile_getclock();

#endif

            main_loop_wait(qemu_calculate_timeout());

#ifdef CONFIG_PROFILER

            dev_time += profile_getclock() - ti;

#endif

        } while (vm_can_run());



        if (qemu_debug_requested()) {

            monitor_protocol_event(QEVENT_DEBUG, NULL);

            vm_stop(EXCP_DEBUG);

        }

        if (qemu_shutdown_requested()) {

            monitor_protocol_event(QEVENT_SHUTDOWN, NULL);

            if (no_shutdown) {

                vm_stop(0);

                no_shutdown = 0;

            } else

                break;

        }

        if (qemu_reset_requested()) {

            monitor_protocol_event(QEVENT_RESET, NULL);

            pause_all_vcpus();

            qemu_system_reset();

            resume_all_vcpus();

        }

        if (qemu_powerdown_requested()) {

            monitor_protocol_event(QEVENT_POWERDOWN, NULL);

            qemu_irq_raise(qemu_system_powerdown);

        }

        if ((r = qemu_vmstop_requested())) {

            vm_stop(r);

        }

    }

    pause_all_vcpus();

}

void pc_cmos_init(ram_addr_t ram_size, ram_addr_t above_4g_mem_size,

                  const char *boot_device, MachineState *machine,

                  ISADevice *floppy, BusState *idebus0, BusState *idebus1,

                  ISADevice *s)

{

    int val, nb, i;

    FDriveType fd_type[2] = { FDRIVE_DRV_NONE, FDRIVE_DRV_NONE };

    static pc_cmos_init_late_arg arg;

    PCMachineState *pc_machine = PC_MACHINE(machine);



    /* various important CMOS locations needed by PC/Bochs bios */



    /* memory size */

    /* base memory (first MiB) */

    val = MIN(ram_size / 1024, 640);

    rtc_set_memory(s, 0x15, val);

    rtc_set_memory(s, 0x16, val >> 8);

    /* extended memory (next 64MiB) */

    if (ram_size > 1024 * 1024) {

        val = (ram_size - 1024 * 1024) / 1024;

    } else {

        val = 0;

    }

    if (val > 65535)

        val = 65535;

    rtc_set_memory(s, 0x17, val);

    rtc_set_memory(s, 0x18, val >> 8);

    rtc_set_memory(s, 0x30, val);

    rtc_set_memory(s, 0x31, val >> 8);

    /* memory between 16MiB and 4GiB */

    if (ram_size > 16 * 1024 * 1024) {

        val = (ram_size - 16 * 1024 * 1024) / 65536;

    } else {

        val = 0;

    }

    if (val > 65535)

        val = 65535;

    rtc_set_memory(s, 0x34, val);

    rtc_set_memory(s, 0x35, val >> 8);

    /* memory above 4GiB */

    val = above_4g_mem_size / 65536;

    rtc_set_memory(s, 0x5b, val);

    rtc_set_memory(s, 0x5c, val >> 8);

    rtc_set_memory(s, 0x5d, val >> 16);



    /* set the number of CPU */

    rtc_set_memory(s, 0x5f, smp_cpus - 1);



    object_property_add_link(OBJECT(machine), "rtc_state",

                             TYPE_ISA_DEVICE,

                             (Object **)&pc_machine->rtc,

                             object_property_allow_set_link,

                             OBJ_PROP_LINK_UNREF_ON_RELEASE, &error_abort);

    object_property_set_link(OBJECT(machine), OBJECT(s),

                             "rtc_state", &error_abort);



    if (set_boot_dev(s, boot_device)) {

        exit(1);

    }



    /* floppy type */

    if (floppy) {

        for (i = 0; i < 2; i++) {

            fd_type[i] = isa_fdc_get_drive_type(floppy, i);

        }

    }

    val = (cmos_get_fd_drive_type(fd_type[0]) << 4) |

        cmos_get_fd_drive_type(fd_type[1]);

    rtc_set_memory(s, 0x10, val);



    val = 0;

    nb = 0;

    if (fd_type[0] < FDRIVE_DRV_NONE) {

        nb++;

    }

    if (fd_type[1] < FDRIVE_DRV_NONE) {

        nb++;

    }

    switch (nb) {

    case 0:

        break;

    case 1:

        val |= 0x01; /* 1 drive, ready for boot */

        break;

    case 2:

        val |= 0x41; /* 2 drives, ready for boot */

        break;

    }

    val |= 0x02; /* FPU is there */

    val |= 0x04; /* PS/2 mouse installed */

    rtc_set_memory(s, REG_EQUIPMENT_BYTE, val);



    /* hard drives */

    arg.rtc_state = s;

    arg.idebus[0] = idebus0;

    arg.idebus[1] = idebus1;

    qemu_register_reset(pc_cmos_init_late, &arg);

}

static uint64_t pl011_read(void *opaque, hwaddr offset,

                           unsigned size)

{

    PL011State *s = (PL011State *)opaque;

    uint32_t c;



    if (offset >= 0xfe0 && offset < 0x1000) {

        return s->id[(offset - 0xfe0) >> 2];

    }

    switch (offset >> 2) {

    case 0: /* UARTDR */

        s->flags &= ~PL011_FLAG_RXFF;

        c = s->read_fifo[s->read_pos];

        if (s->read_count > 0) {

            s->read_count--;

            if (++s->read_pos == 16)

                s->read_pos = 0;

        }

        if (s->read_count == 0) {

            s->flags |= PL011_FLAG_RXFE;

        }

        if (s->read_count == s->read_trigger - 1)

            s->int_level &= ~ PL011_INT_RX;

        pl011_update(s);

        if (s->chr) {

            qemu_chr_accept_input(s->chr);

        }

        return c;

    case 1: /* UARTCR */

        return 0;

    case 6: /* UARTFR */

        return s->flags;

    case 8: /* UARTILPR */

        return s->ilpr;

    case 9: /* UARTIBRD */

        return s->ibrd;

    case 10: /* UARTFBRD */

        return s->fbrd;

    case 11: /* UARTLCR_H */

        return s->lcr;

    case 12: /* UARTCR */

        return s->cr;

    case 13: /* UARTIFLS */

        return s->ifl;

    case 14: /* UARTIMSC */

        return s->int_enabled;

    case 15: /* UARTRIS */

        return s->int_level;

    case 16: /* UARTMIS */

        return s->int_level & s->int_enabled;

    case 18: /* UARTDMACR */

        return s->dmacr;

    default:

        qemu_log_mask(LOG_GUEST_ERROR,

                      "pl011_read: Bad offset %x\n", (int)offset);

        return 0;

    }

}

long do_sigreturn(CPUCRISState *env)

{

	struct target_signal_frame *frame;

	abi_ulong frame_addr;

	target_sigset_t target_set;

	sigset_t set;

	int i;



	frame_addr = env->regs[R_SP];

	/* Make sure the guest isn't playing games.  */

	if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 1))

		goto badframe;



	/* Restore blocked signals */

	if (__get_user(target_set.sig[0], &frame->sc.oldmask))

		goto badframe;

	for(i = 1; i < TARGET_NSIG_WORDS; i++) {

		if (__get_user(target_set.sig[i], &frame->extramask[i - 1]))

			goto badframe;

	}

	target_to_host_sigset_internal(&set, &target_set);

        do_sigprocmask(SIG_SETMASK, &set, NULL);



	restore_sigcontext(&frame->sc, env);

	unlock_user_struct(frame, frame_addr, 0);

	return env->regs[10];

  badframe:

	unlock_user_struct(frame, frame_addr, 0);

	force_sig(TARGET_SIGSEGV);

}

void sh4_translate_init(void)

{

    int i;

    static const char * const gregnames[24] = {

        "R0_BANK0", "R1_BANK0", "R2_BANK0", "R3_BANK0",

        "R4_BANK0", "R5_BANK0", "R6_BANK0", "R7_BANK0",

        "R8", "R9", "R10", "R11", "R12", "R13", "R14", "R15",

        "R0_BANK1", "R1_BANK1", "R2_BANK1", "R3_BANK1",

        "R4_BANK1", "R5_BANK1", "R6_BANK1", "R7_BANK1"

    };

    static const char * const fregnames[32] = {

         "FPR0_BANK0",  "FPR1_BANK0",  "FPR2_BANK0",  "FPR3_BANK0",

         "FPR4_BANK0",  "FPR5_BANK0",  "FPR6_BANK0",  "FPR7_BANK0",

         "FPR8_BANK0",  "FPR9_BANK0", "FPR10_BANK0", "FPR11_BANK0",

        "FPR12_BANK0", "FPR13_BANK0", "FPR14_BANK0", "FPR15_BANK0",

         "FPR0_BANK1",  "FPR1_BANK1",  "FPR2_BANK1",  "FPR3_BANK1",

         "FPR4_BANK1",  "FPR5_BANK1",  "FPR6_BANK1",  "FPR7_BANK1",

         "FPR8_BANK1",  "FPR9_BANK1", "FPR10_BANK1", "FPR11_BANK1",

        "FPR12_BANK1", "FPR13_BANK1", "FPR14_BANK1", "FPR15_BANK1",

    };



    for (i = 0; i < 24; i++) {

        cpu_gregs[i] = tcg_global_mem_new_i32(cpu_env,

                                              offsetof(CPUSH4State, gregs[i]),

                                              gregnames[i]);

    }

    memcpy(cpu_gregs + 24, cpu_gregs + 8, 8 * sizeof(TCGv));



    cpu_pc = tcg_global_mem_new_i32(cpu_env,

                                    offsetof(CPUSH4State, pc), "PC");

    cpu_sr = tcg_global_mem_new_i32(cpu_env,

                                    offsetof(CPUSH4State, sr), "SR");

    cpu_sr_m = tcg_global_mem_new_i32(cpu_env,

                                      offsetof(CPUSH4State, sr_m), "SR_M");

    cpu_sr_q = tcg_global_mem_new_i32(cpu_env,

                                      offsetof(CPUSH4State, sr_q), "SR_Q");

    cpu_sr_t = tcg_global_mem_new_i32(cpu_env,

                                      offsetof(CPUSH4State, sr_t), "SR_T");

    cpu_ssr = tcg_global_mem_new_i32(cpu_env,

                                     offsetof(CPUSH4State, ssr), "SSR");

    cpu_spc = tcg_global_mem_new_i32(cpu_env,

                                     offsetof(CPUSH4State, spc), "SPC");

    cpu_gbr = tcg_global_mem_new_i32(cpu_env,

                                     offsetof(CPUSH4State, gbr), "GBR");

    cpu_vbr = tcg_global_mem_new_i32(cpu_env,

                                     offsetof(CPUSH4State, vbr), "VBR");

    cpu_sgr = tcg_global_mem_new_i32(cpu_env,

                                     offsetof(CPUSH4State, sgr), "SGR");

    cpu_dbr = tcg_global_mem_new_i32(cpu_env,

                                     offsetof(CPUSH4State, dbr), "DBR");

    cpu_mach = tcg_global_mem_new_i32(cpu_env,

                                      offsetof(CPUSH4State, mach), "MACH");

    cpu_macl = tcg_global_mem_new_i32(cpu_env,

                                      offsetof(CPUSH4State, macl), "MACL");

    cpu_pr = tcg_global_mem_new_i32(cpu_env,

                                    offsetof(CPUSH4State, pr), "PR");

    cpu_fpscr = tcg_global_mem_new_i32(cpu_env,

                                       offsetof(CPUSH4State, fpscr), "FPSCR");

    cpu_fpul = tcg_global_mem_new_i32(cpu_env,

                                      offsetof(CPUSH4State, fpul), "FPUL");



    cpu_flags = tcg_global_mem_new_i32(cpu_env,

				       offsetof(CPUSH4State, flags), "_flags_");

    cpu_delayed_pc = tcg_global_mem_new_i32(cpu_env,

					    offsetof(CPUSH4State, delayed_pc),

					    "_delayed_pc_");

    cpu_delayed_cond = tcg_global_mem_new_i32(cpu_env,

                                              offsetof(CPUSH4State,

                                                       delayed_cond),

                                              "_delayed_cond_");

    cpu_ldst = tcg_global_mem_new_i32(cpu_env,

				      offsetof(CPUSH4State, ldst), "_ldst_");



    for (i = 0; i < 32; i++)

        cpu_fregs[i] = tcg_global_mem_new_i32(cpu_env,

                                              offsetof(CPUSH4State, fregs[i]),

                                              fregnames[i]);

}

